(window.GIM_TP=window.GIM_TP||{})["Z.Noach.0"]={"from":0,"a":[[[],[],[]],[["אֵלֶּה תּוֹלְדוֹת נֹחַ, רַבִּי חִיָּיא פָּתַח (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. זַכָּאִין אִנּוּן יִשְׂרָאֵל דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְיָדְעֵי אָרְחִין דְּאוֹרַיְיתָא, דִּבְגִינָהּ יִזְכּוּן לְעָלְמָא דְאָתֵי.","תָּא חֲזֵי, כָּל יִשְׂרָאֵל אִית לוֹן חוּלָקָא לְעָלְמָא דְאָתֵי. מַאי טַעְמָא בְּגִין דְּנָטְרִין בְּרִית דְּעָלְמָא אִתְקַיֵּים עֲלֵיהּ. כְּמָא דְאַתְּ אָמֵר, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי. וְעַל דָּא יִשְׂרָאֵל דְּנָטְרֵי בְּרִית וְקַבִּילוּ לֵיהּ אִית לוֹן חוּלָקָא בְּעָלְמָא דְאָתֵי.","וְלֹא עוֹד אֶלָּא בְּגִין כָךְ אִקְרוּן צַדִּיקִים. מִכָּאן אוֹלִיפְנָא כָּל מָאן דְּנָטִיר הַאי בְּרִית דְּעָלְמָא אִתְקְיַּים עֲלֵיהּ. אִקְרֵי צַדִּיק. מְנָא לָן מִיּוֹסֵף. בְּגִין דְּנָטַר לֵיהּ לִבְרִית עָלְמָא, זָכָה דְאִקְרֵי צַדִּיק. וְעַל כָּךְ וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ.","רַבִּי אֶלְעָזָר אָמַר, אֵלֶּה בְּכָל אֲתַר פָּסַל אֶת הָרִאשׁוֹנִים תָּנִינָן וְכוּ'. מַה כְּתִיב לְעֵילָא בְּפָרְשָׁתָא דִבְרֵאשִׁית (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְגו'. הַהוּא נָהָר דְּנָגִיד וְנָפִיק וְעֲיִּיל לְגִנְתָּא וְאַשְׁקֵי לֵיהּ מִשַּׁקְיוּ דִלְעֵילָא וְעָבִיד לֵיהּ נַיְיחָא וְעָבִיד אִיבִּין וְרַבֵּי זָרְעִין. וְהוּא כְּדֵין נַיְיחָא לְכֹלָא. וְדָא נַיְיחָא לֵיהּ לְגִנְתָּא. וְדָא עָבִיד נַיְיחָא בֵּיהּ (נ\"א לגנתא. וגנתא נייחא ביה). כְּמָא דְאַתְּ אָמֵר (בראשית ג) כִּי בוֹ שָׁבַת. וּכְתִיב, (בראשית ב׳:ב׳) וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וְדָא רָזָא דְמִלָּה דָּא עָבִיד תּוֹלְדוֹת וְלָא אָחֳרָא.","תָּא חֲזֵי (כח ב כגוונא דא נח לתתא. קיימא קדישא הוה דוגמא דלעילא. ועל דא אקרי אישהאדמה. ורזא אוליפנא, דהא נח אצטריך לתיבה לאתחברא בה. ולקיימא זרעא דכולא דכתיב לחיות זרע.)","מָאן תֵּיבָה. דָּא (דא) (לג ב) אֲרוֹן הַבְּרִית. וְנֹחַ וְתֵיבָה לְתַתָּא הָכִי הֲווּ כְּדוּגְמָא (דא) דִלְעֵילָא. נֹחַ כְּתִיב בֵּיהּ בְּרִית דִּכְתִיב וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ וְגו'. וְעַד דְּאִתְקְיַּים בֵּיהּ בְּרִית לָא עָיִיל לְתֵיבוּתָא. דִּכְתִיב וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ וּבָאתָ אֶל הַתֵּיבָה. וּכְדֵין הֲוָה תֵּיבָה אֲרוֹן הַבְּרִית.","תֵּיבָה וְנֹחַ כֹּלָּא כְּגַוְונָא דִלְעֵילָא. וּבְגִין דְּהַאי בְּרִית לְעֵילָא הוּא עָבִיד תּוֹלְדוֹת. כְּגַוְונָא דָא נֹחַ (ד\"א לתתא) אִיהוּ עָבִיד תּוֹלְדוֹת. בְּגִינֵי כָּךְ (כמא דאת אמר) אֵלֶּה תּוֹלְדוֹת נֹחַ.","נֹחַ אִישׁ צַדִּיק. הָכִי הוּא וַדַּאי כְּגַוְונָא דִלְעֵילָא. וְעַל דָּא (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם כְּתִיב. וְאַרְעָא עַל דָּא אִתְקָיְימַת. דְּהָא אִיהוּ עַמּוּדָא דְּעָלְמָא קָיְימָא עֲלֵיהּ. וּמָאן אִיהוּ דָּא צַדִּיק. וְנֹחַ אִקְרֵי צַדִּיק לְתַתָּא.","וְרָזָא (נ\"א דא) דְכֹלָא, אֶת הָאֱלהִים הִתְהַלֶּךְ נֹחַ, דַּיְיקָא, דְּלָא אִתְפְּרַשׁ מִנֵּיהּ לְעָלְמִין. וּלְמֶהֱוֵי הוּא בְּאַרְעָא כְּגַוְונָא דִלְעֵילָא אִישׁ צַדִּיק יְסוֹדָא דְעָלְמָא. בְּרִית שָׁלוֹם שְׁלָמָא דְּעָלְמָא. אִישׁ הָאֲדָמָה וַדַּאי. וְעַל דָּא (בראשית ו׳:ח׳) וְנֹחַ מָצָא חֵן בְּעֵינֵי יְיָ.","תָּמִים הָיָה בְּדוֹרוֹתָיו. מַאי בְּדוֹרוֹתָיו, אִלֵין אִנּוּן דְּנָפְקוּ מִנֵּיהּ. הוּא אַשְׁלִים לְכֻלְהוּ. וְהוּא הֲוָה שְׁלִים מִכֻּלְהוּ. תָּמִים הָיָה דְּאִתְיְילִיד מָהוּל דִּכְתִיב הִתְהַלֵּךְ לְפָנַי וְהיֵה תָמִים. בְּדוֹרוֹתָיו וְלא בְּדָרִין דְּעָלְמָא דְּהָא מִנֵּיהּ נָפְקוּ (תולדות בעלמא).","תָּא חֲזֵי, נֹחַ אִתְחַזֵּי מִיּוֹמָא דְּאִתְבְּרִי עָלְמָא לְמֶהֱוֵי בְּתֵיבָה בְּחִבּוּרָא חַד וּלְמֵיעַל בָּהּ, וְעַד לָא אִתְחַבְּרוּ כְּחֲדָא לָא הֲוָה עָלְמָא כְּדְקָא יְאוּת, לְבָתַר מַה כְּתִיב, (בראשית ט׳:י״ט) וּמֵאֵלֶּה נָפְצָה כָּל הָאָרֶץ. מַהוּ נָפְצָה. כְּמָה דְאַתְּ אָמֵר, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד. דְּמִתַּמָּן אִשְׁתְּכַח פִּרוּדָא וְאִתְבַּדָּרוּ תּוֹלְדוֹת לְכָל סִטְרִין","וְכֹלָּא חַד כְּדוּגְמָא חָדָא. בְּגִינֵי כָךְ אֵלֶּה תּוֹלְדוֹת נֹחַ. אֵלֶּה וַדַּאי. דְּהָא יְסוֹדָא דְעָלְמָא אִיהוּ דְּעָבִיד תּוֹלְדוֹת לְקָיְימָא בְּאַרְעָא. אֲתָא רַבִּי אַבָּא וּנְשָׁקֵיהּ. אָמַר אַרְיָא בְּחֵילֵיהּ טִינָרָא נָקִיב וְתָבַר. כָּךְ הוּא וַדַּאי. וְתָּא חֲזֵי, מִשִּׁיעוּרָא דְּתֵיבוּתָא אוּף נָמֵי הָכִי הוּא."],[[0,"אלה תולדות וכו':","רבי חייא פתח סוד ועמך כולם צדיקים וגו'. הוקשה לו כי אחר אלה תולדות נח היה ראוי שיאמר שם חם ויפת, ולא נח איש צדיק, ואמר אשריהם ישראל שעוסקים בתורה ויודעים דרכי התורה שבשבילה יזכו לעולם הבא."],[1,"ת\"ח, כל וכו':","בא וראה, כל ישראל יש להם חלק לעולם הבא, ושואל, מהו הטעם. ואומר, משום שהם שומרים את הברית, שהעולם מתקיים עליו, כמו שאומר הכתוב, אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי. דהיינו ששומרים ברית מילה בקדושה שלא לטמא אותו בשז\"ל, ובעריות. ולפיכך, ישראל ששומרים הברית, כי קבלו אותו עליהם, יש להם חלק לעולם הבא."],[2,"ולא עוד וכו':","ולא עוד אלא שישראל נקראים משום זה צדיקים, מכאן למדנו, שכל מי ששומר הברית שהעולם מתקיים עליו נקרא צדיק. מאין לנו זה מיוסף שבשביל ששמר ברית העולם, דהיינו שלא נכשל באשת אדונו, זכה שנקרא צדיק. וזה שכתוב ועמך כולם צדיקים וגו'. ובזה ביאר לנו רבי חייא את הכתוב, נח איש צדיק, שפירושו, שנח היה שומר הברית, וע\"כ נתקיימו תולדותיו, ולכן אוה\"כ אלה תולדות נח נח איש צדיק, כי תלויים זה בזה."],[3,"ר' אלעזר אמר וכו':","רא\"א, למדנו בכל מקום שכתוב \u0003אל\"ה\u0004, פוסל את הראשונים וכו' מהו כתוב למעלה בפרשת בראשית ונהר יוצא מעדן וגו', שפירושו, שנהר הזה שהוא יסוד, נמשך ויוצא מעדן, שהוא חכמה, ונכנס בהגן שהיא מלכות, ומשקה אותו משקוי של מעלה, ועושה לו נחת רוח, ועושה פירות ומגדל זרעים ואז הוא נחת לכל, שזהו נחת להגן שיש לו פירות, והוא מביא נחת להנהר, להיותו עושה את הפירות. כמ\"ש, כי בו שבת, היינו בהנהר, שהוא יסוד, וכתיב וישבות ביום השביעי היינו בהגן שהיא מלכות. ומפרש וישבות, מלשון מנוחה ונחת. וז\"ס הדבר, זה עושה תולדות היינו היסוד, שה\"ס נהר היוצא מעדן, ולא אחר. כי שום ספירה אחרת אינה עושית פירות."],[4,"ת\"ח כגוונא וכו':","בא וראה, כעין זה. נח למטה, היה ברית קדש כמו היסוד של מעלה, היינו נהר היוצא מעדן הנ\"ל, ולפיכך נקרא \u0003איש האדמה,\u0004 כי אדמה היא מלכות והיסוד הוא אישה של המלכות. ולמדנו סוד, אשר נח היה צריך אל התבה, הרומזת למלכות, כדי להתחבר בה ולקיים זרע כל העולם, כמו שכתוב, לחיות זרע."],[5,"מאן תיבה וכו':","שואל, מהו היא תיבה, ואומר, היא ארון הברית, שהיא המלכות אחר שקבלה היסוד לתוכה, הנקרא ברית. ונח והתבה למטה היו כן כמו יסוד והמלכות של מעלה והראיה, כי בנח כתוב בו ברית, שכתוב והקימותי את בריתי אתך וגו', וכל עוד שלא נתקיים בו הברית, לא בא אל התבה, שהרי כתוב, והקימותי את בריתי אתך ובאת אל התבה. כי אז נעשית התבה ארון הברית, כלומר, אחר שקבלה לתוכה את נח הצדיק, שהיא ברית, הרי נעשית לארון הברית."],[6,"תיבה ונח וכו':","תיבה ונח, הם לגמרי כעין מלכות וברית שלמעלה, ומתוך שהברית הזה של מעלה, הוא עושה תולדות, כמו כן גם נח עושה תולדות. ולפיכך כתוב, \u0003אלה תולדות נח.\u0004 דהיינו ללמדנו, שהוא עושה תולדות של קיימא, כמו הברית של מעלה, שהוא יסוד דאצילות, מטעם שזכה לברית קדש, ויסוד דאצילות הנקרא ברית, שורה עליו."],[7,"נח איש וכו':","נח איש צדיק, ודאי כן הוא כמו יסוד שלמעלה, וע\"כ כתוב וצדיק יסוד עולם, אשר הארץ, שהיא המלכות מתקיים עליו, שהרי הוא העמוד, שהעולם שהיא המלכות, עומד עליו, וע\"כ נקרא יסוד עולם. ומי הוא היסוד הזה, הוא צדיק, ונח הוא צדיק למטה, בנשמות, וע\"כ אומר עליו הכתוב \u0003נח איש צדיק,\u0004 ללמדנו שהעולם מתקיים עליו."],[8,"ורזא דכלא וכו':","והסוד של כל זה הוא, \u0003את האלקים התהלך נח,\u0004 הוא בדיוק ללמדנו שלא נפרש ממנו לעולם, היינו שלא נפרש מהמלכות לעולם. והוא זכה להיות בארץ \u0003איש צדיק,\u0004 כעין שלמעלה, שהוא יסוד העולם, ברית שלום ושלום העולם, והוא ודאי איש האדמה, דהיינו בעלה דאדמה כנ\"ל. ועל כן כתוב ונח מצא חן בעיני ה'."],[9,"תמים היה וכו':","שואל בהכתוב, תמים היה בדורותיו מהו \u0003בדורותיו.\u0004 ואומר, שהם הדורות היוצאים ממנו, שהוא משלימם כולם בצדקתו, וגם הוא עצמו נשלם מכולם. כלומר שב' משמעות הן בהכתוב תמים היה בדורותיו, א) שתמימותו השלימה כל הדורות היוצאים ממנו. ב) שהוא נעשה תמים בזכות כל הדורות היוצאים ממנו. פירוש אחר. \u0003תמים היה,\u0004 פירושו, שנולד מהול, כמו שכתוב התהלך לפני והיה תמים, שהכונה היא שם על המילה. \u0003בדורותיו,\u0004 שמשמע, ולא בדורות העולם, הוא משום שממנו יצאו. כלומר, אע\"פ שכונת הכתוב הוא, שהוא תמים בכל דורות העולם, מ\"מ אומר \u0003בדורותיו,\u0004 כי כל דורות העולם דורותיו הם, כי ממנו יוצאים."],[10,"ת\"ח נח וכו':","בוא וראה, ראוי היה נח מיום שנברא העולם, להיות בחיבור אחד עם התבה ולכנס בה. וכל עוד שלא נתחברו כאחד, לא היה העולם על היכנו כראוי. אחר זה מה כתוב, \u0003ומאלה נפצה הארץ.\u0004 מהו נפצה, הוא כמו שאתה אומר ומשם יפרד, דהיינו בדומה לתבה עלאה שה\"ס הגן, כי משם והלאה נמצא הפירוד, ונפוצו התולדות לכל הרוחות. דהיינו אחר שיצאו ונתקנו בהתבה, יכולים להמצא בעולם הפירוד ולא ימחו כמו דור המבול."],[11,"וכלא חד וכו':","והכל אחד בדמיון אחד. כלומר, שהענפים למטה דומים לשרשיהם שמלמעלה, ומשום זה, אוה\"כ, \u0003אלה תולדות נח,\u0004 אל\"ה ודאי, הם תולדות ופסל את הראשונים, שלא נתקיימו בעולם (כנ\"ל באות ד') כי יסוד העולם, שהוא נח, הוא העושה פירות להתקיים בעולם."],[11,"אתא ר' אבא וכו':","בא רבי אבא ונשקו לרבי אלעזר. אמר האריה בכחו. נקב ושבר את האבן, כלומר שהיה סתום וקשה לו פירוש הכתובים הללו כמו אבן קשה. ורבי אלעזר הסיר הקושיות מהם. כן הוא ודאי, שכל הנאמר בנח ותבה למטה רומז על שרשיהם שלמעלה באצילות, ובוא וראה אף מהשיעור של התבה שגם כן הוא כך. דהיינו שרומז על שיעור בנין המוחין שבהתבה של מעלה, שהיא מלכות, הנבנית על ידי יסוד דז\"א, כי ג' שיעורים נאמרים בה, ארך ורוחב וקומה, שהם חב\"ד. \u0003הארך,\u0004 ה\"ס חכמה, אבל היא נמשך מבינה שנעשית לחכמה, שספירותיה בסוד מאות וע\"כ הג\"ר שמקבלת התבה ה\"ס שלש מאות אמה ארך התבה, דהיינו כח\"ב שכל אחת מאה, \u0003הרחב,\u0004 ה\"ס בינה מבחינת החסדים שבה, והם מאירים בכל ה' ספירותיה כח\"ב תו\"מ, ומתוך שחסדים הם, נבחנת כל ספירה רק לעשרה, וה\"ס חמשים אמה רחבה. \u0003הקומה,\u0004 ה\"ס דעת, שהיא התכללות חכמה וחסדים יחדיו, כדוגמת הקומה המדומית שהיא התכללות וגידול של הארך ורחב יחדיו, ונמשכת אל התבה מן הז\"א שספירותיו בסוד עשיריות, ומאירה בג\"ר שלה כח\"ב, כמו הארך, וע\"כ אומה\"כ, ושלשים אמה קומתה. הרי ששיעורי בנין התבה על ידי נח, הם כשיעורי בנין המלכות על ידי יסוד דז\"א."]],[[0,"","אֵלֶּה תּוֹלְדת נֹחַ. רַבִּי חִיָּיא פָּתַח, (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁעוֹסְקִים בַּתּוֹרָה וְיוֹדְעִים דַּרְכֵי הַתּוֹרָה שֶׁבִּגְלָלָהּ יִזְכּוּ לָעוֹלָם הַבָּא."],[1,"","בֹּא רְאֵה, לְכָל יִשְׂרָאֵל יֵשׁ חֵלֶק לָעוֹלָם הַבָּא, מָה הַטַּעַם? מִשּׁוּם שֶׁשּׁוֹמְרִים הַבְּרִית שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְעַל זֶה, יִשְׂרָאֵל שֶׁשּׁוֹמְרִים הַבְּרִית וְקִבְּלוּ אוֹתָהּ, יֵשׁ לָהֶם חֵלֶק לָעוֹלָם הַבָּא."],[2,"","וְלֹא עוֹד, אֶלָּא מִשּׁוּם כָּךְ נִקְרְאוּ צַדִּיקִים. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁשּׁוֹמֵר הַבְּרִית הַזּוֹ שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, נִקְרָא צַדִּיק. מִנַּיִן לָנוּ? מִיּוֹסֵף. מִשּׁוּם שֶׁשָּׁמַר אֶת בְּרִית הָעוֹלָם זָכָה שֶׁנִּקְרָא צַדִּיק. וְעַל כָּךְ וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ."],[3,"","רַבִּי אֶלְעָזָר אָמַר, אֵלֶּה - בְּכָל מָקוֹם פָּסַל אֶת הָרִאשׁוֹנִים. שָׁנִינוּ וְכוּ'. מַה כָּתוּב לְמַעְלָה בְּפָרָשַׁת בְּרֵאשִׁית? (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְגוֹ'. אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְנִכְנָס לַגָּן וּמַשְׁקֶה אוֹתוֹ מֵהַשְׁקָאָה שֶׁלְּמַעְלָה, וְעוֹשֶׂה לוֹ נַחַת וְעוֹשֶׂה פֵרוֹת וּמְגַדֵּל זְרָעִים, הוּא אָז נוֹחַ לַכֹּל. וְזֶה נוֹחַ לַגָּן. וְזֶה עוֹשֶׂה מְנוּחָה בּוֹ (נ\"א: לגן, והגן נח בו), כְּמוֹ שֶׁנֶּאֱמַר (שם) כִּי בוֹ שָׁבַת, וְכָתוּב וַיִּשְׁבּת בַּיּוֹם הַשְּׁבִיעִי. וְזֶה סוֹד שֶׁדָּבָר זֶה עוֹשֶׂה תוֹלָדוֹת וְלֹא אַחֵר."],[4,"","בֹּא רְאֵה, כְּמוֹ זֶה נֹחַ לְמַטָּה הַבְּרִית הַקָּדוֹשׁ הָיָה דֻגְמָא שֶׁלְּמַעְלָה, וְעַל זֶה נִקְרָא אִישׁ הָאֲדָמָה. וְסוֹד לָמַדְנוּ, שֶׁהֲרֵי נֹחַ הִצְטָרֵךְ לַתֵּבָה לְהִתְחַבֵּר עִמָּהּ וּלְקַיֵּם זֶרַע שֶׁל הַכֹּל, שֶׁכָּתוּב לְחַיּוֹת זֶרַע."],[5,"","מִי זוֹ הַתֵּבָה? (זה) אֲרוֹן הַבְּרִית. וְנֹחַ וְהַתֵּבָה לְמַטָּה כָּךְ הֵם כְּמוֹ דֻגְמָא (זו) שֶׁלְּמַעְלָה. בְּנֹחַ כָּתוּב בְּרִית, שֶׁכָּתוּב וַהֲקִימֹתִי אֶת בְּרִיתִי אִתָּךְ. וְעַד שֶׁהִתְקַיֵּם בּוֹ בְּרִית לֹא נִכְנַס לַתֵּבָה, שֶׁכָּתוּב וַהֲקִימֹתִי אֶת בְּרִיתִי אִתָּךְ וּבָאתָ אֶל הַתֵּבָה. וְאָז הָיְתָה הַתֵּבָה אֲרוֹן הַבְּרִית."],[6,"","(זו) תֵּבָה וְנֹחַ, הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וּבִגְלַל שֶׁהַבְּרִית הַזֹּאת לְמַעְלָה, הוּא עוֹשֶׂה תוֹלָדוֹת. כְּמוֹ זֶה נֹחַ (למטה) הוּא עוֹשֶׂה תוֹלָדוֹת. מִשּׁוּם כָּךְ (כמו שנאמר) אֵלֶּה תּוֹלְדת נֹחַ."],[7,"","נֹחַ אִישׁ צַדִּיק, כָּךְ הוּא בְּוַדַּאי כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה כָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְהָאָרֶץ מִתְקַיֶּמֶת עַל זֶה, שֶׁהֲרֵי הוּא הָעַמּוּד שֶׁהָעוֹלָם עוֹמֵד עָלָיו, וּמִיהוּ? זֶה צַדִּיק, וְנֹחַ נִקְרָא צַדִּיק לְמַטָּה."],[8,"","וְסוֹד (נ\"א: זה) שֶׁל הַכֹּל - אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ. דַּוְקָא. שֶׁלֹּא נִפְרַד מִמֶּנּוּ לְעוֹלָמִים, וְשֶׁיִּהְיֶה הוּא בָּאָרֶץ כְּמוֹ שֶׁלְּמַעְלָה אִישׁ צַדִּיק יְסוֹד הָעוֹלָם. בְּרִית שָׁלוֹם, שָׁלוֹם שֶׁל הָעוֹלָם. אִישׁ הָאֲדָמָה וַדַּאי. וְעַל זֶה (בראשית ו) וְנֹחַ מָצָא חֵן בְּעֵינֵי ה'."],[9,"","תָּמִים הָיָה בְּדרֹתָיו, מַה זֶּה בְּדרֹתָיו? אֵלֶּה אוֹתָם שֶׁיָּצְאוּ מִמֶּנּוּ. הוּא הִשְׁלִים אֶת כֻּלָּם, וְהוּא הָיָה שָׁלֵם מִכֻּלָּם. תָּמִים הָיָה - שֶׁנּוֹלַד מָהוּל, שֶׁכָּתוּב הִתְהַלֵּךְ לְפָנַי וֶהֱיֵה תָמִים. בְּדרֹתָיו - וְלֹא בַּדּוֹרוֹת שֶׁל הָעוֹלָם, שֶׁהֲרֵי מִמֶּנּוּ יָצְאוּ (תולדות בעולם)."],[10,"","בֹּא רְאֵה, נֹחַ רָאוּי הָיָה מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם לִהְיוֹת בַּתֵּבָה בְּחִבּוּר אֶחָד לְהִכָּנֵס בָּהּ, וְעַד שֶׁלֹּא הִתְחַבְּרוּ כְּאֶחָד, לֹא הָיָה הָעוֹלָם כָּרָאוּי. אַחַר כָּךְ מַה כָּתוּב? (שם ט) וּמֵאֵלֶּה נָפְצָה כָל הָאָרֶץ. מַהוּ נָפְצָה? כְּמוֹ שֶׁנֶּאֱמַר (שם ב) וּמִשָּׁם יִפָּרֵד. שֶׁמִּשָּׁם נִמְצָא פֵרוּד וְהִתְפַּזְּרוּ תוֹלָדוֹת לְכָל הַצְּדָדִים"],[11,"","וְהַכֹּל אֶחָד כְּדֻגְמָא אַחַת. מִשּׁוּם כָּךְ אֵלֶּה תּוֹלְדֹת נֹחַ. אֵלֶּה וַדַּאי. שֶׁהֲרֵי יְסוֹד הָעוֹלָם הוּא שֶׁעוֹשֶׂה תוֹלָדוֹת לְקַיֵּם בָּאָרֶץ. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, אַרְיֵה בְּכֹחוֹ נוֹקֵב סֶלַע וְשׁוֹבֵר. כָּךְ זֶה בְּוַדַּאי. וּבֹא וּרְאֵה, מִשִּׁעוּר הַתֵּבָה גַּם כָּךְ זֶה."]]],[["\u0003תּוֹסֶפְתָּא\u0004 לָמָּה נֹחַ נֹחַ תְּרֵי זִמְנִי. אֶלָּא כָּל צַּדִּיק וצַּדִּיק דִּי בְּעָלְמָא אִיתּ לֵיהּ תְּרֵין רוּחִין. רוּחָא חַד בְּעָלְמָא דֵין ורוּחָא חַד בְּעָלְמָא דְאָתֵּי. והָכִי תִּשְׁכַּח בְּכֻלְהוּ צַּדִּיקֵי משֶׁה משֶׁה, יַעֲקֹב יַעֲקֹב, אַבְרָהָם אַבְרָהָם, שְׁמוּאֵל שְׁמוּאֵל, שֵׁם שֵׁם. בַּר מִיִּצְּחָק דְּלָא כְּתִּיב בֵּיהּ כְּמָה דִכְתִּיב בְּהוּ. בְּגִין דְּיִצְּחָק בְּשַׁעֲתָּא דְּאִתְּקְרָב עַל גַּבֵּי מַדְבְּחָא נָפְּקַתּ נִשְׁמָתֵּיהּ דְּהֲוַתּ בֵּיהּ בְּהַאי עָלְמָא. וכֵיוָן דְּאִתְּמָר בֵּיהּ בְּאַבְרָהָם, בָּרוּךָ מְחַיֵּה הַמֵּתִּים תָּבַתּ בֵּיהּ נִשְׁמָתֵּיהּ דְּעָלְמָא דְּאָתֵּי. בְּגִין דָּא תִּשְׁכַּח דְּלָא יִחֵד קוּדְשָׁא בְּרִיךָ הוּא שְׁמֵיהּ אֶלָּא עַל יִצְּחָק בְּגִין דְּאִתְּחַשַׁב כְּמֵתּ וְעַל דָּא רָמַז קְרָא ואָמַר (איוב ז) הֵן בִּקְדוֹשָׁיו לֹא יַאֲמִין וגו'.","דָּבָר אַחֵר אֵלֶּה תּוֹלְדוֹתּ בְּגִין דְּהֲוָה צַּדִּיק שַׁבַּח לֵיהּ תְּרֵי זִמְנִי. תָּמִים הָיָה בְּדוֹרוֹתָּיו, אֲבָל בְּדָרִין אַחֲרָנִין אֵינוֹ נְחְשַׁב לִכְלוּם, כְּמוֹ דָרָא דְאַבְרָהָם ודָרָא דְמשֶׁה ודָרָא דְּדָוִד. דָּבָר אַחֵר חָמֵי מַאי עָבַד בְּדָרָא דְּכֻלְהוּ חַיָּיבִים, קַל וָחוֹמֶר אִלּוּ הָיָה בְּדָרָא דְּכֻלְהוּ צַּדִּיקִים: (עד כאן תוספתא)","רַבִּי אֶלְעָזָר פָּתַח (תהילים מ״ו:ט׳) לְכוּ חֲזוּ מִפְעֲלוֹת (בדפוס קרימונא אלקים, ועי' מ\"ש לעיל נח ב) יְיָ אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. הַאי קְרָא הָא אִתְּמָר וְאוּקְמוּהָ. אֲבָל לְכוּ חֲזוּ, מַאי חֲזוּ. כְּמָא דְאַתְּ אָמֵר, (ישעיהו כ״א:ב׳) חָזוּת קָשֶׁה הוּגַד לִי. בְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד, אִתְגְּלִי נְבוּאָה עִלָּאָה לִבְנִי נָשָׁא. אֲשֶׁר שָׂם שַׁמּוֹת, שֵׁמוֹת וַדַּאי, דְּהָא שְׁמָא גָּרִים לְכֹלָּא.","כְּתִיב וַיִּקְרָא אֶת שְׁמוֹ נֹחַ לֵאמֹר זֶה וְגו' אַמַּאי הָכָא לֵאמֹר. וְאַמַּאי זֶה. אֶלָּא (הובא לעיל דף נח א' לשון זה) לֵאמֹר דָּא אִתְּתָא. זֶה דָּא צַדִּיק. (רמז כמו דקודשא בריך הוא קרא ליה נח נייחא דארעא. לאמר, מאי לאמר. אלא אתר דא קרי ליה נח. ומאן איהו ארעא קדישא. לאמר זה ינחמנו ממעשנו וגו'. עבד ליה קודשא בריך הוא לתתא כגוונא עלאה) (נ\"א זה דא צדיק וכן נח (לאמר, נח) דא צדיק. לאמר דא נוקבא. בגין דלא מתפרשן דא מן דא. אמר רבי יצחק לאמר דא ארעא קדישא) (וזה אמת) (כצ\"ל באמת בהגהת ד\"א. הרש\"ב) כְּתִיב הָכָא זֶה יְנַחֲמֵנוּ, וּכְתִיב הָתָם (ישעיהו כ״ה:ט׳) זֶה יְיָ קִוִּינוּ לוֹ. זַכָּאִין אִנּוּן צַדִּיקַיָא דִרְשִׁימִין בִּרְשִׁימוּ דְגוּשְׁפַּנְקָא דְמַלְכָּא לְמֶהוֵי בִּשְׁמֵיהּ רְשִׁימִין וְאִיהוּ שָׁוֵי שְׁמָהָן בְּאַרְעָא כְּדְקָא יְאוּת.","כְּתִיב וַיִּקְרָא אֶת שְׁמוֹ נֹחַ. וּכְתִיב, (וישב קפו ב) וַיִּקְרָא שְׁמוֹ יַעֲקֹב. אַמַּאי לָא כְּתִיב אֶת. אֶלָּא הָתָם דַּרְגָּא אַחֲרָא (ד\"א חדא) וְהָכָא דַּרְגָּא אוֹחֲרָא. (נ\"א את, כמה דאת אמר ואראה את יי) כְּדִכְתִיב, (ישעיה ו) וָאֶרְאֶה אֶת יְיָ. וָאֶרְאֶה יְיָ לָא כְּתִיב אֶלָּא אֶת יְיָ. אוּף הָכָא בְּנֹחַ וַיִּקְרָא אֶת שְׁמוֹ נֹחַ. וַיִּקְרָא שְׁמוֹ יַעֲקֹב דַּרְגָּא דִּילֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא מַמָּשׁ קָרָא לֵיהּ יַעֲקֹב. אֲבָל הָכָא אֶת לְאִתְכְּלָלָא שְׁכִינְתָּא. (נ\"א דהיא דרגא אחרא לתתא):","אֵלֶּה תּוֹלְדוֹת נֹחַ וְגו'. רַבִּי יְהוּדָה פָּתַח (תהילים קי״ב:ה׳) טוֹב אִישׁ חוֹנֵן וּמַלְוֶה יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט. טוֹב אִישׁ, דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִקְרֵי טוֹב. כְּמָה דִּכְתִיב, (תהילים קמ״ה:ט׳) טוֹב ה' לַכֹּל. וּכְתִיב, (שמות ט״ו:ג׳) ה' אִישׁ מִלְחָמָה. לְהַאי כֹּל חוֹנֵן וּמַלְוֶה. לְאֲתַר דְּלֵית לֵיהּ מִדִּילֵיהּ. וְהַהוּא אֲתַר מִנֵּיהּ אִתְּזָן יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט, דְּהָא הַהוּא דָּבָר לָא אִתְּזָן אֶלָּא בְּמִשְׁפָּט כְּמָה דְּאַתְּ אָמֵר (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ.","דָּבָר אַחֵר טוֹב אִישׁ, דָּא צַדִּיק דִּכְתִיב, (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְּרִי מַעַלְלֵיהֶם יֹאכֵלוּ. רַבִּי יוֹסֵי אָמַר דָּא נֹחַ דִּכְתִיב נֹחַ אִישׁ צַדִּיק. רַבִּי יִצְחָק אָמַר דָּא שְׁבָחָא דְּשַׁבָּת, דְּבֵיהּ פָּתַח טוֹב, דִּכְתִיב, (תהילים צ״ב:ב׳) טוֹב לְהוֹדוֹת לַה'.","רַבִּי חִיָּיא אָמַר כֹּלָּא חַד וְכֻלְהוּ מִלָּה חָדָא אָמְרוּ. וְדָא עָבִיד תּוֹלְדוֹת בְּעָלְמָא. תּוֹלְדוֹת דְּעָלְמָא מָאן אִנּוּן. אִלֵּין נִשְׁמַתְהוֹן דְּצַדִּיקַיָא דְּאִנּוּן אִיבָּא דְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא.","רַבִּי שִׁמְעוֹן אָמַר בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא מִתְעַטֵּר בְּעִטְרוֹי, מִתְעַטֵּר מֵעֵילָא וּמִתַּתָּא. מֵעֵילָא מֵאֲתַר דְּעֲמִיקָא דְכֹלָּא. מִתְעַטֵּר מִתַּתָּא בַּמֶּה. בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָא. כְּדֵין אִתּוֹסַף חַיִּים מֵעֵילָא וּמִתַּתָּא. וְאִתְכְּלִיל אֲתַר מַקְדְּשָׁא מִכָּל סִטְרִין וּבֵירָא אִתְמַלְיָיא וְיַמָּא אִשְׁתְּלִים, וּכְדֵין יָהַב לְכֹלָּא.","כְּתִיב, (משלי ה׳:ט״ו) שְׁתֵה מַיִם מִבּוֹרְךָ וְנוֹזְלִים מִתּוֹךְ בְּאֵרְךָ. אַמַּאי (הכא) בּוֹרְךָ בְּקַדְמִיתָא וּלְבָתַר בְּאֵרְךָ. דְּהָא בּוֹר לָא אִקְרֵי אֶלָּא רֵיקַנְיָא דְּלָא נְבִיעַ. בְּאֵר מַיִין דְּנָבְעִין. אֶלָּא כֹּלָא אֲתַר חַד הוּא. אֶלָּא אֲתַר דְּמִסְכְּנֵי (נ\"א דמסכנותא) אֲחִידָן בֵּיהּ אִקְרֵי בּוֹר. דְּלֵית לֵיהּ מִדִּילֵיהּ אֶלָּא מַה דְּיַהֲבִין בְּגַוֵּיהּ. וּמַאן אִיהוּ דלי\"ת.","לְבָתַר אִתְעֲבִיד בְּאֵר דְּאִיהוּ נְבִיעַ וּמַלְיָא (ד\"א דמליא) מִכָּל סִטְרִין. וּמָאן אִיהוּ ה\"א. אִתְמַלְיָיא מֵעֵילָא וּנְבִיעַ מִתַּתָּא. אִתְמַלְיָיא מֵעֵילָא כְּמָה דְאֲמָרָן. וּנְבִיעַ מִתַּתָּא מִנִּשְׁמַתְהוֹן דְּצַדִּיקַיָא."],[[0,"למה נח תרי וכו':","שואל למה כתוב ב' פעמים נח. ואומר אלא כל צדיק וצדיק שבעולם יש לו ב' רוחות, אחד הוא בעוה\"ז, ואחד בעוה\"ב. וכן תמצא בכל הצדיקים שקראם הקב\"ה, משה משה, יעקב יעקכ, אברהם אברהם, שמואל שמואל, דהיינו שם שם ב\"פ חוץ מיצחק, שלא כתוב בו ב\"פ יצחק כמו שכתוב בהם, והוא משום, שבשעה שנקרב יצחק על המזבח יצאה נשמתו שהיתה בו בעוה\"ז, וכיון שנאמר לו לאברהם ברוך מחיה המתים, דהיינו שנאמר לו, אל תשלח ידך אל הנער, אחר שכבר שלח ידו לשחטו, חזרה אליו רק נשמתו שבעולם הבא. וע\"כ לא נקרא יצחק יצחק. ומשום זה תמצא. שלא יחד הקב\"ה את שמו, על צדיק בחייו, אלא על יצחק, משום שנחשב כמת. כי לא היה לו נשמה מעוה\"ז אלא מעוה\"ב, כמו שיש לנפטרים מעוה\"ז, וע\"כ רמז הכתוב ואמר, הן בקדושיו לא יאמין וגומר. כי אינו מיחד שמו על הצדיק בחייו."],[1,"ד\"א אלה תולדות וכו':","פירוש אחר על מה שכתוב נח נח. שמשום שהיה צדיק שבח אותו ב' פעמים, שקראו נח נח. \u0003תמים היה בדורותיו,\u0004 אבל אם היה בדורות אחרים, כמו דור של אברהם ודור של משה ודור של דוד לא היה נחשב לכלום. פירוש אחר, ראה מה שעשה בדור שכולם רשעים, מכל שכן אם היה בדור שכולם צדיקים, מה היה עושה."],[2,"ר\"א פתח וכו':","ר\"א פתח הבנת הכ' אלה תולדות נח עם הכתוב. לכו חזו מפעלות ה' וגו' ושואל \u0003לכו חזו,\u0004 מהו חזו, ואומר, שהוא כמש\"ה חזות קשה הוגד לי, כי על ידי המעשים שהקב\"ה עושה מתגלה הנבואה לבני אדם, וכשהנבואה נגלית ע\"י הקדם של מעשים קשים היא נקראת חזות קשה או חזיון. \u0003אשר שם שמות,\u0004 שמות ודאי כי השם הוא הגורם לכל. כלומר ע\"כ ודאי הוא שיש לבדוק בהשם של הדבר, כי הקב\"ה משים בפי בני אדם לקרא שמות בארץ, ושיעור הכתוב הוא לכו והסתכלו במפעלות ה' באמצעות השמות שניתנו להפעולת בהארץ, ע\"י בני אדם, כי הקב\"ה שם בפיהם השמות בנבואה, ע\"י הקדם של מעשים."],[3,"כתיב ויקרא וכו':","שואל, למה כתוב כאן, \u0003לאמר\u0004 ולמה כתוב, \u0003זה,\u0004 ואומר, אלא \u0003לאמר\u0004 הנוקבא, דהיינו מלכות, \u0003זה\u0004 הוא צדיק, דהיינו נח שהוא צדיק, והראיה, כי כאן כתוב \u0003זה,\u0004 ושם כתוב זה ה' קוינו לו, ויליף גזרה שוה, מה \u0003זה\u0004 הנאמר שם הוא ה' הנק' צדיק, אף \u0003זה\u0004 שבכאן הוא צדיק, ורומז לנח, שנקרא צדיק כמו ה'. ושיעור הכתוב הוא, ויקרא את שמו נח, היינו הנוקבא העליונה, שהיא מלכות, קראה אותו נח, \u0003לאמר,\u0004 שהנוקבא אמרה, \u0003זה\u0004 דהיינו נח, ינחמנו וגו',"],[3,"זכאין אינון וכו':","אשריהם הצדיקים הנחתמים ברשימות טבעת המלך, דהיינו הקב\"ה, להיות רשומים בשמו, והוא שם שמות בארץ, דהיינו בפי בני אדם, שיקראו כל דבר בשמו כראוי."],[4,"כתיב ויקרא וכו':","כתוב ויקרא את שמו נח, וכתוב ויקרא שמו יעקב, למה לא כתוב \u0003את\u0004 ביעקב כמו בנח. אלא שם מדרגה אחרת וכאן מדרגה אחרת, כמ\"ש ואראה את ה', ואראה ה' לא כתוב אלא את ה', הרי שהמלה \u0003א\"ת\u0004 הוא בדיוק, אף כאן בנח כתוב ויקרא \u0003את\u0004 שמו נח, כי ויקרא שמו יעקב, המדרגה שלו הוא הקב\"ה ממש, וע\"כ לא כתוב שם \u0003את\u0004 אבל כאן בנח שכתוב את, את, הוא לכלול עמו השכינה. כלומר, השכינה. שהיא הנוקבא, היא נקראת \u0003את,\u0004 וע\"כ יעקב שמדרגתו הוא מרכבה להקב\"ה בלבדו לא כתוב בו את. אבל בנח, שה\"ס צדיק המחובר תמיד עם השכינה כנ\"ל, ע\"ב כתוב בו \u0003את,\u0004 שהיא השכינה הכלולה עם נח."],[5,"אלה תולדות וכו':","ר\"י פתח טוב איש חונן ומלוה יכלכל דבריו במשפט. \u0003טוב איש.\u0004 זה הקב\"ה הנקרא טוב, כמ\"ש \u0003טוב\u0004 ה' לכל, וכתיב ה' \u0003איש\u0004 מלחמה, והוא חונן ומלוה אל \u0003כל\u0004 הזה, שהוא יסוד, כי הויה שהוא ז\"א משפיע ומלוה שפע המוחין להיסוד, בשביל המקום, שאין לו משלו, שהיא הנוקבא, כי מקום זה, שהיא הנוקבא, ניזון ממנו, מן היסוד, \u0003יכלכל דבריו במשפט,\u0004 כי דבר ההוא, שהיא הנוקבא, אינו ניזון אלא במשפט, שהם המוחין דהארת החכמה, (כנ\"ל בראשית א' דף רע\"ו אות ש\"מ ד\"ה ועוד) כמו שאתה אומר, צדק ומשפט מכון כסאך. הרי שהצדק שהיא הנוקבא ניזונת מהמשפט. וסוד ההלואה שאומר, ה\"ס אמא אוזיפת לברתא מאנהא, (כנ\"ל בהקדמת הזהר דף כו' אות י\"ז ד\"ה וזה אמרו) כי הנוקבא אין לה כלום מבחינת עצמה לקבל המוחין, אלא ששואלת אותם מאמא עש\"ה. והיא מקבלתם ע\"י ז\"א, כנודע. ושיעור הכתוב, טוב איש, היינו הקב\"ה, חונן ומלוה השפע להיסוד בשביל הנוקבא, שבזה יכלכל דבריו, שהיא הנוקבא, במשפט, היינו במוחין הגדולים הנקראים משפט."],[6,"ד\"א טוב וכו':","פירוש אחר, \u0003טוב איש,\u0004 זה צדיק שכתוב אמרו צדיק כי טוב כי פרי מעלליהם יאכלו. הרי שהצדיק נקרא טוב. רבי יוסי אומר טוב איש זה נח, שכתוב נח איש צדיק. ושיעור הכתוב טוב איש היינו היסוד דז\"א שנקרא צדיק או נח הצדיק, חונן ומלוה שפע המוחין להנוקבא, שבזה יכלכל דבריו שהיא הנוקבא, במשפט, במוחין דגדלות."],[6,"רבי יצחק אומר","וכו' רי\"א טוב איש נאמר, בשבח השבת דהיינו במוחין דיום השבת שבו פתח הכ' עם המלה טוב, שכתוב טוב להודות לה'. פירוש כי אור השבת ה\"ס אור תכלית שמים וארץ המאיר בגמר התקון, כמ\"ש בנוסח התפלה אתה קדשת וגו'. ולפיכך מטרם גמר התקון הוא מאיר רק בדרך הלואה, (כמ\"ש בת\"ז תקון י\"ט ל\"ח ע\"א) לוו עלי ואני פורע, ע\"ש. וע\"כ אומר ר\"י, טוב איש חונן ומלוה נאמר באורות השבת, הניתנים בהלואה."],[7,"ר' חייא וכו':","ר\"ח אמר, הכל אחד, וכולם דבר אחד אמרו, שזה עושה תולדות בעולם, דהיינו הצדיק. ושואל, מי הם תולדות העולם. ואומר, הם נשמות הצדיקים, שהם פרי מעשיו של הקב\"ה."],[8,"ר\"ש אמר וכו':","רש\"א בשעה שהקב\"ה מתעטר בעטרות שלו, הוא מתעטר מלמעלה ומלמטה, מלמעלה הוא מהמקום העמוק מכל. שהוא או\"א, ומתעטר מלמטה, במה, היינו מנשמות הצדיקים. אז נוסף חיים מלמעלה ומלמטה, ונכלל מקום המקדש מכל הצדדים. והבור נתמלא, והים נשלם, ואז נותן חיים לכל."],[8,"","פירוש כי המוחין דנשמות הצדיקים יוצאין בסוד תלת נקודין חולם שורק חירק, כמו המוחין של ז\"א, ונתבאר בהמוחין דז\"א, שבישסו\"ת יוצאים תחלה ב' נקודות חולם ושורק, בסוד מ\"י אל\"ה, שהם ב' קוין ימין ושמאל, והם במחלוקת ואינם יכולים להאיר עד שנעשה זווג על מסך דז\"א שעלה שם בסוד מ\"ן, ויוצאת עליו קומת חסדים, שה\"ס נקודת החירק וקו אמצעי ואז מכריע בין הקוין שה\"ס \u0003מ\"י אל\"ה,\u0004 ומתחברים בסוד השם \u0003אלהים\u0004 והוא כמ\"ש בזהר אמור אות קצ\"ז בסולם \u0003ויעקב אתער,\u0004 שה\"ס קו אמצעי שיצא על מסך דחירק, \u0003וחמו לאברהם\u0004 שהוא נקודת חחולם וקו ימין, \u0003מתתקן בגיסא אחרא, כדין אחידן ביה תרוייהו ביצחק,\u0004 שהוא נקודת השורק וקו שמאל, \u0003דא מהאי סטרא ודא מהאי סטרא ולא יכלין תוקפוי לנפקא לבר,\u0004 אלא שהוא מתלבש ונכלל בימין. עש\"ה. וכיון שז\"א גרם השלמת המוחין בישסו\"ת זכה גם בעצמו באלו המוחין, (כנ\"ל בראשית א' דף רפ\"ז אות שס\"ג ד\"ה תלת) כיון דתלת נפקי מחד, חד בתלת קיימא ע\"ש."],[8,"","ועד\"ז ממש יוצאים המוחין בסוד נשמת הצריקים. כתחלה י יוצאים בזו\"ן ב' הנקודות חולם ושורק, שה\"ס ב' קוין ימין ושמאל, אשר ז\"א נתתקן בנקודת החולם וקו ימין, והנוקבא נתתקנת בנקודת השורק וקו שמאל, ואז הם במחלוקת ושניהם אינם מאירים בשלמות, עד שנשמות הצדיקים עולים אליהם למ\"ן, ויוצאת שם קומת חסדים על המסך שבנשמות הצדיקים, שה\"ס נקודת החירק וקו האמצעי, ואז מתרבים החסדים ע\"י קו האמצעי וע\"י קו ימין, ומתבטלים הדינין שבנוקבא ומתחברת עם ז\"א, ואותו שיעור השלמות שנשמות הצדיקים גרמו בזו\"ן, זכו בו גם הם."],[8,"","וזה אמרו \u0003בשעתא דקב\"ה מתעטר בעטרוי\u0004 בשעה שז\"א מתתקן בעטרותיו, דהיינו במוחין, \u0003מתעטר מעילא ומתתא,\u0004 היא מתתקן מלמעלה ומלמטה, דהיינו במוהין דנקודת החולם מסוד קו הימין המקובל לו מלמעלה מאו\"א, ובמוחין דנקודת החירק שה\"ס קו האמצעי המקובל לו מלמטה, מנשמות הצדיקים כנ\"ל. וז\"ש \u0003מעילא, מאתר דעמיקא דכלא\u0004 מלמעלה, הוא מקבל ממקום העמוק מכל דהיינו מאו\"א, שמהם המוחין דנקודת החולם, וקו ימין. \u0003מתעטר מתתא, במה, מנשמתהון דצדיקיא,\u0004 ובמה מתתקן מלמטה, הוא בנשמות הצדיקים דהיינו במוחין דנקודת החירק היוצאים על מסך שלהם כנ\"ל. וז\"ש \u0003כדין אתוסף חיים מעילא ותתא, ואתכלל אתר מקדשא מכל סטרין\u0004 ואז מתרבים החיים מכח החסדים שמלמעלה מנקודת החולם, ושמלמטה מנקודת החירק, ונכלל מקום המקדש, שהיא הנוקבא, מכל הצדדים, כי הנוקבא דז\"א, שהיא בחינת מוחין דנקודת השורק וקו שמאל כנ\"ל, שהיתה במחלוקת עם ז\"א שה\"ס קו ימין, נתפייסה עתה מכח שמוקפת מחסדים מב' הצדדים, מבחינת קו ימין ומבחינת קו אמצעי, כמ\"ש בזהר אמור הנ\"ל, \u0003דא מהאי סטרא ודא מהאי סטרא ולא יכלין תוקפוי לנפקא לבר,\u0004 ע\"ש. ואז \u0003ובירא אתמליא וימא אשתלים,\u0004 מבחינת החסדים שלה מכנה אותה בור. ומבחינת החכמה מכנה אותה ים. וע\"כ אחר שהבור מתמלא בחסדים מתלבש החכמה שלה בחסדים והים נשלם. \u0003וכדין יהיב חיין לכלא\u0004 ואז נותן חיים לכל, דהיינו שנותן מוחין לנשמות הצדיקים. כי אותו השיעור שנשמות הצדיקים גרמו להשתלם בז\"א ונוקביה זוכים בו גם הם כנ\"ל."],[9,"כתיב שתה וכו':","כתוב שתה מים מבורך ונוזלים מתוך בארך. ושואל למה כתוב תחלה בורך ואח\"כ בארך. שהרי לא נקרא בור אלא מקום ריקן שאינו נובע מים, ובאר הוא מים הנובעים, ואינם דומים זה לזה. ומשיב אלא הכל מקום אחד הוא, ששניהם רומזים על הנוקבא, אלא המקום שעניים נאחזים בו, כלומר כשאינה מחוברת עם ז\"א בעלה והיא עניה, נקראת בור שאין לו משלו אלא מה שמכניסים בו, ומי הוא, הוא אות \u0003ד'.\u0004 דהיינו הנוקבא בפרודא מז\"א שנקראת אז \u0003ד'.\u0004"],[10,"לבתר וכו':","לאחר כך, דהיינו כשמזוווגת עם ז\"א, היא נעשית באר שהוא נובע ומתמלא מכל הצדדים, דהיינו שמתמלא מקו ימין מז\"א ומקו אמצעי מנשמות הצדיקים, (כנ\"ל בדבור הסמוך). ומי הוא, הוא \u0003ה',\u0004 דהיינו כשהוא בזווג עם ז\"א שנקראת אז ה'. שנתמלא מלמעלה ונובע מלמטה, מתמלאת מלמעלה כמו שאמרנו, (לעיל בדבור הסמוך) דהיינו מז\"א מסוד נקודת החולם, והיא נובעת מלמטה, היינו מנשמת הצדיקים, מסוד נקודת השורק. כנ\"ל."]],[[0,"","לָמָּה נֹחַ נֹחַ פַּעֲמַיִם? אֶלָּא כָּל צַדִּיק וְצַדִּיק שֶׁבָּעוֹלָם יֵשׁ לוֹ שְׁתֵּי רוּחוֹת - רוּחַ אַחַת בָּעוֹלָם הַזֶּה, וְרוּחַ אַחַת בָּעוֹלָם הַבָּא. וְכָךְ תִּמְצָא בְּכָל הַצַּדִּיקִים: מֹשֶׁה מֹשֶׁה, יַעֲקֹב יַעֲקֹב, אַבְרָהָם אַבְרָהָם, שְׁמוּאֵל שְׁמוּאֵל, שֵׁם שֵׁם. פְּרָט לְיִצְחָק שֶׁלֹּא כָתוּב בּוֹ כְּמוֹ שֶׁכָּתוּב בָּהֶם, מִשּׁוּם שֶׁיִּצְחָק, בְּשָׁעָה שֶׁנִּקְרַב עַל גַּבֵּי הַמִּזְבֵּחַ, יָצְאָה נִשְׁמָתוֹ שֶׁהָיְתָה בּוֹ בָּעוֹלָם הַזֶּה. וְכֵיוָן שֶׁנֶּאֱמַר בְּאַבְרָהָם בָּרוּךְ מְחַיֵּה הַמֵּתִים, שָׁבָה אֵלָיו נִשְׁמָתוֹ שֶׁל הָעוֹלָם הַבָּא. מִשּׁוּם זֶה תִּמְצָא שֶׁלֹּא יִחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שְׁמוֹ אֶלָּא עַל יִצְחָק, מִשּׁוּם שֶׁנֶּחְשַׁב כְּמֵת. וְעַל זֶה רָמַז הַכָּתוּב וְאָמַר (איוב טו) הֵן בִּקְדשָׁו לֹא יַאֲמִין וְגוֹ'."],[1,"","דָּבָר אַחֵר אֵלֶּה תּוֹלְדת, מִשּׁוּם שֶׁהָיָה צַדִּיק שִׁבַּח אוֹתוֹ פַּעֲמַיִם. תָּמִים הָיָה בְּדרֹתָיו, אֲבָל בְּדוֹרוֹת אֲחֵרִים אֵינוֹ נֶחְשָׁב לִכְלוּם, כְּמוֹ דּוֹרוֹ שֶׁל אַבְרָהָם וְדוֹר מֹשֶׁה וְדוֹר דָּוִד. דָּבָר אַחֵר, רְאֵה מֶה עָשָׂה בְּדוֹר שֶׁכֻּלָּם רְשָׁעִים, קַל וָחֹמֶר אִלּוּ הָיָה בְּדוֹר שֶׁכֻּלָּם צַדִּיקִים. ע\"כ התוספתא"],[2,"","רַבִּי אֶלְעָזָר פָּתַח, (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת ה' אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. הַפָּסוּק הַזֶּה הֲרֵי נִתְבָּאֵר, וּבֵאֲרוּהוּ. אֲבָל לְכוּ חֲזוּ, מַה זֶּה חֲזוּ? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כא) חָזוּת קָשָׁה הֻגַּד לִי. בְּמַעֲשָׂיו שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מִתְגַּלָּה נְבוּאָה עֶלְיוֹנָה לִבְנֵי אָדָם. אֲשֶׁר שָׂם שַׁמּוֹת - שֵׁמוֹת וַדַּאי, שֶׁהֲרֵי הַשֵּׁם גּוֹרֵם לַכֹּל."],[3,"","כָּתוּב וַיִּקְרָא אֶת שְׁמוֹ נֹחַ לֵאמֹר זֶה וְגוֹ', לָמָּה כָּאן לֵאמֹר? וְלָמָּה זֶה? אֶלָּא לֵאמֹר זוֹ הָאִשָּׁה. זֶה זֶה צַדִּיק. (רמז כמו שהקדוש ברוך הוא קרא לו נח, מנוחת הארץ, לאמר, מה זה לאמר? אלא מקום זה קרא לו נח, ומי הוא? ארץ הקדושה, לאמר זה ינחמנו ממעשנו וגו', עשה אותו הקדוש ברוך הוא למטה כדגמא עליונה). (נ\"א: זה זה צדיק, וכן נח (לאמר, נח) זה צדיק, לאמר זו נקבה, משום שלא נפרדים זה מזה, אמר רבי יצחק, לאמר זו ארץ הקדושה) (וזה אמת). כָּתוּב כָּאן זֶה יְנַחֲמֵנוּ, וְכָתוּב שָׁם (ישעיה כה) זֶה ה' קִוִּינוּ לוֹ. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁרְשׁוּמִים בָּרֹשֶׁם שֶׁל חוֹתֶמֶת הַמֶּלֶךְ לִהְיוֹת בִּשְׁמוֹ רְשׁוּמִים, וְהוּא שָׂם שֵׁמוֹת בָּאָרֶץ כָּרָאוּי."],[4,"","כָּתוּב וַיִּקְרָא אֶת שְׁמוֹ נֹחַ, וְכָתוּב וַיִּקְרָא שְׁמוֹ יַעֲקֹב. לָמָּה לֹא כָתוּב אֶת? אֶלָּא שָׁם דַּרְגָּה אַחֶרֶת (ד\"א אחת) וְכָאן דַּרְגָּה אַחֶרֶת, (נ\"א: את, כמו שנאמר ואראה את ה') כַּכָּתוּב (שם ו) וָאֶרְאֶה אֶת ה'. וָאֶרְאֶה ה' לֹא כָתוּב אֶלָּא אֶת ה', גַּם כָּךְ בְּנֹחַ וַיִּקְרָא אֶת שְׁמוֹ נֹחַ. וַיִּקְרָא שְׁמוֹ יַעֲקֹב - דַּרְגָּה שֶׁלּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מַמָּשׁ קָרְאָה לוֹ יַעֲקֹב. אֲבָל כָּאן אֶת - לְהַכְלִיל אֶת הַשְּׁכִינָה (נ\"א: שהיא דרגה אחרת למטה)."],[5,"","אֵלֶּה תּוֹלְדת נֹחַ וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים קיב) טוֹב אִישׁ חוֹנֵן וּמַלְוֶה יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט. טוֹב אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא טוֹב, כְּמוֹ שֶׁכָּתוּב (שם קמה) טוֹב ה' לַכֹּל, וְכָתוּב (שמות טו) ה' אִישׁ מִלְחָמָה. לַכֹּל הַזֶּה חוֹנֵן וּמַלְוֶה, לְמָקוֹם שֶׁאֵין לוֹ מִשֶּׁלּוֹ, וְאוֹתוֹ מָקוֹם נִזּוֹן מִמֶּנּוּ. יְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט - שֶׁהֲרֵי אוֹתוֹ דָבָר לֹא נִזּוֹן אֶלָּא בְּמִשְׁפָּט, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֲךְ."],[6,"","דָּבָר אַחֵר טוֹב אִישׁ - זֶה צַדִּיק, שֶׁכָּתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְּרִי מַעַלְלֵיהֶם יֹאכֵלוּ. רַבִּי יוֹסֵי אָמַר, זֶה נֹחַ, שֶׁכָּתוּב נֹחַ אִישׁ צַדִּיק. רַבִּי יִצְחָק אָמַר, זֶה הַשֶּׁבַח שֶׁל הַשַּׁבָּת שֶׁבּוֹ פָּתַח טוֹב, שֶׁכָּתוּב (תהלים צב) טוֹב לְהוֹדוֹת לַה'."],[7,"","רַבִּי חִיָּיא אָמַר, הַכֹּל אֶחָד, וְכֻלָּם אָמְרוּ דָּבָר אֶחָד. וְזֶה עוֹשֶׂה תוֹלָדוֹת בָּעוֹלָם. תּוֹלָדוֹת שֶׁל הָעוֹלָם מִי הֵם? אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים שֶׁהֵם פְּרִי מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[8,"","רַבִּי שִׁמְעוֹן אָמַר, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בְּעַטְּרוֹתָיו, מִתְעַטֵּר מִלְמַעְלָה וּמִלְּמַטָּה, מִלְמַעְלָה מִמָּקוֹם שֶׁלְּעֹמֶק הַכֹּל. מִתְעַטֵּר מִלְּמַטָּה בַּמֶּה? בְּנִשְׁמוֹת הַצַּדִּיקִים. וְאָז נוֹסָפִים חַיִּים מִלְמַעְלָה וּמִלְּמַטָּה, וְנִכְלָל מְקוֹם הַמִּקְדָּשׁ מִכָּל הַצְּדָדִים, וְהַבְּאֵר מִתְמַלֵּאת וְהַיָּם נִשְׁלָם, וְאָז נוֹתֵן לַכֹּל."],[9,"","כָּתוּב (משלי ה) שְׁתֵה מַיִם מִבּוֹרֶךְ וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךְ. לָמָּה (כאן) בּוֹרֶךְ בַּתְּחִלָּה וְאַחַר כָּךְ בְּאֵרֶךְ? שֶׁהֲרֵי בּוֹר לֹא נִקְרָא אֶלָּא רֵיק שֶׁאֵינוֹ נוֹבֵעַ. בְּאֵר - מַיִם שֶׁנּוֹבְעִים? אֶלָּא הַכֹּל מָקוֹם אֶחָד הוּא. אֶלָּא מָקוֹם שֶׁהָעֲנִיִּים (נ\"א שהעני) אֲחוּזִים בּוֹ נִקְרָא בּוֹר, שֶׁאֵין לוֹ מִשֶּׁלּוֹ אֶלָּא מַה שֶּׁנּוֹתְנִים לְתוֹכוֹ, וּמִיהוּ? דָּלֶ\"ת."],[10,"","אַחַר כָּךְ נַעֲשֶׂה בְאֵר שֶׁהוּא נוֹבֵעַ וּמָלֵא (שמתמלא) מִכָּל הַצְּדָדִים, וּמִיהוּ? הֵ\"א. מִתְמַלֵּאת מִלְמַעְלָה וְנוֹבַעַת מִלְּמַטָּה. מִתְמַלֵּאת מִלְמַעְלָה כְּמוֹ שֶׁאָמַרְנוּ, וְנוֹבַעַת מִלְּמַטָּה מִנִּשְׁמוֹת הַצַּדִּיקִים."]]],[["דָּבָר אַחֵר שְׁתֵה מַיִם מִבּוֹרְךָ, דָּא דָּוִד מַלְכָּא דִּכְתִיב בֵּיהּ (שמואל ב כ״ג:ט״ו) מִי יַשְׁקֵנִי מַיִם מִבּוֹר בֵּית לֶחֶם. אִית מָאן דְּיֵימַר, וְנוֹזְלִים דָּא יִצְחָק. מִתּוֹךְ דָּא מֹשֶׁה דְאִיהוּ בְּאֶמְצָעִיתָא. בְּאֵרְךָ דָּא אַהֲרֹן דְּאִתְקְרֵי בְּאֵר מַיִם חַיִּים. וְדָּוִד מַלְכָּא דְּאִתְחַבַּר עִמְהוֹן. וְנוֹזְלִים דָּא אַבְרָהָם. מִתּוֹךְ, דָּא יַעֲקֹב דְּאִיהוּ בְּאֶמְצָעִיתָא. בְּאֵרְךָ דָּא יִצְחָק דְּאִקְרֵי בְּאֵר מַיִם חַיִּים. הָא בְּהַאי קְרָא אִשְׁתְּכַח רְתִיכָא קַדִּישָׁא עִלָּאָה מֵאֲבָהָן. וְדָוִד מַלְכָּא אִתְחַבַּר עִמְהוֹן.","תִּיאוּבְתָּא דְּנוּקְבָא לְגַבֵּי דְכוּרָא לָאו אִיהוּ אֶלָּא כַּד עֲיִּיל רוּחָא בָהּ וְאַשְׁדַּת מַיָּיא לְקִבְלָא מַיִּין עִלָּאִין דְּכוּרִין. כָּךְ כְּנֶסֶת יִשְׂרָאֵל לָא אִתְעָרַת תִּיאוּבְתָּא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בְּרוּחָא דְצַדִּיקַיָא דְּעָאלִין בְּגַוָּוהּ. וּכְדֵין נָבְעִין מַיָּיא מִגַּוָּוהּ לְקִבְלָא מַיִּין דִּדְכוּרָא. וְכֹלָּא אִתְעֲבִיד תִּיאוּבְתָּא חָדָא (ס\"א וצבורא חדא) וּצְרוֹרָא חָדָא וְקִשּׁוּרָא חָדָא. וְדָא הוּא רַעֲוָא דְּכֹלָּא וְטִיּוּלָא דִּמְטַיֵּיל קוּדְשָׁא בְּרִיךְ הוּא בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָיא.","תָּא חֲזֵי, כָּל אִנּוּן תּוֹלְדוֹת דְּגִנְתָּא דְעֵדֶן לָא נָפְקִין מִצַּדִּיק. אֶלָּא כַּד עֲיִּיל בְּהַאי תֵּיבָה בְּחִבּוּרָא חָדָא. וְכֹלָּא גְּנִיזִין בָּהּ. וּלְבָתַר מִינָהּ נָפְקִין. אוּף הָכָא נֹחַ אִישׁ צַדִּיק לָא אַפִּיק תּוֹלְדוֹת לְמִפְרֵי בְּעָלְמָא עַד דְּעָאל לַתֵּיבָה וְאִתְכְּנַשׁ כֹּלָּא בָּהּ וְהֲווּ גְנִיזִין בָּהּ. וּלְבָתַר מִנָּהּ נָפְקוּ לְמִפְרֵי בְּעָלְמָא וּלְאִתְקָיְימָא בְּאַרְעָא. וְאִלְמָלֵא דְּנָפְקוּ מִגּוֹ תֵּיבָה לָא אִתְקַיְּימוּ בְּעָלְמָא.","וְכֹלָּא כְּגַוְונָא דִלְעֵילָא. מִגּוֹ תֵּיבָה נָפְקֵי לְעֵילָא. מִגּוֹ תֵּיבָה נָפְקֵי לְתַתָּא. דָּא כְּגַוְונָא דָּא. (מגו) וְהָכָא אִתְקְיַּים עָלְמָא וְלָא מִקַּדְמַת דְּנָא. דִּבְגִינֵי כָךְ כְּתִיב וְנוֹזְלִים מִתּוֹךְ בְּאֵרְךָ. וּכְתִיב וַיּוֹלֶד נֹחַ שְׁלשָׁה בָנִים (אמר רבי יהודה וגו' ככתוב בדף סב א):","וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. אָמַר רַבִּי יְהוּדָה כֵּיוָן דִּכְתִיב וַתִּשָּׁחֵת הָאָרֶץ אַמַּאי לִפְנִי הָאֱלֹהִים. אֶלָּא כֵּיוָן דְּעֲבָדוּ חוֹבֵיהוֹן בְּאִתְגַּלְּיָא לְעֵינֵיהוֹן דְּכֹלָּא כְּדֵין לִפְנֵי הָאֱלהִים כְּתִיב.","רַבִּי יוֹסֵי אָמַר אֲנָא אִפְכָא אֲמָרִית. וַתִּשָּׁחֵת הָאָרֶץ לִפְנִי הָאֱלֹהִים. בְּקַדְמִיתָא לִפְנֵי הָאֱלֹהִים דְּלָא הֲווּ עָבְדֵי בְּאִתְגַּלְּיָיא. לִפְנֵי הָאֱלהִים עֲבָדוּ וְלָא לִפְנֵי בְּנֵי נְשָׁא. וּלְבַסוֹף עֲבָדוּ בְּאִתְגַּלְּיָא הֲדָא הוּא דִכְתִיב וַתִּמָּלֵא הָאָרֶץ חָמָס. דְּלָא הֲוָה אֲתַר בְּכָל אַרְעָא דְּלָא הֲוָה בְּאִתְגַּלְּיָא. וּבְגִין כָּךְ בִּתְרֵי גַּוְונֵי אָמַר קְרָא.","אֵלֶּה תּוֹלְדוֹת נֹחַ. רַבִּי אַבָּא אָמַר מִיּוֹמָא דְּעֲבַר אָדָם עַל פְּקוּדָא דְּמָרֵיהּ כָּל בְּנֵי עָלְמָא דְּאִתְיַלִּידוּ לְבָתַר אִקְרוּן בְּנֵי הָאָדָם. וְלָא לִשְׁבָחָא אִקְרוּן הָכִי. אֶלָּא כְּמַאן דְּאָמַר בְּנוֹי דְּהַהוּא דְּעֲבַר עַל פְּקוּדָא דְמָרֵיהּ.","כֵּיוָן דְּאָתָא נֹחַ, אִקְרוּן בְּנֵי עָלְמָא עַל שְׁמֵיהּ דְּנֹחַ. תּוֹלְדוֹת נֹחַ לְשִׁבְחָא. דְּקָאִים לוֹן בְּעָלְמָא. וְלָא תּוֹלְדוֹת דְּאָדָם דְּאַעֲבוּר לוֹן מֵעָלְמָא וְגָרִים מוֹתָא לְכֻלְהוּ.","אָמַר לֵיהּ רַבִּי יוֹסֵי, אִי הָכִי, הָא כְּתִיב לְבָתַר וַיֵּרֶד יְיָ לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל אֲשֶׁר בָּנוּ בְּנִי הָאָדָם. בְּנֵי הָאָדָם כְּתִיב וְלָא כְּתִיב בְּנֵי נֹחַ. אָמַר לֵיהּ בְּגִין דְּאָדָם (דחטא ד\"א חטא) קַמֵּי מָרֵיהּ טַב לֵיהּ דְּלָא אִבְרֵי וְלָא יִכְתּוֹב עֲלֵיהּ הַאי קְרָא.","אֶלָּא תָּא חֲזֵי, כְּתִיב (משלי י׳:א׳) בֵּן חָכָם יְשַׂמַּח אָב. כַּד בְּרָא טַב, כָּל בְּנִי עָלְמָא דָּכְרִין לֵיהּ לְאֲבוֹי לְטַב. וְכַד אִיהוּ בִּישׁ, כֹּלָּא דָּכְרִין לֵיהּ לְאֲבוֹי לְבִישׁ. אָדָם בְּגִין דְּחָטָא וְעָבַר עַל פְּקוּדָא דְּמָרֵיהּ, כַּד אָתוּ אִנּוּן דְּמָרְדוּ בְּמָרֵיהוֹן מַה כְּתִיב אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם בְּנוֹי (עה א) דְּאָדָם קַדְמָאָה דְּמָרַד בְּמָרֵיהּ וְעֲבַר עַל פְּקוּדֵיהּ.","וּבְגִינֵי כָךְ אֵלֶּה תּוֹלְדוֹת נֹחַ. אֵלֶּה וְלָא קַדְמָאֵי. אֵלֶּה דְּנָפְקוּ וְעָאלוּ גּוֹ תֵּיבָה וְאַפִּיקוּ תּוֹלְדִין לְעָלְמִין וְלָא תּוֹלְדוֹת אָדָם דְּנָפַק מִגִּנְתָּא דְעֵדֶן וְלָא אַפִּיק לוֹן מִתַּמָּן.","תָּא חֲזֵי, אִלּוּ אַפִּיק אָדָם תּוֹלְדוֹת מִגִּנְתָּא דְעֵדֶן, לָא יִשְׁתֵּצוּן לְדָרֵי דָרִין. וְלָא אִתְחַשַּׁךְ נְהוֹרָא דְסִיהֲרָא לְעָלְמִין. וְכֻלְהוּ הֲווּ קָיְימִין לְעָלְמִין. וְאֲפִילּוּ מַלְאֲכֵי עִלָּאִי לָא קָיְימֵי קָמַיְיהוּ בִּנְהוֹרָא וְזִיוָא וְחָכְמְתָא. כְּמָא דְאַתְּ אָמֵר בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ. אֲבָל כֵּיוָן דְּגָרִים חֶטְאָה וְנָפַק אִיהוּ מִגִּנְתָּא דְעֵדֶן וְעֲבַד תּוֹלְדוֹת לְבַר. לָא אִתְקָיְימוּ בְּעָלְמָא וְלָא הֲוִי כְּדְקָא חָזֵי."],[[0,"דבר אחר וכו':","שתה מים מבורך זה דוד המלך, שכתוב בו מי ישקני מים מבור בית לחם. \u0003ונוזלים,\u0004 זה אברהם. \u0003מתוך,\u0004 זה יעקב, שהוא באמצע, ומתוך פירושו מאמצע. \u0003בארך,\u0004 זה יצחק, שנקרא באר מים חיים. הרי נמצא בכתוב הזה מרכבה הקדושה מהאבות, ודוד המלך מתחבר עמהם."],[1,"תיאובתא וכו'","תשוקת הנוקבא אל הדכר אינה, אלא כשהוא מכניס בה רוח, והיא מורה מיין נוקבין לקראת מיין דכורין העליונים, כך כנסת ישראל, דהיינו המלכות, אינה מעוררת חשקה אל הקב\"ה, אלא על ידי רוחות הצדיקים הנכנסים בתוכה, בסוד מ\"ן, ואז מים נובעים מתוכה, שהם אורות חסדים מבחינת נקודת החירק המאירים בה מכח נשמות הצדיקים כנ\"ל. לקראת המים של הדכר, שהם האורות דקו ימין, עם מוחין דנקודת החולם כנ\"ל, ובחינתה עצמה ה\"ס נקודת השורק, כנ\"ל, וכל, ג' בחינות חש\"ח הללו נעשה תשוקה אחת ואגודה אחת וקשר אחד, וזהו רצוי כל, וזהו הטיול שהקב\"ה מטייל עם הצדיקים בגן עדן. וחושב ה' בחינות, הנעשים מג' הבחינות חלם שורק חירק, והם ה' בחינות מוחין הנקראים נ\"ר נח\"י. \u0003תיאובתא,\u0004 הוא אור נפש. \u0003צרורא\u0004 הוא אור הרוח. \u0003קשורא,\u0004 הוא אור הנשמה. \u0003רעוא דכלא,\u0004 הוא אור החיה. \u0003טיולא,\u0004 דמטייל קב\"ה בנשמתהון דצדיקיא, היא אור היחידה."],[2,"ת\"ח כל אינון וכו':","בוא וראה כל אלו התולדות של ג\"ע, שהיא הנוקבא דז\"א, המלבשת לאמא עלאה, שנקראת אז ג\"ע. ותולדות שלה הם הנשמות, אינם יוצאים מהצדיק, היינו יסוד דז\"א, אלא כשהוא נכנס בהתבה שהיא הנוקבא, בחיבור אחד, וכולם, כל התולדות שמקבלת מהצדיק. גנוזים בה זמן מסוים, ואח\"כ נולדים ויוצאים ממנה, אף כאן, נח איש צדיק לא הוציא תולדות לפרות בעולם, עד שנכנס לתבה, והכל נתקבץ בתוכה, והיו גנוזים בתוכה זמן מסוים, ואח\"כ יצאו ממנה לפרות בעולם ולהתקיים בארץ. ואלמלא שיצאו מתוך התבה, לא היו מתקיימים בעולם."],[3,"וכלא וכו':","והכל נעשה כעין של מעלה, מתוך התבה, שהיא הנוקבא, יצאו למעלה, מתוך התבה, יצאו למטה, דהיינו מתבת נח, זה כמו זה, ועתה נתקיים העולם, ולא מקודם לכן. שמשום זה כתוב ונוזלים מתוך בארך, וכתוב ויולד נח שלשה בנים. פירוש, ונוזלים מתוך בארך, קאי על זווג צדיק ותבה העליונים, הבא בג' קוין הנקראים אברהם יצחק יעקב, כנ\"ל, אשר ונוזלים, זה אברהם. מתוך, זה יעקב. בארך, זה יצחק. ועל דרך זה כתוב גם כאן, בנח ותבה, ויולד נח שלשה בנים, שגם הם סוד ג' קוין, \u0003שם,\u0004 ה\"ס קו ימין. \u0003חם\u0004 ה\"ס קו שמאל. \u0003יפת,\u0004 ה\"ס קו אמצעי. כי נח ותבה למטה דומים לגמרי לצדיק ותבה שלמעלה."],[4,"ותשחת הארץ וכו':","אמר ר\"י כיון דכתוב ותשחת הארץ למה כתוב, לפני האלקים. שהוא מובן מאליו. ומשיב,אלא כיון שעשו את חטאיהם בגלוי לעיני כל, כתוב אז, לפני האלקים."],[5,"רבי יוסי וכו'","רי\"א, אני אומר להיפך. ותשחת הארץ לפני האלקים, מתחלה היה לפני האלקים, שפירושו, שלא חטאו בגלוי. כי לפני האלקים עשו מעשיהם ולא לפני בני אדם. ולבסוף עשו מעשיהם בגלוי. ובב' אופנים אומר הכתוב שחטאו. דהיינו בסתר ובגלוי."],[6,"אלה תולדות נח וכו'","רא\"א, מיום שאדם עבר על מצות רבונו, כל בני האדם שנולדו אחריו נקראים בני האדם. ולא לשם שבחו נקראים כן, אלא כמי שאומר, בניו של פלוני שעבר על מצות רבונו."],[7,"כיון דאתא וכו'","כיון שבא נח, נקראים בני העולם על שמו של נח, תולדות נח, והוא לשם שבח, כי נח קיים אותם בעולם, ולא תולדות אדם שהעבירם מהעולם, וגרם לכולם המות."],[8,"א\"ל ר\"י וכו':","\"ל ר\"י אם כן, הרי כתוב לאחר מכאן, וירד ה' לראית את העיר ואת המגדל אשר בנו בני האדם. בני האדם כתוב ולא כתוב בני נח. אע\"פ שהם באו מנח. אמר לו, הוא משום שאדם חטא לפני רבונו מיחס אותם הכתוב לבני אדם, מוטב לו שלא היה נברא, ולא תכתוב עליו התורה את הכתוב הזה."],[9,"אלא ת\"ח וכו':","אלא בוא וראה, כתוב בן חכם ישמח אב, אם הבן טוב, כל בני העולם מזכירים את אביו לטוב, ואם הבן רע, הכל מזכירים את אביו לרע. אדם, משום שחטא ועבר על מצות רבונו, לכן כאשר באו אלו שמרדו ברבונם, דהיינו בוני המגדל. מה כתוב עליהם, אשר בנו בני האדם, בניו של אדם הראשון, שמרד ברבונו ועבר על מצותו."],[10,"ובנין כך וכו'","ומשום זה כתוב אלה תולדות נח, אלה, נחשבים תולדות, ולא הראשונים, אלה, שיצאו ובאו מתוך התבה הם תולדות, ולא תולדות אדם, שיצא מג\"ע ולא הוציא אותם משם. וע\"כ אינם בני קיימא."],[11,"ת\"ח וכו':","בוא וראה אלו הוציא אדם תולדות מג\"ע לא היו כלים לדורי דורות, ולא היה נחשך אור הלבנה לעולם, דהיינו אור המלכות המכונה לבנה, וכולם היו חיים לעולם, ואפילו מלאכים העליונים לא היו יכולים לעמוד בפניהם, באור וזיו וחכמה, כמ\"ש בצלם וכו', אבל כיון שגרם החטא, והוא יצא מג\"ע, ועשה תולדות מחוץ לג\"ע, לא נתקיימו בעולם, כי לא היו כראוי."]],[[0,"","דָּבָר אַחֵר, שְׁתֵה מַיִם מִבּוֹרֶךְ - זֶה דָּוִד הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (שמואל ב כג) מִי יַשְׁקֵנִי מַיִם מִבֹּאר בֵּית לֶחֶם. וְנוֹזְלִים - זֶה אַבְרָהָם. מִתּוֹךְ - זֶה יַעֲקֹב, שֶׁהוּא בָּאֶמְצַע. בְּאֵרֶךְ - זֶה יִצְחָק, שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים. הֲרֵי בַּפָּסוּק הַזֶּה נִמְצֵאת הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה מֵהָאָבוֹת. וְדָוִד הַמֶּלֶךְ הִתְחַבֵּר עִמָּם. יֵשׁ מִי שֶׁיֹּאמַר, וְנוֹזְלִים - זֶה יִצְחָק. מִתּוֹךְ - זֶה מֹשֶׁה, שֶׁהוּא בָּאֶמְצַע. בְּאֵרֶךְ - זֶה אַהֲרֹן, שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים, וְדָוִד הַמֶּלֶךְ שֶׁהִתְחַבֵּר עִמָּהֶם."],[1,"","תְּשׁוּקַת הַנְּקֵבָה לַזָּכָר אֵינָהּ אֶלָּא כַּאֲשֶׁר נִכְנֶסֶת בָּהּ רוּחַ וְשׁוֹפֶכֶת מַיִם כְּנֶגֶד הַמַּיִם הָעֶלְיוֹנִים הַזְּכָרִיִּים. כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא מְעוֹרֶרֶת הִשְׁתּוֹקְקוּת לַקָּדוֹשׁ- בָּרוּךְ-הוּא אֶלָּא בְּרוּחַ הַצַּדִּיקִים שֶׁנִּכְנָסִים בְּתוֹכָהּ, וְאָז נוֹבְעִים מַיִם מִתּוֹכָהּ כְּנֶגֶד מֵי הַזָּכָר. וְהַכֹּל נַעֲשֶׂה תְשׁוּקָה אַחַת (ואגדה אחת) וְקִשּׁוּר אֶחָד. וְזֶהוּ רָצוֹן שֶׁל הַכֹּל וְהַטִּיּוּל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְטַיֵּל עִם נִשְׁמוֹת הַצַּדִּיקִים."],[2,"","בֹּא רְאֵה, כָּל אוֹתָן תּוֹלְדוֹת גַּן הָעֵדֶן לֹא יוֹצְאִים מִצַּדִּיק אֶלָּא כְּשֶׁנִּכְנָס בַּתֵּבָה הַזּוֹ בְּחִבּוּר אֶחָד, וְהַכֹּל גְּנוּזִים בָּהּ, וְאַחַר כָּךְ יוֹצְאִים מִמֶּנָּה. גַּם כָּאן נֹחַ אִישׁ צַדִּיק לֹא הוֹצִיא תוֹלָדוֹת לִפְרוֹת בָּעוֹלָם עַד שֶׁנִּכְנַס בַּתֵּבָה, וְהִתְכַּנְּסוּ הַכֹּל בָּהּ וְהָיוּ גְנוּזִים בָּהּ, וְאַחַר כָּךְ יָצְאוּ מִמֶּנָּה לִפְרוֹת בָּעוֹלָם וּלְהִתְקַיֵּם בָּאָרֶץ. וְאִלְמָלֵא שֶׁיָּצְאוּ מִתּוֹךְ הַתֵּבָה, לֹא הִתְקַיְּמוּ בָעוֹלָם."],[3,"","וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה - מִתּוֹךְ תֵּבָה יוֹצְאִים לְמַעְלָה, מִתּוֹךְ תֵּבָה יוֹצְאִים לְמַטָּה, זֶה כְּמוֹ זֶה. (מתוך) וְכָאן הִתְקַיֵּם הָעוֹלָם וְלֹא מִקֹּדֶם לָזֶה, שֶׁמִּשּׁוּם כָּךְ כָּתוּב וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךְ, וְכָתוּב וַיּוֹלֶד נֹחַ שְׁלֹשָׁה בָנִים."],[4,"","וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁכָּתוּב וַתִּשָּׁחֵת הָאָרֶץ, לָמָּה לִפְנֵי הָאֱלֹהִים? אֶלָּא כֵּיוָן שֶׁעָשׂוּ חֲטָאֵיהֶם בְּגָלוּי לְעֵינֵי הַכֹּל, אָז כָּתוּב לִפְנֵי הָאֱלֹהִים."],[5,"","רַבִּי יוֹסֵי אָמַר, אֲנִי אָמַרְתִּי הָפוּךְ. וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים - בַּהַתְחָלָה לִפְנֵי הָאֱלֹהִים, שֶׁלֹּא הָיוּ עוֹשִׂים בְּגָלוּי. לִפְנֵי הָאֱלֹהִים עָשׂוּ וְלֹא לִפְנֵי בְּנֵי אָדָם. וּלְבַסּוֹף עָשׂוּ בְגָלוּי. זֶהוּ שֶׁכָּתוּב וַתִּמָּלֵא הָאָרֶץ חָמָס, שֶׁלֹּא הָיָה מָקוֹם בְּכָל הָאָרֶץ שֶׁלֹּא הָיָה בְגָלוּי, וּבִגְלַל כָּךְ אָמַר הַפָּסוּק בִּשְׁנֵי גְוָנִים."],[6,"","אֵלֶּה תּוֹלְדת נֹחַ - רַבִּי אַבָּא אָמַר, מִיּוֹם שֶׁעָבַר אָדָם עַל מִצְוַת רִבּוֹנוֹ, כָּל בְּנֵי הָאָדָם שֶׁנּוֹלְדוּ אַחַר כָּךְ נִקְרְאוּ בְּנֵי הָאָדָם. וְלֹא לְשֶׁבַח נִקְרְאוּ כָּךְ, אֶלָּא כְּמוֹ שֶׁאָמַר בְּנוֹ שֶׁל אוֹתוֹ שֶׁעָבַר עַל מִצְוַת רִבּוֹנוֹ."],[7,"","כֵּיוָן שֶׁבָּא נֹחַ, נִקְרְאוּ בְּנֵי הָעוֹלָם עַל שֵׁם נֹחַ. תּוֹלְדת נֹחַ לְשֶׁבַח. שֶׁהֶעֱמִידָם בָּעוֹלָם. וְלֹא תוֹלְדוֹת אָדָם שֶׁהֶעֱבִירָם מֵהָעוֹלָם וְגָרַם מָוֶת לְכֻלָּם."],[8,"","אָמַר לוֹ רַבִּי יוֹסֵי, אִם כָּךְ, הֲרֵי כָּתוּב אַחַר כָּךְ, וַיֵּרֶד ה' לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. בְּנֵי הָאָדָם כָּתוּב, וְלֹא כָתוּב בְּנֵי נֹחַ. אָמַר לוֹ, מִשּׁוּם שֶׁאָדָם (שחטא ד\"א חטא) לִפְנֵי רִבּוֹנוֹ, טוֹב לוֹ שֶׁלֹּא נִבְרָא וְלֹא יִכְתֹּב עָלָיו הַכָּתוּב פָּסוּק זֶה."],[9,"","אֶלָּא בּא רְאֵה, כָּתוּב (משלי י) בֵּן חָכָם יְשַׂמַּח אָב. כַּאֲשֶׁר הַבֵּן טוֹב, כָּל בְּנֵי הָעוֹלָם זוֹכְרִים אֶת אָבִיו לְטוֹב. וּכְשֶׁהוּא רַע, כֻּלָּם זוֹכְרִים אֶת אָבִיו לְרַע. אָדָם, מִשּׁוּם שֶׁחָטָא וְעָבַר עַל מִצְוַת רִבּוֹנוֹ, כְּשֶׁבָּאוּ אוֹתָם שֶׁמָּרְדוּ בְּרִבּוֹנָם מַה כָּתוּב? אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. אָדָם הָרִאשׁוֹן שֶׁמָּרַד בְּרִבּוֹנוֹ וְעָבַר עַל מִצְוָתוֹ,"],[10,"","וְלָכֵן אֵלֶּה תּוֹלְדת נֹחַ. אֵלֶּה וְלֹא הָרִאשׁוֹנִים. אֵלֶּה שֶׁיָּצְאוּ וְנִכְנְסוּ לְתוֹךְ הַתֵּבָה וְהוֹצִיאוּ תוֹלָדוֹת לְעוֹלָמִים. וְלֹא תוֹלְדוֹת אָדָם שֶׁיָּצָא מִגַּן עֵדֶן וְלֹא הוֹצִיא אוֹתָם מִשָּׁם."],[11,"","בֹּא רְאֵה, אִלּוּ הוֹצִיא אָדָם תּוֹלָדוֹת מִגַּן עֵדֶן, לֹא הָיוּ מֻשְׁמָדִים לְדוֹרֵי דוֹרוֹת, וְלֹא נֶחְשַׁךְ אוֹר הַלְּבָנָה לְעוֹלָמִים, וְכֻלָּם הָיוּ קַיָּמִים לְעוֹלָמִים, וַאֲפִלּוּ מַלְאָכִים עֶלְיוֹנִים לֹא עָמְדוּ לִפְנֵיהֶם בְּאוֹר וְזִיו וְחָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ. אֲבָל כֵּיוָן שֶׁגָּרַם הַחֵטְא וְיָצָא מִגַּן עֵדֶן וְעָשָׂה תוֹלָדוֹת בַּחוּץ, לֹא הִתְקַיְּמוּ בָעוֹלָם וְלֹא הָיוּ כָּרָאוּי."]]],[["אָמַר רַבִּי חִזְקִיָּה וְכֵי הֵיךְ יָכְלִין לְמֶעְבַּד תּוֹלְדוֹת תַּמָּן דְּהָא אִלְּמָלֵא לָא אִתְמְשִׁיךְ עֲלֵיהּ יֵצֶר הָרָע וְחָטָא אִתְקְיַּים אִיהוּ בְּעָלְמָא בִּלְחוֹדוֹי וְלָא יַעֲבִיד תּוֹלְדוֹת. כְּגַוְונָא דָא אִלְּמָלֵא דְּחָבוּ יִשְׂרָאֵל בְּעֶגְלָא וְאַמְשִׁיכוּ עֲלַיְיהוּ יֵצֶר הָרָע לָא עֲבָדוּ (במדבר קפט א) תּוֹלְדוֹת לְעָלְמִין וְלָא יֵיתוּן דָּרִין אָחֳרָנִין לְעָלְמָא.","אָמַר לֵיהּ אִלְמָלֵא לֹא חָטָא אָדָם לָא עָבִיד תּוֹלְדוֹת כְּגַוְונָא דָא מִסִּטְרָא דְּיֵצֶר הָרָע. אֲבָל עָבִיד תּוֹלְדוֹת מִסִּטְרָא דְּרוּחָא קַדִּישָׁא. דְּהַשְׁתָּא לָא עָבִיד תּוֹלְדוֹת אֶלָּא מִסִּטְרָא דְּיֵצֶר הָרָע. וּבְגִין דְּכָל תּוֹלְדוֹת דִּבְנֵי נָשָׁא כֻּלְהוּ מִסִּטְרָא דְּיֵצֶר הָרָע, בְּגִין כָּךְ לֵית לוֹן קִיּוּם. וְאִי אֶפְשָׁר לוֹן לְאִתְקָיְימָא, דְּסִטְרָא אָחֳרָא אִתְעָרַב בְּהוּ. (ז\"ח ל\"ג ואפשר לון בסטרא אחרא).","אֲבָל אִלְּמָלֵא לא חָטָא אָדָם וְלָא אִתְתָּרַךְ מִגִּנְתָּא דְעֵדֶן. הֲוָה עָבִיד תּוֹלְדוֹת מִסִּטְרָא דְּרוּחַ קוּדְשָׁא דְּקַדִּישִׁין כְּמַלְאֲכֵי עִלָּאִין קָיְימִין לְדָרֵי דָרִין כְּגַוְונָא דִלְעֵילָא. כֵּיוָן דְּחָטָא וְאוֹלִיד בְּנִין לְבַר מִגִּנְתָּא דְעֵדֶן, וְלָא זָכָה לְאַפָּקָא לוֹן מִגִּנְתָּא, לָא אִתְקָיְימוּ אֲפִלּוּ לְאִשְׁתְּרָשָׁא בְּעָלְמָא דָא. עַד דְּאָתָא נֹחַ דְּאִיהוּ צַדִּיק וְעָאל בַּתֵּבָה. וּמִן תֵּבָה נָפְקוּ כָּל דָּרִין דְּעָלְמָא. וּמִתַּמָּן אִתְבַּדְּרוּ לְכָל אַרְבַּע רוּחֵי עָלְמָא. (שייך לקמן ריש סב):","וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנִּה נִשְׁחָתָה. אַמַּאי נִשְׁחָתָה. בְּגִין כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, כְּמָה דְּאִתְּמָר. רַבִּי חִיָּיא פָּתַח קְרָא וְאָמַר (יונה ג׳:י׳) וַיַּרְא אֱלֹהִים אֶת מַעֲשֵׂיהֶם כִּי שָׁבוּ מִדַּרְכָּם הָרָעָה. תָּא חֲזֵי, בְּשַׁעֲתָא דִּבְנֵי נָשָׁא זָכָאן וְנָטְרֵי פִּקּוּדֵי דְאוֹרַיְיתָא, כְּדֵין אַרְעָא אִתְתַּקְפַת, וְכָל חֵידוּ אִשְׁתַּכְּחַת בָּהּ. מַאי טַעְמָא בְּגִין דִּשְׁכִינְתָּא שָׁרְיָא עַל אַרְעָא. וּכְדֵין כֹּלָּא עִלָּאֵי וְתַתָּאֵי בְּחֶדְוָה. וְכַד בְּנֵי נָשָׁא מְחַבְּלָן אָרְחַיְיהוּ וְלָא נָטְרֵי פְּקוּדֵי אוֹרַיְיתָא וְחָטָאן קַמֵּי מָארִיהוֹן, וּכְדֵין כִּבְיָכוֹל דַּחְיָין לָהּ לִשְׁכִינְתָּא מֵעָלְמָא וְאִשְׁתְּאָרַת אַרְעָא מְחַבְּלָא. דְּהָא שְׁכִינְתָּא אִתְדַּחְיָיא וְלָא שָׁרְיָא עֲלָהּ וּכְדֵין אִתְחַבְּלַת. מַאי טַעֲמָא אִתְחַבְּלַת. בְּגִין דְּשַׁרְיָא רוּחָא אָחֳרָא עֲלָהּ דִּמְחַבְּלָא עָלְמָא. וְעַל דָּא אַמְרִינָן דְּיִשְׂרָאֵל יָהֲבֵי עוֹז לֵאלהִים דִּמְקַיְימִין עָלְמָא. אֱלהִים דָּא שְׁכִינְתָּא.","וְאִם חַס וְשָׁלוֹם אִי יִשְׂרָאֵל יִשְׁתַּכְּחוּ חַיָּיבִין מַה כְּתִיב, (תהלים ו) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים וְגו' מִשּׁוּם דְּרֶשֶׁת הֵכִינוּ לִפְעָמַי. כָּפַף נַפְשִׁי בְּסִבַת חָמָס וְשִׂנְאַת חִנָּם. כָּרוּ לְפָנַי שׁוּחָה וְגו' כְּגַוְונָא דְדוֹר הַמַּבּוּל דִּבְגִין חָמָס דְּהֲוַת בֵּינֵיהוֹן הֲוָה בֵּינֵיהוֹן שִׂנְאָה וּדְבָבוּ.","יָכוֹל אַף בְאַרְעָא דְיִשְׂרָאֵל כֵּן. וְהָא תָּנִינָן אַרְעָא דְיִשְׂרָאֵל לָא שַׁרְיָא עֲלָהּ רוּחָא אָחֳרָא וְלָא מְמַנָּא אָחֳרָא בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. תָּא חֲזֵי, דְּאַרְעָא דְיִשְׂרָאֵל הָכִי הוּא דְּלָא שַׁרְיָא עֲלָהּ (פד ע\"ב) מְמַנָּא וְלָא שְׁלִיחָא אָחֳרָא בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. אֲבָל שַׁעֲתָא חָדָא שַׁרְיָא עֲלָהּ לְחַבְּלָא בְּנִי נָשָׁא. מְנָלָן מִדָּוִד דִּכְתִיב, (דברי הימים א כ״א:ט״ז) וַיַּרְא דָוִד אֶת מַלְאַךְ יְיָ וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ נְטוּיָה עַל יְרוּשָׁלַ ם וּכְדֵין אִתְחַבָּלַת אַרְעָא.","אָמַר רַבִּי אֶלְעָזָר אֲפִלּוּ בְּהַהִיא שַׁעֲתָא קוּדְשָׁא בְּרִיךְ הוּא הֲוָה. כְּתִיב הָכָא מַלְאַךְ יְיָ. וּכְתִיב הָתָם (בראשית מ״ח:ט״ז) הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי. וּכְתִיב (שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלהִים. הֵן לְטַב וְהֵן לְבִישׁ קוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט עֲלָהּ. לְטַב בְּגִין דְּלָא אִתְמַסְּרָא תְּחוֹת שְׁאָר מְמַנָּן, וְכָל דָּיְירֵי עָלְמָא יִכְסְפוּן מִן עוֹבָדַיְיהוּ. לְבִישׁ בְּגִין דְּלָא יֶחדוּן אִנּוּן לְשַׁלְטָאָה עֲלָהּ.","וְאִי תֵימָא (ד\"א ל\"ג לא) וְהָא כְּתִיב, (איכה א׳:י׳) כִּי רָאֲתָה גוֹיִם בָּאוּ מִקְדָשָׁהּ וְחֲרִיבוּ בֵּיתָא וְאִי לָאו שָׁלְטִין אִנּוּן מְמַנָּן לָא אִתְחָרַב מַקְדְּשָׁא. תָּא חֲזֵי, כְּתִיב כִּי אַתָּה עָשִׂיתָ וּכְתִיב עָשָׂה יְיָ אֶת אֲשֶׁר זָמַם.","תָּא חֲזֵי, כְּתִיב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה. נִשְׁחָתָה וַדַּאי כְּמָה דְּאִתְּמָר. הָכִי נָמֵי (יונה ג׳:י׳) וַיַּרְא אֱלהִים אֶת מַעֲשֵׂיהֶם כִּי שָׁבוּ מִדַּרְכָּם הָרָעָה. דְּהָא כְּדֵין אַרְעָא קָרָאת לְעֵילָא וְסָלְקָא בִּסְלִיקוּ עִלָּאָה וּמְקַשְׁטָא אַנְפָּהָא. כְּנוּקְבָא דִּמְקַשְׁטָא לְגַבֵּי דְכוּרָא. הָכִי נָמֵי אַרְעָא. דְּהָא גְּדִילַת בְּנִין זַכָּאִין לְמַלְכָּא.","וְהָכָא דְּלָא תָבוּ דָרָא דְּטוֹפָנָא מַה כְּתִיב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה וְגו' כְּאִתְּתָא דְּאִסְתָּאֲבַת וְאַסְתִּירַת אַנְפָּהָא מִבַּעֲלָהּ. וּבְזִמְנָא דְּאַסְגִיאוּ חוֹבֵי בְּנִי נָשָׁא בְּאִתְגַּלְּיָא, אַרְעָא שַׁוִּיתָא אַנְפָּהָא כְּנוּקְבָא דְּלֵית לָהּ כִּסּוּפָא מִכֹּלָּא כְּמָה דְאַתְּ אָמֵר, (ישעיה כב) וְהָאָרֶץ חָנְפָה תַּחַת יוֹשְׁבֶיהָ. וְעַל דָּא וַיַּרְא כִּי נִשְׁחָתָה וַדַּאי. מַאי טַעֲמָא בְּגִין כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ."],[[0,"א\"ר חזקיה וכו':","אר\"ח, ואיך היו יכולים להוליד תולדות שם, בגן עדן, הרי אלו לא היה היצה\"ר נמשך עליו וחטא היה הוא בלבדו מתקיים בעולם, ולא היה עושה תולדות. כעין זה, אלמלא חטאו ישראל והמשיכו עליהם היצה\"ר אחר קבלת התורה, לא היו עושים תולדות לעולם, ולא היו באים דורות אחרים בעולם. ועיקר קושיתו הוא, הרי כל עיקר כח הזווג בא רק מפאת היצר הרע (כמ\"ש לעיל בזהר בראשית ב' דף קלא אות ר\"ז) ובלי יצה\"ר אין תולדות."],[1,"א\"ל אלמלא וכו':","אמר לו, אם לא חטא אדם לא היה מוליד תולדות, בדרך זה מצד היצר הרע, אלא שהיה עושה תולדות מצד רוח הקדוש, כי עתה אינו עושה תולדות רק מצד היצה\"ר ומשום שתולדות בני אדם כולם הם מצד היצה\"ר, אין להם קיום משום זה, ואי אפשר להם להתקיים, כי הסטרא אחרא נתערב בהם."],[2,"אבל אלמלא וכו':","אבל אם לא חטא אדם, ולא נגרש מגן עדן, היה עושה תולדות מצד רוח קודש הקדשים כמלאכים העליונים. והיו חיים לדורי דורות כמו שהוא למעלה. כלומר, שיש ב' זווגים: א' זווג רוחני למלאכים, ב' זווג דיסודות לנשמות. ומ\"ש שצריכים יצה\"ר, הוא רק לזווג דיסודות, ולא לזווג רוחני שהוא מצד רוח הקודש. כיון שחטא והוליד בנים מחוץ לג\"ע, ולא זכה להוליד אותם מגן עדן, לכן לא נתקיימו, אפילו להשתרש בעולם הזה עד שבא נח ונכנס בהתבה, ומהתבה יצאו כל דורות העולם ומשם נפוצו לכל ארבע רוחות העולם."],[3,"וירא אלקים וכו':","למה נשחתה וכי הארץ בת עונשין היא. ומשיב, משום כי השחית כל בשר את דרכו כמו שאמרו. ר\"ח פתח קרא ואמר, וירא אלקים את מעשיהם וגו', בוא וראה בשעה שבני אדם הם צדיקים, ושומרים מצות התורה אז הארץ מתחזקת וכל חדוה נמצאת בה, מהו הטעם, משום שהשכינה שורה על הארץ ואז העליונים והתחתונים כולם הם בחדוה."],[4,"וכד בני וכו':","וכשבני אדם משחיתים דרכם ואינם שומרים מצות התורה, וחוטאים לפני רבונם, אז, כביכול, דוחים את השכינה מהעולם, והארץ נשארת נשחתה, שהרי השכינה נדחה ממנה ואינה שורה עליה, ואז נשחתת. מהו הטעם שנשחתת, הוא משום שרוח אחר שורה עליה המשחית העולם. מן וע\"ד אמרינן, עד שנאה ודבבו ל\"ג בדפוסים הראשונים. ונראה שהוא גליון."],[5,"יכול אף וכו':","יכול שאפילו בארץ ישראל הוא כן, שגם עליה שורה רוח אחר. והרי למדנו ארץ ישראל אינה שורה עליה לא רוח אחר ולא ממונה אחר זולת הקב\"ה בלבדו. וא\"כ למה נשחתה ארץ ישראל. ומשיב, בוא וראה כי ארץ ישראל, כן הוא, שממונה אינה שורה עליה ולא שליח אחר חוץ מהקב\"ה בלבדו, אבל שעה אחת יוכל המחבל לשרות עליה לחבל בני אדם, מאין לנו זה, מדוד, שכתוב, וירא את מלאך ה' עומד, וחרבו שלופה בידו נטויה על ירושלים, ואז נשחתה הארץ."],[6,"א\"ר אלעזר וכו':","אפילו בשעה ההיא, שראה מלאך ה' עומד, היה זה הקב\"ה, ויליף גזרה שוה, כאן כתוב מלאך ה', ושם כתוב המלאך הגואל אותי, וכתוב ויסע מלאך האלקים, מה שם הוא הקב\"ה, אף כאן הוא הקב\"ה. ובין לטוב ובין לרע שולט עליה הקב\"ה: \u0003לטוב,\u0004 משום שא\"י לא נמסרה תחת שום ממונה ואין מי שיטיב לה רק הקב\"ה בלבדו, וכל דרי עולם יבושו ממעשיהם, להיותם תחת ממונים. \u0003לרע,\u0004 שולט עליה רק הקב\"ה, כדי שלא ישמחו אז הממונים לשלוט עליה."],[7,"ואו תימא וכו'","ואם תאמר, הרי כתוב, כי ראתה גוים באו מקדשה, והחריבו הבית, שמשמע, שאם הממונים לא היו שולטים לא היה נחרב הבית. בוא וראה, שכתוב, כי אתה עשית, וכתוב עשה ה' אשר זמם, הרי שנעשה ע\"י הקב\"ה עצמו ולא ע\"י ממונים."],[8,"ת\"ח כתיב וכו':","בוא וראה, כתוב וירא אלקים את הארץ והנה נשחתה, היא נשחתה ודאי, כמו שכבר נאמר (לעיל אות ל\"ט). כמו כן, וירא אלקים את מעשיהם כי שבו מדרכם הרעה, כי אז קוראת הארץ למעלה, אל ז\"א, ועולה במעלה עליונה, ומיפה פניה כמו נקבה המיפה את עצמה בפני הזכר, כן הארץ, כי בנים צדיקים גדלה להמלך, לז\"א."],[9,"והכא דלא וכו':","וכאן, שלא שבו דור המבול, מה כתוב, וירא אלקים את הארץ והנה נשחתה וגו', כאשה שנטמאה ומסתרת פניה מבעלה, ובשעה שעונות בני אדם מתרבים לחטא בגלוי, משימה הארץ פניה כנקבה שאין לה בושה משום דבר, כמש\"ה והארץ חנפה תחת יושביה, וע\"כ וירא, כי נשחתה ודאי, מהו הטעם, משום כי השחית כל בשר דרכו על הארץ."]],[[0,"","אָמַר רַבִּי חִזְקִיָּה, וְכִי אֵיךְ יָכְלוּ לַעֲשׂוֹת תּוֹלָדוֹת שָׁם, שֶׁהֲרֵי אִלְמָלֵא לֹא נִמְשַׁךְ עָלָיו יֵצֶר הָרָע וְחָטָא, יִתְקַיֵּם הוּא בָּעוֹלָם לְבַדּוֹ וְלֹא יַעֲשֶׂה תוֹלָדוֹת? כְּמוֹ זֶה אִלְמָלֵא שֶׁחָטְאוּ יִשְׂרָאֵל בָּעֵגֶל וְהִמְשִׁיכוּ עֲלֵיהֶם יֵצֶר הָרָע, לֹא יַעֲשׂוּ לְעוֹלָמִים תּוֹלָדוֹת וְלֹא יָבאוּ דוֹרוֹת אֲחֵרִים לָעוֹלָם."],[1,"","אָמַר לוֹ, אִלְמָלֵא לֹא חָטָא אָדָם, לֹא יַעֲשֶׂה תוֹלָדוֹת כְּמוֹ זֶה מִצַּד שֶׁל יֵצֶר הָרָע, אֲבָל יַעֲשֶׂה תוֹלָדוֹת מִצַּד שֶׁל רוּחַ הַקֹּדֶשׁ. שֶׁעַכְשָׁו אֵינוֹ עוֹשֶׂה תוֹלָדוֹת אֶלָּא מִצַּד הַיֵּצֶר הָרָע, וּמִשּׁוּם שֶׁכָּל תּוֹלְדוֹת בְּנֵי הָאָדָם כֻּלָּם מִן הַצַּד שֶׁל יֵצֶר הָרָע, לָכֵן אֵין לָהֶם קִיּוּם, וְאִי אֶפְשָׁר לָהֶם לְהִתְקַיֵּם, שֶׁהַצַּד הָאַחֵר מְעֹרָב בָּהֶם (ואפשר להם בצד האחר)."],[2,"","אֲבָל אִלְמָלֵא לֹא חָטָא אָדָם וְלֹא גֹרַשׁ מִגַּן עֵדֶן, הָיָה עוֹשֶׂה תוֹלָדוֹת מִצַּד שֶׁל רוּחַ הַקֹּדֶשׁ, שֶׁקְּדוֹשִׁים כְּמַלְאָכִים עֶלְיוֹנִים עוֹמְדִים לְדוֹרֵי דוֹרוֹת כְּמוֹ שֶׁהָיָה לְמַעְלָה. כֵּיוָן שֶׁחָטָא וְהוֹלִיד בָּנִים מִחוּץ לְגַן עֵדֶן וְלֹא זָכָה לְהוֹצִיאָם מִן הַגָּן, לֹא הִתְקַיְּמוּ אֲפִלּוּ לְהִשְׁתָּרֵשׁ בָּעוֹלָם הַזֶּה, עַד שֶׁבָּא נֹחַ, שֶׁהוּא צַדִּיק, וְנִכְנַס בַּתֵּבָה, וּמֵהַתֵּבָה יָצְאוּ כָּל דּוֹרוֹת הָעוֹלָם, וּמִשָּׁם הִתְפַּזְּרוּ לְכָל אַרְבַּע רוּחוֹת הָעוֹלָם."],[3,"","וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה. לָמָּה נִשְׁחָתָה? מִשּׁוּם כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, כְּמוֹ שֶׁנֶּאֱמַר. רַבִּי חִיָּיא פָּתַח פָּסוּק וְאָמַר, (יונה ג) וַיַּרְא אֱלֹהִים אֶת מַעֲשֵׂיהֶם כִּי שָׁבוּ מִדַּרְכָּם הָרָעָה. בֹּא רְאֵה, בְּשָׁעָה שֶׁבְּנֵי אָדָם זוֹכִים וְשׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה, אָז הָאָרֶץ מִתְחַזֶּקֶת וְנִמְצֵאת בָּהּ כָּל הַשִּׂמְחָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַשְּׁכִינָה שׁוֹרָה עַל הָאָרֶץ. וְאָז הַכֹּל, עֶלְיוֹנִים וְתַחְתּוֹנִים, בְּחֶדְוָה. וּכְשֶׁבְּנֵי אָדָם מַשְׁחִיתִים דַּרְכֵיהֶם וְלֹא שׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה וְחוֹטְאִים לִפְנֵי רִבּוֹנָם, אָז כִּבְיָכוֹל דּוֹחִים אֶת הַשְּׁכִינָה מֵהָעוֹלָם, וְנִשְׁאֶרֶת הָאָרֶץ מֻשְׁחֶתֶת, שֶׁהֲרֵי הַשְּׁכִינָה נִדְחֲתָה וְלֹא שׁוֹרָה עָלֶיהָ, וְאָז הִיא נִשְׁחֶתֶת. מָה הַטַּעַם נִשְׁחֶתֶת? מִשּׁוּם שֶׁשּׁוֹרָה רוּחַ אַחֶרֶת עָלֶיהָ שֶׁמְּחַבֶּלֶת אֶת הָעוֹלָם. וְעַל זֶה אוֹמְרִים, שֶׁיִּשְׂרָאֵל נוֹתְנִים עֹז לֵאלֹהִים שֶׁמַּעֲמִידִים אֶת הָעוֹלָם. אֱלֹהִים זוֹ שְׁכִינָה."],[4,"","וְאִם חַס וְשָׁלוֹם אִם יִשְׂרָאֵל יִמָּצְאוּ רְשָׁעִים, מַה כָּתוּב? (תהלים ו) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים וְגוֹ', מִשּׁוּם שֶׁרֶשֶׁת הֵכִינוּ לִפְעָמַי. כָּפַף נַפְשִׁי, בְּסִבַּת חָמָס וְשִׂנְאַת חִנָּם. כָּרוּ לְפָנַי שׁוּחָה וְגוֹ', כְּמוֹ שֶׁבְּדוֹר הַמַּבּוּל, שֶׁמִּשּׁוּם הֶחָמָס שֶׁהָיָה בֵינֵיהֶם, הָיְתָה בֵינֵיהֶם שִׂנְאָה וְאֵיבָה."],[5,"","יָכוֹל אַף בְּאֶרֶץ יִשְׂרָאֵל כֵּן? וַהֲרֵי שָׁנִינוּ שֶׁאֶרֶץ יִשְׂרָאֵל לֹא שׁוֹרָה עָלֶיהָ רוּחַ אַחֶרֶת וְלֹא מְמֻנֶּה אַחֵר חוּץ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ. בֹּא רְאֵה שֶׁאֶרֶץ יִשְׂרָאֵל כָּךְ הִיא שֶׁלֹּא שׁוֹרֶה עָלֶיהָ מְמֻנֶּה וְלֹא שָׁלִיחַ אַחֵר פְּרָט לַקָּדוֹשׁ-בָּרוּךְ- הוּא לְבַדּוֹ, אֲבָל שָׁעָה אַחַת שׁוֹרֶה עָלֶיהָ לְהַשְׁחִית אֶת בְּנֵי הָאָדָם. מִנַּיִן לָנוּ? מִדָּוִד, שֶׁכָּתוּב (דברי הימים א כא) וַיַּרְא דָוִד אֶת מַלְאַךְ ה' וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ נְטוּיָה עַל יְרוּשָׁלַיִם, וְאָז נִשְׁחֲתָה הָאָרֶץ."],[6,"","אָמַר רַבִּי אֶלְעָזָר, אֲפִלּוּ בְּאוֹתָהּ שָׁעָה הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה. כָּתוּב כָּאן מַלְאַךְ ה', וְכָתוּב שָׁם (בראשית מח) הַמַּלְאָךְ הַגֹּאֵל אֹתִי, וְכָתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. הֵן לְטוֹב הֵן לְרַע שׁוֹלֵט עָלֶיהָ הַקָּדוֹשׁ בָּרוּךְ הוּא. לְטוֹב - מִשּׁוּם שֶׁלֹּא נִמְסְרָה תַּחַת שְׁאָר הַמְמֻנִּים, וְכָל דַּיָּרֵי הָעוֹלָם יִתְבַּיְּשׁוּ מִמַּעֲשֵׂיהֶם. לְרַע - כְּדֵי שֶׁלֹּא יִשְׂמְחוּ אֵלֶּה לִשְׁלֹט עָלֶיהָ."],[7,"","וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (איכה א) כִּי רָאֲתָה גוֹיִם בָּאוּ מִקְדָּשָׁהּ, וְהֶחֱרִיבוּ בֵיתָהּ. וְאִם לֹא שׁוֹלְטִים אוֹתָם מְמֻנִּים, לֹא נֶחֱרַב הַמִּקְדָּשׁ! בֹּא רְאֵה, כָּתוּב כִּי אַתָּה עָשִׂיתָ, וְכָתוּב (שם ב) עָשָׂה ה' אֲשֶׁר זָמָם."],[8,"","בֹּא רְאֵה, כָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה. נִשְׁחָתָה וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר. כָּךְ גַּם (יונה ג) וַיַּרְא אֱלֹהִים אֶת מַעֲשֵׂיהֶם כִּי שָׁבוּ מִדַּרְכָּם הָרָעָה. שֶׁהֲרֵי אָז הָאָרֶץ קוֹרֵאת לְמַעְלָה וְעוֹלָה בַּעֲלִיָּה עֶלְיוֹנָה וּמְקַשֶּׁטֶת פָּנֶיהָ כִּנְקֵבָה שֶׁמִּתְקַשֶּׁטֶת אֶל הַזָּכָר, כָּךְ גַּם הָאָרֶץ, שֶׁהֲרֵי גִּדְּלָה בָנִים צַדִּיקִים לַמֶּלֶךְ."],[9,"","וְעַכְשָׁו שֶׁלֹּא שָׁבוּ דּוֹר הַמַּבּוּל מַה כָּתוּב? וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה, כְּאִשָּׁה שֶׁנִּטְמְאָה וְהִסְתִּירָה פָנֶיהָ מִבַּעְלָהּ. וּבִזְמַן שֶׁמִּתְרַבִּים חֲטָאֵי בְּנֵי הָאָדָם בְּגָלוּי, הָאָרֶץ שָׂמָה פָנֶיהָ כִּנְקֵבָה שֶׁאֵין לָהּ בּוּשָׁה מִכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כד) וְהָאָרֶץ חָנְפָה תַּחַת יֹשְׁבֶיהָ. וְעַל זֶה וַיַּרְא כִּי נִשְׁחָתָה וַדַּאי. מָה הַטַּעַם? מִשּׁוּם כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ."]]],[["רַבִּי אֶלְעָזָר אֲזַל לְגַבֵּיהּ דְּרַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמוֹי. כֵּיוָן דְּחָמָא לֵיהּ אַתְקִין לֵיהּ תּוּפְסִיתָא (ס\"א טופסיסא) דְּקוּמְרָא בְּמָטוּן דְּקוּלְפָא וִיתִיבוּ. אָמַר לֵיהּ חָמוֹי אֶפְשָׁר דְּשָׁמַעְתְּ מֵאָבוּךְ הַאי דִכְתִיב (איכה ב׳:י״ז) עָשָׂה יְיָ אֲשֶׁר זָמַם בִּצַּע אֶמְרָתוֹ אֲשֶׁר צִוָה מִימֵי קֶדֶם.","אָמַר לֵיהּ הָא אוּקְמוּהָ חַבְרַיָא. בִּצַּע אֶמְרָתוֹ, דְּבָזַע פּוֹרְפִּירָא דִּילֵיהּ. אֲשֶׁר צִוָּה מִימֵי קֶדֶם, דְּהָא פּוֹרְפִּירָא פָּקִיד לָהּ מֵאִנּוּן יוֹמֵי קַדְמָאֵי עִלָּאֵי, וּבְיוֹמָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא בָּזַע לָהּ. בְּגִין דְּהַאי פּוֹרְפִּירָא אִיהִי יְקָרָא דִילֵיהּ וְתִיקוּנָא דִילֵיהּ וּבָזַע לֵיהּ.","אָמַר לֵיהּ עָשָׂה יְיָ אֲשֶׁר זָמַם. וְכִי מַלְכָּא חָשִׁיב (קודם) לְאַבְאָשָׁא לִבְנוֹי עַד לָא יֵיתוּן לְמֶחְטֵי. אָמַר לֵיהּ לְמַלְכָּא דְּהֲוָה לֵיהּ מָאן יְקָר, וּבְכָל יוֹמָא הֲוָה דָּחִיל עֲלֵיהּ דְּלָא יִתְבַּר וְהֲוָה מִסְתַּכֵּל בֵּיהּ וְתַקִּין בְּעֵינוֹי. לְיוֹמִין אֲתָא בְּרֵיהּ וְאַרְגִּיז לֵיהּ לְמַלְכָּא, נְטַל מַלְכָּא הַהוּא מָאן יְקָר וּתְבַר לֵיהּ. הֲדָא הוּא דִכְתִיב עָשָׂה יְיָ אֲשֶׁר זָמָם.","תָּא חֲזֵי, מִן יוֹמָא דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא הֲוָה קוּדְשָׁא בְּרִיךְ הוּא מִסְתַּכֵּל בֵּיהּ וְחֲבִיב עֲלֵיהּ סַגֵּי וְהֲוָה דָּחִיל עֲלַיְיהוּ דְּיִשְׂרָאֵל דְּיֶחטוּן וִיחָרֵב בֵּי מַקְדְּשָׁא. וְכֵן בְּכָל זִמְנָא דְּהֲוָה אָתֵי לְגַבֵּי בֵּי מַקְדְּשָׁא הֲוָה לָבִישׁ הַהוּא פּוֹרְפִּירָא. לְבָתַר דְּגָרְמוּ חוֹבִין וְאַרְגִּיזוּ קַמֵּי מַלְכָּא אִתְחָרַב בֵּי מַקְדְּשָׁא וּבָזַע הַהוּא פּוֹרְפִּירָא (ד\"א גריס הס ההוא פורפירא ואתחרב בי מקדשא) הַיְנוּ דִכְתִיב עָשָׂה יְיָ אֲשֶׁר זָמַם.","בִּצַּע אִמְרָתוֹ וְגו' (האי אמרתו בקדמיתא יתבא בראש אמיר. והא אתעטרו עטרא לרישא ואילן נאה לפניו. ואיהי מימי קדם ודאי. וכדין עציבו קמיה בבתי בראי ודאי והן (ישעיהו ל״ג:ז׳) אראלם צעקו חוצה.","(ישעיהו כ״ב:י״ב) ויקרא יי צבאות ביום ההוא וגו) הַיְינוּ בְּזִמְנָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא. אֲבָל בְּזִמְנָא אֳחָרָא לֵית חֶדְוָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כְּזִמְנָא דְּאִתְאֲבִידוּ חַיָּיבֵי עָלְמָא וְאִנּוּן דְּאַרְגִּיזוּ קַמֵּיהּ הֲדָא הוּא דִכְתִיב, (משלי י״א:י׳) וּבַאֲבוֹד רְשָׁעִים רִנָּה. וְכֵן בְּכָל דָּרָא וְדָרָא דְּעָבִיד דִּינָא בְּחַיָּיבֵי עָלְמָא. חֶדְוָה וְתוּשְׁבַּחְתָּא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא.","וְאִי תֵימָא הָא תָּנִינָן דְּלֵית חֶדְוָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כַּד אִיהוּ עָבִיד דִּינָא בְּחַיָּיבַיָא. אֶלָּא תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְעֲבִיד דִּינָא בְּחַיָּיבַיָא, חֶדְוָון וְתוּשְׁבְּחָן קַמֵּיהּ עַל דְּאִתְאֲבִידוּ מֵעָלְמָא. וְהָנֵּי מִילֵי כַּד מָטָא הַהוּא זִמְנָא (קיג ב, קכא ב) דְּאוֹרִיךְ לוֹן וְלָא תָאבָן לְגַבֵּיהּ מֵחוֹבַיְיהוּ. אֲבָל אִי אִתְעֲבִיד בְּהוּ דִּינָא עַד לָא מָטָא זִמְנַיְיהוּ, (ועד דלא אשתלים חובייהו, כמא דאת אמר, (בראשית ט״ו:ט״ז)) כִּי לא שָׁלֵם עֲוֹן הָאֱמוֹרִי עַד הֵנָּה, כְּדֵין לֵית חֶדְוָה קַמֵיהּ וּבָאִישׁ קַמֵּיהּ עַל דְּאִתְאֲבִידוּ.","וְאִי תֵימָא אִיהוּ עַד לָא מָטוּ זִמְנַיְיהוּ אַמַּאי עָבִיד בְּהוּ דִּינָא. אֶלָּא אִנּוּן גָּרְמִין בִּישָׁא לְגַרְמַיְיהוּ. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא עָבִיד בְּהוּ דִּינָא עַד לָא מָטָא זִמְנַיְיהוּ. אֶלָּא בְּגִין דְּמִשְׁתַּתְּפֵי בַּהֲדַיְיהוּ דְּיִשְׂרָאֵל לְאַבְאָשָׁא לוֹן. וּבְגִין כָּךְ עָבִיד בְּהוּ דִּינָא וְאוֹבִיד לוֹן מֵעָלְמָא בְּלָא זִמְנָא. וְדָא הוּא דְּאַבְאִישׁ קַמֵּיהּ. וּבְגִין כָּךְ אַטְבַּע מִצְרָאֵי בְּיַמָּא. וְאוֹבִיד שַׂנְאֵיהוֹן דְּיִשְׂרָאֵל בִּימֵי יְהוֹשָׁפָט. וְכֵן כֻּלְהוּ. דְּהָא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל אִתְאֲבִידוּ בְּלָא זִמְנָא.","אֲבָל כַּד אִשְׁתְּלִים זִמְנָא דְּאוֹרִיךְ לוֹן וְלָא תָבוּ. כְּדֵין חֶדְוָה וְתוּשְׁבַּחְתָּא קַמֵּיהּ עַל דְּאִתְאֲבִידוּ מֵעָלְמָא. בַּר בְּזִמְנָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא. דְּאַף עַל גַּב דְּאִשְׁתְּלִים זִמְנָא דִּלְהוֹן דְּאַרְגִּיזוּ קַמֵּיהּ, לָא הֲוָה חֶדְוָה קַמֵּיהּ. וּמֵהַהוּא זִמְנָא לָא הֲוָה חֶדְוָה לְעֵילָא וְתַתָּא:","כִּי לְיָמִים עוֹד שִׁבְעָה אָנֹכִי מַמְטִיר עַל הָאָרֶץ אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְגו'. רַבִּי יְהוּדָה אָמַר הָנִי אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה מַאי עֲבִידְתַּיְיהוּ. אֶלָּא אַרְבָּעִים יוֹם לְאַלְקָאָה חַיָּיבֵי עָלְמָא וּכְתִיב, (דברים כ״ה:ג׳) אַרְבָּעִים יַכֶּנּוּ לֹא יוֹסִיף, לָקֳבֵל אַרְבַּע סִטְרֵי עָלְמָא לְכָל חַד עֲשָׂרָה. בְּגִין דְּבַּר נָשׁ מֵאַרְבַּע סִטְרֵי עָלְמָא אִתְבְּרֵי. וְעַל דָּא וּמָחִיתִי אֶת כָּל הַיְקוּם. וְאִצְטְרִיךְ אַרְבָּעִים לְאַלְקָאָה וּלְאִתְמְחֵי עָלְמָא."],[[0,"ר' אלעזר וכו'","ר\"א הלך אל רבי יוסי ברבי שמעון בן לקוניא חותנו. כיון שראה אותו, תקן לו שטיחים של מכסה על מוטות עץ, וישבו. אמר לו חותנו, אפשר ששמעת מאביך זה שכתוב, עשה ה' אשר זמם בצע אמרתו אשר צוה מימי קדם."],[1,"א\"ל וכו':","אמר לו הרי פירשוהו החברים \u0003בצע אמרתו,\u0004 שקרע לבוש היקר שלו, שנקרא פורפירא. \u0003אשר צוה מימי קדם,\u0004 פורפירא זו צוה אותה מאלו ימי קדם העליונים, היינו מהספירות דפרצוף עתיק הנקראות ימי קדם. וביום שנחרב בית המקדש קרע אותה, באשר פורפירא זו הוא הכבוד שלו ותיקון שלו, דהיינו המלכות הנקראת כבוד ה' והיא תיקונו, כי הוא מתתקן על ידה בהמוחין דהארת החכמה, (כנ\"ל בראשית א' דף ע\"ה אות ע' ד\"ה כמראה) \u0003וקרע אותה,\u0004 דהיינו שנסתלקו ממנה ט\"ס ראשונות ולא נשארה בה כי אם חלק העשירית ממנה."],[2,"א\"ל עשה וכו':","הקשה לו, עשה ה' אשר זמם, הכי דרכו של המלך לחשוב להרע לבניו עוד קודם שבאים לחטוא. והשיב לו, זה דומה, למלך שהיה לו כלי יקר ובכל יום היה מפחד עליו שלא ישבר, והיה מסתכל בו והיה ישר בעיניו. לימים בא הבן והכעיס את המלך, לקח המלך את כלי היקר ושבר אותו. זה שכתוב עשה ה' אשר זמם."],[3,"תא חזי וכו':","בוא וראה מיום שנבנה בית המקדש, היה הקב\"ה מסתכל בו, והיה חביב עליו מאד. והיה מפחד על ישראל שלא יחטאו ויחרב בית המקדש. וכן בכל פעם שהיה בא לבית המקדש, היה לובש פורפירא הזו. דהיינו שהיה מזדווג עם המלכות ואחר שגרמו החטאים והכעיסו את המלך, נחרב בית המקדש וקרע לאותה פורפירא. היינו שכתוב, עשה ה'אשר זמם בצע אמרתו."],[4,"האי אמרתו וכו':","אמרתו זו, שהיא המלכות, מתחילה היתה יושבת בראש אמיר, ומתעטר בה המלך עטרה לראשו, ואילן נאה לפניו, היינו אילן הנשמות מטרם שבאים לעולם. ועתה כשנחרב בית המקדש קרע אותה, דהיינו שנסתלקה ממנה ט' ספירות ראשונות ונשארה באור הנפש בלבד."],[4,"וכדין עציבו וכו':","ואז, כשנחרב בהמ\"ק, נעשה עצבות לפניו בבתים החיצונים בודאי, ולא בפנימים, כמ\"ש והן אראלים צעקו חוצה, דהיינו רק בחיצוניות."],[5,"ויקרא ה' צבאות וכו':","היינו רק בזמן שנחרב ביהמ\"ק, קרא לבכי ומספד, אבל בזמן אחר, אין שמחה לפני הקב\"ה, כבזמן שרשעי עולם והמכעיסים אותו נאבדים מהעולם, וז\"ש ובאבוד רשעים רנה, וכן בכל דור ודור, בעת שעושה דין ברשעי עולם, שמחה ורנה לפני הקב\"ה."],[6,"ואי תימא וכו':","ואם תאמר, הרי למדנו, שאין שמחה לפני הקב\"ה כשהוא עושה דין ברשעים. אלא בא וראה, בשעה שנעשה דין ברשעים שמחה ורנה לפניו על שנאבדו מהעולם, במה דברים אמורים כשהגיע הזמן שהמתין להם שיעשו תשובה, ולא שבו אליו מחטאם, אבל אם נעשה בהם הדין מטרם שהגיע זמנם, ועוד לא נשלם עונם, כמו שאתה אומר כי לא שלם עון האמורי עד הנה, דהיינו שעוד אפשר שיעשו תשובה, אז אין שמחה לפניו, ורע לפניו על שנאבדו."],[7,"ואי תימא וכו':","ואם תאמר, אם הוא מטרם שהגיע זמנם, למה עושה בהם דין, אלא הם גרמו רעה לעצמם, כי הקב\"ה לא היה עושה בהם דין מטרם שהגיע זמנם, אלא משום שנתחברו לישראל להרע אותם, משום זה עשה בהם דין והאביר אותם מהעולם לפני זמנם. ולכן רע לפניו להאבידם לפני זמנם, ומשום זה הטביע את המצרים בים, והאביד שונאיהם של ישראל בימי יהושפט, וכן כולם, כי בשביל שהריעו לישראל נאבדו לפני זמנם."],[8,"אבל כד וכו':","אבל כשנשלם הזמן שהמתין להם ולא שבו בתשובה, אז שמחה ורנה לפניו על שנאבדו מהעולם, חוץ בזמן שנחרב בית המקדש, שאע\"פ שכבר נשלם זמנם שהכעיסו לפניו, מכל מקום לא היה שמחה לפניו, ומעת ההוא ואילך, אין שמחה למעלה ולמטה."],[9,"כי לימים וכו':","רי\"א, ארבעים יום וארבעים לילה הללו מה ענינם. ומשיב, אלא ארבעים יום הוא להלקות בהם רשעי עולם, וכתוב ארבעים יכנו לא יוסיף כנגד ארבע רוחות העולם. שה\"ס חו\"ב תו\"מ, לכל אחד עשרה, שהם ארבעים, משום שהאדם נברא מארבע רוחות העולם. ועל זה אומה\"כ ומחיתי את כל היקום, וצריכים ארבעים, להלקות ולמחות העולם."]],[[0,"","רַבִּי אֶלְעָזָר הָלַךְ אֶל רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמִיו. כֵּיוָן שֶׁרָאָה אוֹתוֹ, הִתְקִין לוֹ שָׁטִיחַ שֶׁל כִּסּוּי בְּמוֹטוֹת שֶׁל עֵץ, וְיָשְׁבוּ. אָמַר לוֹ חָמִיו, אֶפְשָׁר שֶׁשָּׁמַעְתָּ מֵאָבִיךְ זֶה שֶׁכָּתוּב (איכה ב) עָשָׂה ה' אֲשֶׁר זָמָם בִּצַּע אֶמְרָתוֹ אֲשֶׁר צִוָּה מִימֵי קֶדֶם?"],[1,"","אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, בִּצַּע אֶמְרָתוֹ - שֶׁקָּרַע הָאַדֶּרֶת שֶׁלּוֹ. אֲשֶׁר צִוָּה מִימֵי קֶדֶם - שֶׁהֲרֵי אוֹתָהּ הָאַדֶּרֶת צִוָּה מֵאוֹתָם יָמִים רִאשׁוֹנִים עֶלְיוֹנִים, וּבַיּוֹם שֶׁחָרַב בֵּית הַמִּקְדָּשׁ קָרַע אוֹתָהּ, מִשּׁוּם שֶׁהָאַדֶּרֶת הַזּוֹ הִיא כְבוֹדוֹ וְתִקּוּנוֹ, וְקָרַע אוֹתָהּ."],[2,"","אָמַר לוֹ, עָשָׂה ה' אֲשֶׁר זָמָם, וְכִי מֶלֶךְ חוֹשֵׁב (קדם) לְהָרַע לְבָנָיו עַד שֶׁלֹּא יָבאוּ לַחֲ א!? אָמַר לוֹ, (משל) לְמֶלֶךְ שֶׁהָיָה לוֹ כְּלִי יָקָר, וּבְכָל יוֹם הָיָה פּוֹחֵד עָלָיו שֶׁלֹּא יִשָּׁבֵר וְהָיָה מִסְתַּכֵּל בּוֹ וּמָצָא חֵן בְּעֵינָיו. לְיָמִים בָּא בְּנוֹ וְהִרְגִּיז אֶת הַמֶּלֶךְ. לָקַח הַמֶּלֶךְ אוֹתוֹ כְּלִי יָקָר וְשָׁבַר אוֹתוֹ. זֶהוּ שֶׁכָּתוּב עָשָׂה ה' אֲשֶׁר זָמָם."],[3,"","בֹּא רְאֵה, מִיּוֹם שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּכֵּל בּוֹ וְחָבִיב עָלָיו הַרְבֵּה, וְהָיָה פּוֹחֵד עַל יִשְׂרָאֵל שֶׁיֶּחְטְאוּ וְיֵחָרֵב בֵּית הַמִּקְדָּשׁ. וְכָךְ בְּכָל פַּעַם שֶׁהָיָה בָּא אֵצֶל בֵּית הַמִּקְדָּשׁ, הָיָה לוֹבֵשׁ אוֹתָהּ אַדֶּרֶת. אַחַר שֶׁגָּרְמוּ הַחֲטָאִים וְהִרְגִּיזוּ לִפְנֵי הַמֶּלֶךְ, נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְקָרַע אוֹתָהּ הָאַדֶּרֶת (קרע אותה האדרת ונחרב בית המקדש). הַיְנוּ שֶׁכָּתוּב עָשָׂה ה' אֲשֶׁר זָמָם."],[4,"","בִּצַע אֶמְרָתוֹ וְגוֹ' (האמרתו הזו בתחלה ישבה בראש אמיר, והרי התעטרו עטרה לראש ואילן נאה לפניו, והיא מימי קדם ודאי, ואז עצבות לפניו בבתים החיצונים ודאי, (ישעיה לג) והן אראלם צעקו חצה,"],[5,"","(שם כב) ויקרא ה' אלהים צבאות ביום ההוא וגו'). הַיְנוּ בִּזְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ. אֲבָל בִּזְמַן אַחֵר אֵין חֶדְוָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ זְמַן שֶׁאוֹבְדִים רִשְׁעֵי הָעוֹלָם וְאוֹתָם שֶׁהִרְגִּיזוּ לְפָנָיו. זֶהוּ שֶׁכָּתוּב (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה. וְכֵן בְּכָל דּוֹר וְדוֹר שֶׁעוֹשֶׂה דִין בְּרִשְׁעֵי הָעוֹלָם, חֶדְוָה וְתִשְׁבַּחַת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁאֵין חֶדְוָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהוּא עוֹשֶׂה דִין בָּרְשָׁעִים אֶלָּא? בּא רְאֵה, בְּשָׁעָה שֶׁנַּעֲשֶׂה דִין בָּרְשָׁעִים, חֶדְווֹת וְתִשְׁבָּחוֹת לְפָנָיו עַל שֶׁנֶּאֶבְדוּ מֵהָעוֹלָם. וְהַדְּבָרִים הַלָּלוּ כְּשֶׁמַּגִּיעַ אוֹתוֹ זְמַן שֶׁהִמְתִּין לָהֶם וְלֹא שָׁבוּ אֵלָיו מֵחֲטָאֵיהֶם. אֲבָל אִם נַעֲשֶׂה בָהֶם דִּין עַד שֶׁלֹּא הִגִּיעַ זְמַנָּם, (ועד) שֶׁלֹּא נִשְׁלָם חֶטְאָם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית טו) כִּי לֹא שָׁלֵם עֲוֹן הָאֱמוֹרִי עַד הֵנָּה, אָז אֵין חֶדְוָה לְפָנָיו, וְרַע לְפָנָיו עַל שֶׁנֶּאֶבְדוּ."],[7,"","וְאִם תֹּאמַר, לָמָּה עוֹשֶׂה בָהֶם דִּין טֶרֶם שֶׁהִגִּיעַ זְמַנָּם? אֶלָּא הֵם גָּרְמוּ רַע לְעַצְמָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ עוֹשֶׂה דִין בְּטֶרֶם מַגִּיעַ זְמַנָּם, אֶלָּא מִשּׁוּם שֶׁמִּשְׁתַּתְּפִים עִם יִשְׂרָאֵל לְהָרַע לָהֶם, וְלָכֵן עוֹשֶׂה בָהֶם דִּין וּמְאַבְּדָם מֵהָעוֹלָם בְּלֹא הַזְּמַן. וְזֶהוּ שֶׁרַע לְפָנָיו. וְלָכֵן הִטְבִּיעַ מִצְרַיִם בַּיָּם וְהֶאֱבִיד שׂוֹנְאֵי יִשְׂרָאֵל בִּימֵי יְהוֹשָׁפָט, וְכֵן כֻּלָּם, שֶׁהֲרֵי מִשּׁוּם יִשְׂרָאֵל נֶאֶבְדוּ לִפְנֵי זְמַנָּם."],[8,"","אֲבָל כְּשֶׁהֻשְׁלַם הַזְּמַן שֶׁחִכָּה לָהֶם וְלֹא שָׁבוּ, אָז חֶדְוָה וְתִשְׁבַּחַת לְפָנָיו עַל שֶׁאָבְדוּ מֵהָעוֹלָם, פְּרָט לַזְּמַן שֶׁחָרַב בֵּית הַמִּקְדָּשׁ, שֶׁאַף עַל גַּב שֶׁהֻשְׁלַם הַזְּמַן שֶׁלָּהֶם שֶׁהִרְגִּיזוּ לְפָנָיו, לֹא הָיְתָה חֶדְוָה לְפָנָיו. וּמֵאוֹתוֹ זְמַן לֹא הָיְתָה חֶדְוָה לְפָנָיו לְמַעְלָה וּלְמַטָּה."],[9,"","כִּי לְיָמִים עוֹד שִׁבְעָה אָנֹכִי מַמְטִיר עַל הָאָרֶץ אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְגוֹ'. רַבִּי יְהוּדָה אָמַר, אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה הַלָּלוּ, מַה מַּעֲשֵׂיהֶם? אֶלָּא אַרְבָּעִים יוֹם לְהַלְקוֹת רִשְׁעֵי הָעוֹלָם, וְכָתוּב (דברים כה) אַרְבָּעִים יַכֶּנּוּ לֹא יֹסִיף, כְּנֶגֶד אַרְבָּעָה רוּחוֹת הָעוֹלָם, לְכָל אֶחָד עֲשָׂרָה. מִשּׁוּם שֶׁבֶּן אָדָם נִבְרָא מֵאַרְבָּעָה רוּחוֹת הָעוֹלָם, וְעַל זֶה וּמָחִיתִי אֶת כָּל הַיְקוּם. וְצָרִיךְ אַרְבָּעִים לְהַלְקוֹת וְלִמְחוֹת אֶת הָעוֹלָם."]]],[["רַבִּי יִצְחָק הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אָמַר לֵיהּ הַאי קְרָא (דקאמרי) דִּכְתִיב וַתִּשָּׁחֵת הָאָרֶץ לִפְנִי הָאֱלהִים. אִי בְּנֵי נָשָׁא חָטָאן אַרְעָא בְּמָּה. אָמַר לֵיהּ בְּגִין דִּכְתִיב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ כְּמָה דְּאִתְּמָר. כְּגַוְונָא דָא (ויקרא י״ח:כ״ה) וַתִּטְמָא הָאָרֶץ וָאֶפְקוֹד עֲוֹנָהּ עָלֶיהָ. אֶלָּא בְּנֵי נָשָׁא חָטָאן וְאִי תֵימָא אַרְעָא בְּמָּה, אֶלָּא עִקְּרָא דְאַרְעָא בְּנֵי נָשָׁא אִנּוּן. וְאִנּוּן מְחַבְּלִין אַרְעָא וְהִיא אִתְחַבָּלַת. וּקְרָא אוֹכַח דִּכְתִיב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ.","תָּא חֲזֵי, כָּל חֶטְאוֹי דְּבַר נָשׁ כֻּלְהוּ חַבָּלוּתָא דִילֵיהּ תַּלְיָין בִּתְשׁוּבָה. וְחֶטְאָה דְּאוֹשִׁיד זַרְעָא עַל אַרְעָא וּמְחַבְּלָא אָרְחֵיהּ וְאַפִּיק זַרְעָא עַל אַרְעָא, מְחַבִּיל לֵיהּ וּמְחַבִּיל אַרְעָא. וְעֲלֵיהּ כְּתִיב, (ירמיהו ב׳:כ״ב) נִכְתַּם עֲוֹנִךְ לְפָנַי. וּכְתִיב בֵּיהּ (תהילים ה׳:ה׳) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגוּרְךָ רָע. בַּר בִּתְשׁוּבָה סַגֵּי. וּכְתִיב, (בראשית ל״ח:ז׳) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי יְיָ וַיְמִיתֵהוּ יְיָ וְהָא אִתְּמָר.","אָמַר לֵיהּ אַמַּאי דָּאִין קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא בְּמַיָא וְלָא בְּאֶשָׁא וְלָא בְּמִלָּה אָחֳרָא. אָמַר לֵיהּ רָזָא הוּא דְּהָא אִנּוּן חַבִּילוּ אָרְחַיְיהוּ בְּגִין דְּמַיִין עִלָאִין וּמַיִין תַּתָּאִין לָא אִתְחַבָּרוּ דְּכַר וְנוּקְבָא כְּדְקָא יְאוּת. וּמַאן אִלֵּין מַיִּין עִלָּאִין בִּינָה. וּמַיִּין תַּתָּאִין מַלְכוּת. ה\"א עִלָּאָה ה\"א תַּתָּאָה. וְכַד אִנּוּן מְחַבְּלִין, אִסְתַּלַק י\"ו דְהוּא דְכַר, וְאִשְׁתָּאַר ה\"א בה\"א (ומיין במיין. מאן אנון דחבילו ארחייהו, כגוונא דא מיין דכורין ונוקבי. ועל דא אתדנו במיא במה דאנון חבו.","ומיין הוו רתיחן ופשטו משכא מנייהו כמה דחבילו ארחייהו במיין רתיחן. דינא לקבל דינא. הדא הוא דכתיב) נִבְקְעוּ כָּל מַעְיְינוֹת תְּהוֹם רַבָּה, הָא מַיִין תַּתָּאִין. וַאֲרוּבּוֹת הַשָּׁמַיִם נִפְתָּחוּ דָּא מַיִין עִלָּאִין. מַיִין עִלָּאִין וְתַתָּאִין.","רַבִּי חִיָּיא וְרַבִּי יְהוּדָה הֲווּ אָזְלֵי בְּאָרְחָא. וּמָטוּ לְגַבֵּי טוּרִין רַבְרְבָן וְאַשְׁכָּחוּ בֵּינֵי טוּרַיָא גַּרְמֵי בְּנֵי נָשָׁא דְּהֲווּ מֵאִנּוּן בְּנִי טוֹפָנָא. וּפָסְעוּ תְּלַת מְאָה פְּסִיעָן בְּגַרְמָא חָדָא. תְּוָוהוּ. אָמְרוּ הַיְינוּ דְּאָמְרוּ חַבְרָנָא דְּאִנּוּן לָא הֲווּ מִסְּתָּפֵי מִדִּינָא דְּקוּדְשָׁא בְּרִיךְ הוּא כְּמָה דִכְתִיב, (איוב כ״א:י״ד-ט״ו) וַיֹּאמְרוּ לָאֵל סוּר מִמֶּנּוּ וְדַעַת דְּרָכֶיךָ לֹא חָפָצְנוּ. מָה עַבְדוּ. הֲווּ סְתִימִין בְּרַגְלַיְיהוּ מַבּוּעֵי תְהוֹמָא. וּמַיִין נָפְקִין רְתִיחָן וְלָא יָכִילוּ לְמֵיקַם בְּהוּ, עַד דְּהֲווּ נִשְׁמָטִין וּנְפָלוּ בְּאַרְעָא וּמַיְיתִין:","וַיּוֹלֶד נֹחַ שְׁלשָׁה בָנִים וְגו'. אָמַר רַבִּי חִיָּיא לְרַבִּי יְהוּדָה תָּא וְאֵימָא לָךְ מִלֵּי דְּשָׁמַעְנָא בְּהַאי. מְתָל לְבַר נָשׁ דְּאָעִיל לְנוּקְבָא דִמְעָרְיָא (ד\"א איבא דמעהא) בְּזִמְנָא חָדָא. וְנָפְקֵי תְּרֵין אוֹ תְּלָתָא בְּנִין. (כל) חַד מִתְפָּרְשָׁא מֵאָחֳרָא בְּאָרְחוֹי בְּעוֹבָדוֹי. דָּא זַכָּאָה וְדָא חַיָּיבָא וְדָא בֵּינוֹנִי. אוּף הָכָא נָמֵי תְּלַת קִטְרֵי דְרוּחָא אָזְלִין וְשָׁטָאן וְאִתְכְּלִילָן בִּתְלַת עָלְמִין.","תָּא חֲזֵי, נִשְׁמָתָא נָפְקַאת וְאָעִיל בֵּין טוּרֵי פִּרוּדָא וְאִתְחַבַּר רוּחָא בְּנִשְׁמָתָא. נָחִית לְתַתָּא אִתְחַבַּר נֶפֶשׁ בְּרוּחַ וְכֻלְהוּ (אזלי ד\"א נחתין) וּמִתְחַבְּרִין דָּא עִם דָּא. אָמַר רַבִּי יְהוּדָה נֶפֶשׁ וְרוּחַ כְּלִילָן דָּא עִם דָּא. נִשְׁמְתָא שַׁרְיָא בְּאָרְחוֹי דְּבַר נָשׁ. (והאי) וְהִיא מְדוֹרָא טְמִירָא דְּלָא אִתְיְידַע אַתְרָהָא.","אֲתָא בַּר נָשׁ לְאִתְדַּכָּאָה, מְסַיְיעִין לֵיהּ בְּנִשְׁמְתָא קַדִּישָׁא וְדָכָאן לֵיהּ וּמְקַדְּשִׁין לֵיהּ וְאִקְרֵי קָדוֹשׁ. לָא זָכָה וְלָא אָתֵי לְאִתְדַּכָּאָה, תְּרֵין דַּרְגִּין פְּתִיחִין דְּאִנּוּן נֶפֶ\"שׁ וְרוּ\"חַ בֵּיהּ. נִשְׁמְתָא קַדִּישָׁא לֵית בֵּיהּ (סיועא דלעילא ודא כפום ארחיה). וְלָא עוֹד אֶלָּא דְּאִי יִסְתָּאַב מְסָאֲבִין לֵיהּ. וְסִיּוּעָא דִלְעֵילָא אַעֲדִיוּ מִינֵיהּ. מִכָּאן וּלְהָלְאָה כָּל חַד לְפוּם אָרְחֵיהּ.","\u0003תוֹסֶפְתָּא\u0004 קְטוּרֵי רָמָאי, דְּקַסְטוֹרֵי דְהוּסְטְרָא (ס\"א דההוא סטרא) אֲנַן פְּתִּיחָן עַיְינִין פְּתִּיחָן אוּדְנִין. קָל מִן קָלַיָא נָחִיתּ מֵעֵילָא לְתַּתָּא. מְתַּבַּר טּוּרִין וטִנָּרִין. מָאן אִנּוּן דְּחָמָאן וְלָא חָמָאן. אֲטִימִין אוּדְנִין. סְתִּימִין עַיְינִין. לָא חָמָאן ולָא שָׁמְעִין לָא יָדְעִין בְּסֻכְלְתָּנוּ, חַד דִּכְלִילָא בִּתְּרֵין בְּגַוויְיהוּ. דָּחְיָין לֵיהּ לְבַר.","אִנּוּן מִתְּדַּבְּקָן בֵין (ס\"א ביה) בְּאִנּוּן תְּרֵי, חַד אוּמָנָא דְּאוּמָנָא לָא שַׁרְיָא (ס\"א שווין) בְּגַוַּויְיהוּ. לָא עָאלִין בֵּין סִפְּרֵי קַדִּישִׁין. כָּל אִנּוּן דְּאוּמָנָא דָּא לָא שַׁרְיָא בְּגַוַויְיהוּ לָא אִכְתְּבוּ בְּסִפְּרֵי דָכְרָנַיָיא אִתְּמְחוּן מִסִפְּרָא דְחַיֵּי כְּמָא דְאַתְּ אָמֵר (תהילים ס״ט:כ״ט) יִמָּחוּ מִסֵפֶּר חַיִּים וְעִם צַּדִּיקִים אַל יִכָּתֵּבוּ."],[[0,"רבי יצחק וכו':","ר\"י היה מצוי לפני ר\"ש, אמר לו, מקרא זה שכתוב, ותשחת הארץ לפני האלקים. אם בני אדם חוטאים הארץ במה חטאת. א\"ל משום שכתוב כי השחית כל בשר את דרכו, כמו שכבר אמרנו (לעיל אות ל\"ט) כעין זה ותטמא הארץ ואפקוד עונה עליה. אלא בני אדם הם חוטאים, ואם תאמר, הארץ במה חוטאת, אלא עיקר הארץ הם בני אדם, והם משחיתים הארץ והיא נשחתת. והמקרא מוכיח שכתוב וירא אלקים וגו'."],[1,"ת\"ח כל וכו':","בוא וראה כל החטאים של האדם, וכל ההשחתה שלו, תלוים בתשובה. והחטאה של השופך זרע על הארץ, שמשחית דרכו ומוציא זרע על הארץ. משחית את עצמו ומשחית הארץ, ועליו כתוב, נכתם עונך לפני, וכתוב בו כי לא אל חפץ רשע אתה לא יגורך רע, דהיינו המוציא זרעו על הארץ שנקרא רע, לא יגור עוד עם הקב\"ה, כלומר, שלא יקבל תשובתו, חוץ בתשובה רבה. וכתוב ויהי ער בכור יהודה רע בעיני ה' וימיתהו ה', וכבר נתבאר."],[2,"א\"ל אמאי וכו':","אמר לו מפני מה דן הקב\"ה את העולם, היינו את דור המבול, במים, ולא באש ולא בדבר אחר. א\"ל סוד הוא, כי הם השחיתו דרכם, בזה, שמים עליונים ומים תחתונים לא נתחברו זכר ונקבה כראוי. כי כל מי שמשחית דרכו, הוא משחית כמו זה מים דכורין ונוקבין, כלומר שפוגם במ\"ד ומ\"ן העליונים, וגורם שלא יתחברו, ועל כן נדונו במים. במה שהם חטאו."],[3,"ומיין הוו וכו':","והמים היו רותחים, והפשיטו העור מהם, כמו שהשחיתו דרכם במים רותחים, דין כנגד דין, דהיינו שנפרע מהם מדה כנגד מדה. וז\"ש \u0003נבקעו כל מעיינות תהום רבה\u0004 זה מים תחתונים. \u0003וארובות השמים נפתחו,\u0004 זה מים עליונים הרי שלקו ע\"י מים עליונים ותחתונים."],[4,"רבי חייא וכו':","ר\"ח ור\"י היו הולכים בדרך, והגיעו אל הרים הגדולים, ומצאו בין ההרים עצמות בני אדם, שהיו מאותם של בני המבול. ופסעו שלש מאות פסיעות בתוך עצם אחד. תמהו ואמרו. היינו שאמרו החברים, שהם לא היו יראים מדינו של הקב\"ה, כמ\"ש, ויאמרו לאל סור ממנו ודעת דרכיך לא חפצנו. מה עשו, היו סותמים עם רגליהם את מעיינות התהום אבל המים יצאו רותחים, ולא יכלו לעמוד בהם, עד שהיו נשמטים ונופלים על הארץ ומתים."],[5,"ויולד נח וכו':","אר\"ח לר\"י, בוא ואומר לך דברים ששמעתי בזה. משל לבן אדם שהכניס לנוקביה פרי הבטן בפעם אחת, ויצאו ב' או ג' בנים, שאחד נבדל מחברו, בדרכיו ובמעשיו: אחד הוא צדיק ואחד הוא רשע, ואחד הוא בינוני."],[5,"אוף הכא וכו':","אף כאן גם כן, ג' קשרי הרוח הולכים ומעופפים ונכללים בשלשה עולמות. שהם בריאה יצירה עשיה. פירוש. כי הוקשה לו מאחר שפירש לעיל באות כ\"ז אשר ויולד נח שלשה בנים, ה\"ס המוחין הבאים בג' הקוין, הנמשכים מג' הנקודות חולם שורק חירק, בסו\"ה ונוזלים מתוך בארך. ע\"ש בהסולם, א\"כ היה צריך להוליד ממוחין הללו רק בן אחד, ולמה הם ג', ולא עוד, אלא שנבדלים כל כך אחד מחברו, אשר שם, היה צדיק, וחם, היה רשע, שכתוב עליו וירא חם אבי כנען את ערות אביו וגו'. וז\"ש \u0003מתל לבר נש וכו',\u0004 אף כאן, אע\"פ כשהיו בנוקבא דאצילות היו שלשתם רק מוח אחד, בסוד ג' קוין שבו, מ\"מ כשנולדו ויצאו משם, באו לג' עולמות בי\"ע דפרודא, ונתחלקו שם ג' הקוין, שה\"ס ג' קשרי הרוח, זה מזה, המכונים נשמה רוח נפש, קו ימין הוא נשמה. בבריאה, קו שמאל הוא רוח ביצירה, קו אמצעי הוא נפש בעשיה. כי קו האמצעי הוא למטה מקו שמאל. וז\"ש \u0003תלת קטרי דרוחא אזלין ושטאן ואתכלילן בג' עלמין,\u0004 כי אחר שיצאו מאצילות ונכללו בג' עולמות בי\"ע נפרדו ונחלקו מחמתם זה מזה, ונעשו על ידיהם ג' בנים, שה\"ס נשמה רוח נפש, והם שם חם ויפת. אמנם בחינת הרוח דהיינו קו השמאל, שהוא חם, עוד לא היה נתקן אז כראוי, וע\"כ היה חם רשע, ויפת להיותו מכריע בין שם לחם נבחן לבינוני."],[6,"ת\"ח נשמתא וכו'","בוא וראה, הנשמה יוצאת מזו\"ן דאצילות, ונכנסת בין הרי הפירוד, לבי\"ע, ונתחבר הרוח בהנשמה, ויורדת יותר למטה, נתחבר הנפש ברוח, וכולם הולכים ומתחברים זה בזה. פירוש. כי הגם שהמוחין נפרדים לג' מחמת יציאתם לבי\"ע דפרודא, מ\"מ יש להם עוד חיבור זה בזה, והוא מטעם. כי בעודה בזו\"ן דאצילות, יש לה כח\"ב תו\"מ דכלים ונרנח\"י דאורות. וכשיוצאת לג' עלמין דפרודא נעשתה לו\"ק: והג' קוין שבה נפרדים זה מזה. ו\"ק דקו ימין, הוא נשמה, ובאה בבריאה. ו\"ק דקו שמאל הוא רוח ובא ליצירה. ו\"ק דקו אמצעי הוא נפש ובאה לעשיה, והג\"ר דאורות דכל אחד נשארות בעולם העליון ממנו. והבינה ותו\"מ דכלים דכל אחד נופלים להעולם שלמטה ממנו. ונמצא כשהנשמה באה בבריאה יורדים בינה ותו\"מ דנשמה, ומתלבשים בהרוח שביצירה, שהוא מדרגה התחתונה, ונעשה בזה חיבור בין הרוח להנשמה. וז\"ש \u0003נשמתא נפקאת ואעיל בין טורי פרודא,\u0004 דהיינו שבאה לבריאה דפרודא, \u0003ואתחבר רוחא בנשמתא,\u0004 כי בינה ותו\"מ דנשמה ירדו ונתלבשו ברוח שביצירה, ועי\"ז נתחברו. \u0003נחית לתתא\u0004 דהיינו ליצירה, \u0003אתחבר נפש ברוח\u0004 כי בינה ותו\"מ דרוח שביצירה נופלים ומתלבשים בהנפש שבעשיה, ועי\"ז נתחברו. \u0003וכלהו אזלין ומתחברין דא עם דא\u0004 דהיינו כל הג', הנשמה ברוח ורוח בנפש."],[6,"אמר ר' יהודה וכו',","נפש ורוח כלולים זה בזה, בעת שנולדים בעולם. ואין נפש בלי רוח, אכן הנשמה שוררת בדרכיו של האדם, כלומר, שאינה נולדה ביחד עם הנפש רוח, אלא שהאדם צריך להמשיך אותה, ע\"י שילך בדרך הישר והטוב. והיא במדור נעלם שלא נודע מקומה. כי הנשמה נולדת בו\"ק, שהיא נפש רוח, והג\"ר נשארים בהנוקבא דאצילות (כנ\"ל בדבור הסמוך) הנעלמת מדרי בי\"ע."],[7,"אתא בר נש וכו':","אם האדם בא לטהר, עוזרים אותו עם נשמה קדושה, ומטהרים אותו ומקדשים אותו ונקרא קדוש. ואם לא זכה ואינו בא לטהר, רק ב' מדרגות פתוחים לו, שהם נפש ורוח, ונשמה קדושה אין לו. ולא עוד אלא אם בא לטמא מטמאים אותו, והוסר ממנו עזרה עליונה. מכאן ואילך כל אחד לפי דרכיו. כלומר אם עושה תשובה ובא לטהר, שוב עוזרים לו. ואין לשאול. הרי כשהאדם נולד אין לו רק נפש מסטרא דבעירי דכיא. (כמ\"ש בזהר משפטים צ\"ד: בסולם אות י\"א) והענין הוא, כי הרוח כלול תמיד בנפש, כמ\"ש כאן. וא\"כ יש לו נפש רוח בעת שנולד. אבל נשמה למדרגה זו דבעירי דכיא, הוא לפי מעשיו, וכן הוא בכל מדרגה."],[8,"קטורי רמאי דקסטורי דקוסטרא אנן וכו'","קשרים רמים של מצודת המצודות אנו, קטורי פירוש נר\"ן, המכונים ג' קטרין. כלומר הנר\"ן שלנו מקושרים בקו האמצעי שהיא מצודה חזקה מכל המצודות כלפי הס\"א. ע\"כ פתוחים העינים ופתוחים האזנים, כלומר יש לנו חו\"ב המכונים עינים ואזנים, כי קול מן הקולות, יורד ממעלה למטה משבר הרים וסלעים. כלומר קו האמצעי הנקרא קול, שהוא דעת הכולל ג' קולות חב\"ד דדעת, ורק קול אחד יורד ומאיר ממעלה למטה ומשבר כל הקליפות החזקות הנק' הרים וסלעים. אבל ב' קולות העליונים. שהם חו\"ב דדעת אינם נמשכים למטה, \u0003מאן אינון דחמאן ולא חמאן וכו',\u0004 מי הם הרואים ואינם רואים, ונעשו אטומי אזנים ושתומי עינים, שאינם רואים, אינם שומעים, ואינם יודעים להשכיל את האחד הכלול ביניהם בהשנים, דוחים אותם לחוץ. פירוש, משום שאינם יודעים להשכיל ולהמשיך את האחד הכלול בשנים, שהוא קו האמצעי, ע\"כ נעשו אטומי אזנים ושתומי עינים, דהיינו שאינם יכולים לקבל המוחין הקדושים של חכמה הנק' עינים ושל בינה הנקראים אזנים. ואינם רואים ואינם שומעים, ולכן דוחים אותם לחוץ מהקדושה."],[9,"אינון מתדבקן ביה באינון תרי:","מתדבקים באלו השנים, דהיינו בב' הקוין ימין ושמאל שהם חכמה ובינה, \u0003חד, אומנא דאומנא לא שריא בגווייהו\u0004 וכו', האחד, שהוא קו אמצעי, והוא, אומן האומנים, שבו תלוים כל המוחין, הוא אינו שורה ביניהם, לכן אינם נכנסים בין הספרים הקדושים. כי כל אלו, שאומן הזה, קו האמצעי, אינו שורה בתוכם אינם נכתבים בספרי הזכרונות, כלומר, שאינם מקבלים המוחין הגדולים דבינה, הנקראים ספר זכרון וספר החיים. וע\"כ, נמחים מספר החיים, שאין להם חלק שם. כמו שאתה אומר, ימחו מספר החיים ועם צדיקים אל יכתבו."]],[[0,"","רַבִּי יִצְחָק הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ פָּסוּק זֶה (שאמרו) שֶׁכָּתוּב וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. אִם בְּנֵי אָדָם חָטְאוּ - הָאָרֶץ בַּמָּה חָטְאָה? אָמַר לוֹ, מִשּׁוּם שֶׁכָּתוּב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, כְּמוֹ שֶׁנֶּאֱמַר. כְּמוֹ זֶה, (ויקרא יח) וַתִּטְמָא הָאֶרֶץ וָאֶפְקֹד עֲונָהּ עָלֶיהָ. אֶלָּא בְּנֵי אָדָם חָטְאוּ. וְאִם תֹּאמַר, הָאָרֶץ בַּמֶּה? אֶלָּא עִקַּר הָאָרֶץ הֵם בְּנֵי הָאָדָם, וְהֵם מַשְׁחִיתִים אֶת הָאָרֶץ וְהִיא נִשְׁחֶתֶת, וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ."],[1,"","בֹּא רְאֵה, כָּל חֲטָאֵי הָאָדָם כֻּלָּם, הַשְׁחָתָתָם תְּלוּיָה בִּתְשׁוּבָה. וְהַחֵטְא שֶׁל שׁוֹפֵךְ זֶרַע עַל הָאָרֶץ וּמַשְׁחִית דַּרְכּוֹ וּמוֹצִיא זֶרַע עַל הָאָרֶץ - מַשְׁחִית אוֹתוֹ וּמַשְׁחִית אֶת הָאָרֶץ, וְעָלָיו כָּתוּב (ירמיה ב) נִכְתַּם עֲונֵךְ לְפָנַי, וְכָתוּב בּוֹ (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. פְּרָט לִתְשׁוּבָה גְדוֹלָה. וְכָתוּב (בראשית לח) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה' וַיְמִיתֵהוּ ה', וַהֲרֵי נִתְבָּאֵר."],[2,"","אָמַר לוֹ, לָמָּה דָן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם בְּמַיִם וְלֹא בְּאֵשׁ וְלֹא בְּדָבָר אַחֵר? אָמַר לוֹ, סוֹד הוּא, שֶׁהֲרֵי הֵם הִשְׁחִיתוּ דַרְכָּם בִּשְׁבִיל שֶׁמַּיִם עֶלְיוֹנִים וּמַיִם תַּחְתּוֹנִים לֹא הִתְחַבְּרוּ זָכָר וּנְקֵבָה כָּרָאוּי. (ומי הם המים העליונים? בינה, ומים תחתונים מלכות, ה\"א עליונה ה\"א תחתונה, וכאשר הם משחיתים, נסתלק י\"ו, שהוא זכר, ונשאר ה\"א בה\"א ומים במים). מַה הֵם הִשְׁחִיתוּ דַרְכָּם, כְּמוֹ זֶה מַיִם זְכָרִיִּים וּנְקֵבִיִּים. וְעַל זֶה נִדּוֹנוּ בְּמַיִם, בְּמַה שֶּׁהֵם חָטְאוּ."],[3,"","וְהַמַּיִם הָיוּ רוֹתְחִים וּפוֹשְׁטִים מֵהֶם אֶת הָעוֹר, כְּמוֹ שֶׁהִשְׁחִיתוּ דַרְכָּם בְּמַיִם רוֹתְחִים. דִּין כְּנֶגֶד דִּין. זֶהוּ שֶׁכָּתוּב נִבְקְעוּ כָּל מַעְיְנוֹת תְּהוֹם רַבָּה. הֲרֵי מַיִם תַּחְתּוֹנִים. וַאֲרֻבֹּת הַשָּׁמַיִם נִפְתָּחוּ - זֶה מַיִם עֶלְיוֹנִים. מַיִם עֶלְיוֹנִים וְתַחְתּוֹנִים."],[4,"","רַבִּי חִיָּיא וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהִגִּיעוּ לְהָרִים גְּדוֹלִים, וּמָצְאוּ בֵּין הֶהָרִים עַצְמוֹת בְּנֵי אָדָם שֶׁהָיוּ מֵאוֹתָם בְּנֵי הַמַּבּוּל, וּפָסְעוּ שְׁלֹשׁ מֵאוֹת פְּסִיעוֹת בְּעֶצֶם אַחַת. תָּמְהוּ. אָמְרוּ, הַיְנוּ מַה שֶּׁאָמְרוּ חֲבֵרֵינוּ שֶׁהֵם לֹא הָיוּ פּוֹחֲדִים מִדִּין הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁכָּתוּב (איוב כא) וַיֹּאמְרוּ לָאֵל סוּר מִמֶּנּוּ וְדַעַת דְּרָכֶיךְ לֹא חָפָצְנוּ. מֶה עָשׂוּ? הָיוּ סוֹתְמִים בְּרַגְלֵיהֶם אֶת מַעְיְנוֹת הַתְּהוֹם, וּמַיִם רְתוּחִים יוֹצְאִים וְלֹא יָכְלוּ לַעֲמֹד בָּהֶם, עַד שֶׁהָיוּ נִשְׁמָטִים וְנוֹפְלִים בָּאָרֶץ וּמֵתִים."],[5,"","וַיּוֹלֶד נֹחַ שְׁלֹשָׁה בָנִים וְגוֹ'. אָמַר רַבִּי חִיָּיא לְרַבִּי יְהוּדָה, בּא וְאֹמַר לְךְ דְּבָרִים שֶׁשָּׁמַעְתִּי בָּזֶה. מָשָׁל לְאָדָם שֶׁמַּכְנִיס לִנְקֵבָה שֶׁמִּתְעַבֶּרֶת (ד\"א פרי מעיה) בְּפַעַם אַחַת, וְיָצְאוּ שְׁנַיִם אוֹ שְׁלֹשָׁה בָנִים. (כל) אֶחָד נִפְרָד מֵאַחֵר בִּדְרָכָיו בְּמַעֲשָׂיו. זֶה צַדִּיק וְזֶה רָשָׁע וְזֶה בֵּינוֹנִי. אַף גַּם כָּאן שְׁלֹשָׁה קְשָׁרִים שֶׁל רוּחַ הוֹלְכִים וְשָׁטִים וְנִכְלָלִים בִּשְׁלֹשָׁה עוֹלָמוֹת."],[6,"","בֹּא רְאֵה, נְשָׁמָה יוֹצֵאת וְנִכְנֶסֶת בֵּין הָרֵי פֵרוּד, וּמִתְחַבֶּרֶת הָרוּחַ בַּנְּשָׁמָה. יוֹרֶדֶת לְמַטָּה, מִתְחַבֶּרֶת הַנֶּפֶשׁ בָּרוּחַ, וְכֻלָּם (הולכים ד\"א יורדים) וּמִתְחַבְּרִים זֶה עִם זֶה. אָמַר רַבִּי יְהוּדָה, נֶפֶשׁ וְרוּחַ כְּלוּלִים זֶה עִם זֶה. הַנְּשָׁמָה שׁוֹרָה בִּדְרָכָיו שֶׁל בֶּן אָדָם, (וזה) וְהוּא מָדוֹר נִסְתָּר שֶׁלֹּא נוֹדָע מְקוֹמוֹ."],[7,"","בָּא בֶּן אָדָם לְהִטָּהֵר - מְסַיְּעִים לוֹ בִּנְשָׁמָה קְדוֹשָׁה וּמְטַהֲרִים אוֹתוֹ וּמְקַדְּשִׁים אוֹתוֹ וְנִקְרָא קָדוֹשׁ. לֹא זָכָה וְלֹא בָא לְהִטָּהֵר - שְׁתֵּי דְרָגוֹת פּוֹתְחִים, שֶׁהֵם נֶפֶשׁ וְרוּחַ בּוֹ. אֵין בּוֹ נְשָׁמָה קְדוֹשָׁה (סיוע שלמעלה, וזה כפי דרכו). וְלֹא עוֹד, אֶלָּא שֶׁאִם יִטְמָא - מְטַמְּאִים אוֹתוֹ. וְהַסִּיּוּעַ שֶׁלְּמַעְלָה מְסִירִים מִמֶּנּוּ. מִכָּאן וָהָלְאָה כָּל אֶחָד לְפִי דַרְכּוֹ."],[8,"","קִשּׁוּרִים רָמִים שֶׁל הֵיכְלֵי הַהֵיכָלוֹת (של אותו צד) אָנוּ פְּתוּחֵי עֵינַיִם, פְּתוּחֵי אָזְנַיִם. קוֹל מֵהַקּוֹלוֹת יוֹרֵד מִלְמַעְלָה לְמַטָּה, מְשַׁבֵּר הָרִים וּסְלָעִים. מִי הֵם שֶׁרוֹאִים וְלֹא רוֹאִים? אֲטוּמֵי אָזְנַיִם, סְתוּמֵי עֵינַיִם, לֹא רוֹאִים וְלֹא שׁוֹמְעִים, לֹא יוֹדְעִים בַּשֵּׂכֶל, אֶחָד שֶׁכָּלוּל בִּשְׁנַיִם בְּתוֹכָם. דּוֹחִים אוֹתָם הַחוּצָה."],[9,"","הֵם נִדְבָּקִים בֵּין (ס\"א בו) בְּאוֹתָם שְׁנַיִם, הָאֶחָד אֻמַּן הָאָמָּנִים לֹא שׁוֹרֶה (ס\"א שמים) בְתוֹכָם. לֹא נִכְנָסִים בֵּין סְפָרִים קְדוֹשִׁים. כָּל אֵלּוּ שֶׁל אֻמָּן זֶה לֹא שׁוֹרֶה בְתוֹכָם, לֹא נִכְתְּבוּ בְּסֵפֶר הַזִּכְרוֹנוֹת וְנִמְחִים מִסֵּפֶר הַחַיִּים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סט) יִמָּחוּ מִסֵּפֶר חַיִּים וְעִם צַדִּיקִים אַל יִכָּתֵבוּ."]]],[["ווי לוֹן כַּד יִפְּקוּן מֵהַאי עָלְמָא ווי לוֹן (לחייהון). מַאן יִתְּבַּע לוֹן כַּד יִתְּמַסְרוּן בִּידָא דְדוּמָה ויתּוֹקְדוּן בְּנוּרָא דְּדָלִיק וְלָא יִפְּקוּן מִנֵּיהּ בַּר בְּרֵישׁ יַרְחֵי ושַׁבַּתֵּי כְּמָא דְאַתְּ אָמֵר, (ישעיהו ס״ו:כ״ג) והָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּתּ בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲווֹתּ לְפָּנַי אָמַר יְיָ. לְבָתַּר כָּרוֹזָא דְּבִסְטַר צָּפּוֹן אַכְרִיז עֲלַיְיהוּ ואָמַר (תהילים ט׳:י״ח) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה וְגו'. כַּמָּה חֲבִילֵי טְרִיקִין אִתְּכַּנְשׁוּ עֲלַיְיהוּ בְּאַרְבַּע סִטְרִין. אֶשָׁא מְלַהֲטָא בְּגֵי בֶּן הִנֹּם.","תְּלַתּ זִמְנִין בְּיוֹמָא מִתְּפַּקְדָן (ס\"א מתוקדן). וְלָא עוֹד אֶלָּא בְּזִמְנָא דְיִשְׂרָאֵל אֲתִּיבוּ בְּקוֹל רָם אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךָ, קוּדְשָׁא בְּרִיךָ הוּא אִתְּמְלֵי רַחֲמִין וְחַיִיס עַל כֹּלָּא. ורָמִיז לְמַלְאָכָא דִּמְמַנָּא עַל תַּרְעֵי דְּגֵיהִנֹּם סמריאל שְׁמֵיהּ וּתְּלַתּ מַפְּתְּחָן בִּידֵיהּ וּפְּתַּח תְּלַתּ תַּרְעִין דְּבִסְטַר מַדְבְּרָא וְחָמָאן נְהוֹרָא דְּהַאי עָלְמָא. אֲתָּא תְּנָנָא דְנוּרָא וסָתִּים אוֹרְחִין.","כְּדֵין תְּלַתּ מְמַנָּן דִּתְּחוֹתּ יְדַיְיהוּ תְּלַתּ מַגְרוֹפִּין מְנַשְׁבָן בִּידַיְיהוּ ואֲתִּיבוּ תְּנָנָא לְאַתְּרַיְיהוּ ורַוְוחִין לוֹן שַׁעֲתָּא וּפַּלְגוּתּ שַׁעֲתָּא. וּלְבָתַּר תַּיְיבִין לְאֶשַׁיְיהוּ. וְכֵן תְּלַתּ זִמְנִין בְּיוֹמָא וּבְכָל זִמְנִין דְּאָמְרֵי יִשְׂרָאֵל אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךָ וכוּ' אִנּוּן רַוְוחִין לוֹן. זַכָּאִין אִנּוּן צַּדִּיקַיָיא דְּאוֹרְחֵיהוֹן מְנַהֲרָא בְּהַהוּא עָלְמָא לְכָל סִטְרִין כְּמָא דְאַתְּ אָמֵר, (משלי ד׳:י״ח) ואוֹרַח צַּדִּיקִים כְּאוֹר נוֹגַהּ הוֹלֵךָ ואוֹר עַד נְכוֹן הַיּוֹם (עד כאן לשון התוספתא):","רַבִּי אַבָּא אָמַר, בַּגֵּיהִנָּם אִית מְדוֹרִין עַל מְדוֹרִין תִּנְיָינִין תְּלִיתָאִין עַד שֶׁבַע. וְהָא אוּקְמוּהָ חַבְרַיָיא. וְזַכָּאִין אִנּוּן צַדִּיקַיָא דְּאִנּוּן מִסְתַּמְּרִין מֵחוֹבֵי חַיָּיבַיָא וְלָא אָזְלֵי בְּאָרְחַיְיהוּ וְלָא מִסְתָּאֲבֵי בְּהוּ. וְכָל מַאן דְּאִסְתָּאַב כַּד אָזִיל לְהַהוּא עָלְמָא, נָחִית לַגֵּיהִנֹּם. וְנָחִית עַד מְדוֹרָא תַּתָּאָה.","וּתְרֵין מְדוֹרִין אִנּוּן דִּסְמִיכִין דָּא עִם דָּא שְׁאוֹל וַאֲבַדּוֹן. מָאן דְּנָחִית לִשְׁאוֹל דַּיְינִין לֵיהּ תַּמָּן וּמְקַבֵּל עָנְשֵׁיהּ וּסְלִיקוּ לֵיהּ לִמְדוֹרָא אָחֳרָא עִלָּאָה. וְכֵן דַּרְגָּא בָּתַר דַּרְגָּא עַד דְּאִנּוּן סָלְקִין לֵיהּ. אֲבָל מָאן דְּנָחִית לַאֲבַדּוֹן לָא סָלְקִין לֵיהּ לְעָלְמִין. וּבְגִין כָּךְ אִקְרֵי אֲבַדּוֹן דְּהָא אָבִיד הוּא מִכֹּלָּא.","תָּא חֲזֵי נֹחַ זַכָּאָה, הֲוָה אַתְרֵי בִּבְנֵי דָרֵיהּ וְלָא הֲווּ שָׁמְעֵי לֵיהּ. עַד דְּקוּדְשָׁא בְּרִיךְ הוּא אַיְיתֵי עֲלַיְיהוּ דִינָא דְּגֵיהִנֹּם. מַאי דִינָא דְּגֵיהִנֹּם אֶשָׁא וְתַלְגָא. מַיָיא וְאֶשָׁא. דָּא צְנִינָא וְדָא רְתִיחָא. וְכֻלְהוּ בְּדִינָא דְּגֵיהִנֹּם אִתְדָּנוּ וְאִתְאֲבִידוּ מֵעָלְמָא.","וּלְבָתַר אִתְקְיַּים עָלְמָא כְּדְקָא חָזֵי לֵיהּ. וְעָאל נֹחַ בַּתֵּבָה וְאָעִיל בָּהּ כָּל זִינָא וְזִינָא (ד\"א מבריין) דְּעָלְמָא. וַדַּאי נֹחַ עֵץ עוֹשֶׂה פְּרִי הֲוָה. וְנָפְקוּ מִן תֵּבָה כָּל זְיָינֵי עָלְמָא כְּגַוְונָא דִלְעֵילָא.","תָּא חֲזֵי, כַּד הַאי עֵץ עוֹשֶׂה פְּרִי אִתְחַבַּר בְּעֵץ פְּרִי כָּל אִנּוּן זַיְינִין דִּלְעֵילָא חֵיוָון רַבְרְבָן וּזְעֵירָן וְכַמָּה זַיְינִין וְכָל חַד לְזִינֵיהּ כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:כ״ה) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. כְּגַוְונָא דָא נֹחַ בַּתֵּבָה. וְכֻלְהוּ נָפְקוּ מִן תֵּיבוּתָא וְאִתְקְיַּים עָלְמָא כְּגַוְונָא דִלְעֵילָא. וּבְגִינֵי כָךְ נֹחַ אִישׁ הָאֲדָמָה אִקְרֵי. נֹחַ אִישׁ צַדִּיק אִקְרֵי וְהָא אוּקְמוּהָ.","רַבִּי חִיָּיא אָמַר תְּלַת מְאָה שְׁנִין עַד לָא אָתֵי טוֹפָנָא הֲוָה נֹחַ אַתְרֵי בְּהוּ עַל עוֹבָדֵיהוֹן וְלָא הֲווּ שָׁמְעִין לֵיהּ. עַד דְקוּדְשָׁא בְּרִיךְ הוּא אַשְׁלִים זִמְנָא דְּאוֹרִיךְ לוֹן וְאִתְאֲבִידוּ מֵעָלְמָא. תָּא חֲזֵי, מַה כְּתִיב לְעֵילָא וַיְהִי כִּי הֵחֵל הָאָדָם לָרוֹב עַל פְּנֵי הָאֲדָמָה וּבָנוֹת יֻלְדוּ לָהֶם. וְהֲווּ אָזְלִין עַרְטִילָאִין לְעֵינֵיהוֹן דְּכֹלָּא. מַה כְּתִיב, (בראשית ו׳:ב׳) וַיִּרְאוּ בְּנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם וְגו'. וְדָא הֲוָה יְסוֹדָא וְעִקָּרָא לְמֵיגַד בְּחוֹבֵיהוֹן עַד דְּגָרִים לוֹן לְאִשְׁתֵּצָאָה מֵעָלְמָא. וּבְגִין כָּךְ אִתְמַשְׁכָאן בָּתַר יֵצֶר הָרָע וּבְגִזְעוֹי וְשָׁרְשׁוֹי. וְדָחוּ מְהֵימְנוּתָא קַדִּישָׁא מִבֵּינַיְיהוּ. וְאִסְתָּאֲבוּ (נ\"א ואיתאבידו) כְּמָה דְּאִתְּמָר. בְּגִין כָּךְ קֵץ כָּל בָּשָׂר בָּא לְפָנַי, לַאֲלָפָא קָטֵיגוֹרְיָא עֲלַיְיהוּ:","וַיֹּאמֶר אֱלֹהִים אֶל נֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. (אהדרנא למלה קדמאה קץ כל בשר בא לפני. בא לפני ודאי בגין דאנון גרמו). רַבִּי יְהוּדָה פָּתַח (תהילים ל״ט:ה׳) הוֹדִיעֵנִי יְיָ קִצִּי וּמִדַּת יָמַי מָה הִיא אֵדְעָה מֶה חָדֵל אָנִי. אָמַר (לעיל נד א) דָּוִד קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, תְּרֵין קִצִּין אִנּוּן, חַד לְיָמִינָא וְחַד לִשְׂמָאלָא, וְאִנּוּן תְּרֵין אוֹרְחִין לְמֵיהַךְ בְּהוּ בְּנֵי נָשָׁא לְהַהוּא עָלְמָא. קֵץ לְיָמִינָא דִּכְתִיב, (דניאל יב) לְקֵץ הַיָּמִין, וְקֵץ לִשְׂמָאלָא דִּכְתִיב, (איוב כ״ח:ג׳) קֵץ שָׂם לַחשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר (אבן אופל וצלמות. מאי ולכל תכלית הוא חוקר, מאן הוא חוקר. אלא ההוא קץ לשמאלא דמחשיך אפיהון דברייתא) מַאי וּלְכָל תַּכְלִית, בְּזִמְנָא דְדִינָא שָׁרְיָא עַל עָלְמָא לְשֵׁיצָאָה אֶבֶן אוֹפֶל וְצַלְמָוֶת. קֵץ שָׂם לַחשֶׁךְ. דָּא מַלְאַךְ הַמָוֶת, דָּא נָחָשׁ, קֵץ כָּל בָּשָׂר, קֵץ שָׂם לַחשֶׁךְ, דְהָא מִסִטְרָא דְהִתּוּכָא דְדַהֲבָא קָאָתֵי. וּלְכָל תַּכְלִית בְּזִמְנָא דְדִינָא שָׁרְיָא עַל עָלְמָא הוּא חוֹקֵר לְמֶהוֵי קַטֵיגוֹרְיָא לְעָלְמָא לְאַחְשָׁכָא אַפֵּיהוֹן דִּבְּרַיְיתָא וְכוּ'."],[[0,"ווי לון וכו':","ווי להם כאשר יצאו מעוה\"ז, מי ידרוש ויבקש בעדם, כאשר ימסרו בידי המלאך דומה וישרפו באש דולק. ולא יצאו משם, חוץ בר\"ח ושבת, כמש\"ה, והיה מדי חודש וגו'. לאחר, השבת ור\"ח, כרוז מכריז עליהם מצד צפון, ואומר, ישובו רשעים לשאולה וגו'. וכמה מלאכי חבלה מתאספים ובאים עליהם. בארבע רוחות לוהט האש בגי בן הנם. דהיינו להעניש הרשעים, שפגמו בד' בחינות, חו\"ב תו\"מ."],[1,"תלת זמנין ביומא מתפקדן וכו',","ג' פעמים ביום נפקדים, להקל על עונשם, והיינו בעת ג' זווגי זו\"ן שבג' התפלות. כמ\"ש להלן. ולא עוד אלא בשעה שישראל אומרים אמן יהא שמיה רבא וכו' בקול רם, נעשה זווג למעלה, והקב\"ה מתמלא רחמים, והוא חס על הכל. ורומז להמלאך הממונה על שערי גיהנם, ששמו \u0003סמריאל,\u0004 וג' מפתחות בידו, ופותח ג' שערים שבצד המדבר, והם רואים האור של עוה\"ז. ובא עשן של אש וסותם דרכי האור."],[1,"","פירוש. כי נתבאר לעיל (בראשית ב' דף קל\"ו אות רט\"ו ד\"ה ויטול רשות) שנטילת רשות ופיוסא נוהג בכל זווג זו\"ן שפירושו, שז\"א ממשיך בתחילת הזווג מהארת הקו שמאל, בסוד שמאלו תחת לראשי. ואח\"כ מזדווג עמה בשליטת הימין. עש\"ה. ונמצא שבשליטת קו שמאל, הוא רומז להמלאך \u0003סמריאל\u0004 הממונה של גיהנם, שהוא הענף של קו שמאל, שיפתח ג' שערים שבצד המדבר: \u0003ג' שערים\u0004 היינו ג' הקוין שבהזווג. שבצד המדבר. היינו שליטת צד השמאל, שממנו כחות המדבר. ואז נמשך הארת השמאל ממעלה למטה עד לעוה\"ז וז\"ש \u0003וחמאן נהורא דהאי עלמא,\u0004 הרי כי \u0003תלת זמנין ביומא מתפקדן,\u0004 דהיינו בג' זווגי זו\"ן, הנעשים בכח ג' התפילות, כי הארת השמאל שבתחילת כל זווג, מגיע אל הרשעים שבגיהנם. כמבואר והמשכה זו אינו נעשה רק ברגע תחילת הזווג דזו\"ן, כדי לפייס הנוקבא, כמ\"ש שם. ותכף \u0003אתא תננא דנורא וסתים אורחין,\u0004 כי נסתמו דרכי האור ונעשה חשך. כמ\"ש שם."],[2,"כדין תלת ממנן","וכו', אז ג' ממונים שתחת ידם נמצא ג' מגריפות, הם מנשבים בידיהם ומחזירים העשן למקומו. פירוש. אחר שכבר פייס הנוקבא בהארת השמאל, והנוקבא אינה יכולה לעמוד בו, כמ\"ש שם, \u0003כי אתא תננא דנורא וסתים ארחין,\u0004 עושה זווג בשליטת הימין, וממשיך לה הארה מושלמת. ונמצא שמזווג הימין הזה נמשכים ובאים \u0003תלת ממנן,\u0004 שנמשכים מג' קוין של הזווג, וג' מגרופין, היינו ג' כחות הימין המנקים את צנורות השפע מן הדינים, כמו עם מגרופות, והם ממשיכים חסדים, שבזה נבחן, אשר \u0003מנשבן בידייהו ואתיבו תננא לאתרייהו\u0004 דהיינו שמחזירים הדינים המכונים עשן ואש, אל מקומם, שהוא הגיהנם. ובינתים, דהיינו מעת שהאירו ג' הקוין בשליטת השמאל, ומטרם שבא עשן האש וסתם הדרכים, נבחן \u0003ורווחין לון שעתא ופלגות שעתא,\u0004 והיה להם הרוחה, שעה וחצי שעה. פירוש. כי ג' קוין של המוחין שהם חכמה בינה דעת, נקראים שלש שעות, וקו הדעת נחלק לשנים, שהם חסד וגבורה, ולפי זה נמצא שבעת שהאיר השמאל, האירה הבינה שהיא \u0003שעתא,\u0004 והגבורה, שהוא \u0003פלגות שעתא\u0004 מן הדעת. אבל משעתא ופלגות שעתא שלצד ימין, שהם: חכמה, וחסד שבדעת, לא האיר אז כלום. הרי שהשיגו הרוחה להנות בינתים, רק משעה וחצי שעה בלבד. \u0003ולבתר תייבין לאשייהו.\u0004 ואחר שחזר הימין להאיר בהזווג חוזרים לאש שלהם דהיינו לאש הגיהנם. ואינם יכולים להנות מחכמה וחסד שבדעת המאיר בעת הזווג הזה \u0003וכן תלת זמני וכו'\u0004 וכן ג' פעמים ביום ובכל פעם שישראל אומרים אמן יהא שמיה רבא וכו', הם משיגים הרוחה. דהיינו בתחלת כל זווג, כנ\"ל, אשריהם הצדיקים אשר דרכיהם מאירים בעולם הבא לכל הצדדים, כמו שאתה אומר, ואורח צדיקים וגו'. ע\"כ לשון התוספתא."],[3,"רבי אבא וכו':","רא\"א, בגיהנם, יש מדורים על מדורים, שניים שלישיים עד שבע, והחברים בארו אותם. (ח\"ב רס\"ג, פקודי בסולם אות תתל\"ח). ואשריהם הצדיקים, המשמרים את עצמם מחטאי הרשעים ואינם הולכים בדרכיהם ואינם נטמאים בהם. וכל מי שנטמא, כשנפטר והלך לעולם האמת הוא יורד לגיהנם, ויורד עד המדור התחתון."],[4,"ותרין מדורין וכו',","ושני מדורים הם הסמוכים זה לזה, הנקראים שאול ואבדון. מי שיורד לשאול דנים אותו שם. ומקבל ענשו, ואח\"כ, מעלים אותו למדור אחר העליון מזה, וכן עולה מדרגה אחר מדרגה, עד שמעלים אותו משם. אבל מי שיורד לאבדון, אינם מעלים אותו משם לעולם. ומשום זה נקרא אבדון. כי הוא אבוד שם לגמרי."],[5,"ת\"ח נח וכו':","בוא וראה, נח הצדיק היה מתרה בבני דורו, ולא היו שומעים לו, עד שהביא הקב\"ה עליהם דינו של גיהנם. מהו דינו של גיהנם. הוא אש ושלג, מים ואש זה קר וזה רותח. וכולם נידונו בדינו של גיהנם ונאבדו מן העולם."],[6,"ולבתר אתקיים וכו'.","ואחר כן, נתקיים העולם כראוי לו, ונכנס נח בהתבה, והביא לתוכה כל מין ומין מבריות העולם. ודאי הוא, שנח היה עץ עושה פרי, דהיינו יסוד צדיק הנקרא כך, ויצאו כל המינים שבעולם מן התיבה, כמו למעלה. דהיינו כמו ביסוד ומלכות שלמעלה. כמ\"ש לפנינו."],[7,"ת\"ח כד וכו':","בוא וראה, כאשר, עץ עושה פרי הזה, שהוא יסוד דז\"א, נתחבר בעץ פרי. שהיא מלכות. יוצאים ממנה, כל אלו המינים של מעלה, חיות גדולות וקטנות, וכמה מינים, וכל אחד למינו. כמש\"ה, חיות קטנות עם גדולות. כעין זה היה נח בהתבה, וכולם יצאו מן התבה, כלומר שכולם קבלו תיקונים מצד היותם בהתבה, כמו התולדות שלמעלה המקבלים תקונם מהמלכות. ונתקיים העולם כעין שנתקיים למעלה. ומשום זה נקרא נח איש האדמה, דהיינו בעלה דאדמה. ונקרא נח איש צדיק, דהיינו כעין יסוד צדיק שלמעלה, וכבר בארו זה, לעיל אות ח ' ט '."],[8,"רבי חייא וכו':","רח\"א שלש מאות שנה עד שלא בא המבול, היה נח מתרה בהם על מעשיהם, ולא היו שומעים לו, עד שנשלם הזמן שהקב\"ה המתין להם, דהיינו כמ\"ש, והיו ימיו מאה ועשרים שנה, ונאבדו מהעולם."],[8,"ת\"ח מה כתיב וכו':","בוא וראה, מה כתוב למעלה, דהיינו בפרשה הקודמת, ויהי כי החל האדם וגו', והיו הולכים ערומים לעיני כל, מה כתוב, ויראו בני האלהים את בנות האדם, וגו', וזה היה להם יסוד ועיקר. שגרם להם, להמשיך בחטאיהם, עד שגרם להם להשמד מהעולם, ומשום זה, נמשכו אחר יצר הרע, בגזעו ושרשיו ודחו אמונה קדושה מביניהם ונטמאו, כמו שאמרו. ומשום זה, קץ כל בשר בא לפני, ללמד שטנה עליהם."],[9,"ויאמר אלקים וגו':","רבי יהודה פתח, הודיעני ה' קצי וגו': אמר דוד לפני הקב\"ה, שני קצים הם, אחד לימין ואחד לשמאל, והם שני דרכים לבני אדם ללכת בהם לעולם האמת."],[9,"קץ לימינא וכו':","יש קץ לימין. כי כתוב לקץ הימין. ויש קץ לשמאל, כי כתוב קץ שם לחשך וגו' אבן אופל וצלמות. מהו ולכל תכלית הוא חוקר, מי הוא החוקר, אלא ההוא קץ שהוא לשמאל, הוא החוקר, שהוא מחשיך פניהם של הבריות. פירוש סיום האצילות נקרא קץ, ויש בו בחינת ימין, המאיר ממטה למעלה. והוא קדוש. ונקרא קץ הימין. ויש בו בחינת שמאל, ששם נאחז הס\"א להמשיך האור ממעלה למטה. והוא בחינת מלאך המות. (כמ\"ש בהקדמת הזהר דף קצ\"ט אות ר\"י)."]],[[0,"","אוֹי לָהֶם כְּשֶׁיֵּצְאוּ מֵהָעוֹלָם הַזֶּה. אוֹי לָהֶם (לחייהם). מִי יִתְבַּע אוֹתָם כַּאֲשֶׁר יִמָּסְרוּ בִּידֵי דוּמָה וְיִשָּׂרְפוּ בְּאֵשׁ שֶׁדּוֹלֶקֶת וְלֹא יֵצְאוּ מִמֶּנָּה רַק בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲווֹת לְפָנַי אָמַר ה'. אַחַר כָּךְ כָּרוֹז שֶׁבְּצַד צָפוֹן מַכְרִיז עֲלֵיהֶם וְאוֹמֵר, (תהלים ט) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה וְגוֹ'. כַּמָּה אֲגֻדּוֹת שֶׁל יִסּוּרִים יִתְכַּנְּסוּ עֲלֵיהֶם בְּאַרְבָּעָה צְדָדִים. אֵשׁ לוֹהֶטֶת בְּגֵיא בֶן הִנּוֹם."],[1,"","שָׁלש פְּעָמִים בְּיוֹם מִתְפַּקְּדִים (נשרפים). וְלֹא עוֹד, אֶלָּא בִּזְמַן שֶׁיִּשְׂרָאֵל עוֹנִים בְּקוֹל רָם אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְמַלֵּא רַחֲמִים וְחָס עַל הַכֹּל, וְרוֹמֵז לַמַּלְאָךְ הַמְמֻנֶּה עַל שַׁעֲרֵי הַגֵּיהִנֹּם, שֶׁשְּׁמוֹ סמריא\"ל, וּשְׁלֹשָׁה מַפְתְּחוֹת בְּיָדוֹ, וּפוֹתֵחַ שְׁלֹשָׁה שְׁעָרִים שֶׁבְּצַד הַמִּדְבָּר, וְרוֹאִים אֶת אוֹר הָעוֹלָם הַזֶּה. בָּא עָשָׁן שֶׁל אֵשׁ וְסוֹתֵם הַדְּרָכִים."],[2,"","וְאָז שְׁלֹשָׁה מְמֻנִּים שֶׁתַּחַת יְדֵיהֶם שָׁלֹשׁ מַגְרֵפוֹת, מְנַשְּׁבִים בִּידֵיהֶם וּמַחֲזִירִים עָשָׁן לִמְקוֹמָם, וְנוֹתְנִים לָהֶם רְוָחָה שָׁעָה וָחֵצִי. וְאַחַר כָּךְ שָׁבִים לָאֵשׁ שֶׁלָּהֶם. וְכָךְ שָׁלֹשׁ פְּעָמִים בְּיוֹם. וּבְכָל זְמַן שֶׁאוֹמְרִים יִשְׂרָאֵל אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ וְכוּ', מְרַוְּחִים לָהֶם. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁדַּרְכָּם מְאִירָה בְּאוֹתוֹ עוֹלָם לְכָל הַצְּדָדִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. (עד כאן התוספתא)."],[3,"","רַבִּי אַבָּא אָמַר, בַּגֵּיהִנֹּם יֵשׁ מְדוֹרִים עַל מְדוֹרִים, שְׁנִיִּים שְׁלִישִׁיִּים, עַד שֶׁבַע. וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים. וְאַשְׁרֵי הַצַּדִּיקִים שֶׁהֵם נִשְׁמָרִים מֵחֲטָאֵי הָרְשָׁעִים וְלֹא הוֹלְכִים בְּדַרְכֵיהֶם וְלֹא נִטְמָאִים בָּהֶם. וְכָל מִי שֶׁנִּטְמָא, כְּשֶׁהוֹלֵךְ לְאוֹתוֹ עוֹלָם יוֹרֵד לַגֵּיהִנֹּם, וְיוֹרֵד עַד הַמָּדוֹר הַתַּחְתּוֹן."],[4,"","וּשְׁנֵי מְדוֹרִים הֵם שֶׁסְּמוּכִים זֶה עִם זֶה - שְׁאוֹל וַאֲבַדּוֹן. מִי שֶׁיּוֹרֵד לַשְּׁאוֹל, דָּנִים אוֹתוֹ שָׁם וּמְקַבֵּל עָנְשׁוֹ, וּמַעֲלִים אוֹתוֹ לְמָדוֹר עֶלְיוֹן אַחֵר. וְכֵן דַּרְגָּה אַחַר דַּרְגָּה, עַד שֶׁהֵם מַעֲלִים אוֹתוֹ. אֲבָל מִי שֶׁיּוֹרֵד לָאֲבַדּוֹן, לֹא מַעֲלִים אוֹתוֹ לְעוֹלָמִים, וְלָכֵן נִקְרָא אֲבַדּוֹן, שֶׁהֲרֵי אָבוּד הוּא מֵהַכֹּל."],[5,"","בֹּא רְאֵה, נֹחַ הַצַּדִּיק הָיָה מַתְרֶה בִּבְנֵי דוֹרוֹ, וְלֹא הָיוּ שׁוֹמְעִים לוֹ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵבִיא עֲלֵיהֶם דִּין הַגֵּיהִנֹּם. מַהוּ דִּין גֵּיהִנֹּם? אֵשׁ וְשֶׁלֶג, מַיִם וְאֵשׁ. זֶה צוֹנֵן וְזֶה רוֹתֵחַ. וְכֻלָּם נִדּוֹנוּ בְּדִין הַגֵּיהִנֹּם וְאָבְדוּ מֵהָעוֹלָם,"],[6,"","וְאַחַר כָּךְ הִתְקַיֵּם הָעוֹלָם כָּרָאוּי לוֹ. וְנִכְנַס נֹחַ בַּתֵּבָה וְהִכְנִיס בָּהּ כָּל מִין וּמִין (מבריות) הָעוֹלָם. וַדַּאי נֹחַ עֵץ עֹשֶׂה פְּרִי הָיָה. וְיָצְאוּ מֵהַתֵּבָה כָּל מִינֵי הָעוֹלָם כְּמוֹ שֶׁלְּמַעְלָה."],[7,"","בֹּא רְאֵה, כְּשֶׁעֵץ זֶה עוֹשֶׂה הַפְּרִי, מִתְחַבֵּר בְּעֵץ פְּרִי כָּל אוֹתָם מִינִים שֶׁלְּמַעְלָה חַיּוֹת גְּדוֹלוֹת וּקְטַנּוֹת, וְכַמָּה מִינִים כָּל מִין לְמִינוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. כְּמוֹ זֶה נֹחַ בַּתֵּבָה. וְכֻלָּם יָצְאוּ מֵהַתֵּבָה, וְהִתְקַיֵּם הָעוֹלָם כְּמוֹ שֶׁלְּמַעְלָה. וְלָכֵן נֹחַ נִקְרָא אִישׁ הָאֲדָמָה. נֹחַ נִקְרָא אִישׁ צַדִּיק. וַהֲרֵי בֵּאֲרוּהָ."],[8,"","רַבִּי חִיָּיא אָמַר, שְׁלֹשׁ מֵאוֹת שָׁנָה עַד שֶׁלֹּא בָא הַמַּבּוּל הָיָה נֹחַ מַתְרֶה בָהֶם עַל מַעֲשֵׂיהֶם וְלֹא הָיוּ שׁוֹמְעִים לוֹ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁלִים הַזְּמַן שֶׁחִכָּה לָהֶם וְאָבְדוּ מֵהָעוֹלָם בֹּא רְאֵה מַה כָּתוּב לְמַעְלָה, וַיְהִי כִּי הֵחֵל הָאָדָם לָרֹב עַל פְּנֵי הָאֲדָמָה וּבָנוֹת יֻלְּדוּ לָהֶם. וְהָיוּ הוֹלְכִים עֲרֻמִּים לְעֵין כֹּל. מַה כָּתוּב? (בראשית ו) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם וְגוֹ'. וְזֶה הָיָה יְסוֹד וְעִקָּר לְהִמָּשֵׁךְ בְּחֶטְאָם עַד שֶׁגָּרַם לָהֶם לְהִשָּׁמֵד מֵהָעוֹלָם, וְלָכֵן נִמְשְׁכוּ אַחַר יֵצֶר הָרָע וּבְגִזְעוֹ וּבְשָׁרְשׁוֹ וְדָחוּ אֶת הָאֱמוּנָה הַקְּדוֹשָׁה מִבֵּינֵיהֶם, וְנִטְמְאוּ (נ\"א: ונאבדו) כְּמוֹ שֶׁנֶּאֱמַר. לָכֵן קֵץ כָּל בָּשָׂר בָּא לְפָנַי - לְלַמֵּד קָטֵגוֹרְיָה עֲלֵיהֶם."],[9,"","וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. (חזרנו לדבר הראשון, קץ כל בשר בא לפני, בא לפני ודאי, משום שהם גרמו). רַבִּי יְהוּדָה פָּתַח, (תהלים לט) הוֹדִיעֵנִי ה' קִצִּי וּמִדַּת יָמַי מַה הִיא אֵדְעָה מֶה חָדֵל אָנִי. אָמַר דָּוִד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: שְׁנֵי קִצִּים הֵם, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל, וְהֵם שְׁתֵּי דְרָכִים לָלֶכֶת בָּהֶם בְּנֵי אָדָם לְאוֹתוֹ הָעוֹלָם. קֵץ לְיָמִין - שֶׁכָּתוּב (דניאל יב) לְקֵץ הַיָּמִין. וְקֵץ לִשְׂמֹאל - שֶׁכָּתוּב (איוב כח) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר (אבן אפל וצלמות, מה זה ולכל תכלית הוא חוקר? מי הוא החוקר? אלא אותו קץ לשמאל שמחשיך פני הבריות). מַהוּ וּלְכָל תַּכְלִית? בִּזְמַן שֶׁשָּׁרוּי הַדִּין עַל הָעוֹלָם לְהַשְׁמִיד - אֶבֶן אֹפֶל וְצַלְמָוֶת. קֵץ שָׂם לַחֹשֶׁךְ - זֶה מַלְאַךְ הַמָּוֶת, זֶה נָחָשׁ. קֵץ כָּל בָּשָׂר, קֵץ שָׂם לַחֹשֶׁךְ, שֶׁהֲרֵי מִצַּד שֶׁל הִתּוּךְ הַזָּהָב הוּא בָא. וּלְכָל תַּכְלִית - בִּזְמַן שֶׁדִּין שָׁרוּי עַל הָעוֹלָם, הוּא חוֹקֵר לִהְיוֹת קָטֵגוֹר לָעוֹלָם לְהַחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת. קֵץ לְיָמִין, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב לְקֵץ הַיָּמִין."]]],[["קֵץ לְיָמִינָא כִּדְקָאֲמָרָן דִּכְתִיב לְקֵץ הַיָּמִין. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְדָנִיֵּאל וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ. אָמַר לֵיהּ מְנוּחָה בְּהַאי עָלְמָא אוֹ בְּהַהוּא עָלְמָא, אָמַר לֵיהּ בְּהַהוּא עָלְמָא כְּמָא דְאַתְּ אָמֵר יָנוּחוּ עַל מִשְׁכְּבוֹתָם. (דניאל י״ב:י״ג) (ותעמוד לגורלך לקץ הימין. אמרז ליה לאן אתר דהא לא ידענא מה יהא עלי בההוא עלמא. אמר ליה ותנוח). אָמַר לֵיהּ בְּזִמְנָא דִיקוּמוּן מֵעַפְרָא אֵיקוּם בֵּינַיְיהוּ אוֹ לָאו. אָמַר לֵיהּ וְתַעֲמֹד. אָמַר לֵיהּ הָא יְדַעְנָא דִּי יְקוּמוּן כִּתּוֹת כִּתּוֹת, מִנְּהוֹן דְּזַכָּאֵי קְשׁוֹט וּמִנְּהוֹן דְּחַיָּיבֵי עָלְמָא, וְלָא יְדַעְנָא עִם מָאן מִנְּהוֹן אֵיקוּם. אָמַר לֵיהּ לְגוֹרָלְךָ. אָמַר לֵיהּ הָא אֲמַרְתְּ וְאַתָּה לֵךְ לַקֵּץ. אִית קֵץ לְיָמִינָא וְאִית קֵץ לִשְׂמָאלָא, וְלָא יְדַעְנָא לְאָן קֵץ. לְקֵץ הַיָּמִין אוֹ לְקֵץ הַיָּמִים. אָמַר לֵיהּ לְקֵץ הַיָּמִין.","אוּף הָכָא דָּוִד אָמַר לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא (תהילים ל״ט:ה׳) הוֹדִיעֵנִי יְיָ קִצִּי. מָה אִיהוּ חוּלַק עַדְבִי. וְלָא נָח דַּעְתֵּיהּ עַד דְּאִתְבַּשַּׂר דְּיֶהוֵי לְיָמִינָא דִּכְתִיב, (תהילים ק״י:א׳) שֵׁב לִימִינִי. תָּא חֲזֵי, אוּף קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. מָאן אִיהוּ. דָּא קֵץ דְּאַחְשַׁךְ אַפַּיְיהוּ דִּבְרִיָּיתָא דְּאִיהוּ קֵץ כָּל בָּשָׂר","בָּא לְפָנַי. מִכָּאן אוֹלִיפְנָא חַיָּיבֵי עָלְמָא מַקְדִּימִין לֵיהּ וּמָשְׁכָן לֵיהּ עֲלַיְיהוּ לְאַחְשָׁכָא לוֹן. דְּכֵיוָן דְּיָהֲבֵי לֵיהּ רְשׁוּתָא נָטִיל נִשְׁמָתָא. וְלָא נָטִיל עַד דְּיָהֲבֵי לֵיהּ רְשׁוּתָא. וְעַל דָּא בָּא לְפָנַי לְמֵיטַל רְשׁוּ לְאַחְשָׁכָא אַפַּיְיהוּ דִּבְנֵי עָלְמָא. וּבְגִינֵי כָךְ וְהִנְּנִי מַשְׁחִיתָם אֶת הָאָרֶץ. וְעַל דָּא עֲשֵׂה לְךָ תֵּבַת עֲצֵי גוֹפֶר בְּגִין לְאִשְׁתְּזָבָא וְלָא יָכִיל לְשַׁלְטָאָה עֲלָךְ.","תָּא חֲזֵי, תָּנִינָן בְּזִמְנָא דְמוֹתָא אִית בְּמָתָא אוֹ בְּעָלְמָא (נ\"א דאתייהיב רשו למלאך המות לחבלא). לָא יִתְחֲזֵי בַּר נָשׁ בְּשׁוּקָא. בְּגִין דְּאִית לֵיהּ רְשׁוּ לִמְחַבְּלָא לְחַבָּלָא כֹּלָּא. בְּגִינֵי כָךְ אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לָךְ לְאִסְתַּמְרָא וְלָא תֶחזֵי גַרְמָךְ קַמֵּי דִמְחַבְּלָא דְּלָא יִשְׁלוֹט עֲלָךְ.","וְאִי תֵימָא מָאן יָהִיב הָכָא מְחַבְּלָא. דְּהָא מַיִין הֲווּ וְאִתְגַּבָּרוּ. תָּא חֲזֵי, לֵית לָךְ דִּינָא בְּעָלְמָא אוֹ כַּד אִתְמַחֵי אוֹ כַּד אִתְמָסַר עַלְמָא בְּדִינָא, דְּלָא אִשְׁתְּכַח הַהוּא מְחַבְּלָא דְּאָזִיל בְּגוֹ אִנּוּן דִּינִין דְּאִתְעֲבִידוּ בְּעָלְמָא. אוּף הָכִי הָכָא טוֹפָנָא הֲוָה, וּמְחַבְּלָא אָזִיל בְּגוֹ טוֹפָנָא. וְאִיהוּ אִקְרֵי הָכִי דְּאִתְכְּלִיל בִּשְׁמָא דָא. וְעַל דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְנֹחַ לְטַמְרָא גַרְמֵיהּ וְלָא יִתְחֲזֵי בְּעָלְמָא.","וְאִי תֵימָא הַאי תֵּיבוּתָא אִתְחֲזֵי בְּגוֹ הַאי עָלְמָא וּמְחַבְּלָא אָזִיל בְּגַוֵּויהּ. כָּל זִמְנָא דְּלָא יִתְחֲזֵי אַפֵּי דְּבַּר נָשׁ קַמֵּי מְחַבְּלָא לָא יָכִיל לְשַׁלְטָאָה עֲלֵיהּ. מְנָלָן מִמִּצְרַיִם דִּכְתִיב, (שמות י״ב:כ״ב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מַאי טַעְמָא בְּגִין דְּאִיהוּ אִשְׁתְּכַּח וְיָכִיל הוּא לְחַבְּלָא. וְלֹא אִצְטְרִיךְ לְאִתְחַזָּאָה קַמֵּיהּ. בְּגִין כָּךְ הֲוָה גָנִיז נֹחַ וְכָל אִנּוּן דְּעִמֵּיהּ בְּתֵיבוּתָא. וּמְחַבְּלָא לָא יָכִיל לְשַׁלְטָאָה עֲלַיְיהוּ:","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הֲווּ אָזְלֵי בְּאָרְחָא. אִעָרַע בְּהַנֵּי טוּרֵי דְּקַרְדוּ, חָמוּ רְשִׁימִין בְּקִיעִין בְּאָרְחָא דְּהֲווּ מִן יוֹמֵי דְטוֹפָנָא. אָמַר לֵיהּ רַבִּי חִיָּיא לְרַבִּי יוֹסֵי הַנֵּי בְּקִיעִין דְּהֲווּ מִיּוֹמוֹי דְּטוֹפָנָא, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁבִיק לוֹן לְדָרֵי דָרִין בְּגִין דְּלָא יִתְמַחֵי חוֹבֵיהוֹן דְּרַשִּׁיעַיָא קַמֵּיהּ.","דְּכָךָ אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. לְזַכָּאִין דְּעָבְדִין רְעוּתֵיהּ, בָּעֵי דְּיִדְכְּרוּן לְהוּ לְעֵילָא וְתַתָּא וְלָא יִתְנְשֵׁי דּוּכְרָנֵיהוֹן לְדָרֵי דָרִין לְטַב. כְּגַוְונָא דָא לְרַשִּׁיעַיָיא דְּלָא עָבְדִין רְעוּתֵיהּ, בְּגִין דְּלָא יִתְנְשֵׁי חוֹבַיְיהוּ וּלְאַדְכָּרָא עָנְשַׁיְיהוּ וְדָכְרָנֵיהוֹן לְבִישׁ לְדָרֵי דָרִין. הַיְינוּ דִכְתִיב, (ירמיהו ב׳:כ״ב) נִכְתַּם עֲוֹנֵךְ לְפָנַי וְגו'.","פָּתַח רַבִּי יוֹסֵי וְאָמַר (ישעיהו י׳:ל׳) צַהֲלִי קוֹלֵךְ בַּת גַּלִּים הַקְשִׁיבִי לַיְשָׁה עֲנִיָּה עֲנָתוֹת. הַאי קְרָא אוּקְמוּהָ חַבְרַיָא. אֲבָל הַאי קְרָא עַל כְּנֶסֶת יִשְׂרָאֵל אִתְּמָר. צַהֲלִי קוֹלֵךְ בַּת גַּלִּים, בְּרַתֵּיהּ דְּאַבְרָהָם אָבִינוּ הָכִי אוּקְמוּהָ בַּת גַּלִּים כְּדִכְתִיב, (שיר השירים ד׳:י״ב) גַּל נָעוּל. גַּלִּים אִנּוּן נְהוֹרִין דְּמִתְכַּנְשֵׁי וְאָזְלֵי וְעָאלִין לְגַוָּוהּ וּמַלְיָין לָהּ כְּדִכְתִיב, (שיר השירים ד׳:י״ג) שְׁלָחַיִךְ פַּרְדֵּס רִמּוֹנִים.","הַקְשִׁיבִי לַיְשָׁה כְּמָא דְאַתְּ אָמֵר (איוב ד׳:י״א) לַיִשׁ אוֹבֵד מִבְּלִי טֶרֶף. לַיִשׁ דְּכַר. לַיְשָׁה נוּקְבָא. אַמַּאי אִקְרֵי לַיִשׁ, אִי מִשּׁוּם (משלי ל׳:ל׳) דִּכְתִיב לַיִשׁ גִּבּוֹר בַּבְּהֵמָה, אוֹ מִשּׁוּם דִּכְתִיב לַיִשׁ אוֹבֵד מִבְּלִי טָרֶף. אֶלָּא כֹּלָּא אִיהוּ לַיִשׁ גְּבוּרָה תַּתָּאָה וּדְאָתֵי מִגְּבוּרָה עִלָּאָה. לַיִשׁ אוֹבֵד מִבְּלִי טָרֶף, בְּשַׁעֲתָא דְּאִנּוּן נְחָלִין מִסְתַּלְקִין וְלָא עָאלִין לְגַוָּוהּ, כְּדֵין אִתְקְרֵי לַיְשָׁה דְּאֲבִידַת מִבְּלִי טֶרֶף. דִּכְתִיב לַיִשׁ אוֹבֵד מִבְּלִי טֶרֶף וּבְנֵי לָבִיא יִתְפָּרְדוּ."],[[0,"קץ לימינא כדקאמרן וכו':","הקץ לימין, הוא כמו שאמרנו, שכתוב לקץ הימין אמר לו הקב\"ה לדניאל, ואתה לך לקץ ותנוח. א\"ל דניאל, בעולם הזה או בעולם האמת, א\"ל בעולם האמת. כמש\"ה. ינוחו על משכבותם. אמר לו בשעה שיקומו מעפר, דהיינו בתחית המתים, אקום ביניהם או לא. א\"ל ותעמוד. א\"ל דניאל, יודע אני שיקומו, לתחית המתים, כתות כתות, מהם צדיקי אמת ומהם רשעי עולם ואיני יודע עם מי מהם אקום. א\"ל לגורלך. היינו עם הצדיקים, א\"ל והרי אמרת ואתה לך לקץ, הרי יש קץ לימין ויש קץ לשמאל, ואיני יודע לאיזה קץ, לקץ הימין או לקץ השמאל. אמר לו לקץ הימין."],[1,"אוף הכי דוד וכו':","אף דוד כן, אמר לו להקב\"ה, הודיעני ה' קצי, מהו חלק גורלי, ולא נח דעתו עד שנתבשר שיהיה לימין, שכתוב, שב לימיני."],[1,"ת\"ח אוף","וכו': בוא וראה, אף לנח אמר הקב\"ה, קץ כל בשר בא לפני. מי הוא אם קץ הימין או קץ השמאל. ואומר. זהו הקץ, שהחשיך פניהם של הבריות, להיותו קץ כל בשר, דהיינו קץ השמאל ההוא מלאך המות."],[2,"בא לפני.","מכאן למדנו, שרשעי עולם מקדימים אותו ומושכים אותו עליהם להחשיך להם. כיון שנותנים לו רשות, הוא נוטל הנשמה, ואינו נוטל הנשמה עד שנותנים לו רשות, וע\"כ אוה\"כ \u0003בא לפני,\u0004 שבא לפני לקבל רשות להחשיך פניהם של בני העולם, ועל כן והנני משחיתם את הארץ. היינו שנתתי לו רשות וע\"כ עשה לך תיבת עצי גופר. כדי שתנצל ולא יוכל לשלוט עליך."],[3,"ת\"ח תנינן","וכו': בוא וראה למדנו בשעה שיש מגפה בעיר או בעולם, לא יתראה האדם בשוק, משום שיש לו רשות להמשחית להשחית הכל, משום זה אמר לו הקב\"ה, אתה צריך להשמר, ולא תראה עצמך לפני המשחית, שלא ימשול עליך."],[4,"ואי תימא וכו':","ואם תאמר, מי נתן כאן משחית, הרי רק מים היו ונתגברו, ונעשו למבול. בוא וראה. אין לך דין הנעשה בעולם, אם כשהעולם מוכה, או אפילו כשהעולם רק נמסר לדין, שלא ימצא אותו המשחית הולך בתוך הדינים הנעשים בעולם. אף כאן כן הוא, מבול היה והמשחית הלך בתוך המבול, והוא נקרא כן בשם מבול, כי נכלל בשם הזה. וע\"כ אמר הקב\"ה לנח להסתיר עצמו בתוך התבה ולא להראות בעולם."],[5,"ואי תימא","וכו': ואם תאמר, הרי התיבה נראתה בעולם הזה שהמשחית הלך בו וא\"כ עדיין הוא מגולה לפני המשחית. אלא כל עוד שפניו של אדם אינם נראים לפני המשחית אינו יכול למשול על האדם. מאין לנו זה, ממצרים, שכתוב, ואתם לא תצאו איש וגו' מהו הטעם, משום שהמשחית נמצא בחוץ, והוא יכול להשחית ולא צריכים להתראות לפניו, ומשום זה נח וכל אלה שהיו עמו נסתתרו בהתבה, והמשחית, לא יכול למשול עליהם."],[6,"רבי חייא וכו':","ר\"ח ור\"י היו הולכים בדרך, ופגשו בהרי אררט, ראו בהדרך רשומות בקעים, שהיו מימי המבול, א\"ל ר\"ח לר' יוסי, בקעים הללו הם מימי המבול, והקב\"ה הניח אותם לדורי דורות, שלא ימחו לפניו עונותיהם של הרשעים."],[7,"דכך ארחוי וכו',","כי כך דרכיו של הקב\"ה אשר להצדיקים שעושים רצונו רוצה שיזכרו אותם למעלה ולמטה, ולא ישכח זכרונם לדורי דורות. כעין זה, להרשעים שאינם עושים רצונו רוצה ג\"כ שיזכרו אותם, כדי שלא ישכחו עונותיהם, ולזכור עונשם, וזכרונם לרע, לדורי דורות. והיינו שכתוב, נכתם עונך לפני וגו'."],[8,"פתח וכו':","פתח ר' יוסי ואמר, צהלי קולך בת גלים הקשיבי לישה עניה ענתות מקרא זה כבר פרשוהו החברים. אבל כתוב זה נאמר על כנסת ישראל, היא המלכות, צהלי קולך בת גלים היינו בת אברהם אבינו, שהוא בסוד אבא יסד ברתא, והוא חסד שעלה להיות חכמה, וכשיש לה מוחין דאבא, נקראת בת גלים, וכן פרשוהו, בת גלים היינו כמו שכתוב גל נעול, שהמלכות נקראת גל בעת שיש לה מוחין דאבא, וכן כאן נקראת גלים, כי גלים, הם האורות המתקבצים, בסוד ג' הנקודות חולם שורק חירק, והולכים ונכנסים לתוך המלכות וממלאים אותה, כמ\"ש שלחיך פרדס רמונים. אשר \u0003שלחיך\u0004 פירושו ג\"כ האורות המתקבצים ונמשכים להמלכות. כמו נהרות ונחלים. ושיעור הכתוב צהלי קולך בת גלים נאמר על המלכות שתשמח ותרנן בקולה בעת שהיא בת גלים, דהיינו שיש לה המוחין הגדולים הנקראים \u0003גלים,\u0004 שהם מוחין דאבא."],[9,"הקשיבי לישה וכו':","לישה פירושו, כמו שכתוב ליש אובד מבלי טרף, דהיינו בהיפך מהשם. \u0003גלים\u0004 כי יורה לעת שהמלכות נאבדת מחמת חוסר שפע, ליש הוא שם זכר, לישה היא שם נקבה, וכשאומר לישה יורה על המלכות שהיא נוקבא, ושואל, למה היא נקראת על השם ליש, אם משום שכתוב, ליש גבור בבהמה, דהיינו על מדת הגבורה שבה, או משום שכתוב ליש אובד מבלי טרף שהוא על חוסר שפע שבה, ומשיב אלא הכל הוא ב \u0003ליש\u0004 שהשם \u0003ליש\u0004 יורה על זמן היותה בבחינת נקודת השורק, שאז שניהם בה, הן מדת הגבורה והן חסרון השפע, שהוא אז גבורה תחתונה, מלכות, ושהוא נמשכת מגבורה עלאה, דהיינו מהגבורה שבבינה, ע\"כ נאמר עליה ליש גבור בבהמה. והיא, ליש אובד מבלי טרף, בשעה שאלו הנחלים, שהם אורות העליונים, מסתלקים ואינם נכנסים לתוכה, אז נקראת לישה, הנאבדת מבלי טרף, כמו שכתוב ליש אובד מבלי טרף ובני לביא יתפרדו."]],[[0,"","אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָנִיֵּאל: וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ. אָמַר לוֹ: מְנוּחָה בָּעוֹלָם הַזֶּה אוֹ בָּעוֹלָם הַהוּא? אָמַר לוֹ: בָּעוֹלָם הַהוּא, כְּמוֹ שֶׁנֶּאֱמַר יָנוּחוּ עַל מִשְׁכְּבוֹתָם. (דניאל יב) (ותעמד לגורלך לקץ הימין, אמר לו, ' לאיזה מקום, שהרי לא ידעתי מה יהיה עלי באותו עולם? אמר לו', ותנוח). אָמַר לוֹ: בִּזְמַן שֶׁיָּקוּמוּ מֵהֶעָפָר, אָקוּם בֵּינֵיהֶם אוֹ לֹא? אָמַר לוֹ: וְתַעֲמֹד. אָמַר לוֹ: הֲרֵי יָדַעְתִּי שֶׁיָּקוּמוּ כִּתּוֹת כִּתּוֹת, מֵהֶם שֶׁל צַדִּיקֵי אֱמֶת וּמֵהֶם שֶׁל רִשְׁעֵי הָעוֹלָם, וְלֹא יָדַעְתִּי עִם מִי מֵהֶם אָקוּם. אָמַר לוֹ: לְגוֹרָלְךְ. אָמַר לוֹ: הֲרֵי אָמַרְתָּ וְאַתָּה לֵךְ לַקֵּץ. יֵשׁ קֵץ לְיָמִין וְיֵשׁ קֵץ לִשְׂמֹאל, וְלֹא יָדַעְתִּי לְאֵיזֶה קֵץ, לְקֵץ הַיָּמִין אוֹ לְקֵץ הַיָּמִים? אָמַר לוֹ: לְקֵץ הַיָּמִין."],[1,"","גַּם כָּאן דָּוִד אָמַר לַקָּדוֹשׁ-בָּרוּךְ- הוּא, (תהלים לט), הוֹדִיעֵנִי ה' קִצִּי, מַהוּ חֵלֶק גּוֹרָלִי. וְלֹא נָחָה דַעְתּוֹ עַד שֶׁהִתְבַּשֵּׂר שֶׁיִּהְיֶה לְיָמִין, שֶׁכָּתוּב (שם קי) שֵׁב לִימִינִי. בֹּא רְאֵה, גַּם הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ לְנֹחַ, קֵץ כָּל בָּשָׂר בָּא לְפָנַי. מִיהוּ? זֶה הַקֵּץ שֶׁמַּחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת, שֶׁהוּא קֵץ כָּל בָּשָׂר,"],[2,"","בָּא לְפָנַי. מִכָּאן לָמַדְנוּ שֶׁרִשְׁעֵי הָעוֹלָם מַקְדִּימִים וּמוֹשְׁכִים אוֹתוֹ עֲלֵיהֶם לְהַחְשִׁיךְ לָהֶם. שֶׁכֵּיוָן שֶׁנּוֹתְנִים לוֹ רְשׁוּת, הוּא נוֹטֵל אֶת הַנְּשָׁמָה, וְלֹא נוֹטֵל עַד שֶׁנּוֹתְנִים לוֹ רְשׁוּת, וְעַל זֶה בָּא לְפָנַי לִטֹּל רְשׁוּת לְהַחְשִׁיךְ פְּנֵי בְּנֵי הָעוֹלָם. וְלָכֵן וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ. וְעַל זֶה עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר, כְּדֵי לְהִנָּצֵל, וְלֹא יוּכַל לִשְׁלֹט עָלֶיךְ."],[3,"","בֹּא רְאֵה, שָׁנִינוּ, בִּזְמַן שֶׁיֵּשׁ מָוֶת בָּעִיר אוֹ בָּעוֹלָם (נ\"א: שנתנה רשות למלאך המות להשחית) לֹא יֵרָאֶה אָדָם בַּשּׁוּק, מִשּׁוּם שֶׁיֵּשׁ לוֹ רְשׁוּת לַמַּשְׁחִית לְהַשְׁחִית הַכֹּל. מִשּׁוּם כָּךְ אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתָּה צָרִיךְ לְהִשָּׁמֵר, וְלֹא תַרְאֶה אֶת עַצְמְךְ לִפְנֵי הַמַּשְׁחִית שֶׁלֹּא יִשְׁלֹט עָלֶיךְ."],[4,"","וְאִם תֹּאמַר, מִי נָתַן כָּאן מַשְׁחִית, שֶׁהֲרֵי מַיִם הָיוּ וְהִתְגַּבְּרוּ.? בֹּא רְאֵה, אֵין לְךְ דִּין בָּעוֹלָם אוֹ כְּשֶׁמֻּכֶּה אוֹ כְּשֶׁנִּמְסָר הָעוֹלָם בְּדִין, שֶׁלֹּא נִמְצָא אוֹתוֹ הַמַּשְׁחִית שֶׁהוֹלֵךְ בְּתוֹךְ אוֹתָם הַדִּינִים שֶׁנַּעֲשִׂים בָּעוֹלָם. גַּם כָּאן בַּמַּבּוּל כָּךְ הָיָה, וְהַמַּשְׁחִית הוֹלֵךְ בְּתוֹךְ הַמַּבּוּל. וְהוּא נִקְרָא כָּךְ, שֶׁנִּכְלָל בַּשֵּׁם הַזֶּה. וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ לִשְׁמֹר עַצְמוֹ וְלֹא יִתְרָאֶה בָּעוֹלָם."],[5,"","וְאִם תֹּאמַר, הֲרֵי הַתֵּבָה הַזּוֹ נִרְאֵית בְּתוֹךְ הָעוֹלָם הַזֶּה וְהַמַּשְׁחִית הוֹלֵךְ בְּתוֹכוֹ? כָּל זְמַן שֶׁלֹּא נִרְאִים פְּנֵי אָדָם לִפְנֵי הַמַּשְׁחִית, לֹא יָכוֹל לִשְׁלֹט עָלָיו. מִנַּיִן לָנוּ? מִמִּצְרַיִם, שֶׁכָּתוּב (שמות יב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא נִמְצָא וְהוּא יָכוֹל לְהַשְׁחִית, וְלֹא צָרִיךְ לְהִתְרָאוֹת לְפָנָיו. לָכֵן הָיָה גָנוּז נֹחַ וְכָל אֵלּוּ שֶׁעִמּוֹ בְּתוֹךְ הַתֵּבָה, וְהַמַּשְׁחִית לֹא יָכֹל לִשְׁלֹט עֲלֵיהֶם."],[6,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. פָּגְשׁוּ בְּאוֹתָם הָרֵי אֲרָרָט. רָאוּ רִשּׁוּמִים בְּקִיעִים בַּדֶּרֶךְ שֶׁהָיוּ מִימֵי הַמַּבּוּל. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, הַבְּקִיעִים הַלָּלוּ שֶׁהָיוּ מִימֵי הַמַּבּוּל וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁאִירָם לְדוֹרֵי דוֹרוֹת, כְּדֵי שֶׁלֹּא יִמָּחֶה חֶטְאָם שֶׁל הָרְשָׁעִים לְפָנָיו."],[7,"","שֶׁכָּךָ דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא: לַצַּדִּיקִים שֶׁעוֹשִׂים רְצוֹנוֹ - רוֹצֶה שֶׁיִּזְכְּרוּ אוֹתָם לְמַעְלָה וּלְמַטָּה וְלֹא יִשָּׁכַח זִכְרָם לְדוֹרֵי דוֹרוֹת לְטוֹב. כְּמוֹ זֶה לָרְשָׁעִים שֶׁלֹּא עוֹשִׂים רְצוֹנוֹ - כְּדֵי שֶׁלֹּא יִשָּׁכַח חֶטְאָם, וּלְהַזְכִּיר עָנְשֵׁיהֶם וְזִכְרוֹנָם לְרַע לְדוֹרֵי דוֹרוֹת, הַיְינוּ שֶׁכָּתוּב (ירמיה ב) נִכְתָּם עֲוֹנֵךְ לְפָנַי וְגוֹ'."],[8,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (ישעיה י) צַהֲלִי קוֹלֵךְ בַּת גַּלִּים הַקְשִׁיבִי לַיְשָׁה עֲנִיָּה עֲנָתוֹת. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים. אֲבָל פָּסוּק זֶה נֶאֱמַר עַל כְּנֶסֶת יִשְׂרָאֵל. צַהֲלִי קוֹלֵךְ בַּת גַּלִּים - בִּתּוֹ שֶׁל אַבְרָהָם אָבִינוּ, כָּךְ פֵּרְשׁוּהָ בַּת גַּלִּים, כַּכָּתוּב (שיר ד) גַּל נָעוּל. גַּלִּים הֵם מְאוֹרוֹת שֶׁמִּתְכַּנְּסִים וְהוֹלְכִים וְנִכְנָסִים לְתוֹכָהּ וּמְמַלְּאִים אוֹתָהּ, כַּכָּתוּב (שם) שְׁלָחַיִךְ פַּרְדֵּס רִמּוֹנִים."],[9,"","הַקְשִׁיבִי לַיְשָׁה, כְּמוֹ שֶׁנֶּאֱמַר (איוב ד) לַיִשׁ אֹבֵד מִבְּלִי טָרֶף. לַיִשׁ - זָכָר. לַיְשָׁה - נְקֵבָה. לָמָּה נִקְרָא לַיִשׁ? אִם מִשּׁוּם שֶׁכָּתוּב (משלי ל) לַיִשׁ גִּבּוֹר בַּבְּהֵמָה, אוֹ מִשּׁוּם שֶׁכָּתוּב לַיִשׁ אֹבֵד מִבְּלִי טָרֶף. אֶלָּא הַכֹּל הוּא לַיִשׁ, גְּבוּרָה תַחְתּוֹנָה שֶׁבָּאָה מִגְּבוּרָה עֶלְיוֹנָה. לַיִשׁ אֹבֵד מִבְּלִי טָרֶף - בְּשָׁעָה שֶׁאוֹתָם נְחָלִים מִסְתַּלְּקִים וְלֹא נִכְנָסִים לְתוֹכָהּ, אָז נִקְרֵאת לַיְשָׁה שֶׁאוֹבֶדֶת מִבְּלִי טֶרֶף, שֶׁכָּתוּב לַיִשׁ אֹבֵד מִבְּלִי טָרֶף וּבְנֵי לָבִיא יִתְפָּרָדוּ."]]],[["וּמַה דְּאָמַר לַיְשָׁה הַיְינוּ עֲנִיָּה עֲנָתוֹת מִסְּכֵּנָא דְּמִסְכֵּנוּתָא כְּמָא דְאַתְּ אָמֵר, (ירמיהו א׳:א׳) מִן הַכֹּהֲנִים אֲשֶׁר בַּעֲנָתוֹת וּכְתִיב, (מלכים א ב׳:כ״ו) עֲנָתֹת לֵךְ עַל שָׂדֶיךָ. מַאי אִירְיָא. אֶלָּא כָּל זִמְנָא דְּדָוִד מַלְכָּא הֲוָה קַיָּים, אִסְתַּלַּק אֶבְיָתָר בְּעוּתְרָא וּבְכֹלָּא. לְבָתַר אָמַר לֵיהּ שְׁלֹמֹה עֲנָתוֹת לֵךְ עַל שָׂדֶיךָ.","אַמַּאי קָרֵי לֵיהּ שְׁלֹמֹה הָכִי. אֶלָּא אָמַר לֵיהּ בְּיוֹמָךְ הֲוָה אַבָּא בְּמִסְכֵּנוּ וְהַשְׁתָּא לֵךְ עַל שָׂדֶיךָ. הַשְׁתָּא אִית לוֹמַר אַמַּאי אִקְרֵי אֶבְיָתָר עֲנָתוֹת. אִי תֵימָא דְּהֲוָה מִן עֲנָתוֹת, הָא תָּנִינָן דִּכְתִיב, (שמואל א כ״ב:כ׳) וַיִּמָּלֵט בֵּן אֶחָד לַאֲחִימֶלֶךְ בֶּן אֲחִיטוּב וּשְׁמוֹ אֶבְיָתָר. וְהוּא מִנּוֹב הֲוָה, דְּהָא נוֹב עִיר הַכֹּהֲנִים הֲוָה. וְאַף עַל פִּי דְּאָמְרוּ דְּהִיא נוֹב הִיא עֲנָתוֹת וְאַמַּאי לָהּ אִקְרֵי עֲנָתוֹת בְּגִין דְּנָחֲתַת לְמִסְכֵּנוּ וְאִתְאֲבִיד קַרְתָּא עַל יְדָא דְשָׁאוּל וְאִתְאֲבִידוּ כָּהֲנִי. אֶלָּא עֲנָתוֹת כְּפַר הֲוָה, וְלָאו הוּא נוֹב, וְעַל דָּא קָרֵי לֵיהּ אֶבְיָתָר עֲנָתוֹת, בְּגִין דְּאָמַר (מלכים א ב׳:כ״ו) וְכִי הִתְעַנִּיתָ בְּכֹל אֲשֶׁר הִתְעַנָּה אָבִי. וּמִקַּרְתָּא דְנוֹב הֲוָה, וְעַל מִסְכְּנוּ דְּדָוִד דְּהֲוָה בְּיוֹמוֹי אִקְרֵי לֵיהּ הָכִי.","אָמַר רַבִּי חִיָּיא בְּמִסְכְּנוּתָא הֲוָה עָלְמָא מִיּוֹמָא דְּעֲבַר אָדָם עַל פִּקּוּדֵי קוּדְשָׁא בְּרִיךְ הוּא, עַד דְּאָתָא נֹחַ וְקָרִיב קָרְבָּן וְאִתְיְישַׁב עָלְמָא. אָמַר רַבִּי יוֹסֵי לָא אִתְיְישַׁב עָלְמָא וְלָא נַפְקָא אַרְעָא מִזּוּהֲמָא דְּנָחָשׁ עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי וְאִתְאֲחִידוּ בְּאִילָנָא דְחַיֵּי כְּדֵין אִתְיְישַׁב עָלְמָא.","וְאִלְמָלֵא דְהָדְרוּ יִשְׂרָאֵל וְחָאבוּ קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא לָא הֲווּ מֵתִין לְעָלְמִין. דְּהָא אִתְפַּסַּק מִנַּיְיהוּ זוּהֲמָא דְנָחָשׁ. כֵּיוָן דְּחָבוּ כְּדֵין אִתְבָּרוּ אִנּוּן לוּחֵי קַדְמָאֵי, דְּהֲווּ בְּהוּ חֵירוּ דְּכֹלָּא. חֵירוּ דְּהַהוּא נָחָשׁ דְּאִיהוּ קֵץ כָּל בָּשָׂר.","וְכַד קָמוּ לֵיוָאֵי לְקַטְלָא קְטָלָא, כְּדֵין אִתְעַר חִוְיָא בִּישָׁא וְהֲוָה אָזִיל קַמַּיְיהוּ וְלָא יָכִיל לְשַׁלְטָאָה בְּהוּ, בְּגִין דְּהֲווּ יִשְׂרָאֵל מִזְדָּרְזִין כֻּלְהוּ בְּחֲגִירוּ מְזַיְינָן וְלָא יָכִיל הַהוּא נָחָשׁ לְשַׁלְטָאָה בְּהוּ. וְכֵיוָן דְּאָמַר לְמשֶׁה (שמות ל״ג:ה׳) וְעַתָּה הוֹרֵד עֶדְיְךָ מֵעָלֶיךָ, אִתְיְיהִיב רְשׁוּ לְהַאי נָחָשׁ לְשַׁלְטָאָה עֲלַיְיהוּ.","תָּא חֲזֵי, מַה כְּתִיב, (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חֹרֵב. וַיִּתְנַצְּלוּ וַיְנַצְּלוּ מִבָּעֵי לֵיהּ. אֶלָּא וַיִּתְנַצְּלוּ עַל יְדָא דְּאַחֲרָא בְּגִין דְּאִתְיְיהִיב רְשׁוּ לְנָחָשׁ לְשַׁלְטָאָה. אֶת עֶדְיָם מֵהַר חוֹרֵב דְּקִבְּלוּ מִטּוּרָא דְחוֹרֵב כַּד אִתְיְיהִיב אוֹרַיְיתָא לְיִשְׂרָאֵל.","אָמַר רַבִּי חִיָּיא נֹחַ דְּהֲוָה צַדִּיק אַמַּאי לָא הֲוָה בָּטִיל מוֹתָא מֵעָלְמָא. אֶלָּא בְּגִין דְּעַד לָא סָלְקַת זוּהֲמָא מֵעָלְמָא. וְעוֹד דְּאִנּוּן לָא הֲווּ מְהֵימְנִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וְכֻלְהוּ אֲחִידָן בְּטַרְפֵּי אִילָנָא לְתַתָּא וּמִתְלַבְּשָׁאן בְּרוּחַ מְסָאֳבָא.","וְתוּ לְבָתַר אוֹסְפוּ לְמֶחטֵי וּלְמֵהַךְ בָּתַר יֵצֶר הָרָע כַּד בְּקַדְמִיתָא: וְאוֹרַיְיתָא קַדִּישָׁא דְּאִיהִי אִילָנָא דְחַיֵּי אַכַּתֵּי לָא נָחִית לָהּ קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא. וְתוּ דְּאִיהוּ אַמְשִׁיךְ לֵיהּ בְּעָלְמָא לְבָתַר דִּכְתִיב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל בְּתוֹךְ אָהֳלה וְהָא אִתְּמָר.","עַד דְּהֲווּ אָזְלֵי, חָמוּ חַד יוּדָאי דְּהֲוָה אָתֵי. אָמַר רַבִּי יוֹסֵי הַאי בַּר נָשׁ יוּדָאי אִיהוּ וְאִתְחֲזֵי. כַּד מָטָא גַּבַּיְיהוּ שְׁאִילוּ לֵיהּ. אָמַר לוֹן שְׁלִיחָא דְמִצְוָה אֲנָא. דְּהָא אֲנַן דָּיְירֵי בִּכְפַר דְּרָאמִין, וּמָטֵי זִמְנָא דְחַג, וְאֲנַן צְרִיכִין לוּלָב וְזִינִין דְּעִמֵּיהּ, וְאֲנָא אָזִיל לְקָטְעָא לוֹן לְמִצְוָה. אֲזְלוּ כְּחֲדָא.","אָמַר לְהוּ הַהוּא יוּדָאי הַנִּי אַרְבַּע מִינִין דְּלוּלָב דְּבְּכֻלְהוֹ אָתָאן לְרַצוּיֵי עָלְמָא (נ\"א על מיא) שְׁמַעְתּוּן אַמַּאי אֲנַן צְרִיכִין לוֹן בַּחַג. אָמַר לֵיהּ כְּבָר אִתְעָרוּ בְּהוּ חַבְרַיָיא. אֲבָל אִי מִלָּה חַדְתָּא אִיהוּ תְּחוֹת יְדָךְ אֵימָא לָהּ.","אָמַר לוֹן וַדַּאי הַהוּא אֲתַר דְּאֲנַן דָּיְירֵי בֵּיהּ הוּא זְעֵיר וְכֻלְהוּ עָסְקֵי בְּאוֹרַיְיתָא. וְאִית עֲלָן צוּרְבָא מֵרַבָּנָן רַבִּי יִצְחָק בַּר יוֹסֵי מֵחוֹזָאָה שְׁמֵיהּ. וּבְכָל יוֹמָא וְיוֹמָא אָמַר לָן מִלִּין חַדְתִּין בְּאוֹרַיְיתָא. וְאָמַר דְּהָא בְּחַג זִמְנָא הוּא לְשַׁלְטָאָה. (ישראל שליטין בההוא זמנא, ונקיטנא לולב דמתחזי דאנן נציחנא עלייהו על כל אנון דאקרון הממ העם ולשלטאה עלייהו) (אזי עבר על נפשנו המים הזדונים ברוך יי שלא נתננו טרף לשניהם. וכי אית שנים למים, אלא) (ס\"א דכל אנון רברבין) אִנּוּן שְׁאָר עַמִּין. אִנּוּן רַבְרְבִין מְמַנָּן עַל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וּמִתְבָּרְכָאן מִסִּטְרַיְיהוּ דְיִשְׂרָאֵל וְקָרִינָן לוֹן מַיִם הַזֵּידוֹנִים. כְּמָא דְאַתְּ אָמֵר, (תהילים קכ״ד:ה׳) הַמַּיִם הַזֵּדוֹנִים.","וּבְגִין לְשַׁלְטָאָה עֲלַיְיהוּ אָתֵינָא בְּרָזָא דִשְׁמָא קַדִּישָׁא בְּאִנּוּן אַרְבַּע מִינִין שֶׁבַּלּוּלָב לְרַצּוּיֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא (עלייהו) וּלְשַׁלְטָאָה עֲלַיְיהוּ בְּרָזָא דִשְׁמָא קַדִּישָׁא. וּלְאַתְעָרָא עֲלָן מַיִין קַדִּישִׁין לְנַסְכָא עַל גַּבֵּי מַדְבְּחָא."],[[0,"ומה דאמר וכו':","ומה שאומר הכתוב לישה היינו עניה ענתות, כלומר לישה ועניה ענתות היינו הך, עניה ענתות, פירושו עניות שבעניות כמש\"ה מן הכהנים אשר בענתות, וכתוב ענתות לך על שדך, שענתות האלו פירושם עניות. אף כאן, פירושו עניות. ושואל, מה משמיענו שלמה במה שקראו ענתות. שלא מצינו לו לאביתר שהיה נקרא כן עד הנה, ומשיב. אלא כל זמן שדוד המלך היה חי, נתעלה אביתר בעושר ובכל. לאחר כך דהיינו אחר שמת דוד נעשה עני. אמר לו שלמה. ענתות לך על שדך. ומיושב בזה שעד עתה, כל עוד שדוד המלך היה חי, לא נקרא בשם ענתות, כי היה עושר. אלא אחר מיתתו של דוד נעשה עני, וקראו שלמה ענתות."],[1,"אמאי קרי וכו':","שואל סוף סוף, למה קרא לו שלמה כן, בשם ענתות ומה לו לקרוא אותו בשם בזיון. ומשיב אלא אמר לו בימיך היה אבי בעניות, ועתה שאני עשיר לך על שדך. כי מי ששימש בימי עוני אינו ראוי שישמש בימי עושר. ואומר עתה יש לפרש כלומר לפי\"ז יש לפרש למה נקרא אביתר ענתות, אם תאמר, משום שהיה מן ענתות, הנה למדנו, שכתוב וימלט בן אחד וגו' והוא היה מנוב. שהרי נוב היה עיר הכהנים. ואע\"פ שאמרו, היא נוב היא ענתות, ולמה נקראת ענתות, משום שירדה לעניות, והעיר נאבדה על ידי שאול והכהנים נאבדו, מ\"מ אינו כך, אלא ענתות כפר היה והוא אינו נוב וע\"כ קרא שלמה לאביתר ענתות, משום שאמר שלמה וכי התענית בכל אשר התענה אבי. ומעיר נוב היה, ועל שדוד היה בעניות בימיו, קרא אותו ענתות."],[2,"אמר וכו':","אר\"ח העולם היה בעניות, מיום שאדם עבר על מצות הקב\"ה, עד שבא נח והקריב קרבן, ונתיישב העולם. אמר רבי יוסי. לא נתיישב העולם, והארץ לא יצאה מזוהמת הנחש, עד שעמדו ישראל על הר סיני, ונתאחזו בעץ החיים, אז נתיישב להעולם."],[3,"ואלמלא וכו':","ואם לא חזרו ישראל וחטאו לפני הקב\"ה לא היו מתים לעולם, כי הוסרה מהם זוהמת הנחש כיון שחטאו, נשברו אז לוחות הראשונות שהיה בהם חירות מכל, חירות מאותו נחש, שהוא קץ כל בשר. דהיינו מלאך המות."],[4,"וכד קמו וכו':","וכשעמדו הלוים להרוג הרג, דהיינו בעת שאמר להם משה שימו איש חרבו על ירכו וגו', אז חזר ונתעורר נחש הרע, והיה הולך לפניהם ולא יכול למשול בהם, כי ישראל כולם, היו מזוינים בחגורות מזונינות, דהיינו כמ\"ש בזהר. לעיל (דפו\"י ח\"א נב: בראשית ב' אות רצ\"א בסולם) שבעת מתן תורה \u0003חגר לון קב\"ה חגורין דאתוון דשמיה קדישא, דלא יכול לשלטאה עלייהו האי חויא,\u0004 שהם העדי שקבלו מהר חורב, ע\"ש. וע\"כ, לא היה יכול הנחש למשול עליהם. וכיון שאמר למשה, ועתה הורד עדיך מעליך, ניתן רשות להנחש למשול עליהם."],[5,"ת\"ח מה וכו':","בא וראה, מה כתוב, ויתנצלו בני ישראל את עדים מהר חורב, ושואל כתוב. ויתנצלו, וינצלו, היה צריך לכתוב, ואומר. אלא ויתנצלו יורה שנתנצלו ע\"י כח אחר, כי ניתן רשות להנחש למשול עליהם. את עדים מהר חורב. פירושו, העדי שקבלו מהר חורב כאשר ניתנה התורה לישראל."],[6,"אמר וכו':","אר\"ח נח שהיה צדיק, למה לא ביטל המות מהעולם כמו שהיה במתן תורה. ואומר, אלא שהוא משום שזוהמת הנחש עוד לא יצאה מהעולם, ועוד שבני העולם עוד לא היה להם אמונה בהקב\"ה, והיו נאחזים כולם בעלי האילן למטה שהם כחות החיצונים והיו מתלבשים ברוח הטומאה."],[7,"ותו וכו':","ועוד שאחר כך, שיצאו מן התיבה, הוסיפו לחטא וללכת אחר היצה\"ר כבתחילה, והתורה הקדושה, שהיא עץ החיים, עוד לא הוריד אותה הקב\"ה בארץ. ועוד שהוא עצמו חזר והמשיך המות לעולם. שכתוב ו ישת מן היין וגו', והוא כבר נתבאר."],[8,"עד דהוו וכו':","בעוד שהיו הולכים, ראו שהיה בא לנגדם יהודי אחד, אמר ר\"י אדם זה הוא יהודי, שהוא נראה כיהודי. כשהגיע אליהם, שאלו לו מי הוא. אמר להם שליח מצוה אני, כי אנו יושבים בכפר דראמין, והגיע זמן החג, וצריכים אנחנו לולב והמינים שעמו, ואני הולך לקצץ אותם לשם מצוה. הלכו יחד."],[9,"א\"ל ההוא וכו'","אמר להם אותו היהודי אלו ד' מינים שבלולב, שבכולם באים לרצות בעד העולם, השמעתם למה אנו צריכים להם בחג, ולא בזמן אחר. אמרו לו. כבר העירו בהם החברים לומר טעמם. אבל אם יש דבר חדש תחת ידך אמור אותו."],[10,"אמר לון וכו':","אמר להם, אותו המקום שאנו יושבים בו, ודאי הוא קטן. אבל כולם עוסקים בתורה. ויש עלינו רב, מצוין בהרבנים, ושמו רבי יצחק בר יוסי מחוזאה, ובכל יום ויום, הוא אומר לנו דברים חדשים בתורה. ואמר, כי בחג הגיע הזמן לממשלה. כלומר שישראל ישלטו על השרים של ע' אומות, וכתוב, אזי עבר על נפשנו המים הזידונים ברוך ה' שלא נתננו טרף לשיניהם, ושואל וכי יש שינים למים. ואומר, אלא מים זידונים הם שאר העמים, ושינים הם השרים הממונים על שאר העמים עכו\"ם, והם מתברכים מצדם של ישראל."],[11,"ובגין לשלטאה וכו'.","ובכדי למשול אליהם על שרי האומות, אנו באים בסוד השם הקדוש, המרומז באילו ארבעה מינים שבלולב. הדסים ה\"ס חג\"ת מ \u0003הי'\u0004 דשם הויה, ערבות ה\"ס נו\"ה הנמשכים מ \u0003הה'\u0004 דהוי\"ה, לולב ה\"ס יסוד מה \u0003ו'\u0004 דהויה, אתרוג ה\"ס מלכות \u0003ה'\u0004 תתאה, לרצות לו להקב\"ה, ולמשול עליהם בסוד השם הקדוש. ולעורר עלינו מים קדושים דהיינו שפע מים העליונים לנסך אותם על המזבח. שהיא המלכות. המכניעים את המים הזידונים, הנ\"ל."]],[[0,"","וּמַה שֶּׁאָמַר לַיְשָׁה, הַיְנוּ עֲנִיָּה עֲנָתוֹת, עֹנִי שֶׁל עֲנִיּוּת, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה א) מִן הַכֹּהֲנִים אֲשֶׁר בַּעֲנָתוֹת, וְכָתוּב (מלכים א ב) עֲנָתֹת לֵךְ עַל שָׂדֶיךְ. מַה מַּשְׁמִיעֵנוּ? אֶלָּא כָּל זְמַן שֶׁהַמֶּלֶךְ דָּוִד הָיָה קַיָּם, עָלָה אֶבְיָתָר בְּעֹשֶׁר וּבַכֹּל. אַחַר כָּךְ אָמַר לוֹ שְׁלֹמֹה, עֲנָתֹת לֵךְ עַל שָׂדֶיךְ."],[1,"","לָמָּה קָרָא לוֹ שְׁלֹמֹה כָּךְ? אֶלָּא אָמַר לוֹ, בְּיָמֶיךְ הָיָה אַבָּא בְּעֹנִי, וְעַכְשָׁו לֵךְ עַל שָׂדֶיךְ. כָּעֵת יֵשׁ לוֹמַר, לָמָּה נִקְרָא אֶבְיָתָר עֲנָתוֹת? אִם תֹּאמַר שֶׁהָיָה מֵעֲנָתוֹת, הֲרֵי שָׁנִינוּ שֶׁכָּתוּב (שמואל א כב) וַיִּמָּלֵט בֵּן אֶחָד לַאֲחִימֶלֶךְ בֶּן אֲחִטוּב וּשְׁמוֹ אֶבְיָתָר. וְהוּא מִנּוֹב הָיָה, שֶׁהֲרֵי נוֹב הָיְתָה עִיר הַכֹּהֲנִים. וְאַף עַל פִּי שֶׁאָמְרוּ, הִיא נוֹב הִיא עֲנָתוֹת, וְלָמָּה נִקְרֵאת עֲנָתוֹת? מִשּׁוּם שֶׁיָּרְדָה לְעֹנִי וְאָבְדָה הָעִיר עַל יְדֵי שָׁאוּל וְאָבְדוּ הַכֹּהֲנִים. אֶלָּא עֲנָתוֹת כְּפָר הָיָה, וְאֵינָהּ נוֹב, וְלָכֵן קָרָא לָהּ אֶבְיָתָר עֲנָתוֹת, מִשּׁוּם שֶׁאָמַר (מלכים א ב) וְכִי הִתְעַנִּיתָ בְּכֹל אֲשֶׁר הִתְעַנָּה אָבִי. וְהוּא הָיָה מֵהָעִיר נוֹב, וְעַל הָעֹנִי שֶׁל דָּוִד שֶׁהָיָה לוֹ בְּיָמָיו קָרָא לוֹ כָּךְ."],[2,"","אָמַר רַבִּי חִיָּיא, הָעוֹלָם הָיָה בְּעֹנִי מִיּוֹם שֶׁעָבַר אָדָם עַל מִצְווֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁבָּא נֹחַ וְהִקְרִיב קָרְבָּן וְהִתְיַשֵּׁב הָעוֹלָם. אָמַר רַבִּי יוֹסֵי, לֹא הִתְיַשֵּׁב הָעוֹלָם וְלֹא יָצְאָה הָאָרֶץ מִזֻּהֲמַת הַנָּחָשׁ, עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי וְנֶאֶחְזוּ בְּעֵץ הַחַיִּים, וְאָז הִתְיַשֵּׁב הָעוֹלָם."],[3,"","וְאִלְמָלֵא שֶׁחָזְרוּ יִשְׂרָאֵל וְחָטְאוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הָיוּ מֵתִים לְעוֹלָמִים, שֶׁהֲרֵי נִפְסְקָה מֵהֶם זֻהֲמַת הַנָּחָשׁ. כֵּיוָן שֶׁחָטְאוּ, אָז נִשְׁבְּרוּ אוֹתָם הַלּוּחוֹת הָרִאשׁוֹנִים שֶׁהָיְתָה בָּהֶם חֵרוּת שֶׁל הַכֹּל, הַחֵרוּת מֵאוֹתוֹ הַנָּחָשׁ שֶׁהוּא קֵץ כָּל בָּשָׂר."],[4,"","וּכְשֶׁקָּמוּ הַלְוִיִּם לַהֲרֹג הֶרֶג, אָז הִתְעוֹרֵר הַנָּחָשׁ הָרָע וְהָיָה הוֹלֵךְ לִפְנֵיהֶם, וְלֹא יָכֹל לִשְׁלֹט בָּהֶם, מִשּׁוּם שֶׁיִּשְׂרָאֵל הָיוּ מִזְדָּרְזִים כֻּלָּם בַּחֲגוֹרוֹת מְזֻיָּנוֹת, וְלֹא יָכֹל הַנָּחָשׁ לִשְׁלֹט בָּהֶם. וְכֵיוָן שֶׁאָמַר לְמֹשֶׁה (שמות לג) וְעַתָּה הוֹרֵד עֶדְיְךְ מֵעָלֶיךְ, נִתְּנָה רְשׁוּת לַנָּחָשׁ הַזֶּה לִשְׁלֹט עֲלֵיהֶם"],[5,"","בֹּא רְאֵה מַה כָּתוּב (שם), וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חֹרֵב. וַיִּתְנַצְּלוּ? וַיְנַצְּלוּ צָרִיךְ לִהְיוֹת! אֶלָּא וַיִּתְנַצְּלוּ עַל יְדֵי הָאַחֵר, מִשּׁוּם שֶׁנִּתְּנָה רְשׁוּת לַנָּחָשׁ לִשְׁלֹט. אֶת עֶדְיָם מֵהַר חֹרֵב, שֶׁקִּבְּלוּ מֵהַר חוֹרֵב כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל."],[6,"","אָמַר רַבִּי חִיָּיא, נֹחַ שֶׁהָיָה צַדִּיק, לָמָּה לֹא הָיָה מְבַטֵּל מָוֶת מֵהָעוֹלָם? אֶלָּא מִשּׁוּם שֶׁעֲדַיִן לֹא הִסְתַּלְּקָה הַזֻּהֲמָה מִן הָעוֹלָם. וְעוֹד, שֶׁהֵם לֹא הֶאֱמִינוּ בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וְכֻלָּם אֲחוּזִים בֶּעָלִים שֶׁל הָאִילָן לְמַטָּה וּמִתְלַבְּשִׁים בְּרוּחַ טֻמְאָה."],[7,"","וְעוֹד הוֹסִיפוּ אַחַר כָּךְ לַחֲטֹא וְלָלֶכֶת אַחַר יֵצֶר הָרָע כְּבָרִאשׁוֹנָה. וְהַתּוֹרָה הַקְּדוֹשָׁה, שֶׁהִיא עֵץ הַחַיִּים, עֲדַיִן לֹא הוֹרִיד אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָרֶץ, וְעוֹד שֶׁהוּא מָשַׁךְ אוֹתוֹ בָּעוֹלָם אַחַר כָּךְ, שֶׁכָּתוּב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה, וַהֲרֵי נִתְבָּאֵר."],[8,"","עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ יְהוּדִי אֶחָד שֶׁהָיָה בָּא. אָמַר רַבִּי יוֹסֵי, הָאִישׁ הַזֶּה הוּא יְהוּדִי וְנִרְאֶה. כְּשֶׁהִגִּיעַ אֲלֵיהֶם, שָׁאֲלוּ אוֹתוֹ. אָמַר לָהֶם, אֲנִי שְׁלִיחַ מִצְוָה, שֶׁהֲרֵי אָנוּ גָרִים בִּכְפָר רָאמִין, וְהִגִּיעַ זְמַן הֶחָג, וְאָנוּ צְרִיכִים לוּלָב עִם הַמִּינִים שֶׁלּוֹ עִמּוֹ, וַאֲנִי הוֹלֵךְ לִקְטֹף אוֹתָם לְמִצְוָה. הָלְכוּ כְּאֶחָד."],[9,"","אָמַר לָהֶם אוֹתוֹ יְהוּדִי, אַרְבַּעַת מִינֵי הַלּוּלָב הַלָּלוּ שֶׁבְּכֻלָּם בָּאִים לְרַצּוֹת בְּעַד הָעוֹלָם (נ\"א: על המים), שְׁמַעְתֶּם לָמָּה אָנוּ צְרִיכִים אוֹתָם בֶּחָג? אָמַר לוֹ, כְּבָר הֵעִירוּ בָזֶה הַחֲבֵרִים, אֲבָל אִם דָּבָר חָדָשׁ הוּא תַּחַת יָדְךְ - אֱמֹר אוֹתָהּ."],[10,"","אָמַר לָהֶם, וַדַּאי אוֹתוֹ מָקוֹם שֶׁאָנוּ גָרִים בּוֹ הוּא קָטָן, וְכֻלָּם עוֹסְקִים בַּתּוֹרָה, וְיֵשׁ עָלֵינוּ תַּלְמִיד חָכָם וּשְׁמוֹ רַבִּי יִצְחָק בַּר יוֹסֵי מָחוֹזָאָה, וּבְכָל יוֹם וָיוֹם אוֹמֵר לָנוּ דִּבְרֵי תוֹרָה חֲדָשִׁים, וְאָמַר שֶׁהֲרֵי בֶּחָג זְמַן הוּא לִשְׁלֹט. (ישראל שולטים באותו זמן ולוקחים לולב שמראה שאנו נצחנו על כל אותם שנקראים המון העם ולשלט עליהם) (אזי עבר על נפשנו המים הזידונים ברוך ה' שלא נתננו טרף לשניהם, וכי יש שנים למים? אלא) (שכל אותם גדולים) אוֹתָם שְׁאָר הָעַמִּים. אוֹתָם מְמֻנִּים גְּדוֹלִים עַל שְׁאָר הָעַמִּים עַכּוּ\"ם, וּמִתְבָּרְכִים מִצִּדָּם שֶׁל יִשְׂרָאֵל, וְקוֹרְאִים לָהֶם מַיִם הַזֵּידוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכד) הַמַּיִם הַזֵּידוֹנִים."],[11,"","וּבִשְׁבִיל לִשְׁלֹט עֲלֵיהֶם בָּאנוּ בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ בְּאוֹתָם אַרְבָּעָה מִינֵי הַלּוּלָב לְרַצּוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא (עליהם) וְלִשְׁלֹט עֲלֵיהֶם בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ, וּלְהָעִיר עָלֵינוּ מַיִם קְדוֹשִׁים לְנַסֵּךְ עַל גַּבֵּי הַמִּזְבֵּחַ."]]],[["תּוּ אָמַר לוֹן בְּרֹאשׁ הַשָּׁנָה אִתְעֲרוּתָא קַדְמָאָה אִיהוּ בְּעָלְמָא. מַאי אִתְעֲרוּתָא קַדְמָאָה. דָּא בֵּי דִינָא דִּלְתַתָּא (נ\"א דא ראש השנה ממש) דְּאִתְעַר לְמֵידַן עַלְמָא. וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל עָלְמָא בְּדִינָא וְדָאִין עָלְמָא.","וְשָׁלְטָא הַאי בֵּי דִינָא לְמֵידַן עָלְמָא, עַד יוֹמָא דְכִפּוּרֵי דְּנָהֲרִין אַנְפָּהָא, וְלָא אִשְׁתְּכַח חִוְיָא דַּלְטוֹרָא בְּעָלְמָא. דְּאִיהוּ אִתְעַסַּק בַּמֶה דְאַתְיָין לֵיהּ הַהוּא שָׂעִיר דְּאִיהוּ מִסִּטְרָא דְּרוּחַ מְסָאֳבָא כְּדְקָא חָזֵי לֵיהּ. וּבְגִין דְּאִתְעַסַּק בְּהַהוּא שָׂעִיר לָא קָרִיב לְמַקְדְּשָׁא.","וְשָׂעִיר דָּא כְּהַהוּא שָׂעִיר דְּרֹאשׁ חֹדֶשׁ דְּאִתְעַסַּק בֵּיהּ וְאַנְהִירוּ אַנְפָּהָא דְרֹאשׁ הַשָׁנָה (נ\"א כך בראש השנה) (נ\"א אנהירו) (אנפוי דמקדשא). וְעַל דָּא יִשְׂרָאֵל כֻּלְהוּ מַשְׁכְּחִין רַחֲמֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִתְעֲבַר חוֹבַיְיהוּ. וְרָזָא חָדָא אָמַר לוֹן וְלָא אִתְיְיהִיב רְשׁוּ לְגַלָּאָה בַּר לְחֲסִידֵי קַדִּישִׁין עֶלְיוֹנִין חַכִּימִין. אָמַר רַבִּי יוֹסֵי מַאן אִיהוּ. אָמַר לוֹן עַד לָא בָּדִיקְנָא בְּכוּ.","אֲזְלוּ. לְבָתַר אָמַר לוֹן. כַּד סִיהֲרָא אִתְקְרִיבַת בְּשִׁמְשָׁא. אַתְעַר קוּדְשָׁא בְּרִיךְ הוּא סִטְרָא דְצָפוֹן וְאָחִיד בָּהּ בִּרְחִימוּ וּמָשִׁיךְ לָהּ לְגַבֵּיהּ, וְדָרוֹם אִתְעַר מִסִּטְרָא אָחֳרָא. וְסִיהֲרָא סַלְקָא וּמִתְחַבְּרָא בְּמִזְרָח. וּכְדֵין יָנְקָא מִתְּרֵין סִטְרִין וּנְטִילַת בִּרְכָאן בַּחֲשַׁאי, וּכְדֵין אִתְבָּרְכָא סִיהֲרָא וְאִתְמַלְיָיא. וְהָכָא אִתְקְרִיבַת אִתְּתָא בְּבַעֲלָהּ.","כְּמָה דְאִית רָזָא דִּיוּקְנָא שַׁיְיפֵי (נ\"א בתיקוני דשייפי) דְאָדָם וְתִיקּוּנוֹי. הָכִי נָמֵי אִית (נ\"א איהו) רָזָא דְּדִיוּקְנָא דְּשַׁיְיפֵי נוּקְבָא וְתִקּוּנִי דְנוּקְבָא. וְכֹלָּא פָּרִישׁ בְּגַוָון. הָכִי נָמֵי אִית לְעֵילָא (ד\"א מאן) אָחִיד בָּהּ וְאִתְעַר לָקֳבֵל בִּרְחִימוּ הָכִי נֲמֵי אִית לְתַתָּא רָזָא וְתִקּוּנָא דְּאָדָם תַּתָּאָה אָחֳרָא תְּחוֹת סִיהֲרָא (ד\"א ותקונא דנוקבא).","כְּמָה דִדְרוֹעָא שְׂמָאלָא (תשא קצד ב, פקודי רלג ב) לְעֵילָא אָחִיד בָּהּ וְאִתְעַר לְקֳבְלָהּ בִּרְחִימוּ. הָכִי נָמֵי אִית לְתַתָּא. (ווי העמודים כלהו קיימי שייפין לאתאחדא דא בדא ולאתקשרא דא בדא קשרי מהימנותא סטרא דקדושא מסטרא דרוח מסאבא דאיהו רזא דנחש לתתא). הַאי נָחָשׁ אִיהוּ דְרוֹעָא שְׂמָאלָא דְרוּחַ מְסָאֳבָא. וְאָחִיד בֵּיהּ מַאן דְּרָכִיב בֵּיהּ וְקָרָבָא לְגַבֵּי דְסִיהֲרָא וּמָשִׁיךְ לָהּ בֵּינַיְיהוּ נ\"א בִּדְבִיקוּ דְּקוּטְפָא וְאִסְתָּאֳבַת.","וּכְדֵין יִשְׂרָאֵל לְתַתָּא מְקָרְבִין שָׂעִיר. וְהַהוּא נָחָשׁ אִתְמְשַׁךְ אֲבַתְרֵיהּ דְּהַהוּא שָׂעִיר. וְסִיהֲרָא אִתְדְּכִיאַת וְסַלְקָאת לְעֵילָא וְאִתְקְּשָׁרַת לְעֵילָא לְאִתְבָּרְכָא. וּנְהִירִין אַנְפָּהָא מַה דְּאִתְחַשְׁכַת לְתַתָּא.","כְּדֵין הָכָא בְּיוֹמָא דְכִפּוּרֵי כֵּיוָן דְּהַהוּא חִוְיָא בִּישָׁא אִתְעַסַּק בְּהַהוּא שָׂעִיר. סִיהֲרָא אִתְפָּרְשַׁת מִנֵּיהּ וְאִתְעַסְּקַת (בישראל) לְאוֹלָפָא עֲלַיְיהוּ סָנֵיגוֹרְיָא וְסוֹכֶכֶת עֲלַיְיהוּ כְּאִמָּא עַל בְּנִין. וְקוּדְשָׁא בְּרִיךְ הוּא בָּרִיךְ לוֹן מִלְּעֵילָא וּמָחִיל לוֹן.","לְבָתַר יִשְׂרָאֵל כַּד מָטוּ לַחַג מִתְעָרֵי סִטְרָא דְּיָמִינָא לְעֵילָא. בְּגִין דְּיִתְקַשַּׁר בֵּיהּ סִיהֲרָא וְיִתְנְהִירוּ אַנְפָּהָא כְּדְקָא חָזֵי. וּכְדֵין פַּלְגַת (יהב) חוּלָקָא דְּבִרְכָאן לְכָל אִנּוּן מְמַנָּן דִּלְתַתָּא דְּיִתְעַסְּקוּן בְּחוּלַקְהוֹן. וְלָא יֵיתוּן לְיָנְקָא וּלְקָרָבָא בְּסִטְרָא דְּחוּלַקְהוֹן דְּיִשְׂרָאֵל.","כְּגַוְונָא דָא לְתַתָּא כַּד שְׁאָר עַמִין אִתְבָּרְכוּן. כֻּלְהוֹן אִנּוּן מִתְעַסְּקִין בְּאַחְסָנַת חוּלַקְהוֹן. וְלָא הֲווּ אַתְיָין לְאִתְעָרְבָא בַּהֲדַיְיהוּ דְיִשְׂרָאֵל וּלְחָמְדָא חוּלַק אַחְסַנְתֵּיהוֹן. וּבְגִין כָּךְ יִשְׂרָאֵל אִנּוּן מָשְׁכִין בִּרְכָאן לְכָל אִנּוּן מְמַנָּן בְּגִין דְּיִתְעַסְּקוּן בְּחוּלַקְהוֹן וְלָא יִתְעָרְבוּן בַּהֲדַיְיהוּ.","וְכַד סִיהֲרָא אִתְמְלֵי בִּרְכָאן לְעֵילָא כְּדְקָא יְאוּת. יִשְׂרָאֵל אָתְיָין וְיָנְקִין מִינָּהּ בִּלְחוֹדַיְיהוּ. וְעַל דָּא כְּתִיב (במדבר כ״ט:ל״ה) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. מַאי עֲצֶרֶת, כְּתַרְגּוּמוֹ כְּנִישׁוּ. כָּל מַה דִּכְנִישׁוּ מֵאִנּוּן בִּרְכָאן עִלָּאִין. לָא יָנְקִין מִנֵּיהּ עַמִּין אָחֳרָנִין בַּר יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. וּבְגִין כָּךְ כְּתִיב עֲצֶרֶת תִּהְיֶה לָכֶם. לָכֶם וְלָא לִשְׁאָר עַמִּין. לָכֶם וְלָא לִשְׁאָר מְמַנָּן.","וְעַל דָּא אִנּוּן מְרַצִּין עַל הַמַּיִם לְמֵיהַב לוֹן חוּלַק בִּרְכָאן דְּיִתְעַסְּקוּן בֵּיהּ. וְלָא יִתְעָרְבוּן לְבָתַר בְּחֶדְוָותָא דְיִשְׂרָאֵל כַּד יָנְקִין בִּרְכָאן עִלָּאִין. וְעַל הַהוּא יוֹמָא כְּתִיב דּוֹדִי לִי וַאֲנִי לוֹ. דְּלָא אִתְעָרַב אוֹחֲרָא בַּהֲדָן."],[[0,"תו אמר לון וכו'","עוד אמר להם, בראש השנה, התעוררות הראשון חוזר ובא בעולם שהיא הנוקבא. כלומר. הנוקבא חוזרת לקדמותה כמו שהיתה ביום ד' דמע\"ב. ושואל, מהו התעוררות הראשון. ואמר, זה בית דין שלמטה, שנתעורר לדין העולם, והקב\"ה יושב על כסא הדין ודן את העולם. פירוש. הנוקבא נקראת בית, וביום ד' דמעשה בראשית מטרם שניבנית, היתה מחזה ולמטה דז\"א באחוריו, ואז היתה מלאה דינים ונקראת בית דין שלמטה, דהיינו למטה מחזה, וע\"כ היא דן את העולם בדין, וכן ז\"א יושב אז על כסא דין ודן את העולם ומצב הזה נקרא, אתערותא קדמאה."],[1,"ושלטא וכו':","ובית דין זה שולט לדון העולם עד יום הכיפורים, שאז פניה מאירים דהיינו שמשגת ג\"ר הנק' פנים, ונחש המקטרג אינו נמצא בעולם שהוא מתעסק באותו שעיר לעזאזל שמביאים לו, שהוא מצד רוח הטומאה, כראוי לו. להמקטרג. ומשום שמתעסק באותו השעיר, אינו קרב למקדשא, שהיא הנוקבא. כלומר, אינו קרב לקטרג על ישראל ולהפריד הזווג של ז\"א ונוקבא."],[2,"ושעיר דא וכו':","ושעיר הזה הוא כמו שעיר החטאת של ראש חודש, כי מתעסק בו, וע\"כ מאירים הפנים של המקדש, שהיא הנוקבא. וע\"כ ישראל כולם מוצאים רחמים לפני הקב\"ה ומעביר עונם. ועל סוד אחד, אמר להם, אותו היהודי, שלא ניתן רשות לגלותו חוץ לחסידים קדושים עליונים החכמים. א\"ל רבי יוסי, מה הוא הסוד. אמר להם, עוד לא בדקתי אתכם, ואיני יודע, אם אתם ראוים לשמוע סוד הזה."],[3,"אזלו, לבתר וכו':","הלכו. אחר כך אמר להם, כאשר הלבנה שהיא הנוקבא נקרבת אל השמש שהוא ז\"א, מעיר הקב\"ה את צד הצפון, שהוא קו השמאל, הנמשך מנקודת השורק, ואוחז בה באהבה, ומושך אותה אצלו. שה\"ס הפיוסא ונטילת רשות, כנ\"ל (בראשית ב' דף קל\"ו אות רט\"ו ד\"ה פנימיות) והדרום, שהוא קו ימין, נתעורר מצד אחר, מצד נקודת החירק, והלבנה, היא הנוק' עולה ומתחברת במזרח, שהוא ז\"א, ואז יונקת משני הצדדים, מדרום ומצפון, ולוקחת הברכות, דהיינו שפע הזווג, בלחש. שהיא בחי' ו\"ק מכח נקודת החירק, שה\"ס וקולה לא ישמע. כי קול ודיבור פירושו ג\"ר. ואז מתברכת הלבנה ומתמלאת משפע, וכאן מתקרבת האשה לבעלה כלומר, זה הוא זווג שלם המשפיע מוחין שלמים להעולם. (וענין ג' הנקודות המרומזים כאן, (עי' לעיל בראשית א' דף ט\"ו ד\"ה אות ט' ההיא נקודה) ומשמיענו בזה, שסדר הזווג הוא שמתחילה ממשיך ז\"א להנוקבא, הארת קו השמאל, שהסוה\"כ שמאלו תחת לראשי. ואח\"כ את קו הימין, שה\"ס וימינו תחבקני, ומשמאל נמשך הארת החכמה, ומימין חסדים כנודע. ואח\"כ מבאר. איך הנחש מתאחז בעת הארת קו השמאל, כמ\"ש לפנינו."],[4,"כמה דאית וכו':","כמו שיש סוד צורות איברי אדם, דהיינו ז\"א, ותקוניו, כן יש סוד צורות אברי הנוקבא דז\"א, ותקוני הנוקבא. וכל ההפרש הוא רק בהגוון, שז\"א ה\"ס גוון ירוק. ונוקביה, ה\"ס גוון אדום. אמנם בצורות האברים הם שוים. וכמו כן יש למטה, מאצילות, סוד תקון אדם תחתון אחר, מסטרא אחרא, שמתחת הלבנה. שיש בו אותן צורות אברים, דהיינו ימין ושמאל וכדומה. ומשמעינן בזה, שהמדרגות נחתמות זו מזו, והצורות שבעליונה עוברות על התחתונה, והתעוררות כל בחינה שבאחת מהן, מעוררת הבחינה שכנגדה באחרות. כמו שמבאר לפנינו."],[5,"כמה דדרועא וכו':","כמו שזרוע השמאל למעלה, בז\"א, אוחז בה בהנוקבא, ומתעורר כנגדה באהבה, כן יש למטה, מהנוקבא, נחש הזה, שהוא זרוע שמאל של רוח הטומאה, והוא הנוקבא דטומאה. ואוחז בו, מי שרוכב עליו, שהוא הזכר דטומאה, המזדווג עם הנחש. והוא קרב אז אל הלבנה שהיא הנוקבא, ומושך אותה, היינו שיונק ממנה, מבין הדבקים, דהיינו ממקום הזווג, ונטמאת, פירוש, כי ב' נקודות הן בהנוקבא: אחת, דמדת הדין, שאינה ראויה לקבל מוחין מכח צמצום א', והיא גנוזה בה, ואחת דמדת הרחמים, מהבינה, שבה מקבלת כל המוחין ומאירה לעולם, והיא גלויה בהנוקבא. וע\"כ היא נקראת עץ הדעת טוב ורע, כי אם \u0003זכי ברנש הא טוב, ואי לא זכי הא רע.\u0004 שפירושו, אם האדם מקבל הארת השמאל בתקוני הקדושה, שהוא ממטה למעלה, אז הוא טוב, שמקבל ממנה כל המוחין בשלמות. ואם לא זכי, אלא שממשיך המוחין ממעלה למטה, אז מתקרב הנחש אל הנוקבא, ומגלה את הנקודה דמדת הדין שבה. שאינה ראויה לקבל מוחין ושפע מז\"א, מכח צמצום א' כנ\"ל, ומחמתה מתקלקלת גם נקודה הב' דמדת הרחמים, וע\"כ נפרד הזווג, ונבחנת כמו שנטמאה, ואינה ראויה עוד להזדווג ולקבל שפע מז\"א. (ועיין כל זה לעיל בהקדמת הזהר דף קכ\"ג באות קכ\"ב ו קכ\"ג ובהסולם שם) וז\"ש כאן, \u0003וקרבא לגבי דסיהרא ומשיך לה בינייהו דקוטפא ואסתאבת.\u0004 דהיינו שמגלה את הנקודה דמדת הדין הגנוזה בין הדבקים. ואז \u0003ואסתאבת,\u0004 כלומר שאינה יכולה עוד להזדווג ולקבל שפע בשביל העולם, כמבואר."],[6,"וכדין ישראל וכו'","ואז ישראל למטה מקריבים שעיר, בר\"ח, שע\"י השעיר. ממשיכים מיתוק המלכות בהבינה, והארת השמאל ממטה למעלה, ונחש ההוא נמשך אחרי אותו השעיר כי כל תאותו הוא להארת השמאל, והלבנה נטהרת, כי היא עתה ראויה לקבל שפע מז\"א בעלה, ועולית למעלה ונקשרת למעלה, דהיינו בז\"א, כדי להתברך, ופניה מאירים עתה, כלפי מה שנחשכה מקודם בהיותה למטה, מטרם שבאה בזווג עם ז\"א. ובזה נתבאר ענין שעיר ר\"ח, שהוא בא לטהר הנוקבא, דהיינו להמשיך לה הכלים דמדת הרחמים מבינה, עם הארת השמאל, שעי\"ז היא חוזרת לטהרתה. ואע\"פ, שהנחש יכול עוד לעורר הנקודה דמדה\"ד אחר שכבר נתגלתה לו' מ\"מ אינו עושה זאת, מחמת שאינו רוצה לקלקל את הארת השמאל, שהוא תאב מאד להארה זו. ונמצא עתה שקטגור נעשה סנגור."],[7,"כדין הכא וכו':","כמו כן, גם כאן ביוהכ\"פ, כיון שאותו נחש הרע, מתעסק באותו שעיר לעזאזל, שהוא ג\"כ המשכת הארת השמאל כמו שעיר ר\"ח, (כנ\"ל באות ק') הלבנה נפרדת ממנו, מהנחש, כי נעסק בהשעיר ואינו רוצה עוד לקטרג עליה, כנ\"ל בדיבור הסמוך, והנוקבא עוסקת עתה ללמד זכות על ישראל ומסככת עליהם כאם על הבנים, והקב\"ה מברך אותם מלמעלה, ומוחל להם עונותיהם."],[8,"לבתר ישראל וכו':","ואח\"כ כשישראל מגיעים לחג הסוכות, מתעורר צד הימין של מעלה, בסו\"ה וימינו תחבקני כדי שהלבנה, דהיינו הנוקבא, תתקשר בו, בימין, ופניה יאירו כראוי, ואז מחלקת חלק מברכותיה לכל אלו הממונים של מטה, דהיינו ע' שרים, כדי שיתעסקו בחלקם. ולא יבוא לינק וליקרב לצד חלקם של ישראל. דהיינו על דרך שנתבאר אצל הנחש והנוקבא, שלהיותו מתעסק בהשעיר, אינו מקטרג על הנוקבא, כנ\"ל."],[9,"כגוונא דא וכו':","כעין זה למטה בעוה\"ז, כאשר שאר האומות כולם מתברכים, הם נעסקים בנחלת חלקם, ואינם באים להתערב עם ישראל ולחמוד את נחלת חלקם. דהיינו כמ\"ש בנחש והנוקבא, ובע' ממונים העליונים וישראל, כן הוא גם בין ע' האומות וישראל, ומשום זה בחג ע\"י הקרבת ע' פרים ממשיכים ישראל ברכות לכל אלו הממונים על ע' אומות. כדי שיתעסקו בחלקם, ולא יתערבו עמהם."],[10,"וכד סיהרא וכו':","וכאשר הלבנה מתמלאה עם ברכות למעלה כראוי, באים ישראל ויונקים ממנה בלבדם. וע\"כ כתוב ביום השמיני עצרת תהיה לכם, מהו עצרת, הוא כתרגומו, כנישו. דהיינו אוסף, כי כל מה שנאסף מהברכות העליונות אינם יונקים ממנה עמים אחרים חוץ מישראל בלבדו. ומשום זה כתוב עצרת תהיה לכם, שהמשמעות הוא לכם, ולא לשאר עמים. לכם ולא לשאר ממונים."],[11,"ועל דא אינון וכו':","ועל כל ישראל מרצים את הקב\"ה במים שמנסכים על המזבח. כדי לתת להממונים של האומות חלק מהברכות, שיתעסקו בו ולא יתערבו אח\"כ בשמחתם של ישראל כאשר ינקו ישראל ברכות העליונות. ועל יום זה כתוב, דודי לי ואני לו, שאחר אינו מתערב עמנו."]],[[0,"","עוֹד אָמַר לָהֶם, בְּרֹאשׁ הַשָּׁנָה הִתְעוֹרְרוּת רִאשׁוֹנָה הִיא בָּעוֹלָם. מַה זֶּה הִתְעוֹרְרוּת רִאשׁוֹנָה? זֶה בֵּית דִּין הַתַּחְתּוֹן (נ\"א: זה ראש השנה ממש) שֶׁמִּתְעוֹרֵר לָדוּן אֶת הָעוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל הָעוֹלָם בְּדִין וְדָן אֶת הָעוֹלָם."],[1,"","וְשׁוֹלֵט בֵּית הַדִּין (שלמטה) הַזֶּה לָדוּן אֶת הָעוֹלָם, עַד יוֹם הַכִּפּוּרִים שֶׁמְּאִירִים פָּנֶיהָ, וְלֹא נִמְצָא נָחָשׁ מַלְשִׁין בָּעוֹלָם, שֶׁהוּא מִתְעַסֵּק בְּמַה שֶּׁמְּבִיאִים לוֹ אוֹתוֹ הַשָּׂעִיר, שֶׁהוּא מִצַּד רוּחַ הַטֻּמְאָה כָּרָאוּי לוֹ. וּמִשּׁוּם שֶׁמִּתְעַסֵּק בְּאוֹתוֹ שָׂעִיר, לֹא קָרֵב לַמִּקְדָּשׁ."],[2,"","וְשָׂעִיר זֶה כְּמוֹ אוֹתוֹ שָׂעִיר שֶׁל רֹאשׁ חֹדֶשׁ שֶׁמִּתְעַסֵּק בּוֹ וּמְאִירוֹת פָּנֶיהָ שֶׁל רֹאשׁ הַשָּׁנָה (כך בראש השנה) (מאירים) (פני המקדש). וְעַל זֶה כָּל יִשְׂרָאֵל מוֹצְאִים רַחֲמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וַחֲטָאֵיהֶם מִתְבַּטְּלִים. וְסוֹד אֶחָד אָמַר לָנוּ, וְלֹא נִתְּנָה רְשׁוּת לְגַלּוֹת פְּרָט לַחֲסִידִים קְדוֹשִׁים עֶלְיוֹנִים חֲכָמִים. אָמַר רַבִּי יוֹסֵי, מַהוּ? אָמַר לָהֶם, עֲדַיִן לֹא בָדַקְתִּי אֶתְכֶם."],[3,"","הָלְכוּ, אַחַר כָּךְ אָמַר לָהֶם, כְּשֶׁהַלְּבָנָה מִתְקָרֶבֶת לַשֶּׁמֶשׁ, מְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא צַד הַצָּפוֹן וְאוֹחֵז בּוֹ בְּאַהֲבָה וּמוֹשֵׁךְ אוֹתוֹ אֵלָיו, וְהַדָּרוֹם מִתְעוֹרֵר מִצַּד אַחֵר, וְהַלְּבָנָה עוֹלָה וּמִתְחַבֶּרֶת בַּמִּזְרָח. וְאָז יוֹנֶקֶת מִשְּׁנֵי צְדָדִים וְנוֹטֶלֶת בְּרָכוֹת בַּחֲשַׁאי, וְאָז מִתְבָּרֶכֶת הַלְּבָנָה וּמִתְמַלֵּאת. וְכָאן מִתְקָרֶבֶת הָאִשָּׁה לְבַעְלָהּ."],[4,"","כְּמוֹ שֶׁיֵּשׁ סוֹד דְּמוּת אֵיבְרֵי (נ\"א בתקוני האיברים) הָאָדָם וְתִקּוּנָיו, כָּךְ גַּם יֵשׁ (הוא) סוֹד שֶׁל דְּמוּת אֵיבְרֵי הַנְּקֵבָה וְתִקּוּנֵי הַנְּקֵבָה, וְהַכֹּל מְפֹרָשׁ בְּתוֹכֵנוּ. כָּךְ גַּם יֵשׁ לְמַעְלָה (מי) שֶׁאוֹחֵז בָּהּ וּמִתְעוֹרֵר כְּנֶגֶד בְּאַהֲבָה, כָּךְ גַּם יֵשׁ לְמַטָּה סוֹד וְתִקּוּן הָאָדָם הַתַּחְתּוֹן הָאַחֵר תַּחַת הַלְּבָנָה (ד\"א ותקון הנקבה)."],[5,"","כְּמוֹ שֶׁזְּרוֹעַ שְׂמֹאל לְמַעְלָה אוֹחֶזֶת בָּהּ וּמִתְעוֹרֵר כְּנֶגְדָּהּ בְּאַהֲבָה, כָּךְ גַּם יֵשׁ לְמַטָּה. (ווי העמודים כלם עומדים איברים להאחז זה בזה ולהתקשר זה בזה קשרי האמונה צד הקדשה מצד של רוח טמאה שהוא סוד הנחש שלמטה). נָחָשׁ זֶה הוּא זְרוֹעַ שְׂמֹאל שֶׁל רוּחַ הַטֻּמְאָה, וְאוֹחֵז בּוֹ מִי שֶׁרוֹכֵב עָלָיו, וְקָרֵב לַלְּבָנָה וּמוֹשֵׁךְ אוֹתָהּ בֵּינֵיהֶם (נ\"א: בדבקות) שֶׁל דְּבֵקוּת וְנִטְמֵאת."],[6,"","וְאָז יִשְׂרָאֵל לְמַטָּה מַקְרִיבִים שָׂעִיר, וְאוֹתוֹ נָחָשׁ נִמְשָׁךְ אַחַר אוֹתוֹ הַשָּׂעִיר, וְהַלְּבָנָה נִטְהֶרֶת וְעוֹלָה לְמַעְלָה וּמִתְקַשֶּׁרֶת לְמַעְלָה לְהִתְבָּרֵךְ, וּפָנֶיהָ מְאִירִים מַה שֶּׁנֶּחְשְׁכָה לְמַטָּה."],[7,"","אָז כָּאן בְּיוֹם הַכִּפּוּרִים, כֵּיוָן שֶׁאוֹתוֹ נָחָשׁ הָרָע מִתְעַסֵּק בְּאוֹתוֹ שָׂעִיר, הַלְּבָנָה נִפְרֶדֶת מִמֶּנּוּ וּמִתְעַסֶּקֶת (בישראל) לְלַמֵּד עֲלֵיהֶם סָנֵגוֹרְיָא, וְסוֹכֶכֶת עֲלֵיהֶם כְּמוֹ אֵם עַל הַבָּנִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אוֹתָם מִלְמַעְלָה וּמוֹחֵל לָהֶם."],[8,"","אַחַר כָּךְ כְּשֶׁיִּשְׂרָאֵל מַגִּיעִים לֶחָג, מְעוֹרְרִים צַד יָמִין לְמַעְלָה, כְּדֵי שֶׁתִּתְקַשֵּׁר בּוֹ הַלְּבָנָה וְיֵאוֹרוּ פָנֶיהָ כָּרָאוּי. וְאָז מְחַלֶּקֶת (נותנת) חֵלֶק שֶׁלָּהּ בְּרָכוֹת לְכָל אוֹתָם מְמֻנִּים שֶׁלְּמַטָּה שֶׁיִּתְעַסְּקוּ בְּחֶלְקָם, וְלֹא יָבֹאוּ לִינֹק וּלְהִתְקָרֵב לַצַּד שֶׁל חֵלֶק יִשְׂרָאֵל."],[9,"","כְּמוֹ זֶה לְמַטָּה - כְּשֶׁשְּׁאָר הָעַמִּים מִתְבָּרְכִים, כֻּלָּם מִתְעַסְּקִים בִּירֻשַּׁת חֶלְקָם, וְלֹא יָבֹאוּ לְהִתְעָרֵב עִם יִשְׂרָאֵל וְלַחְמֹד חֵלֶק יְרֻשָּׁתָם. וְלָכֵן יִשְׂרָאֵל מוֹשְׁכִים בְּרָכוֹת לְכָל אוֹתָם מְמֻנִּים, כְּדֵי שֶׁיִּתְעַסְּקוּ בְחֶלְקָם וְלֹא יִתְעָרְבוּ עִמָּם."],[10,"","וּכְשֶׁהַלְּבָנָה מִתְמַלֵּאת בְּרָכוֹת לְמַעְלָה כָּרָאוּי. יִשְׂרָאֵל בָּאִים וְיוֹנְקִים מִמֶּנָּה לְבַדָּם. וְעַל זֶה כָּתוּב (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. מַה זֶּה עֲצֶרֶת? כְּתַרְגּוּמוֹ כְּנִישׁוּ (התכגסות). כָּל מַה שֶּׁכִּנְּסוּ מֵאוֹתָם בְּרָכוֹת עֶלְיוֹנוֹת, לֹא יוֹנְקִים מִמֶּנָּה עַמִּים אֲחֵרִים, פְּרָט לְיִשְׂרָאֵל לְבַדָּם. וְלָכֵן כָּתוּב עֲצֶרֶת תִּהְיֶה לָכֶם, לָכֶם וְלֹא לִשְׁאָר הָעַמִּים, לָכֶם וְלֹא לִשְׁאָר הַמְמֻנִּים."],[11,"","וְעַל זֶה הֵם מְרַצִּים עַל הַמַּיִם, לָתֵת לָהֶם חֵלֶק בְּרָכוֹת שֶׁיִּתְעַסְּקוּ בוֹ, וְלֹא יִתְעָרְבוּ אַחַר כָּךְ בְּחֶדְוַת יִשְׂרָאֵל כְּשֶׁיּוֹנְקִים בְּרָכוֹת עֶלְיוֹנוֹת. וְעַל אוֹתוֹ יוֹם כָּתוּב דּוֹדִי לִי וַאֲנִי לוֹ. שֶׁלֹּא מִתְעָרֵב אַחֵר עִמָּנוּ."]]],[["לְמַלְכָּא דְּזַמַּן רְחִימוֹי בִּסְעוּדָתָא עִלָּאָה דְּעֲבִיד לֵיהּ לְיוֹמָא רְשִׁימָא. הָא רְחִימוֹי דְמַלְכָּא יְדַע דְּמַלְכָּא אִתְרָעֵי בֵּיהּ. אָמַר מַלְכָּא הַשְׁתָּא אֲנָא בָּעֵי לְמֶחֱדֵי עִם רְחִימָאי. וְדָחִילְנָא דְּכַד אֲנָא בִּסְעוּדָתָא עִם רְחִימָאי יַעֲלוּן כָּל אִנּוּן קַסְטוֹרֵי מְמַנָּן וִיתִיבוּן עִמָּנָא לִפְתוֹרָא לְמִסְעַד סְעוּדָתָא דְחֶדְוָה עִם רְחִימָאי. מָה עֲבַד אַקְדִים הַהוּא רְחִימוֹי קוּסְטוּרִין דִּירוֹקֵי וּבִשְׂרָא דְתוֹרֵי וְאַקְרִיב קַמַּיְיהוּ דְּאִנּוּן קַסְטוּרֵי מְמַנָּן לְמֵיכַל. לְבָתַר יָתִיב מַלְכָּא עִם רְחִימוֹי לְהַהִיא סְעוּדָתָא עִלָּאָה מִכָּל עִדּוּנִין דְּעָלְמָא. וּבְעוֹד דְּאִיהוּ בִּלְחוֹדוֹי עִם מַלְכָּא שָׁאִיל לֵיהּ כָּל צָרְכּוֹי וְיָהִיב לֵיהּ. וְאַחֲדֵי מַלְכָּא עִם רְחִימוֹי בִּלְחוֹדוֹהִי וְלָא אִתְעָרְבִין אָחֳרָנִין בֵּינַיְיהוּ. כָּךְ יִשְׂרָאֵל עִם קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין כָּךְ כְּתִיב בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם.","אָמְרוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא קוּדְשָׁא בְּרִיךְ הוּא אַתְקִין אוֹרְחָא קַמָּן. זַכָּאִין אִנּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. אָתֵי נְשָׁקוּהוּ. קָרָא עֲלֵיהּ רַבִּי יוֹסֵי (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ וְרַב שְׁלוֹם בָּנָיִךְ. כַּד מָטוּ בֵּי חֲקַל יָתִיבוּ. אָמַר הַהוּא בַּר נָשׁ מַאי שְׁנָא דִּכְתִיב, (בראשית י״ט:כ״ד) וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה וְגו'. (נדפס בפקודי רכז ב) וּמַאי שְׁנָא בְּטוֹפָנָא דִּכְתִיב אֱלהִים אֱלהִים בְּכָל אֲתַר. (אמאי) וְלָא כְּתִיב וַיְיָ (בכלא).","אֶלָּא תָּנִינָן בְּכָל אֲתַר דִּכְתִיב וַיְיָ הוּא וּבֵית דִּינוֹ. אֱלֹהִים סְתָם דִּינָא בִּלְחוֹדוֹי. אֶלָּא בִּסְדוֹם אִתְעֲבִיד דִּינָא וְלָא לְשֵׁיצָאָה עָלְמָא. וּבְגִין כָּךְ אִתְעָרֵב אִיהוּ בַּהֲדֵי דִינָא. אֲבָל בְּטוֹפָנָא כָּל עָלְמָא שָׁצֵי וְכָל אִנּוּן דְּאִשְׁתַּכָּחוּ (נ\"א בלחודוי) בְּעָלְמָא.","וְאִי תֵימָא (ד\"א דהא) נֹחַ וּדְעִמֵּיהּ (ד\"א אשתזיבו). (נ\"א הא) סָתִים מַעֲיָנָא הֲוָה דְּלָא אִתְחֲזֵי. וְעַל דָּא כָּל מַה דְּאִשְׁתְּכַח בְּעָלְמָא שָׁצֵי לֵיהּ. וְעַל דָּא וַיְיָ בְּאִתְגַלְיָא וְלָא שָׁצֵי כֹלָּא. אֱלהִים בָּעֵי סְתִימוּ וּבָעֵי לְאִסְתַּמְּרָא דְּהָא כֹּלָּא שָׁצֵי. וְעַל דָּא אֱלהִים בִּלְחוֹדוֹי הֲוֵי.","וְרָזָא דָּא (תהילים כ״ט:י׳) יְיָ לַמַּבּוּל יָשָׁב. מַהוּ יָשָׁב. אִלְמָלֵא קְרָא כְּתִיב לָא יָכְלִינָן לְמֵימַר. יָשָׁב בִּלְחוֹדוֹי דְּלָא אַתְיָא עִם דִּינָא. כְּתִיב הָכָא יָשָׁב, וּכְתִיב הָתָם (ויקרא י״ג:מ״ו) בָּדָד יֵשֵׁב בִּלְחוֹדוֹי.","וּבְגִין דְּנֹחַ הֲוָה סָתִים מַעֲיָנָא. לְבָתַר כַּד אִתְעֲבִיד דִּינָא וְשָׁצֵי עָלְמָא וְנָח רוּגְזֵיהּ מַה כְּתִיב וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ וְגו'. דְּהָא כַּד שָׁצֵי עָלְמָא לָא אִדְכַּר דְּסָתִים מַעֲיָנָא הֲוָה.","וְרָזָא (ודא) אוֹלִיפְנָא קוּדְשָׁא בְּרִיךְ הוּא סָתִים וְגַלְיָא. גַּלְיָא הוּא בֵּי דִינָא דִלְתַתָּא. סָתִים הוּא אֲתַר דְּכָל בִּרְכָאן נָפְקֵי מִתַּמָּן. וּבְגִין כָּךְ כָּל מִלּוֹי דְּבַר נָשׁ דְּאִנּוּן בִּסְתִימוּ בִּרְכָאן שַׁרְיָין עֲלוֹי. וְכָל דְּאִנּוּן בְּאִתְגַּלְּיָא הַהוּא אֲתַר דְּבֵי דִינָא שָׁרְיָאן עֲלוֹי בְּגִין דְּאִיהוּ אֲתַר בְּאִתְגְּלֵי וְהַהוּא דְאִקְרֵי רַע עַיִן שַׁלִּיט עֲלֵיהּ, וְכֹלָּא הוּא בְּרָזָא עִלָּאָה כְּגַוְונָא דִלְעֵילָא.","בָּכָה רַבִּי יוֹסֵי וְאָמַר זַכָּאָה דָרָא דְּרַבִּי שִׁמְעוֹן שַׁרְיָא בְּגַוֵּיהּ דְּהָא זְכוּתָא דִילֵיהּ אַזְמִין לָן בְּטוּרֵי מִלִּין עִלָּאִין כְּאִלֵּין (עד כאן). אָמַר רַבִּי יוֹסֵי הַאי בַּר נָשׁ לְאוֹדָעָא לָן מִלִּין אִלֵּין קָא אָתֵי וְשַׁדְרֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְגַבָּן. כַּד אָתוּ וְסִדְּרוּ מִלִּין קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אָמַר וַדַּאי שַׁפִּיר קָא אָמַר.","(נדפס בפקודי רסח ב)רַבִּי אֶלְעָזָר הֲוָה יָתִיב יוֹמָא חַד קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אֲבוּי. אָמַר לֵיהּ הַאי קֵץ כָּל בָּשָׂר אִתְהַנֵּי מֵאִנּוּן קָרְבָּנִין דְּהֲווּ יִשְׂרָאֵל מְקָרְבִין עַל גַּבֵּי מַדְבְּחָא אוֹ לָא. אָמַר לֵיהּ כֹּלָּא הֲווּ מִסְתַּפְּקֵי כְּחֲדָא לְעֵילָא וְתַתָּא.","וְתָא חֲזֵי כַּהֲנִי וְלֵיוָאֵי וְיִשְׂרָאֵל אִנּוּן אִקְרוּן אָדָם בְּחִבּוּרָא דְּאִנּוּן רְעוּתִין קַדִּישִׁין דְּסָלְקִין מִגַּוַויְיהוּ. הַהוּא כִּשְׂבָּא אוֹ אִמְרָא אוֹ הַהִיא בְּהֵמָה דְּקָרְבִין אִצְטְרִיךְ עַד לָא יִתְקְרִיב עַל גַּבֵּי מַדְבְּחָא לְפָרָשָׁא עֲלָהּ כָּל חַטָּאִין וְכָל רְעוּתִין בִּישִׁין לְאִתְוַדָּאָה עֲלָהּ. וּכְדֵין הַהִיא אִתְקְרֵי בְּהֵמָה בְּכֹלָּא בְּגוֹ אִנּוּן חַטָּאִין וּבִישִׁין וְהִרְהוּרִין.","כְּגַוְונָא דְּקָרְבָּנָא דַּעֲזָאזֵל דִּכְתִיב (ויקרא ט״ז:כ״א) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנוֹת בְּנֵי יִשְׂרָאֵל וְגו'. הָכִי נָמֵי הָכָא. וְכַד סָלְקָא עַל גַּבֵּי מַדְבְּחָא מְטוּלָא עַל חַד תְּרֵין. וּבְגִין כָּךְ דָא סַלְקָא לְאַתְרֵיהּ. וְדָא סַלְקָא לְאַתְרֵיהּ. דָּא בְּרָזָא דְאָדָם וְדָא בְּרָזָא דִבְהֵמָה כְּמָה דְאַתְּ אָמֵר (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ.","חֲבִיתִין וְכָל שְׁאָר מְנָחוֹת לְאַתְעָרָא רוּחָא קַדִּישָׁא בִּרְעוּתָא דְּכַהֲנֵי וְשִׁירָתָא דְּלֵיוָאֵי וּבִצְלוֹתָא דְיִשְׂרָאֵל. וּבְהַהוּא תְּנָנָא וְשַׁמְנָא וְקִמְחָא דְּסָלִיק מִתְרַוָּון וּמִסְתַּפְּקִין (ס\"א ומתפנקין) (ס\"א ומתפשטין) כָּל שְׁאָר מָארֵי דְדִינִין דְּלָא יָכְלִין לְשַׁלְטָאָה בְּהַהוּא דִינָא דְאִתְמָסַר לוֹן. וְכֹלָּא בְּזִמְנָא חָדָא. תָּא חֲזֵי, כֹּלָּא אִתְעֲבִיד בְּרָזָא דִמְהֵימְנוּתָא לְאִסְתַּפְּקָא דָּא בְּדָא, וּלְאִסְתַּלָּקָא לְעֵילָא מָאן דְּאִצְטְרִיךְ עַד אֵין סוֹף."],[[0,"למלכא דזמן וכו':","משל למלך שהזמין את אוהבו לסעודה שהוא עושה ביום מסוים, כדי שאוהב המלך ידע שהמלך רוצה בו. אמר המלך. עתה אני רוצה לשמוח עם אוהבי לבדו ואני מתירא, שאני אהיה בתוך הסעודה עם אוהבי, יבואו כל אלו השוטרים הממונים, וישבו עמנו אל השולחן, לסעוד סעודת השמחה עם אוהבי ביחד. מה עשה האוהב, הוא הקדים תבשילין של ירקות ובשר שור והקריב לאכול לפני אותם השוטרים הממונים, ואחר כך ישב המלך עם אוהבו, לאותה סעודה העליונה מכל מעדני עולם. ובעוד שהוא עם המלך בלבדו שואל ממנו כל צרכיו, והוא נותן לו, והמלך שמח עם אוהבו בלבדו, וזרים לא יתערבו ביניהם. כך ישראל עם הקב\"ה, כנ\"ל, משום זה כתוב ביום השמיני עצרת תהיה לכם."],[1,"אמרו רבי יוסי וכו':","אמרו ר\"י ור\"ח, הקב\"ה תקן את הדרך לפנינו, אשריהם העוסקים בתורה. באו ונשקוהו לאותו יהודי וקרא עליו רבי יוסי, וכל בניך למודי ה' ורב שלום בניך."],[1,"כד מטו וכו':","כשהגיעו לשדה ישבו. אמר אותו אדם, מה נשתנה, שכתב וה' המטיר על סדום ועמורה ואינו כתוב ואלקים המטיר וגו'. ומה נשתנה בהמבול, שכתוב בו בכל מקום אלקים, אלקים, ולא כתוב בו וה'. כמו במהפכת סדום ועמורה."],[2,"אלא תנינן וכו':","אלא למדנו, בכל מקום שכתוב וה', פירושו, הוא ובית דינו, דהיינו ז\"א שהוא רחמים, ביחד עם נוקביה. שהיא דין, ואם כתוב, אלקים סתם יורה על הבית דין בלבד. דהיינו הנוקבא בלבדה בלי ז\"א. כי בסדום, נעשה הדין שלא לכלות העולם, וע\"כ נתערב הוא, ז\"א. עם הדין, וע\"כ כתוב שם, \u0003וה',\u0004 שיורה על מדת הרחמים שהוא ז\"א הנקרא הוי\"ה, ובית דינו יחד, שהיא נוקביה. כי הו' הנסמך אל הויה מרבה את הנוקבא. אבל בהמבול השמיד כל העולם וכל הנמצאים בהעולם. ע\"כ כתוב בו השם \u0003אלקים.\u0004 שיורה על מדת הדין בלבדו בלי שיתוף מדת הרחמים."],[3,"ואי תימא וכו':","ואם תאמר, נח וכל שעמו ניצולו, ולא נשמדו כל הנמצאים, הוא משום שהיה נעלם מעין, שלא היה נראה להמשחית ועל כן, נבחן, שנכלה כל מה שנמצא בעולם דהיינו כל מה שנראה לעין המשחית. ועל כן, וה' יורה שאינו משחית כל מה שבגלוי לעין. כמו בהפיכת סדום, \u0003אלקים\u0004 יורה שצריכים להסתר וצריכים להשמר. מפני שמכלה את הכל דהיינו כל מה שגלוי לעין. ועל כן \u0003אלקים\u0004 יורה על הנוקבא לבדה בלי ז\"א שהוא רחמים."],[4,"ורזא דא וכו'","וז\"ס ה' למבול ישב. ושואל מהו פירושו של ישב, ואמר, אלמלא המקרא כתוב לא יכולנו לומר זה כי ישב פרושו לבדו בפני עצמו, כי לא נתחבר עם הדין שנעשה בהמבול. וילפינן גזרה שוה. כתוב כאן ישב, ושם כתוב בדד ישב מחוץ למחנה, מה שם פירושו לבדו בפני עצמו, אף ישב שבכאן, פירושו לבדו בפני עצמו. ושיעור הכתוב הויה למבול ישב שבעת דינו של המבול ישב בפני עצמו ולא נתחבר לדון דין הזה. וע\"כ היה כולו דין בלי רחמים."],[5,"ובגין דנח וכו':","ומשום שנח היה נעלם מעין לכן אחר שנעשה הדין ונכלה העולם ושכך כעסו, מה כתוב ויזכור אלקים את נח, כי עד עתה, דהיינו בעת שכילה העולם. לא נזכר נח, שהיה נעלם מעין."],[6,"ורזא אוליפנא וכו':","וסוד למדתי שהקב\"ה נעלם וגלוי, \u0003גלוי\u0004 היינו הב\"ד שלמטה, שהיא הנוקבא רחל, העומדת מחזה ולמטה דז\"א \u0003נעלם,\u0004 היינו המקום שכל הברכות יוצאים משמה, שהיא הזווג ז\"א ולאה, העומדת מחזה ולמעלה דז\"א. שמזווג הזה באים כל הברכות. ומשום זה, כל דברי האדם שהם בהעלם אצלו שורה עליהם ברכות. וכל שהם בהתגלות, מקום ההוא של בית דין שורה עליו. דהיינו הנוקבא שמחזה ולמטה דז\"א, משום שהוא מקום הגילוי, דהיינו עלמא דאתגליא. כלומר, שהחסדים מתגלים בה בהארת החכמה, ואותו שנקרא רע עין שולט עליו, כלומר שבמקום הגילוי, דהארת חכמה, מתאחזים כל הדינים והקליפות, אבל בהנוקבא שמחזה ולמעלה ששם חסדים מכוסים, שמשום זה הוא נקראת עלמא דאתכסיא, אין שום קליפה יכולה להאחז בה, ולפיכך כל שרבריו מכוסים שורה עליו ברכה מעלמא דאתכסיא. וכל שדבריו מגולים שורה עליו דינים מעלמא דאתגליא, והכל הוא בסוד עליון כעין של מעלה."],[7,"בכה וכו':","בכה ר\"י ואמר אשרי הדור שר\"ש שורה בתוכו, כי זכותו של ר\"ש הזמין לנו על ההרים לשמוע דברים עליונים כאלו. אמר ר\"י אדם זה בא אלינו רק להודיע לנו דברים האלו, כי הקב\"ה שלחו אלינו. כשבאו וסדדו הדברים ששמעו לפני ר\"ש, אמר, ודאי יפה הוא אומר. כלומר, שדבריר אמיתים המה."],[8,"רבי אלעזר וכו':","ר\"א ישב איזה יום לפני ר\"ש אביו, שאל אותו, קץ כל בשר זה, שהוא הס\"א (כנ\"ל באות ע\"ה) נהנה מאלו הקרבנות שהיו ישראל מקריבין על המזבח, או לא. אמר לו כולם היו מקבלים סיפוקם ביחד הן למעלה והן למטה."],[9,"ות\"ח כהני וכו':","ובוא וראה, כהנים ולוים וישראלים שה\"ס ג' קוין ימין שמאל ואמצע, נקראים אדם בהחיבור של אלו רצוניות הקדושים העולים מהם למ\"ן, מהכהנים בעבודתם, ומלוים בשירתם, ומישראל במעמדם, בעת הקרבת הקרבן. כשבה ההוא, או האיל, או בהמה ההיא, שמקריבים צריכים לפרש עליה, מטרם שמקריבים אותה על המזבח, כל החטאים וכל רצוניות הרעים. להתודות עליה: ואז נקרא קרבן ההוא בשם בהמה בתוך כל אלו החטאים והרעות והרהורים שהתודה עליו. פירוש. \u0003אדם\u0004 בגי' מ\"ה וע\"כ הוא כינוי לז\"א, שה\"ס הויה במילוי אלפין שבגימ' מ\"ה. \u0003בהמה\u0004 בגי' נ\"ב, וע\"כ הוא כינוי אל הנוקבא, שה\"ס הויה במילוי ההין שבגי' ב\"ן. והשם הזה יורה בעיקר על מוחין דשמאל שהיא מקבלת. ולפיכך. הארת המוחין השלמים שבאים בזווג כל ג' הקוין, ימין שמאל אמצע, נקרא בשם \u0003אדם.\u0004 והארת החכמה הנמשכת בקו שמאל. מטרם שנתחבר בזווג ג' הקוין. נבחנת בשם \u0003בהמה.\u0004 ואומר שבהקרבת הקרבן יש ב' הבחינות \u0003אדם ובהמה,\u0004 כי ע\"י המ\"ן שמעלים כהנים בעבודתם ולוים בשירתם וישראל במעמדם בעת הקרבת הקרבן. שה\"ס ג' הקוין, נמשכים המוחין בבחינת \u0003אדם,\u0004 ועל ידי הודוי שמתודים על הקרבן, נמשך הארת החכמה שבקו שמאל בלבדו בלי זווג מכל הקוין, שהארה זו נקראת בשם \u0003בהמה.\u0004 ומהארה זו דבהמה, נהנה ג\"כ הקץ כל בשר, כמו שמסיק לפנינו אחר המאמר דר\"ש באות קכ\"ח ומיושב שאלת רבי אלעזר. וצריך שתדע שאין כפרת עונות אלא ע\"י המשכת הארת החכמה שבשמאל. וז\"ש. \u0003אתקרי בהמה בכלא, בגו אינון חטאין וכו'\u0004 כלומר, מכח הוידוי, וכפרת עונות שבהקרבן, הוא נבחן בשם \u0003בהמה.\u0004 שה\"ם הארת החכמה שבשמאל, שמשם כפרת העונות."],[10,"כגוונא דקרבנא וכו':","כמו הקרבן של עזאזל, שכתוב בו, והתודה עליו כל עונות וגו' כן כאן, ככל קרבן נוהג וידוי העונות. כי כאשר הקרבן עולה על המזבח ואינו נשלח המדברה מגיע לו על אחת שתים, שצריכים להתודות עליו. ומשום זה, זה עולה למקומו וזה עולה למקומו, זה בסוד אדם, שה\"ס ג' קוין, וזה בסוד בהמה, שה\"ס הארת הקו שמאל בלבד כמו שאתה אומר, אדם ובהמה תושיע ה'."],[11,"חביתין וכו':","מנחת חביתים וכל שאר המנחות. צריכים לעורר רוח הקדוש דהיינו בחינת אדם, בהרצון של הכהנים ובשירת הלוים ובתפלת ישראל, שה\"ס ג' קוין (כנ\"ל בדיבור הסמוך) ובאותו העשן, ושמן וקמח העולה על המזבח, מתרוים ומסתפקים כל בעלי הדין, שאינם יכולים לשלוט בדין ההוא שנמסר להם. והם בחינת בהמה. הרי שגם במנחות יש ג\"כ ב' הבחינות אדם ובהמה. והכל נמשך בזמן אחד כלומר הן בחינת אדם והן בחינת בהמה נמשך כאחד בעת הקרבת הקרבן. \u0003ת\"ח וכו\u0004 בוא וראה, הכל נעשה בסוד האמונה, להספיק זה לזה ולהעלות למעלה מה שנצרך, עד אין סוף. \u0003להספיק זה לזה,\u0004 קאי על קו ימין המשלים לשמאל וקו שמאל המשלים לימין, (כנ\"ל בראשית א' דף ש\"א אות שפ\"ה ד\"ה אר\"ח) \u0003לעלות למעלה מה שנצרך\u0004 קאי על הארת החכמה שבשמאל שצריכים להעלותה למעלה ולא להמשיכה למטה. (כנ\"ל בראשית א' דף ש\"ג אות שפ\"ו ד\"ה ונודע), \u0003עד אין סוף,\u0004 היינו להעלות הכל לרדל\"א, שה\"ס אין סוף כמו שרבי שמעון ממשיך ומבאר כל זה לפנינו."]],[[0,"","לְמֶלֶךָ שֶׁהִזְמִין אֲהוּבוֹ לִסְעוּדָה עֶלְיוֹנָה שֶׁעָשָׂה לוֹ לְיוֹם רָשׁוּם. אֲהוּב הַמֶּלֶךְ הֲרֵי יוֹדֵעַ שֶׁהַמֶּלֶךְ רוֹצֶה בּוֹ. אָמַר הַמֶּלֶךְ, כָּעֵת אֲנִי רוֹצֶה לִשְׂמֹחַ עִם אֲהוּבִי, וַאֲנִי חוֹשֵׁשׁ שֶׁכַּאֲשֶׁר אֲנִי בִּסְעוּדָה עִם אֲהוּבִי, יִכָּנְסוּ כָּל אוֹתָם פְּקִידִים מְמֻנִּים וְיֵשְׁבוּ עִמָּנוּ לַשֻּׁלְחָן לִסְעֹד סְעוּדַת הַשִּׂמְחָה עִם אֲהוּבִי. מֶה עָשָׂה? הִקְדִּים אוֹתוֹ אָהוּב מִינִים שֶׁל יְרָקוֹת וּבְשַׂר שְׁוָרִים וְהִקְרִיב לִפְנֵי אוֹתָם פְּקִידִים מְמֻנִּים לֶאֱכֹל. אַחַר כָּךְ יָשַׁב הַמֶּלֶךְ עִם אֲהוּבוֹ לְאוֹתָהּ הַסְּעוּדָה הָעֶלְיוֹנָה מִכָּל עִדּוּנֵי הָעוֹלָם. וּבְעוֹד שֶׁהוּא לְבַדּוֹ עִם הַמֶּלֶךְ, בִּקֵּשׁ מִמֶּנּוּ כָּל צְרָכָיו וְנָתַן לוֹ, וְשָׂמַח הַמֶּלֶךְ עִם אֲהוּבוֹ לְבַדּוֹ, וְלֹא הִתְעָרְבוּ אֲחֵרִים בֵּינֵיהֶם. כָּךְ יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. לָכֵן כָּתוּב בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם."],[1,"","אָמְרוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא, הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְקִין הַדֶּרֶךְ לְפָנֵינוּ. אַשְׁרֵי אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה. בָּאוּ וּנְשָׁקוּהוּ. קָרָא עָלָיו רַבִּי יוֹסֵי, (ישעיה נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה' וְרַב שְׁלוֹם בָּנָיִךְ. כְּשֶׁהִגִּיעוּ לַשָּׂדֶה, יָשְׁבוּ. אָמַר אוֹתוֹ הָאִישׁ, מַה שּׁוֹנֶה שֶׁכָּתוּב (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה וְגוֹ', וּמַה שּׁוֹנֶה בַּמַּבּוּל שֶׁכָּתוּב אֱלֹהִים אֱלֹהִים בְּכָל מָקוֹם, (למה) וְלֹא כָתוּב וַה' (בכל)? ."],[2,"","אֶלָּא שָׁנִינוּ, בְּכָל מָקוֹם שֶׁכָּתוּב וַה' - הוּא וּבֵית דִּינוֹ. אֱלֹהִים סְתָם - דִּין לְבַדּוֹ. אֶלָּא בִּסְדֹם נַעֲשָׂה דִין וְלֹא לְהַשְׁמִיד עוֹלָם, וְלָכֵן הוּא הִתְעָרֵב בְּדִין, אֲבָל בַּמַּבּוּל הֻשְׁמַד כָּל הָעוֹלָם וְכָל אוֹתָם שֶׁנִּמְצְאוּ (בלבדו) בָּעוֹלָם."],[3,"","וְאִם תֹּאמַר, (הרי) נֹחַ וּמִי שֶׁהָיָה עִמּוֹ (נצלו הרי) נִסְתָּר מִן הָעַיִן הָיָה, שֶׁלֹּא נִרְאֶה. וְעַל זֶה כָּל מַה שֶּׁנִּמְצָא בָּעוֹלָם הִשְׁמִיד אוֹתוֹ, וְעַל זֶה וַה' בְּגִלּוּי, וְלֹא הִשְׁמִיד הַכֹּל. אֱלֹהִים צָרִיךְ הַסְתָּרָה, וְצָרִיךְ (אדם) לְהִשָּׁמֵר, שֶׁהֲרֵי הַכֹּל מַשְׁמִיד, וְעַל זֶה אֱלֹהִים לְבַדּוֹ הָיָה."],[4,"","וְזְהִ סוֹד (תהלים כט) ה' לַמַּבּוּל יָשָׁב. מַה זֶּה יָשָׁב? אִלְמָלֵא פָּסוּק כָּתוּב, לֹא יָכֹלְנוּ לְאָמְרוֹ. יָשַׁב לְבַדּוֹ, שֶׁלֹּא בָא עִם דִּין. כָּתוּב כָּאן יָשָׁב, וְכָתוּב שָׁם (ויקרא יג) בָּדָד יֵשֵׁב לְבַדּוֹ."],[5,"","וּמִשּׁוּם שֶׁנֹּחַ הָיָה נִסְתָּר מִן הָעַיִן, אַחַר כָּךְ נַעֲשָׂה דִין, וְהֻשְׁמַד הָעוֹלָם וְנָח רֻגְזוֹ, מַה כָּתוּב? וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ וְגוֹ'. שֶׁהֲרֵי כְּשֶׁהִשְׁמִיד הָעוֹלָם, לֹא נִזְכַּר שֶׁהָיָה נִסְתָּר מֵהָעַיִן,"],[6,"","וְסוֹד (זה) לָמַדְנוּ - הַקָּדוֹשׁ בָּרוּךְ הוּא נִסְתָּר וְגָלוּי. גָּלוּי הוּא בֵּית הַדִּין שֶׁלְּמַטָּה, וְנִסְתָּר הוּא מָקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת מִשָּׁם. וְלָכֵן כָּל דִּבְרֵי הָאָדָם שֶׁהֵם בַּסֵּתֶר, בְּרָכוֹת שׁוֹרוֹת עָלָיו. וְכָל אוֹתָם שֶׁבַּנִּגְלֶה, אוֹתוֹ מָקוֹם שֶׁל בֵּית דִּין שׁוֹרִים עָלָיו, מִשּׁוּם שֶׁהוּא מָקוֹם בְּגִלּוּי, וְאוֹתוֹ שֶׁנִּקְרָא רַע עַיִן שׁוֹלֵט עָלָיו, וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן כְּמוֹ שֶׁלְּמַעְלָה."],[7,"","בָּכָה רַבִּי יוֹסֵי וְאָמַר, אַשְׁרֵי הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בְּתוֹכוֹ, שֶׁהֲרֵי זְכוּתוֹ הִזְמִינָה לָנוּ בֶּהָרִים דְּבָרִים עֶלְיוֹנִים כָּאֵלֶּה (עד כאן). אָמַר רַבִּי יוֹסֵי, הָאִישׁ הַזֶּה בָּא לְהוֹדִיעֵנוּ הַדְּבָרִים הַלָּלוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתוֹ אֵלֵינוּ. כְּשֶׁבָּאוּ וְסִדְּרוּ הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר, וַדַּאי שֶׁיָּפֶה אָמַר."],[8,"","רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב יוֹם אֶחָד לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, קֵץ כָּל בָּשָׂר הַזֶּה נֶהֱנָה מֵאוֹתָם קָרְבָּנוֹת שֶׁהָיוּ יִשְׂרָאֵל מַקְרִיבִים עַל גַּבֵּי הַמִּזְבֵּחַ אוֹ לֹא? אָמַר לוֹ, כֻּלָּם הָיוּ מְסֻפָּקִים כְּאֶחָד לְמַעְלָה וּלְמַטָּה."],[9,"","וּבֹא וּרְאֵה, כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים הֵם נִקְרָאִים אָדָם בְּחִבּוּר שֶׁל אוֹתָם רְצוֹנוֹת קְדוֹשִׁים שֶׁעוֹלִים מִתּוֹכָם. אוֹתוֹ כֶּשֶׂב אוֹ אַיִל אוֹ אוֹתָהּ בְּהֵמָה שֶׁמַּקְרִיבִים, צָרִיךְ עַד שֶׁלֹּא תֻקְרַב עַל הַמִּזְבֵּחַ לְפָרֵשׁ עָלֶיהָ כָּל הַחֲטָאִים וְכָל הָרְצוֹנוֹת הָרָעִים לְהִתְוַדּוֹת עָלֶיהָ, וְאָז הַהִיא נִקְרֵאת בְּהֵמָה בַּכֹּל בְּתוֹךְ אוֹתָם חֲטָאִים וְרָעוֹת וְהִרְהוּרִים."],[10,"","כְּמוֹ הַקָּרְבָּן שֶׁל הָעֲזָאזֵל שֶׁכָּתוּב (ויקרא יו) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת בְּנֵי יִשְׂרָאֵל וְגוֹ' - כָּךְ גַּם כָּאן. וּכְשֶׁעוֹלֶה עַל הַמִּזְבֵּחַ מַשָּׂא עַל אֶחָד שְׁנַיִם, וְלָכֵן זֶה עוֹלֶה לִמְקוֹמוֹ וְזֶה עוֹלֶה לִמְקוֹמוֹ. זֶה בְּסוֹד אָדָם, וְזֶה בְּסוֹד בְּהֵמָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לו) אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'."],[11,"","הַחֲבִתִּין וְכָל שְׁאָר הַמְּנָחוֹת לְעוֹרֵר רוּחַ קְדוֹשָׁה בִּרְצוֹן הַכֹּהֲנִים וְשִׁירַת הַלְוִיִּם וּבִתְפִלַּת יִשְׂרָאֵל. וּבְאוֹתוֹ עָשָׁן וְשֶׁמֶן וְקֶמַח שֶׁעוֹלִים, מִתְרַוִּים וּמִסְתַּפְּקִים (ס\"א ומתפנקים ס\"א ומתפשטים) כָּל שְׁאָר בַּעֲלֵי הַדִּינִים שֶׁלֹּא יְכוֹלִים לִשְׁלֹט בְּאוֹתוֹ הַדִּין שֶׁנִּמְסָר לָהֶם, וְהַכֹּל בִּזְמַן אֶחָד. בּא רְאֵה, הַכֹּל נַעֲשָׂה בְּסוֹד הָאֱמוּנָה לְהִסְתַּפֵּק זֶה בָּזֶה וְלַעֲלוֹת לְמַעְלָה מִי שֶׁצָּרִיךְ עַד אֵין סוֹף."]]],[["(נדפס בפקודי רכא א, רסח ב) אָמַר רַבִּי שִׁמְעוֹן אֲרֵימַת יְדָאי בִּצְלוֹתִין לְעֵילָא, דְּכַד רְעוּתָא עִלָּאָה לְעֵילָא לְעֵילָא קָיְימָא עַל הַהוּא רְעוּתָא דְּלָא אִתְיְדָע וְלֹא אִתְפַּס כְּלַל לְעָלְמִין רֵישָׁא דְּסָתִים יַתִּיר לְעֵילָא. וְהַהוּא רֵישָׁא אַפִּיק מַאי דְאַפִּיק וְלָא יְדִיעַ וְנָהִיר מַאי דְנָהִיר כֹּלָּא בִּסְתִימוּ.","רְעוֹ דְּמַחֲשָׁבָה עִלָּאָה לְמִרְדַּף אֲבַתְרֵיהּ וּלְאִתְנְהָרָא מִנֵּיהּ. חַד פְּרִיסוּ אִתְפְּרִיס. וּמִגּוֹ הַהוּא פְּרִיסָא בִּרְדִיפוּ דְּהַהִיא מַחֲשָׁבָה עִלָּאָה מָטֵי וְלָא מָטֵי עַד הַהוּא פְּרִיסָא נָהִיר מַה דְּנָהִיר. וּכְדֵין (ס\"א ההוא) אִיהוּ מַחֲשָׁבָה עִלָּאָה נָהִיר בִּנְהִירוּ (בסתימו) סָתִים דְּלָא יְדִיעַ וְהַהוּא מַחֲשָׁבָה לָא יָדַע.","כְּדֵין בָּטַשׁ הַאי נְהִירוּ דְּמַחֲשָׁבָה דְּלָא אִתְיְידַע בִּנְהִירוּ דְּפַרְסָא דְּקָיְימָא דְּנָהִיר מִמַּה דְּלָא יְדִיעַ וְלָא אִתְיְידַע וְלָא אִתְגַּלְיָיא. וּכְדֵין (נ\"א האי) דָּא נְהִירוּ דְּמַחֲשָׁבָה דְּלָא אִתְיְידַע בָּטַשׁ בִּנְהִירוּ דִּפְרִיסָא וְנָהֲרִין כְּחֲדָא וְאִתְעֲבִידוּ תֵּשַׁע הֵיכָלִין.","וְהֵיכָלִין לָאו אִנּוּן נְהוֹרִין וְלָאו אִנּוּן רוּחִין וְלָאו אִנּוּן נִשְׁמָתִין. וְלָא אִית (איהו) מָאן דְּקָיְימָא בְּהוּ. רְעוּתָא דְּכָל תֵּשַׁע נְהוֹרִין דְּקָיְימֵי כֻּלְהוּ בְּמַחֲשָׁבָה דְּאִיהוּ חַד מִנַּיְיהוּ בְּחוּשְׁבְּנָא כֻּלְהוּ לְמִרְדַּף בַּתְרַיְיהוּ בְּשַׁעֲתָא דְּקָיְימֵי בְּמַחֲשָׁבָה וְלָא מִתְדַּבְּקָן וְלָא אִתְיְידָעוּ. וְאִלֵּין לָא קָיְימֵי לָא בִּרְעוּתָא וְלָא בְּמַחֲשָׁבָה עִלָּאָה (נ\"א עלאין). תָּפְסִין בָּהּ וְלָא תָפְסִין. בְּאִלֵּין קָיְימֵי כָּל רָזֵי דִמְהֵימְנוּתָא וְכָל אִנּוּן נְהוֹרִין מֵרָזָא דְּמַחֲשָׁבָה עִלָּאָה (דלתתא ד\"א ולתתא) כֻּלְהוּ אִקְרוּן אֵין סוֹף. עַד הָכָא מָטוּ נְהוֹרִין וְלָא מָטוּן וְלָא אִתְיְידָעוּ. לָאו הָכָא רְעוּתָא וְלָא מַחֲשָׁבָה.","(כדין ד\"א כד) נָהִיר מַחֲשָׁבָה וְלָא אִתְיְידַע (ידיע) מִמַּאן דְּנָהִיר. כְּדֵין אִתְלַבֵּשׁ וְאַסְתִּים גּוֹ בִּינָה וְנָהִיר לְמַאן דְנָהִיר וְאָעִיל דָּא בְּדָא עַד דְּאִתְכְּלִילוּ כֻּלְהוּ כְּחֲדָא.","וּבְרָזָא דְּקָרְבָּנָא כַּד סָלִיק כֹּלָּא אִתְקַשַּׁר דָּא בְּדָא וְנָהִיר דָּא בְּדָא. כְּדֵין קָיְימֵי כֻּלְהוּ בִּסְלִיקוּ וּמַחֲשָׁבָה אִתְעַטַּר בְּאֵין סוֹף. הַהוּא נְהִירוּ דְּאִתְנְהִיר מִנֵּיהּ מַחֲשָׁבָה עִלָּאָה (דלא אתיידע בה כלל) אִקְרֵי אֵין סוֹף. וּמִנֵּיהּ אִשְׁתְּכַח וְקָיְימָא וְנָהִיר לְמַאן דְּנָהִיר וְעַל דָּא כֹּלָּא קָאִים. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָא בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי.","תָּא חֲזֵי, הַאי קֵץ כָּל בָּשָׂר, כְּמָה דְּקִשּׁוּרָא אִשְׁתְּכַח לְעֵילָא בְּחֵדוּ, אוּף הָכִי נָמֵי לְתַתָּא בְּחֶדְוְותָא. וּרְעוּתָא לְאִסְתַּפְּקָא כֹּלָּא לְעֵילָא וְתַתָּא. וְאִימָּא קָיְימָא עֲלַיְיהוּ דְיִשְׂרָאֵל כְּדְקָא יְאוּת.","תָּא חֲזֵי, בְּכָל רֵישֵׁי יַרְחָא וְיַרְחָא כַּד סִיהֲרָא מִתְחַדְּשָׁא יָהֲבִין לֵיהּ לְהַאי קֵץ כָּל בָּשָׂר חוּלְקָא חָדָא יַתִּיר עַל קָרְבָּנִין לְאִתְעַסְקָא בֵּיהּ וְיִשְׁתַּמֵּשׁ בְּחוּלָקֵיהּ. וִיהֵא סִטְרָא דְיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. בְּגִין דְּיִתְאַחֲדוּן בְּמַלְכֵיהוֹן, וְדָא אִיהוּ שָׂעִיר. בְּגִין דְּאִיהוּ בְּחוּלָקָא דְּעֵשָׂו דִּכְתִיב בֵּיהּ שָׂעִיר (בראשית כ״ז:י״א) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. וְעַל דָּא אִיהוּ אִשְׁתַּמַּשׁ בְּחוּלָקֵיהּ. וְיִשְׂרָאֵל אִנּוּן מִשְׁתַּמְּשִׁין בְּחוּלָקֵיהוֹן. וּבְגִין כָּךְ כְּתִיב, (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגוּלָתוֹ.","תָּא חֲזֵי, הַאי קֵץ כָּל בָּשָׂר, כָּל רְעוּתֵיהּ לָאו אִיהוּ אֶלָּא בְּבִשְׂרָא תָּדִיר וּבְגִין כָּךְ תִּקּוּנָא דְבִשְׂרָא תָּדִיר לְגַבֵּיהּ וְעַל דָּא אִקְרֵי קֵץ כָּל בָּשָׂר. וְכַד אִיהוּ שַׁלִּיט, שַׁלִּיט עַל גּוּפָא וְלָא עַל נִשְׁמְתָא. נִשְׁמְתָא סָלְקָא לְאַתְרָא וּבִשְׂרָא אִתְיְהִיב לְאֲתַר דָּא. כְּגַוְונָא דָא בְּקָרְבָּנָא דִּרְעוּתָא סָלְקָא לְאֲתַר חָד, וּבִשְׂרָא לְאֲתַר חָד.","וּבַּר נָשׁ דְּאִיהוּ זַכָּאָה אִיהוּ קָרְבָּנָא מַמָּשׁ לְכַפָּרָה. וְאָחֳרָא דְּלָאו אִיהוּ זַכָּאָה, לָאו אִיהוּ קָרְבָּנָא בְּגִין דְּבֵיהּ מוּמָא דִּכְתִיב, (ויקרא כב) כִּי לֹא לְרָצוֹן וְגו'. וְעַל דָּא צַדִּיקַיָא כַּפָּרָה אִנּוּן דְּעָלְמָא וְקָרְבָּנָא אִנּוּן בְּעָלְמָא (עד כאן): תָּא חֲזֵי, וַיֹּאמֶר אֱלהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. לְמֵיטַל רְשׁוּ לְאַחְשָׁכָא אַפַּיְיהוּ דִּבְנֵי עָלְמָא. וּבְגִינֵי כָךְ הִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ. (ועל דא עשה לך תבת עצי גופר בגין לאשתזבא בה ולא יכיל לשלטאה עלך. רבי חייא ורבי יוסי הוו אזלי בארחא אמר חד) כְּתִיב וַיַעַשׂ נֹחַ כְּכֹל אֲשֶׁר צִוָהוּ ה'."],[[0,"אמר ר' שמעון וכו':","אמר ר\"ש הרימותי ידי למעלה בתפילה. כי בא לגלות סדר אצילות ג\"ר דא\"א הנקראים כתרא, מוחא דאוירא, ומוחא סתימאה, ואיך עולים לרישא דלא אתיידע, שה\"ס א\"ס ב\"ה. שהוא ענין גבוה ונסתר מאד. ע\"כ התפלל שגילוי הסודות הללו יהיה לרצון לפני השי\"ת."],[0,"דכד רעותא וכו':","כאשר רצון העליון למעלה, למעלה שה\"ס כתרא דא\"א, עומד ונתקן על אותו רצון שלא נודע ולא נתפס לעולם, שה\"ס ראש עתיק הנקרא רישא דלא אתיידע, נעשה כתרא דא\"א משום זה, ראש הסותם ביותר למעלה. וראש הזה האציל מה שהאציל, ולא ידוע, הוא מוחא דאוירא דא\"א. והאיר מה שהאיר, בדרך סתום. הוא מוחא סתימאה דא\"א. וטעם הדברים מבאר לפנינו."],[1,"רעו דמחשבה וכו':","הרצון של מחשבה העליונה, הוא כתרא דא\"א, הנקרא \u0003רעותא עלאה,\u0004 ואחר שנתקן לבחינת ראש נקרא \u0003מחשבה עלאה,\u0004 הוא, לרדוף אחריו, אחר רדל\"א, ולקבל הארתו. אבל פרסא אחת נפרשה, בין רדל\"א לכתרא, ומתוך פרסא זו ברדיפת מחשבה העליונה, כתרא, אחר אורו של רדל\"א, האור מגיע ואינו מגיע אליו, כי הפרסא מעכבת עליו, וכך עד הפרסא מאיר מה שמאיר, ולא מפרסא ולמטה. וע\"כ, מחשבה העליונה מאירה בהארה סתומה למוחא סתימאה, ובאור שאינו ידוע למוחא דאוירא. והמחשבה עצמה שהוא כתרא, הוא בבחינת לא ידע."],[1,"","פירוש, ר\"ש ממשיך לבאר כאן ב' ענינים: א) איך הקץ כל בשר נהנה מהקרבנות שישראל מקריבים, בכדי ליישב שאלת ר\"א בנו. ב) ענין ההארה של ראש פרצוף עתיק דאצילות, הנק' רישא דלא אתיידע, שה\"ס אין סוף ב\"ה שממנו נמשך ענין יציאת המוחין דקטנות והמוחין דגדלות של ג' רישין של א\"א. הנקראים כתרא, מוחא דאוירא, ומוחא סתימאה שה\"ס יה\"ו של א\"א עצמו. וכן מבאר הקטנות והגדלות של הלבושים דא\"א הנקראים או\"א, ישסו\"ת, וזו\"ן. ואיך יה\"ו דלבושים נכללים ביה\"ו דא\"א גופיה, וכולם נכללים בראש עתיק הנזכר, הנק' רדל\"א שה\"ס א\"ס ב\"ה שהיא כונת הקרבן, כנ\"ל \u0003לאסתפקא דא בדא, ולאסתלקא וכו' עד אין סוף.\u0004"],[1,"וז\"ש חד פריסו אתפרם:","שפירושו עלית המלכות למקום בינה. ומסיימת שם המדרגה, שסיום חדש זה נקרא \u0003פרסא,\u0004 ועל ידי סיום זה, ירדו ג' הספירות בינה ותו\"מ מכל מדרגה להמדרגה שמתחתיה, (כנ\"ל דף כ\"ב אות ס\"ב ד\"ה ת\"ח ע\"ש) ונמצא בינה ותו\"מ דמחשבה עלאה שהוא כתרא, ירדו למוחא דאוירא. ובתו\"מ של מוחא דאוירא ירדו למוחא סתימאה. ובתו\"מ דמו\"ס ירדו לאו\"א וכו'. באופן שלא נשאר בכל מדרגה רק כתר וחכמה דכלים. שלא יכלו לקבל בהם מרדל\"א, רק ב' אורות נפש רוח, הנבחנים לו\"ק, ולקטנות של ג' רישין. וז\"ש \u0003וכדין ההוא מחשבה עלאה\u0004 שהוא כתרא דא\"א, \u0003נהיר בנהירו סתים,\u0004 מאיר בהארה סתומה למוחא סתימאה. דהיינו ו\"ק. \u0003דלא ידיע,\u0004 ולמוחא דאוירא מאיר באור שאינו נודע, דהיינו ג\"כ רק ו\"ק. \u0003וההוא מחשכה\u0004 עצמה, דהיינו כתרא דא\"א, \u0003לא, ידעו\u0004 דהיינו ג\"כ רק בחי' ו\"ק. אמנם יש הפרש ביניהם, כי \u0003נהירו סתים\u0004 פירושו, שגם בגדלות כשישיג ג\"ר ישאר סתום ולא יאיר לאחרים, ונחירו \u0003דלא ידיע,\u0004 פירושו שרק עתה אינו נודע אבל בגדלות יהיה נודע, וע\"כ נקרא מוחא דאוירא, כי בגדלות יוצאת הי' \u0003מאויר\u0004 שלו ונעשה \u0003אור. ולא ידע,\u0004 הוא כמו לא אתיידע. שפירושו, שגם בגדלות לא יהיה נודע. וכל אלו המיעוטים נעשו משום הפרסא שעלתה למקום בינה וסיימה שם המדרגה, והורידה את בינה ותו\"מ דכל ראש להראש שמתחתיו, וכיון שלא נשארו אלא ב' כלים בכל ראש. לא יכלו לקבל יותר מב' אורות שהם נ\"ר, הנבחנים לו\"ק."],[2,"כדין בטש וכו':","אז, הארה זו של המחשבה שלא נודע, הכה בהארת הפרסא העומדת, והמאירה בג' המעוטים הנ\"ל שהם, ממה שאינו ידוע במוחא דאוירא. ואינו נודע, בכתרא ולא נגלה במוחא סתימאה, וכך הכה הארת המחשבה שלא נודע, שהיא רדל\"א בהארת הפרסא, ומאירים יחד. פירוש, כי הארת רדל\"א הכה וחזר והוריד הפרסא למקומה למלכות, שעל ידי זה חזרו לכל מדרגה ג' הכלים בינה ותו\"מ שנפלו ממנה, ונשלמו שוב בכח\"ב תו\"מ דכלים ובנרנח\"י דאורות. וז\"ש \u0003וכדין, דא נהירו דמחשבה דלא אתיידע, בטש בנהירו דפריסא, ונהרין כחדא.\u0004 כי ע\"י ביטוש הזה חזרו להאיר בכל השלימות כמקודם לכן. ומ\"ש \u0003ונהרין כחדא.\u0004 שמשמע, שג' רישין דא\"א הכלולים בהפרסא, מאירים יחד עם רדל\"א. הענין הוא. כי ראש עתיק הנקיא רדל\"א, היא בחינת ראש הנוקבא דעתיק, שהיא נתקנה בסוד \u0003בקע\u0004 (כנ\"ל בראשית א' דף ה' אות ב' ד\"ה וזה) ונמצא שבעת עלית הפרסא למקום בינה, נפלו גם בינה ותו\"מ דרדל\"א למקום הג' רישין דא\"א, ועתה אחר שנעשה הביטוש, החוזר ומעלה הבינה והתו\"מ מכל המדרגות, עלו ג\"כ בינה ותו\"מ דרדל\"א למקומם. ונודע שעם עלית בינה ותו\"מ דעליון עולה עמהם גם התחתון, שהחזיק בהם מקודם לכן, (כנ\"ל ב\"א דף י' אות ה' ד\"ה אי בהאי) ונמצא לפי\"ז, שג' רישין דא\"א עלו לרדל\"א עם חזרת בינה ותו\"מ שלה, ונעשו למדרגה אחת. וז\"ש \u0003ונהרין כחדא\u0004 שג' רישין דא\"א מאירים ביחד עם רדל\"א, כי נעשו עתה למדרגה אחת."],[2,"ואתעבידו ט' היכלין וכו':","ונעשו מהם ט' היכלות, ברדל\"א. כי הג' רישין דא\"א נכללות זו מזו והם \u0003תשע נהורין\u0004 במקומם עצמם, דהיינו בא\"א, ועל ידי עלותם לרדל\"א, \u0003ונהרין כחדא\u0004 (כנ\"ל. בדיבור הסמוך) נעשו שם ברדל\"א \u0003תשע היכלות.\u0004 ואין הפירוש שהט' אורות נעדרו ממקומם עצמם בסבת העליה לרדל\"א, אלא הפירוש הוא שמאירים בשני מקומות: שהם ט' היכלות ברדל\"א, והם ט' אורות במקומם עצמם. כי אין העדר ברוחני אלא כל תנועה יורה רק תוספות."],[3,"והיכלין, לאו אינון וכו':",": והיכלות הללו אינם אורות, כמו הט' אורות דא\"א במקומם עצמם. ואינם רוחות ואינם נשמות, ואין מי שיעמוד עליהם מה הם. כי אור א\"ס ב\"ה מאיר ברישא דלא אתיידע, וע\"כ נבחנים \u0003תשע היכלין\u0004 הללו שנעשו ברדל\"א, לבחינת א\"ס, שאין מחשבה תפיסה בו, כמ\"ש לפנינו."],[3,"רעותא דכל תשע נהורין וכו':","הרצון של כל תשע האורות, דג' רישין דא\"א, שכולם עומדים במחשבה, דהיינו במקומן בא\"א הנקרא מחשבה, שהוא אחד מהם בחשבון. שהמחשבה דא\"א הוא אחד מהתשעה האורות. והוא לאפוקי היותם ברדל\"א שאין רדל\"א מבחינתם כלל. הנה רצון כולם הוא לרדוף אחריהם דתשעה היכלין העומדים במקום רדל\"א בשעה שהתשע אורות עומדים בהמחשבה, שהוא א\"א, אבל ההיכלות אינם מושגים ואינם נודעים להט' אורות כי אלו ט' היכלות אינם עומדים לא בבחינת רצין, ולא בבחינת מחשבה העליונה, שהיא א\"א, תופסים בה ואינם תופסים. באלו ט' היכלין, נמצאים ועומדים כל סודות האמונה. וכל אלו האורות מסוד המחשבה העליונה, שהיא א\"א, מקובלים מהם, כולם, כל הט' היכלין. נקראים \u0003אין סוף.\u0004 כי עד כאן האורות מגיעים ואינם מגיעים, ואינם נודעים, אין כאן לא רצון ולא מחשבה."],[4,") כד נהיר מחשבה ולא ידיע וכו':","כאשר מאירה המחשבה שלא נודעה ממי היא מאירה, דהיינו מוחא דאוירא כנ\"ל. וכה היא נתלבשה ונסתמה תוך הבינה, ומאירה למי שמאירה, ונכנסים זו בזו עד שנכללים כולם כאחד."],[4,"","פירוש. כי נתבאר לעיל (באות קכ\"ד ד\"ה כדין בטש) שעל ידי הביטוש דנהירו דרדל\"א בנהירו דפרסא, חזרה הפרסא למקומה למלכות, ובינה ותו\"מ שנפלו מכל המדרגות חוזרות למעלתם למקומם כבתחילה. ע\"ש. ונמצא שגם הבינה שיצאה מראש דא\"א, חזרה עתה לראש א\"א ומקבלת שמה שוב אור החכמה. גם נודע שבהיות חכמה דא\"א בחוסר חסדים ע\"כ הבינה נסתמה שם. בסוד עמיק וסתים בשמא, (כנ\"ל בהקדמת הזהר דף כ\"ב אות י\"ד בד\"ה קיימא ולא קיימא עש\"ה.) כי הז\"ת דבינה אינן יכולות לקבל חכמה בלי לבוש החסדים, כמ\"ש שם."],[4,"","וז\"א, \u0003כד נהיר מחשבה ולא ידיע ממאן דנהיר,\u0004 דהיינו ראש הב' דא\"א הנקרא מוחא דאוירא. שהוא מאיר בג\"ר, אחר ביטוש רדל\"א באור הפרסא כנ\"ל, (בד\"ה כדין בטש) אשר אז חוזרת גם הבינה לראש דא\"א, כנ\"ל. \u0003כדין אתלבש ואסתים גו בינה,\u0004 נמצא אז שמתלבש בהארתו ונסתם תוך הבינה. כי הבינה עלתה לראש ומלבשת אותו, ואור החכמה שמקבלת ממנו סותמתה. כמבואר. ומ\"ש \u0003מחשבה ולא ידיע,\u0004 שהוא מוחא דאוירא, הוא בדיוק, להוציא ב' ראשים דא\"א האחרים,שהם כתרא, ומו\"ס, שהם אינם מאירים לאחרים, כי כתרא הוא בבחינת \u0003לא ידע,\u0004 להיותה מלבישה לרדל\"א. ומו\"ס \u0003בנהירו סתים,\u0004 כנ\"ל (באות קכ\"ג ד\"ה רעו דמחשבה ע\"ש). וע\"כ נבחן, שגם אחר שעלתה לראש א\"א, אינה מלבשת אותם, אלא למוחא דאוירא בלבדו."],[4,"","ונתבאר שם (בהק' הזהר דף כ\"ג אות י\"ד ד\"ה וז\"ש) שבכדי לפתוח הארת החכמה מסתימתה נעשה זווג הממשיך קומת חסדים, ונתלבשה החכמה בהחסדים, ואז נגלה הארתה ע\"ש. וז\"ש כאן, \u0003ונהיר למאן דנהיר\u0004 דהיינו שנזדווג והאיר קומת החסדים, הנק' \u0003לבוש יקר דנהיר,\u0004 כמ\"ש שם. ועל ידי זה \u0003ואעיל דא בדא\u0004 שהחכמה נכנסה ונתלבשה בתוך אור החסדים, וכן אור החסדים נכללה באור החכמה, עד \u0003דאתכלילו כלהו כחדא,\u0004 עד שנכללו כולם כאחד, דהיינו לרבות גם זו\"ן הנכללים ג\"כ בזווג הזה, להיותם הגורמים ליציאת קומת החסדים בהבינה (כנ\"ל בראשית א' דף רפ\"ז אות שס\"ג ד\"ה תלת ע\"ש)."],[5,"וברזא דקרבנא כד סליק,","וכו'. ובסוד הקרבן, כשעולה על המזבח, נעשו כל אלו היחודים דג' רישין דא\"א ברדל\"א, ובינה בראש א\"א וכו' על דרך שנתבאר עד הנה, \u0003כלא אתקשר דא בדא,\u0004 שמתחילה נתקשר הכל זה בזה, כי בעת ירידת הפרסאות, שבינה ותו\"מ דכל מדרגה, חוזרים ממקום התחתון למדרגתם בהעליון, מעלים אז עמהם גם את התחתון, להיותו דבוק בהם, ונמצאים אלו בינה ותו\"מ החוזרים למדרגתם, שהם מקשרים כל תחתון בהעליון, ועל ידי זה נמצאים הזו\"ן עולים לבינה, והבינה לראש דא\"א, וראש דא\"א לרדל\"א לט' היכלות שבו. כנ\"ל. ונתבאר לעיל שעל ידי עליה זו נסתם הבינה מטעם חוסר חסדים. ואז, \u0003ונהיר דא בדא,\u0004 ומאירים זה בזה, כי מזדווג ומוציא קומת החסדים בסוד \u0003לבוש יקר דנהיר,\u0004 ואז מאירים החסדים בהחכמה והחכמה בחסדים כנ\"ל."],[5,"כדין קיימי כלהו בסליקו,","ואז נמצאים כל המדרגות בסוד העליה. כי בינה וזו\"ן נמצאים בהעליה לא\"א, לסוד ג' רישין שבו, וג' רישין דא\"א בהעליה לרדל\"א לסוד ט' היכלות אשר שם, כמ\"ש לעיל. ונמצא \u0003ומחשבה אתעטר באין סוף.\u0004 והמחשבה שה\"ס א\"א, נתעטר, בעלייתו לרדל\"א, בסוד אור אין סוף, דהיינו בהארת \u0003תשע היכלין\u0004 אשר ברדל\"א, שבהם מאיר אור אין סוף, כי \u0003ההוא נהירו דאתנהיר מניה מחשבה עלאה אקרי אין סוף.\u0004 כי אותו ההארה שהמחשבה עלאה, שהוא א\"א, מאירה משם, שהם תשע היכלין כנ\"ל. הוא נקרא אין סוף. \u0003ומניה אשתכח וקיימא, ונהיר למאן דנהיר.\u0004 וממנו, מא\"ס, נמצא, א\"א, עומד ומאיר למי שמאיר. ועל זה עומד הכל. דהיינו על המשכת אור א\"ס אל העולמות ע\"י א\"א, על דרך שנתבאר. \u0003זכאה חולקיהון דצדיקיא בעלמא דין ובעלמא דאתי,\u0004 אשרי חלקם של הצדיקים המעלים מ\"ן ומייחדים היחודים הגבוהים האמורים, בעוה\"ז ובעוה\"ב. כי נוחלים שני עולמות."],[6,"ת\"ח האי קץ כל בשר","וכו': בוא וראה קץ כל בשר הזה, הנה כמו שהקישור נמצא למעלה, בבינה וא\"א, בשמחה, דהיינו התקשרות כל תחתון בעליון. ע\"י חזרת בינה ותו\"מ למדרגתם, הגורם להם שמחה, אחר שנתלבשה החכמה בחסדים, אף כמו כן למטה, בזו\"ן ועולמות התחתונים. נעשה התקשרות כל תחתון בעליון בשמחה ורצון ליתן סיפוק לכל, למעלה ולמטה דהיינו גם לקץ כל בשר. ואימא, היא השכינה, שורה על ישראל כראוי."],[7,"ת\"ח בכל רישי,",": בוא וראה בכל ראש חדש ור\"ח בעת שהלבנה מתחדשת, דהיינו שהנוקבא מתחדשת בזווגה עם ז\"א, נותנים אז לקץ כל בשר זה, חלק נוסף על קרבנות הרגילים, שהוא שעיר ר\"ח, שיתעסק בו וישתמש בחלקו, שע\"י שעיר ר\"ח נתחדש הארת צד השמאל, שהקץ כל בשר נהנה ממנו, והוא חלקו (כנ\"ל באות ק\"ד ד\"ה וכדין ישראל, ע\"ש) וישאר הצד של ישראל, שהוא הימין, להם לבדם, כדי שיתיחדו במלכם. וזה הוא שמקריבים דוקא שעיר, משום שהוא בחלקו של עשו שכתוב בו שעיר, שכתוב, הן עשו אחי איש שעיר, ועל כן הקץ כל בשר משתמש בחלקו של עשו שהוא צד שמאל, וישראל משתמשים בחלקם, שהוא צד ימין. ועל כן כתוב, כי יעקב בחר לו יה ישראל לסגולתו"],[8,"ת\"ח האי קץ וכו':","בוא וראה, קץ כל בשר זה, כל רצונו תמיד אינו אלא בבשר ומשום זה, תקון הבשר, בכל מקום שהוא, רק בשבילו. ועל כן נקרא קץ כל בשר. וכשהוא שולט, שולט על הגוף. שהוא בשר. ולא על הנשמה. הנשמה מסתלקת למקומה, והבשר, דהיינו הגוף, ניתן למקום הזה, דהיינו לקץ כל בשר. כמו זה הוא בקרבן שהרצון של המקריבו עולה למקום אחד דהיינו להקדושה, והבשר של הקרבן עולה למקום אחד, דהיינו לקץ כל בשר."],[8,"","פירוש. כי מהותם של הקליפות הם מהכלים הנשברים שנשתיירו מזמן שביה\"כ, שגם בעת שהמאציל בירר ותקן העולמות אבי\"ע וכל אשר בהם, לא תקן אותם, ואינם ראוים לתקונם במשך שתא אלפי שני מטרם גמר התקון. אבל בגמר התקון יתוקנו גם הם, ואז יתבטלו כל הקליפות, כמ\"ש בלע המות לנצח. ועתיד הס\"מ להיות מלאך קדוש, כנודע. ומכאן תבין שכל כחם להחטיא את האדם, הוא כי להיותם ריקנים מכל אור מטרם גמה\"ת, ע\"כ רודפים אחר האדם שימשיך להם מעט מאורות השלמים שיאירו בגמה\"ת, כדי לחיות את נפשם בדומה לרעב וצמא הרודף אחר מי שיש לו לחם ומים ולוחם עמו. וז\"ס שאמרו ז\"ל על עצה\"ד שהחטא היה מפני שאכלו פגה שהפירוש הוא מחוסר זמן, כי עצה\"ד הוא מהאורות השלמים, שלא יתוקנו אלא בגמר התקון, שהאורות הללו ישלימו הקליפות ויתקנו אותם, וע\"כ רדף הס\"מ והנחש לפתות לאדם וחוה שימשיכו לו מאור הזה תכף. ואע\"פ שידעו שעוד אינם ראוי לזה כי מחוסרי זמן המה, מ\"מ נופל להם איזה חלק מכח החטא כנודע."],[8,"","ונודע שה' הכלים כח\"ב תו\"מ מכונים מוחא עצמות גידין בשר ועור. ונמצא שכלי, דת\"ת נק' בשר, וכלי דמלכות נק' עור. גם נודע שמטעם גניזו דאו\"א הפנימים אחר שביה\"כ, אסור להמשיך מטרם גה\"ת הג\"ר של מוחין דחיה, שהוא אור החכמה, אלא רק ו\"ק בלבד. (כנ\"ל ב\"א דף פ' ע\"ו ד\"ה ביאור עש\"ה). ונודע שיש ערך הפכי בין כלים לאורות, ובזמן שאין לו לז\"א רק מוחא, יש לו רק אור הנפש. וכשמשיג פרצוף עצמות קונה אור הרוח, ובפרצוף גידין אור הנשמה, ובפרצוף בשר אור החיה, ובפרצוף עור אור היחידה. ולפי שאסור להמשיך ג\"ר דאור החיה. מטרם גמה\"ת, נמצא שבפרצוף הד' שהוא בשר, חסרים לו הכלים התחתונים ממנו, שהם בשר ועור, ואין לו בו אלא ג' כלים. שהם מוחא עצמות גידין, המסתיימים על החזה דפרצוף זה. ומחזה ולמטה. שהם בשר ועור דפרצוף בשר זה, חסרים לו עד גמה\"ת."],[8,"","ולפי המתבאר מובן. שכל חשקם של הס\"א הוא, שהאדם ימשיך להם אלו האורות דג\"ר דחיה. הבאים בהכלים דבשר ועור של פרצוף הד' דז\"א. כי פחות מזה. שהם האורות שאינם מאירים אלא בכלים המתוקנים, לא יוכלו הקליפות להנות מהם מאומה, כי אין להם כלום מכלים האלו, וז\"ס שאמרו לעיל (בהקדמת הזהר דף קצ\"ט אות ר\"י) שהחטא דעצה\"ד היה כי \u0003חבר לתתא ואתפרש לעילא\u0004 דהיינו שהמשיך האורות מחזה ולמטה דפרצוף הד', שהוא אור החכמה, לתוך הכלי \u0003דבשר.\u0004 והחטא דעצה\"ד הוא המקור שכל החטאים מסתעפים ממנו כנודע."],[8,"","וזה אמרו, \u0003האי קץ כל בשר לאו רעותיה אלא בבשרא תדיר,\u0004 דהיינו להמשיך לו הג\"ר דחיה, המאירים אחר גמר התקון, כי מהאורות הנוהגים לפני גמה\"ת אין לקליפות שום הנאה, כי ע\"כ המה בחינות קליפות משום שאין להם כלים המתוקנים לקבלת אורות הללו כנ\"ל. ע\"כ אין רצונם של הקליפות, אלא \u0003בבשר,\u0004 דהיינו שימשיכו להם האור בבחינת הכלי דבשר דפרצוף הד'."],[8,"","ועם זה תבין, סוד שעיר ר\"ח, וכן כל הקרבנות שאז נמשך מבחינת ג\"ר הללו, ע\"י שליטת קו השמאל שברגע תחילת הזווג, אשר הקליפות מקבלים אז האור מבחינת הבשר שלהם, ואין בזה הפסד לקדושה כי חלק קטן הוא מאד, ועוד כי על ידי חלק זה שמקבלים, הם נפרדים מהקדושה, ואינם מקטרגים עוד על ישראל להחטיאם. ועיקר תיקון זה נעשה בשעיר ר\"ח. וז\"ש \u0003בכל רישי ירחא וירחא וכו'. ועל דא איהו אשתמש בחולקיה, וישראל אינון משתמשין בחולקיהון,\u0004 כי הס\"א נוטלת אותה הארת השמאל המאירה בתחילת הזווג, שזה חלקם כנ\"ל. וישראל נוטלים המוחין השלמים המתוקנים בג' קוים שה\"ס ו\"ק דחיה, שזהו חלקם. ואחר שנעשה עיקר התקון בשעיר ר\"ח, נוהג ענין זה בכל הקרבנות. וז\"ש \u0003כגוונא דא בקרבנא דרעותא סלקא לאתר חד\u0004 שע\"י עלית מ\"ן שנק' רעותא זוכים הכהנים לוים וישראלים לקבל מוחין השלמים בהכלים המתוקנים בג' קוים כנ\"ל, \u0003ובשרא לאתר חד\u0004 דהיינו לסטרא אחרא, שבשר הוא חלקם, ולא דבר פחות ממנו, כנ\"ל. אלא שאין להם רק נהירו דקיק מרגע תחילת הזווג, כנ\"ל."],[9,"ובר גש דאיהו זכאה","וכו' ואדם שהוא צדיק, הוא עצמו קרבן ממש לכפר דהיינו ע\"י שמקריב \u0003רעותא\u0004 שלו. ואחר שאינו צדיק, הוא אינו קרבן, משום שיש בו מום, שכתוב, כי לא לרצון וגו'. וע\"כ הצדיקים הם כפרה של העולם והם קרבן בעולם, בוא וראה, ויאמר אלקים לנח קץ כל בשר בא לפני. היינו הס\"א כנ\"ל, והוא בא לקבל רשות להחשיך פניהם של בני אדם, ומשום זה, והנני משחיתם את הארץ."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, הֲרִימוֹתִי יָדַי בִּתְפִלּוֹת לְמַעְלָה, שֶׁכְּשֶׁרָצוֹן הָעֶלְיוֹן לְמַעְלָה לְמַעְלָה עוֹמֵד עַל אוֹתוֹ רָצוֹן שֶׁלֹּא נוֹדָע וְלֹא נִתְפָּס כְּלָל לְעוֹלָמִים, הָרֹאשׁ הַיּוֹתֵר נִסְתָּר שֶׁלְּמַעְלָה, וְאוֹתוֹ הָרֹאשׁ מוֹצִיא מַה שֶּׁמּוֹצִיא, וְלֹא יָדוּעַ, וּמֵאִיר מַה שֶּׁמֵּאִיר הַכֹּל בְּסֵתֶר."],[1,"","רְצוֹן הַמַּחֲשָׁבָה הָעֶלְיוֹנָה לִרְדֹּף אַחֲרָיו וְלִהְיוֹת מוּאָר מִמֶּנּוּ. מָסָךְ אֶחָד נִפְרָד. וּמִתּוֹךְ אוֹתוֹ מָסָךְ בִּרְדִיפַת אוֹתָהּ מַחֲשָׁבָה עֶלְיוֹנָה מַגִּיעָה וְלֹא מַגִּיעָה עַד אוֹתוֹ מָסָךְ, מְאִירָה מַה שֶּׁמְּאִירָה. וְאָז אוֹתָהּ מַחֲשָׁבָה עֶלְיוֹנָה מְאִירָה בְּאוֹר (בסתר) נִסְתָּר שֶׁלֹּא יָדוּעַ, וְאוֹתָהּ מַחֲשָׁבָה לֹא יוֹדֵעַ."],[2,"","וְאָז מַכֶּה אוֹר הַמַּחֲשָׁבָה הַזֶּה שֶׁלֹּא נוֹדָע בָּאוֹר שֶׁל הַמָּסָךְ שֶׁעוֹמֵד, שֶׁמֵּאִיר מִמַּה שֶּׁלֹּא יָדוּעַ וְלֹא נוֹדָע וְלֹא הִתְגַּלָּה. וְאָז (נ\"א: זה) זֶה אוֹר הַמַּחֲשָׁבָה שֶׁלֹּא נוֹדָע מַכֶּה בָּאוֹר שֶׁל הַמָּסָךְ, וּמְאִירִים כְּאֶחָד. וְנַעֲשִׂים תִּשְׁעָה הֵיכָלוֹת."],[3,"","וְהַהֵיכָלוֹת אֵינָם אוֹרוֹת וְלֹא רוּחוֹת וְלֹא נְשָׁמוֹת, וְאֵין מִי שֶׁעוֹמֵד בָּהֶם. הָרָצוֹן שֶׁל כָּל תִּשְׁעָה הָאוֹרוֹת שֶׁעוֹמְדִים כֻּלָּם בַּמַּחֲשָׁבָה, שֶׁהוּא אֶחָד מֵהֶם בְּחֶשְׁבּוֹן כֻּלָּם לִרְדּף אַחֲרֵיהֶם. בְּשָׁעָה שֶׁעוֹמְדִים בַּמַּחֲשָׁבָה וְלֹא נִדְבָּקִים וְלֹא נוֹדָעִים. וְאֵלֶּה לֹא עוֹמְדִים לֹא בְּרָצוֹן וְלֹא בְּמַחֲשָׁבָה עֶלְיוֹנָה (עליונות). תּוֹפְסִים בָּהּ וְלֹא תוֹפְסִים. בְּאֵלֶּה עוֹמְדִים כָּל סוֹדוֹת הָאֱמוּנָה וְכָל אוֹתָם הָאוֹרוֹת מִסּוֹד הַמַּחֲשָׁבָה הָעֶלְיוֹנָה (שלמטה ולמטה) כֻּלָּם נִקְרָאִים אֵין סוֹף. עַד כָּאן מַגִּיעִים אוֹרוֹת וְלֹא מַגִּיעִים וְלֹא נוֹדָעִים. אֵין כָּאן רָצוֹן וְלֹא מַחֲשָׁבָה."],[4,"","(אז) כְּשֶׁמְּאִירָה הַמַּחֲשָׁבָה וְלֹא נוֹדַעַת (ידוע) מִמִּי שֶׁמְּאִירָה, אָז מִתְלַבֶּשֶׁת וְנִסְתֶּרֶת לְתוֹךְ הַבִּינָה וּמְאִירָה לְמִי שֶׁמְּאִירָה, וְנִכְנָסִים זֶה בָּזֶה, עַד שֶׁכֻּלָּם נִכְלָלִים כְּאֶחָד."],[5,"","וּבְסוֹד הַקָּרְבָּן כְּשֶׁעוֹלֶה, הַכֹּל נִקְשָׁר זֶה בָּזֶה וּמֵאִיר זֶה בָּזֶה. אָז עוֹמְדִים כֻּלָּם בַּעֲלִיָּה, וְהַמַּחֲשָׁבָה מִתְעַטֶּרֶת עִם אֵין סוֹף. אוֹתוֹ הָאוֹר שֶׁמּוּאֶרֶת מִמֶּנּוּ הַמַּחֲשָׁבָה הָעֶלְיוֹנָה שֶׁלֹּא נוֹדַעַת בָּהּ כְּלָל נִקְרָא אֵין סוֹף, וּמִמֶּנּוּ נִמְצָא וְעוֹמֵד וּמֵאִיר לְמִי שֶׁמֵּאִיר, וְעַל זֶה הַכֹּל עוֹמֵד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[6,"","בֹּא רְאֵה, קֵץ כָּל בָּשָׂר הַזֶּה, כְּמוֹ שֶׁהַקֶּשֶׁר נִמְצָא לְמַעְלָה בְּשִׂמְחָה, גַּם כָּאן לְמַטָּה בְּחֶדְוָה, וְרָצוֹן לְהִסְתַּפֵּק הַכֹּל לְמַעְלָה וּלְמַטָּה. וְהָאֵם עוֹמֶדֶת עַל יִשְׂרָאֵל כָּרָאוּי."],[7,"","בֹּא רְאֵה, בְּכָל רֹאשׁ חֹדֶשׁ וְחֹדֶשׁ כְּשֶׁמִּתְחַדֶּשֶׁת הַלְּבָנָה, נוֹתְנִים לְקֵץ כָּל בָּשָׂר הַזֶּה חֵלֶק אֶחָד יוֹתֵר עַל הַקָּרְבָּנוֹת לְהִתְעַסֵּק בּוֹ וְיִשְׁתַּמֵּשׁ בְּחֶלְקוֹ, וְיִהְיֶה צַד שֶׁל יִשְׂרָאֵל לְבַדָּם כְּדֵי שֶׁיִּתְאַחֲדוּ עִם מַלְכָּם, וְזֶהוּ הַשָּׂעִיר, מִשּׁוּם שֶׁהוּא בְּחֵלֶק עֵשָׂו, שֶׁכָּתוּב בּוֹ שָׂעִיר, (בראשית כז) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. וְעַל זֶה הוּא הִשְׁתַּמֵּשׁ בְּחֶלְקוֹ, וְיִשְׂרָאֵל מִשְׁתַּמְּשִׁים בְּחֶלְקָם, וְלָכֵן כָּתוּב (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ."],[8,"","בֹּא רְאֵה, קֵץ כָּל בָּשָׂר הַזֶּה, כָּל רְצוֹנוֹ אֵינוֹ אֶלָּא בְּבָשָׂר תָּמִיד, וְלָכֵן תִּקּוּן הַבָּשָׂר תָּמִיד אֵלָיו, וְלָכֵן נִקְרָא קֵץ כָּל בָּשָׂר. וּכְשֶׁהוּא שׁוֹלֵט, שׁוֹלֵט עַל הַגּוּף וְלֹא עַל הַנְּשָׁמָה. הַנְּשָׁמָה עוֹלָה לִמְקוֹמָהּ, וְהַבָּשָׂר נִתָּן לַמָּקוֹם הַזֶּה. כְּמוֹ זֶה בְּקָרְבָּן, שֶׁהָרָצוֹן עוֹלֶה לְמָקוֹם אֶחָד, וְהַבָּשָׂר לְמָקוֹם אֶחָד."],[9,"","וְהָאִישׁ שֶׁהוּא צַדִּיק, הוּא קָרְבָּן מַמָּשׁ לְכַפָּרָה, וְאַחֵר שֶׁאֵינוֹ צַדִּיק אֵינוֹ קָרְבָּן, מִשּׁוּם שֶׁיֵּשׁ בּוֹ מוּם, שֶׁכָּתוּב (ויקרא כב) כִּי לֹא לְרָצוֹן וְגוֹ'. וְעַל זֶה הַצַּדִּיקִים הֵם כַּפָּרַת הָעוֹלָם וְהֵם קָרְבָּן בָּעוֹלָם. בֹּא רְאֵה, וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. לִטֹּל רְשׁוּת לְהַחְשִׁיךְ פְּנֵי בְּנֵי הָעוֹלָם. וְלָכֵן הִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ. (ועל זה עשה לך תבת עצי גפר, כדי להנצל בה ולא יוכל לשלט עליך, רבי חייא ורבי יוסי היו הולכים בדרך אמר אחד). כָּתוּב וַיַּעַשׂ נֹחַ כְּכֹל אֲשֶׁר צִוָּהוּ ה'."]]],[["תָּא חֲזֵי, מַה כְּתִיב וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה וְגו'. וְכִי אַמַּאי אֲתָא חוּשְׁבְּנָא דָא לְמִמְנֵי. אֶלָּא אִילוּ לָא הֲוָה נֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה לָא יֵיעוּל לְתֵיבוּתָא וְלָא יִתְחַבַּר בַּהֲדָהּ. כֵּיוָן דְּאִשְׁתַּלִּים בְּשֵׁשׁ מֵאוֹת שָׁנָה כְּדֵין אִתְחַבַּר בַּהֲדָהּ.","וְעַל דָּא מִן יוֹמָא דְּאִשְׁתַּלִּים חוֹבַיְיהוּ דִּבְנֵי עָלְמָא אוֹרִיךְ לוֹן קוּדְשָׁא בְּרִיךְ הוּא עַד דְּאִשְׁתַּלִּים נֹחַ בְּשֵׁשׁ מֵאוֹת שָׁנָה וְאִשְׁתַּלִּים דַּרְגֵּיהּ כְּדְקָא יְאוּת וְהֲוָה צַדִּיק שְׁלִים. וּכְדֵין עָאל לְתֵיבוּתָא. וְכֹלָּא כְּגַוְונָא דִּלְעֵילָא: וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה כְּמָה דְאֲמָרָן. וּבְגִינֵי כָךְ לָא אִתְּמָר כְּבֶן שֵׁשׁ מֵאוֹת שָׁנָה. (ד\"א ל\"ג לקביל שית סטרין דעלמא). תּוּ פָּתַח וְאָמַר וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם. מַאי טַעְמָא הִנְנִי כֵּיוָן דְּאָמַר וַאֲנִי. אֶלָּא אֲנִי אָנֹכִי (נ\"א הנני) כֹּלָּא מִלָּה חָדָא הִיא.","תָּא חֲזֵי, בְּכָל אֲתַר אֲנִי אִתְעֲבִיד גּוּפָא לְנִשְׁמְתָא וַדַּאי דִּמְקַבְּלָא מִמַּה דִּלְעֵילָא. וּבְגִין כָּךְ אִתְרְמִיז בְּאָת קַיָּימָא דִּכְתִיב אֲנִי הִנֵּה בְּרִיתִי אִתָּךְ. אֲנִי דְּקָיְימָא בְּאִתְגַּלְּיָא מְזוּמֶנֶת לְמִנְדַע. אֲנִי כָּרְסְיָא לְמַה דִּלְעֵילָא. אֲנִי דְּעֲבִידְנָא נוּקְמִין לְדָרֵי דָרִין. וַאֲנִי כָּלִיל דְּכַר וְנוּקְבָא כְּחֲדָא. לְבָתַר אִתְרְשִׁים בִּלְחוֹדוֹי דְּאִזְדַּמַּן לְמֶעְבַּד דִּינָא. הִנְנִי. מֵבִיא אֶת הַמַּבּוּל מַיִם.","כֵּיוָן דְּאָמַר מֵבִיא אֶת הַמַּבּוּל לָא יְדַעְנָא דְּאִיהוּ מַיִם. אֶלָא אֶת הַמַּבּוּל לְאַסְגָאָה מַלְאַךְ הַמָּוֶת, דְּאַף עַל גַּב דְּמַיָא הֲווּ. מְחַבְּלָא (לחבלא בהון מחבלא) (ד\"א הוה) אָזִיל בְּעָלְמָא לְשֵׁיצָאָה בְּאִנּוּן מַיִין.","אֲנִי יְיָ, הָכִי תָּנִינָן נְאֱמָן אֲנָא לְשַׁלְּמָא אֲגַר טַב לְצַדִּיקַיָּא וּלְאִתְפָּרַע מֵרַשִׁיעַיָּא. וּבְגִין כָּךְ אַבְטַח לוֹן קְרָא לְצַדִּיקַיָּא בְּאֲנִי לְשַׁלְּמָא אֲגַר טַב דִּלְהוֹן לְעָלְמָא דְאָתֵי. וְאַגְזִים לְרַשִׁיעַיָּא לְאִתְפְּרַע מִנַּיְיהוּ לְעָלְמָא דְאָתֵי בְּאֲנִי.","לְשַׁחֵת כָּל בָּשָׂר. כְּמָה דְאוֹקִימְנָא דְּדָא הוּא מְחַבְּלָא דְעָלְמָא. וְעַל דָּא כְּתִיב, (שמות י״ב:כ״ג) וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגוֹף. וְדָא הוּא לְשַׁחֵת כָּל בָּשָׂר מִסִּטְרָא דְּקֵץ כָּל בָּשָׂר בָּא לְפָנַי. דְּהָא כֵּיוָן דְּמָטָא זִמְנָא דְּאוֹרִיךְ לוֹן קוּדְשָׁא בְּרִיךְ הוּא (ד\"א ל\"ג ואוריך לון) עַד דְּאַשְׁלִים נֹחַ לְשֵׁשׁ מֵאוֹת שָׁנָה כְּדֵין לְשַׁחֵת כָּל בָּשָׂר. אָמַר הָכִי אוֹלִיפְנָא מִשְׁמֵיהּ דְּרַבִּי יִצְחָק (ס\"א ברבי יוסי מחוזאי) דְּאָמַר לָן (נ\"א האי דאמרי לכון).","פָּתַח וְאָמַר, (ישעיהו ל״ח:י״א) אָמַרְתִּי לֹא אֶרְאֶה יָהּ יָהּ בְּאֶרֶץ הַחַיִּים לֹא אַבִּיט אָדָם עוֹד עִם יוֹשְׁבֵי חָדֶל. אָמַרְתִּי לא אֶרְאֶה יָהּ, כַּמָּה אֲטִימִין אִנּוּן בְּנִי נָשָׁא דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בְּמִלֵּי דְאוֹרַיְיתָא, אֶלָּא מִסְתַּכְּלֵי בְּמִלּוֹי דְעָלְמָא וְאִתְנְשֵׁי מִנַּיְיהוּ רוּחָא דְחָכְמְתָא.","דְּכַד בַּר נָשׁ אִסְתַּלַּק מֵהַאי עָלְמָא וְיָהִיב חוּשְׁבְּנָא לְמָארֵיהּ מִכָּל מַה דְּעֲבַד בְּהַאי עָלְמָא בְּעוֹד דְּאִיהוּ קָאִים רוּחָא וְגוּפָא כְּחֲדָא וְחָמֵי מַה דְּחָמֵי, עַד דְּאָזִיל לְהַהוּא עָלְמָא וּפָגַע לֵיהּ לְאָדָם הָרִאשׁוֹן יָתִיב לְתַרְעָא דְגִנְתָּא דְעֵדֶן לְמֶחמֵי כָּל אִנּוּן דְּנָטְרוּ פִּקּוּדֵי דְמָארֵיהוֹן וְחָדֵי בְּהוּ.","וְכַמָּה צַדִּיקַיָּא סָחֳרָנֵיהּ דְּאָדָם. אִנּוּן דְּאִתְמְנָעוּ מֵאָרְחָא דְּגֵיהִנֹּם וְסָטוּ לְגַבֵּי אָרְחָא דְּגַן עֵדֶן. וְאִלֵּין אִקְרוּן יוֹשְׁבֵי חָדֶל. וְלָא כְּתִיב יוֹשְׁבֵי חָלֶד. בְּגִין דְּלָא הֲווּ כְּמוֹ חוּלְדָה דְּגָרְרָא וּמַנְחָא וְלָא יָדְעָא לְמַאן שַׁבְקָא. אֶלָּא יוֹשְׁבֵי חָדֶל. כְּמָא דְאַתְּ אָמֵר, (ישעיהו ב׳:כ״ב) חִדְלוּ לָכֶם מִן הָאָדָם וְגו' (אלא יושבי חדל) דְּאִתְמְנַע לוֹן מֵאָרְחָא דְּגִיהִנֹּם. וְאַתְקִיפוּ בְּהוּ לְאַעָלָא לְהוּ בְּגִנְתָּא דְעֵדֶן.","דָּבָר אַחֵר יוֹשְׁבֵי חָדֶל אִנּוּן מָרֵיהוֹן דִּתְשׁוּבָה דִּמְנָעוּ גַּרְמַיְיהוּ מֵאִנּוּן חוֹבִין דְּחַיָּיבַיָא. וּבְגִין דְּאָדָם הָרִאשׁוֹן תָּב בִּתְיוּבְתָּא קַמֵּי מָארֵיהּ. יָתִיב (נ\"א עם) עַל אִנּוּן דְּאִתְמְנָעוּ מֵחוֹבֵיהוֹן וְאִנּוּן בְּנֵי חָדֶל. כְּמָא דְאַתְּ אָמֵר, (תהילים ל״ט:ה׳) אֵדְעָה מֶה חָדֵל אָנִי. וּבְגִין כָּךְ אִיהוּ יָתִיב לְתַרְעָא דְּגִנְתָּא דְּעֵדֶן וְחָדֵי בְּהוּ בְּצַדִּיקַיָּא דְּאַתְיָין בְּהַהוּא אוֹרְחָא דְּגִנְתָּא דְּעֵדֶן.","תָּא חֲזֵי, מַה כְּתִיב אָמַרְתִּי לא אֶרְאֶה יָהּ. וְכִי מַאן יָכִיל לְמֶחמֵי יָהּ. אֶלָּא סוֹפָא דִקְרָא אוֹכַח דִּכְתִיב יָהּ בְּאֶרֶץ הַחַיִּים. תָּא חֲזֵי, כַּד (תרומה קמא) סָלְקִין נִשְׁמָתִין לְאֲתַר צְרוֹרָא דְחַיֵּי. תַּמָּן מִתְהַנָּן בְּזָהֳרָא דְּאַסְפַּקְלַרְיָאה דְּנָהֲרָא דְּנָהִיר מֵאֲתַר עִלָאָה דְכֹלָּא. וְאִילוּ לָא מִתְלַבְּשָׁא נִשְׁמָתָא בְּזָהֲרָא דִלְבוּשָׁא אָחֳרָא לָא תִיכוֹל לְאִתְקָרָבָא לְמֶחמֵי הַהוּא נְהוֹרָא."],[[0,"ת\"ח מה כתיב","וכו': בוא וראה, מה כתוב, ונח בן שש מאות שנה וגו', ושואל, למה בא הכתוב למנות חשבון הזה, של שני נח. ומשיב, אלא אלו לא היה נח בן שש מאות שנה. לא היה נכנס להתיבה, ולא היה מתחבר עמה. כיון שנשלם בשש מאות שנה אז נתחבר עמה. פירוש. כי אמר לעיל דף ב' אות ו ' שהתבה היא כנגד הנוקבא של מעלה, ונח כננד יסוד של מעלה. ויסוד הוא ספירה הששית של ז\"א. ולפיכך, כל עוד שלא נשלמו לו שש מאות שנה, לא היה עוד ראוי להיות מרכבה לספירה הששית. ומה שחושב מאות, הוא לרמז על המוחין שלו שהיו מבינה שה\"ס מאות."],[1,"ועל דא מן יומא","וכו': וע\"כ מיום שנשלמו עונותיהם של בני העולם, דהיינו שנעשו ראוים לקבל עונשם, המתין עוד להם הקב\"ה, עד שנשלם נח בשש מאות שנה, ונשלם מדרגתו כראוי, והיה צדיק שלם ואז נכנס להתיבה והכל כעין של מעלה. כלומר, הכל נעשה, באופן שיהיה עליו השראה מיסוד ומלכות של מעלה. וז\"ש,, כמו שאמרנו, ומשום זה לא נאמר כבן שש מאות שנה. כי שש מאות שנה הוא בדיוק, כדי להשלים ספירת היסוד, כנ\"ל."],[2,"תו פתח ואמר","וכו': עוד פתח ואמר, ואני הנני מביא את המבול מים, ושואל מה הטעם שאומר הכתוב הנני, אחר שכבר אמר ואני. כי אומר ואני הנני. ומשיב, אלא \u0003אני הנני,\u0004 הכל דבר אחד הוא. בוא וראה, בכל מקום שכתוב אני, נעשה גוף לנשמה, כלומר אני, היא הנוקבא. שהיא בחינת גוף לז\"א, הנבחן כנשמה שלה. ודאי שמקבלת ממה שלמעלה, מז\"א. ומשום זה מרומזת המלה אני, באות הברית, דהיינו עם \u0003ו'\u0004 שהוא יסוד דז\"א, שכתוב אני הנה בריתי אתך. משום שמקבלת מברית דז\"א, אני יורה העומדת להתגלות המזומנת להשגה. \u0003אני\u0004 יורה: אני כסא למה שלמעלה. \u0003אני\u0004 יורה: אני העושה נקמה לדורי דורות. ואני, שכתוב כאן עם \u0003ו'\u0004 יורה שכלול דכר ונוקבא ביחד, כי ה \u0003ו'\u0004 של ואני, יורה על הדכר שהוא ז\"א. ואח\"כ נרשמה הנוקבא בלבדה בלי ז\"א, בעת שנזדמנה לעשות הדין, דכתיב \u0003הנני\u0004 מביא מבול מים על הארץ. וכתוב הנני בלי \u0003ו'\u0004 ובזה מיושב מ\"ש כאן, \u0003ואני הנני,\u0004 כי \u0003ואני\u0004 כתוב עם \u0003ו'\u0004 שיורה על ז\"א המחובר בהנוקבא הנקראת אני, וזהו קודם שנגמר לעשות הדין. ואח\"כ שכבר נגמר, כתוב \u0003הנני\u0004 בלא ו', להורות שהדין נעשה על ידי הנוקבא בלבדה בלי ז\"א."],[3,"כיון דאמר","וכו'. שואל, מאחר שאומר, מביא את המבול, אין אנו יודעים עוד שהוא מים עד שהוצרך לומר המבול מים. ומשיב, אלא את המבול, הוא לרבות מלאך המות, שהיה שם, כי אע\"פ שהיו רק מים, היה המחבל הולך בעולם להשחיתם במים האלו."],[4,"אני ה'","וכו': אני ה', כך למדנו, שהוא יורה, נאמן אני לשלם שכר טוב לצדיקים ולהפרע מרשעים, וע\"כ מבטיח הכתוב לצדיקים עם המלה \u0003אני\u0004 לשלם שכרם הטוב לעולם הבא. וכן מאיים לרשעים להפרע מהם לעולם הבא עם המלה אני. פירוש. כי השם אני יורה דקיימא באתגליא, ואין התגלות, אלא על גילוי שכר ועונש. ונמצא בהכרח, כי \u0003אני\u0004 יורה, נאמן אני לשלם שכר וכו'."],[5,"לשחת","כל בשר וכו': כמו שביארנוהו שזה הוא מחבל העולם, וע\"כ כתוב ולא יתן המשחית לבא אל בתיכם לנגוף, דהיינו שאינו נותן לו רשות, וזה הוא לשחת כל בשר, שהוא מצד המשחית המרומז בהכ', קץ כל בשר בא לפני. שפירושו בא לפני ליטול רשות, כי מאחר שהגיע הזמן שהמתין להם הקב\"ה, עד שנשלמו לנח שש מאות שנה, שאפשר לקיים בו ליתן שכר טוב לצדיקים, אז הוא הזמן להפרע מן הרשעים, וע\"כ אתן רשות להמשחית לשחת כל בשר. כנ\"ל דף כ\"ט ד\"ה בא לפני ע\"ש. אמר לו, כך למדנו משמו של רבי יצחק, שאמר לנו כך."],[6,"פתח ואמר","וכו': פתח ואמר, כתיב אמרתי לא אראה יה וגו'. אמרתי לא אראה יה: כמה אטומים הם בני אדם, שאינם יודעים ואינם משגיחים בדברי תורה אלא שמסתכלים בדברי העולם, ורוח החכמה נשכח מהם."],[7,"דכד ב\"נ","וכו': כי כשהאדם מסתלק מהעולם הזה, ונותן חשבון לרבונו מכל מה שעשה בעולם הזה, בעודו נמצא ברוח וגוף ביחד. והוא רואה מה שרואה, עד שבא לעולם האמת, ופוגע שם באדם הראשון, היושב בשער גן עדן, לראות כל אלו שומרי מצות רבונם, ושמח בהם."],[8,"וכמה צדיקים:","וכמה צדיקים הם מסביב אדה\"ר, שמנעו את עצמם מדרך הגיהנם ונטו לדרך הגן עדן, ואלו נקראים יושבי חדל. ושואל למה לא כתוב יושבי \u0003חלד:\u0004 ואומר, משום שאינם כמו החולדה, שגוררת ומצנעת ואינה יודעת למי היא עוזבת. אלא שהם יושבי \u0003חדל.\u0004 כמו שאתה אומר. חדלו לכם מן האדם וגו', שחדלו פירושו מנעו, אף כאן נקראים יושבי \u0003חדל,\u0004 משום שנמנעו מדרך הגיהנם. ונתגברו בעצמם להכנס בגן עדן."],[9,"ד\"א יושבי חדל:","פירוש אחר. יושבי חדל, פירושו בעלי תשובה שמנעו את עצמם מעונותיהם של הרשעים. ומשום שאדם הראשון חזר בתשובה לפני רבונו הוא יושב עם אלו ששבו ונמנעו מעונותיהם שהם נקראים בני חדל, כש\"א, אדעה מה חדל אני. ומשום זה אדה\"ר יושב בשער הגן עדן. והוא שמח בהם בהצדיקים הבאים בדרך גן עדן."],[10,"ת\"ח מה כתיב","וכו': בוא וראה מה כתוב, אמרתי לא אראה יה ושואל וכי מי הוא שיכול לראות יה. ומשיב סוף הכתוב מוכיח את הכונה, שכתוב יה בארץ החיים, בוא וראה כאשר הנשמות עולות להמקום צרור החיים הן נהנות שמה מזהר אספקלריא המאירה, המאיר ממקום העליון על כל המקומות. ואלו לא היתה מתלבשת הנשמה בזהר לבוש אחר, לא היתה יכולה להתקרב לראות אור ההוא. פירוש. כשזו\"ן עולים ומלבישים את או\"א עלאין אשר האור שלהם נקרא אור החיה. נקרא אז ז\"א \u0003עץ החיים,\u0004 וכן הוא נקרא \u0003אספקלריא המאירה\u0004 והנוקבא \u0003ארץ החיים.\u0004 ויסוד של ז\"א נקרא \u0003צרור החיים.\u0004 להיותו מקום הקבוץ של המוחין, הנגלים \u0003בתלת דוכתי,\u0004 שהם חולם שורק חירק, (כנ\"ל בראשית א' דף כ' אות י\"ב ע\"ש בהסולם), שהסוה\"כ יקוו המים מתחת השמים אל מקום אחד. שהם נקוים מתלת דוכתי, ובאים אל היסוד דז\"א הנקרא מקום אחד. וע\"כ נקרא צרור החיים. וכשהנשמות עולות לזו\"ן הם עולות עם אתוון אל\"ה דזו\"ן, שנפלו למקומם ונתדבקו בהם (כנ\"ל דף ט' ד\"ה ועד\"ז) והם סוד נה\"י דז\"א, שעקרם הוא קו אמצעי, שהוא יסוד דז\"א. הרי שמקום עליית הנשמות לז\"א, הוא ביסוד שלו הנקרא, \u0003צרור החיים,\u0004 ושם נהנים בזהר ז\"א הנקרא \u0003אספקלריא המאירה.\u0004 וענין הלבוש, יתבאר להלן בדיבור הסמוך."]],[[0,"","בֹּא רְאֵה מַה כָּתוּב, וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה וְגוֹ'. וְכִי לָמָּה בָּא הַחֶשְׁבּוֹן הַזֶּה לִמְנוֹת? אֶלָּא אִלּוּ לֹא הָיָה נֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה, לֹא יִכָּנֵס לַתֵּבָה וְלֹא יִתְחַבֵּר עִמָּהּ. כֵּיוָן שֶׁהִשְׁתַּלֵּם בְּשֵׁשׁ מֵאוֹת שָׁנָה, אָז הִתְחַבֵּר עִמָּהּ."],[1,"","וְעַל כֵּן, מִיּוֹם שֶׁהִשְׁתַּלֵּם חֶטְאָם שֶׁל בְּנֵי הָעוֹלָם, חִכָּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁהִשְׁתַּלֵּם נֹחַ בְּשֵׁשׁ מֵאוֹת שָׁנָה, וְנִשְׁלְמָה דַרְגָּתוֹ כָּרָאוּי וְהָיָה צַדִּיק שָׁלֵם, וְאָז נִכְנַס לַתֵּבָה. וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה, כְּמוֹ שֶׁאָמַרְנוּ. וְלָכֵן לֹא נֶאֱמַר כְּבֶן שֵׁשׁ מֵאוֹת שָׁנָה (ד\"א כנגד ששת צדדי העולם). עוֹד פָּתַח וְאָמַר, וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם. מָה הַטַּעַם הִנְנִי כֵּיוָן שֶׁאָמַר וַאֲנִי? אֶלָּא אֲנִי, אָנֹכִי, (הנני) - הַכֹּל זֶה דָּבָר אֶחָד."],[2,"","בֹּא רְאֵה, בְּכָל מָקוֹם אֲנִי נַעֲשֶׂה גּוּף לַנְּשָׁמָה, וַדַּאי שֶׁמְּקַבֶּלֶת מִמַּה שֶּׁלְּמַעְלָה, וְלָכֵן נִרְמָז בְּאוֹת הַבְּרִית, שֶׁכָּתוּב אֲנִי הִנֵּה בְּרִיתִי אִתָּךְ. אֲנִי שֶׁקַּיֶּמֶת בְּגָלוּי מְזֻמֶּנֶת לָדַעַת, אֲנִי כִּסֵּא לְמַה שֶּׁלְּמַעְלָה, אֲנִי שֶׁעוֹשָׂה נְקָמוֹת לְדוֹרֵי דוֹרוֹת. וַאֲנִי - כּוֹלֵל זָכָר וּנְקֵבָה כְּאֶחָד. אַחַר כָּךְ נִרְשָׁם לְבַדּוֹ, שֶׁהִזְדַּמֵּן לַעֲשׂוֹת דִּין. הִנְנִי. מֵבִיא אֶת הַמַּבּוּל מַיִם."],[3,"","כֵּיוָן שֶׁאָמַר מֵבִיא אֶת הַמַּבּוּל, לֹא יָדַעְנוּ שֶׁהוּא מַיִם? אֶלָּא אֶת הַמַּבּוּל, לְרַבּוֹת מַלְאַךְ הַמָּוֶת. שֶׁאַף עַל גַּב שֶׁהָיוּ מַיִם, הַמַּשְׁחִית (להשחית בהם) (היה) הוֹלֵךְ בָּעוֹלָם לְהַשְׁמִיד בְּאוֹתָם הַמַּיִם."],[4,"","אֲנִי ה' - כָּךְ שָׁנִינוּ, נֶאֱמָן אֲנִי לְשַׁלֵּם שָׂכָר טוֹב לַצַּדִּיקִים וּלְהִפָּרַע מֵהָרְשָׁעִים. וְלָכֵן הִבְטִיחַ לָהֶם הַפָּסוּק לַצַּדִּיקִים בַּאֲנִי, לְשַׁלֵּם שָׂכָר טוֹב שֶׁלָּהֶם לָעוֹלָם הַבָּא. וְאִיֵּם לָרְשָׁעִים לְהִפָּרַע מֵהֶם לָעוֹלָם הַבָּא בַּאֲנִי."],[5,"","לְשַׁחֵת כָּל בָּשָׂר - כְּמוֹ שֶׁהֶעֱמַדְנוּ, שֶׁזֶּהוּ הַמַּשְׁחִית שֶׁל הָעוֹלָם, וְעַל זֶה כָּתוּב (שמות יב) וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגֹּף. וְזֶה הוּא לְשַׁחֵת כָּל בָּשָׂר, מִצַּד שֶׁל קֵץ כָּל בָּשָׂר בָּא לְפָנַי. שֶׁהֲרֵי כֵּיוָן שֶׁהִגִּיעַ זְמַן שֶׁחִכָּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא (ד\"א וחכה להם) עַד שֶׁהִשְׁלִים נֹחַ לְשֵׁשׁ מֵאוֹת שָׁנָה, אָז לְשַׁחֵת כָּל בָּשָׂר. אָמַר, כָּךְ לָמַדְנוּ מִשְּׁמוֹ שֶׁל רַבִּי יִצְחָק (ס\"א ברבי יוסי מחוזאי), שֶׁאָמַר לָנוּ, (ס\"א זה שאמרתי לכם)."],[6,"","פָּתַח וְאָמַר, (ישעיה לח) אָמַרְתִּי לֹא אֶרְאֶה יָהּ יָהּ בְּאֶרֶץ הַחַיִּים לֹא אַבִּיט אָדָם עוֹד עִם יוֹשְׁבֵי חָדֶל. אָמַרְתִּי לֹא אֶרְאֶה יָהּ, כַּמָּה אֲטוּמִים הֵם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּדִבְרֵי הַתּוֹרָה, אֶלָּא מִסְתַּכְּלִים בְּדִבְרֵי הָעוֹלָם וְנִשְׁכַּחַת מֵהֶם רוּחַ חָכְמָה."],[7,"","שֶׁכְּשֶׁאָדָם מִסְתַּלֵּק מֵהָעוֹלָם הַזֶּה וְנוֹתֵן חֶשְׁבּוֹן לְרִבּוֹנוֹ מִכָּל מַה שֶּׁעָשָׂה בָּעוֹלָם הַזֶּה בְּעוֹד שֶׁהוּא קַיָּם רוּחַ וְגוּף כְּאֶחָד, וְרוֹאֶה מַה שֶּׁרוֹאֶה, עַד שֶׁהוֹלֵךְ לְאוֹתוֹ עוֹלָם וּפוֹגֵשׁ בְּאָדָם הָרִאשׁוֹן יוֹשֵׁב בְּשַׁעַר גַּן עֵדֶן לִרְאוֹת כָּל אוֹתָם שֶׁשָּׁמְרוּ אֶת מִצְווֹת רִבּוֹנָם וְשָׂמֵחַ בָּהֶם."],[8,"","וְכַמָּה צַדִּיקִים סְבִיב אָדָם. אֵלּוּ שֶׁנִּמְנְעוּ מִדֶּרֶךְ הַגֵּיהִנֹּם וְסָטוּ לְדֶרֶךְ גַּן הָעֵדֶן, וְאֵלֶּה נִקְרָאִים יוֹשְׁבֵי חָדֶל. וְלֹא כָתוּב יוֹשְׁבֵי חָלֶד, כִּי אֵינָם כְּמוֹ חֻלְדָּה שֶׁגּוֹרֶרֶת וּמַנִּיחָה וְלֹא יוֹדַעַת לְמִי מַנִּיחָה, אֶלָּא יוֹשְׁבֵי חָדֶל, כְּמוֹ שֶׁנֶּאֱמַר (שם ב) חִדְלוּ לָכֶם מִן הָאָדָם וְגוֹ', (אלא יושבי חדל) שֶׁנִּמְנְעוּ מִדֶּרֶךְ הַגֵּיהִנֹּם, וְהֶחֱזִיקוּ בָהֶם לְהַכְנִיסָם בְּגַן עֵדֶן."],[9,"","דָּבָר אַחֵר יוֹשְׁבֵי חָדֶל - אֵלּוּ בַּעֲלֵי תְשׁוּבָה שֶׁמָּנְעוּ עַצְמָם מֵאוֹתָם חֲטָאֵי הָרְשָׁעִים. וּמִשּׁוּם שֶׁאָדָם הָרִאשׁוֹן שָׁב בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ, יוֹשֵׁב (עם) עַל אוֹתָם שֶׁנִּמְנְעוּ מֵחֲטָאֵיהֶם וְהֵם בְּנֵי חָדֶל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) אֵדְעָה מֶה חָדֵל אָנִי. וְלָכֵן הוּא יוֹשֵׁב בְּשַׁעַר גַּן הָעֵדֶן וְשָׂמֵחַ בַּצַּדִּיקִים שֶׁבָּאִים בְּאוֹתָהּ דֶּרֶךְ שֶׁל גַּן עֵדֶן"],[10,"","בֹּא רְאֵה מַה כָּתוּב, אָמַרְתִּי לֹא אֶרְאֶה יָהּ. וְכִי מִי יָכוֹל לִרְאוֹת יָהּ? אֶלָּא סוֹף הַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב יָהּ בְּאֶרֶץ הַחַיִּים. בֹּא רְאֵה, כְּשֶׁהַנְּשָׁמוֹת עוֹלוֹת לִמְקוֹם צְרוֹר הַחַיִּים, שָׁם נֶהֱנִים בַּזֹּהַר שֶׁל הָאַסְפַּקְלַרְיָה שֶׁמְּאִירָה מֵהַמָּקוֹם הָעֶלְיוֹן שֶׁל הַכֹּל. וְאִלּוּ לֹא הִתְלַבְּשָׁה הַנְּשָׁמָה בַּזֹּהַר שֶׁל לְבוּשׁ אַחֵר, לֹא תוּכַל לְהִתְקָרֵב לִרְאוֹת אֶת אוֹתוֹ הָאוֹר."]]],[["וְרָזָא דְמִלָּה כְּמָה דְּיַהֲבֵי לְנִשְׁמָתָא לְבוּשָׁא דְּמִתְלַבְּשָׁא בֵּיהּ לְמֵיקַם בְּהַאי עָלְמָא. הָכִי נָמֵי יַהֲבֵי לָהּ לְבוּשָׁא דְּזָהֲרָא עִלָּאָה לְמֵיקַם בֵּיהּ בְּהַהוּא עָלְמָא וּלְאִסְתַּכָּלָא בְּגוֹ הַהוּא אַסְפַּקְלַרְיָאה דְּנָהֲרָא מִגּוֹ הַהוּא אֶרֶץ הַחַיִּים.","תָּא חֲזֵי, משֶׁה לָא יָכִיל לְקָרְבָא לְאִסְתַּכְּלָא בַּמֶּה דְאִסְתַּכַּל אֶלָּא כַּד אִתְלַבַּשׁ בִּלְבוּשָׁא אָחֳרָא כְּמָא דְאַתְּ אָמֵר (שמות כ״ד:י״ח) וַיָּבֹא משֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְתַרְגּוּם בִּמְצִיעוּת עֲנָנָא. וְאִתְלַבַּשׁ בָּהּ כְּמַאן דְּאִתְלַבַּשׁ בִּלְבוּשָׁא. וּבְגִין דָא (שמות כ׳:י״ח) וּמשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאֱלהִים וּכְתִיב, (שמות כ״ד:י״ח) וַיָּבֹא משֶׁה בְּתוֹךְ הֶעָנָן וְגו' וַיְהִי משֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְיָכִיל לְאִסְתַּכָּלָא בַּמֶּה דְאִסְתַּכַּל.","כְּגַוְונָא דָא מִתְלַבְּשִׁין נִשְׁמַתְהוֹן דְּצַדִּיקַיָא בְּהַהוּא עָלְמָא בִּלְבוּשָׁא כְּגַוְונָא דְּהַהוּא עָלְמָא דְּלָא יִתְנַהֵג אֶלָּא בִּלְבוּשָׁא כְּגַוְונָא דָא וְקָיְימֵי לְאִסְתַּכָּלָא בִּנְהוֹרָא דְּנָהִיר בְּהַהוּא אֶרֶץ הַחַיִּים. וְזֶהוּ יָהּ יָהּ בְּאֶרֶץ הַחַיִּים. דְּהֲוָה סָבִיר דְּלָא יִזְכֵּי לְהַהוּא נְהוֹרָא וּלְהַהוּא אִסְתַּכְּלוּתָא בְּגִין דְּנַהֲרָא דְּנָגִיד פָּסִיק לֵיהּ וְלָא אוֹלִיד. לא אַבִּיט אָדָם עוֹד דָּא אָדָם קַדְמָאָה כְּמָה דְּאִתְּמָר.","וְכָל דָא לָמָּה. בְּגִין דְּאָמַר לֵיהּ נְבִיאָה כִּי מֵת אַתָּה בְּהַאי עָלְמָא וְלָא תִחְיֶה לְהַהוּא עָלְמָא. בְּגִין. דְּמָאן דְּלָא (הוה) אוֹלִיד בְּנִין בְּהַאי עָלְמָא, כַּד נָפִיק מִנֵּיהּ מְתַרְכִין לֵיהּ מִכָל מַה דְּאֲמָרָן. וְלָא שַׁרְיָא לְמֶחמֵי בְּהַהוּא נְהוֹרָא דְּנָהִיר (כל שכן וכל שכן שאר עמא ושאר בני נשא). וּמַה חִזְקִיָּה דְּהֲוָה לֵיהּ זְכוּת אָבוֹת וְאִיהוּ זַכָּאָה צַדִּיק וַחֲסִידָא כָּךְ. כָּל שֶׁכֵּן מַאן דְּלֵית לֵיהּ זְכוּת אָבוֹת וְחָטֵי קַמֵּי מָארֵיהּ.","הַאי לְבוּשָׁא דְּקָאֲמָרָן אִיהוּ (אנון) מַה דְּאָמְרוּ חַבְרַיָיא חֲלוּקָא דְּרַבָּנָן דְּאִתְלְבִישׁוּ בְּהַהוּא עָלְמָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא דְּגָנִיז לוֹן קוּדְשָׁא בְּרִיךְ הוּא כַּמָּה טָבִין וְעִידוּנִין לְהַהוּא עָלְמָא, עֲלַיְיהוּ כְּתִיב, (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלהִים זוּלָתֶךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ:","וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם עַל הָאָרֶץ. רַבִּי יְהוּדָה פָּתַח (במדבר כ׳:י״ג) הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ וַיִּקָּדֵשׁ בָּם. וְכִי בְּאֲתַר אָחֳרָא לֹא רָבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ. מַאי שְׁנָא הָכָא דְּקָאָמַר הֵמָּה מֵי מְרִיבָה וְלָא אָחֳרָנִין. אֶלָּא הַנֵּי מֵי מְרִיבָה הֲווּ וַדַּאי דְּיָהֲבוּ חֵילָא וְתוּקְפָא לְמָארֵיהוֹן דְּדִינָא לְאִתְתַּקְפָא. בְּגִין דְּאִית מַיִין מְתוּקִין וְאִית מַיִין מְרִירָן. אִית מַיִין צְלִילָן וְאִית מַיִין עֲכִירָן. אִית מַיִין שְׁלָם וְאִית מַיִין קְטָטוּ. וְעַל דָּא הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ, דְּאַמְשִׁיכוּ עֲלַיְיהוּ לְמַאן דְּלָא אִצְטְרִיךְ וְאִסְתְּאִיבוּ בֵּיהּ הֲדָא הוּא דִכְתִיב וַיִּקּ1ָדִשׁ בָּם.","אָמַר לֵיהּ רַבִּי חִזְקִיָה אִי הָכִי מַאי וַיִּקָּדֵשׁ וַיִּקָּדֵשׁוּ מִבָּעֵי לֵיהּ. אֶלָּא מִלָּה אִסְתְּלִיקַת. וַיִּקָּדֵשׁ אִתְפְּגִים מַאן דְּלָא אִצְטְרִיךְ. כִּבְיָכוֹל דְּאִתְפְּגֵימַת סִיהֲרָא. וַיִּקָּדֵּשׁ לָאו לְשִׁבְחָא אִיהוּ הָכָא. וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל כְּמָה דְּאוֹקִימְנָא לְאַיְיתָאָה מְחַבְּלָא עֲלַיְיהוּ כְּמָה דְאִנּוּן אִסְתְּאָבוּ בֵּיהּ.","אָמַר רַבִּי יוֹסֵי וַוי לוֹן לְרַשִּׁיעַיָא דְּלָא בָּעָאן לְאֲתָבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל חוֹבֵיהוֹן בְּעוֹד דְּאִנּוּן בְּהַאי עָלְמָא. דְּכַד בַּר נָשׁ אָתִיב וְאִתְנֶחָם עַל חוֹבוֹי. קוּדְשָׁא בְּרִיךְ הוּא מָחִיל לֵיהּ. וְכָל אִנּוּן דְּמִתְתַּקְפִין בְּחוֹבַיְיהוּ וְלָא בָּעוּ לְאֲתָבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל (חובוי) חוֹבֵיהוֹן. לְבָתַר (ינפול) יִנְפְּלוּ לְגֵּיהִנֹּם וְלָא יִסְקוּן לֵיהּ מִתַּמָּן לְעָלְמִין.","תָּא חֲזֵי, בְּגִין דְּאַתְקִיפוּ לִבַּיְיהוּ כָּל אִנּוּן דָּרָא דְּנֹחַ וּבָעוּ לְאַחֲזָאָה חוֹבַיְיהוּ בְּאִתְגַּלְיָא. קוּדְשָׁא בְּרִיךְ הוּא אַיְיתֵי דִינָא עֲלַיְיהוּ בְּהַהוּא גַוְונָא. אָמַר רַבִּי יִצְחָק וְאֲפִילּוּ כַּד חָטֵי בַּר נָשׁ בְאִתְכַּסְיָא קוּדְשָׁא בְּרִיךְ הוּא רַחֲמָן. וְאִי תָּב בַּר נָשׁ לְגַבֵּיהּ חָפֵי עֲלֵיהּ וּמָחִיל לֵיהּ וְשָׁבִיק לֵיהּ. וְאִי לָא, גָּלֵי לֵיהּ לְעֵינֵי כֹלָּא. מְנָלָן מִסּוֹטָה.","וְהָכִי נָמֵי אִתְמְחוּן אִלֵּין חַיָּיבַיָא מֵאַרְעָא בְּאִתְגַּלְיָא. וְהֵיךְ אִתְמְחוּן. אֶלָּא דְּהֲווּ נָפְקֵי מַיָיא וְהֲווּ רְתִיחָן מִן תְּהוֹמָא וְסָלְקֵי וְאַעֲבַר מִנַּיְיהוּ מָשְׁכָא. וְכֵיוָן דְּאַעֲבַר מִנַּיְיהוּ מָשְׁכָא הָכִי נָמֵי בִּשְׂרָא וְלָא אִשְׁתְּאָרוּ אֶלָּא בְּגַרְמַיְיהוּ לְחוֹד. לְקַיְימָא דִכְתִיב וַיִּמָּחוּ מִן הָאָרֶץ. וְכָל אִנּוּן גַּרְמֵי אִתְפָּרְדָן דָּא מִן דָּא וְלָא אִשְׁתָּאֲרוּ כְּחֲדָא. וּמִכֹּלָא אִתְעֲבָרוּ מֵעָלְמָא. רַבִּי יִצְחָק אָמַר וַיִּמָּחוּ מִן הָאָרֶץ, מַאי וַיִּמָּחוּ, כְּמָא דְאַתְּ אָמֵר יִמָּחוּ מִסֵּפֶר חַיִּים. מִכָּאן אוֹלִיפְנָא דְּלֵית לוֹן תְּחִיָּה לְעָלְמִין וְלָא יְקוּמוּן בְּדִינָא."],[[0,"ורזא דמלה","וכו': וסוד הדבר, כמו שנותנים להנשמה לבוש להתקיים בו בעולם הזה, שהוא הגוף, כמו כן נותנים להנשמה לבוש זהר העליון, להתקיים בו בעולם הבא ולהסתכל בתוך \u0003אספקלריאה דנהרא,\u0004 שהוא ז\"א, מתוך \u0003ארץ החיים\u0004 ההוא, שהיא הנוקבא דז\"א, ומיושב מה שהקשה בהכתוב, אמרתי לא אראה יה, כי הכונה היא באמצעות ב' התקונים הללו, א) על ידי לבוש זהר העליון ב) על ידי הנוקבא דז\"א הנקראת ארץ החיים. שע\"י ב' תקינים הללו זוכים הצדיקים להסתכל באספקלריא המאירה. שה\"ס יה בארץ החיים כמ\"ש להלן בסמוך."],[1,"ת\"ח משה:","בוא וראה, משה, לא היה יכול לגשת להסתכל במה שנסתכל, אלא כאשר התלבש בלבוש אחר. כמש\"א, ויבא משה בתוך הענן וגו' ותרגום במציעות עננא, ונתלבש בו כמו שמתלבשים בלבוש, ומשום זה, ומשה נגש וגו'. וכתוב ויבא משה וגו' ויהי משה בהר וגו' והיה יכול להסתכל במה שנסתכל."],[2,"כגוונא דא וכו':","כמו זה, מתלבשות נשמות הצדיקים בעולם האמת, בלבוש כעין עולם ההוא, שלא יתנהגו אלא בהתאם לאיתו הלבוש. ואז הם מוכנים להסתכל באור המאיר בארץ החיים ההוא. דהיינו באור הנוקבא שמתוכה הם מסתכלים בתוך אספקלריאה המאירה כנ\"ל וזהו, יה יה בארץ החיים, שאמר חזקיהו, שהיה חושב, שלא יזכה עוד לאותו האור ולאותו הסתכלות, משום שנהר הנמשך, מג\"ע, הפסיקו ולא הוליד. כי מי שאינו עוסק בפריה ורביה פוגם בנהר היוצא מעדן שהוא יסוד דז\"א (כנ\"ל בהקדמה דף ר\"ו ד\"ה ברית) לא אביט אדם עוד, זהו אדם הראשון, כמו שאמרנו לעיל, שאדה\"ר יושב בשער נ\"ע ומקבל נשמות הצדיקים הבאים לג\"ע. וחזקיה חשב, שלא יזכה להביט אדם בשער הג\"ע."],[3,"וכל דא למה וכו':","וכל זה למה, למה חשב חזקיהו כל זה, הוא משום שאמר לו הנביא כי מת אתה בעולם הזה, ולא תחיה לעולם האמת, כי כל מי שאינו מוליד בנים בעולם הזה, כאשר נפטר ויצא ממנו, מגרשין אותו מכל מה שאמרנו לעיל, ואינו שורה שם לראות באותו אור המאיר, ומה חזקיהו שהיה נקי צדיק וחסיד היה לו כך, כל שכן, מי שאין לו זכות אבות וחטא לפני רבונו, על אחת כמה וכמה."],[4,"האי לבושא וכו':","לבוש הזה שאמרנו, הוא מה שאמרו החברים, שיש חלוקא דרבנן. שמתלבשים בעולם האמת. אשרי חלקם של הצדיקים שגנז להם הקב\"ה הרבה טוב ועדנים לעולם האמת, עליהם כתוב, עין לא ראתה אלקים זולתך יעשה למחכה לו."],[5,"ואני הנני מביא מבול וגו':",": ר\"י פתח, המה מי מריבה אשר רבו בני ישראל וגו'. ושואל, וכי במקום אחר לא רבו בני ישראל את ה', מה נשתנה כאן שאומר, המה מי מריבה, שמשמע, ולא אחרים, ומשיב. אלא, אלו היו מי מריבה, ודאי, שנתנו כח וגבורה לבעל הדין להתחזק. משום שיש מים מתוקים ויש מים מרורים, שה\"ס הקדושה והלעומת, דקו ימין. ויש מים צלולים ויש מים עכורים שה\"ס הקדושה והלעומת, של קו שמאל. יש מי שלום ויש מי מריבה, שה\"ס הקדושה והלעומת של קו האמצעי, ועל כן אוה\"כ, המה מי מריבה אשר רבו בני ישראל את ה', להורות שהוא הלעומת של קו אמצעי. כי המשיכו עליהם את מי שלא היו צריכים להמשיך, דהיינו את הלעומת הנקרא מי מריבה, ונטמאו בו. וז\"ש ויקדש בם."],[6,"א\"ל רבי חזקיה וכו':","א\"ל ר\"ח אם כן,מהו ויקדש שאוה\"ב, היה צריך לומר ויקדשו, לשון רבים, דקאי על בני ישראל. ומשיב אלא המלה מסתתרת, כי פירושה היא, שנפגם מי שלא היה צריך, כביכול, כי נפגמה הסיהרא, שהיא הנוקבא, והמלה ויקדשו לא לשבח כתוב כאן. והכתוב מסתיר ואינו רוצה לבטא את זה. ומסיק ר' יהודה, ואני הנני מביא את המבול הוא כמו שאמרנו, להביא את המחבל עליהם, כמו שהם נטמאו בו. פירוש, כמו שאמרנו במי מריבה, שהוא שם המחבל, שבו נטמאו, אף כאן, המבול הוא שם המחבל שנטמאו בו."],[7,"אמר רבי יוסי וכו':","אר\"י ווי להם לרשעים, שאינם רוצים לשוב לפני הקב\"ה על עונותיהם, בעודם בעה\"ז, כי כשבן אדם שב ומתחרט על עונותיו, הקב\"ה מוחל לו. וכל אלו שמחזיקים עונותיהם, ואינם רוצים לשוב לפני הקב\"ה על עונותיהם, נופלים אח\"כ לגיהנם ולא יעלו אותם משם לעולם."],[8,"ת\"ח בגין וכו':","בוא וראה, משום שכל בני דורו של נח חזקו את לבם ובקשו להראות עונם בגלוי, הביא עליהם הקב\"ה את הדין באותו האופן. אמר רבי יצחק ואפילו כשהאדם חוטא, אם הוא בסתר, הקב\"ה הוא רחמן, ואם האדם ישוב אליו, מכפר עליו ומוחל לו וסולח לו. ואם אינו שב אליו, מגלה חטאיו לעיני כל. מאין לנו זה, מן סוטה. שהיא חטאה בסתר, והקב\"ה מגלה עונה בגלוי ע\"י מים המאררים."],[9,"והכי נמי וכו':","וכמו כן נמחו הרשעים הללו מן הארץ בגלוי, דהיינו דור המבול. ואיך נמחו, אלא שהיו המים יוצאים ועולים מן התהום והם רותחים, והפשיטו מהם את עורם, וכיון שנפשט מהם העור, נפשט מהם אה\"כ גם הבשר, ולא נשארו אלא בעצמותיהם בלבד. לקיים הכתוב, וימחו מן הארץ. וכל עצמותיהם נפרדו זה מזה, ולא נשארו יחד. ומהכל נעברו מהעולם, \u0003רבי יצחק אמר, וימחו מן הארץ\u0004 מהו וימחו, הוא כמו שאתה אומר, ימחו מספר חיים, מכאן למדנו, שאין להם תחיה לעולמים, ולא יקומו בדין."]],[[0,"","וְסוֹד הַדָּבָר - כְּמוֹ שֶׁנּוֹתְנִים לַנְּשָׁמָה לְבוּשׁ שֶׁמִּתְלַבֶּשֶׁת בּוֹ לַעֲמֹד בָּעוֹלָם הַזֶּה, כָּךְ גַּם נוֹתְנִים לָהּ לְבוּשׁ שֶׁל זֹהַר עֶלְיוֹן לַעֲמֹד בָּהּ בְּאוֹתוֹ עוֹלָם וּלְהִסְתַּכֵּל בְּתוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁמְּאִירָה מִתּוֹךְ אוֹתָהּ אֶרֶץ הַחַיִּים."],[1,"","בֹּא רְאֵה, מֹשֶׁה לֹא יָכֹל לְהִתְקָרֵב לְהִסְתַּכֵּל בְּמַה שֶּׁהִסְתַּכֵּל אֶלָּא כְּשֶׁהִתְלַבֵּשׁ בִּלְבוּשׁ אַחֵר, כְּמוֹ שֶׁנֶּאֱמַר (שמות כד) וַיָּבא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְתַרְגּוּם, בְּאֶמְצָעוּת הֶעָנָן. וְהִתְלַבֵּשׁ בּוֹ כְּמִי שֶׁמִּתְלַבֵּשׁ בִּלְבוּשׁ. וְלָכֵן (שם כ) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאֱלֹהִים, וְכָתוּב (שם כד) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וְגוֹ', וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה, וְיָכֹל לְהִסְתַּכֵּל בְּמַה שֶּׁהִסְתַּכֵּל."],[2,"","כְּמוֹ זֶה מִתְלַבְּשׁוֹת נִשְׁמוֹת הַצַּדִּיקִים בְּאוֹתוֹ הָעוֹלָם בִּלְבוּשׁ כְּמוֹ שֶׁל אוֹתוֹ הָעוֹלָם, שֶׁלֹּא יִתְנַהֵג אֶלָּא בִּלְבוּשׁ כְּמוֹ זֶה, וְעוֹמְדִים לְהִסְתַּכֵּל בָּאוֹר הַמֵּאִיר בְּאוֹתָהּ אֶרֶץ הַחַיִּים. וְזֶהוּ יָהּ יָהּ בְּאֶרֶץ הַחַיִּים, שֶׁהָיָה סָבוּר שֶׁלֹּא יִזְכֶּה לְאוֹתוֹ אוֹר וּלְאוֹתָהּ הִסְתַּכְּלוּת, מִשּׁוּם שֶׁהַנָּהָר הַשּׁוֹפֵעַ מַפְסִיק אוֹתוֹ וְלֹא הוֹלִיד. לֹא אַבִּיט אָדָם עוֹד - זֶה אָדָם הָרִאשׁוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר."],[3,"","וְכָל זֶה לָמָּה? כִּי אָמַר לוֹ הַנָּבִיא, כִּי מֵת אַתָּה - בָּעוֹלָם הַזֶּה, וְלֹא תִחְיֶה - לָעוֹלָם הַבָּא. מִשּׁוּם שֶׁמִּי שֶׁלֹּא (היה) מוֹלִיד בָּנִים בָּעוֹלָם הַזֶּה, כְּשֶׁיּוֹצֵא מִמֶּנּוּ, מְגָרְשִׁים אוֹתוֹ מִכָּל מַה שֶּׁאָמַרְנוּ, וְלֹא שׁוֹרֶה לִרְאוֹת בְּאוֹתוֹ אוֹר הַמֵּאִיר (כל שכן וכל שכן לשאר העמים ושאר בני האדם). וּמָה חִזְקִיָּה שֶׁהָיְתָה לוֹ זְכוּת אָבוֹת וְהוא זַכַּאי צַדִּיק וְחָסִיד כָּךְ, כָּל שֶׁכֵּן מִי שֶׁאֵין לוֹ זְכוּת אָבוֹת וְחוֹטֵא לִפְנֵי רִבּוֹנוֹ."],[4,"","הַלְּבוּשׁ הַזֶּה שֶׁאָמַרְנוּ הוּא (הם) מַה שֶּׁאָמְרוּ הַחֲבֵרִים, חָלוּק שֶׁל רַבָּנָן שֶׁמִּתְלַבְּשִׁים בּוֹ בְּאוֹתוֹ הָעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁגָּנַז לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה טוֹבוֹת וְעִדּוּנִים לָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ."],[5,"","וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם עַל הָאָרֶץ. רַבִּי יְהוּדָה פָּתַח, (במדבר כ) הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה' וַיִּקָּדֵשׁ בָּם. וְכִי בְמָקוֹם אַחֵר לֹא רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה'? מַה שּׁוֹנֶה כָּאן שֶׁאָמַר הֵמָּה מֵי מְרִיבָה, וְלֹא אֲחֵרִים? אֶלָּא מֵי הַמְּרִיבָה הַלָּלוּ הָיוּ וַדַּאי שֶׁנָּתְנוּ כֹּחַ וְחֹזֶק לְבַעֲלֵי הַדִּין לְהִתְחַזֵּק. מִשּׁוּם שֶׁיֵּשׁ מַיִם מְתוּקִים וּמַיִם מְרִירִים. יֵשׁ מַיִם צְלוּלִים וְיֵשׁ מַיִם עֲכוּרִים. יֵשׁ מֵי שָׁלוֹם וּמֵי קְטָטָה. וְעַל זֶה, הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה', שֶׁהִמְשִׁיכוּ עֲלֵיהֶם אֶת מִי שֶׁלֹּא צָרִיךְ וְנִטְמְאוּ בוֹ. זֶהוּ שֶׁכָּתוּב וַיִּקָּדֵשׁ בָּם."],[6,"","אָמַר לוֹ רַבִּי חִזְקִיָּה, אִם כָּךְ, מַה זֶּה וַיִּקָּדֵשׁ? הָיָה צָרִיךְ לִהְיוֹת וַיִּקָּדְשׁוּ! אֶלָּא הַדָּבָר עָלָה. וַיִּקָּדֵשׁ - נִפְגַּם מִי שֶׁלֹּא צָרִיךְ. כִּבְיָכוֹל שֶׁנִּפְגְּמָה הַלְּבָנָה. וַיִּקָּדֵשׁ אֵינוֹ לְשֶׁבַח כָּאן. וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל, כְּמוֹ שֶׁבֵּאַרְנוּ, לְהָבִיא מַשְׁחִית עֲלֵיהֶם כְּמוֹ שֶׁהֵם נִטְמְאוּ בוֹ."],[7,"","אָמַר רַבִּי יוֹסֵי, אוֹי לָרְשָׁעִים שֶׁלֹּא רוֹצִים לָשׁוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל חֲטָאֵיהֶם בְּעוֹד שֶׁהֵם בָּעוֹלָם הַזֶּה. שֶׁכְּשֶׁאָדָם שָׁב וּמִתְנַחֵם עַל חֶטְאוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹחֵל לוֹ, וְכָל אוֹתָם שֶׁמַּחֲזִיקִים בַּחֲטָאֵיהֶם וְלֹא רָצוּ לָשׁוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל (חטאים) חֲטָאֵיהֶם, אַחַר כָּךְ (יפל) יִפְּלוּ לַגֵּיהִנֹּם וְלֹא יַעֲלוּ מִשָּׁם לְעוֹלָמִים."],[8,"","בֹּא רְאֵה, מִשּׁוּם שֶׁחִזְּקוּ אֶת לִבָּם כָּל אוֹתָם דּוֹרוֹ שֶׁל נֹחַ וְרָצוּ לְהַרְאוֹת חֶטְאָם בְּגָלוּי, הֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם הַדִּין בְּאוֹתוֹ הַגָּוֶן. אָמַר רַבִּי יִצְחָק, אֲפִלּוּ כְּשֶׁחוֹטֵא אָדָם בְּנִסְתָּר, הַקָּדוֹשׁ בָּרוּךְ הוּא רַחֲמָן. וְאִם שָׁב בֶּן הָאָדָם אֵלָיו, מְכַסֶּה עָלָיו וּמוֹחֵל לוֹ וּמְוַתֵּר לוֹ. וְאִם לֹא, הוּא מְגַלֶּה אוֹתוֹ לְעֵינֵי כֹל. מִנַּיִן לָנוּ? מִסּוֹטָה."],[9,"","וְכָךָ גַּם נִמְחוּ הָרְשָׁעִים הַלָּלוּ מֵהָאָרֶץ בְּגָלוּי. וְאֵיךְ נִמְחוּ? אֶלָּא שֶׁהָיוּ יוֹצְאִים מַיִם, וְהָיוּ רוֹתְחִים מֵהַתְּהוֹם, וְעוֹלִים וּמַעֲבִירִים מֵהֶם אֶת עוֹרָם. וְכֵיוָן שֶׁהָעֳבַר מֵהֶם הָעוֹר - כָּךְ גַּם הַבָּשָׂר, וְלֹא נִשְׁאֲרוּ אֶלָּא בָּעֲצָמוֹת שֶׁלָּהֶם בִּלְבַד, לְקַיֵּם אֶת מַה שֶּׁכָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ. וְכָל אוֹתָם הָעֲצָמוֹת נִפְרְדוּ זוֹ מִזּוֹ וְלֹא נִשְׁאֲרוּ כְּאֶחָד, וּמֵהַכֹּל הָעָבְרוּ מֵהָעוֹלָם. רַבִּי יִצְחָק אָמַר, וַיִּמָּחוּ מִן הָאָרֶץ, מַה זֶּה וַיִּמָּחוּ? כְּמוֹ שֶׁנֶּאֱמַר יִמָּחוּ מֵאֶרֶץ חַיִּים. מִכָּאן לָמַדְנוּ, שֶׁאֵין לָהֶם תְּחִיָּה לְעוֹלָמִים וְלֹא יָקוּמוּ בְּדִין."]]],[["וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ. אָמַר רַבִּי אֶלְעָזָר מֵהָכָא קִיּוּמָא דִּבְרִית לְעֵילָא כְּקִיוּמָא דִּבְרִית לְתַתָּא. מַשְׁמַע דִּכְתִיב אִתָּךְ. וְאָמַר רַבִּי אֶלְעָזָר מִכָּאן אוֹלִיפְנָא דְּכַד זַכָּאִין אִנּוּן בְּעָלְמָא אִתְקְיַּים עָלְמָא לְעֵילָא וְתַתָּא. אָמַר רַבִּי שִׁמְעוֹן מִלָּה סָתִים אִיהוּ. כַּד אִתְעֲרוּתָא דִדְכוּרָא לְגַבֵּי נוּקְבָא כַּד אִיהוּ מְקַנֵּי לָהּ.","תָּא חֲזֵי, רָזָא דְמִלָּה כַּד צַדִּיקָא אִיהוּ בְּעָלְמָא מִיָּד שְׁכִינְתָּא לָא אִתְעֲדִיאַת מִנֵּיהּ וְתִיאוּבְתָּא דִּילָהּ בֵּיהּ. כְּדֵין תִּיאוּבְתָּא דִלְעֵילָא לְגַבָּהּ בִּרְחִימוּ כְּתִיאוּבְתָּא דִדְכוּרָא לְנוּקְבֵיהּ כַּד אִיהוּ מְקַנִּי לָהּ. וְעַל דָּא וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ. אִתְעַר תִּיאוּבְתָּא בְּגִינָךְ. כְּגַוְונָא דָא (בראשית י״ז:כ״א) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק.","וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ לְמֶהֱוֵי אָת בְּרִיתִי בְּעָלְמָא. וּלְבָתַר וּבָאתָ אֶל הַתֵּבָה, דְּאִלְמָלֵא לָאו אִיהוּ צַדִּיק (ברית) לָא יֵיעוּל לְתֵיבוּתָא דְּהָא לָא אִתְחַבַּר לַתֵּבָה בַּר צַדִּיק, וּבְגִינֵי כָךְ וּבָאתָ אֶל הַתֵּבָה וְהָא אִתְּמָר.","אָמַר רַבִּי אֶלְעָזָר בְּכָל זִמְנָא דִּבְנֵי נָשָׁא יִתְאַחֲדוּן בִּבְרִית דָּא, וְלָא יִשְׁבְּקוּן לֵיהּ, לֵית עַם וְלִישָׁן בְּעָלְמָא דְּיֵיכוּל לְאַבְאָשָׁא לוֹן. וְנֹחַ אַתְקִיף בִּבְרִית דָּא וְנָטַר לֵיהּ, בְּגִינֵי כָךְ קוּדְשָׁא בְּרִיךְ הוּא נָטַר לֵיהּ (וכל דיליה). וְכָל בְּנִי דָרֵיהּ לָא נָטְרוּ לֵיהּ, בְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אַעֲבַר לוֹן מֵעָלְמָא. וְהָא אִתְּמָר בְּהַהוּא חוֹבָא מַמָּשׁ דְּאִנּוּן חָאבוּ בְּהַהוּא גַוְונָא אִתְמְחוּן מֵעָלְמָא.","רַבִּי יְהוּדָה הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, וְהֲווּ עָסְקֵי בְּהַאי קְרָא דִּכְתִיב, (מלכים א י״ח:ל׳) וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. מַאי וַיְרַפֵּא. תָּא חֲזֵי, בִּימֵי אֵלִיָּהוּ, יִשְׂרָאֵל כֻּלְהוּ שָׁבְקוּ לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא וְשָׁבְקוּ בְּרִית קַיָּימָא דִלְהוֹן. כַּד אֲתָא אֵלִיָּהוּ וְחָמָא דְקָא שָׁבְקוּ בְּנֵי יִשְׂרָאֵל הַאי בְּרִית קַיָּימָא וְאַעֲבָרוּ מִנַּיְיהוּ הַאי בְּרִית.","כֵּיוָן דְּחָמָא אֵלִיָּהוּ כָךְ אֲתָא לְאַתְקָנָא מִלָּה לְדוּכְתֵּיהּ. כֵּיוָן דְּקָרִיב מִלָּה לְדוּכְתֵּיהּ אִתְּסֵי כֹּלָּא. הֲדָא הוּא דִכְתִיב וַיְרַפֵּא אֶת מִזְבַּח יְיָ הֶהָרוּס. דָּא בְּרִית קַיָּימָא (ד\"א ל\"ג דאתא לאתקנא מזבח יי ההרוס ברית קיימא) דְּהֲוָה שָׁבִיק מֵעָלְמָא. וּכְתִיב, (מלכים א י״ח:ל״א) וַיִּקַּח אֵלִיָּהוּ שְׁתֵּים עֶשְׂרֵה אֲבָנִים לְמִסְפַּר שִׁבְטֵי בְּנֵי יַעֲקֹב. דָּא הוּא תִּקּוּנָא דְּמִזְבַּח יְיָ.","אֲשֶׁר הָיָה דְּבַר יְיָ אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. מַאי טַעְמָא אִדְכַּר הָכָא יִשְׂרָאֵל, אֶלָּא וַדַּאי יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ וַדַּאי לְאִסְתַּלָּקָא לְעֵילָא וְלְאֲתָבָא בְּרִית קַיָּימָא לְאַתְרֵיהּ. וְהַיְנוּ דִּכְתִיב כִּי עָזְבוּ בְּרִיתְךָ בְּנִי יִשְׂרָאֵל. וּבְגִין כָּךְ אֶת מִזְבְּחוֹתֶיךָ הָרָסוּ.","תָּא חֲזֵי, כָּל זִמְנָא דְּיִשְׂרָאֵל נָטְרוּ קְיָימָא קַדִּישָׁא כְּדֵין עָבְדֵי קִיּוּמָא לְעֵילָא וְתַתָּא. וְכַד שָׁבְקֵי לְהַאי בְּרִית כְּדֵין לָא אִשְׁתְּכַח קִיּוּם לְעֵילָא וְתַתָּא דִּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי. וּבְגִין כָּךְ וַיְרַפֵּא אֶת מִזְבַּח יְיָ הֶהָרוּס. וְכִי רְפוּאָה אִיהוּ. הָכִי הוּא וַדַּאי דְּהָא מְקַיֵּים לְהַהוּא אֲתַר דִּמְהֵימְנוּתָא תַּלְיָא בֵּיהּ.","תָּא חֲזֵי, אוּף הָכִי פִּנְחָס בְּשַׁעֲתָא דְקַנֵּי לְעוֹבָדָא דְזִמְרִי אַתְקִין לְהַאי בְּרִית בְּאַתְרֵיהּ. וּבְגִין כָּךְ כְּתִיב, (במדבר כ״ה:י״ב) הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וְכִי סַלְקָא דַעְתָּךְ דִּבְגִין פִּנְחָס הֲוָה. וּמַה קְטָטָא הֲוָה לֵיהּ לְפִנְחָס בְּהַאי בְּרִית. אֶלָּא הָכָא אִתְקְשַׁר מִלָּה בְּדוּכְתֵּיהּ. הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי. וּמָה אֶתֵּן לוֹ שָׁלוֹם (לאתחברא כל חד בדוכתיה) לְאִתְחַבְּרָא בְּרִית בְּאַתְרֵיהּ. וְעַל דָּא הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי (שלום). וּמַה (נ\"א איהו) שָׁלוֹם דְּאִיהוּ אַתְרֵיהּ לְאִתְחַבְּרָא בַּהֲדֵיהּ. מַה דְּאִתְפָּרַשׁ מִנֵּיהּ בְּחוֹבַיְיהוּ. בְּגִינֵיהּ אִתְחַבַּר בֵּיהּ. וְעַל דָּא הוֹאִיל וְהוּא אַתְקִין מִלָּה בְּדוּכְתֵּיהּ, מִכָּאן וּלְהָלְאָה וְהָיְתָה לוֹ וּלְזַרְעוֹ אַחֲרָיו בְּרִית כְּהֻנַּת עוֹלָם, תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו וְגו'.","אָמַר רַבִּי שִׁמְעוֹן לֵית לָךְ מִלָּה בְּעָלְמָא דְּקוּדְשָׁא בְּרִיךְ הוּא קַנֵּי לָהּ כְּמוֹ חוֹבָא דִבְרִית כְּמָא דְאַתְּ אָמֵר, (ויקרא כ״ו:כ״ה) חֶרֶב נוֹקֶמֶת נְקַם בְּרִית. וְתָּא חֲזֵי, לָא אִשְׁתְּלִים חוֹבָא דְדָרָא דְּטוֹפָנָא, אֶלָּא בְּגִין דְּחָבוּ בְּחַבִּילוּ (דארחייהו) עַל אַרְעָא. וְאַף עַל גַּב דְּהֲווּ מְקַפְּחֵי דָא לְדָא כְּדִכְתִיב וַתִּמָּלֵא הָאָרֶץ חָמָס (וחמס מכלא הוה ובגין כך) וּכְתִיב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. מִכָּל מָקוֹם וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. וְהִנְנִי מַשְׁחִיתָם מִדָּה כְּנֶגֶד מִדָּה, הִנְנִי מַשְׁחִיתָם בְּחוֹבָא דְּחַבָּלוּתָא."],[[0,"והקימותי את בריתי אתך וכו'","אמר רבי אלעזר, מכאן נשמע, שקיום הברית שלמעלה הוא כקיום הברית של מטה. זהו משמע ממה שכתוב \u0003אתך.\u0004 פירוש, ברית ה\"ס יסוד, קיום הברית היינו סוד זווג זו\"ן. והכתוב \u0003והקמותי את בריתי,\u0004 קאי על זווג זו\"ן. \u0003אתך\u0004 היינו על ידי התחברותך בהתיבה. כי נח ותיבה הם יסוד ומלכות שלמטה, ובהם תלוי זווג יסוד ומלכות של מעלה שהם זו\"ן."],[0,"ואר\"א מכאן וכו'","ואמר ר' אלעזר, מכאן למדנו, כשיש צדיקים בהעולם מתקיים העולם למעלה ולמטה. פירוש. הנוקבא נקראת \u0003עולם\u0004 למעלה. וקיום פירושו זווג. וכשיש צדיקים בעולם התחתון, גורמים זווג זו\"ן למעלה, ומתקיימת הנוקבא על ידיהם, וזה נשמע מהכתוב והקמות את בריתי אתך, כנ\"ל בדיבור הסמוך. ושם ביאר ר\"א בקיום הברית העליון, ע\"י נח. וכאן מבאר הכתוב בקיום הנוקבא על ידי נח."],[1,"אר\"ש מלה וכו'","אמר ר\"ש דבר סתר הוא, כי התעוררות הזכר להנקבה היא בעת שמקנא אותה. בוא וראה סוד הדבר, כי כשיש צדיק בעולם, מיד, אין השכינה מסתלקת ממנו, ותשוקתה היא אליו, אז נתעוררת אליה תשוקה העליונה באהבה כתשוקת הזכר להנקבה בעת שמקנא אותה. וז\"ש והקמותי את בריתי אתך. שפירושו שנתעוררה בי התשוקה בגללך, כעין זה הכ' ואת בריתי אקים את יצחק, פירושו הוא בגלל יצחק. כמו בנח. פירוש. הנה הכל נמשך לעולם על ידי הנוקבא, בין התקונים ובין הקלקולים, כנודע בסו\"ה ומלכותו בכל משלה. וכשהשפעה היא מתוקנת, היא נמשכת מזווג זעיר אנפין ונוקביה. וכשהשפעה היא מקולקלת היא נמשכת מזווג זו\"ן דטומאה, הנקראים \u0003אל אחר,\u0004 שהוא מתדבק בהנוקבא דז\"א, (כנ\"ל דף ל\"ז אות ק\"ג), ומושך אליו השפע דקדושה ומהפכה לטומאה וקלקולים. וה\"ס הקנאה שז\"א מקנא את הנוקבא, שאל אחר לא יתדבק בה. וכשיש, צדיק בעולם, אז מתוך גודל חשקה של הנוקבא להשפיע אל הצדיק היא מתרחקת מאל אחר, והאהבה של הז\"א מתגברת עתה ביותר, להזדווג עם השכינה, להשפיע להצדיק, כמו שאהבת גבר מתגברת על אשתו בעת שמקנה אותה, ומפחד שלא תסתר עם אחר. כי כן ז\"א היה מפחד שהיא לא תתדבק להשפיע לאל אחר כנ\"ל."],[2,"והקימותי את בריתי אתך:","פירושו,שאתה תהיה בריתי בעולם, ואחר כך \u0003ובאת אל התיבה.\u0004 כי לולא היה צדיק לא היה נכנס אל התיבה, כי לא יתחבר איש בהתיבה רק צדיק, ומשום זה כתוב ובאת אל התיבה, אחר והקמותי את בריתי אתך. וכבר נתבאר."],[3,"אר\"א בכל זמנא וכו':","אמר ר\"א כל זמן שבני אדם מחזיקים בברית הזה, אין עם ולשון בעולם שיכול להרע להם. ונח החזיק בברית הזה ושמר אותו, משום זה שמר אותו הקב\"ה, וכל בני דורו לא שמרו הברית, משום זה העבירם הקב\"ה מן העולם. והנה אמרו, באותו החטא שחטאו באותו אופן ממש נמחו מהעולם. היינו כמ\"ש לעיל דף כ\"א אות נ\"ח ונ\"ט. ע\"ש."],[4,"ר' יהודה הוה שכיח וכו':","ר\"י היה מצוי לפני ר' שמעון, והיו עוסקים במקרא הזה, שכתוב, וירפא את מזבח ה' ההרוס, מהו כאן וירפא. בוא וראה, בימי אליהו, ישראל כולם עזבו את הקב\"ה, ועזבו את הברית קדש שלהם. כשבא אליהו וראה שבני ישראל עזבו את הברית קדש, והברית הוסר מהם. כיון שראה אליהו את זה, בא לתקן הדבר אל מקומו, היינו שבא לתקן היסוד שיהיה ראוי לזווג עם המלכות, שזה נבחן לרפואת המזבח, שהיא המלכות. כמ\"ש לפנינו."],[5,"כיון דקריב וכו':","כיון שהקריב הדבר למקומו, דהיינו שתקן היסוד להקריבו למלכות, נתרפא הכל, זהו שכתוב, וירפא את מזבח ה' ההרוס, שזה הוא הברית שהיה נעזב מהעולם, פירוש. המלכות נקראת מזבח ה', ונהרסה, מסבת הברית שעזבו בני ישראל. וכתוב, ויקח אליהו שתים עשרה אבנים למספר שבטי בני יעקב, זהו התיקון של מזבח ה'. דהיינו תקון ההריסה ורפואתו. כי פגם הברית, מהרס את בנין המלכות כי ט' ספירות תחתונות שלה נהרסות ונופלות לקליפות ותקון הברית חוזר ובונה אותה בעשרה ספירות, שבסוד הארת החכמה הן נחלקות לי\"ב. שז\"ס י\"ב אבנים."],[6,"אשר היה דבר ה' וגו':","שואל מה הטעם שנזכר כאן השם ישראל על המזבח, ואומר, אלא ודאי שהתקון הוא להעלותה למעלה. היינו להעלות המלכות לאו\"א. ולהשיב ברית קדש למקומו, היינו שהיסוד דז\"א יחזור ויזדווג עם המלכות שאין זווג לזו\"ן אלא אחר עלותם למקום או\"א. והיינו, שכתוב כי עזבו בריתך בני ישראל, ומשום זה את מזבחותיך, שהיא המלכות, הרסו. ובסוד תקון הברית היא חוזרת ונבנית."],[7,"ת\"ח כל זמנא וכו':","בוא וראה, כל זמן שישראל שומרים הברית קדש, הם עושים קיום למעלה ולמטה, וכשהם עוזבים ברית הזה אז אין קיום למעלה ולמטה. שכתוב אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי. ומשום זה כתוב כאן, וירפא את מזבח ה' ההרוס, ושואל, וכי נחשב זה לרפואה, ואומר, כן הוא ודאי, שהרי הוא מקיים לאותו מקום שהאמונה תלויה בו. כלומר, שהוא מקיים הברית, שהוא היסוד, אשר המלכות, הנקראת אמונה, תלויה בו."],[8,"ת\"ח אוף הכי פנחס וכו':","בוא וראה, אף פנחס כן, בשעה שקנא למעשה זמרי תקן את ברית הזה במקומו. ומשום זה כתוב, הנני נותן את בריתי שלום. וכי יעלה על דעתך, שבשביל פנחס הוא השלום, ומה הוא המחלוקת שהיה לו לפנחס עם ברית הזה. אלא כאן, בהמלה שלום, נקשר הדבר במקומו, והפירוש הוא, הנני נותן לו את בריתי, ומה אתן לו, להברית. שלום שפירושו זווג, שיתחבר הביית במקומו, שהיא המלכות, וע\"כ נאמר הנני נותן לו את בריתי שלום, ומהו שלום, הוא המקום להתחבר עמו, דהיינו הזווג עם המלכות, הנקרא בשם שלום. כי מה שנפרש ממנו, מהיסוד, מחמת עונותיהם של ישראל, דהיינו המלכות שנפרשה מהיסוד. חזר ונתחבר על ידי פנחס, וע\"כ הואיל והוא תקן הדבר במקומו מכאן ולהלאה, והיתה לו וגו'."],[9,"אמר ר' שמעון וכו':","אר\"ש אין לך דבר בעולם שהקב\"ה מקנא אותו כמו עון הברית, כמו שאתה אומר, חרב נוקמת נקם ברית, ובוא וראה, לא נשלם עון דור המבול, אלא משום שחטאו בהשחתת דרכיהם על הארץ. ואע\"פ, שהיו חומסים זה את זה, כמו שכתוב, ותמלא הארץ חמס. וכתיב כי מלאה וגו', מכל מקום כתוב, ותשחת הארץ וגו', והנני משחיתם, אשר יורה מדה כנגד מדה, הנני משחיתם בשביל החטא של השחתת זרע. הרי שלא נחתם גזר דינם אלא על פגם הברית."]],[[0,"","וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ. אָמַר רַבִּי אֶלְעָזָר, מִכָּאן קִיּוּם הַבְּרִית לְמַעְלָה כְּקִיּוּם הַבְּרִית לְמַטָּה, מַשְׁמָע שֶׁכָּתוּב אִתָּךְ. וְאָמַר רַבִּי אֶלְעָזָר, מִכָּאן לָמַדְנוּ, שֶׁכְּשֶׁהַצַּדִּיקִים בָּעוֹלָם, מִתְקַיֵּם הָעוֹלָם לְמַעְלָה וּלְמַטָּה. אָמַר רַבִּי שִׁמְעוֹן, דָּבָר נִסְתָּר הוּא, כְּשֶׁהִתְעוֹרְרוּת הַזָּכָר לַנְּקֵבָה כְּשֶׁהוּא מְקַנֵּא לָהּ"],[1,"","בֹּא רְאֵה סוֹד הַדָּבָר, כְּשֶׁצַּדִּיק יֵשׁ בָּעוֹלָם, מִיָּד הַשְּׁכִינָה לֹא זָזָה מִמֶּנּוּ וְהִשְׁתּוֹקְקוּתָהּ בּוֹ. וְאָז הִשְׁתּוֹקְקוּת שֶׁלְּמַעְלָה אֵלֶיהָ בְּאַהֲבָה כְּהִשְׁתּוֹקְקוּת הַזָּכָר לִנְקֵבָתוֹ כְּשֶׁהוּא מְקַנֵּא לָהּ. וְעַל זֶה, וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ. הַהִשְׁתּוֹקְקוּת מִתְעוֹרֶרֶת בִּגְלָלְךְ. כְּמוֹ זֶה (בראשית יז) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק."],[2,"","וַהֲקִמֹתִי אֶת בְּרִיךְ אִתָּךְ, לִהְיוֹת אוֹת בְּרִיתִי בָּעוֹלָם, וְאַחַר כָּךְ וּבָאתָ אֶל הַתֵּבָה. שֶׁאִלְמָלֵא אֵינוֹ צַדִּיק (ברית), לֹא יִכָּנֵס לַתֵּבָה. שֶׁהֲרֵי לֹא מִתְחַבֵּר לַתֵּבָה, רַק צַדִּיק. וְלָכֵן וּבָאתָ אֶל הַתֵּבָה, וַהֲרֵי זֶה נִתְבָּאֵר."],[3,"","אָמַר רַבִּי אֶלְעָזָר, בְּכָל זְמַן שֶׁבְּנֵי אָדָם יֶאֶחְזוּ בִּבְרִית זוֹ וְלֹא יַעַזְבוּ אוֹתָהּ, אֵין עַם וְלָשׁוֹן בָּעוֹלָם שֶׁיּוּכְלוּ לְהָרַע לָהֶם. וְנֹחַ הֶחֱזִיק בִּבְרִית זוֹ וְשָׁמַר אוֹתָהּ, וְלָכֵן שָׁמַר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (וכל אשר לו). וְכָל בְּנֵי דוֹרוֹ לֹא שָׁמְרוּ אוֹתָהּ, וְלָכֵן הֶעֱבִיר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהָעוֹלָם. וַהֲרֵי נֶאֱמַר, בְּאוֹתוֹ חֵטְא מַמָּשׁ שֶׁהֵם חָטְאוּ - בְּאוֹתוֹ גָוֶן נִמְחוּ מֵהָעוֹלָם."],[4,"","רַבִּי יְהוּדָה הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן, וְהָיוּ עוֹסְקִים בַּפָּסוּק הַזֶּה שֶׁכָּתוּב (מלכים א יח) וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. מַה זֶּה וַיְרַפֵּא.? בֹּא רְאֵה, בִּימֵי אֵלִיָּהוּ כָּל יִשְׂרָאֵל עָזְבוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָזְבוּ אֶת בְּרִית הַמִּילָה שֶׁלָּהֶם. כְּשֶׁבָּא אֵלִיָּהוּ וּרְאֵה שֶׁעָזְבוּ בְּנֵי יִשְׂרָאֵל בְּרִית מִילָה הַזּוֹ וְהֶעֱבִירוּ מֵהֶם אֶת הַבְּרִית הַזּוֹ."],[5,"","כֵּיוָן שֶׁרָאָה כָּךְ אֵלִיָּהוּ, בָּא לְתַקֵּן דָּבָר בִּמְקוֹמוֹ. כֵּיוָן שֶׁהִקְרִיב דָּבָר לִמְקוֹמוֹ - הַכֹּל הִתְרַפֵּא. זֶהוּ שֶׁכָּתוּב וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. זוֹ בְּרִית הַמִּילָה (שבא לתקן מזבח ה' ההרוס ברית המילה) שֶׁנֶּעֶזְבָה בָּעוֹלָם. וְכָתוּב (שם) וַיִּקַּח אֵלִיָּהוּ שְׁתֵּים עֶשְׂרֵה אֲבָנִים כְּמִסְפַּר שִׁבְטֵי בְנֵי יַעֲקֹב. זֶהוּ תִקּוּן שֶׁל מִזְבַּח ה'."],[6,"","אֲשֶׁר הָיָה דְבַר ה' אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ. מָה הַטַּעַם נִזְכַּר כָּאן יִשְׂרָאֵל? אֶלָּא וַדַּאי יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ וַדַּאי לְהִתְעַלּוֹת לְמַעְלָה וּלְהָשִׁיב אֶת בְּרִית הַמִּילָה לִמְקוֹמָהּ. וְהַיְנוּ שֶׁכָּתוּב (שם יט) כִּי עָזְבוּ בְרִיתְךְ בְּנֵי יִשְׂרָאֵל, וּמִשּׁוּם כָּךְ אֶת מִזְבְּחֹתֶיךְ הָרָסוּ."],[7,"","בֹּא רְאֵה, כָּל זְמַן שֶׁיִּשְׂרָאֵל שָׁמְרוּ בְּרִית הַקָּדוֹשׁ, אָז עָשׂוּ קִיּוּם לְמַעְלָה וּלְמַטָּה. וּכְשֶׁעָזְבוּ אֶת הַבְּרִית הַזֹּאת, אָז לֹא נִמְצָא קִיּוּם לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְלָכֵן וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. וְכִי זוֹ רְפוּאָה? כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי מְקַיֵּם אֶת אוֹתוֹ מָקוֹם שֶׁהָאֱמוּנָה תְּלוּיָה בּוֹ."],[8,"","בֹּא רְאֵה, גַּם כָּךְ פִּנְחָס, בְּשָׁעה שֶׁקִּנֵּא לְמַעֲשֵׂה זִמְרִי, הִתְקִין אֶת הַבְּרִית הַזּוֹ בִּמְקוֹמָהּ, וְלָכֵן כָּתוּב (במדבר כה) הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁמִּשּׁוּם פִּנְחָס הָיָה? אֵיזוֹ קְטָטָה הָיְתָה לוֹ לְפִנְחָס בַּבְּרִית הַזּוֹ? אֶלָּא כָּאן נִקְשָׁר הַדָּבָר בִּמְקוֹמוֹ. הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי. וּמָה אֶתֵּן לוֹ? שָׁלוֹם (להתחבר כל אחד במקומו) לְהִתְחַבֵּר הַבְּרִית בִּמְקוֹמָהּ, וְעַל זֶה הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וּמַהוּ? שָׁלוֹם, שֶׁהוּא מָקוֹם לְהִתְחַבֵּר עִמּוֹ. מַה שֶּׁנִּפְרַד מִמֶּנּוּ בְּחֶטְאָם - בִּגְלָלוֹ הִתְחַבֵּר בּוֹ. וְעַל זֶה, הוֹאִיל וְהוּא הִתְקִין הַדָּבָר בִּמְקוֹמוֹ, מִכָּאן וָהָלְאָה - וְהָיְתָה לוֹ וּלְזַרְעוֹ אַחֲרָיו בְּרִית כְּהֻנַּת עוֹלָם תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו."],[9,"","אָמַר רַבִּי שִׁמְעוֹן, אֵין לְךְ דָּבָר בָּעוֹלָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַנֵּא לוֹ כְּמוֹ חֵטְא הַבְּרִית, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית. וּבא וּרְאֵה, לֹא הֻשְׁלַם חֵטְא דּוֹר הַמַּבּוּל אֶלָּא מִשּׁוּם שֶׁחָטְאוּ בְּהַשְׁחָתַת דַּרְכָּם עַל הָאָרֶץ, וְאַף עַל גַּב שֶׁהָיוּ חוֹמְסִים זֶה אֶת זֶה, כַּכָּתוּב וַתִּמָּלֵא הָאָרֶץ חָמָס (וחמס מהכל היה, ולכן), וְכָתוּב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. מִכָּל מָקוֹם וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. וְהִנְנִי מַשְׁחִיתָם - מִדָּה כְּנֶגֶד מִדָּה. הִנְנִי מַשְׁחִיתָם בְּחֵטְא הַהַשְׁחָתָה."]]],[["וְאִית דְּאָמְרֵי דְּלָא אִשְׁתְּלִים קִסְטַיְיהוּ אֶלָּא בְּחוֹבָא דְּחָמָס דְּהֲווּ מְקַפְּחִין דָּא לְדָא דְּהֲווּ בִּישִׁין לַשָּׁמַיִם וְלַבְּרִיּוֹת. תָּא חֲזֵי, כַּמָּה אִנּוּן מְמַנָּן מִלְּעֵילָא דְּאִתְפָּקְדָן עַל קָלֵי דְאִנּוּן דְּמָסְרֵי דִינָא עַל חַבְרֵיהוֹן עַל מַה דְּעָבְדֵי לוֹן. וְעַל דָּא כְּתִיב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. וּבְגִין כָּךְ כְּתִיב וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ:","וַיֹּאמֶר יְיָ לְנֹחַ בֹּא אַתָּה וְכָל בֵּיתְךָ. אָמַר רַבִּי שִׁמְעוֹן אַמַּאי בְּכֻלְהוּ (ד\"א ל\"ג אמר) אֱלֹהִים וְהָכָא יְיָ. מַאי שָׁנָא הָכָא דְּאִתְּמָר יְיָ שְׁמָא עִלָּאָה דְּרַחֲמֵי. אֶלָּא רָזָא אִיהוּ דְּאוֹלִיפְנָא. לָאו אוֹרַח אַרְעָא לְקַבְּלָא אִתְּתָא אוּשְׁפִּיזָא בַּהֲדָהּ אֶלָּא בִּרְשׁוּ דְּבַעֲלָהּ.","אוּף הָכִי (נמי נח) נֹחַ בָּעָא לְאַעָלָא בְּתֵיבוּתָא לְאִתְחַבְּרָא בַּהֲדָהּ. וְלָאו הֲוָה (ליה) יָאוֹת עַד דְּבַעֲלָהּ דְּתֵיבָה יָהַב לֵיהּ רְשׁוּ לְאַעֲלָאָה (בהדה). דִּכְתִיב בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה. וּבְגִין כָּךְ אִקְרֵי הָכָא יְיָ בַּעֲלָהּ דְּתֵיבָה. וּכְדֵין עָאל נֹחַ וְאִתְחַבַּר בַּהֲדָהּ. וְכֵן אוֹלִיפְנָא דְּלֵית לֵיהּ רְשׁוּ לְאוּשְׁפִּיזָא לְמֵיעָאל לְבֵיתָא אֶלָּא בִּרְשׁוּ בַּעֲלָהּ מָארֵיהּ דְּבֵיתָא, הֲדָא הוּא דִכְתִיב לְבָתַר וַיָּבֹא נֹחַ וְגו'.","תָּא חֲזֵי, מַה כְּתִיב כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. מִכָּאן אוֹלִיפְנָא דְּלָא יְקַבֵּל בַּר נָשׁ אוּשְׁפִּיזָא בְּבֵיתֵיהּ אִי אִיהוּ חָשִׁיד בֵּיהּ דְּאִיהוּ חַיָּיבָא. אֶלָּא אִי קָאִים בְּעֵינוֹי לְזַכָּאָה דְּלָא חָשִׁיד בְּעֵינוֹי כְּלָל. הֲדָא הוּא דִכְתִיב בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה, מַאי טַעְמָא בְּגִין כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה.","וְאוֹלִיפְנָא דְּאִי יָהִיב לֵיהּ רְשׁוּ בִּלְחוֹדוֹי וְלָא יָהִיב רְשׁוּ לְכָל אִנּוּן דְּאַתְיָין עִמֵּיהּ, לָא יֵיעוּל לוֹן לְבֵיתָא. הֲדָא הוּא דִכְתִיב בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה. לְכֹלָא יָהִיב רְשׁוּתָא לְמֵיעַל. וּמִקְרָא דָא אוֹלִיפְנָא רָזָא דְּאָרְחוֹי דְאַרְעָא. (ד\"א ל\"ג בא אתה וכל ביתך אל התבה וגו').","רַבִּי יְהוּדָה פָּתַח (תהילים כ״ד:א׳) לְדָוִד מִזְמוֹר לַיְיָ הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיוֹשְׁבֵי בָהּ. הָא תָּנִינָן לְדָוִד מִזְמוֹר דְּאָמַר שִׁירָתָא וּלְבָתַר שָׁארַת עֲלֵיהּ רוּחַ קַדִּשָׁא, מִזְמוֹר לְדָוִד דְּשָׁארַת עֲלֵיהּ רוּחַ קַדִּישָׁא וּלְבָתַר אָמַר (לה) שִׁירָתָא.","לַיְיָ הָאָרֶץ וּמְלוֹאָהּ, הַאי קְרָא עַל אַרְעָא דְיִשְׂרָאֵל אִתְּמָר דְּאִיהִי אַרְעָא קַדִּישָׁא. וּמְלוֹאָהּ דָּא שְׁכִינְתָּא כְּמָא דְאַתְּ אָמֵר, (דברי הימים ב ה׳:י״ד) כִּי מָלֵא כְבוֹד יְיָ אֶת בֵּית יְיָ. וּכְתִיב, (שמות מ׳:ל״ד) וּכְבוֹד יְיָ מָלֵא אֶת הַמִּשְׁכָּן. מַאי מָלֵא וְלָא מִילָא. אֶלָּא מָלֵא וַדַּאי דְּאִתְמַלְיָיא מִכֹּלָּא. דְּאִתְמַלְיָיא מִן שִׁמְשָׁא. סִיהֲרָא שְׁלִים בְּכָל סִטְרִין. מָלֵא מִכָּל טוּבָא דִלְעֵילָא. כְּאִסְקוֹפָא דָא דְּאִתְמַלְיָיא מִכָּל טוּבָא דְּעָלְמָא. וְעַל דָּא כְּתִיב לַיְיָ הָאָרֶץ וּמְלוֹאָהּ. תֵּבֵל וְיוֹשְׁבֵי בָהּ דָּא שְׁאָר אַרְעָאן.","דָּבָר אַחֵר לַיְיָ הָאָרֶץ וּמְלוֹאָהּ דָּא אַרְעָא קַדִּישָׁא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בָהּ. וּמְלוֹאָהּ אִלֵּין נִשְׁמַתְהוֹן דְּצַדִּיקַיָּיא (ד\"א ל\"ג דכלהון מליין לה) אִתְמַלְיָיא (ד\"א דאתמלייא) מִנַּיְיהוּ מֵחֵילָא דְּעַמּוּדָא חַד דְּעָלְמָא קָיְימָא עֲלֵיהּ.","וְאִי תֵימָא עַל חָד קָיְימָא. תָּא חֲזֵי, מַה כְּתִיב, (תהילים כ״ד:ב׳) כִּי הוּא עַל יַמִּים יְסָדָהּ. כִּי הוּא. מַאן הוּא. דָּא קוּדְשָׁא בְּרִיךְ הוּא. כְּמָא דְאַתְּ אָמֵר הוּא עָשָׂנוּ. וּכְתִיב, (איוב כ״ח:כ״ד) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט.","עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ אִלֵּין שִׁבְעָה עַמּוּדִים דְּקָיְימָא (ארעא) עֲלַיְיהוּ וּמַלְיָין לָהּ. הִיא אִתְמַלְיָיא מִנַּיְיהוּ, הֵיךְ אִתְמַלְיָיא מִנַּיְיהוּ. בְּשַׁעֲתָא דְּאַסְגִּיאוּ זַכָּאִין בְּעָלְמָא כְּדֵין אַרְעָא דָּא עַבְדַּת פֵּירִין וְאִתְמַלְיָיא מִכֹּלָּא.","וּבְשַׁעֲתָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא כְּדֵין כְּתִיב, (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחרָב וְיָבֵשׁ. אָזְלוּ מַיִם מִנִּי יָם, דָּא אַרְעָא קַדִּישָׁא דְּאֲמָרָן דְּאִשְׁתַּקְיָא מִשַּׁקְיוּ עִלָּאָה. וְנָהָר יֶחֱרָב וְיָבֵשׁ, הַהוּא עַמּוּדָא חַד דְּקָאִים עֲלָהּ לְאִתְנָהֲרָא מִנֵּיהּ. וְנָהָר יֶחֱרָב וְיָבֵשׁ כְּמָא דְאַתְּ אָמֵר (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד.","וְאָמַר רַבִּי יְהוּדָה בְּהַהוּא זִמְנָא דְּאִתְאֲבִידוּ אִנּוּן חַיָּבִין מֵעָלְמָא קוּדְשָׁא בְּרִיךְ הוּא (עציב) (נ\"א אסתכל) אִשְׁתַּדַל עַל עָלְמָא וְלָא חָמָא מַאן (דקאים) דְּאָגִין עוֹלָה. וְאִי תֵימָא הָא נֹחַ, דְּהֲוָה לֵיהּ לְאַגָּנָא עַל (דריה) גַרְמֵיהּ וּלְאֲפָקָא מִנֵּיהּ תּוֹלָדִין לְעָלְמָא. הֲדָא הוּא דִכְתִיב כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. בַּדּוֹר הַזֶּה דַּיְיקָא."],[[0,"ואית דאמרי וכו':","ויש אומרים, שלא נשלמה סאתם אלא בעון החמס, שהיו חומסים זה את זה, מטעם שבזה היו רעים לשמים ולבריות, בוא וראה, כמה ממונים הם למעלה, שנתמנו על הקולות של מוסרי דין על חבריהם לשמים, על מה שנעשו להם, ועל עון זה כתוב כי מלאה הארץ חמס מפניהם, דהיינו שכל אחד ואחד מסר דין לשמים על חבירו. ומשום זה כתוב עליהם והנני משחיתם את הארץ."],[1,"ויאמר ה' לנח בא אתה וכל ביתך:","אמר ר\"ש למה בכל הכתובים נאמר כאן אלקים, ובמקרא זה כתוב השם הוי\"ה, ומה נשתנה כאן שנאמר הויה שהוא שם העליון של רחמים. אלא הוא סוד שלמדנו, שאינו דרך ארץ, שהאשה תזמין לה אורח, אלא רק ברשות בעלה."],[2,"אוף הכי וכו':","אף כן, בקש נח לכנוס בהתיבה, שה\"ס המלכות, להתחבר עמה, ולא היה נאה לו, עד שבעלה של התיבה יתן לו רשות לכנוס, שכתוב, בא אתה וכל ביתך אל התיבה, ומשום זה כתוב בהמקרא כאן הוי\"ה, שהוא בעלה של התיבה. כי הוי\"ה הוא ז\"א והתיבה היא מלכות. ואז נכנס נח ונתחבר בהתיבה. וכן למדנו, שאין רשות להאורח לכנוס אל הבית, אלא ברשות בעלה, בעל הבית, וז\"ש אח\"כ ויבא נח וגו'."],[3,"ת\"ח מה כתוב וכו':","בוא וראה מה כתוב, כי אותך ראיתי צדיק וכו', מכאן למדנו, שלא יקבל אדם אורח לביתו אם הוא חושד בו שהוא רשע, אלא אם כן שהוא נחשב בעיניו לצדיק ואינו חושד בעיניו כלל, וז\"ש בא אתה וכל ביתך אל התיבה, מה הטעם, משום כי אותך ראיתי צדיק לפני בדור הזה."],[4,"ואוליפנא וכו'","ולמדנו, שאם נותן לו להאורח בלבדו רשות, ולא נתן רשות לכל הבאים עם האורח, אל יכניסם להבית. ז\"ש, בא אתה וכל ביתך אל התיבה, אשר לכולם נתן רשות לכנוס. ומקרא הזה למדנו - סוד סדרי דרך ארץ."],[5,"רבי יהודה פתח וכו':","ר\"י פתח, לדוד מזמור לה' הארץ ומלואה וגו'. הנה למדנו, כל מקום שכתוב, לדוד מזמור, יורה שאמר שירה ואח\"כ שרה עליו רוח הקודש ואם כתוב, מזמור לדוד, יורה, ששרה עליו תחלה רוח הקודש, ואח\"כ אמר השירה."],[6,"לה' הארץ ומלואה וכו'","מקרא זה, על ארץ ישראל נאמר, שהיא ארץ הקודש. \u0003ומלואה\u0004 זה השכינה. כש\"א, כי מלא כבוד ה' את בית ה'. וכתוב כי כבוד ה' מלא את המשכן, אשר מלא זה נאמר על השכינה, אף כאן ומלואה נאמר על השכינה. מהו שנאמר מלא ולא, נאמר מילא, דהיינו שלא נאמר, מילא את המשכן. אלא היא מלא ודאי, שנתמלא מכל, שנתמלא מן השמש. הלבנה, שהיא השכינה. שלימה מכל הצדיקים, מלא מכל טוב שלמעלה כאוצר הזה שנתמלא מכל טוב העולם. ועל זה כתוב, לה' הארץ ומלואה. והכתוב, תבל ויושבי בה, זה נאמר על שאר ארצות מחוץ לארץ ישראל."],[7,"ד\"א לה' הארץ וכו':","פירוש אחר בהכ', לה' הארץ ומלואה, שהיא ארץ הקדושה העליונה. שהקב\"ה חפץ בה. דהיינו הנוקבא, \u0003ומלואה,\u0004 זה נשמות הצדיקים, שהנוקנא מתמלאה מהם, מכח עמוד אחד, שהיא יסוד דז\"א, שהעולם עומד עליו. כלומר, כל מה שיש בהעולם, שהיא הנוקבא, מקובל מן יסוד דז\"א: ולפיכך נבחן שהעולם עומד עליו."],[8,"ואי תימא על חד וכו'","ואם תאמר על עמוד אחד עומד, בוא וראה מה שכתוב, כי הוא על ימים יסדה, כי \u0003הוא,\u0004 סובב על הקב\"ה, כמו שאתה אומר \u0003הוא\u0004 עשנו. וכן כתוב כי \u0003הוא\u0004 לקצות הארץ יביט."],[9,"על ימים יסדה ועל נהרות יכוננה:","אלו הם ז' עמודים שהנוקבא עומדת עליהם והם ממלאים אותה, והיא מתמלאת מהם. שהם ז' ספירות חג\"ת נהי\"מ דז\"א. ושואל איך היא מתמלאת מהם. ואומר, בשעה שצדיקים מתרבים בעולם, אז ארץ הזו, דהיינו הנוקבא, עושית פירות, ומתמלאת מכל."],[10,"ובשעתא דאסגיאו חייבין וכו':","ובשעה שהרשעים מתרבים בעולם, אז כתוב, אזלו מים מני ים ונהר יחרב ויבש."],[10,"אזלו מים מני ים.","זו ארץ הקדושה שאמרנו, דהיינו הנוקבא, ששולתה משיקוי העליון, ועתה אזלו מים ואינם. \u0003ונהר יחרב ויבש,\u0004 הוא אותו העמוד, שהיא עומדת עליו, דהיינו היסוד, שעתה נחרב ונתיבש. כמו שאת אומר, \u0003הצדיק אבד\u0004 שהוא היסוד הנקרא צדיק."],[11,"ואמר רבי יהודה וכו':","ואר\"י באותה שעה שהרשעים נאבדים מהעולם, הקב\"ה מסתכל בהעולם, ואינו רואה מי שיגין עליהם. ואם תאמר, הנה נח שהיה לו להגין על דורו בזמן המבול, ולהוציא תולדות אל העולם, למה לא הגין עליהם. ע\"כ כתוב, כי אותך ראיתי צדיק לפני בדור הזה. \u0003בדור הזה\u0004 הוא בדיוק, ללמד שבדור אחר לא היה צדיק, וע\"כ לא הספיק זכותו להגין על דור המבול."]],[[0,"","וְיִשִׁ אוֹמְרִים שֶׁלֹּא הִתְמַלְּאָה סְאָתָם אֶלָּא בְּחֵטְא הֶחָמָס שֶׁהָיוּ חוֹמְסִים זֶה אֶת זֶה, שֶׁהָיוּ רָעִים לַשָּׁמַיִם וְלַבְּרִיּוֹת בֹּא רְאֵה כַּמָּה מְמֻנִּים מִלְמַעְלָה שֶׁמֻּפְקָדִים עַל קוֹלוֹת אֵלּוּ שֶׁמּוֹסְרִים הַדִּין עַל חַבְרֵיהֶם עַל מַה שֶּׁעָשׂוּ לָהֶם, וְעַל זֶה כָּתוּב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. וְלָכֵן כָּתוּב וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ."],[1,"","וַיֹּאמֶר ה' לְנֹחַ בֹּא אַתָּה וְכָל בֵּיתְךְ. אָמַר רַבִּי שִׁמְעוֹן, לָמָּה בְּכֻלָּם (אמר) אֱלֹהִים וְכָאן יְיָ? מַה שּׁוֹנֶה כָּאן שֶׁנֶּאֱמַר ה', הַשֵּׁם הָעֶלְיוֹן שֶׁל הָרַחֲמִים? אֶלָּא סוֹד הוּא שֶׁלָּמַדְנוּ - אֵין דֶּרֶךְ אֶרֶץ שֶׁתְּקַבֵּל אִשָּׁה אוֹרֵחַ עִמָּהּ אֶלָּא בִּרְשׁוּת בַּעְלָהּ."],[2,"","אַף כָּךְ (גם נח,) נֹחַ רָצָה לְהִכָּנֵס לַתֵּבָה לְהִתְחַבֵּר עִמָּהּ, וְלֹא הָיָה (לו) רָאוּי עַד שֶׁבַּעַל הַתֵּבָה יִתֵּן לוֹ רְשׁוּת לְהִכָּנֵס (עמה), שֶׁכָּתוּב בֹּא אַתָּה וְכֹל בֵּיתְךְ אֶל הַתֵּבָה. וְלָכֵן נִקְרָא כָּאן ה', הַבַּעַל שֶׁל הַתֵּבָה, וְאָז נִכְנַס נֹחַ וְהִתְחַבֵּר עִמָּהּ. וְכֵן לָמַדְנוּ שֶׁאֵין רְשׁוּת לְאוֹרֵחַ לְהִכָּנֵס לְבַיִת אֶלָּא בִּרְשׁוּת בַּעְלָהּ, בַּעַל הַבַּיִת. זֶהוּ שֶׁכָּתוּב אַחַר כָּךְ וַיָּבֹא נֹחַ וְגוֹ'"],[3,"","בֹּא רְאֵה מַה כָּתוּב, כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. מִכָּאן לָמַדְנוּ שֶׁלֹּא יְקַבֵּל אָדָם אוֹרֵחַ בְּבֵיתוֹ אִם הוּא חוֹשֵׁד בּוֹ שֶׁהוּא רָשָׁע, אֶלָּא אִם עוֹמֵד בְּעֵינָיו לְצַדִּיק שֶׁלֹּא חָשׁוּד בְּעֵינָיו כְּלָל. זֶהוּ שֶׁכָּתוּב בּא אַתָּה וְכֹל בֵּיתְךְ אֶל הַתֵּבָה. מָה הַטַּעַם? מִשּׁוּם כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה."],[4,"","וְלָמַדְנוּ, שֶׁאִם נָתַן לוֹ רְשׁוּת לְבַדּוֹ וְלֹא נָתַן רְשׁוּת לְכָל אוֹתָם שֶׁבָּאִים עִמּוֹ, לֹא יַכְנִיס אוֹתָם לַבַּיִת. זֶהוּ שֶׁכָּתוּב בֹּא אַתָּה וְכָל בֵּיתְךְ אֶל הַתֵּבָה. לְכֻלָּם נָתַן רְשׁוּת לְהִכָּנֵס. וּמִפָּסוּק הַזֶּה לָמַדְנוּ סוֹד דֶּרֶךְ אֶרֶץ. (ד\"א בא אתה וכל ביתך אל התבה וגו')."],[5,"","רַבִּי יְהוּדָה פָּתַח, (תהלים כד) לְדָוִד מִזְמוֹר לַה' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיֹשְׁבֵי בָהּ. הֲרֵי שָׁנִינוּ, לְדָוִד מִזְמוֹר - שֶׁאָמַר שִׁירָה וְאַחַר כָּךְ שָׁרְתָה עָלָיו רוּחַ הַקֹּדֶשׁ. מִזְמוֹר לְדָוִד - שֶׁשָּׁרְתָה עָלָיו רוּחַ הַקֹּדֶשׁ וְאַחַר כָּךְ אָמַר שִׁירָה."],[6,"","לַה' הָאָרֶץ וּמְלוֹאָהּ - פָּסוּק זֶה נֶאֱמַר עַל אֶרֶץ יִשְׂרָאֵל שֶׁהִיא אֶרֶץ הַקְּדוֹשָׁה. וּמְלוֹאָהּ זוֹ הַשְּׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים ב ה) כִּי מָלֵא כְבוֹד ה' אֶת בֵּית ה', וְכָתוּב (שמות מ) וּכְבוֹד ה' מָלֵא אֶת הַמִּשְׁכָּן. לָמָּה מָלֵא וְלֹא מִלֵּא? אֶלָּא מָלֵא וַדַּאי, שֶׁהִתְמַלֵּא מֵהַכֹּל, שֶׁהִתְמַלֵּא מֵהַשֶּׁמֶשׁ. הַלְּבָנָה שְׁלֵמָה בְּכָל הַצְּדָדִים. מָלֵא מִכָּל טוּב שֶׁלְּמַעְלָה, כְּמוֹ הָאוֹצָר הַזֶּה שֶׁהִתְמַלֵּא מִכָּל טוּב שֶׁל הָעוֹלָם, וְעַל זֶה כָּתוּב לַה' הָאָרֶץ וּמְלוֹאָהּ. תֵּבֵל וְיֹשְׁבֵי בָהּ - אֵלּוּ שְׁאָר הָאֲרָצוֹת."],[7,"","דָּבָר אַחֵר, לַה' הָאָרֶץ וּמְלוֹאָהּ - זוֹ אֶרֶץ הַקְּדוֹשָׁה הָעֶלְיוֹנָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּהּ. וּמְלוֹאָהּ - אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים (ד\"א שכלם ממלאים אותה) מִתְמַלֵּאת (ד\"א שמתמלאת) מֵהֶם מִכֹּחַ עַמּוּד אֶחָד שֶׁהָעוֹלָם עוֹמֵד עָלָיו."],[8,"","וְאִם תֹּאמַר עַל אֶחָד עוֹמֵד. בֹּא רְאֵה מַה כָּתוּב, (תהלים כד) כִּי הוּא עַל יַמִּים יְסָדָהּ. כִּי הוּא, מִי הוּא זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר הוּא עָשָׂנוּ, וְכָתוּב (איוב כח) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט."],[9,"","עֵל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ - אֵלּוּ שִׁבְעָה עַמּוּדִים שֶׁעוֹמֶדֶת הָאָרֶץ עֲלֵיהֶם וּמְמַלְּאִים אוֹתָהּ, וְהִיא מִתְמַלֵּאת מֵהֶם. אֵיךְ מִתְמַלֵּאת מֵהֶם? בְּשָׁעָה שֶׁמִּתְרַבִּים הַצַּדִּיקִים בָּעוֹלָם, אָז הָאָרֶץ הַזּוֹ עוֹשָׂה פֵּרוֹת וּמִתְמַלֵּאת מֵהַכֹּל."],[10,"","וּבְשָׁעָה שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, אָז כָּתוּב (שם יד) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחֱרַב וְיָבֵשׁ. אָזְלוּ מַיִם מִנִּי יָם - זוֹ הָאָרֶץ הַקְּדוֹשָׁה שֶׁאָמַרְנוּ שֶׁנִּשְׁקֵית מֵהַשְׁקָאָה עֶלְיוֹנָה. וְנָהָר יֶחֱרַב וְיָבֵשׁ - אוֹתוֹ הָעַמּוּד הָאֶחָד שֶׁעוֹמֵד עָלֶיהָ לִהְיוֹת מוּאָר מִמֶּנּוּ. וְנָהָר יֶחֱרַב וְיָבֵשׁ - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נז) הַצַּדִּיק אָבָד."],[11,"","וְאָמַר רַבִּי יְהוּדָה, בְּאוֹתוֹ זְמַן שֶׁנֶּאֱבָדִים אוֹתָם רְשָׁעִים מֵהָעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא (עצוב) (מסתכל) מִשְׁתַּדֵּל עַל הָעוֹלָם וְלֹא רוֹאֶה מִי שֶׁמֵּגֵן (שעומד) עָלָיו. וְאִם תֹּאמַר הֲרֵי נֹחַ, שֶׁהָיָה לוֹ לְהָגֵן עַל (דורו) עַצְמוֹ וּלְהוֹצִיא מִמֶּנּוּ תוֹלָדוֹת לָעוֹלָם - זֶהוּ שֶׁכָּתוּב כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. דַּוְקָא בַּדּוֹר הַזֶּה."]]],[["רַבִּי יוֹסֵי אָמַר בַּדּוֹר הַזֶּה דָּא שְׁבָחָא דִּילֵיהּ דְּהֲוָה בְּהַהוּא דָרָא חַיָּיבָא וְאִשְׁתְּכַח כּוּלֵי הַאי אִישׁ צַדִּיק תָּמִים (ודאי ולאו בדרא דיליה אלא) (ס\"א ודא די ליה) וְאֲפִילּוּ בְּדָרָא דְמשֶׁה, אֲבָל לָא הֲוָה יָכִיל לְאַגָּנָא עַל עָלְמָא. בְּגִין דְּלָא אִשְׁתַּכְּחוּ עֲשָׂרָה בְּעָלְמָא כְּמָא דְאַתְּ אָמֵר, (בראשית י״ח:כ״ט) אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה וְלָא אִשְׁתַּכְּחוּ תַּמָּן, אוּף הָכָא לָא אִשְׁתַּכְּחוּ עֲשָׂרָה. אֶלָא הוּא וּתְלַת בְּנוֹי וְנוּקְבַיְיהוּ וְלָא הֲווּ עֲשָׂרָה.","רַבִּי אֶלְעָזָר שָׁאִיל לֵיהּ לְרַבִּי שִׁמְעוֹן אֲבוֹי, הָא תָּנִינָן בְּשַׁעֲתָא דְעָלְמָא אִתְמַלְיָיא חוֹבֵי בְּנֵי נָשָׁא וְדִינָא נָפַק, וַוי לְהַהוּא זַכָּאָה דְּאִשְׁתְּכַח בְּעָלְמָא דְּאִיהוּ אִתְפַּס בְּחוֹבוֹי דְחַיָיבַיָא בְּקַדְמִיתָא. נֹחַ אֵיךְ אִשְׁתְּזִיב דְּלָא אִתְפַּס בְּחוֹבַיְיהוּ. אָמַר לֵיהּ הָא אִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאֲפָקָא מִנֵּיהּ תּוֹלָדִין לְעָלְמָא מִגּוֹ תֵּיבוּתָא. וְתוּ דְּהָא דִּינָא לָא יָכְלָא לְשַׁלְטָאָה עֲלוֹי בְּגִין דְּהֲוָה טָמִיר וְגָנִיז בַּתֵּבָה וְאִתְכַּסְיָיא מֵעֵינָא.","וְתָּא חֲזֵי, כְּתִיב, (צפניה ב׳:ג׳) בַּקְשׁוּ צֶדֶק בַּקְשׁוּ עֲנָוָה אוּלַי תִּסָּתְרוּ בְּיוֹם אַף יְיָ. וְנֹחַ בִּקֵּשׁ צֶדֶק וְעָאל בְּגַוָּוהּ לְשַׁלְטָאָה וּלְקַטְרְגָא לֵיהּ.","הָכָא אִתְרְמִיז לְאִנּוּן קַדִּישֵׁי עֶלְיוֹנִין לְמִנְדַע בְּרָזָא דְּאַתְוָון קַדִּישִׁין עִלָּאִין הִפּוּכָא דְּאַתְוָון כ\"ב לְאִתְמְחֵי לְאִנּוּן חַיָּיבַיָא. וְעַל דָּא וַיִּמָּחוּ מִן הָאָרֶץ כְּתִיב. בֹּא אַתָּה וְכָל בֵּיתְךָ.","רַבִּי יִצְחָק פָּתַח (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין משֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם. (נ\"א זרוע תפארתו) דָּא זְכוּתָא דְאַבְרָהָם דְּאִיהוּ יָמִינָא מִמּשֶׁה. תִּפְאֶרֶת דְּמשֶׁה. וּבְגִין כָּךְ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם. דְּהָא זְכוּתָא דְאַבְרָהָם בּוֹקֵעַ מַיִם אִיהוּ. וְכָל דָּא לָמָה לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם.","תָּא חֲזֵי, מַה בֵּין משֶׁה לִשְׁאָר בְּנֵי עָלְמָא. בְּשַׁעֲתָא דְאֲמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְמשֶׁה (שמות ל״ב:י׳) וְעַתָּה הַנִּיחָה לִי וְגו'. וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָדוֹל וְגו'. מִיָּד אָמַר משֶׁה וְכִי אֶשְׁבּוֹק דִּינְהוֹן דְּיִשְׂרָאֵל בְּגִינִי. הַשְׁתָּא יֵימְרוּן כָּל אִנּוּן בְּנֵי עָלְמָא דְּאֲנָא קַטְלִית לוֹן לְיִשְׂרָאֵל. כְּמָה דְּעֲבַד נֹחַ.","דְּכֵיוָן דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דִּישֵׁזִיב לֵיהּ בְּתֵיבוּתָא (כמה דאתמר) דִּכְתִיב וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם וְגו'. וּכְתִיב וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנֵי הָאֲדָמָה וַאֲנִי הִנְנִי מֵקִים אֶת בְּרִיתִי וְגו' וּבָאתָ אֶל הַתֵּבָה כֵּיוָן דְּאָמַר לֵיהּ דְּיִשְׁתְּזִיב הוּא וּבְנוֹי לָא בָּעָא רַחֲמִין עַל עָלְמָא וְאִתְאֲבִידוּ. וּבְגִין כָּךְ אִקְרוּן מֵי הַמַּבּוּל עַל שְׁמֵיהּ כְּמָא דְאַתְּ אָמֵר, (ישעיהו נ״ד:ט׳) כִּי מֵי נֹחַ זֹאת לי אשׁר נשׁבָּעַתִּי מעָבוֹר מֵי נֹחַ.","אָמַר משֶׁה הַשְׁתָּא יֵימְרוּן בְּנִי עָלְמָא דְּאֲנָא קְטִילַת לוֹן בְּגִין דְּאָמַר לִי וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָדוֹל. הַשְׁתָּא טַב לִי דְּאֵימוּת וְלָא יִשְׁתֵּצוּן יִשְׂרָאֵל. מִיָּד וַיְחַל משֶׁה אֶת פְּנֵי יְיָ אֱלֹהָיו. בָּעָא רַחֲמִין עֲלַיְיהוּ וְאִתְעַר רַחֲמֵי עַל עָלְמָא.","וְאָמַר רַבִּי יִצְחָק שֵׁירוּתָא דְּבָעָא רַחֲמֵי עֲלַיְיהוּ מַאי קָאֲמַר. לָמָּה יְיָ יֶחרֶה אַפְּךָ בְּעַמֶּךָ. וְכִי מִלָּה דָא אֵיךְ אָמַר לֵיהּ משֶׁה לָמָּה. וְהָא עֲבָדוּ כּוֹכָבִים וּמַזָּלוֹת כְּמָא דְאַתְּ אָמֵר עָשׂוּ לָהֶם עֵגֶל מַסֵּכֶה וַיִּשְׁתַּחֲווּ לוֹ וַיֹּאמְרוּ אֵלֶּה וְגו'. וּמשֶׁה אָמַר לָמָּה. אֶלָּא הָכִי אוֹלִיפְנָא מַאן דִּמְרַצֶּה לְאָחֳרָא לָא בָּעֵי לְמֶעְבַּד הַהוּא חוֹבָא (דאיהו) רַב, אֶלָּא יַזְעִיר לֵיהּ קַמֵּיהּ. וּלְבָתַר יַסְגֵּי לֵיהּ קַמֵּיהּ אָחֳרָא (ד\"א ל\"ג חייבא) דִּכְתִיב אַתֶּם חֲטָאתֶם חֲטָאָה גְדֹלָה.","וְלָא שָׁבִיק לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַד דְּמָסַר גַּרְמֵיהּ לְמוֹתָא דִּכְתִיב וְעַתָּה אִם תִּשָּׂא חֲטָאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ. וְקוּדְשָׁא בְּרִיךְ הוּא מָחִיל לוֹן דִּכְתִיב וַיִּנָּחֶם יְיָ עַל הָרָעָה וְגו'. וְנֹחַ לָא עֲבַד כֵּן אֶלָּא בָּעָא לְאִשְׁתְּזָבָא וְשָׁבִיק כָּל עָלְמָא.","וּבְכָל זִמְנָא דְדִינָא שַׁרְיָא עַל עָלְמָא, רוּחַ קוּדְשָׁא אָמַר וַוי דְּלָא אִשְׁתְּכַח כְּמשֶׁה דִּכְתִיב (ישעיהו ס״ג:י״א) וַיִּזְכּוֹר (ימי עולם משה עמו) (וגו) אַיֵּה הַמַּעֲלֵם מִיָּם וְגו'. דִּכְתִיב (שמות י״ד:ט״ו) וַיֹּאמֶר יְיָ אֶל משֶׁה מַה תִּצְעַק אֵלָי. דְּהָא אִיהוּ בִּצְלוֹתָא סָלִיק לוֹן מִן יַמָּא. וּבְגִין דְּשַׁוֵּי גַּרְמֵיהּ בִּצְלוֹתָא עֲלַיְיהוּ דְיִשְׂרָאֵל בְּיַמָּא. אִיקְרֵי (על שמיה) הַמַּעֲלֵם מִיָּם. דְּאִיהוּ אַסִּיק לוֹן מִן יַמָּא."],[[0,"ר' יוסי אמר וכו':","רי\"א \u0003בדור הזה,\u0004 זהו לשבחו, שהיה בדור החייב ההוא, ונמצא בכל זה איש צדיק תמים. ודאי לאו דוקא בדורו, אלא אפילו בדור של משה היה צדיק. אבל לא היה יכול להגין על העולם, משום שלא נמצאו עשרה צדיקים בהעולם כמש\"א במהפכת סדום, אולי ימצאון שם עשרה, ולא נמצאו שם, ע\"כ נחרבו, אף כאן לא נמצאו עשרה, אלא נח ושלשה בניו ונקבותיהם שלא היו עשרה, וע\"כ לא יכלו להגן על הדור."],[1,"ר' אלעזר שאיל וכו':","ר\"א שאל לו לר\"ש אביו, הנה למדנו, בשעה שהעולם מתמלא מעונות בני אדם, והדין יוצא, ווי לאותו צדיק הנמצא בהעולם, שהוא נענש תחילה בעונותיהם של הרשעים. כלפי זה הקשה, איך נצל נח מן המבול ולא נענש בעונות הדור. \u0003א\"ל, הא אתמר וכו':\u0004 והשיב לו ר\"ש, הנה אמרו שהקב\"ה רצה להוציא ממנו תולדות לעולם, וע\"כ נצל. ועוד, כי הדין לא היה יכול לשלוט עליו, משום שהיה מכוסה ונחבא בהתיבה ונעלם מהעין."],[2,"ות\"ח כתיב וכו':","ובוא וראה, כתוב, בקשו צדק בקשו ענוה אולי תסתרו ביום אף ה'. ונח בקש צדק, ונכנס בתוך התיבה, ונסתתר ביום אף ה'. ועל כן לא היה יכול הדין לשלוט עליו ולקטרג עליו."],[3,"הכא אתרמיז וכו':","כאן נרמז לקדושים העליונים להשכיל ולדעת בסוד אותיות הקדושות העליונות, אשר היפוך סדרם של כ\"ב אותיות, הוא למחות לאותם הרשעים, וע\"כ כתוב, וימחו מן הארץ, וכתוב בא אתה וכל ביתך אל התיבה."],[3,"","פירוש. כי יש בכ\"ב אותיות ב' סדרים, א) סדר ישר, א\"ב ג\"ד ה\"ו וכו', שיורה על רחמים. ב) סדר הפוך, תשר\"ק צפע\"ס וכו', שיורה על דין. והנה \u0003בית ותיבה\u0004 הם אותיות שוות (היינו לפי נוסח הזהר ש \u0003תיבה\u0004 היא מלאה עם י'.) אלא \u0003בית,\u0004 הוא בסדר ישר: ב' י' ת'. ו \u0003תיב\u0004 ה, הוא בסדר הפוך: ת' י' ב' המורה על דין ו \u0003ה'\u0004 הסופית היא נחה, ואינה נדרשת. ונאמר בא אתה וכל \u0003ביתך\u0004 אל ה \u0003תיב\u0004 ה, שניתן להשכיל בזה אשר מדת הרחמים הרמוזה בה \u0003בית\u0004 תכנס ותסתתר במדת הדין הרמוז בה \u0003תיבה,\u0004 באופן שכל מה שאין ה \u0003תיב\u0004 ה קולטתו נמחה מן הארץ, וז\"ש \u0003ועל דא וימחו מן הארץ, וכתיב\u0004 (ה\"ג בדפוסים ראשונים) \u0003בא אתה וכל ביתך אל התיבה.\u0004 כי על כן נמחו מהארץ, משום שמדת הרחמים הרמוזה ב \u0003בית\u0004 ך נצטמצם ובא בתוך מדת הדין הרמוזה בה \u0003תיב\u0004 ה, וכל שאינו נקלט בהתיבה נמחה מהארץ."],[4,"רבי יצחק פתח וכו':","ר\"י פתח, מוליך לימין משה זרוע תפארתו וגו'. \u0003זרוע תפארתו,\u0004 זהו זכותו של אברהם שה\"ס חסד, שהוא לימין ממשה, תפארת של משה. כלומר, משה ה\"ס תפארת, וחסד הוא לימינו של משה שהוא ת\"ת. ושיעור הכתוב \u0003וזרוע,\u0004 הוא זרוע ימין, של \u0003תפארתו\u0004 דמשה, ומשום זה, \u0003בוקע מים מפניהם,\u0004 כי זכותו של אברהם, שהוא חסד, הוא בוקע מים. וכל זה למה, כדי \u0003לעשות לו שם עולם.\u0004"],[5,"ת\"ח מה בין משה וכו':","בוא וראה מה בין משה לשאר בני העולם. בשעה שאמר לו הקב\"ה למשה, ועתה הניחה לי וגו' ואעשה אותך לגוי גדול וגו' מיד אמר משה, וכי בשביל טובתי אעזוב דינם של ישראל ולא אבקש רחמים עליהם. עתה יאמרו כל בני העולם, שאני הרגתי לישראל, כמו שעשה נח."],[6,"דכיון וכו':","מכיון שאמר לו הקב\"ה שיציל אותו בהתיבה, שכתוב, ואני הנני מביא וגו', וכתוב, ומחיתי וגו', ובאת אל התיבה, כיון שאמר לו שינצלו הוא ובניו לא ביקש רחמים על העולם, ונאבדו. ומשום זה נקראים מי המבול על שמו, כמש\"א כי מי נח זאת לי וגו'."],[7,"אמר משה וכו':","אמר משה עתה יאמרו בני העולם שאני הרגתי אותם. משום שאמר לי ואעשה אותך לגוי גדול, עתה טוב לי שאמות ולא יכלו ישראל. מיד, ויחל משה וגו' ביקש רחמים עליהם ונתעוררו רחמים על העולם."],[8,"ואמר ר' יצחק וכו':","בהתחלה, שביקש רחמים עליהם, מה אמר. \u0003למה ה' יחרה אפך בעמך.\u0004 ושואל וכי, מלה זו, \u0003למה,\u0004 איך אמר אותה משה, והרי עבדו עבודה זרה כמש\"א, עשו להם עגל מסכה, וישתחוו לו ויאמרו אלה וגו' ומשה אמר \u0003למה.\u0004 ומשיב, אלא הכי למדנו, מי שמרצה לחברו, בעד אדם שחטא לו, אינו צריך לעשות אותו החטא גדול, אלא שימעט החטא לפניו. ואח\"כ יגדיל החטא לפני האחר, החוטא, ולפיכך אמר משה לפני הקב\"ה \u0003למה\u0004 יחרה אפך, כי מיעט את החטא. ואח\"כ פנה לישראל והגדיל החטא, שכתוב אתם חטאתם חטאה גדולה."],[9,"ולא שביק וכו':","ולא הניח להקב\"ה, עד שמסר עצמו למיתה, על ישראל, שכתוב, ועתה אם תשא חטאתם וגו'. והקב\"ה מחל להם, שכתוב, וינחם ה' על הרעה וגו'. ונח לא עשה כן. אלא בקש להנצל, ועזב כל העולם."],[10,"ובכל זמנא וכו':","ובכל שעה שהדין שורה בהעולם, אומר רוח הקודש, ווי שלא נמצא עוד כמשה, שכתוב, ויזכור וגו', איה המעלם מים וגו', שכתוב, ויאמר ה' אל משה מה תצעק אלי, כי הוא העלה אותם מן הים, בתפלה, ומשום ששם את עצמו בתפלה על ישראל, בהים, נקרא על שמו, \u0003המעלם מים,\u0004 שהוא העלה אותם מן הים."]],[[0,"","רַבִּי יוֹסֵי אָמַר, בַּדּוֹר הַזֶּה זֶה שֶׁבַח שֶׁלּוֹ, שֶׁהָיָה בְּאוֹתוֹ דוֹר רָשָׁע, וְנִמְצָא כָּל כָּךְ אִישׁ צַדִּיק תָּמִים (ודאי ולא בדורו, אלא) (ס\"א וזה שלו) וַאֲפִלּוּ בְּדוֹרוֹ שֶׁל מֹשֶׁה, אֲבָל לֹא הָיָה יָכוֹל לְהָגֵן עַל הָעוֹלָם, מִשּׁוּם שֶׁלֹּא נִמְצְאוּ עֲשָׂרָה בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יח) אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה, וְלֹא נִמְצְאוּ שָׁם. גַּם כָּאן לֹא נִמְצְאוּ עֲשָׂרָה, אֶלָּא הוּא וּשְׁלֹשֶׁת בָּנָיו וּנְקֵבוֹתֵיהֶם, וְלֹא הָיוּ עֲשָׂרָה."],[1,"","רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו, הֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁהָעוֹלָם מִתְמַלֵּא בַּחֲטָאֵי בְּנֵי אָדָם וְהַדִּין יוֹצֵא - אוֹי לְאוֹתוֹ צַדִּיק שֶׁנִּמְצָא בָּעוֹלָם, שֶׁהוּא נִתְפָּס בַּחֲטָאֵי הָרְשָׁעִים בַּתְּחִלָּה. אֵיךְ נִצַּל נֹחַ שֶׁלֹּא נִתְפַּס בַּחֲטָאֵיהֶם? אָמַר לוֹ, הֲרֵי נֶאֱמַר שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מִמֶּנּוּ תּוֹלָדוֹת לָעוֹלָם מִתּוֹךְ הַתֵּבָה. וְעוֹד, שֶׁהֲרֵי הַדִּין לֹא יָכֹל לִשְׁלֹט עָלָיו, מִשּׁוּם שֶׁהָיָה טָמִיר וְנִסְתָּר בַּתֵּבָה וְהִתְכַּסָּה מֵהָעַיִן."],[2,"","וּבֹא וּרְאֵה, כָּתוּב (צפניה ב) בַּקְּשׁוּ צֶדֶק בַּקְּשׁוּ עֲנָוָה אוּלַי תִּסָּתְרוּ בְּיוֹם אַף ה'. וְנֹחַ בִּקֵּשׁ צֶדֶק, וְנִכְנַס לְתוֹךְ הַתֵּבָה וְנִסְתַּר בְּיוֹם אַף ה', וְעַל זֶה הַדִּין לֹא יָכֹל לִשְׁלֹט וּלְקַטְרֵג עָלָיו."],[3,"","כָּאן נִרְמָז לְאוֹתָם קְדוֹשִׁים עֶלְיוֹנִים לָדַעַת בְּסוֹד הָאוֹתִיּוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת הַהִפּוּךְ שֶׁל הָאוֹתִיּוֹת כ\"ב לְהַכּוֹת אֶת אוֹתָם הָרְשָׁעִים, וְעַל זֶה וַיִּמָּחוּ מִן הָאָרֶץ כָּתוּב. בּא אַתָּה וְכֹל בֵּיתְךְ."],[4,"","רַבִּי יִצְחָק פָּתַח, (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם (זרוע תפארתו) - זוֹ זְכוּת שֶׁל אַבְרָהָם, שֶׁהוּא הַיָּמִין מִמֹּשֶׁה, תִּפְאֶרֶת שֶׁל מֹשֶׁה, וּמִשּׁוּם כָּךְ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם, שֶׁהֲרֵי הַזְּכוּת שֶׁל אַבְרָהָם הִיא בּוֹקַעַת מַיִם. וְכָל זֶה לָמָּה? לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם"],[5,"","בֹּא רְאֵה מַה בֵּין מֹשֶׁה לִשְׁאָר בְּנֵי הָעוֹלָם. בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה (שמות לב) וְעַתָּה הַנִּיחָה לִּי וְגוֹ', וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל וְגוֹ' - מִיָּד אָמַר מֹשֶׁה, וְכִי אֶעֱזֹב דִּינָם שֶׁל יִשְׂרָאֵל בִּשְׁבִילִי? כָּעֵת יֹאמְרוּ כָּל אוֹתָם בְּנֵי הָעוֹלָם שֶׁאֲנִי הָרַגְתִּי אֶת יִשְׂרָאֵל כְּמוֹ שֶׁעָשָׂה נֹחַ."],[6,"","שֶׁכֵּיוָן שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּצִּיל אוֹתוֹ בַּתֵּבָה, (כמו שנאמר) שֶׁכָּתוּב וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם וְגוֹ', וְכָתוּב וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנֵי הָאֲדָמָה וַאֲנִי הִנְנִי מֵקִים אֶת בְּרִיתִי וְגוֹ' וּבָאתָ אֶל הַתֵּבָה - כֵּיוָן שֶׁאָמַר לוֹ שֶׁיִּנָּצֵל הוּא וּבָנָיו, לֹא בִקֵּשׁ רַחֲמִים עַל הָעוֹלָם וְנֶאֶבְדוּ. וּמִשּׁוּם כָּךְ נִקְרָאִים מֵי הַמַּבּוּל עַל שְׁמוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נד) כִּי מֵי נֹחַ זֹאת לִי אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ."],[7,"","אָמַר מֹשֶׁה, כָּעֵת יֹאמְרוּ בְּנֵי הָעוֹלָם שֶׁאֲנִי הָרַגְתִּי אוֹתָם מִשּׁוּם שֶׁאָמַר לִי וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל. כָּעֵת טוֹב לִי שֶׁאָמוּת וְלֹא יֻשְׁמְדוּ יִשְׂרָאֵל. מִיָּד - וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו. בִּקֵּשׁ רַחֲמִים עֲלֵיהֶם וְעוֹרֵר רַחֲמִים עַל הָעוֹלָם."],[8,"","וְאָמַר רַבִּי יִצְחָק, בַּתְּחִלָּה כְּשֶׁבִּקֵּשׁ רַחֲמִים עֲלֵיהֶם מָה אָמַר? לָמָה ה' יֶחֱרֶה אַפְּךְ בְּעַמֶּךְ. וְכִי הַדָּבָר הַזֶּה אֵיךְ אָמַר אוֹתוֹ מֹשֶׁה לָמָּה, וַהֲרֵי עָבְדוּ כּוֹכָבִים וּמַזָּלוֹת, כְּמוֹ שֶׁנֶּאֱמַר עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ וַיֹּאמְרוּ אֵלֶּה וְגוֹ', וּמֹשֶׁה אָמַר לָמָּה? אֶלָּא כָּךְ לָמַדְנוּ, מִי שֶׁמְּרַצֶּה אֶת הָאַחֵר, לֹא צָרִיךְ לַעֲשׂוֹת אֶת אוֹתוֹ חֵטְא (שהוא) לְגָדוֹל, אֶלָּא יַקְטִין אוֹתוֹ לְפָנָיו, וְאַחַר כָּךְ יַגְדִּיל אוֹתוֹ לִפְנֵי הָאַחֵר (הרשע), שֶׁכָּתוּב אַתֶּם חֲטָאתֶם חֲטָאָה גְדֹלָה."],[9,"","וְלֹא עָזַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁמָּסַר עַצְמוֹ לְמִיתָה, שֶׁכָּתוּב וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָחַל לָהֶם, שֶׁכָּתוּב וַיִּנָּחֵם ה' עַל הָרָעָה וְגוֹ'. וְנֹחַ לֹא עָשָׂה כֵּן, אֶלָּא רָצָה לְהִנָּצֵל, וְעָזַב אֶת כָּל הָעוֹלָם."],[10,"","וּבְכָל פַּעַם שֶׁהַדִּין שׁוֹרֶה עַל הָעוֹלָם, רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת: אוֹי שֶׁלֹּא נִמְצָא כְּמוֹ מֹשֶׁה, שֶׁכָּתוּב (ישעיה סג) וַיִּזְכֹּר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ אַיֵּה הַמַּעֲלֵם מִיָּם וְגוֹ', שֶׁכָּתוּב (שמות יד) וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. שֶׁהֲרֵי בַּתְּפִלָּה הוּא הֶעֱלָה אוֹתָם מֵהַיָּם, וּמִשּׁוּם שֶׁשָּׂם עַצְמוֹ בִּתְפִלָּה עַל יִשְׂרָאֵל בַּיָּם, נִקְרָא (על שמו) הַמַּעֲלֵם מִיָּם, שֶׁהוּא הֶעֱלָה אוֹתָם מֵהַיָּם."]]],[["אַיֵּה הַשָּׂם בְּקִרְבּוֹ אֶת רוּחַ קָדְשׁוֹ דָּא אִיהוּ משֶׁה דְּאַשְׁרֵי שְׁכִינְתָּא בֵּינַיְיהוּ דְיִשְׂרָאֵל. מוֹלִיכָם בַּתְּהֹמוֹת כַּד אִתְבָּקְעוּ מַיָא וְאֲזְלוּ בְּגוֹ תְּהוֹמֵי בְּיַבֶּשְׁתָּא דִּגְלִידוּ מַיָא (וכלא אתמר על משה). (נ\"א ועל דא אקרי משה עמו) בְּגִין דְּאַמְסַר גַּרְמֵיהּ עַל יִשְׂרָאֵל.","אָמַר רַבִּי יְהוּדָה אַף עַל גַּב דְּזַכָּאָה הֲוָה נֹחַ לָאו אִיהוּ כְּדַאי (בגין) דְּקוּדְשָׁא בְּרִיךְ הוּא יָגִין עַל עָלְמָא בְּגִינֵיהּ. תָּא חֲזֵי, משֶׁה לָא תָּלָה מִלָּה בִּזְכוּתֵיהּ אֶלָּא בִּזְכוּת אֲבָהָן קַדְמָאֵי. אֲבָל נֹחַ לָא הֲוָה לֵיהּ בְּמַאן דְּיִתְלֵי בִּזְכוּתָא כְּמשֶׁה.","אָמַר רַבִּי יִצְחָק וְעִם כָּל דָּא כֵּיוָן דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ הֲוָה לֵיהּ לְמִבְעֵי רַחֲמֵי עֲלַיְיהוּ. וְקָרְבָּנָא דְּאַקְרִיב לְבָתַר, דְּיַקְרִיב לֵיהּ מִן קַדְמַת דְּנָא דִּלְמָא יִשָּׁכֵךְ רוּגְזָא מֵעָלְמָא.","אָמַר רַבִּי יְהוּדָה מַאי הֲוָה לֵיהּ לְמֶעְבַּד דְּהָא חַיָּיבֵי עָלְמָא הֲווּ מַרְגִּיזִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ יַקְרִיב קָרְבָּנָא. אֶלָּא וַדַּאי נֹחַ דָּחִיל עַל גַּרְמֵיהּ הֲוָה, בְּגִין דְּלָא יֶעֱרַע בֵּיהּ מוֹתָא בְּגוֹ חַיָּיבֵי עָלְמָא דְּהֲוָה חָמֵי עוֹבָדֵיהוֹן בִּישָׁא כָּל יוֹמָא, וְהֵיךְ מַרְגְזָן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כָּל יוֹמָא.","רַבִּי (אלעזר פתח) יִצְחָק אָמַר כָּל זִמְנָא דְּחַיָּיבֵי עָלְמָא אַסְגִּיאוּ, זַכָּאָה דְּאִשְׁתְּכַח בֵּינַיְיהוּ הוּא אִתְפַּס בְּקַדְמִיתָא. דִּכְתִיב, (יחזקאל ט׳:ו׳) וּמִמִּקְדָּשִׁי תָּחֵלּוּ. וְתָנִינָן אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְּקוּדָשִׁי. וְנֹחַ הֵיךְ שֵׁזִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בֵּין כָּל אִנּוּן חַיָּיבַיָא. אֶלָּא בְּגִין דְּיִפְקוּן מִנֵּיהּ תּוֹלָדִין בְּעָלְמָא דְּהֲוָה צַדִּיק כְּדְקָא יְאוּת.","וְתוּ דְּאִיהוּ אַתְרֵי בְּהוּ כָּל יוֹמָא וְיוֹמָא וְלָא קַבִּילוּ מִנֵּיהּ, וְקִיֵּים בְּנַפְשֵׁיהּ קְרָא דִּכְתִיב, (יחזקאל ג׳:י״ט) וְאַתָּה כִּי הִזְהַרְתָּ רָשָׁע וְגו'. וּכְתִיב וְאַתָּה אֶת נַפְשְׁךָ הִצַּלְתָּ. מִכָּאן כָּל מַאן דְּאַזְהַר לְחַיָּיבָא אַף עַל גַּב דְּלָא קַבִּיל מִנֵּיהּ הוּא שֵׁזִיב לֵיהּ לְגַרְמֵיהּ וְהַהוּא חַיָּיבָא אִתְפַּס בְּחוֹבֵיהּ. וְעַד כַּמָּה יַזְהַר לֵיהּ עַד דְּיִמְחֵי לֵיהּ הָא אוּקְמוּהָ חַבְרַיָא.","רַבִּי יוֹסֵי הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן יוֹמָא חַד, אָמַר לֵיהּ מַאי חָמָא קוּדְשָׁא בְּרִיךְ הוּא לְשֵׁיצָאָה כָּל חֵיוַת בְּרָא וְעוֹף שְׁמַיָא עִמְּהוֹן דְּחַיָיבַיָא. אִי בְּנֵי נָשָׁא חָטָאן בְּעִירֵי וְעוֹפֵי שְׁמַיָא וּשְׁאָר בְּרִיָין מַה חָטוּ. אָמַר לֵיהּ בְּגִין דִּכְתִיב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ. כֻּלְהוּ הֲווּ מְחַבְּלֵי אָרְחַיְיהוּ. שַׁבְקֵי זִינַיְהוּ וְדָבְקוּ בְּזִינָא אָחֳרָא.","תָּא חֲזֵי, אִנּוּן חַיָּיבֵי עָלְמָא גָּרְמוּ הָכִי לְכָל בִּרְיָין. וּבָעוֹן (לאשכחא) לְאַכְּחָשָׁא עוֹבָדָא דִבְרֵאשִׁית. וְאִנּוּן גָּרְמוּ לְכָל בִּרְיָין לְחַבְּלָא אָרְחַיְיהוּ כְּמָה דְאִנּוּן מְחַבְּלָן. אָמַר קוּדְשָׁא בְּרִיךְ הוּא אַתּוּן בְּעִיתוּ (לאשכחא) לְאַכְּחָשָׁא עוֹבָדֵי יְדַי, אֲנָא אַשְׁלִים רְעוּתָא דִּלְכוֹן וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנִי הָאֲדָמָה. אַהֲדַר עָלְמָא לְמַיִין כְּמָה דְּהֲוָה בְּקַדְמִיתָא מַיִין בְּמַיִין וְהָא אִתְּמָר. מִכָּאן וּלְהָלְאָה אַעֲבִיד בִּרְיָין אָחֳרָנִין בְּעָלְמָא כְּדְקָא יְאוּת:","וַיָּבֹא נֹחַ וּבָנָיו וְאִשְׁתּוֹ וּנְשֵׁי בָנָיו אִתּוֹ. רַבִּי חִיָּיא פָּתַח וְאָמַר (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לא אֶרְאֶנּוּ נְאֻם יְיָ. כַּמָּה אִנּוּן בְּנֵי נָשָׁא אֲטִימִין לִבָּא סְתִימִין עַיְינִין דְּלָא מַשְׁגִּיחִין וְלָא יָדְעִין בִּיקָרָא דְמָארֵיהוֹן דִּכְתִיב בֵּיהּ הֲלֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא. הֵיךְ בָּעוּן בְּנִי נָשָׁא לְאִסְתַּתְּרָא מֵחוֹבַיְיהוּ וְאָמְרֵי מִי רוֹאֵנוּ וּמִי יוֹדְעֵנוּ. וּכְתִיב, (ישעיהו כ״ט:ט״ו) וְהָיָה בְּמַחְשָׁךְ מַעֲשֵׂיהֶם. לְאָן יִתְטַמְרוּן מִקַּמֵּיהּ.","לְמַלְכָּא דְּבָנָה פַּלְטְרִין וְעֲבַד תְּחוֹת אַרְעָא טְמִירִין פְּצִירִין. לְיוֹמִין מָרָדוּ בְּנֵי פַּלְטְרִין בְּמַלְכָּא אַסְחַר (אצער) עֲלַיְיהוּ מַלְכָּא בְּגַיְיסוֹי. מָה עֲבָדוּ עָאלוּ וּטְמִירוּ גַּרְמַיְיהוּ תְּחוֹת נוּקְבֵי פְּסִירִין. אָמַר מַלְכָּא אֲנָא עַבְדִית לוֹן וּמִקַּמָּאי אַתּוּן בָּעָאן לְאִתְטַמָּרָא, הֲדָא הוּא דִכְתִיב אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם יְיָ. אֲנָא הוּא דַּעֲבָדִית נוּקְבֵי פְּסִירִין וְעֲבָדִית חֲשׁוֹכָא וּנְהוֹרָא וְאַתּוּן אֵיךְ יָכְלִין לְאִתְטַמָּרָא קַמָּאי.","תָּא חֲזֵי, כַּד בַּר נָשׁ חָטֵי קַמֵּי מָארֵיהּ וְאַמְשִׁיךְ גַּרְמֵיהּ לְאִתְכַּסְיָא. קוּדְשָׁא בְּרִיךְ הוּא עָבִיד בֵּיהּ דִּינָא בְּאִתְגַּלְיָא. וְכַד בַּר נָשׁ אַדְכֵּי גַרְמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאַסְתָּרָא לֵיהּ דְּלָא יִתְחֲזֵי בְּיוֹם אַף יְיָ. דְּוַדַּאי אִבָּעֵי לֵיהּ לְאֵינַשׁ דְּלָא יִתְחֲזֵי קַמֵּי מְחַבְּלָא כַּד שַׁרְיָא עַל עַלְמָא דְּלָא יִסְתַּכֵּל בֵּיהּ. דְּהָא כָּל אִנּוּן דְּיִתְחַזּוּן קַמֵּיהּ אִית לֵיהּ רְשׁוּ לְחַבָּלָא."],[[0,"איה השם בקרבו את רוח קדשו:","הוא משה, שהשרה השכינה בתוך ישראל, וכן, מוליכם בתהומות, כאשר נבקעו המים והלכו בתוך התהומות ביבשה, שקפאו המים, והוא משום שמסר את עצמו על ישראל ע\"כ נקרא כל זה על שמו."],[1,"אמר ר' יהודה וכו':","אר\"י אע\"פ שנח היה צדיק, לא היה כדאי שהקב\"ה יגן על העולם בשבילו. בוא וראה, משה לא תלה משהו בזכותו אלא, בזכות אבות הראשונים, אבל נח לא היה לו במי שיתלה בזכותו, כמו משה."],[2,"אמר ר' יצחק וכו':","ועם כל זה. כיון שאמר לו הקב\"ה, והקימותי את בריתי אתך, היה לו לבקש רחמים עליהם, והקרבן שהקריב אחר המבול, היה לו להקריב מקודם לכן, אולי היה משקיט הכעס מהעולם."],[3,"אמר ר' יהודה וכו':","אר\"י מה היה לו לנח לעשות, שהרי רשעי עולם היו מכעיסים לפני הקב\"ה והוא יקריב קרבן עליהם, אלא ודאי נח היה מפחד על עצמו שלא ישיגהו המות בתוך רשעי העולם, כי היה רואה מעשיהם הרעים כל היום, ואיך מכעיסים כל היום לפני הקב\"ה."],[4,"ר' יצחק אמר וכו':","רי\"א בכל זמן שמתרבים רשעי עולם, הצדיק שנמצא ביניהם, הוא נענש תחלה, שכתוב וממקדשי תחלו, ולמדנו אל תקרא ממקדשי אלא ממקודשי, ולפי זה, ונח, איך הצילו הקב\"ה בין כל אותם הרשעים. ואומר, אלא בשביל שיצאו ממנו תולדות בעולם, הצילו כי היה צדיק כראוי. כלומר, והוא ראוי להוציא תולדות מתוקנים."],[5,"ותו דאיהו וכו':",": ועוד שהוא התרה בהם כל יום ויום ולא קבלו ממנו, וקיים בנפשו המקרא שכתוב, ואתה כי הזהרת רשע וגו' וכתיב ואתה את נפשך הצלת. מכאן, כל מי שמזהיר את הרשע, אע\"פ שלא קיבל ממנו, הוא הציל את עצמו, ואותו הרשע נתפס בחטאו. ושואל, ועד כמה מחויב להזהיר אותו ואומר עד שיכנו. וכבר בארוהו החברים."],[6,"ר' יוסי הוה שכיח וכו':","ר\"י היה מצוי לפני ר\"ש. יום אחד, אמר לו, מה ראה הקב\"ה לכלות כל חיות השדה וכל עוף השמים ביחד עם הרשעים, אם בני אדם חטאו, בהמות ועוף השמים ושאר הבריות מה חטאו. אמר לו, משום שכתוב כי השחית כל בשר את דרכו על הארץ, כולם היו משחיתים את דרכם, עזבו את מינם ונתדבקו במין אחר."],[7,"ת\"ח אינון חייבי וכו':","בא וראה, רשעי העולם האלו גרמו כן לכל הבריות, שיתדבקו באינו מינם, ובקשו להכחיש מעשה בראשית, דהיינו לערבב המינים זה בזה ולהכחיש צורתם, והם גרמו לכל הבריות להשחית דרכם כמו שהם השחיתו. אמר הקב\"ה אתם רוצים להכחיש מעשה ידי. אני אשלים רצונכם, ומחיתי את כל היקום אשר עשיתי מעל פני האדמה, אחזיר העולם למים, כמו שהיה העולם מתחלה מים במים, וכבר בארוהו. מכאן ולהלאה אעשה בריות אחרות בעולם כראוי."],[8,"ויבא נח ובניו וגו':","רבי חייא פתח ואמר, אם יסתר איש במסתרים ואני לא אראנו נאם ה'. כמה הם בני אדם אטומי לב וסתומי עין, שאינם מסתכלים ואינם יודעים את כבוד רבונם, שכתוב בו, הלא את השמים ואת הארץ אני מלא, איך מבקשים בני אדם להסתר מחטאם, ואומרים, מי רואנו ומי יודענו. וכתוב והיה במחשך מעשיהם, אנה יסתתרו מלפניו."],[9,"למלכא דבנה פלטרין וכו':","בדומה למלך שבנה ארמון, ועשה מתחת קרקע הארמון מחבואים מבוצרים. לימים, מרדו בני הארמון בהמלך, והקיף אותם המלך בחיילותיו. מה עשו, באו והסתירו עצמם תוך המחילות המבוצרות. אמר המלך אני עשיתי את המחבואים הללו, ומלפני אתם רוצים להסתתר בהם. וז\"ש, אם יסתר איש במסתרים ואני לא אראנו נאם ה'. אני הוא שעשיתי המחילות המבוצרות. ועשיתי אור וחשך, ואתם, איך תוכלו להסתר מפני."],[10,"תא חזי וכו':","כשהאדם חטא לפני רבונו, וממשיך ומביא את עצמו להסתר, דהייינו שמביא את עצמו לחשוב שאין מי שיראנו, הקב\"ה עושה בו הדין בגלוי. וכשהאדם מטהר את עצמו, דהיינו שעושה תשובה, הקב\"ה מבקש להסתיר אותו, שלא יתראה ביום אף ה'. כי ודאי הוא, שהאדם צריך להסתיר עצמו שלא יתראה לפני המשחית כשהוא שורה בעולם, כדי שלא יסתכל בו, כי כל אלו שמתראים לפניו, יש לו רשות להשחיתם."]],[[0,"","אַיֵּה הַשָּׂם בְּקִרְבּוֹ אֶת רוּחַ קָדְשׁוֹ - זֶהוּ מֹשֶׁה, שֶׁהִשְׁרָה שְׁכִינָה בֵּין יִשְׂרָאֵל. מוֹלִיכָם בַּתְּהֹמוֹת - כְּשֶׁנִּבְקְעוּ הַמַּיִם וְהָלְכוּ בְּתוֹךְ הַתְּהוֹם בַּיַּבָּשָׁה שֶׁקָּפְאוּ הַמַּיִם (והכל נאמר על משה) (נ\"א: ועל זה נקרא משה עמו), מִשּׁוּם שֶׁמָּסַר עַצְמוֹ עַל יִשְׂרָאֵל."],[1,"","אָמַר רַבִּי יְהוּדָה, אַף עַל גַּב שֶׁצַּדִּיק הָיָה נֹחַ, אֵינוֹ כְּדַאי (כדי) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָגֵן עַל הָעוֹלָם בִּשְׁבִילוֹ. בֹּא רְאֵה, מֹשֶׁה לֹא תָלָה הַדָּבָר בִּזְכוּתוֹ, אֶלָּא בִּזְכוּת הָאָבוֹת הָרִאשׁוֹנִים, אֲבָל לְנֹחַ לֹא הָיָה לוֹ בְּמַה שֶּׁיִּתְלֶה בִּזְכוּת כְּמוֹ מֹשֶׁה."],[2,"","אָמַר רַבִּי יִצְחָק, וְעִם כָּל זֶה, כֵּיוָן שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ, הָיָה לוֹ לְבַקֵּשׁ עֲלֵיהֶם רַחֲמִים. וְהַקָּרְבָּן שֶׁהִקְרִיב אַחַר כָּךְ - שֶׁיַּקְרִיב אוֹתוֹ מִקֹּדֶם לָזֶה, אוּלַי יִשְׁכַּךְ הַכַּעַס מֵהָעוֹלָם."],[3,"","אָמַר רַבִּי יְהוּדָה, מֶה הָיָה לוֹ לַעֲשׂוֹת, שֶׁהֲרֵי רִשְׁעֵי הָעוֹלָם הָיוּ מַכְעִיסִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא יַקְרִיב קָרְבָּן!? אֶלָּא וַדַּאי נֹחַ פּוֹחֵד עַל עַצְמוֹ הָיָה בִּשְׁבִיל שֶׁלֹּא יִפְגֹּשׁ בּוֹ הַמָּוֶת בְּתוֹךְ רִשְׁעֵי הָעוֹלָם, שֶׁהָיָה רוֹאֶה מַעֲשֵׂיהֶם הָרָעִים בְּכָל יוֹם וְאֵיךְ מַכְעִיסִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל יוֹם."],[4,"","רַבִּי (אלעזר פתח) יִצְחָק אָמַר, כָּל פַּעַם שֶׁמִּתְרַבִּים רִשְׁעֵי הָעוֹלָם, הַצַּדִּיק שֶׁנִּמְצָא בֵינֵיהֶם נִתְפָּס בָּרִאשׁוֹנָה, שֶׁכָּתוּב (יחזקאל ט) וּמִמִּקְדָּשִׁי תָּחֵלּוּ. וְשָׁנִינוּ, אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְקֻדָּשִׁי. וְאֵיךְ הִשְׁאִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת נֹחַ בֵּין כָּל אוֹתָם הָרְשָׁעִים? אֶלָּא כְּדֵי שֶׁיֵּצְאוּ מִמֶּנּוּ תוֹלָדוֹת לָעוֹלָם, שֶׁהָיָה צַדִּיק כָּרָאוּי."],[5,"","וְעוֹד, שֶׁהוּא הִתְרָה בָהֶם כָּל יוֹם וָיוֹם וְלֹא קִבְּלוּ מִמֶּנּוּ, וְקִיֵּם בְּנַפְשׁוֹ אֶת הַפָּסוּק שֶׁכָּתוּב (שם ג) וְאַתָּה כִּי הִזְהַרְתָּ רָשָׁע וְגוֹ', וְכָתוּב וְאַתָּה אֶת נַפְשְׁךְ הִצַּלְתָּ. מִכָּאן שֶׁכָּל מִי שֶׁמַּזְהִיר אֶת הָרָשָׁע - אַף עַל גַּב שֶׁלֹּא קִבֵּל מִמֶּנּוּ, הוּא מַצִּיל אֶת עַצְמוֹ, וְאוֹתוֹ רָשָׁע נִתְפָּס בְּחֶטְאוֹ. וְעַד כַּמָּה יַזְהִיר אוֹתוֹ? עַד שֶׁיַּכֶּה אוֹתוֹ, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים."],[6,"","רַבִּי יוֹסֵי הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן יוֹם אֶחָד. אָמַר לוֹ, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁמִיד אֶת כָּל חַיּוֹת הַבָּר וְעוֹף הַשָּׁמַיִם עִם הָרְשָׁעִים? אִם בְּנֵי הָאָדָם חָטְאוּ, בְּהֵמוֹת וְעוֹפוֹת הַשָּׁמַיִם וּשְׁאָר הַבְּרִיּוֹת מֶה חָטְאוּ? אָמַר לוֹ, מִשּׁוּם שֶׁכָּתוּב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ. כֻּלָּם הָיוּ מַשְׁחִיתִים דַּרְכֵיהֶם. עָזְבוּ אֶת מִינָם וְנִדְבְּקוּ בְּמִין אַחֵר."],[7,"","בֹּא רְאֵה, אוֹתָם רִשְׁעֵי הָעוֹלָם גָּרְמוּ כָּךְ לְכָל הַבְּרִיּוֹת, וְרָצוּ (להשכיח) לְהַכְחִישׁ מַעֲשֵׂה בְרֵאשִׁית, וְהֵם גָּרְמוּ לְכָל הַבְּרִיּוֹת לְהַשְׁחִית דַּרְכָּם כְּמוֹ שֶׁהֵם הִשְׁחִיתוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתֶּם רְצִיתֶם (להשכיח) לְהַכְחִישׁ מַעֲשֵׂי יָדַי? אֲנִי אַשְׁלִים רְצוֹנְכֶם, וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנֵי הָאֲדָמָה. אַחֲזִיר הָעוֹלָם לְמַיִם כְּמוֹ שֶׁהָיָה בַּהַתְחָלָה, מַיִם בְּמַיִם, וַהֲרֵי נִתְבָּאֵר. מִכָּאן וָהָלְאָה אֶעֱשֶׂה בְּרִיּוֹת אֲחֵרוֹת בָּעוֹלָם כָּרָאוּי."],[8,"","וַיָּבֹא נֹחַ וּבָנָיו וְאִשְׁתּוֹ וּנְשֵׁי בָנָיו אִתּוֹ. רַבִּי חִיָּיא פָּתַח וְאָמַר, (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'. כַּמָּה הֵם בְּנֵי אָדָם אֲטוּמֵי לֵב וּסְתוּמֵי עֵינַיִם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים בִּכְבוֹד רִבּוֹנָם, שֶׁכָּתוּב בּוֹ הֲלוֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא. אֵיךְ רוֹצִים בְּנֵי אָדָם לְהִסְתַּתֵּר מֵחֲטָאֵיהֶם וְאוֹמְרִים מִי רוֹאֵנוּ וּמִי יוֹדְעֵנוּ, וְכָתוּב (ישעיה כט) וְהָיָה בְמַחְשָׁךְ מַעֲשֵׂיהֶם. לְאָן יֵחָבְאוּ מִפָּנָיו?"],[9,"","לְמֶלֶךָ שֶׁבָּנָה פַּלְטֵרִין וְעָשָׂה תַּחַת הָאָרֶץ מְחִלּוֹת נִסְתָּרוֹת. לְיָמִים מָרְדוּ בְּנֵי הָאַרְמוֹן בַּמֶּלֶךְ. הִקִּיף (צער) עֲלֵיהֶם הַמֶּלֶךְ בִּגְיָסוֹת. מֶה עָשׂוּ? נִכְנְסוּ וְהֶחְבִּיאוּ עַצְמָם תַּחַת נִקְבֵי הַמְּחִלּוֹת. אָמַר הַמֶּלֶךְ, אֲנִי עָשִׂיתִי אוֹתָם, וּמִלְּפָנַי אַתֶּם רוֹצִים לְהִתְחַבֵּא? זֶהוּ שֶׁכָּתוּב אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'? אֲנִי הוּא שֶׁעָשִׂיתִי מְחִלּוֹת וְעָשִׂיתִי חֹשֶׁךְ וְאוֹר, וְאַתֶּם אֵיךְ תּוּכְלוּ לְהִתְחַבֵּא מִלְּפָנַי?!"],[10,"","בֹּא רְאֵה, כְּשֶׁאָדָם חוֹטֵא לִפְנֵי רִבּוֹנוֹ וּמַמְשִׁיךְ עַצְמוֹ לְהִסְתַּתֵּר, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה בּוֹ דִּין בְּגָלוּי. וּכְשֶׁהָאָדָם מְטַהֵר עַצְמוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהַסְתִּירוֹ שֶׁלֹּא יִרְאֶה בְּיוֹם אַף ה'. שֶׁוַּדַּאי שֶׁצָּרִיךְ לוֹ לָאָדָם שֶׁלֹּא לְהֵרָאוֹת לִפְנֵי הַמַּשְׁחִית כְּשֶׁשּׁוֹרֶה עַל הָעוֹלָם שֶׁלֹּא יִסְתַּכֵּל בּוֹ, שֶׁהֲרֵי כָּל אֵלּוּ שֶׁנִּרְאִים לְפָנָיו, יֵשׁ לוֹ רְשׁוּת לְהַשְׁחִית."]]],[["וְהַיְינוּ דְקָאֲמַר רַבִּי שִׁמְעוֹן כָּל בַּר נָשׁ דְּעֵינֵיהּ בִּישָׁא, עֵינָא דִּמְחַבְּלָא שַׁרְיָא עֲלוֹי. וְאִיהוּ מְחַבְּלָא דְעָלְמָא אִקְרֵי. וְלִבָּעֵי לֵיהּ לְאִינֵישׁ לְאִסְתַּמְּרָא מִנֵּיהּ וְלָא לְאִתְקְרָבָא בַּהֲדֵיהּ דְּלָא יִתְּזַק (קמיה). וְאָסִיר לְמִקְרַב בַּהֲדֵיהּ בְּאִתְגַּלְיָא. וּמִשּׁוּם הָכִי מֵאִישׁ רַע עַיִן בָּעֵי לְאִסְתַּמְּרָא מִנִּיהּ. מִקַּמֵּי מַלְאַךְ הַמָּוֶת עַל אַחַת כַּמָּה וְכַמָּה.","(ועל דא) מַה כְּתִיב בְּבִלְעָם (במדבר כ״ד:ג׳) וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן. דְּעֵינָא בִּישָׁא הֲוָה לֵיהּ וּבְכָל אֲתַר דְּהֲוָה מִסְתַּכֵּל בֵּיהּ הֲוָה אַמְשִׁיךְ עֲלֵיהּ רוּחַ מְחַבְּלָא. וּבְגִין כָּךְ הֲוָה בָּעֵי לְאִסְתַּכָּלָא בְּהוּ בְּיִשְׂרָאֵל בְּגִין דִּישֵׁצֵי בְּכָל אֲתַר דְּעֵינֵיהּ הֲוָה מִסְתַּכֵּל. מַה כְּתִיב וַיִּשָּׂא בִּלְעָם אֶת עֵינָיו דְּזָקִיף עֵינָא חַד וּמָאִיךְ עֵינָא חַד בְּגִין לְאִסְתַּכָּלָא בְּהוּ בְּיִשְׂרָאֵל בְּעֵינָא בִּישָׁא.","תָּא חֲזֵי, מַה כְּתִיב וַיַּרְא אֶת יִשְׂרָאֵל שׁוֹכֵן לִשְׁבָטָיו. וְחָמָא דִּשְׁכִינְתָּא חַפְיָא עֲלַיְיהוּ וּרְבִיעָא עֲלַיְיהוּ מִתְתַּקְּנָא בִּתְרֵיסַר שִׁבְטִין תְּחוֹתָהּ וְלָא יָכִיל לְשַׁלְטָאָה עֲלַיְיהוּ עֵינֵיהּ. אָמַר אֵיךְ אֵיכוֹל לְהוֹן דְּהָא רוּחַ קַדִּישָׁא עִלָּאָה רְבִיעָא עֲלַיְיהוּ וְחָפַת לוֹן בְּגַדְפָהָא. הֲדָא הוּא דִכְתִיב כָּרַע שָׁכַב כַּאֲרִי, וּכְלָבִיא. מִי יְקִימֶנּוּ. מִי יְקִימֶנּוּ מֵעֲלַיְיהוּ בְּגִין דְּיִתְגַלְיָין וְשָׁלְטָא עֵינָא עֲלַיְיהוּ.","וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְחַפְיָא לְנֹחַ לְאִסְתַּתְּרָא מֵעֵינָא דְּלָא יָכִיל רוּחַ מְסָאֳבָא לְשַׁלְטָא עֲלֵיהּ בְּגִין דְּלָא יִתְחַבֵּל וְהָא אִתְּמָר. וַיָּבֹא נֹחַ כְּמָה דְּאִתְּמָר לְאִסְתַּתְּרָא מֵעֵינָא. מִפְּנֵי מֵי הַמַּבּוּל (דהא) דְּמַיִין דָּחֲקוּ לֵיהּ. אָמַר רַבִּי יוֹסֵי חָמָא מַלְאַךְ הַמָּוֶת דְּהֲוָה אָתֵי (ד\"א ל\"ג לגביה) וּבְגִין כָּךְ עָאל לְתֵיבוּתָא וְאִסְתַּמַּר בָהּ תְּרִיסַר יַרְחֵי (שתא).","וְאַמַּאי תְּרֵיסַר יַרְחִין. פְּלִיגֵי בָּהּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה. חַד אָמַר י\"ב יַרְחִין דְּכָךְ אִיהוּ דִינָא דְּחַיָיבַיָא. וְחַד אָמַר לְאַשְׁלָמָא צַדִּיק (נ\"א צריך) דַּרְגִּין תְּרֵיסַר וּשְׁאָר דַּרְגִּין דְּאִתְחַזֵּי לְאֲפָקָא מִן תֵּיבָה.","רַבִּי יְהוּדָה אָמַר שִׁתָּא יַרְחֵי אִנּוּן בְּמַיָא וְשִׁיתָּא יַרְחֵי בְּאֶשָׁא. וְהָא הָכָא מַיָיא הֲווּ אַמַּאי תְּרֵיסַר יַרְחֵי. אָמַר (ליה) רַבִּי יוֹסֵי בִּתְרֵי דִינִין דְּגֵיהִנֹּם אִתְדָנוּ בְּמַיָא וְאֶשָׁא. בְּמַיָא דְּמַיִין דְּנָחֲתוּ עֲלַיְיהוּ מִלְּעֵילָא הֲווּ צְנִינִין כְּתַלְגָא. בְּאֶשָׁא דְּמַיִין דְּנַפְקֵי מִתַּתָּא הֲווּ רְתִיחָן כְּאֶשָׁא. וְעַל דָּא בְּדִינָא דְּגֵיהִנֹּם אִתְדָּנוּ בְּאֶשָׁא וּמַיָיא (ובגין כך תריסר ירחי הוו דאמר רבי אלעזר דינא דחייביא בגיהנם תריסר ירחי הוו והא אוקמוה. ועל דא כל אנון חייבי עלמא אתדנו בתרין דינין אלין במיא ואשא) עַד דְּאִשְׁתֵּצִיאוּ מֵעָלְמָא. וְנֹחַ הֲוָה מִסְתַּתֵּר בְּתֵיבוּתָא וְאִתְכַּסֵּי מֵעֵינָא וּמְחַבְּלָא לָא קָרִיב לְגַבֵּיהּ, וְתֵיבוּתָא אִיהִי הֲוָה שַׁטְיָא עַל אַנְפֵּי מַיָא כְּמָא דְאַתְּ אָמֵר וַיִּשְׂאוּ אֶת הַתֵּיבָה וַתָּרָם מֵעַל הָאָרֶץ.","אַרְבָּעִים יוֹם לָקוּ. דִּכְתִיב וַיְהִי הַמַּבּוּל אַרְבָּעִים יוֹם עַל הָאָרֶץ וְגו'. וְכָל שְׁאָר זִמְנָא אִתְמְחוּן מֵעָלְמָא. הֲדָא הוּא דִכְתִיב וַיִּמָּחוּ מִן הָאָרֶץ. וַוי לוֹן לְאִנּוּן חַיָיבַיָא דְּהָא לָא יְקוּמוּן לְאַחְיָיא בְּעָלְמָא לְמֵיקַם בְּדִינָא הֲדָא הוּא דִכְתִיב וַיִּמָּחוּ כְּמָא דְאַתְּ אָמֵר, (תהילים ט׳:ו׳) שְׁמָם מָחִית לְעוֹלָם וָעֶד. דְּאֲפִילּוּ לְמֵיקַם בְּדִינָא לָא יְקוּמוּן:","וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ. רַבִּי אַבָּא פָּתַח (תהילים נ״ז:ו׳) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךָ. וַוי לוֹן לְחַיָיבַיָא דְּאִנּוּן חָטָאן וּמַרְגִּיזִין לְמָארֵיהוֹן בְּכָל יוֹמָא. וּבְחוֹבַיְיהוּ דַּחְיָין לָהּ לַשְּׁכִינְתָּא מֵאַרְעָא. וְגָרְמִין דְּתִסְתַּלֵּק מֵעָלְמָא. וּשְׁכִינְתָּא אִקְרֵי אֱלֹהִים. וְעֲלָהּ כְּתִיב רוּמָה עַל הַשָּׁמַיִם אֱלהִים.","תָּא חֲזֵי, מַה כְּתִיב וַיִּשְׂאוּ אֶת הַתֵּבָה דְּדַחְיָין לָהּ לְבַר. וַתָּרָם מֵעַל הָאָרֶץ, דְּלָא שַׁרְיָיא בְּעָלְמָא וְאִסְתַּלְקַת מִנָּהּ. וְכַד אִסְתַּלְקַת מֵעָלְמָא, הָא לֵית מַאן דְּיַשְׁגַּח בְּעָלְמָא וְדִינָא שָׁלְטָא (בדינא) כְּדֵין עֲלוֹי. וְכַד יִתְמָחוּן חַיָּיבֵי עָלְמָא וְיִסְתַּלְּקוּן מִנֵּיהּ (דעלמא), שְׁכִינְתָּא אֲהַדְרַת מְדוֹרָהּ בְּעָלְמָא.","אָמַר לֵיהּ רַבִּי יֵיסָא, אִי הָכִי הָא אַרְעָא דְיִשְׂרָאֵל דְּאִתְמָחוּן חַיָּיבַיָא דְּהֲווּ בְּהַהוּא זִמְנָא אַמַּאי לָא אֲהַדְּרַת שְׁכִינְתָּא לְאַתְרָהּ כְּדִבְקַדְמִיתָא. אָמַר לֵיהּ בְּגִין דְּלָא אִשְׁתָּאֲרוּ בָהּ שְׁאָר זַכָּאֵי עָלְמָא. אֶלָּא (אבל) בְּכָל אֲתַר דְּאֲזְלוּ נַחְתַת וְשַׁוִּיאַת מְדוֹרָהּ עִמְּהוֹן. וּמַה בְּאַרְעָא נוּכְרָאָה אָחֳרָא לָא אִתְפָּרְשָׁא מִנַּיְיהוּ, כָּל שֶׁכֵּן אִי אִשְׁתְּאָרוּ בְּאַרְעָא קַדִּישָׁא."],[[0,"והיינו דקאמר רבי שמעון וכו':","והוא שאמר רבי שמעון, כל אדם שעינו רעה, עין המשחית שורה עליו, והוא נקרא משחית העולם, וצריך האדם להשמר ממנו, שלא יקרב אליו, ולא יוזק. ואסור לקרב אליו בגלוי. כלומר, שיהיה נגלה לעינו הרעה. ומשום זה, אם מאדם רע עין צריכים להשמר ממנו, מפני מלאך המות על אחת כמה וכמה שצריכים להשמר מפניו. וצריכים להסתר ביום אף ה'."],[1,"מה כתיב בבלעם וכו':","מה כתוב בבלעם. ונאם הגבר שתום העין. שהיה לו עין רעה, ובכל מקום שהיה מסתכל בו, היה ממשיך עליו רוח המשחית. ומשום זה היה רוצה להסתכל בישראל, כדי שיכלה בכל מקום שעינו תסתכל. מה כתיב, וישא בלעם את עיניו, שזקף עין אחת והשפיל עין אחת, כדי להסתכל בישראל בעין הרעה."],[1,"","פירוש. כי אברים הכפולים העינים והאזנים וכו' באים משיתוף מדת הדין עם מדת הרחמים, דהינו המלכות בבינה. ואבר הימני עקרו ממדת הרחמים מבינה, ואבר השמאלי עקרו מדת הדין ממלכות דצמצום א'. (כמ\"ש בתע\"ס חלק ו' דף תס\"ו תשובה כ\"א ע\"ש.) גם נודע שאם האדם זוכה נמצא מדת הדין בגניזו והעלמה, ומדת הרחמים הוא בגלוי והיא פועלת הכל. ואם אינו זוכה, מתגלה עליו מדת הדין והוא אובד הכל. (כנ\"ל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' תרין ע\"ש) וז\"ש לעיל \u0003דלא יתחזי קמי מחבלא\u0004 וכו' \u0003דהא כל אינון דיתחזון קמיה אית ליה רשו לחבלא,\u0004 כי כשמתרבים הרשעים בעולם ניתן רשות למשחית לגלות את מדת הדין ולהעניש את העולם, לכן גם הצדיק צריך לפחוד ממנו, שהרי כל כחו הוא, מפני שמדת הדין נעלם וגניז, ואינו פועל כלפי הצדיק, לפיכך יוכל המשחית לגלות מדת הדין שבו ולהענישו ביחד עם הרשעים. וז\"ס שאומר כאן בבלעם, \u0003דעינא בישא הוה ליה וכו' בעי לאסתכלא בישראל בגין דישצי בכל אתר דעיניה הוה מסתכל.\u0004 דהיינו שבעין הרעה שלו היה מגלה מדת הדין הטמיר, כנ\"ל. וז\"ש \u0003דזקיף עינא חד,\u0004 שהוא עין השמאלי דמדת הדין. \u0003ומאיך עינא חד,\u0004 שביטל כח עינו הימני ששם מדת הרחמים. \u0003בגין לאסתכלא בהו בישראל בעינא בישא,\u0004 דהיינו בעין השמאלי שלו, שהוא מדת הדין."],[2,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב, וירא את ישראל שוכן לשבטיו, וראה שהשכינה חופפת עליהם ורובצת עליהם, ומתתקנת בי\"ב שבטים מתחתיה, ולא יכול עינו של בלעם לשלוט עליהם. אמר, איך אוכל להם הרי רוח הקדש העליון, דהיינו בינה, רובץ עליהם וחופה אותם בכנפיה, ז\"ש כרע שכב כארי וכלביא מי יקימנו, שפירושו, מי יקימנו, לרוח הקדש העליון שלא יחפה עליהם, כדי שיתגלו, והעין יוכל לשלט בהם. פירוש. כי רוח הקדש העליון, היא בינה שה\"ס מדת הרחמים, שהיתה מחפה ומגינה על ישראל, שמדת הדין לא תוכל לשלוט בהם. וע\"כ אמר בלעם, \u0003מי יקימנו\u0004 שלא תכסה אותם מדת הרחמים ותוכל עינו הרעה לכלותם."],[3,"ועל דא קב\"ה וכו':","ועל כן ביקש הקב\"ה לחפות על נח להסתירו מעין רואה, כדי שלא יוכל רוח הטמא לשלוט עליו, כדי שלא ישחת, וכבר בארנוה. \u0003ויבא נח,\u0004 הוא כמו שאמרנו כדי להסתר מעין. \u0003מפני מי המבול,\u0004 כי המים דחקו אותו אל התבה. כלומר, כי ראה את מי המבול, ופחד מהם, וע\"כ בא אל התבה. אמר ר' יוסי ראה את מלאך המות שהיה בא, עם מי המבול, וע\"כ נכנס אל התיבה."],[4,"ואסתמר בה תריסר ירחי וכו':","ונשמר בה בהתבה י\"ב חדשי השנה. ושואל, למה הם י\"ב חדשים. חולקים בה ר' יצחק ור' יהודה, אחד אומר, שי\"ב חודש הם, כי כך הוא דינם של הרשעים בגיהנם, ואחד אומר שהם, כדי להשלים בי\"ב מדרגות את נח הצדיק ושאר המדרגות שהיו ראוים לצאת מן התבה, שלתקון כל מדרגה צריכים חודש אחד, וע\"כ נתעכבו י\"ב חדש."],[5,"ר' יהודה אמר וכו':","ר\"י אמר הרי ששה חדשים דנים את הרשעים בגיהנם במים. וששה חדשים דנים אותם באש. והנה כאן בהמבול רק דין של מים היה, וא\"כ למה נדונו י\"ב חדש, והיה מספיק ששה חדשים. אמר לו ר' יוסי, בשני הדינים של גיהנם נדונו, במים ובאש: נדונו במים, כי המים שהיו יורדים עליהם מלמעלה היו קרים כשלג. נדונו באש, כי המים שהיו יוצאים מלמטה מן התהום, היו רותחים כאש. וע\"כ נדונו בדינא דגיהנם י\"ב חדש במים ובאש, עד שנכלו מהעולם. ונח היה מסתתר בהתיבה ונעלם מעין, והמחבל לא קרב אליו, והתיבה היתה משוטטת על פני המים כמש\"א וישאו את התבה וגו'."],[6,"ארבעים יום וכו':","מ' יום לקו, שכתוב ויהי המבול ארבעים יום וגו', וכל שאר הזמן עד י\"ב חדש נמחו מהעולם וז\"א וימחו מן הארץ. ווי להם לאותם הרשעים, כי לא יקומו לתחיה בהעולם, לעמוד בדין, וז\"ש וימחו, כמש\"א, שמם מחית לעולם ועד. כי אפילו לעמוד בדין לא יקומו. כלומר שלא יהיו אפילו בין אותם שיקומו לדראון עולם."],[7,"וישאו את התבה ותרם וגו':","ר' אבא פתח רומה על השמים אלקים וגו'. ווי להם להרשעים שהם חוטאים ומכעיסים את רבונם בכל יום, ובחטאיהם דוחים את השכינה מהארץ, וגורמים שתסתלק מהעולם, והשכינה נקראת אלקים, ועליה כתוב רומה על השמים אלקים."],[8,"ת\"ח מה כתיב וכו':","בא וראה מה כתוב, וישאו את התיבה, פירושו, שדחו אותה לחוץ. התיבה היינו השכינה. ותרם מעל הארץ, פירושו, שהשכינה לא שרתה בהעולם ונסתלקה מהעולם. וכאשר נסתלקה מהעולם, הרי אין מי שישגיח על העולם, ואז הדין שולט בהעולם. ואחר שימחו רשעי עולם ויסתלקו ממנו, מחזרת השכינה את המדור שלה בהעולם."],[9,"א\"ל ר' ייסא וכו':","א\"ל ר\"י, אם כן, הנה ארץ ישראל, שנמחו הרשעים שהיו בה באותו הזמן, של חורבן בהמ\"ק, למה לא חזרה השכינה אחר כך למקומה כבתחילה. אמר לו, משום שלא נשארו בה שאר צדיקי העולם. כלומר, שהנשארים אחר החורבן לא נשארו בארץ ישראל אלא שהלכו למצרים כמ\"ש בירמיה. אלא בכל מקום שהלכו ישראל בגלות ירדה השכינה ושמה את מדורה עמהם. ומה בארץ נכריה אחרת, לא נפרדה מהם השכינה, כל שכן אם היו ישראל נשארים בארץ ישראל, ודאי שהיתה חוזרת אליהם אחר החורבן."]],[[0,"","וְזְהִוּ מַה שֶּׁאָמַר רַבִּי שִׁמְעוֹן, כָּל אָדָם שֶׁעֵינוֹ רָעָה - עֵין הַמַּשְׁחִית שׁוֹרָה עָלָיו. וְהוּא נִקְרָא מַשְׁחִית הָעוֹלָם. וְצָרִיךְ הָאָדָם לְהִשָּׁמֵר מִמֶּנּוּ וְלֹא לְהִתְקָרֵב אֵלָיו כְּדֵי שֶׁלֹּא יִנָּזֵק (לפניו), וְאָסוּר לִקְרַב אֵלָיו בְּהִתְגַּלּוּת. וּמִשּׁוּם כָּךְ צָרִיךְ לְהִשָּׁמֵר מֵאִישׁ רַע עַיִן, וּמִלִּפְנֵי מַלְאַךְ הַמָּוֶת עַל אַחַת כַּמָּה וְכַמָּה."],[1,"","(ועל זה) מַה כָּתוּב בְּבִלְעָם? (במדבר כד) וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן. שֶׁעַיִן רָעָה הָיְתָה לוֹ, וּבְכָל מָקוֹם שֶׁהָיָה מִסְתַּכֵּל בּוֹ, הָיָה מַמְשִׁיךְ עָלָיו אֶת רוּחַ הַמַּשְׁחִית. וְלָכֵן רָצָה לְהִסְתַּכֵּל בְּיִשְׂרָאֵל, כְּדֵי לְהַשְׁמִיד בְּכָל מָקוֹם שֶׁעֵינָיו הָיוּ מִסְתַּכְּלוֹת. מַה כָּתוּב? וַיִּשָּׂא בִלְעָם אֶת עֵינָיו. שֶׁזָּקַף עַיִן אַחַת וְהִנְמִיךְ עַיִן אַחַת כְּדֵי לְהִסְתַּכֵּל עַל יִשְׂרָאֵל בְּעַיִן רָעָה."],[2,"","בֹּא רְאֵה מַה כָּתוּב, וַיַּרְא אֶת יִשְׂרָאֵל שֹׁכֵן לִשְׁבָטָיו. וְרָאָה שֶׁהַשְּׁכִינָה מְכַסָּה עֲלֵיהֶם וְרוֹבֶצֶת עֲלֵיהֶם מְתֻקֶּנֶת בִּשְׁנֵים עָשָׂר שְׁבָטִים תַּחְתֶּיהָ, וְאֵין יְכוֹלוֹת עֵינָיו לִשְׁלֹט עֲלֵיהֶם. אָמַר, אֵיךְ אוּכַל לָהֶם, שֶׁהֲרֵי רוּחַ קְדוֹשָׁה עֶלְיוֹנָה רוֹבֶצֶת עֲלֵיהֶם וּמְכַסָּה אוֹתָם בִּכְנָפֶיהָ? זֶהוּ שֶׁכָּתוּב כָּרַע שָׁכַב כַּאֲרִי וּכְלָבִיא מִי יְקִימֶנּוּ. מִי יְקִימֶנּוּ מֵעֲלֵיהֶם כְּדֵי שֶׁיִּתְגַּלּוּ וְתִשְׁלֹט עֲלֵיהֶם הָעַיִן."],[3,"","וְעַל זֶה רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַסּוֹת אֶת נֹחַ, לְהִסְתַּתֵּר מֵהָעַיִן, שֶׁלֹּא תוּכַל רוּחַ הַטֻּמְאָה לִשְׁלֹט עָלָיו כְּדֵי שֶׁלֹּא יֻשְׁחַת, וַהֲרֵי נִתְבָּאֵר. וַיָּבֹא נֹחַ, כְּמוֹ שֶׁנִּתְבָּאֵר לְהִסְתַּתֵּר מֵהָעַיִן. מִפְּנֵי מֵי הַמַּבּוּל, (שהרי) הַמַּיִם דָּחֲקוּ אוֹתוֹ. אָמַר רַבִּי יוֹסֵי, רָאָה מַלְאַךְ הַמָּוֶת שֶׁהָיָה בָּא (אליו) וְלָכֵן נִכְנַס לַתֵּבָה וְנִשְׁמַר בָּהּ שְׁנֵים עָשָׂר חֳדָשִׁים (של השנה)."],[4,"","וְלָמָּה שְׁנֵים עָשָׂר חֳדָשִׁים? נֶחְלְקוּ בָהּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה. הָאֶחָד אָמַר שְׁנֵים עָשָׂר חֹדֶשׁ שֶׁכָּךְ הוּא דִין הָרְשָׁעִים. וְאֶחָד אָמַר לְהַשְׁלִים צַדִּיק (נ\"א צריך) שְׁתֵּים עֶשְׂרֵה דְרָגוֹת וּשְׁאָר הַדְּרָגוֹת שֶׁהָיוּ רְאוּיִים לָצֵאת מֵהַתֵּבָה."],[5,"","רַבִּי יְהוּדָה אָמַר, שִׁשָּׁה חֳדָשִׁים הֵם בְּמַיִם וְשִׁשָּׁה חֳדָשִׁים בְּאֵשׁ, וַהֲרֵי כָּאן הָיוּ מַיִם, וְלָמָּה שְׁנֵים עָשָׂר חֳדָשִׁים? אָמַר (לו) רַבִּי יוֹסֵי, בִּשְׁנֵי דִינֵי הַגֵּיהִנֹּם נִדּוֹנוּ - בְּמַיִם וְאֵשׁ. בְּמַיִם - שֶׁהַמַּיִם שֶׁיָּרְדוּ עֲלֵיהֶם מִלְמַעְלָה הָיוּ צוֹנְנִים כַּשֶּׁלֶג. וּבְאֵשׁ - שֶׁהַמַּיִם שֶׁיָּצְאוּ מִלְּמַטָּה הָיוּ רוֹתְחִים כָּאֵשׁ. וְעַל זֶה בְּדִין הַגֵּיהִנֹּם נִדּוֹנוּ - בְּאֵשׁ וּמַיִם (ולכן שנים עשר חדש היו, שאמר רבי אלעזר, דין הרשעים בגיהנם הם שנים עשר חדשים, והרי פרשוה, ועל זה כל אותם רשעי העולם נדונים בשני דינים הללו במים ואש) עַד שֶׁהֻשְׁמְדוּ מִן הָעוֹלָם. וְנֹחַ הָיָה מִסְתַּתֵּר בַּתֵּבָה וְהִתְכַּסָּה מִן הָעַיִן וְהַמַּשְׁחִית וְלֹא קָרַב אֵלָיו, וְהַתֵּבָה הָיְתָה שָׁטָה עַל פְּנֵי הַמַּיִם, כְּמוֹ שֶׁנֶּאֱמַר וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ."],[6,"","אַרְבָּעִים יוֹם לָקוּ, שֶׁכָּתוּב וַיְהִי הַמַּבּוּל אַרְבָּעִים יוֹם עַל הָאָרֶץ וְגוֹ'. וְכָל שְׁאָר הַזְּמַן נִמְחוּ מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ. אוֹי לָהֶם לְאוֹתָם רְשָׁעִים, שֶׁהֲרֵי לֹא יָקוּמוּ לִחְיוֹת בָּעוֹלָם לַעֲמֹד בְּדִין. זֶהוּ שֶׁכָּתוּב וַיִּמָּחוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ט) שְׁמָם מָחִיתָ לְעוֹלָם וָעֶד. שֶׁאֲפִלּוּ לַעֲמֹד בְּדִין לֹא יָקוּמוּ."],[7,"","וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ. רַבִּי אַבָּא פָּתַח, (שם נז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךְ. אוֹי לָהֶם לָרְשָׁעִים שֶׁחוֹטְאִים וּמַרְגִּיזִים אֶת רִבּוֹנָם בְּכָל יוֹם, וּבַחֲטָאֵיהֶם דּוֹחִים אֶת הַשְּׁכִינָה מִן הָאָרֶץ, וְגוֹרְמִים שֶׁתִּסְתַּלֵּק מִן הָעוֹלָם. וְהַשְּׁכִינָה נִקְרֵאת אֱלֹהִים, וְעָלֶיהָ כָּתוּב רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים."],[8,"","בֹּא רְאֵה מַה כָּתוּב, וַיִּשְׂאוּ אֶת הַתֵּבָה, שֶׁדָּחוּ אוֹתָהּ הַחוּצָה. וַתָּרָם מֵעַל הָאָרֶץ, שֶׁלֹּא שׁוֹרָה בָּעוֹלָם וְהִסְתַּלְּקָה מִמֶּנּוּ. וּכְשֶׁהִיא מִסְתַּלֶּקֶת מֵהָעוֹלָם, הֲרֵי אֵין מִי שֶׁיַּשְׁגִּיחַ בָּעוֹלָם, וְאָז הַדִּין שׁוֹלֵט (הדין) עָלָיו. וּכְשֶׁיִּמָּחוּ רִשְׁעֵי הָעוֹלָם וְיִסְתַּלְּקוּ מִמֶּנּוּ (מהעולם), הַשְּׁכִינָה מַחֲזִירָה אֶת מְדוֹרָהּ לָעוֹלָם."],[9,"","אָמַר לוֹ רַבִּי יֵיסָא, אִם כָּךְ, הֲרֵי אֶרֶץ יִשְׂרָאֵל שֶׁנִּמְחוּ הָרְשָׁעִים שֶׁהָיוּ בְּאוֹתוֹ זְמַן, אָז לָמָּה לֹא חָזְרָה הַשְּׁכִינָה לִמְקוֹמָהּ כְּבַתְּחִלָּה? אָמַר לוֹ, מִשּׁוּם שֶׁלֹּא נִשְׁאֲרוּ בָהּ שְׁאָר צַדִּיקֵי הָעוֹלָם, אֶלָּא (אבל) בְּכָל מָקוֹם שֶׁהָלְכוּ, יָרְדָה וְשָׂמָה אֶת מְדוֹרָהּ עִמָּהֶם. וּמָה בְּאֶרֶץ נָכְרִיָּה אַחֶרֶת לֹא נִפְרְדָה מֵהֶם - כָּל שֶׁכֵּן אִם נִשְׁאֲרוּ בָּאָרֶץ הַקְּדוֹשָׁה."]]],[["וְהָא אִתְּמָר. בְּכָל חוֹבִין דְּחַיָּיבֵי עָלְמָא דַּחְיָין לָהּ לַשְּׁכִינְתָּא. חַד מִנַּיְיהוּ מַאן דִּמְחַבֵּל אָרְחֵיהּ עַל אַרְעָא כִּדְאֲמָרָן. וּבְגִין כָּךְ לָא חָמֵי אַנְפֵּי שְׁכִינְתָּא וְלָא עָאל בְּפַלְטֵרִין. וְעַל דָּא כְּתִיב בְּאִלֵּין וַיִּמָּחוּ מִן הָאָרֶץ אִתְמָחוּן מִן כֹּלָּא.","תָּא חֲזֵי, בְּהַהוּא זִמְנָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַחְיָיאָה מֵתַיָיא, כָּל אִנּוּן מֵתִין דְּיִשְׁתַּכְּחוּן לְבַר בִּשְׁאָר אַרְעִין נוּכְרָאִין קוּדְשָׁא בְּרִיךְ הוּא יִבְרָא לוֹן גּוּפַיְיהוּ (נ\"א יוקים לון בגופייהו) כְּדְקָא חָזֵי. דְּהָא גַּרְמָא חַד דְּאִשְׁתָּאַר בֵּיהּ בְּבַר נָשׁ תְּחוֹת אַרְעָא הַהוּא גַרְמָא יִתְעֲבִיד כְּחֲמִירָא בְּעִיסָה וְעֲלֵיהּ יִבְנֵי קוּדְשָׁא בְּרִיךְ הוּא כָּל גּוּפָא.","וְלָא יָהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתִין אֶלָּא בְּאַרְעָא דְיִשְׂרָאֵל. דִּכְתִיב, (יחזקאל ל״ז:י״ב) הִנֵּה אֲנִי פּוֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. דְּיִתְגַּלְגְּלוּן תְּחוֹת אַרְעָא. וּלְבָתַר מַה כְּתִיב וְנָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם וְגו'. דְּהָא בְּאַרְעָא דְיִשְׂרָאֵל יְקַבְּלוּן נִשְׁמָתִין כָּל (אנון) בְּנֵי עָלְמָא. בַּר אִלֵּין (דרא דטופנא) דְּאִסְתָּאֲבוּ וּסְאִיבוּ אַרְעָא. בְּאִלֵּין כְּתִיב וַיִּמָּחוּ מִן הָאָרֶץ. מִן הָאָרֶץ דַּיְיקָא. וְאַף עַל גַּב דְּאַקְשׁוּ וְאַפְלִיגוּ קַדְמָאֵי עַל דָּא. וַיִּמָּחוּ כְּמָא דְאַתְּ אָמֵר, (תהילים ס״ט:כ״ט) יִמָּחוּ מִסֵּפֶר חַיִים.","אָמַר לֵיהּ רַבִּי שִׁמְעוֹן וַדַּאי לֵית לוֹן חוּלָקָא בְּעָלְמָא דְאָתֵי דִּכְתִיב וַיִּמָּחוּ מִן הָאָרֶץ. וּכְתִיב לְעוֹלָם יִירְשׁוּ אָרֶץ. אֲבָל יְקוּמוּן בְּדִין. וְעֲלַיְיהוּ כְּתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנִי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדֵרָאוֹן עוֹלָם. וּפְלוּגְתָּא בְּהָא אֲבָל כֹּלָּא כְּמָה דְאוּקְמוּהָ חַבְרַיָיא:","וַיִּמַּח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. רַבִּי אַבָּא אָמַר (את כל) לְאַכְלָלָא כָּל אִנּוּן שַׁלִּיטִין דְּשָׁלְטִין מְמַנָּן עַל אַרְעָא. וְדָא הוּא הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. דְּכַד עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בִּבְנֵי עָלְמָא אַעֲבַר לְאִנּוּן שַׁלִּיטִין דִּמְמַנָּן עֲלַיְיהוּ בְּקַדְמִיתָא וּלְבָתַר לְאִנּוּן דְּיַתְבֵי תְּחוֹת גַּדְפַיְיהוּ דִּכְתִיב (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וּלְבָתַר עַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.","וְהֵיךָ מִתְעַבְרָן קַמֵּיהּ. אֶלָּא אַעֲבַר לוֹן בְּנוּרָא דְּדָלִיק הֲדָא הוּא דִכְתִיב, (דברים ד׳:כ״ד) כִּי ה' אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא אֵל קַנָּא. אֶשָׁא (הוא) דְּאָכִיל אֶשָׁא. הַהוּא יָקוּם דְּעֲלַיְיהוּ (נ\"א מעבר) בְּאֶשָׁא. וְאִנּוּן דְּיַתְבֵי תְּחוֹתַיְיהוּ בְּמַיָא. וּבְגִינֵי כָּךְ וַיִּמַּח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנִי הָאֲדָמָה. וּלְבָתַר מֵאָדָם וְעַד בְּהֵמָה עַד רֶמֶשׂ וְעַד עוֹף הַשָּׁמַיִם וַיִּמָּחוּ מִן הָאָרֶץ. כָּל אִלֵּין דִּלְתַתָּא. וַיִּשָּׁאֶר אַךְ נֹחַ. אַךְ לִמְעוּטֵי. דְּלָא אִשְׁתָּאֲרוּ בְּעָלְמָא בַּר נֹחַ וּדְעִמֵּיהּ בְּתֵיבוּתָא. רַבִּי יוֹסֵי אוֹמֵר חֲגִיר הֲוָה דְּאָכִישׁ לֵיהּ אַרְיָא וְהָא אוּקְמוּהָ:","וַיִּזְכֹּר אֱלהִים אֶת נֹחַ וְאֶת כָּל הַחַיָּה וְאֶת כָּל הַבְּהֵמָה אֲשֶׁר אִתּוֹ בַּתֵּבָה. רַבִּי חִיָּיא פָּתַח (משלי כ״ב:ג׳) עָרוּם רָאָה רָעָה וְנִסְתָּר. הַאי קְרָא אִתְּמָר עַל נֹחַ דְּעָאל לְתֵיבוּתָא וְאִסְתַּתַּר בָּהּ. וְעָאל לְגוֹ תֵיבוּתָא בְּזִמְנָא דְמַיָּיא דָּחֲקוּ לֵיהּ. וְהָא אִתְּמָר דְּעַד לָא עָאל לְתֵיבוּתָא חָמָא לֵיהּ לְמַלְאַךְ הַמָּוֶת דְּאָזִיל בֵּינַיְיהוּ וְאַסְחַר לוֹן. כֵּיוָן דְּחָמָא לֵיהּ, עָאל לַתֵּבָה וְאִסְתַּתַּר בְּגַוָּהּ. הֲדָא הוּא דִכְתִיב עָרוּם רָאָה רָעָה וְנִסְתָּר. רָאָה רָעָה דָּא מַלְאַךְ הַמָּוֶת וְנִסְתָּר מִקַּמֵּיהּ הֲדָא הוּא דִכְתִיב מִפְּנֵי מֵי הַמַּבּוּל.","רַבִּי יוֹסֵי אָמַר עָרוּם רָאָה רָעָה וְנִסְתָּר. (ויסתר לא כתיב), אַהֲדַר עַל מַה דְּאִתְּמָר בְּזִמְנָא דְּמוֹתָא שַׁרְיָא בְּעָלְמָא בַּר נָשׁ חַכִּים יִסָּתֵר וְלָא יָקוּם לְבַר וְלָא יִתְחֲזֵי קַמֵּי מְחַבְּלָא. בְּגִין דְּכֵיוָן דְּאִתְיְיהִיב לֵיהּ רְשׁוּ, יְחַבֵּל כָּל אִנּוּן דְּיִשְׁתַּכְּחוּן קַמֵּיהּ וְיַעַבְרוּן קַמֵּיהּ בְּאִתְגַלְיָיא. וְסוֹפָא דִקְרָא וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ עָבְרִין קַמֵּיהּ וְאִתְחַזְיָין קַמֵּיהּ וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָבְרוּ, עָבְרוּ פִּקּוּדָא (דא) (נ\"א דמאריהון) וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָרוּם רָאָה רָעָה וְנִסְתָּר דָּא נֹחַ. וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ אִלֵּין בְּנֵי דָרֵיהּ."],[[0,"והא אתמר, בכל חובין וכו':","והנה נתבאר, שבכל החטאים של רשעי עולם המה דוחים את השכינה. ואחר מהם הוא מי שמשחית דרכו על הארץ, כמו שאמרנו, ומשום זה, אינו רואה את פני השכינה ולא יכנס בהיכל המלך. ועל כן כתוב בהם, וימחו מן הארץ שנמחו מן הכל."],[1,"ת\"ח בההוא זמנא וכו':","בוא וראה. בעת ההוא, שעתיד הקב\"ה להחיות המתים, כל אלו המתים שימצאו לחוץ, מהארץ, בשאר ארצות הנכריות, הקב\"ה יעמיד אותם בגופם כראוי, כי עצם אחד נשאר בו בהאדם מתחת הארץ, עצם הזה יעשה כשאור בעיסה, ועליו יבנה הקב\"ה כל הגוף."],[2,"ולא יהיב וכו'","ולא יתן להם הקב\"ה נשמות, רק בארץ ישראל. שכתוב, הנה, אני פותח את קברותיכם וגו', כי יתגלגלו מתחת הארץ. ויבואו לארץ ישראל ואחר זה מה כתוב, ונתתי רוחי בכם וחייתם וגו'. כי בארץ ישראל יקבלו נשמות כל בני העולם. חוץ מאלו שנטמאו וטמאו הארץ, דהיינו דור המבול, באלו כתיב, וימחו מן הארץ. מן הארץ הוא בדיוק. דהיינו שלא יקומו בתחיית המתים, ולא יבואו לארץ לקבל נשמות. ואע\"פ שהקשו הראשונים וחלקו על זה, ואמרו שיקומו בתחיית המתים. מ\"מ הוא כמו שאמרנו, כי \u0003וימחו,\u0004 הוא כמו שאתה אומר ימחו מספר חיים. שלא יקומו לתחיה."],[3,"א\"ל רבי שמעון וכו':","א\"ל ר\"ש, ודאי שאין להם לדור המבול חלק לעולם הבא, שכתוב. וימחו מן הארץ וכתוב לעולם ירשו ארץ ויליף גזרה שוה. אבל יקומו לתחיה כדי לעמוד בדין, ועליהם כתוב, ורבים מישני אדמת עפר יקוצו וגו'. ויש מחלוקת בזה, אבל הכל הוא כמו שבארוה החברים."],[4,"וימח את כל היקום וכו':","רבי אבא אמר, הכתוב, בא לרבות כל אלו השליטים ששולטים וממונים על הארץ, דהיינו המלאכים שהם ממונים על עמי הארץ. שגם הם נמחו. וזהו, את כל היקום אשר על פני האדמה. כי כאשר הקב\"ה עושה דין בבני העולם מעביר בתחילה להממונים השולטים עליהם, ואח\"כ לבני העולם היושבים תחת כנפי חסותם. שכתוב, יפקוד ה' על צבא מרום במרום, ואח\"כ, על מלכי האדמה על האדמה."],[5,"והיך מתעברן וכו':","ואיך נעברים לפניו הממונים. הוקשה לו, כיון שאין מיתה נוהג בהם איך הוא מעבירם. ואומר, אלא שמעביר אותם באש שורף, וז\"ש, כי ה' אלקיך אש אכלה הוא וגו'. את היקום שעליהם, שהם הממונים של מעלה העבירם באש. ואותם הנמצאים תחתיהם, שהם בני העולם, מחה אותם במים. וע\"כ כתוב מתחילה וימח את כל היקום וגו'. ואחר כך, מאדם ועד בהמה וגו'. וישאר אך נח, \u0003אך\u0004 הוא למעט שלא נשאר בכל העולם רק נח ושעמו בהתיבה, ר' יוסי אומר, \u0003אך\u0004 בא למעט את נח גופיה, שנעשה פסח, שהכה אותו אריה, וכבר בארוה."],[6,"ויזכור אלקים את נח וגו':","רבי חייא פתח, ערום ראה רעה ונסתר. מקרא זה נאמר על נח שנכנס אל התיבה ונסתר בה. ונכנס אל התיבה בעת שהמים דחקו אותו. וכבר נתבאר, שמטרם שנכנס בהתיבה ראה את מלאך המות הולך ביניהם ומקיף אותם, כיון שראה אותו, נכנס להתיבה ונסתר בה. וז\"ש ערום ראה רעה ונסתר. \u0003ראה רעה,\u0004 זה מלאך המות. ונסתר מפניו, וז\"ש מפני מי המבול. דהיינו מפני מלאך המות שראה במי המבול."],[7,"רבי יוסי אמר וכו':","רי\"א, ערום ראה רעה ונסתר, סובב על מה שאמרו, בזמן שמות שורה בעולם, איש חכם יסתר ולא יעמוד בחוץ, ולא יתראה לפני המשחית, משום שמאחר שניתן לו רשות להמשחית הוא ישחית כל אלו שימצאו לפניו ושיעברו בגלוי לפניו. וזה הוא סוף המקרא, ופתאים עברו ונענשו, שהם עוברים לפניו ונראים לפניו, ונענשו, דבר אחר, \u0003עברו,\u0004 פירושו שעברו של מצות רבונם ונענשו. \u0003ד\"א ערום ראה רעה ונסתר:\u0004 זהו נח ופתאים עברו ונענשו אלו הם בני דורו."]],[[0,"","וַהֲרֵי אָמַרְנוּ. בְּכָל הַחֲטָאִים שֶׁל רִשְׁעֵי הָעוֹלָם, דּוֹחִים אֶת הַשְּׁכִינָה. אֶחָד מֵהֶם מִי שֶׁמַּשְׁחִית דַּרְכּוֹ עַל הָאָרֶץ, כְּמוֹ שֶׁאָמַרְנוּ, וְלָכֵן לֹא רוֹאֶה פְּנֵי שְׁכִינָה וְלֹא נִכְנָס לַפַּלְטֵרִין. וְעַל זֶה כָּתוּב עַל אֵלֶּה וַיִּמָּחוּ מִן הָאָרֶץ, שֶׁנִּמְחוּ מֵהַכֹּל."],[1,"","בֹּא רְאֵה, בְּאוֹתוֹ הַזְּמַן שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, כָּל אוֹתָם מֵתִים שֶׁיִּמָּצְאוּ בַחוּץ בִּשְׁאָר אֲרָצוֹת נָכְרִיּוֹת, הַקָּדוֹשׁ בָּרוּךְ הוּא יִבְרָא לָהֶם גּוּפֵיהֶם (נ\"א: יעמידם בגופם) כָּרָאוּי. שֶׁהֲרֵי עֶצֶם אַחַת שֶׁנִּשְׁאֶרֶת בָּאָדָם תַּחַת הָאָרֶץ, אוֹתָהּ עֶצֶם תֵּעָשֶׂה כַּשְּׂאוֹר שֶׁבָּעִסָּה, וְעָלֶיהָ יִבְנֶה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל הַגּוּף."],[2,"","וְלֹא יִתֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לָהֶם נְשָׁמוֹת אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל, שֶׁכָּתוּב (יחזקאל לז) הִנֵּה אֲנִי פֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. שֶׁיִּתְגַּלְגְּלוּ תַּחַת הָאָרֶץ. וְאַחַר כָּךְ מַה כָּתוּב? וְנָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם וְגוֹ', שֶׁהֲרֵי בְּאֶרֶץ יִשְׂרָאֵל יְקַבְּלוּ נְשָׁמוֹת כָּל אוֹתָם בְּנֵי הָעוֹלָם, פְּרָט לְאֵלּוּ (דור המבול) שֶׁנִּטְמְאוּ וְטִמְּאוּ אֶת הָאָרֶץ. בְּאֵלֶּה כָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ, דַּוְקָא מִן הָאָרֶץ. וְאַף עַל גַּב שֶׁהִקְשׁוּ וְנֶחְלְקוּ הָרִאשׁוֹנִים עַל זֶה. וַיִּמָּחוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סט) יִמָּחוּ מִסֵּפֶר חַיִּים."],[3,"","אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁאֵין לָהֶם חֵלֶק בָּעוֹלָם הַבָּא, שֶׁכָּתוּב וַיִּמָּחוּ מִן הָאָרֶץ, וְכָתוּב לְעוֹלָם יִירְשׁוּ אָרֶץ. אֲבָל יָקוּמוּ בְדִין. וַעֲלֵיהֶם כָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת לְדִרְאוֹן עוֹלָם. וְהַמַּחֲלֹקֶת בָּזֶה. אֲבָל הַכֹּל כְּפִי שֶׁבֵּאֲרוּהָ הַחֲבֵרִים."],[4,"","וַיִּמַח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. רַבִּי אַבָּא אָמַר, (את כל) - לִכְלֹל כָּל אוֹתָם שַׁלִּיטִים שֶׁשּׁוֹלְטִים הַמְמֻנִּים עַל הָאָרֶץ, וְזֶהוּ הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. שֶׁכַּאֲשֶׁר עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בִּבְנֵי הָעוֹלָם, מַעֲבִיר אֶת אוֹתָם הַשַּׁלִּיטִים הַמְמֻנִּים עֲלֵיהֶם בַּהַתְחָלָה, וְאַחַר כָּךְ אֶת אוֹתָם שֶׁיּוֹשְׁבִים תַּחַת כַּנְפֵיהֶם, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם, וְאַחַר כָּךְ - עַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה."],[5,"","וְאֵיךָ מָעֳבָרִים מִלְּפָנָיו? אֶלָּא מַעֲבִיר אוֹתָם בְּאֵשׁ שֶׁדּוֹלֶקֶת. זֶהוּ שֶׁכָּתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא אֵל קַנָּא. אֵשׁ (הוא) שֶׁאוֹכֶלֶת אֵשׁ. אוֹתוֹ שֶׁעוֹמֵד מֵעֲלֵיהֶם (נ\"א: עובר) בְּאֵשׁ. וְאוֹתָם שֶׁיּוֹשְׁבִים תַּחְתֵּיהֶם בְּמַיִם. וּמִשּׁוּם כָּךְ וַיִּמַח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה, וְאַחַר כָּךְ מֵאָדָם וְעַד בְּהֵמָה עַד רֶמֶשׂ וְעַד עוֹף הַשָּׁמַיִם וַיִּמָּחוּ מִן הָאָרֶץ, כָּל אֵלּוּ שֶׁלְּמַטָּה. וַיִּשָּׁאֵר אַךְ נֹחַ - אַךְ לְמַעֵט. שֶׁלֹּא נִשְׁאֲרוּ בָּעוֹלָם רַק נֹחַ וּמִי שֶׁעִמּוֹ בַּתֵּבָה. רַבִּי יוֹסֵי אָמַר, שֶׁהָיָה חִגֵּר, שֶׁהִכִּישׁוֹ אַרְיֵה, וַהֲרֵי פֵּרְשׁוּהָ."],[6,"","וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ וְאֶת כָּל הַחַיָּה וְאֶת כָּל הַבְּהֵמָה אֲשֶׁר אִתּוֹ בַּתֵּבָה. רַבִּי חִיָּיא פָּתַח, (משלי כב) עָרוּם רָעָה רָעָה וְנִסְתָּר. פָּסוּק זֶה נֶאֱמַר עַל נֹחַ שֶׁנִּכְנַס לַתֵּבָה וְהִסְתַּתֵּר בָּהּ, וְנִכְנַס לְתוֹךְ הַתֵּבָה בִּזְמַן שֶׁהַמַּיִם דָּחֲקוּ אוֹתוֹ. וַהֲרֵי נֶאֱמַר שֶׁעַד שֶׁלֹּא נִכְנַס לַתֵּבָה, רָאָה אֶת מַלְאַךְ הַמָּוֶת שֶׁהוֹלֵךְ בֵּינֵיהֶם וּמַקִּיף אוֹתָם. כֵּיוָן שֶׁרָאָה אוֹתוֹ, נִכְנַס לַתֵּבָה וְהִסְתַּתֵּר בְּתוֹכָהּ. זֶהוּ שֶׁכָּתוּב עָרוּם רָאָה רָעָה וְנִסְתָּר. רָאָה רָעָה - זֶהוּ מַלְאַךְ הַמָּוֶת, וְנִסְתַּר מִלְּפָנָיו. זֶהוּ שֶׁכָּתוּב מִפְּנֵי מֵי הַמַּבּוּל."],[7,"","רַבִּי יוֹסֵי אָמַר, עָרוּם רָאָה רָעָה וְנִסְתָּר, (לא כתוב ויסתר) חָזַר עַל מַה שֶּׁנֶּאֱמַר, בִּזְמַן שֶׁהַמָּוֶת שָׁרוּי בָּעוֹלָם, בֶּן אָדָם חָכָם יִסְתַּתֵּר וְלֹא יַעֲמֹד בַּחוּץ וְלֹא יִתְרָאֶה לִפְנֵי הַמַּשְׁחִית, מִשּׁוּם שֶׁכֵּיוָן שֶׁנִּתְּנָה לוֹ הָרְשׁוּת, הוּא יַשְׁחִית אֶת כָּל אוֹתָם שֶׁנִּמְצָאִים לְפָנָיו וְעוֹבְרִים לְפָנָיו גָּלוּי. וְסוֹף הַפָּסוּק - וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ. עָבְרוּ לְפָנָיו וְהִתְרָאוּ לְפָנָיו, וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָבְרוּ - עָבְרוּ עַל מִצְוָה זוֹ (נ\"א: של רבונם) וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָרוּם רָאָה רָעָה וְנִסְתָּר - זֶה נֹחַ. וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ - אֵלּוּ בְּנֵי דוֹרוֹ (ונענשו)."]]],[["(ונענשו), כֵּיוָן דְּאִסְתַּתַּר וְאִשְׁתָּהֵי תַּמָּן כָּל הַהוּא זִמְנָא. לְבָתַר וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ. אָמַר רַבִּי שִׁמְעוֹן (ויזכור אלהים את נח) תָּא חֲזֵי בְּשַׁעֲתָא דְּדִינָא אִתְעֲבִיד לָא כְּתִיב בֵּיהּ זְכִירָה. כֵּיוָן דְּאִתְעֲבִיד (ביה) דִּינָא וְאִתְאֲבִידוּ חַיָּיבֵי עָלְמָא, כְּדֵין כְּתִיב בֵּיהּ זְכִירָה. דְּהָא כַּד דִּינָא שַׁרְיָא בְּעָלְמָא אִתְחַבְּרוּתָא לָא אִשְׁתְּכַח. וּמְחַבְּלָא שַׁרְיָא עַל עָלְמָא.","כֵּיוָן דְּאִתְעֲבַר דִּינָא וְאִשְׁתַּכִּיךְ רוּגְזָא, תָּב כֹּלָּא לְאַתְרֵיהּ. וּבְגִין כָּךְ כְּתִיב הָכָא וַיִּזְכֹּר אֱלהִים אֶת נֹחַ. דְּבֵיהּ שַׁרְיָא זָכוֹר. דְּנֹחַ אִישׁ צַדִּיק כְּתִיב בֵּיהּ.","כְּתִיב, (תהילים פ״ט:י׳) אַתָּה מוֹשֵׁל בְּגֵאוּת הַיָּם בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. בְּשַׁעֲתָא דְּיַמָּא קָפִיץ בְּגַלְגּוּלֵי וּתְהוֹמֵי סָלְקֵי וְנָחֲתֵי, קוּדְשָׁא בְּרִיךְ הוּא שָׁדַר חַד חוּטָא מִסִּטְרָא דְּיָמִינָא וּמָשִׁיךְ גַּלְגְּלוֹי וְשָׁכִיךְ זַעְפֵּיהּ וְלֵית מַאן דְּיָדַע לֵיהּ.","יוֹנָה נָחַת לְיַמָּא וְאִזְדַּמַּן לֵיהּ הַהוּא נוּנָא וּבָלַע לֵיהּ. הֵיךְ לָא נָפְקַת נִשְׁמְתֵיהּ מִנֵּיהּ וְלָא פָּרְחָא מִיָּד. אֶלָא בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט בְּהַהוּא גֵּאוּתָא דְיַמָּא.","וְהַהוּא גֵּאוּתָא דְיַמָּא הוּא חַד חוּטָא דִּשְׂמָאלָא דְּסָלִיק לֵיהּ לְיַמָּא לְעֵילָא וּבֵיהּ אִסְתַּלַּק. וְאִי לָאו הַהוּא חוּטָא דְּמָטֵי לֵיהּ מִסִּטְרָא דְּיָמִינָא לָא סָלְקָא לְעָלְמִין. דְכַד (דכיון) דְּהַהוּא חוּטָא נָחִית לְיַמָּא וְיַמָּא אִתְאַחִיד בָּהּ כְּדֵין אִתְעָרִין גַּלְגְּלוֹי וְשַׁאֲגָן לְמִטְרַף טַרְפָּא. עַד דְּקוּדְשָׁא בְּרִיךְ הוּא אָתִיב לֵיהּ (לון) לְאֲחוֹרָא וְתָבִין לְאַתְרַיְיהוּ.","הֲדָא הוּא דִכְתִיב בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. תְּשַׁבְּחֵם לְאִנּוּן גַּלֵּי יַמָּא. תְּשַׁבְּחֵם תְּתַבַּר לוֹן לְאֲתָבָא לְאַתְרַיְיהוּ. דָּבָר אַחֵר תְּשַׁבְּחֵם מַמָּשׁ שְׁבָחָא הוּא לוֹן בְּגִין דְּסָלְקִין בְּתִיאוּבְתָּא לְמֶחמֵי. מִכָּאן כָּל מָאן דְּכָסִיף לְאִסְתַּכָּלָא וּלְמִנְדַע אַף עַל גַּב דְּלָא יָכִיל (נ\"א ולא יהבין ליה רשותא) שְׁבָחָא אִיהוּ דִילֵיהּ וְכֹלָּא מְשַׁבְּחָן לֵיהּ.","אָמַר רַבִּי יְהוּדָה נֹחַ כַּד הֲוָה בַּתֵּיבָה דָּחִיל הֲוָה דְּלָא יִדְכַּר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין. וְכֵיוָן דְּאִתְעֲבִיד דִּינָא וְאִתְעֲבָרוּ חַיָּיבֵי עָלְמָא כְּדֵין מַה כְּתִיב וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ.","רַבִּי אֶלְעָזָר אָמַרתָּא חֲזֵי, בְּשַׁעֲתָא דְדִינָא שַׁרְיָא בְּעָלְמָא לָא לִיבָּעֵי לֵיהּ לְאֵינִישׁ דְּיִדְכַּר שְׁמֵיהּ לְעֵילָא (קמיה דקודשא בריך הוא בעלמא). דְּהָא אִי אַדְכַּר שְׁמֵיהּ יִדְכְּרוּן חוֹבוֹי (כלהו) וְיֵיתוּן לְאַשְׁגָּחָא בֵּיהּ.","מְנָלָן מִשּׁוּנַמִּית, דְּהַהוּא יוֹמָא יוֹם טוֹב דְּרֹאשׁ הַשָּׁנָה הֲוָה וְקוּדְשָׁא בְּרִיךְ הוּא דָּאִין עָלְמָא. וּכְדֵין אָמַר לֵיהּ אֱלִישָׁע (מלכים ב ד׳:י״ג) הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ דָּא קוּדְשָׁא בְּרִיךְ הוּא. דִּכְדֵין אִקְרֵי מֶלֶךְ. מֶלֶךְ הַקָּדוֹשׁ מֶלֶךְ הַמִּשְׁפָּט. וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשָׁבֶת. לָא בָּעֵינָא דְּיִדְכְּרוּן לִי וְיִשְׁגְּחוּן בִּי אֶלָּא בְּתוֹךְ עַמִי. מַאן דְּעֲיִּיל רֵישֵׁיהּ בֵּין עַמָּא (כלא) לָא יִשְׁגְּחוּן עֲלֵיהּ לְמֵידַן לֵיהּ לְבִישׁ. בְּגִינֵי כָךְ אָמְרָה בְּתוֹךְ עַמִּי.","תָּא חֲזֵי, נֹחַ בְּשַׁעֲתָא דְרוּגְזָא שַׁרְיָא בְּעָלְמָא לָא אִדְכַּר. כֵּיוָן דְּדִינָא אִתְעֲבָר מַה כְּתִיב וַיִּזְכֹּר אֱלהִים אֶת נֹחַ הַשְׁתָּא אִדְכַּר שְׁמֵיהּ. דָּבָר אַחֵר וַיִּזְכֹּר אֱלהִים אֶת נֹחַ כְּמָה דְּאַתְּ אָמֵר וָאֶזְכֹּר אֶת בְּרִיתִי.","רַבִּי חִזְקִיָּה הֲוָה אָזִיל מִקַּפּוֹטְקִיָּא לְלוּד. פָּגַע בֵּיהּ רַבִּי יֵיסָא. אָמַר לֵיהּ תְּוַוהְנָא עֲלָךְ דְּאַתְּ בִּלְחוֹדָךְ. דְּהָא תָּנִינָן דְּלָא יִפּוּק בַּר נָשׁ יְחִידָאי בְּאָרְחָא. אָמַר לֵיהּ רַבְיָא חַד אָזִיל בַּהֲדָאי וְאִיהוּ אָתֵי אֲבַתְרָאי. אָמַר לֵיהּ וְעַל דָּא תְּוַוהְנָא אֵיךְ אָזִיל בַּהֲדָךְ מַאן דְּלָא תִשְׁתָּעֵי בֵּיהּ מִלֵּי דְאוֹרַיְיתָא. דְּהָא תָּנִינָן כָּל מַאן דְּאָזִיל בְּאָרְחָא וְלָאו עִמֵּיהּ מִלֵּי דְאוֹרַיְיתָא אִסְתַּכַּן בְּנַפְשֵׁיהּ. אָמַר לֵיהּ הָכִי הוּא וַדַּאי.","אַדְהָכִי מָטָא הַהוּא רַבְיָא. אָמַר לֵיהּ רַבִּי יֵיסָא בְּרִי מֵאָן אֲתַר אַנְתְּ. אָמַר לֵיהּ מִקַּרְתָּא דְלוּד וְשָׁמַעְנָא דְּהַאי בַּר נָשׁ חַכִּים אָזִיל תַּמָּן וְזַמִּינָא גַרְמָאי לְפוּלְחָנִיהּ וּלְמֵיהַךְ בַּהֲדֵיהּ.","אָמַר לֵיהּ בְּרִי יְדַעְתְּ מִלֵּי דְאוֹרַיְיתָא. אָמַר לֵיהּ יְדַעְנָא דְּהָא אַבָּא הֲוָה אוֹלִיף לִי בְּפָרָשַׁת קָרְבָּנוֹת וְאַרְכִינָא אוּדְנָאי לְמַאי דְּהֲוָה אָמַר עִם אָחִי דְּאִיהוּ קְשִׁישָׁא מִנָּאי. אָמַר לֵיהּ רַבִּי יֵיסָא בְּרִי אֵימָא לִי.","פָּתַח וְאָמַר וַיִּבֶן נֹחַ מִזְבֵּחַ לַיְיָ וַיִּקַּח מִכָּל הַבְּהֵמָה הַטְּהוֹרָה וּמִכָּל הָעוֹף הַטָּהוֹר וַיַּעַל עוֹלוֹת בַּמִּזְבֵּחַ. וַיִּבֶן נֹחַ מִזְבֵּחַ, דָּא אִיהוּ מִזְבֵּחַ דְּאַקְרִיב בֵּיהּ אָדָם קַדְמָאָה. נֹחַ אַמַּאי קָרִיב עוֹלָה. דְּהָא עוֹלָה לָא סַלְקָא אֶלָּא בְּגִין הִרְהוּרָא דְלִבָּא (דרעותא) וְנֹחַ בְּמָּה חָב. אֶלָּא נֹחַ הִרְהֵר וְאָמַר הָא קוּדְשָׁא בְּרִיךְ הוּא גָּזַר דִּינָא עַל עָלְמָא דְּיִתְחָרַב, דִּילְמָא בְּגִין דְּשֵׁזִיב לִי כָּל זְכוּתָא פָּקַע לִי וְלָא יִשְׁתָּאַר לִי זְכוּ בְּעָלְמָא. מִיָּד וַיִּבֶן נֹחַ מִזְבֵּחַ לַיְיָ."],[[0,") כיון דאסתתר וכו':","כיון שנסתתר בהתבה ונתעכב שם כל אותו הזמן, אחר כך, ויזכור אלקים את נח. אמר ר\"ש, בוא וראה. בשעה שהדין נעשה, לא כתוב בו זכירה, כיון שנעשה הדין ורשעי העולם נאבדו, אז כתוב בו זכירה והוא מטעם, כי בעת שהדין שורה בהעולם, זווג העליון אינו נמצא, והמשחית שורה בהעולם, וע\"כ אין זכירה לטוב בעת ההוא כי זכירה פירושו זווג."],[1,"כיון דאתעבר דינא וכו':","ואחר שעבר הדין, והכעס נשתכך, שב הכל למקומו, שזווג העליון חוזר למקומו, והרחמים מושפעים להעולם. ומשום זה כתוב כאן \u0003ויזכור אלקים את נח.\u0004 כי בו, בנח, שורה השם \u0003זכור,\u0004 שפירושו זווג, כי נח איש צדיק כתוב בו. והוא כסא לזווג העליון. וכשחזר הזווג למקומו נמצא שזכר אלקים את נח."],[2,"כתיב אתה מושל בגאות הים וגו':","בשעה שהים קופץ בגליו, והתהומות עולים ויורדים, הקב\"ה שולח חוט אחד, של חסד מצד הימין, ומושך בחזרה את גלגליו, וכעסו שכך, ואין מי שישיג אותו. פירוש. כשהנוקבא מקבלת חכמה נקראת \u0003ים.\u0004 וענין התרוממות \u0003גלי הים,\u0004 הוא בעת, שהנוק' מקבלת מקו שמאל בלבד, שהיא שפע החכמה בלי חסדים. אז מתרוממים \u0003גלי הים,\u0004 שהוראתם לשון \u0003גילוי,\u0004 כי רומז שמימי החכמה עולים ומתגלים וניתנים להשגה. אמנם אין הים יכול לקבל חכמה בלי חסדים, וע\"כ \u0003הגלים\u0004 חוזרים ויורדים, כי עולים להתגלות, ומיד יורדים ונעלמים מהשגה מחוסר חסדים (כנ\"ל דף מ\"ו ד\"ה פירוש) ונבחן משום זה שהים זועף, דהיינו שמתאמץ להעלות מימיו בכח גדול, וכן חוזר ויורד בכח גדול. וחוזר חלילה בלי הפסק. וזה נמשך עד שבא קו אמצעי, וממשיך קו הימין שהוא חסד ומלביש החכמה שבשמאל בחסדים שבימין, ואז חוזרים הגלים למקומם וזעפו של הים נשקט, כי עתה מאירים החכמה והחסדים יחדיו בכל תקוניהם בשלימות הנרצה. (כנ\"ל דף מ\"ו ד\"ה ונתבאר ע\"ש),"],[2,"","וזה אמרו, \u0003בשעתא דימא קפיץ בגלגלוי\u0004 דהיינו שהנוקבא הנקראת \u0003ים\u0004 מקבלת מקו שמאל בלבדו, שאז קופץ הים עם גליו וזועף, \u0003ותהומי סלקי ונחתי\u0004 שעולים לקבל החכמה ותכף יורדים, כי לא יוכלו לקבל מחוסר חסדים, \u0003קב\"ה שדר חד חוטא מסטרא דימינא.\u0004 הקב\"ה, שה\"ס עמודא דאמצעיתא, מכריע וממשיך החסדים מקו ימין, והחכמה מתלבשת בהחסדים, ואז, \u0003ומשיך גלגלוי ושכיך זעפיה,\u0004 ומושך גלי הים בחזרה. כי מלבישם בחסדים, ונשקט כעסו, כי עתה מאירים בו המוחין בשלימות. אמנם מסבת הלבשת החכמה בחסדים נעלמות הג\"ר דחכסה, ורק הו\"ק דחכמה מאירה (כנ\"ל דף ל\"ו ד\"ה אזלו), וז\"ש על הג\"ר, \u0003ולית מאן דידע ליה,\u0004 שאין מי שישיג הג\"ר. כי נעלמו בסבת התלבשות בהחסדים."],[3,"יונה נחת וכו':","יונה ירד לים, ונזדמן לו אותו הדג ובלע אותו, שואל, איך לא יצאה נשמתו הימנו. ולא פרחה מיד הימנו, ומשיב, אלא משום שהקב\"ה מושל בגאות הים. פירוש \u0003גאות הים,\u0004 היינו הדינין הבאים מכח שליטת קו השמאל כמ\"ש לפנינו, ועכ\"ז נצל יונה מהם, הרי שהקב\"ה שה\"ס קו האמצעי שהוא רחמים שולט \u0003בגאות הים\u0004 ע\"י חוט של חסד ששולח מצד הימין, ומכריעהו, כנ\"ל בדיבור הסמוך, וע\"כ נשאר חי במעי הדג ונצל ממנו."],[4,"וההוא גאותא דימא וכו':","וגאות הים ההוא, הוא חוט אחד של השמאל, המעלה את גלי הים למעלה ובו הוא מתעלה אבל אם לא היה מגיע לו חוט ההוא. של חסד, מימין, לא היה מתעלה לעולם, כי כאשר חוט ההוא של שמאל, יורד להים, והים נאחז בו, אזי מתעוררים גליו ושואגים לטרוף טרף. כי אינם יכולים לקבל וליזון משפע החכמה מפני חסרון החסדים (כנ\"ל בדיבור הסמוך) וע\"כ נמצאים רעבים ושואגים לטרף, עד שהקב\"ה מחזיר הגלים לאחוריהם וחוזרים למקומם. דהיינו שממשיך החוט של חסד ומלביש החכמה בחסדים ואז הוא מושך גלי הים בחזרה. כנ\"ל בדיבור הסמוך. שבזה מתתקנת החכמה ויכולה להאיר בשלמות. הרי שלא יוכל הים להתעלות בהחכמה מקו שמאל מטרם שנמשך חוט של חסד שהחכמה מתלבשת בו, וז\"ש, \u0003וביה אסתלק.\u0004 אבל \u0003ואי לאו ההוא חוטא דמטי ליה מסטרא דימינא לא סלקא לעלמין.\u0004 דהיינו כמבואר."],[5,"הה\"ד בשוא גליו אתה תשבחם וכו':","היינו אתה תשבחם לגלי הים, תשבחם הוא כמו תשברם, כי משבר אותם להחזירם למקומם. שהוא ע\"י חוט של חסד כנ\"ל. דבר אחר. תשבחם ממש, כפשוטו, שהתרוממות הגלים הוא שבחם, משום שעולים לראות בתשוקה. מכאן כל החושב להסתכל ולדעת, אע\"פ שאינו יכול, נחשב לו לשבח וכולם משבחים אותו. פירוש, החכמה נקראת עינים, והארת החכמה נקראת ראיה. וענין התרוממות הגלים, הוא מכח הארת קו שמאל בחכמה בלי חסדים, שע\"כ אינם יכולים לראות דהיינו לקבל חכמה. כנ\"ל. ואומר, אע\"פ שאינם יכולים לראות, מ\"מ שבח נחשב להם, משום שהם רצים בתשוקה לראות."],[6,"אמר ר' יהודה וכו':","אר\"י, נח, בעת שהיה בהתיבה, היה מתירא אולי לא יזכור אותו הקב\"ה לעולם. ואחר שנעשה הדין ונעברו רשעי העולם, אז מה כתוב ויזכור אלקים את נח. וטעם הדבר אומר ר' אלעזר לפנינו."],[7,"ר' אלעזר אומר וכו'","רא\"א בוא וראה בשעה שהדין שורה בהעולם, לא ראוי לו לאדם שיהיה נזכר שמו למעלה. כי אם יהיה נזכר שמו יהיו נזכרים חטאיו, ויבואו להסתכל בו ולדון אותו."],[8,"מנלן משונמית וכו':","מאין לנו זה, הוא נשמע משונמית. כי יום ההוא יום טוב של ראש השנה היה, (כמ\"ש בזהר פנחס אות שנ\"א) והקב\"ה דן אז את העולם. ואז אמר לה אלישע היש לדבר לך אל המלך, זהו הקב\"ה שנקרא אז מלך, מלך הקדוש, מלך המשפט. ותאמר בתוך עמי אנכי יושבת. שאמרה, איני רוצה שיזכרו אותי ויסתכלו עלי, אלא \u0003בתוך עמי\u0004 כי מי שמכניס את ראשו בין העם, אין משגיחים עליו לדון אותו לרע, משום זה אמרה \u0003בתוך עמי.\u0004"],[9,"ת\"ח נח וכו'","בוא וראה, נח, בשעה שהרוגז היה שורה בהעולם, לא נזכר, כיון שעבר הדין, מה כתוב, ויזכור אלקים את נח. עתה נזכר שמו. דבר אחר, ויזכור אלקים את נח. הוא כמו שאתה אומר, ואזכור את בריתי. כלומר שגרם לזווג עליון, כנ\"ל באות רט\"ז"],[10,"ר' חזקיה וכו':","ר\"ח היה הולך מקפוטקיא ללוד. פגע בו רבי ייסא, אמר לו תמיהני עליך, שאתה הולך יחידי, שהרי למדנו, אל יצא אדם בדרך יחידי. אמר לו, תינוק אחד הולך עמי, והוא בא אחרי. אמר לו, ועל זה תמיהני, איך הולך עמך, מי שלא תדבר עמו בדברי תורה. שהרי למדנו כל מי שהולך בדרך ואין עמו דברי תורה, הוא מתחייב בנפשו, אמר לו, כן הוא ודאי."],[11,"אדהכי מטא וכו':","בינתים הגיע אותו התינוק, אמר לו רבי ייסא, בני, מאיזה מקום אתה, אמר לו מעיר לוד, ושמעתי, שאדם חכם הזה הולך שמה, זמנתי את עצמי לעבודתו, לשרתו, וללכת עמו."],[12,"אמר ליה ברי וכו':","אמר לו בני. יודע אתה דברי תורה, אמר לו יודע אני. כי אבי היה מלמדני בפרשת קרבנות, והטיתי אזני למה שהיה לומד עם אחי הגדול ממני, אמר לו רבי ייסא, בני, אמור לי."],[13,"פתח ואמר ויבן וכו'","פתח ואמר, ויבן נח מזבח לה' ויקח וגו', ויבן נח מזבח זהו המזבח שהקריב עליו אדם הראשון. והקשה, נח, מפני מה הקריב עולה, הרי עולה אינו בא אלא בשביל לכפר על הרהורי הלב, ונח, במה חטא. והשיב, אלא נח הרהר ואמר, הנה הקב\"ה גזר דין על העולם שיחרב, אולי בשכר שהציל אותי יצאה בזה כל זכותי, ולא נשאר לי עוד זכות בעולם. מיד ויבן נח מזבח לה'. ומה שהקריב דוקא קרבן עולה מפרש לפנינו באות רל\"ב."]],[[0,"","כֵּיוָן שֶׁהִסְתַּתֵּר וְהִשְׁתַּהָה שָׁם כָּל אוֹתוֹ זְמַן, אַחַר כָּךְ וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ. אָמַר רַבִּי שִׁמְעוֹן, (ויזכר אלהים את נח) בּא רְאֵה, בְּשָׁעָה שֶׁהַדִּין נַעֲשָׂה, לֹא כָתוּב בּוֹ זְכִירָה. כֵּיוָן שֶׁנַּעֲשָׂה (בו) הַדִּין וְנֶאֶבְדוּ רִשְׁעֵי הָעוֹלָם, אָז כָּתוּב בּוֹ זְכִירָה. שֶׁהֲרֵי כַּאֲשֶׁר הַדִּין שָׁרוּי בָּעוֹלָם, לֹא נִמְצֵאת הִתְחַבְּרוּת, וְהַמַּשְׁחִית שָׁרוּי עַל הָעוֹלָם."],[1,"","כֵּיוָן שֶׁעָבַר הַדִּין וְשָׁכַךְ הָרֹגֶז, שָׁב הַכֹּל לִמְקוֹמוֹ, וְלָכֵן כָּתוּב כָּאן וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, שֶׁבּוֹ שׁוֹרֶה זָכוֹר, שֶׁנֹּחַ אִישׁ צַדִּיק כָּתוּב בּוֹ."],[2,"","כָּתוּב (תהלים פט) אַתָּה מוֹשֵׁל בְּגֵאוּת הַיָּם בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. בְּשָׁעָה שֶׁהַיָּם קוֹפֵץ בְּגַלָּיו וְהַתְּהוֹמוֹת עוֹלִים וְיוֹרְדִים, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ חוּט אֶחָד מִצַּד הַיָּמִין וּמוֹשֵׁךְ אֶת גַּלָּיו וְשׁוֹכֵךְ זַעְפּוֹ, וְאֵין מִי שֶׁיּוֹדֵעַ אוֹתוֹ."],[3,"","יוֹנָה יָרַד לַיָּם וְהִזְדַּמֵּן לוֹ אוֹתוֹ הַדָּג וּבָלַע אוֹתוֹ, אֵיךְ לֹא יָצְאָה נִשְׁמָתוֹ מִמֶּנּוּ וְלֹא פָרְחָה מִיָּד? אֶלָּא מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט בְּאוֹתָהּ גֵּאוּת שֶׁל הַיָּם,"],[4,"","וְאוֹתָהּ גֵּאוּת הַיָּם הִיא חוּט אֶחָד שֶׁל הַשְּׂמֹאל שֶׁמַּעֲלֶה אֶת הַיָּם לְמַעְלָה, וּבוֹ הוּא מִתְעַלָּה. וְאִם לֹא אוֹתוֹ הַחוּט שֶׁמַּגִּיעַ אֵלָיו מִצַּד הַיָּמִין, לֹא יַעֲלֶה לְעוֹלָמִים. שֶׁכַּאֲשֶׁר (שכיון) שֶׁאוֹתוֹ הַחוּט יוֹרֵד לַיָּם, וְהַיָּם אוֹחֵז בּוֹ, אָז מִתְעוֹרְרִים הַגַּלִּים וְשׁוֹאֲגִים לִטְרֹף טֶרֶף, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵשִׁיב אוֹתוֹ (אותם) לְאָחוֹר וְשָׁבִים לִמְקוֹמָם."],[5,"","זְהִוּ שֶׁכָּתוּב בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. תְּשַׁבְּחֵם אֶת אוֹתָם גַּלֵּי הַיָּם. תְּשַׁבְּחֵם - תְּשַׁבֵּר אוֹתָם לַחֲזֹר לִמְקוֹמָם. דָּבָר אַחֵר, תְּשַׁבְּחֵם מַמָּשׁ. שֶׁבַח הוּא לָהֶם מִשּׁוּם שֶׁעוֹלִים לִרְאוֹת בְּהִשְׁתּוֹקְקוּת. מִכָּאן, כָּל מִי שֶׁנִּכְסָף לְהִסְתַּכֵּל וְלָדַעַת, אַף עַל גַּב שֶׁלֹּא יָכוֹל (נ\"א: ולא נותנים לו רשות) - הַשֶּׁבַח הוּא שֶׁלּוֹ, וְכֻלָּם מְשַׁבְּחִים אוֹתוֹ."],[6,"","אָמַר רַבִּי יְהוּדָה, נֹחַ, כְּשֶׁהָיָה בַּתֵּבָה, הָיָה פּוֹחֵד שֶׁלֹּא יִזְכֹּר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים. וְכֵיוָן שֶׁנַּעֲשֶׂה הַדִּין וְנֶעֶבְרוּ רִשְׁעֵי הָעוֹלָם, אָז מַה כָּתוּב? וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ."],[7,"","רַבִּי אֶלְעָזָר אָמַר, בּא רְאֵה, בְּשָׁעָה שֶׁהַדִּין שָׁרוּי בָּעוֹלָם, לֹא צָרִיךְ לָאָדָם שֶׁיִּזָּכֵר שְׁמוֹ לְמַעְלָה (לפני הקדוש ברוך הוא בעולם). שֶׁהֲרֵי אִם נִזְכָּר שְׁמוֹ, נִזְכָּרִים (כל) חֲטָאָיו וְיָבוֹאוּ לְהַשְׁגִּיחַ בּוֹ."],[8,"","מִנַּיִן לָנוּ? מִשּׁוּנַמִּית. שֶׁאוֹתוֹ הַיּוֹם הָיָה יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם, וְאָז אָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאָז נִקְרָא מֶלֶךְ. מֶלֶךְ הַקָּדוֹשׁ. מֶלֶךְ הַמִּשְׁפָּט. וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשָׁבֶת. אֵינִי רוֹצָה שֶׁיִּזְכְּרוּ אוֹתִי וְיַשְׁגִּיחוּ בִי, אֶלָּא בְּתוֹךְ עַמִּי. מִי שֶׁמַּכְנִיס רֹאשׁוֹ בֵּין הָעָם (כלו), לֹא יַשְׁגִּיחוּ עָלָיו לָדוּן אוֹתוֹ לְרַע. מִשּׁוּם כָּךְ אָמְרָה בְּתוֹךְ עַמִּי."],[9,"","בֹּא רְאֵה, נֹחַ, בְּשָׁעָה שֶׁהָרֹגֶז הָיָה שָׁרוּי בָּעוֹלָם, לֹא נִזְכַּר. כֵּיוָן שֶׁעָבַר הַדִּין, מַה כָּתוּב? וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ. עַכְשָׁו נִזְכַּר שְׁמוֹ. דָּבָר אַחֵר וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, כְּמוֹ שֶׁנֶּאֱמַר וָאֶזְכֹּר אֶת בְּרִיתִי."],[10,"","רַבִּי חִזְקִיָּה הָיָה הוֹלֵךְ מִקַּפּוֹטְקִיָּא לְלוֹד. פָּגַע בּוֹ רַבִּי יֵיסָא. אָמַר לוֹ, תְּמֵהַנִי עָלֶיךְ שֶׁאַתָּה לְבַד, שֶׁהֲרֵי שָׁנִינוּ שֶׁלֹּא יֵצֵא אָדָם יְחִידִי לַדֶּרֶךְ. אָמַר לוֹ, תִּינוֹק אֶחָד הָלַךְ עִמִּי, וְהוּא בָא אַחֲרַי. אָמַר לוֹ, וְעַל זֶה אֲנִי תָּמֵהַּ, אֵיךְ הוֹלֵךְ עִמְּךְ מִי שֶׁלֹּא תְדַבֵּר עִמּוֹ דִּבְרֵי תוֹרָה? שֶׁהֲרֵי שָׁנִינוּ, כָּל מִי שֶׁהוֹלֵךְ בַּדֶּרֶךְ וְאֵין עִמּוֹ דִּבְרֵי תוֹרָה, מִסְתַּכֵּן בְּנַפְשׁוֹ. אָמַר לוֹ, כָּךְ זֶה בְּוַדַּאי."],[11,"","בֵּינְתַיִם הִגִּיעַ אוֹתוֹ תִינוֹק. אָמַר לוֹ רַבִּי יֵיסָא, בְּנִי, מֵאֵיזֶה מָקוֹם אַתָּה? אָמַר לוֹ, מֵעִיר לוֹד, וְשָׁמַעְתִּי שֶׁהָאִישׁ הַזֶּה הֶחָכָם הוֹלֵךְ לְשָׁם, וְזִמַּנְתִּי עַצְמִי לַעֲבוֹדָתוֹ וְלָלֶכֶת עִמּוֹ. אָמַר לוֹ, בְּנִי, אַתָּה יוֹדֵעַ דִּבְרֵי תוֹרָה?"],[12,"","אָמַר לוֹ, אֲנִי יוֹדֵעַ, שֶׁהֲרֵי אָבִי לִמֵּד אוֹתִי בְּפָרָשַׁת קָרְבָּנוֹת, וְהִרְכַּנְתִּי אָזְנַי לְמַה שֶּׁהָיָה אוֹמֵר עִם אָחִי, שֶׁהוּא גָּדוֹל מִמֶּנִּי. אָמַר לוֹ רַבִּי יֵיסָא, בְּנִי, אֱמֹר לִי."],[13,"","פָּתַח וְאָמַר: וַיִּבֶן נֹחַ מִזְבֵּחַ לַה' וַיִּקַּח מִכֹּל הַבְּהֵמָה הַטְּהֹרָה וּמִכֹּל הָעוֹף הַטָּהוֹר וַיַּעַל עֹלֹת בַּמִּזְבֵּחַ. וַיִּבֶן נֹחַ מִזְבֵּחַ - זֶהוּ הַמִּזְבֵּחַ שֶׁהִקְרִיב בּוֹ אָדָם הָרִאשׁוֹן. לָמָּה נֹחַ הִקְרִיב עוֹלָה, שֶׁהֲרֵי עוֹלָה לֹא עוֹלָה אֶלָּא בִּשְׁבִיל הִרְהוּר וּרְצוֹן הַלֵּב, וְנֹחַ בַּמָּה חָטָא? אֶלָּא נֹחַ הִרְהֵר וְאָמַר: הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא גָּזַר דִּין עַל הָעוֹלָם שֶׁיֵּחָרֵב, אוּלַי מִשּׁוּם שֶׁמַּצִּיל אוֹתִי פָּקְעָה כָּל זְכוּתִי וְלֹא תִשָּׁאֵר לִי זְכוּת בָּעוֹלָם? מִיָּד - וַיִּבֶן נֹחַ מִזְבֵּחַ לַה'."]]],[["הַהוּא מִזְבֵּחַ דְּאַקְרִיב בֵּיהּ אָדָם הָרִאשׁוֹן הֲוָה. אִי הָכִי אַמַּאי וַיִּבֶן. אֶלָּא בְּגִין דְּחַיָּיבֵי עָלְמָא גָּרְמוּ דְּלָא קָיְימָא בְּדוּכְתֵּיהּ. כֵּיוָן דְּאָתָא נֹחַ כְּתִיב בֵּיהּ וַיִּבֶן.","וַיַּעַל עוֹלוֹת עֹלַת כְּתִיב חָדָא (הוא). כְּתִיב, (ויקרא א׳:י״ג) עוֹלָה הִוא אִשֵּׁה רֵיחַ נִיחֹחַ לַיְיָ (לעולם עולה סלקא דכר. אי) עוֹלָה סַלְקָא דְּכַר וְלָא סַלְקָא נוּקְבָא דִּכְתִיב זָכָר תָּמִים יַקְרִיבֶנּוּ. אַמַּאי כְּתִיב אִשֶּׁה דְּהָא אֵשׁ בָּעֵי לְאִשְׁתַּכְּחָא תַּמָּן.","אֶלָא אַף עַל גַּב דְּעוֹלָה אִתְקְרִיב דָּכָר. וּלְאַתְרֵיהּ אִתְקְרִיב. נוּקְבָא לָא בָּעְיָא לְאִתְפָּרְשָׁא מִנֵּיהּ, אֶלָּא בָּהּ אִתְקְרִיב בְּגִין לְחַבְּרָא דָּא בְּדָא. דְּסָלְקָא נוּקְבָא לְגַבֵּי דְכוּרָא לְאִתְחַבְּרָא כְּחֲדָא. וְאַף עַל גַּב דְּאִשֶּׁה לְשׁוּם אִישִׁים.","נֹחַ אִצְטְרִיךְ לֵיהּ לְמִקְרַב עוֹלָה. דְּאִיהוּ בְּאֲתַר דִּדְכוּרָא. עֲבַד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאִתְחַבְּרָא וּלְאַעֲלָאָה בַּתֵּיבָה. וְעַל דָּא אַקְרִיב עוֹלָה. עוֹלָה הוּא אִשֶּׁה. אֵשׁ ה' דְּאִתְחַבַּר (בה) שְׂמָאלָא בְּנוּקְבָא. דְּהָא (כל) נוּקְבָא מִסִּטְרָא דִשְׂמָאלָא קָא אַתְיָא וּדְכוּרָא מִסִטְרָא דִימִינָא בְּאִתְדַּבְּקוּתָא דָּא בְּדָא. וּבְגִין כָּךְ אִקְרֵי נוּקְבָא אִשֶּׁה. אִשֶּׁה קְטִירוּ דִּרְחִימוּ דְּאָחִיד בָּהּ שְׂמָאלָא לְסַלְקָא לָהּ לְעֵילָא וּלְאִתְקַשְּׁרָא כְּחֲדָא. וּבְגִין כָּךְ (ד\"א כתיב) עוֹלָה הִוא אִשֵּׁה. קְשִׁירוּ דִּדְכַר וְנוּקְבָא דָּא בְּדָא:","וַיָּרַח יְיָ אֶת רֵיחַ הַנִּיחֹחַ. וּכְתִיב אִשֶּׁה רֵיחַ נִיחוֹחַ. אִשֶּׁה הָכִי שְׁמַעְנָא תְּנָנָא וְאֶשָׁא מְחֻבָּרִין כְּחֲדָא. דְּהָא לֵית תְּנָנָא בְּלָא אֶשָׁא כְּמָה דִכְתִיב (שמות י״ט:י״ח) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו יְיָ בָּאֵשׁ.","תָּא חֲזֵי (נשא קלז, קלח) אֵשׁ נָפִיק מִלְּגָיו וְאִיהוּ דַּק. וְאָחִיד בְּמִלָּה אָחֳרָא לְבַר דְּלָאו אִיהוּ דַּק הָכִי וְאִתְאַחֲדָן דָּא בְּדָא וּכְדֵין תְּנָנָא סָלְקָא. מַאי טַעְמָא בְּגִין דְּאִתְאֲחִיד אֶשָׁא בְּמִלָּה דְּרָגִישׁ. וְסִימָנָיךְ חוּטְמָא דְּנָפִיק בֵּיהּ תְּנָנָא מִגּוֹ אֶשָׁא.","וְעַל דָּא כְּתִיב (דברים ל״ג:י׳) יָשִׂימוּ קְטוֹרָה בְּאַפֶּךָ. בְּגִין דְּאַהֲדַר אֶשָׁא לְאַתְרֵיהּ. וְחוֹטְמָא (אתרגיש) אִתְכְּנִישׁ בְּהַהוּא רֵיחָא לְגוֹ לְגוֹ עַד דְּאִתְאַחִיד כֹּלָּא וְתָב לְאַתְרֵיהּ. וְאִתְקְרִיב כֹּלָּא לְגוֹ מַחְשָׁבָה וְאִתְעֲבִיד רְעוּתָא חָדָא. וּכְדֵין רֵיחַ נִיחֹחַ. דְּנָח רוּגְזָא וְאִתְעֲבִיד נַיְיחָא.","דְּהָא תְּנָנָא אִתְכְּנִישׁ וְעֲיִּיל וְקָמִיט בְּאֶשָׁא וְאֶשָׁא אָחִיד בִּתְנָנָא וְעַיְילֵי תַּרְוַויְיהוּ לְגוֹ לְגוֹ עַד דְּנָח רוּגְזָא. וְכַד אִתְאֲחִיד (אחיד) כֹּלָא דָּא בְדָא וְנָח רוּגְזָא, כְּדֵין הוּא נַיְיחָא, וּקְשִׁירוּ חַד וְאִתְקְרֵי נַיְיחָא. נַיְיחָא דְרוּחָא חֶדְוָותָא דְּכֹלָּא כְּחֲדָא. נְהִירוּ דְּבוֹצִינִין נְהִירוּ דְּאַנְפִּין. וּבְגִין כָּךְ כְּתִיב, וַיָּרַח יְיָ אֶת רֵיחַ הַנִּיחֹחַ. כְּמַאן דְּאָרַח וְכָנִישׁ כֹּלָּא לְגוֹ אַתְרֵיהּ.","אַתָא רַבִּי יֵיסָא וּנְשָׁקֵיהּ. אָמַר וּמַה כָּל הָדֵין טָבָא אִית תְּחוֹת יְדָךְ וְלָא יְדַעְנָא בֵּיהּ. אָמַר אַהֲדַרְנָא מִן אוֹרְחָא, וְנִתְחַבֵּר בַּהֲדָךְ. אֲזְלוּ. אָמַר רַבִּי חִזְקִיָּה אָרְחָא דָא בַּהֲדֵי שְׁכִינְתָּא נְהַךְ דְּהָא מִתַקְנָא קַמָּן. אָחִיד בִּידָא דְּהַהוּא יְנוּקָא וְאֲזְלוּ. אָמְרוּ לֵיהּ אֵימָא לָן קְרָא חַד מֵאִנוּן דְּאָמַר לָךְ אֲבוּךְ.","פָּתַח הַהוּא יְנוּקָא וְאָמַר (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְשִׁיקוֹת פִּיהוּ, דָּא הוּא תְּאוֹבְתָּא עִלָּאָה דְּיִפּוּק (דנפקא) רְעוּתָא מִפּוּמָא לְנַשְׁקָא וְלָא נָפִיק מֵחוֹטְמָא כַּד אֶשָׁא נָפְקָא, דְּהָא כַּד אִתְחַבֵּר פּוּמָא לְנַשְׁקָא נָפִיק אֶשָׁא בִּרְעוּתָא בִּנְהִירוּ דְאַנְפִּין בְּחֶדְוָה דְּכֹלָא בְּאִתְדַּבְּקוּתָא דְנַיְיחָא.","וּבְגִין כָּךְ כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן. מֵהַהוּא יַיִן (יין) דְּמֶחדֵי וְנָהִיר אַנְפִּין וְחָיְיכִין עַיְינִין וְעָבִיד רְעוּתָא. וְלָאו מִיַּיִן דִּמְשַׁכֵּר (דשכיר) וְעָבִיד רוּגְזָא וְאַחְשִׁיךְ אַנְפִּין וְלָהֲטָאן עַיְינִין יַיִן דְּרוּגְזָא.","וְעַל דָּא בְּגִין דְּחֲמַר דָּא טַב, נָהִיר אַנְפִּין וְחָדֵי עַיְינִין וְעָבִיד תִּיאוּבְתָּא דִרְחִימוּ, מַקְרִיבִין לֵיהּ כָּל יוֹמָא עַל גַּבֵּי מַדְבְּחָא שִׁעוּרָא דְּמַאן דְּשָׁתֵי לֵיהּ חָדֵי לֵיהּ וְעָבִיד לֵיהּ נַיְיחָא דִכְתִיב (במדבר כ״ח:ה׳) וְנִסְכּוֹ יַיִן רְבִיעִית הַהִין. וּבְגִין כָּךְ כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן. מֵהַהוּא יַיִן דְּאִתְעַר רְחִימוּתָא וְתִיאוּבְתָּא."],[[0,"ההוא מזבח וכו':","מזבח זה, הוא שהקריב עליו אדם הראשון ושואל, אם כן מהו ויבן, הלא אדה\"ר בנהו, ומשיב אלא משום שרשעי העולם גרמו, שלא היה עומד במקומו, דהיינו, במקום ההשפעה לקדושה. כיון שבא נח להקריב עליו כתוב בו, \u0003ויבן.\u0004 כי החזירו למקום ההשפעה אל הקדושה."],[1,"ויעל עולות וכו':","כתוב עלת בלי ו' שהוא סימן הרבים. כי הקריב רק עולה אחד. כתוב, עולה הוא אשה וגו'. ומקשה הרי עולה הוא זכר ולא נקבה, שכתוב זכר תמים יקריבנו, ואם כן, למה כתוב \u0003אשה\u0004 עם ה' סופית, שהיא לשון נקבה הרי \u0003אש\u0004 בלי ה' סופית, היה צריך להמצא שמה שהוא לשון זכר."],[2,"אלא אע\"ג וכו':","ומתרץ. אלא אף על פי שעולה נקרב זכר, ולמקומו נקרב, דהיינו לז\"א שהוא זכר, מכל מקום, אין הנוקבא צריכה, משום זה להפרד מז\"א אלא בהנוקבא הוא נקרב, כדי לחבר ז\"א ונוקביה זה בזה, כי על ידי הקרבן, עולה הנוקבא לז\"א להתחבר ביחד. ואע\"פ שדרשינן (זבחים מו:) \u0003אשה\u0004 לשם אישים ולא לגבבא, מ\"מ אפשר גם ללמוד ממנו שרומז על הנוקבא."],[3,"נח איצטריך וכו':","נח היה צריך להקריב עולה, משום שהקב\"ה התקין אותו במקום זכר, שיתחבר ויכנס בהתיבה שה\"ס נוקבא. (כנ\"ל דף ב' אות' ה) ועל כן הקריב עולה. ובזה תירץ למה הקריב דוקא עולה ולא קרבן אחר, כיון שבאמת לא חטא, אלא משום שחשב שתמה לו כל זכות, כנ\"ל באות רכ\"ח, ע\"ש."],[3,"עולה הוא אשה וכו':","עולה הוא אשה, שבהכתוב, \u0003אש\"ה\u0004 הוא נוטריקון \u0003אש ה',\u0004 יורה, שהשמאל דז\"א המכונה \u0003אש,\u0004 נתחבר בהנוקבא הנק' \u0003ה'.\u0004 כי הנוקבא באה מצד שמאל הנקרא אש, שנתדבקו הנוקבא והאש זה בזה, ומשום זה נקראת נקבה \u0003אשה,\u0004 שהשם \u0003אשה,\u0004 יורה, קשר האהבה, אשר השמאל, שהוא \u0003אש,\u0004 אוחז בה שה\"ס \u0003ה',\u0004 להעלותה למעלה, לז\"א, לקשרם כאחד. ומשום זה אומר הכתוב, עולה הוא אשה, שיורה על קשר דכר ונוקבא זה בזה."],[4,"וירח ה' את ריח הניחח וכתיב אשה ריח ניחח וכו':","כתוב וירח ה' וגו' וכתיב אשה ריח ניחח, המלה, אשה, כך שמעתי פירושה, אשר עשן ואש מחוברים כאחד, שהרי אין עשן בלי אש, כמו שכתוב, והר סיני עשן כלו מפני אשר ירד עליו ה' באש."],[5,"ת\"ח אש נפיק וכו':","בוא וראה, אש יוצא מבפנים, והוא דק, ונאחז בדבר אחר מבחוץ שאינו דק כל כך, ונאחזים זה בזה, ואז עולה העשן. מהו הטעם, הוא משום, שהאש נאחז בדבר המתפעל ממנו, והסימן לך, חוטם, שיוצא בו העשן מתוך האש."],[5,"","פירוש. דינים, מכונים אש, בסו\"ה כי באש ה' נשפט וגו' (ישעיה ס\"ו) ושורש הדינים הוא מיציאת הבינה לבר מראש דא\"א, ששם אור החכמה, ונתמעטה מחכמה ונשארה באור החסדים בלי חכמה. ויש בהתמעטות הזאת ג' בחינות, שה\"ס ג' \u0003אשיות.\u0004 א) \u0003אשא דכיא,\u0004 והוא בג\"ר דבינה, שה\"ס או\"א עלאין, והוא מטעם שהתמעטות הזה, מאור החכמה, שבראש דא\"א, אינו נוגע להם כלום, כי אין דרכם לקבל חכמה אלא חסדים בלבד, בסו\"ה כי חפץ חסד הוא. ואפילו בעת היותם בראש א\"א, אינם מקבלים חכמה. לפיכך הם תמיד בבחינת ג\"ר, והם תמיד באור דחסדים, וההתמעטות מחכמה נבחן בהם \u0003לאשא דכיא.\u0004 כי נשארו בבחינת ג\"ר גם אחר שנתמעטו מחכמה. ב) הוא \u0003אשא סתם,\u0004 והוא בז\"ת דבינה, שה\"ס ישסו\"ת. והוא מטעם, שהם שרשי הזו\"ן, וצריכים להארת חכמה כדי להשפיע לזו\"ן, ולפיכך כל עוד שאין בהם חכמה, הם נבחנים לו\"ק בלי ראש, וע\"כ אינם נבחנים לאשא דכיא, להיותם מחוסרי ראש, אלא שנבחנים \u0003אשא סתם.\u0004 כלומר, שהם בלי טהרה, עד שישיגו הארת החכמה. אמנם אשא סתם שבהם, נבהן לאש דקה, והוא מטעם, שאינם רגישים להארת החכמה, שהרי אינם צריכים הארת חכמה בשביל עצמם, אלא בשביל זו\"ן, אבל לעצמם אינם מקבלים אלא חסדים, להיותם בחינת בינה גם הם. ונמצא שהאש אינו יכול להאחז בהם כלום. וע\"כ נבחן בהם האש לאש דקה בלי אחיזה. ג) \u0003אשא ותננא,\u0004 והם בזו\"ן. והוא מטעם, שז\"א רגיש הוא כלפי האש ההוא, שהיא ההתמעטות מחכמה, כי ז\"א צריך להארת החכמה. כי כל עצמותו של ז\"א הוא חסדים בהארת החכמה, שבזה נעשה לבחי\"ג, (כמ\"ש בפתיחה לחה\"ק דף ב' אות ה' ע\"ש) ונבחן שאש הזאת של התמעטות החכמה, מחמת יציאת הבינה מהראש, נאחז בו, להיותו עב ורגיש אליה, וע\"כ אש הזאת דבינה, נאחז בז\"א ומוציא בו עשן."],[5,"","וזה אמרו \u0003אש נפיק מלגיו,\u0004 היינו מישסו\"ת, \u0003ואיהו דק,\u0004 כי אינו יכול לאחוז בישסו\"ת, כי אינם רגישים כלל להארת החכמה כנ\"ל, \u0003ואחיד במלה אחרא לבר,\u0004 היינו בז\"א, \u0003דלאו איהו דק הכי,\u0004 כי הוא רגיש להארת החכמה, \u0003ואתאחדן דא בדא, וכדין תננא סלקא,\u0004 היינו הדינים שבמלכות דז\"א, הנקראים תננא, שהם מתגלים מתוך אחיזת האש בז\"א. \u0003וסימנך, חוטמא, דנפיק ביה תננא מגו אשא,\u0004 חוטם ה\"ס ז\"א, כי אזן חוטם פה, ה\"ס בינה ז\"א ונוקבא. וכשהאש מגיע לחוטם, שהוא רגיש, יוצא בו העשן מתוך האש, כמבואר, ונעשו בו דינים כפולים אש מבינה ועשן ממלכות. וז\"ס ב' נוקבי דפרדשקי המובא באדרא רבא (אות ס\"ג) שמנקב ימין, נמשך המתקה לאש הבינה, ומנקב שמאל נמשך המתקה לעשן המלכות. ועי' בחלק י\"ג דף אלף ת\"ד ד\"ה תיקון ג'"],[6,"וע\"ד כתיב ישימו וכו':","וע\"כ כתוב ישימו קטורה באפך, דהיינו, על ידי הקטרת ממתיקים הדינים, שהם אש ועשן היוצאים מהחוטם, משום שמחזיר האש מן החוטם אל מקומו, לישסו\"ת שמשם יצא כנ\"ל. והחוטם נאסף באותו הריח של הקטורת, ובא לפנימי פנימיות עד שכולם מתיחדים זה בזה, וכל אחד חוזר למקומו, ומתקרבים כולם לתוך המחשבה, שהוא א\"א. ואח\"כ נעשו כולם רצון אחד, ואז הוא ריח ניחח, שנח הכעס, ונעשה נחת רוח."],[6,"","פירוש. ב' פעולות נעשו כאן, על ידי אתערותא דלתתא של הקרבת הקטרת, א) שנתיחדו כל המדרגות זה בזה, דהיינו שכל אחת מהן חזרה והעלה את אתוון אל\"ה שלה שנפלו להתחתונה, \u0003עד דאתאחיד כלא ותב לאתריה.\u0004 ואתוון אל\"ה דבינה עם הזו\"ן הדבוקים בהם עלו לבינה, ואתוון אלה דא\"א עם הבינה הדבוקה בהם עלו וחזרו לראש א\"א, ששם מאיר בהם החכמה בלי חסדים, וז\"ש \u0003ואתקריב כלא לגו מחשבה,\u0004 ובזה נתבטל אש הדינים מהחוטם ומישסו\"ת, שהרי הבינה חזרה לראש א\"א כמקודם לכן, ועמה כל שאר המדרגות. וע\"כ \u0003נח רוגזא.\u0004 ב) שנעשו כולם לרצון אחד. כי החכמה אינה יכולה להאיר בלי חסדים, וע\"כ נעשה אח\"כ הזווג על המסך דז\"א, שה\"ס החוטם, ויוצא קומת חסדים, ומתלבשת החכמה בחסדים, ואז \u0003ואתעביד רעותא חדא,\u0004 כי בזה נקשרו כל ג' הקוין זה בזה כנודע, (כנ\"ל דף ע\"ז ד\"ה כתיב) ובזה \u0003אתעביד נייחא,\u0004 שנעשה נחת רוח. כי עתה מאיר הכל בשלימות. כי החסדים נשלמו בהארת החכמה והחכמה בהתלבשות החסדים."],[7,"דהא תננא אתכניש וכו':","שהרי העשן נאסף ונכנס ונתקמט בהאש, והאש נאחזה בהעשן, ונכנסו שניהם לפנימי פנימיות, עד שנח הכעס. והיינו פעולה א' שבדיבור הסמוך שנעשה מכח הבינה שחזרה לראש א\"א, ע\"ש. ואחר שנתיחדו כולם זה בזה, והכעס נח, נעשה זווג חדש, אז נעשה נחת רוח וקשר אחד מג' הקוין, ונקרא זה, נייחא. והיינו פעולה הב' שבדיבור הסמוך ע\"ש. והוא נחת רוח, מחסדים, וחדות כל, מחכמה, כאחד. כי החסדים נשלמו מהארת חכמה והחכמה מלבוש החסדים, כנ\"ל בדיבור הסמוך. והם הארת הנרות. מבחינת השמאל, ואור הפנים. מבחינת הימין. ומשום זה כתוב וירח ה' את ריח הניחח, כמי שמריח ומאסף הכל למקומו."],[8,"אתא ר' ייסא וכו':","בא רבי ייסא ונשקו, לאותו תינוק, אמר, והרי כל טוב הזה יש תחת ידך, ולא ידעתי בו, אמר אחזור מהדרך שלי ונתחבר עמך. הלכו. אמר ר' חזקיה, דרך הזה עם השכינה נלך, שהוא מתוקן לפנינו. אחז בידו של אותו התינוק והלכו. אמרו לו, אמור לנו מקרא אחד מאותם שאמר לך אביך."],[9,"פתח ההוא ינוקא וכו':","פתח אותו התינוק ואמר, ישקני מנשיקות פיהו, זה הוא תשוקה עליונה, כי יצא הרצון דרך הפה, ולא יצא דרך החוטם, בעת שיצאה האש, כי כאשר הפה נתחבר, למי שהוא, לנשק, יוצאת האש: ברצון, בהארת הפנים, בחדות כל, בדביקות של נחת רוח. והוא כמ\"ש לעיל בב\"ב (דף פ\"ב ד\"ה הני, ודף פ\"ה ד\"ה כיון) אשר האור היוצא דרך הפה הוא בחינת אוירא דכיא ואור חחסדים, והוא בחינת האור מאו\"א עלאין שה\"ס אשא דכיא כנ\"ל. והוא כל בחינת הג\"ר שבהעולמות עש\"ה. וכיון שהוא אור החסדים מאו\"א ע\"כ אין שום אחיזה בו לקליפות. וע\"כ \u0003נפיק אשא ברעותא בנהירו דאנפין וכו'.\u0004 להיותו בחינת \u0003אשא דכיא\u0004 כנ\"ל."],[10,"ובג\"כ כי טובים וכו':","ומשום זה אומר הכתוב, כי טובים דודיך מיין, דהיינו מיין ההוא המשמח, והפנים מאירים והעינים צוחקות ועושה חיבה ורעות, ולא מיין המשכר שעושה רוגז וכעס, ומחשיך הפנים, והעינים לוהטות מיין הרוגז."],[10,"","פירוש. הארת השמאל מכונה יין, שה\"ס הארת חכמה מסוד נקודת השורק כנודע. וכל תיקונו הוא ע\"י קו אמצעי המיחד ימין ושמאל זה בזה, ומקיים הארת שניהם באופן שהשמאל יאיר ממטה למעלה והימין גם ממעלה למטה כנ\"ל (דף ל\"ז ד\"ה כמה ע\"ש) וע\"י תיקון זה נבחן הארת החכמה בסוד יין המשמח \u0003ונהיר אנפין וחייכין עיינין וכו',\u0004 אמנם אם ממשיכים הארת החכמה ממעלה למטה, אז נפרדו הימין ושמאל זה מזה, והחכמה נמשכת בלי חסדים, שאז אינה יכולה להאיר וכל הדינין נמשכים ממנה. ונק' משום זה יין \u0003המשכר,\u0004 כי כל זה מגיע להם, מפני שממשיכים הארת החכמה יותר מהשיעור הנרצה, דהיינו שממשיכה ממעלה למטה."],[11,"וע\"ד בגין דחמר וכו':","וע\"כ, משום שיין זה הוא טוב, והפנים מאירים והעינים שמחות ופועל תשוקת האהבה, מקריבים אותו כל יום על המזבח. בשעור כזה, שמי ששותה אותו משמחו ופועל בו נחת רוח, כמו שכתוב, ונסכו יין רביעית ההין, דהיינו שנזהר להמשיכו בבחינת ממטה למעלה, כנ\"ל, המכונה רביעית ההין. ומשום זה נאמר, כי טובים דודיך מיין, מאותו היין המעורר אהבה ותשוקה."]],[[0,"","אוֹתוֹ מִזְבֵּחַ שֶׁבּוֹ הִקְרִיב אָדָם הָרִאשׁוֹן הָיָה. אִם כָּךְ, אָז לָמָּה וַיִּבֶן? אֶלָּא מִשּׁוּם שֶׁרִשְׁעֵי הָעוֹלָם גָּרְמוּ שֶׁלֹּא עָמַד בִּמְקוֹמוֹ. כֵּיוָן שֶׁבָּא נֹחַ, כָּתוּב בּוֹ וַיִּבֶן."],[1,"","וַיַּעַל עֹלֹת, כָּתוּב עֹלַת, אֶחָד. כָּתוּב (ויקרא א) עֹלָה הִוא אִשֵּׁה רֵיחַ נִיחֹחַ לַה' (לעולם עלה עולה זכר, אם) עוֹלָה - עוֹלֶה זָכָר וְלֹא עוֹלָה נְקֵבָה, שֶׁכָּתוּב זָכָר תָּמִים יַקְרִיבֶנּוּ. לָמָּה כָּתוּב אִשֶּׁה, שֶׁהֲרֵי אֵשׁ צְרִיכָה לְהִמָּצֵא שָׁם?"],[2,"","אֶלָּא אַף עַל גַּב שֶׁעוֹלָה נִקְרֶבֶת זָכָר וְלִמְקוֹמָהּ נִקְרֶבֶת, הַנְּקֵבָה לֹא צְרִיכָה לְהִפָּרֵד מִמֶּנּוּ, אֶלָּא עִמָּהּ נִקְרָב, בִּשְׁבִיל לְחַבֵּר זֶה עִם זֶה. שֶׁעוֹלָה הַנְּקֵבָה אֶל הַזָּכָר לְהִתְחַבֵּר כְּאֶחָד, וְאַף עַל גַּב שֶׁאִשֶּׁה לְשׁוּם אִישִׁים."],[3,"","נֹחַ הָיָה צָרִיךְ לְהַקְרִיב עוֹלָה, שֶׁהוּא בַּמָּקוֹם שֶׁל הַזָּכָר, עָשָׂה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְחַבֵּר וּלְהִכָּנֵס לַתֵּבָה, וְעַל זֶה הִקְרִיב עוֹלָה. עוֹלָה הוּא אִשֶּׁה. אֵשׁ ה'. שֶׁהִתְחַבֵּר (עמה) הַשְּׂמֹאל בַּנְּקֵבָה. שֶׁהֲרֵי (כל) נְקֵבָה מִצַּד הַשְּׂמֹאל בָּאָה, וְזָכָר מִצַּד הַיָּמִין בְּהִתְדַּבְּקוּת זֶה בָּזֶה, וְלָכֵן נִקְרֵאת (עולה) נְקֵבָה אִשֶּׁה. אִשֶּׁה - קֶשֶׁר שֶׁל הָאַהֲבָה שֶׁאוֹחֵז בָּהּ הַשְּׂמֹאל לְהַעֲלוֹתָהּ לְמַעְלָה וּלְהִתְקַשֵּׁר כְּאֶחָד, וְלָכֵן כָּתוּב עֹלָה הִוא אִשֵּׁה, הַקֶּשֶׁר שֶׁל זָכָר וּנְקֵבָה זֶה עִם זֶה."],[4,"","וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ. וְכָתוּב אִשֵּׁה רֵיחַ נִיחֹחַ. אִשֶּׁה, כָּךְ שָׁמַעְנוּ - עָשָׁן וְאֵשׁ מְחֻבָּרִים כְּאֶחָד, שֶׁהֲרֵי אֵין עָשָׁן בְּלֹא אֵשׁ, כְּמוֹ שֶׁכָּתוּב (שמות יט) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ."],[5,"","בֹּא רְאֵה, אֵשׁ יוֹצֵאת מִבִּפְנִים וְהוּא דַק, וְאוֹחֵז בְּדָבָר אֶחָד בַּחוּץ שֶׁאֵינוֹ דַק כָּךְ, וְנֶאֱחָזִים זֶה בָּזֶה, וְאָז עוֹלֶה הֶעָשָׁן. מָה הַטַּעַם? מִשּׁוּם שֶׁהָאֵשׁ אוֹחֶזֶת בְּדָבָר הַמִּתְפַּעֵל, וְסִימָן לַדָּבָר - הַחֹטֶם שֶׁיּוֹצֵא בּוֹ עָשָׁן מִתּוֹךְ אֵשׁ."],[6,"","וְעַל זֶה כָּתוּב (דברים לג) יָשִׂימוּ קְטוֹרָה בְּאַפֶּךְ. מִשּׁוּם שֶׁחוֹזֶרֶת הָאֵשׁ לִמְקוֹמָהּ. וְהַחֹטֶם (מתפעל) נֶאֱסָף בְּאוֹתוֹ רֵיחַ לִפְנַי וְלִפְנִים, עַד שֶׁנֶּאֱחָז הַכֹּל וְחוֹזֵר לִמְקוֹמוֹ, וְנִקְרָב הַכֹּל לְתוֹךְ הַמַּחֲשָׁבָה וְנַעֲשֶׂה רָצוֹן אֶחָד. וְאָז רֵיחַ נִיחֹחַ, שֶׁנָּח הָרֹגֶז וְנַעֲשֶׂה נַחַת."],[7,"","שֶׁהֲרֵי הֶעָשָׁן נֶאֱסָף וְנִכְנָס וּמִתְקַמֵּט בָּאֵשׁ, וְהָאֵשׁ אוֹחֶזֶת בֶּעָשָׁן, וְנִכְנָסִים שְׁנֵיהֶם לִפְנַי וְלִפְנִים עַד שֶׁנָּח הָרֹגֶז. וּכְשֶׁהַכֹּל נֶאֱחָזִים (אוחז) זֶה בָּזֶה וְנָח הָרֹגֶז, אָז הוּא מְנוּחָה וְקֶשֶׁר אֶחָד וְנִקְרֵאת נַחַת. נַחַת הָרוּחַ חֶדְוַת הַכֹּל כְּאֶחָד. הֶאָרַת הַנֵּרוֹת הֶאָרַת הַפָּנִים. וְלָכֵן כָּתוּב וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ, כְּמוֹ מִי שֶׁמֵּרִיחַ וְכוֹנֵס הַכֹּל לְתוֹךְ מְקוֹמוֹ."],[8,"","בָּא רַבִּי יֵיסָא וּנְשָׁקוֹ. אָמַר, וּמַה כָּל הַטּוּב הַזֶּה תַּחַת יָדְךְ וְלֹא יָדַעְתִּי בוֹ? אָמַר, אֶחֱזֹר מֵהַדֶּרֶךְ וְנִתְחַבֵּר עִמְּךְ. הָלְכוּ. אָמַר רַבִּי חִזְקִיָּה, בְּדֶרֶךְ זוֹ עִם הַשְּׁכִינָה נֵלֵךְ, שֶׁהֲרֵי מְתֻקֶּנֶת לְפָנֵינוּ. אָחַז בִּידֵי אוֹתוֹ תִינוֹק וְהָלְכוּ. אָמַר לוֹ, אֱמֹר לָנוּ פָּסוּק אֶחָד מֵאוֹתָם שֶׁאָבִיךְ אָמַר לְךְ."],[9,"","פָּתַח אוֹתוֹ הַתִּינוֹק וְאָמַר, (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. זוֹהִי הִשְׁתּוֹקְקוּת הָעֶלְיוֹנָה שֶׁיּוֹצֵא (שיצא) רָצוֹן מֵהַפֶּה לְנַשֵּׁק, וְלֹא יוֹצֵא מֵהַחֹטֶם כַּאֲשֶׁר יוֹצֵאת אֵשׁ. שֶׁהֲרֵי כְּשֶׁמִּתְחַבֵּר הַפֶּה לְנַשֵּׁק, יוֹצֵאת אֵשׁ בְּרָצוֹן בְּפָנִים מְאִירוֹת, בְּחֶדְוַת הַכֹּל, בְּהִתְדַּבְּקוּת שֶׁל מְנוּחָה."],[10,"","וּמִשּׁוּם כָּךְ כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, מֵאוֹתוֹ יַיִן (יין) הַמְשַׂמֵּחַ וּמֵאִיר פָּנִים וְהָעֵינַיִם מְחַיְּכוֹת, וְנַעֲשֶׂה הָרָצוֹן. וְלֹא מֵהַיַּיִן הַמְשַׁכֵּר (שמשכיר) וְעוֹשֶׂה רֹגֶז וּמַחְשִׁיךְ פָּנִים, וְהָעֵינַיִם לוֹהֲטוֹת יַיִן שֶׁל רֹגֶז."],[11,"","וְעַל זֶה, מִשּׁוּם שֶׁיַּיִן זֶה טוֹב מֵאִיר הַפָּנִים וּמְשַׂמֵּחַ הָעֵינַיִם וְעוֹשֶׂה הִשְׁתּוֹקְקוּת שֶׁל אַהֲבָה, מַקְרִיבִים אוֹתוֹ כָּל יוֹם עַל גַּבֵּי הַמִּזְבֵּחַ בְּשִׁעוּר שֶׁמִּי שֶׁשּׁוֹתֶה אוֹתוֹ, מְשַׂמֵּחַ אוֹתוֹ וְעוֹשֶׂה לוֹ נַחַת, שֶׁכָּתוּב (במדבר כח) וְנִסְכּוֹ רְבִיעִית הַהִין. וּמִשּׁוּם כָּךְ כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, מֵאוֹתוֹ הַיַּיִן שֶׁמִּעוֹרֵר אַהֲבָה וְהִשְׁתּוֹקְקוּת."]]],[["וְכֹלָּא כְּמָה דִלְתַתָּא אִתְעַר רְחִימוּתָא דִּלְעֵילָא. תְּרֵין שְׁרַגִּין כַּד אִתְדָעַךְ נְהוֹרָא דִּלְעֵילָא בִּתְנָנָא דְסָלִיק מֵהַהוּא דִלְתַתָּא אִתְדְּלִיק הַהוּא דִלְעֵילָא. אָמַר רַבִּי חִזְקִיָה הָכִי הוּא וַדַּאי דְּעָלְמָא עִלָּאָה תַּלְיָא בְּתַתָּאָה וְתַתָּאָה בְּעִלָּאָה, וּמֵזִמְנָא דְּאִתְחְרִיב בֵּי מַקְדְּשָׁא בִּרְכָאן לָא אִשְׁתַּכָּחוּ לְעֵילָא וְתַתָּא. לְאַחֲזָאָה דְּדָא בְּדָא תַּלְיָא.","וְאָמַר רַבִּי יוֹסֵי בִּרְכָאן לָא אִשְׁתַּכָּחוּ וּלְוָוטִין אִשְׁתַּכָּחוּ, דְּהָא יְנִיקוּ דְּכֹלָּא בְּהַהוּא סִטְרָא נָפְקֵי (ד\"א וברכאן לא נפקי), מַאי טַעְמָא, בְּגִין דְּיִשְׂרָאֵל לָא שַׁרְיָין בְּאַרְעָא וְלָא פָּלְחֵי פּוּלְחָנָא דְאִצְטְרִיךְ לְאַדְלָקָא בּוֹצִינִין וּלְאִשְׁתַּכָּחָא בִּרְכָאן, וּבְגִין כָּךְ לָא מִשְׁתַּכְּחֵי לְעֵילָא וְתַתָּא, וְעָלְמָא לָא יָתִיב בְּקִיּוּמֵיהּ כְּדְקָא יְאוּת.","וְאֲמַר רַבִּי חִזְקִיָּה לא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַאי הוּא, אָמַר רַבִּי יֵיסָא הָכִי שְׁמַעְנָא מֵרַבִּי שִׁמְעוֹן דְּאָמַר כָּל זִמְנָא דְּאֶשָׁא דִּלְעֵילָא אוֹסִיף לְתָקְפָא, תְּנָנָא דְּאִיהוּ דִינָא דִלְתַתָּא אַתְקִיף רוּגְזָא וְשָׁצֵי כֹּלָּא. בְּגִין דְּכַד נָפִיק אֶשָׁא לֵית לֵיהּ פֶּסֶק (קמיה) עַד דְּיִשְׁתְּלִים דִּינָא. וְכַד דִּינָא דִּלְתַתָּא לָא אוֹסִיף לְאִתְתַּקְפָא בְּדִינָא דִלְעֵילָא עָבִיד דִּינָא וּפָסִיק וְלָא יִשְׁתַּלַּם דִּינָא לְשֵׁיצָאָה. וּבְגִין כָּךְ כְּתִיב לֹא אוֹסִיף לְמֵיהַב תּוֹסֶפֶת לְאִתְתַּקְפָא דִינָא דִלְתַתָּא.","אָמַר הַהוּא יְנוּקָא שְׁמַעְנָא בְּגִין דִּכְתִיב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרְךָ. דְּהָא בְּהַהִיא שַׁעֲתָא דְּאִתְלַטְיָא אַרְעָא בְּחוֹבָא דְאָדָם. אִתְיְיהִיב רְשׁוּ לְשַׁלְטָאָה עֲלָהּ הַהוּא חִוְיָא בִישָׁא דְּאִיהוּ מְחַבְּלָא דְעָלְמָא וְשָׁצֵי בְּנֵי עָלְמָא. מֵהַהוּא יוֹמָא דְּקָרִיב נֹחַ קָרְבָּנָא, וְאָרַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִתְיְיהִיב רְשׁוּ לְאַרְעָא לְנַפְקָא מִתְּחוֹת הַהוּא נָחָשׁ וְנָפְקָא מִמְסָאָבָא. וְעַל דָּא מַקְרִיבִין יִשְׂרָאֵל קָרְבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְאַנְהָרָא אַפֵּי אַרְעָא. אָמַר רַבִּי חִזְקִיָּה יָאוֹת הוּא (והיא) וְהַאי הֲוָה תָּלֵי עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי. אָמַר רַבִּי יִיִסָא קוּדְשָׁא בְּרִיךְ הוּא אַזְעִיר לָהּ לְסִיהֲרָא וְשָׁלְטָא הַהוּא נָחָשׁ, אֲבָל בְּגִין חוֹבָא דְּאָדָם אִתְלַטְיָיא בְּגִין לְמֵילַט עָלְמָא. בְּהַהוּא יוֹמָא (דאתייהבת אורייתא) נַפְקַת אַרְעָא מֵהַהִיא קְלָלָה וְקָיְימָא סִיהֲרָא בְּהַהִיא גְרִיעוּתָא, בַּר בְּשַׁעֲתָא דְקוּרְבָּנָא אִשְׁתַּכָּחוּ בְּעָלְמָא וְיִשְׂרָאֵל יָתְבִין עַל אַרְעֲהוֹן.","אָמַר רַבִּי יֵיסָא לְהַהוּא יְנוּקָא מַה שְּׁמָךְ, אָמַר לֵיהּ אַבָּא. אָמַר לֵיהּ אַבָּא תְּהֵא בְּכֹלָּא בְּחָכְמָה וּבְשָׁנִין. קָרָא עֲלֵיהּ (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ וְתָגֵל יוֹלַדְתֶּךָ.","אָמַר רַבִּי חִזְקִיָּה זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא רוּחַ מְסָאֳבָא מִן עָלְמָא כְּמָה (ד\"א ל\"ג דאתמר) דִכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה יְיָ אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי יְיָ דִּבֶּר.","וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַנְהָרָא לְסִיהֲרָא וְלְאֲפָקָא לָהּ מֵחֲשׁוֹכָא בְּגִין הַהוּא חִוְיָא בִישָׁא. כְּמָה דִכְתִיב, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. מַאי אוֹר, הַהוּא אוֹר דְּגָנִיז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדָא דִבְרֵאשִׁית:","וַיְבָרֶךָ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגו'. רַבִּי אַבָּא פָּתַח וְאָמַר, (משלי י׳:כ״ב) בִּרְכַּת יְיָ הִיא תַעֲשִׁיר וְלא יוֹסִיף עֶצֶב עִמָּהּ. בִּרְכַּת יְיָ דָּא שְׁכִינְתָּא דְּאִיהִי אִתְפַּקְדָא עַל בִּרְכָאן דְּעָלְמָא, וּמִנָּהּ נָפְקֵי בִּרְכָאן לְכֹלָּא.","תָּא חֲזֵי מַה כְּתִיב בְּקַדְמִיתָא וַיֹּאמֶר יְיָ לְנֹחַ בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּיבָה וְגו'. כְּמָה דְּאִתְּמָר דְּמָארֵיהּ דְּבֵיתָא יָהַב לֵיהּ רְשׁוּ לְמֵיעָאל. לְבָתַר אִתְּתָא אָמְרָה לֵיהּ לְנַפְקָא. בְּקַדְמִיתָא עָאל בִּרְשׁוּתָא דְבַעֲלָהּ, לְסוֹף נָפַק בִּרְשׁוּ דְאִתְּתָא. מִכָּאן אוֹלִיפְנָא מָארֵיהּ דְּבֵיתָא יָעִיל וְאִתְּתָא תָּפִיק, הֲדָא הוּא דִכְתִיב וַיֹּאמֶר אֱלהִים אֶל נֹחַ לֵאמֹר צֵא מִן הַתֵּבָה. דְּרְשׁוּ הֲוָה בִידָהָא לְאֲפָקָא לֵיהּ לְאוּשְׁפִּיזָא וְלָא לְאַעֲלָא לֵיהּ."],[[0,"וכלא כמה דלתתא וכו'.","והכל כמו שהוא למטה כן נתעורר האהבה למעלה. שני נרות, כאשר נכבה אור הנר שלמעלה, בהעשן העולה מהנר של מטה, נדלק הנר שלמעלה. פירוש, בינה ומלכות הן שני נרות עליון ותחתון. ובעת חזרת הבינה לראש א\"א, שיש לה שם חכמה בלי חסדים, היא נכבית לגמרי, כי אפילו אור החכמה שישנו שם אינה יכולה לקבל, כי אין החכמה מקובלת בלי לבוש החסדים כנודע, אלא ע\"י הזווג שנעשה אח\"כ על המסך דזו\"ן המוציא קומת אור החסדים, נעשה הכרעה בין ימין ושמאל והחכמה מתלבשת בחסדים, ואז נדלקה הבינה ומאירה. והנה מסך זה היא של הנוק' דז\"א, ונמצא שהבינה, שהיא נר העליון, שנכבה מפאת חזרתה לראש א\"א, חוזרת ונדלקת ע\"י נר התחתון שהיא הנוקבא דז\"א."],[0,"א\"ר חזקיה הכי הוא ודאי וכו'.","אר\"ח ברור שכן הוא, אשר עולם העליון, שהוא בינה, תלוי בהתחתון, שהיא הנוקבא, דהיינו כנ\"ל, שהבינה שנכבית, חוזרת ונדלקת ע\"י הנוקבא. ועולם התחתון שהיא הנוקבא, תלוי בעולם העליון שהוא בינה, כי כל שיעור הארה שהנוקבא גרמה להאיר בהבינה, זוכה בו גם הנוקבא. ומשעה שנחרב בית המקדש, ברכות אינן נמצאות למעלה בבינה, ולמטה בהנוקבא, שזה מראה שהם תלוים זה בזה. פירוש. בית המקדש ה\"ס הנוקבא, וכיון שנחרבה, ואינה מעלית המסך שלה להבינה, ליחד הימין ושמאל שבה, נמצאת גם הבינה בלי אור, כי אינה נדלקת ממנה, ומכל שכן הנוקבא שהיא בלי אור, כי אין לה ממי לקבל ונמצא שאין אור נמצא לא בבינה לא במלכות."],[1,"ואמר רבי יוסי וכו':","ואר\"י, ברכות אינם נמצאים, וקללות נמצאים, כי יניקת כל מאותו הבחינה יוצאת, דהיינו מהדלקת נר העליון בהעשן של נר התחתון, כמו שמפרש והולך, מהו הטעם, משום שישראל אינם שרוים בארץ, ואינם עובדים עבודה הנצרכת, להדליק הנרות דהיינו להדליק העליון בתחתון, ולהמשיך הברכות בהעולמות, ומשום זה, הברכות אינם נמצאות למעלה ולמטה, והעולם אינו נמצא בקיומו כראוי."],[2,"וא\"ר חזקיה וכו':","ואר\"ח לא אוסיף לקלל וגו' מה הוא פירושו, וכי נוהג בו ית' חרטה ח\"ו. א\"ר ייסא כך שמעתי מר' שמעון שאמר, כל זמן שהאש של מעלה, של בינה, מוסיפה להתגבר, נמצא, העשן, שהוא הדין שלמטה, של הנוקבא, מגביר הכעס ומכלה את כל. משום כי כאשר האש מבינה, יוצאת, אין לה הפסק עד שתשלים הדין של הנוקבא, שהוא העשן. וכשהדין של מטה, העשן, אינו מוסיף להתגבר מכח הדין של מעלה, מכח האש, הוא עושה הדין ומפסיק אותו, ואיני גומר הדין עד להשחית, ועל כן כתוב, לא אוסיף שפירושו. לא אוסיף ליתן תוספת אש להגביר הדין של מטה. שהוא העשן."],[2,"","ביאור הדברים. כי נודע, שע\"י החטא, של עץ הדעת נפלו העולמות, והטוב והרע נתערבו זה בזה, ולא היה ניכר הטוב מפני הרע. ולפיכך תיקן הא' הוא, לגלות הרע, ואח\"כ להפרידו מהטוב. וז\"ס הקללה שקילל הש\"י את האדמה מסבת החטא של עצה\"ד, אשר קללה זו רבצה על הארמה וגילתה הרע לאט לאט עד שהביאה המבול על הארץ, ואז נגמר גילוי הרע. וע\"כ אחר המבול, שכבר נגלה הרע כל צרכו, הביא נח קרבן, שעל ידי זה הפריד הרע מהטוב, כמ\"ש בהזהר לפנינו."],[2,"","וכבר ידעת, שהדינין של המלכות, שה\"ס האדמה, נקראים \u0003עשן,\u0004 ונתבאר לעיל באות רל\"ד \u0003אש נפיק מלגיו\u0004 דהיינו מבינה \u0003ואחיד במלה אחרא לבר,\u0004 דהיינו בזו\"ן \u0003וכדין תננא סלקא,\u0004 שעל ידי התפשטות האש מבינה אל זו\"ן מתגלים הדינים של הנוקבא הנקראים עשן עש\"ה בהסולם. ובזה מבאר רבי שמעון ענין הקללה שקילל ה' את האדמה בעבור האדם."],[2,"כל זמנא דאשא דלעילא אוסיף לתקפא תננא וכו' דכד נפיק אשא לית ליה פסק עד דישתלים דינא","שכדי לתקן את החטא דעצה\"ד, הוסיף הקב\"ה המשכת האש של הבינה, וגילה העשן שבהאדמה, שהיא המלכות, לאט לאט, עד שנשלם הדין, בביאת המבול. דהיינו שנגלה הרע שהיה מעורב בהטוב, עד שהיה אפשר להפרידו מהטוב כנ\"ל. וז\"ש, \u0003ובגין כך כתיב לאחר המבול, לא אוסיף למיהב תוספת לאתתקפא דינא דלתתא,\u0004 כי עתה שכבר נשלם גילוי הרע, כבר אין לי צורך עוד להוסיף אש כדי לגלות הדין, כי כבר נגלה הרע כל צרכו. ואולי תאמר שהקב\"ה יעשה זאת כדי ליטול נקמה בהרשעים, לכן מסיים הכתוב כי יצר לב האדם רע מנעוריו, ואין לכעוס עליו, וכל העונשים של הקב\"ה המה רק תיקונים בלבד. וכיון שהתיקון הנצרך למבול כבר נגמר לכן אמר לא אוסיף וכו'. וכל זה מתבאר לפנינו להלן בדברי הינוקא, כמ\"ש להלן בדיבור הסמוך."],[3,"אמר ההוא ינוקא וכו':","אמר אותו התינוק, שמעתי, משום שכתוב ארורה האדמה בעבורך, כי באותה שעה שנתקללה האדמה בחטאו של אדם הראשון, ניתן רשות לאותו נחש הרע. לשלוט עליה, שהוא המחבל של העולם, שבזה נגלה הרע לאט לאט עד שהביא את המבול, (כנ\"ל בדיבור הסמוך) וכילה את כל בני העולם, דהיינו בהמבול שאז נגלה הרע כל צרכו, והיה אפשר להפרידו. מיום ההוא שנח הקריב הקרבן, והריח אותו הקב\"ה, שבזה הפריד הרע מהטוב. (כנ\"ל בדבור הסמוך) ניתן רשות להארץ לצאת מתחת שליטת הנחש, ולצאת מהטומאה, כי נפרד הרע ממנה. ועל כן מקריבים ישראל קרבנות להקב\"ה, כדי להאיר פני הארץ שהיא המלכות כלומר, נח עוד לא גמר תיקון הזה, וע\"כ צריכים עוד ישראל להקריב קרבנות. א\"ר חזקיה, יפה הוא. ותיקון זה היה תלוי עד שעמדו ישראל על הר סיני. ואז נפרד הרע לגמרי מן האדמה. כי פסקה הזוהמא ונעשו חירות ממלאך המות כנודע."],[4,"א\"ר ייסא קב\"ה וכו':","אר\"י הקב\"ה, מיעט את הלבנה, שהיא הנוקבא עוד מטרם שחטא האדם, ושלט הנחש. אבל משום חטאו של האדם היא נתקללה גם כן, כדי לקלל העולם המקבלים ממנה. ביום ההוא, שנח הקריב קרבן, יצאה הארץ, שהיא הנוקבא, רק מאותה הקללה. אבל עוד עומדת הלבנה במיעוטה. חוץ משעה שנמצא קרבן בעולם וישראל יושבים על אדמתם, אז נתקן מיעוט הלבנה. דהיינו בימי שלמה, כנודע. והוא חולק על הינוקא, שאמר (באות רמ\"ד), שע\"י הקרבן של נח ניתן רשות להארץ לצאת משליטת הנחש. והוא אומר, שרק הקללה נתבטלה, ושליטת הנחש נשארה, שמשום זה צריכים לקרבנות ישראל בבית המקדש."],[4,"אמר ר' ייסא לההוא ינוקא וכו':","אר\"י לאותו התינוק מה שמך, אמר לו, אבא. אמר לו. אבא תהיה בכל, אב בחכמה ואב בשנים. קרא עליו המקרא הזה, ישמח אביך ואמך ותגל יולדתך."],[5,"א\"ר חזקיה זמין, וכו':","אר\"ח עתיד הקב\"ה להעביר את רוח הטומאה מהעולם שכתוב ואת רוח הטומאה אעביר מן הארץ. וכתוב בלע המות לנצח וגו'."],[6,"וזמין וכו':","ועתיד הקב\"ה להאיר את הלבנה, ולהוציא אותה מחשך, שהשיגה מכח אותו נחש הרע, כמ\"ש והיה אור הלבנה וגו'. ושואל, מהו אור שבעת הימים, ומשיב, הוא אותו האור שגנזו הקב\"ה במעשה בראשית. כנ\"ל ב\"א דף ר\"פ אות שנ\"א ע\"ש."],[7,"ויברך וכו':","ר' אבא פתח ואמר, ברכת ה' היא תעשיר וגו', ברכת ה' היא השכינה, שהיא נתפקדה על ברכות העולם וממנה יוצאות הברכות לכל."],[8,"תא חזי מה וכו':","בוא וראה מה כתוב מתחילה, מקודם הכתוב ויברך וגו' כתוב, ויאמר ה' לנח בא אתה וכל ביתך, אל התיבה וגו'. בהכניסה לתיבה כתוב ויאמר הויה, שהוא ז\"א. ובהיציאה נאמר ויאמר אלקים, שהיא הנוקבא דז\"א. הוא כמו שאמרו, שבעל הבית שהוא ז\"א, נתן לו לנח רשות להכנס, ואח\"כ אומרת לו האשה לצאת שהיא נוקבא דז\"א, הוא נכנס מתחילה ברשות הבעל, ז\"א, ולבסוף הוא יצא ברשות האשה. שהיא, הנוקבא דז\"א. מכאן למדנו שבעל הבית יכניס האורח לביתו, והאשה תוציא אותו. וז\"ש ויאמר אלקים לנח צא מן התיבה, כי רשות היה בידיה להוציא את האורח, ולא להכניסו."],[8,"","ויש להבין הדברים משורשם, כי איזה דמיון יש כאן, לענין אורח ובעלי אכסניא. וצריך שתדע, שבשעה שהאדם הוא בכל השלימות נבחן ליושב \u0003בית.\u0004 שמלת \u0003בית\u0004 רומזת על הנוקבא דז\"א המאירה במוחין דג\"ר, בסו\"ה בחכמה יבנה בית. ולפיכך אותם המקבלים ממנה נבחנים ליושבי \u0003בית.\u0004 אמנם בעת שהאדם צריך לתקונים, כי אינו בשלמות, הרי הוא צריך לשמירה שלא יתאחזו בו החיצונים להחטיאו, וע\"כ הוא מוכרח לצאת מן ה \u0003בית,\u0004 כי אסור לו לקבל מוחין הגבוהים הללו, מפחד שלא יינקו ממני החיצונים, ומחוייב לצאת לדרך ה', דהיינו לקבל התקונים הצריכים אליו, ומותר לו בעת הזה לקבל מוחין מבחינת זווג ז\"א ולאה, כי להיותם בחינת אור החסדים המכוסים מחכמה, אין מהם שום יניקה לחיצונים. ומוחין הללו מכונים \u0003אכסניא,\u0004 כי הם מיועדים בשביל עוברי דרכים. ולפיכך, אע\"פ שנח צדיק תמים היה, מ\"מ הוא מדמה אותו לאורח עובר דרך, והוא מטעם, שבעת המבול, שניתן רשות להמשחית, היה צריך גם הוא לשמירה מפניו, (כנ\"ל דף ס\"ד אות קע\"ו) וע\"כ היה אסור לו לקכל מוחין מבחינת \u0003בית,\u0004 אלא מבחינת \u0003אכסניא,\u0004 המשומר מפני החיצונים, דהיינו כמו עוברי דרך. ומוחין הללו דאכסניא. מיוחסים לז\"א הנק' הוי\"ה, מטעם שהם נמשכים מבחינת חג\"ת שהוא ז\"א. אבל מוחין מבחינת \u0003בית,\u0004 מיוחסים רק להנוקבא הנקראת אלקים, משום שמוחין דחכמה אינם מגולים בשום מדרגה באצילות אלא בהנוקבא, (כנ\"ל ב\"ב דף ט\"ז אות ל'). ומתיישב בזה הקושיא שהקשה, למה בביאתו אל התיבה נאמר השם הוי\"ה, וביציאתו השם אלקים. כי התבה היא כמו בחינת אכסניא, וע\"כ כשנאמר לו בא אתה וכל \u0003ביתך\u0004 אל ה \u0003תיב\u0004 ה, שיהפך בחינת \u0003בית\u0004 שלו שהוא א\"ב ביושר לבחינת \u0003תיב\u0004 ה שהוא א\"ב למפרע, (כנ\"ל דף ס\"ד ד\"ה פירוש) שהם בחינת מוחין \u0003דאכסניא,\u0004 המיוחסים לז\"א הנק' \u0003הוי\"ה,\u0004 ע\"כ נאמר הויה. שז\"ס שהבעל, ז\"א, מכניס האורח אל \u0003האכסניא,\u0004 כי ממנו נמשכים המוחין כנ\"ל. אבל להוציאו מבחינת \u0003תיבה\u0004 ולהחזירו \u0003לבית,\u0004 דהיינו למוחין דג\"ר, שהם רק ברשות הנוקבא כנ\"ל, צריכה ע\"כ הנוקבא הנקראת \u0003אלקים\u0004 להוציאו, דהיינו להשפיע לו המוחין ד \u0003בית.\u0004 וע\"כ נאמר השם \u0003אלקים\u0004 בעת ההוצאה, כמ\"ש וידבר אלקים אל נח לאמור צא מן התיבה, וכן הוא בהוצאת האורח מהאכסניא אל הבית. ואין להקשות הלא יש הרבה מדרגות בינתים, שאפשר לקבלם גם מז\"א. והוא כי המדובר הוא במי שכבר השיג המוחין ד \u0003בית,\u0004 כמו נח, אלא שיצא ממנו לאכסניא משום איזה טעם, כנ\"ל, וע\"כ ודאי באותו רגע שנתבטל הטעם ויוצא מהאכסניא תכף שב להבית, שזה תלוי, ברשות הנוקבא בלבדה, כמבואר."]],[[0,"","וְהַסֹלֹ כְּמוֹ שֶׁלְּמַטָּה מְעוֹרֵר אַהֲבָה שֶׁלְּמַעְלָה. שְׁנֵי נֵרוֹת, כְּשֶׁדּוֹעֵךְ הָאוֹר שֶׁלְּמַעְלָה בֶּעָשָׁן שֶׁעוֹלֶה מֵאוֹתוֹ שֶׁלְּמַטָּה, נִדְלָק אוֹתוֹ שֶׁלְּמַעְלָה. אָמַר רַבִּי חִזְקִיָּה, כָּךְ הוּא בְּוַדַּאי, שֶׁהָעוֹלָם הָעֶלְיוֹן תָּלוּי בַּתַּחְתּוֹן וְהַתַּחְתּוֹן בָּעֶלְיוֹן. וּמִזְּמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, לֹא נִמְצְאוּ בְרָכוֹת לְמַעְלָה וּלְמַטָּה, כְּדֵי לְהַרְאוֹת שֶׁזֶּה תָּלוּי בָּזֶה."],[1,"","וְאָמַר רַבִּי יוֹסֵי, בְּרָכוֹת אֵין נִמְצָאוֹת, וּקְלָלוֹת נִמְצָאוֹת, שֶׁהֲרֵי יְנִיקַת הַכֹּל מֵאוֹתוֹ צַד יוֹצְאִים (ד\"א וברכות לא יוצאות). מָה הַטַּעַם? מִשּׁוּם שֶׁיִּשְׂרָאֵל לֹא שְׁרוּיִים בָּאָרֶץ וְלֹא עוֹבְדִים עֲבוֹדָה שֶׁצָּרִיךְ לְהַדְלִיק מְאוֹרוֹת וּלְהִמָּצֵא בְרָכוֹת, וְלָכֵן לֹא נִמְצָאִים לְמַעְלָה וּלְמַטָּה, וְהָעוֹלָם לֹא יוֹשֵׁב בְּקִיּוּמוֹ כָּרָאוּי."],[2,"","וְאָמַר רַבִּי חִזְקִיָּה, לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַהוּ זֶה? אָמַר רַבֵּי יֵיסָא, כָּךְ שָׁמַעְתִּי מֵרַבִּי שִׁמְעוֹן שֶׁאָמַר, כָּל פַּעַם שֶׁאֵשׁ שֶׁלְּמַעְלָה מוֹסִיפָה לְהִתְחַזֵּק - הֶעָשָׁן, שֶׁהוּא דִין שֶׁלְּמַטָּה, מְחַזֵּק הָרֹגֶז וּמַשְׁמִיד הַכֹּל. מִשּׁוּם שֶׁכְּשֶׁיּוֹצֵאת אֵשׁ, אֵין לָהּ הַפְסָקָה (לפניו) עַד שֶׁנִּשְׁלָם הַדִּין, וּכְשֶׁדִּין שֶׁלְּמַטָּה לֹא מוֹסִיף לְהִתְחַזֵּק עִם הַדִּין שֶׁלְּמַעְלָה, עוֹשֶׂה דִין וּפוֹסֵק, וְלֹא יֻשְׁלַם הַדִּין לְהַשְׁמִיד. וְלָכֵן כָּתוּב לֹא אֹסִף, לָתֵת תּוֹסֶפֶת שֶׁיִּתְחַזֵּק הַדִּין שֶׁלְּמַטָּה."],[3,"","אָמַר אוֹתוֹ תִינוֹק, שָׁמַעְתִּי מִשּׁוּם שֶׁכָּתוּב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה שֶׁהִתְקַלְלָה הָאָרֶץ בְּחֶטְאוֹ שֶׁל אָדָם, נִתְּנָה רְשׁוּת שֶׁיִּשְׁלֹט עָלֶיהָ אוֹתוֹ הַנָּחָשׁ הָרָע, שֶׁהוּא מַשְׁחִית אֶת הָעוֹלָם וּמַשְׁמִיד אֶת בְּנֵי הָעוֹלָם. מֵאוֹתוֹ יוֹם שֶׁהִקְרִיב נֹחַ קָרְבָּן וְהֵרִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ, נִתְּנָה רְשׁוּת לָאָרֶץ לָצֵאת מִתַּחַת אוֹתוֹ הַנָּחָשׁ וְיָצְאָה מִטֻּמְאָתָהּ. וְלָכֵן מַקְרִיבִים יִשְׂרָאֵל קָרְבָּן לַקָּדוֹשׁ- בָּרוּךְ-הוּא, כְּדֵי לְהָאִיר פְּנֵי הָאָרֶץ. אָמַר רַבִּי חִזְקִיָּה, יָפֶה הוּא, (והוא) וזֶה הָיָה תָלוּי עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי. אָמַר רַבִּי יֵיסָא, הַקָּדוֹשׁ בָּרוּךְ הוּא הִקְטִין אֶת הַלְּבָנָה וְשָׁלַט אוֹתוֹ הַנָּחָשׁ, אֲבָל מִשּׁוּם חֶטְאוֹ שֶׁל אָדָם הִתְקַלְלָה כְּדֵי לְקַלֵּל אֶת הָעוֹלָם. בְּאוֹתוֹ יוֹם (שנתנה התורה) יָצְאָה הָאָרֶץ מֵאוֹתָהּ קְלָלָה וְעָמְדָה הַלְּבָנָה בְּאוֹתָהּ גְּרִיעוּת, פְּרָט לַשָּׁעָה שֶׁקָּרְבָּנוֹת נִמְצְאוּ בָעוֹלָם וְיִשְׂרָאֵל יוֹשְׁבִים עַל אַרְצָם."],[4,"","אָמַר רַבִּי יֵיסָא לְאוֹתוֹ תִינוֹק, מַה שִּׁמְךְ? אָמַר לוֹ, אַבָּא. אָמַר לוֹ, אַבָּא תִּהְיֶה בַּכֹּל, בְּחָכְמָה וּבְשָׁנִים. קָרָא עָלָיו (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ."],[5,"","אָמַר רַבִּי חִזְקִיָּה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר רוּחַ הַטֻּמְאָה מֵהָעוֹלָם, כְּמוֹ (שנאמר) שֶׁכָּתוּב (זכריה ג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ, וְכָתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי ה' דִּבֵּר."],[6,"","ועָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר אֶת הַלְּבָנָה וּלְהוֹצִיאָהּ מֵהַחֹשֶׁךְ מִשּׁוּם אוֹתוֹ נָחָשׁ הָרָע, כְּמוֹ שֶׁכָּתוּב (שם ל) והיה אור הלבנה כאור החמה ואור החמה יהיה שבעתים כאור שבעת הימים. איזה אור? אותו האור שגנזו הקדוש ברוך הוא במעשה בראשית."],[7,"","ויְבָרֶךָ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (משלי י) בִּרְכַּת ה' הִיא תַעֲשִׁיר וְלֹא יוֹסִף עֶצֶב עִמָּהּ. בִּרְכַּת ה' - זוֹ הַשְּׁכִינָה, שֶׁהִיא מְמֻנָּה עַל בִּרְכוֹת הָעוֹלָם, וּמִמֶּנָּה יוֹצְאוֹת בְּרָכוֹת לַכֹּל."],[8,"","בֹּא רְאֵה מַה כָּתוּב בַּהַתְחָלָה, וַיֹּאמֶר ה' לְנֹחַ בּא אַתָּה וְכֹל בֵּיתְךְ אֶל הַתֵּבָה וְגוֹ'. כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁבַּעַל הַבַּיִת נָתַן לוֹ רְשׁוּת לְהִכָּנֵס. אַחַר כָּךְ הָאִשָּׁה אָמְרָה לוֹ לָצֵאת. בַּהַתְחָלָה נִכְנַס בִּרְשׁוּת בַּעְלָהּ, וּבַסּוֹף יָצָא בִּרְשׁוּת הָאִשָּׁה. מִכָּאן לָמַדְנוּ שֶׁבַּעַל הַבַּיִת יַכְנִיס, וְהָאִשָּׁה תּוֹצִיא. זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֱלֹהִים אֶל נֹחַ לֵאמֹר צֵא מִן הַתֵּבָה. שֶׁרְשׁוּת הָיְתָה בְיָדֶיהָ לְהוֹצִיא אֶת הָאוֹרֵחַ, וְלֹא לְהַכְנִיסוֹ."]]],[["כֵּיוָן דְּנָפַק יָהַב מַתְּנָן לָהּ, בְּגִין דְּאִיהִי בְּבֵיתָא וּבֵיתָא בִּידָהָא. וְאִנוּן מַתְּנָן דְּיָהַב לָהּ בְּגִין לְאַסְגָּאָה לָהּ רְחִימוּתָא בְּבַעֲלָהּ. מִכָּאן אוֹלִיפְנָא אוֹרַח אַרְעָא לְאוּשְׁפִּיזָא. (למיהב בידא דבעלה כד נפק יהב מתנן לאתתיה ולא בידה ובגין כך כיון דיהב ליה מתנן) וְעַל דָּא לְבָתַר דְּיָהַב לָהּ מַתְּנָן לְאַסְגָּאָה לָהּ רְחִימוּתָא בְּבַעֲלָהּ (נ\"א כיון דנפק יהב מתנן ונבזבזן בידא דבעלה למיהב לאתתיה ולמחדי בה ולאסגאה לה רחימותא בבעלה, הדא הוא דכתיב ויקח מכל וגו' ויעל עולות במזבח, אלין מתנן דיהב בידא דבעלה בגין לאסגאה לה רחימותא בעלמא, ומכאן אוליפנא אורח ארעא לאושפיזא דיהב מתנן בידא דבעלה לאתתיה ולא בידהא, ועל דא ויעל עולות במזבח, קורבנא לדכורא לאסגאה רחימותא בבעלה ברכא ליה) בָּרְכָא לֵיהּ, דִּכְתִיב וַיְבָרֶךְ אֱלהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגו'. וּבְגִין כָּךְ כְּתִיב, (משלי י׳:כ״ב) בִּרְכַּת יְיָ הִיא תַעֲשִׁיר. וַדַּאי כְּמָה דְאִתְּמָר.","וְלֹא יוֹסִיף עֶצֶב עִמָּהּ. רָזָא דִּכְתִיב בְּעִצָּבוֹן תֹּאכֲלֶנָּה. עִצָּבוֹן עֲצִיבוּ וְרוּגְזָא בְּלָא נְהִירוּ דְאַנְפִּין. כַּד אִתְחֲשַׁךְ סִיהֲרָא וּבִרְכָאן לָא מִשְׁתַּכְּחֵי. בְּעִצָּבוֹן סִטְרָא דְרוּחָא אָחֳרָא דְּאִמְנַע בִּרְכָאן מֵעָלְמָא, וּבְגִין כָּךְ וְלֹא יוֹסִיף עֶצֶב עִמָּהּ. וְדָא הוּא רָזָא דִכְתִיב, (בראשית ח׳:כ״א) לא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה:","וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה. מִכָּאן וּלְהָלְאָה יְהֵא לְכוֹן דְּיּוֹקְנִין דִּבְנֵי נָשָׁא דְּהָא בְּקַדְמִיתָא לָא הֲווּ דִּיוּקְנִין דִּבְנֵי נָשָׁא. תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב, (בראשית ט׳:ו׳) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וּכְתִיב, (בראשית ה׳:א׳) בִּדְמוּת אֱלהִים עָשָׂה אוֹתוֹ. כֵּיוָן דְּחָטוּ אִשְׁתַּנּוּ דְּיוּקְנַיְיהוּ מֵהַהוּא דִּיוּקְנָא עִלָּאָה וְאִתְהַפָּכוּ אִנוּן לְמִדְחַל מִקַּמֵּי חֵיוָון בְּרָא.","בְּקַדְמִיתָא כָּל בְּרִיָּין דְּעָלְמָא זָקְפָן עַיְינִין וְחָמָאן דִּיוּקְנָא קַדִּישָׁא עִלָּאָה וְזָעָאן וְדָחֲלִין מִקַּמֵּיהּ. כֵּיוָן דְּחָטוּ אִתְהַפַּךְ דְּיוּקְנַיְיהוּ מֵעֵינַיְיהוּ לִדְיוּקְנָא אָחֳרָא. וְאִתְהַפַּךְ דִּבְנֵי נָשָׁא זָעִין וְדָחֲלִין קַמֵּי שְׁאָר בְּרִיָּין.","תָּא חֲזֵי, כָּל אִנוּן בְּנֵי נָשָׁא דְּלָא חָטָאן קַמֵּי מָארֵיהוֹן וְלָא עָבְרִין עַל פִּקּוּדֵי אוֹרַיְיתָא. זִיו דִּיוּקְנָא דִּלְהוֹן לָא אִשְׁתַּנֵּי מֵחֵיזוּ דִּדְיוּקְנָא עִלָּאָה. וְכָל בְּרִיָּין דְּעָלְמָא זָעִין וְדָחֲלִין קַמֵּיהּ. וּבְשַׁעֲתָא דִּבְנִי נָשָׁא עָבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, אִתְחַלַּף דִּיוּקְנָא דִלְהוֹן וְכֻלְהוּ זָעִין וְדָחֲלִין מִקַּמֵּי בְּרִיָין אָחֳרָנִין, בְּגִין דְּאִתְחַלַּף דִּיוּקְנָא עִלָּאָה וְאִתְעֲבַר מִנַּיְיהוּ, וּכְדֵין שָׁלְטֵי בְּהוּ חֵיוַת בְּרָא, דְּהָא לָא חָמוּ בְּהוּ הַהוּא דִּיוּקְנָא עִלָאָה כִּדְקָחָזֵי.","וְעַל כָּךְ הַשְׁתָּא כֵּיוָן דְּעָלְמָא אִתְחַדַּשׁ כְּמִלְּקַדְּמִין, בָּרִיךְ לוֹן בְּרָכָה דָא וְשַׁלִּיט לוֹן עַל כֹּלָּא, כְּמָא דְאַתְּ אָמֵר וְכָל דְּגֵי הַיָּם בְּיֶדְכֶם נִתָּנוּ. וְאֲפִילּוּ נוּנֵי יַמָּא. רַבִּי חִיָּיא אָמַר בְּיֶדְכֶם נִתָּנוּ. מִקַּדְמַת דְּנָא. דְּכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא מְסַר כֹּלָּא בִּידֵהוֹן דִּכְתִיב וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגו'.","וַיְבָרֶךָ אֱלהִים אֶת נֹחַ. רַבִּי חִזְקִיָּה פָּתַח (תהלים לכ) לְדָוִד מַשְׂכִּיל אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה. הַאי קְרָא אוּקְמוּהָ, אֲבָל קְרָא דָא בְּרָזָא דְּחָכְמְתָא אִתְּמָר. דְּהָא תָּנִינָן בַּעֲשָׂרָה זִינֵי שְׁבָחָא שַׁבַּח דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא וְחַד מִנַּיְיהוּ מַשְׂכִּיל. וְהוּא דַּרְגָּא חַד מֵאִנוּן עֲשָׂרָה. וְדָוִד אַתְקִין גַּרְמֵיהּ עַד לָא יִשְׁרֵי עֲלוֹי הַאי דַּרְגָּא.","אַשְׁרֵי נְשׂוּי פֶּשַׁע, דְּהָא בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַתְקִיל חוֹבֵי וְזַכְוָון דִּבְנֵי נָשָׁא דְּהַהוּא (ד\"א כד ההוא) תִיקְלָא דְּבִסְטַר חוֹבִין מִסְתַּלְּקִין וְאִנוּן אוֹחֳרָנִין זַכְיָין דְּאִנוּן בְּתִיקְלָא אָחֳרָא מַכְרִיעִין לְתַתָּא דָּא הוּא נְשׂוּי פֶּשַׁע.","כְּסוּי חֲטָאָה בְּשַׁעֲתָא דְדִינָא שַׁרְיָא בְּעָלְמָא דִּיהֵא מְחַפְיָא דְּלָא יִשְׁלוֹט עֲלוֹי מְחַבְּלָא, כְּמָה דְּהֲוָה לְנֹחַ דְּכַסֵּי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵהַהוּא חֲטָאָה דְּאַמְשִׁיךְ עֲלֵיהּ אָדָם עַל עָלְמָא. דְּכֵיוָן דְּחֲטָאָה דָא אַנְגִיד אָדָם עַל עַלְמָא, שְׁאָר בְּרִיָּין שָׁלְטָאן וּבַר נָשׁ דָּחִיל מִנַּיְיהוּ וְעָלְמָא לָא אַתְקִין בְּתִקּוּנִיהּ. וּבְגִין כָּךְ כַּד נָפַק נֹחַ מִתֵּיבוּתָא קוּדְשָׁא בְּרִיךְ הוּא בָּרְכֵיהּ. דִּכְתִיב וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וְגו':","וְאַתֶּם פְּרוּ וּרְבוּ. בְּהַנֵּי בִּרְכָאן לָא אִשְׁתַּכָּחוּ נוּקְבֵי, אֶלָּא אֶת נֹחַ וְאֶת בָּנָיו, אֲבָל נוּקְבֵי לָא אָמַר קְרָא. אָמַר רַבִּי שִׁמְעוֹן וְאַתֶּם כְּלָלָא דִּדְכוּרֵי וְנוּקְבֵי כְּחֲדָא. וְתוּ אֶת נֹחַ לְאַסְגָּאָה נוּקְבֵיהּ. וְאֶת בָּנָיו לְאַסְגָּאָה נוּקְבֵי דִלְהוֹן."],[[0,"כיון דנפק יהב וכו':","כיון שיצא מהתיבה נתן לה מתנות דהיינו שהקריב קרבן, משום שהיא בהבית והבית בידיה, כלומר המוחין דבית הם רק בידי הנוקבא בלבדה (כנ\"ל בדיבור הסמוך) ואלו המתנות שנתן לה, הוא כדי לחבבה על בעלה. מכאן למדנו דרך ארץ לאורח. ליתן מתנות לבעלת האכסניא בשעת יציאתו. וע\"כ לאחר שנתי לה מתנות כדי לחבבה על בעלה, ברכה אותו, שנאמר, ויברך אלקים את נח. ומשום זה כתוב, ברכת ה' היא תעשיר, שהוא ודאי כמו שנתבאר אשר \u0003ברכת ה' דא שכינתא דאיהי אתפקדא על ברכאן דעלמא.\u0004 לעיל באות רמ\"ח."],[1,"ולא יוסיף עצב עמה וכו':","הוא סוד הכתוב בעצבון תאכלנה. עצבון פירושו עצבות וכעס בלי הארת פנים. והוא, כאשר נחשך הלבנה והברכות אינן נמצאות. בעצבון פירושו, הצד של רוח האחר דקליפות, שמונע הברכות מהעולם, להיותו מחטיא את בני האדם. ועל זה כתוב, ולא יוסיף עצב עמה. וזה הוא הסוד שכתוב, לא אוסיף לקלל עוד את האדמה. כי עצב פירושו אחיזת הסטרא אחרא המביא קללה לעולם, ונמצא כשלא יוסיף עצב עמה, לא יוסיף עוד לקלל, כי היינו הך."],[2,"ומוראכם וחתכם יהיה וגו':","היינו שמכאן ולהלאה, יהיה לכם צורות בני אדם, שמהן יראים חיות השדה, שהרי מקודם לכן, מעת החטא דעצה\"ד, לא היו להם צורות בני אדם. בוא וראה, מתחילה כתוב, בצלם אלקים עשה את האדם, וכתוב בדמות אלקים עשה אותו. וע\"כ יראו מהם חיות השדה, כיון שחטאו, נשתנו צורותיהם מאותה צורה העליונה, ונהפכו הם, לירא מפני חיות השדה."],[3,"בקדמיתא וכו':","מתחילה כל בריות העולם נשאו עיניהם וראו צורה קדושה עליונה, שבבני האדם זעו ופחדו מפניה. כיון שחטאו, נהפך צורתם לעיניהם של החיות, לצורה אחרת, וע\"כ נהפך, אשר בני האדם זעים ומפחדים מפני שאר הבריות."],[4,"ת\"ח כל אינון וכו':","בוא וראה כל אלו בני אדם שלא חטאו לפני רבונם, ולא עברו על מצות התורה, זיו צורתם, אינו משתנה מהמראה של צורה העליונה דהיינו צלם האלקים, וכל בריות העולם זעים ומפחדים מפניו, ובשעה שבני אדם עוברים על דברי התורה מתחלפת צורתם, וכולם זעים ומפחדים מפני בריות אחרות. משום שנתחלפה צורה העליונה ונעברה מהם, ואז שולטים בהם חיות השדה, כי אינם רואים בהם אותה צורה העליונה כראוי."],[5,"ועל כך השתא וכו':","ועל כן עתה כשיצאו מן התיבה, כיון שהעולם נתחדש כבתחילה, ברך אותם ברכה זו, והמשיל אותם על כל הבריות, ואפילו על דגי הים. כש\"א, וכל דגי הים בידכם נתנו. ר' חייא אמר, בידכם נתנו, מקודם לכן, כי כשברא הקב\"ה את העולם מסר הכל בידיהם, שכתוב ורדו בדגת הים ובעוף השמים וגו'. הרי שנתנו בידיהם עוד מיום שנברא אדם הראשון."],[5,"","פנימיות הדברים. כי האדם הוא אחרון שבבריאה, ונודע שכל בריה היותר זך נברר תחילה. ונמצא שבחינת האדם היא העבה ביותר מכל בריות העולם. גם נודע, שכל מסך היותר עב הוא מקבל קומת זווג היותר גבוה, וע\"כ קבל האדם קומת אור יותר גבוה מכל בריות העולם, שה\"ס צלם אלקים. וע\"כ נפל פחדו על כל בריות העולם. כי מטבע הקטן להכנע ולירא מפני הגדול ממנו. אמנם אחר שחטא בעץ הדעת, ואבד קומת האור, ונשאר לו העוביות, הגדולה יותר מכל הבריות, ריקנית בלי אור, ונגלה ששפל יותר מכל בריות העולם. וע\"כ נתהפך השיטה, שהאדם מפחד מבריות העולם. וז\"ס שאמרו חז\"ל (סנהדרין לח.) אם חטא אדם אומרים לו יתוש קדמך. כי אם אינו חוטא, ומחזיק לו מסך על עוביותו, נמצאת העוביות לשבח אליו, שהרי משיג משום זה קומת אור גבוה יותר. אבל כשהוא חוטא ואובד קומת אורו, ונשאר בעוביותו בלבד, הרי היא לגנאי לו, ואז היתוש קודם במעלה אליו, כי נברר תחילה, והוא זך ביותר."],[6,"ויברך אלקים את נח וכו':","ר' חזקיה פתח, לדוד משכיל וגו', מקרא זה בארוהו, אבל מקרא הזה נאמר בסוד החכמה, שהרי למדנו, בעשרה מיני שבח שיבח דוד להקב\"ה, ואחד מהם הוא משכיל, אשר יורה על סוד החכמה. והוא מדרגה אחת מאלו עשרת המדרגות, דהיינו ניציח, ניגון, משכיל, מכתם, מזמור, שיר, אשרי, תפילה, הודאה, והללויה, שבהם תיקן דוד ספר תהלים. ודוד תיקן את עצמו מטרם ששרה עליו המדרגה הזו. והיינו כמ\"ש לעיל (אות קס\"ח) בהפרש שבין לדוד מזמור או מזמור לדוד ע\"ש."],[7,"אשרי נשוי פשע וכו':","הכתוב אשרי נשוי פשע, פירושו, כי בשעה שהקב\"ה שקל חובות וזכיות של בני אדם במאזנים, אשר הכף שבצד החובות עולה. והאחרות, שהם הזכיות שבכף האחרת מכריעות, ונמשכות למטה, זה הוא \u0003נשוי פשע,\u0004 כי הכף עם הפשעים נשאת ועלתה למעלה, להיותו רובו זכאי ומיעוטו חייב. סוד הדברים. כי קו ימין ה\"ס כף זכיות. וקו שמאל, ה\"ס כף חובות, מפני שרק ממנו כל הדינים. וקו האמצעי מכריע בין כפות המאזנים הללו, שממשיך אור ימין ממעלה למטה, ואור השמאל ממטה למעלה. \u0003והכרעה\u0004 זו נקראת \u0003נשוי פשע,\u0004 שבהיותו מעלה הארת השמאל שלא תאיר ממעלה למטה, נמצא מבטל כל העונות והפשעים. כי אין אחיזה לדינים, בהארה שממטה למעלה."],[8,"כסוי חטאה וכו':","הכתוב, כסוי חטאה, פירושו, שבשעה שהדין שורה בעולם יהיה מכוסה, שלא ישלוט עליו המחבל, כמו שהיה לנח, שכסה עליו הקב\"ה, בשעת המבול, מאותו החטא, דעצה\"ד, שהמשיך אדם הראשון על העולם. וע\"כ לא ראה אותו המחבל, כלומר שלא היה לו בו שום אחיזה שיוכל להענישו. ומכיון שאדם המשיך חטא הזה על העולם, נמצאו שאר הבריות שולטים והאדם מפחד מפניהם, והעולם אינו מתוקן בתיקונו. ומשום זה, כשיצא נח מהתיבה, ברכו הקב\"ה, שנאמר ויברך אלקים את נח וגו' ומוראכם וחתכם יהיה על כל חית השדה וגו'. דהיינו שהחזירו לאותה בחינה כמו שהיה אדם הראשון קודם החטא דעצה\"ד, שכל הבריות היו יראים מפניו."],[9,"ואתם פרו ורבו וכו':","מקשה, באלו הברכות לא נזכרו הנקבות, אלא כתוב את נח ואת בניו, אבל נקבות לא אמר הכתוב. אמר רבי שמעון, \u0003ואתם,\u0004 שכתוב בו \u0003ו'\u0004 יתירה, הוא כולל זכרים ונקבות יחד. כי ה \u0003ו'\u0004 של ואתם מרבה גם את הנקבות. \u0003ותו את נח וכו':\u0004 ועוד, את נח, המלה \u0003את\u0004 המיותרת כאן, שהיא שם הנוקבא (כנ\"ל בבראשית א' דף י\"ז ד\"ה בשעתא ע\"ש) באה לרבות אשתו של נח. \u0003ואת בניו,\u0004 המלה \u0003את\u0004 באה לרבות הנשים שלהם."]],[[0,"","כֵּיוָן שֶׁיָּצָא, נָתַן לָהּ מַתָּנוֹת, מִשּׁוּם שֶׁהִיא בַּבַּיִת וְהַבַּיִת בְּיָדֶיהָ. וְאוֹתָם הַמַּתָּנוֹת שֶׁנָּתַן לָהּ, כְּדֵי לְהַרְבּוֹת אַהֲבָה אֶל בַּעְלָהּ. מִכָּאן לָמַדְנוּ דֶּרֶךְ אֶרֶץ לְאוֹרֵחַ (לתת ביד בעלה, כשיוצא נותן מתנות לאשתו, ולא בידה, ולכן, כיון שנתן לו מתנות). וְעַל זֶה, לְאַחַר שֶׁנָּתַן לָהּ מַתָּנוֹת לְהַרְבּוֹת לָהּ אַהֲבָה עִם בַּעְלָהּ. (נ\"א: כיון שיצא, נתן מתנות ואוצרות ביד בעלה לתת לאשתו ולשמח עמה ולהרבות לה אהבה עם בעלה, זהו שכתוב ויקח מכל וגו' ויעל עלת במזבח, אלו מתנות שנתן ביד של בעלה כדי להרבות לה אהבה בעולם, ומכאן למדנו דרך ארץ לאורח שיתן מתנות ביד של בעלה לאשתו ולא בידיה, ועל זה ויעל עלת במזבח, קרבן לזכר, להרבות אהבה עם בעלה ברך אותו) בֵּרַךְ אוֹתוֹ, שֶׁכָּתוּב וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגוֹ'. וְלָכֵן כָּתוּב (משלי י) בִּרְכַּת ה' הִיא תַעֲשִׁיר. וַדַּאי כְּמוֹ שֶׁנִּתְבָּאֵר."],[1,"","וְלֹא יוֹסִף עֶצֶב עִמָּהּ - סוֹד הַכָּתוּב בְּעִצָּבוֹן תֹּאכֲלֶנָּה. עִצָּבוֹן - עַצְבוּת וְרֹגֶז בְּלִי הֶאָרַת פָּנִים. כְּשֶׁנֶּחְשֶׁכֶת הַלְּבָנָה (מלכות) וּבְרָכוֹת לֹא נִמְצָאוֹת. בְּעִצָּבוֹן - צַד שֶׁל רוּחַ אַחֵר שֶׁמּוֹנֵעַ בְּרָכוֹת מֵהָעוֹלָם, וְלָכֵן לֹא יוֹסִף עֶצֶב עִמָּהּ. וְזֶהוּ סוֹד הַכָּתוּב (בראשית ח) לֹא אֹסִף עוֹד לְקַלֵּל אֶת הָאֲדָמָה."],[2,"","וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה. מִכָּאן וּלְהָלְאָה יִהְיֶה לָכֶם דְּמֻיּוֹת בְּנֵי אָדָם, שֶׁהֲרֵי בַּתְּחִלָּה לֹא הָיוּ דְמֻיּוֹת שֶׁל בְּנֵי אָדָם. בּא רְאֵה, בַּתְּחִלָּה כָּתוּב (שם ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (שם ה) בִּדְמוּת אֱלֹהִים עָשָׂה אֹתוֹ. כֵּיוָן שֶׁחָטְאוּ, הִשְׁתַּנְּתָה דְמוּתָם מֵאוֹתָהּ דְּמוּת עֶלְיוֹנָה, וְהֵם הִתְהַפְּכוּ לִפְחֹד מִלִּפְנֵי חַיּוֹת הַשָּׂדֶה."],[3,"","בַּהַתְחָלָה כָּל בְּרִיּוֹת הָעוֹלָם זָקְפוּ עֵינַיִם, וְרָאוּ דְמוּת קְדוֹשָׁה עֶלְיוֹנָה וְזָעוּ וּפָחֲדוּ מִלְּפָנָיו. כֵּיוָן שֶׁחָטְאוּ, הִתְהַפְּכָה דְמוּתָם בְּעֵינֵיהֶם לִדְמוּת אַחֶרֶת, וְהִתְהַפֵּךְ שֶׁבְּנֵי אָדָם זָעִים וּפוֹחֲדִים לִפְנֵי שְׁאָר הַבְּרִיּוֹת."],[4,"","בֹּא רְאֵה, כָּל אוֹתָם בְּנֵי אָדָם שֶׁלֹּא חוֹטְאִים לִפְנֵי רִבּוֹנָם וְלֹא עוֹבְרִים עַל מִצְווֹת הַתּוֹרָה, זִיו דְּמוּתָם לֹא מִשְׁתַּנֶּה מִמַּרְאֵה הַדְּמוּת הָעֶלְיוֹנָה, וְכָל בְּרִיּוֹת הָעוֹלָם זָעִים וּפוֹחֲדִים לְפָנָיו. וּבְשָׁעָה שֶׁבְּנֵי אָדָם עוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, מִתְחַלֶּפֶת דְּמוּתָם, וְכֻלָּם מִזְדַּעְזְעִים וּפוֹחֲדִים מִלִּפְנֵי הַבְּרִיּוֹת הָאֲחֵרוֹת, מִשּׁוּם שֶׁהִתְחַלְּפָה הַדְּמוּת הָעֶלְיוֹנָה וְהָעָבְרָה מֵהֶם, וְאָז שׁוֹלְטִים בָּהֶם חַיּוֹת הַשָּׂדֶה, שֶׁהֲרֵי לֹא רוֹאִים בָּהֶם אוֹתָהּ דְּמוּת עֶלְיוֹנָה כָּרָאוּי."],[5,"","וְעַל כָּךְ עַכְשָׁו, כֵּיוָן שֶׁהָעוֹלָם הִתְחַדֵּשׁ כְּמוֹ מִקֹּדֶם, בֵּרְכָם אֶת הַבְּרָכָה הַזּוֹ וְהִשְׁלִיט אוֹתָם עַל הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר וְכָל דְּגֵי הַיָּם בְּיֶדְכֶם נִתָּנוּ. וַאֲפִלּוּ דְּגֵי הַיָּם. רַבִּי חִיָּיא אָמַר, בְּיֶדְכֶם נִתָּנוּ - מִקֹּדֶם לָכֵן. כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָעוֹלָם, מָסַר בִּידֵיהֶם אֶת הַכֹּל, שֶׁכָּתוּב וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ'."],[6,"","וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ. רַבִּי חִזְקִיָּה פָּתַח, (תהלים לב) לְדָוִד מַשְׂכִּיל אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל פָּסוּק זֶה נִתְבָּאֵר בְּסוֹד הַחָכְמָה. שֶׁהֲרֵי שָׁנִינוּ, בַּעֲשָׂרָה מִינֵי שֶׁבַח שִׁבַּח דָּוִד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֶחָד מֵהֶם הוּא מַשְׂכִּיל, וְהוּא דַּרְגָּה אַחַת מֵאוֹתָן עֶשֶׂר. וְדָוִד הִתְקִין עַצְמוֹ בְּטֶרֶם שֶׁתִּשְׁרֶה עָלָיו הַדַּרְגָּה הַזּוֹ."],[7,"","אַשְׁרֵי נְשׂוּי פֶּשַׁע, שֶׁהֲרֵי בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹקֵל חֲטָאִים וּזְכֻיּוֹת שֶׁל בְּנֵי אָדָם שֶׁל אוֹתוֹ (ד\"א כשאותו) מִשְׁקָל שֶׁבְּצַד הַחֲטָאִים עוֹלִים, וְאוֹתָם הָאֲחֵרִים, הַזְּכֻיּוֹת שֶׁהֵן בְּמִשְׁקָל אַחֵר, מַכְרִיעוֹת לְמַטָּה - זֶהוּ נְשׂוּי פֶּשַׁע."],[8,"","כְּסוּי חֲטָאָה - בְּשָׁעָה שֶׁהַדִּין שׁוֹרֶה בָּעוֹלָם, שֶׁיִּהְיֶה מְכַסֶּה שֶׁלֹּא יִשְׁלֹט עָלָיו הַמַּשְׁחִית, כְּמוֹ שֶׁהָיָה לְנֹחַ שֶׁכִּסָּה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתוֹ חֵטְא שֶׁהִמְשִׁיךְ עָלָיו אָדָם עַל הָעוֹלָם. שֶׁכֵּיוָן שֶׁחֵטְא זֶה הִשְׁפִּיעַ אָדָם עַל הָעוֹלָם, שְׁאָר הַבְּרִיּוֹת שׁוֹלְטוֹת, וּבֶן אָדָם פּוֹחֵד מֵהֶם, וְהָעוֹלָם לֹא הֻתְקַן בְּתִקּוּנוֹ. וְלָכֵן כְּשֶׁיָּצָא נֹחַ מֵהַתֵּבָה, בֵּרְכוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וְגוֹ'."],[9,"","וְאַתֶּם פְּרוּ וּרְבוּ. בַּבְּרָכוֹת הַלָּלוּ לֹא נִמְצְאוּ נְקֵבוֹת, אֶלָּא אֶת נֹחַ וְאֶת בָּנָיו, אֲבָל נְקֵבוֹת הַפָּסוּק לֹא אָמַר. אָמַר רַבִּי שִׁמְעוֹן, וְאַתֶּם - כְּלָל שֶׁל הַזְּכָרִים וְהַנְּקֵבוֹת כְּאֶחָד. וְעוֹד, אֶת נֹחַ - לְרַבּוֹת אֶת אִשְׁתּוֹ. וְאֶת בָּנָיו - לְרַבּוֹת אֶת נְקֵבוֹתֵיהֶ ם."]]],[["וּבְגִין כָּךְ כְּתִיב אַתֶּם פְּרוּ וּרְבוּ לְמֶעְבַּד תּוֹלְדוֹת מִכָּאן וּלְהָלְאָה שִׁרְצוּ בָאָרֶץ. וְהָכָא יָהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא שֶׁבַע פִּקּוּדֵי אוֹרַיְיתָא לוֹן וּלְכָל דְּאָתוּ אֲבַּתְרַיְיהוּ, עַד דְּקָיְימוּ יִשְׂרָאֵל בְּטוּרָא דְסִינַי וְאִתְיְיהַב לוֹן כָּל פִּקּוּדֵי אוֹרַיְיתָא כְּחֲדָא:","וַיֹּאמֶר אֱלֹהִים לְנֹחַ וְגו'. זֹאת אוֹת הַבְּרִית אֲשֶׁר אֲנִי נוֹתֵן בֵּינִי וּבֵינֵיכֶם וְגו'. אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. נָתַתִּי מִקַּדְמַת דְּנָא. רַבִּי שִׁמְעוֹן פָּתַח (יחזקאל א׳:כ״ו) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. מַה כְּתִיב לְעֵילָא וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים כְּקוֹל שַׁדַּי בְּלֶכְתָּן. אִלֵּין אַרְבַּע חֵיוָון רַבְרְבָן עִלָּאִין קַדִּישִׁין דְּהַהוּא רָקִיעַ מִתְתַּקְּנָא עֲלַיְיהוּ. וְכֻלְהוּ גַדְפַיְיהוּ (ד\"א ל\"ג פרישן) מִתְחַבְּרָאן דָּא בְּדָא לְחַפְיָיא גוּפַיְיהוּ.","וּבְשַׁעֲתָא דְּאִנוּן פָּרְשֵׂי גַדְפַיְיהוּ, אִשְׁתְּמַע קוֹל גַּדְפִין דְּכֻלְהוּ דְּאָמְרֵי שִׁירָתָא, הֲדָא הוּא דִכְתִיב כְּקוֹל שַׁדַּי. דְּלָא אִשְׁתְּכִיךְ לְעָלְמִין. כְּמָה דִכְתִיב, (תהילים ל׳:י״ג) לְמַעַן יְזַמֶּרְךָ כָבוֹד וְלא יִדּוֹם. וּמַאי אָמְרֵי, (תהילים צ״ח:ב׳) הוֹדִיעַ יְיָ יְשׁוּעָתוֹ לְעֵינֵי הַגּוֹים גִּלָּה צִדְקָתוֹ.","קוֹל הֲמֻלָּה כְּקוֹל מַחֲנְה, כְּקוֹל מַשִּׁרְיָיתָא קַדִּישָׁא כַּד מִתְחַבְּרָן כָּל חֵילִין עִלָּאִין לְעֵילָא. וּמַאי אָמְרֵי קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְיָ צְבָאוֹת מְלא כָל הָאָרֶץ כְּבוֹדוֹ. אֲהַדְּרוּ לְדָרוֹם אָמְרוּ קָדוֹשׁ, אֲהַדְּרוּ לְצָפוֹן אָמְרוּ קָדוֹשׁ. אֲהַדְּרוּ לְמִזְרָח אָמְרוּ קָדוֹשׁ. אֲהַדְּרוּ לְמַעֲרָב אָמְרוּ בָּרוּךְ.","וְהַאי רָקִיעַ קָאִים עַל רֵישֵׁיהוֹן. וּבְכָל אֲתַר דְּאִיהִי אָזְלָא, אַסְחָרוּ אַפִּין לְהַהִיא סִטְרָא דְּאִתְכְּלִילוּ אַנְפִּין בֵּיהּ. אִסְחָרוּ אַנְפִּין לְאַרְבַּע זָוְיָין, וְכֻלְהוּ מִסְתַּחֲרִין לְתַתָּא.","בְּרִבּוּעָא דִילֵיהּ אִתְגְּלִיפַת בְּאַרְבַּע אַנְפִּין, אַנְפֵּי אַרְיֵה. אַנְפֵּי נִשְׁרָא. אַנְפֵּי שׁוֹר. אַנְפֵּי אָדָם. גָּלִיף בְּכֻלְהוּ אָדָם. אַנְפֵּי אַרְיֵ\"ה אָדָם. אַנְפֵּי נֶשֶׁ\"ר אָדָם. אַנְפֵּי שׁוֹ\"ר (ד\"א אדם). כֻּלְהוּ כְּלִילָן בֵּיהּ. וּבְגִין כָּךְ כְּתִיב וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם.","וְהַאי רָקִיעַ דְּאִתְרַבַּע כֻּלְהוּ גְּוָונִין כְּלִילָן בֵּיהּ, אַרְבַּע גְּוָונִין אִתְחַזְּיָין בֵּיהּ גְּלִיפִין בְּאַרְבַּע אַרְבַּע. בְּאַרְבַּע גְּלִיפִין רְשִׁימִין טְהִירִין עִלָּאִין וְתַתָּאִין. כַּד מִתְפָּרְשָׁאן גְּוָונִין דְּאִנוּן אַרְבַּע סָלְקִין תְּרֵיסַר. גַּוָון יָרֹק. גַּוָון סוּמָק. גַּוָּון חִוַּור. גַּוָון סַפִּיר דְאִתְכְּלִילוּ מִכָּל גְּוָונִין. הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:כ״ח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶּעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנּוֹגַהּ סָבִיב הוּא מַרְאֶה דְּמוּת כְּבוֹד יְיָ. חֵיזוּ דִּגְוָונִין דְּכֹלָּא. וּבְגִין כָּךְ אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן.","מַאי קַשְׁתִּי, כְּמָה דְאִתְּמָר בְּיוֹסֵף דִּכְתִיב, (בראשית מ״ט:כ״ד) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ. בְּגִין דְּיוֹסֵף צַדִּיק אִקְרֵי, וּבְגִין כָּךְ קַשְׁתּוֹ דָּא בְּרִית דְּקֶשֶׁת דְּאִתְכְּלִיל בְּצַדִּיק, דִּבְרִית דָּא בְּדָא אִתְאַחִיד. וּבְגִין דְּנֹחַ הֲוָה צַדִיק, קָיְימָא דִילֵיהּ קֶשֶׁת.","וַיָּפוֹזוּ. מַאי וַיָּפוֹזוּ, אַנְהִירוּ בַּחֲמִידוּ דְכֹלָּא. כְּמָא דְאַתְּ אָמֵר (תהילים י״ט:י״א) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וּמְתוּקִים. אִתְנְהִירוּ בִּנְהִירוּ עִלָּאָה כַּד נָּטַר בְּרִית. וּבְגִין כָּךְ אִקְרֵי יוֹסֵף הַצַּדִּיק. עַל דָּא אִקְרֵי הַקֶּשֶׁת בְּרִית, כָּלִיל דָּא בְּדָא.","זָהֲרָא יְקָרָא עִלָּאָה חֵיזוּ דְּכָל חֵיזוּ חָזוּ כְּחֵיזוּ טְמִירִין (נ\"א טמירא) גְּוָונִין טְמִירִין. גְּוָונִין דְּלָא אִתְגַּלְיָין. וְלֵית רְשׁוּ לְאִסְתַּכָּלָא בְּעֵינָא בַּקֶּשֶׁת כַּד אִתְחֲזֵי בְּעָלְמָא דְּלָא יִתְחֲזֵי קְלָנָא בִּשְׁכִינְתָּא. וְכֵן גְּוָונִין דְּקֶשֶׁת הוּא חֵיזוּ סוֹסְטִיפָא קְטִירָא כְּחֵיזוּ יְקָרָא עִלָּאָה דְּלָא לְאִסְתַּכָּלָא.","וְכֵיוָן דְּאַרְעָא חָמַאת לְהַאי קֶשֶׁת קְיָימָא קַדִּישָׁא, אִתְקָיְימַת בְּקִיּוּמָא. וְעַל דָּא וְהָיְתָה לְאוֹת בְּרִית בֵּין אֱלהִים וְגו'. הַאי דְּאֲמָרָן דְּאִלֵּין תְּלַת גְּוָונִין וְחַד דְּאִתְכְּלִיל בֵּינַיְיהוּ כֻּלְהוּ רָזָא חָדָא. וּבְגוֹ עֲנָנָא סָלְקָא לְאִתְחֲזָאָה.","(יחזקאל א׳:כ״ו) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר. הַאי הִיא אֶבֶן שְׁתִיָּה דְּאִיהִי נְקוּדָה חָדָא דְּכָל עָלְמָא. וְקָיְימָא עֲלָהּ קֹדֶשׁ הַקֳּדָשִׁים. וּמַאי הִיא, כֻּרְסְיָיא קַדִּישָׁא עִלָּאָה דְּאִיהִי מְמַנָּא עַל אִלֵּין אַרְבַּע דְּמוּת כִּסֵּא בְּאַרְבַּע סָמְכִין, וְדָא הוּא תּוֹרָה שֶׁבְּעַל פֶּה.","וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֶה אָדָם עָלָיו מִלְּמַעְלָה. דָּא הוּא תּוֹרָה שֶׁבִּכְתָב. מִכָּאן דְּתוֹרָה שֶׁבִּכְתָב יְשַׁוּוּן יָתָהּ עַל תּוֹרָה שֶׁבְּעַל פֶּה. בְּגִין דְּהַאי כֻּרְסְיָיא לְדָא, כְּמַרְאֵה אָדָם דְּאִיהוּ דִּיוּקְנָא דְּיַעֲקֹב דְּאִיהוּ יָתִיב עֲלָהּ."],[[0,"ובגין כך וכו':","ומשום זה כתוב ואתם פרו ורבו. דהיינו לעשות תולדות. הרי שגם הנקבות נתברכו. מכאן ולהלאה. שרצו בארץ. וכאן מסר להם הקב\"ה שבע מצות התורה, להם ולכל הבאים אחריהם, עד שעמדו ישראל על הר סיני, וניתן להם לישראל, כל מצות התורה ביחד. ואיך מרומזים כאן השבע מצות תמצא במסכת סנהדרין דף נ\"ו ע\"א."],[1,"ויאמר אלקים לנח וגו':","את קשתי נתתי בענן, המלה \u0003נתתי\u0004 מורה, שנתן מקודם לכן. פירוש, כי קשת ה\"ס אבן שתיה, כמ\"ש להלן, ואבן שתיה נתקנה עוד מטרם שנברא העולם שהרי עליה הושתת העולם. וע\"כ אומר הכתוב, \u0003נתתי,\u0004 שהוא לשון עבר, שמכבר נתן זאת."],[1,"ר\"ש פתח וכו':","כתוב, וממעל לרקיע וגו', מה כתוב למעלה מזה, ואשמע את קול כנפיהם וגו'. אלו הן ארבע חיות הגדולות העליונות הקדושות, שאותו הרקיע מתתקן עליהן. וכולן, כנפיהן מתחברות זו בזו, לכסות גופיהן. פירוש. הרקיע, ה\"ס הסיום של צמצום ב' הנקרא פרסא. (כמ\"ש בפתיחה אות ס\"ז) ואמר ר\"ש, שרקיע הזה מתתקן על ד' חיות הגדולות שהם חו\"ג תו\"מ. כמ\"ש לפנינו באות רס\"ג, רס\"ד ורס\"ה."],[2,"ובשעתא דאינון וכו':","ובשעה שהם פורשים כנפיהם, נשמע קול כנפיהם של כולם, שאומרים שירה. וז\"ש \u0003כקול שדי,\u0004 שאינו נדם לעולם, כמ\"ש, למען יזמרך כבוד ולא ידום. ושואל, ומה אומרים. ומשיב שאומרים, הודיע ה' ישועתו לעיני הגוים גלה צדקתו."],[3,"קול המולה כקול מחנה","פירושו, כקול מחנה הקדושה, כאשר מתחברים כל צבאות העליונים למעלה. ושואל מה אומרים, ומשיב שאומרים. קדוש קדוש קדוש ה' צבאות מלא כל הארץ כבודו: מחזירים עצמם לדרום אומרים קדוש, מחזירים עצמם לצפון אומרים קדוש, מחזירים עצמם למזרח אומרים קדוש, מחזירים עצמם למערב אומרים ברוך."],[3,"","ביאור הדברים. ר\"ש מבאר ב' מיני הקול שבהכתוב. ואומר \u0003דההוא רקיע מתתקנא עלייהו.\u0004 שהתיקון צמצום ב' שבהמלכות הנק' רקיע, (כנ\"ל באות רס\"א) מתתקן על החיות ומסבה זו נכללת ב' הנקודות שבהמלכות בגוף החיות, שהן מפתחא ומנעולא, (כנ\"ל בהקדמת הזהר ד ף קכ\"ג אות קכ\"ב ד\"ה ב') ולפיכך יש בהם ב' בחינת קול. א) קול ממותק הבינה, אשר נקודה דמנעולא נגנזת ונעלמת לגמרי, ורק הנקודה דמפתחא נגלית בהם. וע\"כ \u0003גדפייהו מתחבראן דא בדא לחפייא גופייהו,\u0004 דהיינו לכסות בחינת הדין הוכלל בגופם מבחינת מנעולא שבהם. ואז נבחן קולם בסוד \u0003קול המולה כקול מחנה.\u0004 ואז מתפשטים בהם המוחין שה\"ס ג\"פ קדוש, בסוד ג' קוין שה\"ס דרום צפון מזרח, (כנ\"ל ב\"א דף שט\"ז אות תי\"ג). ומערב שה\"ס מלכות מקבלת ג' קדושות הללו, ובחינתה עצמה ה\"ס ברוך כבוד ה' ממקומו, וד' בחינות הללו מאירים בהחיות, בסו\"ה \u0003והחיות רצוא.\u0004 ב) הוא \u0003קול גדפין\u0004 דהיינו \u0003בשעתא דאינון פרשי גדפייהו,\u0004 שכנפיהם פרודות, ואינן מכסות על גופם, שאז נשמע קול בחינת הדין הכלול בגופם ובכנפיהם, אשר קול זה אינו נמתק בהבינה. מחמת הדין הנשמע בתוכו. ולפיכך נוהג בו מיתוק אחר. והוא, כי מבחינת הדין הזה מתתקן המסך דחירק, שעליו יוצא קו האמצעי המכריע בין ב' הקוין. (כנ\"ל בראשית א' דף מ\"ח ד\"ה נפק) וכל עוד שלא נעשה הזווג על מסך הזה, יש מחלוקת בין הקוין ואינם מאירים, כמ\"ש שם. נמצא שכל הארת הקוין תלויה על בחינת הדין הזה הכלול בהמסך, והוא הגורם להם, ע\"כ הוא חשוב כמוהם אע\"פ שהוא דין. ועל זה הקול אומר הכתוב \u0003ואשמע את קול כנפיהם כקול מים רבים,\u0004 דהיינו הדינים המכונים מים רבים, \u0003כקול שדי בלכתן,\u0004 שפירושו, \u0003דלא אשתכך לעלמין,\u0004 על דרך הכתוב \u0003למען יזמרך כבור ולא ידום.\u0004 כלומר, כי קול זה אע\"פ שנשמע בו בחינת דין, מ\"מ חשוב מאד, כי מעת הגלותו, נעשה הכרעה בין הקוין, והמוחין מאירים על ידו, והכבוד אינו נדם עוד לעולם. וזסו\"ה לעיני \u0003הגוים גלה צדקתו,\u0004 כי אע\"פ שהוא \u0003לעיני הגוים,\u0004 כלומר שיש בו בחינת דין, מ\"מ הוא חשוב מאד, כי \u0003גלה צדקתו,\u0004 שעל ידו נגלו המוחין, וזולתו לא היו מוחין בזו\"ן, כנ\"ל."],[4,"והאי רקיע וכו':","ורקיע זה עומד על ראשם, ובכל מקום שהחיה הולכת משיבה פניה לאותו הצד שד' הפנים נכללות בו. כלומר שד' הפנים של החיות נכללות זו בזו ויש בפני אריה כל ד' הפנים. וכן בפני שור כל ד' הפנים וכו'. וההפרש ביניהם, שאותו הצד שהפנים נכללות בו, הוא השולט, ורק לאותו הצד משיבה פניה, אם נכללים בפני אריה, הרי פני אריה השולט, שהוא צד הדרום. ואם בפני שור, צד הצפון שולט, וכו'. וכן הן משיבות פניהם לארבע הזויות כלומר לארבע הרוחות וכולן מוחזרות ומתפשטות למטה. דהיינו מחזה ולמטה. פירוש. החיות בכללן נמשכות מחצוניות המלכות דהיינו רק מבחינת נהי\"מ שלה. אבל עכ\"ז יש בהחיות עצמן חג\"ת נהי\"מ, אשר חג\"ת שבהם נקראים חיות עליונות הקדושות, (כמ\"ש באות רס\"א) \u0003אלין ארבע חיוון רברבן עלאין קדישין.\u0004 ואומר כאן עליהם, \u0003וכלהו מסתחרין לתתא,\u0004 שהן גם מוחזרות ומתפשטות לבחינת נהי\"מ, שהם בחינת מחזה ולמטה. ואלו נקראים חיות קטנות. (כנ\"ל ב\"ב דף פ\"ג ד\"ה מנציצו ע\"ש.) וההפרש שביניהם יתבאר לפנינו."],[5,"ברבועא דיליה וכו':","בארבעה צדדים שבו, שהם דרום צפון מזרח מערב, שבהרקיע, נחקקו החיות בארבע פנים. פני אריה לצד דרום, פני שור לצר צפון, פני נשר לצד מזרח, פני אדם לצד מערב. וחקוק בכולם פני אדם: בפני אריה חקוק אדם, בפני נשר אדם, בפני שור אדם. כי כולן כלולות בו, בפני אדם. ומשום זה כתוב, ודמות פניהם פני אדם. שמשמע שיש לכל אחת מהן פני אדם."],[6,"והאי רקיע דאתרבע וכו':","והרקיע הזה שנעשה רבוע לד' צדדין דרום וכו' כל הצבעים כלולים בו. ארבעה צבעים נראים בו, שהם, לבן, אדום, ירוק, ושחור, חקוקים כל אחד בארבעה ארבעה. כלומר שכל אחד מהם כלול מכולם. באופן, שהם \u0003ט\"ז גוונין.\u0004"],[6,"בארבע גליפין וכו':","בארבע חקיקות רשומים העליונים, שהם חיות דחג\"ת. והתחתונים שהם חיות דנהי\"מ. כאשר מתפשטים הגוונים של אלו הארבעה, דהיינו של החיות דנהי\"מ. הם עולים שנים עשר גוונים, ולא ששה עשר גוונים, כמו החיות דחג\"ת: שהם גוון ירוק, גוון אדום, גוון לבן, גוון ספיר שנכלל מכל ג' הגוונים. כלומר שגוון ספיר שהיא המלכות אינו גוון בפני עצמו אלא הוא מקבל בתוכו כל ג' הגוונין, וע\"כ אין כאן רק ד\"פ ג' גוונין שהם, \u0003י\"ב גוונים.\u0004 וז\"ש כמראה הקשת וגו' שבו ג' גוונים. כן מראה הנגה סביב הוא מראה דמות כבוד ה', דהיינו המלכות, הוא מראה של כל ג' הגוונין. כלומר שבמלכות עצמה אין שום גוון, אלא שכלולה מג' הגוונים. ומשום זה כתוב את קשתי נתתי בענן."],[6,"","פירוש. כי החיות הן חג\"ת ונהי\"מ, ונודע כי רק במחזה ולמעלה נמצאת המלכות, שהם בחיות דחג\"ת. וע\"כ יש שם ארבעה גוונין. דהיינו גם גוון שחור, ובהתכללותם זה בזה יש בהן ט\"ז גוונין. מה שאין כן במחזה ולמטה שעצמות המלכות נעלמת שם (כנ\"ל ב\"ב דף מ\"ו ד\"ה ביאור) וע\"כ יש שם רק ג' גוונין לבן אדום ירוק, והמלכות היא בסוד גוון ספיר שכולל אותם הג' גוונין, דהיינו מה שמקבלת מהם, והגוון של עצמה נעלם. וע\"כ כשנכללים זה בזה, אין שם רק ד' בחינות שבכל אחת ג' גוונין, שהם י\"ב גוונין. וזהו שמסיים, \u0003ובגין כך כתוב ואת קשתי נתתי בענן,\u0004 שנראה בהענן רק ג' גוונין לבד, לבן אדום ירוק, וגוון עצמותה שהוא שחור, אינו נראה שם. וצריך שתדע, שגוון ירוק הנאמר בכ\"מ שהוא גוון קו אמצעי היינו ירוק כאור החמה ולא ירוק ככרתי."],[7,"מאי קשתי וכו':","שואל, מהו קשתי. ואומר שהוא כמו שנאמר ביוסף, ותשב באיתן קשתו. שקשתו הוא מלכות, אלא משום שיוסף נקרא צדיק, שהוא בחינת יסוד, ומשום זה, הקשת שלו הוא ברית דקשת, דהיינו יסוד דמלכות. כי ברית הוא יסוד, וקשת מלכות, כי נכלל בצדיק, כי ברית זה, יסוד, נתאחד בזה בהקשת. פירוש. קשת הוא מלכות, כמ\"ש הזהר (ויחי אות תשע\"ו) על הכ' ותשב באיתן קשתו, ששואל שם, מהו קשת, ומשיב, דא בת זוגו. דהיינו מלכות, שהיא בת זוגו דיסוד. אלא שמסתפק כאן, כיון שהכתוב אומר כאן, וראיתיה לזכור ברית עולם, הרי משמע שהקשת הוא \u0003ברית,\u0004 שהוא יסוד. וע\"כ שואל כאן, מהו קשתי. ומשיב, \u0003קשתו, דא ברית דקשת,\u0004 כלומר, לא מלכות ממש אלא יסוד דמלכות, כי על ידי מיתוקה של המלכות בהבינה נאבדה בחינת עצמותה דמלכות, כי נגנזה ברדל\"א, וא\"א יצא בט\"ס הסר מלכות, אלא עטרת יסוד, הוא המלכות שלו, וה\"ס נקודה דמפתחא (לעיל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' ע\"ש) ועטרת יסוד נבחנת כמו יסוד דמלכות, ומלכות דמלכות חסרה. וז\"ש \u0003דאתכליל בצדיק,\u0004 שע\"כ הוא רק יסוד דמלכות, משום שנכללה בהיסוד שנעשית לעטרת יסוד, \u0003דברית דא בדא אתאחיד,\u0004 שהיסוד שנקרא ברית נתאחד בהקשת, וע\"כ נקרא גם הקשת בהכתוב בשם \u0003ברית,\u0004 דהיינו לזכור ברית עולם, כי \u0003ובגין דנח הוה צדיק, קיימא דיליה קשת,\u0004 כי משום שנה היה צדיק, נעשה הברית שלו בסוד הקשת, כי נכלל בו. וע\"כ קוראו הכתוב בשם ברית. ובזה תבין מ\"ש לעיל (בראשית א' דף ע\"ה אות ע') אשר הקשת זה חי עלמין בענן דא מלכות. כי הקשת נבחן ליסוד דמלכות, וע\"כ אומר עליו חי עלמין, וענן נבחן למלכות דיסוד, וע\"כ אומר עליו דא מלכות. ושיעור הכתוב את קשתי נתתי בענן, פירושו, שנתן יסוד דמלכות במלכות דיסוד, ונמתקו זה בזה בסוד מפתחא כנ\"ל, ואז מתגלים עליה כל המוחין לקיום העולם, וז\"ש וראיתיה לזכור ברית עולם."],[8,"ויפוזו מאי ויפוזו וכו':","שואל מה פירושו של ויפוזו זרועי ידיו. ואומר, שהאירו ידיו אור הנחמד לכל כמו זהב ופז, כמש\"א, הנחמדים מזהב ופז רב ומתוקים וגו'. נאורו ידיו באור העליון כאשר שמר הברית. פירוש. כיון שזכה לברית דקשת, כמ\"ש ותשב באיתן קשתו, שפירושו \u0003מפתחא,\u0004 כנ\"ל, ע\"כ זכה על ידיה למוחין העליונים, וידיו, שהן חסד וגבורה, \u0003נפוזו,\u0004 דהיינו שנעשו לחכמה ובינה, שעליהם אומר הכתוב הנחמדים וכו'. \u0003ובגין כך אקרי יוסף הצדיק\u0004 ומשום זה שזכה לברית נקרא יוסף הצדיק. \u0003על דא אקרי הקשת ברית, כליל דא בדא,\u0004 ועל כן נקראת הקשת בשם ברית, משום שכלולים זה בזה. כמו שנתבאר לעיל בדיבור הסמוך."],[9,"ודא זהרא וכו':","וזה הקשת הוא זהר כבוד העליון, מראה כל המראות. דהיינו מלכות, הנקראת כבוד העליון, ובה כל המראות (כנ\"ל בראשית א' דף ע\"ד אות ס\"ט) היא מראה. כמראה אורות הנסתרים, שהם גוונין נסתרים, גוונין שלא נגלו. כלומר אלו ג' גוונים, לבן אדום וירוק, שהם חג\"ת, שאורותיהם מכוסים ונעלמים למעלה מחזה, נתגלה \u0003המראה\u0004 בהקשת. כנ\"ל בראשית א' דף ע\"ז אות ע\"א וע\"ב ע\"ש בהסולם)."],[9,"ולית רשו וכו':","ואין רשות להעין להסתכל בקשת כשהוא נראה בעולם, שלא יראה דופי בהשכינה, פירוש כי אע\"פ שקשת ה\"ס מפתחא, ואין בה מדת הדין, מ\"מ גם מדת הדין גנוזה בה, ועל ידי הסתכלות שפירושו, המשכת האור ממעלה למטה, נעשה גילוי למידת הדין, כמ\"ש לעיל (בהקדמת הזהר דף קכ\"ג אות קכ\"ב) \u0003לא זכי הא רע,\u0004 עש\"ה. וז\"ס שאסור להסתכל בקשת, \u0003וכן גוונין דקשת הוא חיזו סוסטיפא קטירא,\u0004 וכן הגוונים של הקשת קשורים הם במראה ערפל וענן, שזה יורה שהם \u0003מכוסים,\u0004 כמראה כבוד העליון, שלא להסתכל בה."],[10,"וכיון דארעא וכן':","וכיון שהארץ רואה את הקשת, כלומר, שהמלכות הנקראת ארץ, מתתקנת מבחינת הקשת, שפירושו מפתחא כנ\"ל. נמצא ברית הקדוש מתקיים בקיומו, דהיינו שמשפיע לה המוחין עלאין, וע\"כ, והיתה לאות ברית וגו'. מה שאמרנו לעיל (באות רס\"ו) שאלו הם ג' גוונין לבן, אדום, ירוק, וגוון אחד הוא הנכלל ביניהם, כולם הם סוד אחד. כלומר שגם הקשת הוא מג' גוונין וגוון הכולל את הג', והקשת עולה בתוך הענן כדי להראות. כי אינו נראה רק בתוך הענן."],[11,") וממעל לרקיע וגו':","כמראה אבן ספיר, זה אבן ספיר. הוא אבן שתיה, שהיא נקודה אחת שכל העולם עומד עליה, דהיינו נקודה דמפתחא, ועליה עומד קדש הקדשים, ומה היא, הנקודה, היא כסא הקדוש העליון. שהיא ממונה על אלו ארבע גוונין הנ\"ל, והוא דמות כסא בארבע אדנים, כלומר ד' הגוונין לבן אדום ירוק ספיר נעשו לה ד' אדנים. וזה הכסא הוא תורה שבעל פה. דהיינו המלכות."],[12,"ועל דמות הכסא דמות כמראה אדם וגו':","זה הוא תורה שבכתב, שהוא ז\"א, מכאן נשמע, שמשימים תורה שבכתב על תורה שבעל פה, משום שזה כסא לזה. כמראה אדם הוא צורתו של יעקב, שהוא ז\"א, שהוא יושב עליו."]],[[0,"","וְלָכֵן כָּתוּב וְאַתֶּם פְּרוּ וּרְבוּ, לַעֲשׂוֹת תּוֹלָדוֹת מִכָּאן וָהָלְאָה, שִׁרְצוּ בָאָרֶץ. וְכָאן נָתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁבַע מִצְווֹת הַתּוֹרָה וּלְכָל הַבָּאִים אַחֲרֵיהֶם, עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי וְנִתְּנוּ לָהֶם כָּל מִצְווֹת הַתּוֹרָה כְּאֶחָד."],[1,"","וַיֹּאמֶר אֱלֹהִים לְנֹחַ וְגוֹ', זאת אוֹת הַבְּרִית אֲשֶׁר אֲנִי נֹתֵן בֵּינִי וּבֵינֵיכֶם וְגוֹ', אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. נָתַתִּי - מִקֹּדֶם לָכֵן. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. מַה כָּתוּב לְמַעְלָה? וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים כְּקוֹל שַׁדַּי בְּלֶכְתָּן. אֵלּוּ אַרְבַּע חַיּוֹת גְּדוֹלוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת שֶׁאוֹתוֹ הָרָקִיעַ מְתֻקָּן עֲלֵיהֶם. וְכָל הַכְּנָפַיִם (נפרדות) מִתְחַבְּרוֹת זוֹ בָּזוֹ לְכַסּוֹת אֶת גּוּפָם."],[2,"","וּבְשָׁעָה שֶׁהֵם פּוֹרְשִׂים כַּנְפֵיהֶם, נִשְׁמָע קוֹל הַכְּנָפַיִם שֶׁלְּכֻלָּם שֶׁאוֹמְרִים שִׁירָה. זֶהוּ שֶׁכָּתוּב כְּקוֹל שַׁדַּי, שֶׁלֹּא שׁוֹכֵךְ לְעוֹלָמִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ל) לְמַעַן יְזַמֶּרְךְ כָבוֹד וְלֹא יִדּוֹם. וּמָה אוֹמְרִים? (שם צח) הוֹדִיעַ ה' יְשׁוּעָתוֹ לְעֵינֵי הַגּוֹיִם גִּלָּה צִדְקָתוֹ."],[3,"","קוֹל הֲמֻלָּה כְּקוֹל מַחֲנֶה, כְּקוֹל מַחֲנֶה קָדוֹשׁ כְּשֶׁמִּתְחַבְּרִים כָּל הַצְּבָאוֹת הָעֶלְיוֹנִים לְמַעְלָה. וּמָה אוֹמְרִים? קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. חוֹזְרִים לַדָּרוֹם, אוֹמְרִים קָדוֹשׁ. חוֹזְרִים לַצָּפוֹן, אוֹמְרִים קָדוֹשׁ. חוֹזְרִים לַמִּזְרָח, אוֹמְרִים קָדוֹשׁ. חוֹזְרִים לַמַּעֲרָב, אוֹמְרִים בָּרוּךְ."],[4,"","וְהָרָקִיעַ הַזֶּה עוֹמֵד עַל רָאשֵׁיהֶם. וּבְכָל מָקוֹם שֶׁהִיא הוֹלֶכֶת, מְסוֹבְבִים פָּנִים לְאוֹתוֹ צַד שֶׁנִּכְלָלִים הַפָּנִים בּוֹ. מְסוֹבֵב פָּנָיו לְאַרְבָּעָה רוּחוֹת, וְכֻלָּם מִסְתּוֹבְבִים לְמַטָּה."],[5,"","בָּרִבּוּעַ שֶׁלּוֹ נֶחְקֶקֶת בְּאַרְבַּע פָּנִים: פְּנֵי אַרְיֵה, פְּנֵי נֶשֶׁר, פְּנֵי שׁוֹר, פְּנֵי אָדָם. חָקוּק בְּכֻלָּם אָדָם. פְּנֵי אַרְיֵ\"ה אָדָם. פְּנֵי נֶשֶׁ\"ר אָדָם. פְּנֵי שׁוֹ\"ר (אדם). כֻּלָּם כְּלוּלִים בּוֹ. וְלָכֵן כָּתוּב וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם."],[6,"","וְהָרָקִיעַ הַזֶּה שֶׁהִתְרַבַּע, כָּל הַגְּוָנִים כְּלוּלִים בּוֹ. אַרְבָּעָה גְוָנִים נִרְאִים בּוֹ חֲקוּקִים בְּאַרְבַּע אַרְבַּע. בְּאַרְבָּעָה חִקּוּקִים רְשׁוּמִים אוֹרוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים. כְּשֶׁנִּפְרָדִים הַגְּוָנִים שֶׁל אוֹתָם אַרְבַּע, עוֹלִים שְׁנֵים עָשָׂר. גָּוֶן יָרֹק. גָּוֶן אָדם. גָּוֶן לָבָן. גָּוֶן סַפִּיר שֶׁנִּכְלְלוּ מִכָּל הַגְּוָנִים. זֶהוּ שֶׁכָּתוּב (יחזקאל א) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד ה'. הַמַּרְאֶה שֶׁל כָּל הַגְּוָנִים, וְלָכֵן אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן."],[7,"","מַה זֶּה קַשְׁתִּי? כְּמוֹ שֶׁנֶּאֱמַר בְּיוֹסֵף, שֶׁכָּתוּב (בראשית מט) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ, מִשּׁוּם שֶׁיּוֹסֵף נִקְרָא צַדִּיק. וְלָכֵן קַשְׁתּוֹ, זוֹ בְּרִית שֶׁל הַקֶּשֶׁת שֶׁנִּכְלֶלֶת בְּצַדִּיק, שֶׁהַבְּרִית זֶה עִם זֶה נֶאֱחָז. וּמִשּׁוּם שֶׁנֹּחַ הָיָה צַדִּיק, הַבְּרִית שֶׁלּוֹ קֶשֶׁת."],[8,"","וַיָּפֹזּוּ, מַה זֶּה וַיָּפֹזּוּ? הֵאִירוּ בְּחֶמְדַּת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפַּז רָב וּמְתוּקִים. הוּאֲרוּ בְּאוֹר עֶלְיוֹן כְּשֶׁשָּׁמַר הַבְּרִית. וְלָכֵן נִקְרָא יוֹסֵף הַצַּדִּיק. וְעַל זֶה הַקֶּשֶׁת נִקְרֵאת בְּרִית, כּוֹלֵל זֶה בָּזֶה."],[9,"","זֹהַר נִכְבָּד עֶלְיוֹן הַמַּרְאֶה שֶׁל כָּל הַמַּרְאוֹת, מַרְאֶה כְּמַרְאֶה טְמוּנִים (נ\"א: טמון) הַגְּוָנִים הַטְּמוּנִים. הַגְּוָנִים שֶׁלֹּא הִתְגַּלּוּ. וְאֵין רְשׁוּת לְהִסְתַּכֵּל בָּעַיִן בַּקֶּשֶׁת כְּשֶׁנִּרְאֵית בָּעוֹלָם, שֶׁלֹּא יִתְרָאֶה קָלוֹן בַּשְּׁכִינָה. וְכֵן גּוֹנֵי הַקֶּשֶׁת הוּא מַרְאֶה מוּצָק קָשׁוּר כְּמַרְאֵה כָּבוֹד הָעֶלְיוֹן שֶׁלֹּא לְהִסְתַּכֵּל."],[10,"","וְכֵיוָן שֶׁהָאָרֶץ רָאֲתָה אֶת הַקֶּשֶׁת הַזּוֹ, בְּרִית קְדוֹשָׁה, הִתְקַיְּמָה בְּקִיּוּם. וְעַל זֶה וְהָיְתָה לְאוֹת בְּרִית בֵּין אֱלֹהִים וְגוֹ'. זֶה שֶׁאָמַרְנוּ שֶׁאֵלּוּ שְׁלֹשֶׁת הַגְּוָנִים וְאֶחָד שֶׁנִּכְלָל בֵּינֵיהֶם כֻּלָּם סוֹד אֶחָד, וּבְתוֹךְ הֶעָנָן עוֹלֶה לְהֵרָאוֹת."],[11,"","(יחזקאל א) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר - זוֹהִי אֶבֶן הַשְּׁתִיָּה שֶׁהִיא נְקֻדָּה אַחַת שֶׁל כָּל הָעוֹלָם וְעוֹמֵד עָלֶיהָ קֹדֶשׁ הַקְּדָשִׁים, וּמַהִי? הַכִּסֵּא הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁמְּמֻנֶּה עַל אַרְבָּעָה אֵלֶּה דְּמוּת כִּסֵּא בְּאַרְבָּעָה עַמּוּדִים, וְזוֹהִי תוֹרָה שֶׁבְּעַל פֶּה."],[12,"","וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה - זוֹהִי תוֹרָה שֶׁבִּכְתָב. מִכָּאן שֶׁתּוֹרָה שֶׁבִּכְתָב יָשִׂימוּ אוֹתָהּ עַל תּוֹרָה שֶׁבְּעַל פֶּה, מִשּׁוּם שֶׁזֶּה כִּסֵּא לָזֶה. כְּמַרְאֵה אָדָם, שֶׁהוּא הַדְּמוּת שֶׁל יַעֲקֹב שֶׁהוּא יוֹשֵׁב עָלֶיהָ."]]],[["רַבִּי יְהוּדָה קָם לֵילְיָא חַד לְמִלְעֵי בְּאוֹרַיְיתָא בְּפַלְגוּ לֵילְיָא בְּבֵי אוּשְׁפִּיזָא בְּמָתָא מַחְסֵיָא. וְהֲוָה תַּמָּן בְּבֵיתָא חַד יוּדָאי דְּאֲתָא בִּתְרֵי קְסִירָא דְקַטְפִירָא. פָּתַח רַבִּי יְהוּדָה וְאָמַר (בראשית כ״ח:כ״ב) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים. דָּא הִיא אֶבֶן שְׁתִיָּה דְּמִתַּמָּן אִשְׁתִּיל עָלְמָא וְעֲלָה אִתְבְּנֵי בֵּי מַקְדְּשָׁא.","זָקַף רֵישֵׁיהּ הַהוּא יוּדָאי וְאֲמַר לָהּ הַאי מִלָּה אֵיךְ אֶפְשָׁר, וְהָא אֶבֶן שְׁתִיָּה עַד לָא אִתְבְּרֵי עָלְמָא הֲוַת וּמִינָהּ אִשְׁתִּיל עָלְמָא, וְאַתְּ אֲמַרְתְּ וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. דְּמַשְׁמַע דְּיַעֲקֹב שַׁוֵי לָהּ הַשְׁתָּא דִּכְתִיב, (בראשית כ״ח:כ״ב) וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מֵרַאֲשׁוֹתָיו. וְתוּ דְּיַעֲקֹב בְּבֵית אֵל הֲוָה וְהַאי אַבְנָא הֲוַת בִּיְרוּשָׁלַ ם.","רַבִּי יְהוּדָה לָא אַסְחַר רֵישֵׁיהּ לְגַבֵּיהּ, פָּתַח וְאָמַר (עמוס ד׳:י״ב) הִכּוֹן לִקְרַאת אֱלקֶיךָ יִשְׂרָאֵל. וּכְתִיב, (דברים כ״ז:ט׳) הַסְכֵּת וּשְׁמַע יִשְׂרָאֵל. מִלֵּי דְאוֹרַיְיתָא בָּעְיָין כַּוָּונָה. וּמִלִּין דְּאוֹרַיְיתָא בָּעָאן לְאִתְתַּקָּנָא בְּגוּפָא וּרְעוּתָא כְּחֲדָא. קָם הַהוּא יוּדָאי וְאִתְלַבַּשׁ, וְיָתִיב לְגַבֵּיהּ דְּרַבִּי יְהוּדָה, וְאָמַר זַכָּאִין אַתּוּן צַדִּיקַיָא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יוֹמָא וְלֵילֵי.","אָמַר לֵיהּ רַבִּי יְהוּדָה הַשְׁתָּא דְּכַוְונַת גַּרְמָךְ, אֵימָא מִילָךְ דְּנִתְחַבֵּר כְּחֲדָא. דְּהָא מִלֵּי דְאוֹרַיְיתָא בָּעְיָין תִּקּוּנָא דְגוּפָא וְתִקּוּנָא דְלִבָּא. וְאִי לָאו בְּעַרְסָאי שְׁכִיבְנָא וּבְלִבָּאי אָמַרְנָא מִלִּין. אֶלָּא הָא תָּנִינָן דְּאָפִילּוּ חַד דְּיָתִיב וְלָעֵי בְּאוֹרַיְיתָא שְׁכִינְתָּא אִתְחַבְּרַת בַּהֲדֵיהּ, וּמַה שְּׁכִינְתָּא הָכָא וְאֲנָא שָׁכִיב בְּעַרְסָאי. וְלָא עוֹד אֶלָּא דְּבַעֲיָין צַחוּתָא.","וְתוּ דְּכָל בַּר נָשׁ (אחרי מות סז א) דְּקָם לְמִלְעֵי בְּאוֹרַיְיתָא מִפַּלְגוּ לֵילְיָא כַּד אִתְעַר רוּחַ צָפוֹן (בפלגו דליליא) קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָא בְּגִנְתָּא דְעֵדֶן. וְהוּא וְכָל צַדִּיקַיָיא דִּבְגִנְתָּא כֻּלְהוּ צַיְיתִין (ליה וצייתין) לְאִלֵּין מִלִּין דְּנָפְקֵי מִפּוּמֵיהּ. וּמַה קוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָּיא מִתְעַדְּנִין לְמִשְׁמַע מִלֵּי דְאוֹרַיְיתָא בְּשַׁעֲתָא דָּא וְאֲנָא אֱהֵא שָׁכִיב בְּעַרְסָאי. אָמַר לֵיהּ הַשְׁתָּא אֵימָא מִילָךְ.","אָמַר לֵיהּ שְׁאֵילְנָא עַל מַה דְּאֲמַרְתְּ בִּפְסוּקָא דָא (רזא דאבן שתיה דאמרת) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלהִים דְּדָא אֶבֶן שְׁתִיָה. (השתא דציית למלי) הֵיךְ אֶפְשָׁר, דְּהָא אֶבֶן שְׁתִיָּה עַד לָא אִתְבְּרֵי עָלְמָא הֲוַת וּמִנָּהּ אִשְׁתִּיל עָלְמָא, וְאַתְּ אֲמַרְתְּ אֲשֶׁר שַׂמְתִּי, דְּמַשְׁמַע דְּיַעֲקֹב שַׁוֵּי לָהּ הַשְׁתָּא. וּכְתִיב וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מֵרַאֲשׁוֹתָיו.","וְתוּ דְּיַעֲקֹב בְּבֵית אֵל הֲוָה וְאַבְנָא דָא הֲוַת בִּיְרוּשָׁלַם. אָמַר לֵיהּ כָּל אַרְעָא דְיִשְׂרָאֵל אִכְפַּל תְּחוֹתוֹי וְהַהוּא אֶבֶן תְּחוֹתֵיהּ הֲוַת. אָמַר לֵיהּ אֲשֶׁר שָׂם כְּתִיב. וּכְתִיב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. אָמַר לֵיהּ אִי יָדַעְתְּ מִלָּה אֵימָא לָהּ.","פָּתַח וְאָמַר, (תהילים י״ז:ט״ו) אֲנִי בְצֶדֶק אֶחזֶה פָנֶיךָ אֶשְׂבְּעָה בְהָקִיץ תְּמוּנָתֶךָ. דָּוִד מַלְכָּא חֲבִיבוּתָא וּדְבֵקוּתָא דִילֵיהּ בְּהַאי אֶבֶן הֲוָה. וְעֲלָהּ אָמַר (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְכַד בָּעָא לְאִסְתַּכְּלָא בְּחִיזוּ יְקָרָא דְמָרֵיהּ, נְטַל לְהַאי אֶבֶן בִּידֵיהּ בְּקַדְמִיתָא וּלְבָתַר עָיִיל.","בְּגִין דְּכָל מַאן דְּבָעֵי לְאִתְחֲזָאָה קַמֵּי מָרֵיהּ, לָא אָעִיל אֶלָּא בְּהַאי אֶבֶן. דִּכְתִיב, (ויקרא יג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. וְדָוִד מְשַׁבַּח גַּרְמֵיהּ וְאָמַר אֲנִי בְּצֶדֶק אֶחזֶה פָנֶיךָ. וְכָל אִשְׁתַּדְּלוּתֵיהּ דְּדָוִד לְאִתְחֲזָאָה בְּהַאי אֶבֶן כְּדְקָא יְאוּת לְגַבֵּי דִּלְעֵילָא.","תָּא חֲזֵי, אַבְרָהָם אַתְקִין צְלוֹתָא דְצַפְרָא וְאוֹדַע טִיבוּ דְמָארֵיהּ בְּעָלְמָא. וְאַתְקִין הַהִיא שַׁעֲתָא בְּתִקּוּנָהָא כְּדְקָא יָאוֹת דִּכְתִיב, (בראשית כ״ב:ג׳) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. יִצְחָק אַתְקִין צְלוֹתָא דְמִנְחָה וְאוֹדַע בְּעָלְמָא דְּאִית דִּין וְאִית דַּיָּין דְּיָכוֹל לְשֵׁזָבָא וּלְמֵידַן עָלְמָא.","יַעֲקֹב אַתְקִין צְלוֹתָא דְעַרְבִית, וּבְגִין צְלוֹתָא דָא דְּאַתְקִין מַה דְּלָא אַתְקִין בַר נָשׁ מִקַּדְמַת דְּנָא כְּדְקָא יְאוּת. בְגִין כָּךְ שַׁבַּח גַּרְמֵיהּ וְאָמַר וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. דְּעַד הַהִיא שַׁעֲתָא לָא שַׁוִּי לָהּ אָחֳרָא כַּוָּותֵיהּ."],[[0,"רבי יהודה קם וכו':","ר\"י קם משנתו בלילה אחד לעסוק בתורה, בחצות לילה, באכסניא, בעיר מתא מחסיא. והיה שם בהבית יהודי אחד, שבא בשני שקים עם מלבושים למכור. פתח ר\"י ואמר, והאבן הזאת אשר שמתי מצבה יהיה בית אלקים, זו האבן, היא אבן שתיה, שמשם נשתל העולם, ועליה נבנה בית המקדש."],[1,"זקף רישיה וכו':","זקף ראשו אותו היהודי ואמר לו, דבר זה איך אפשר, והרי אבן שתיה היה מקודם שנברא העולם. וממנה נשתל העולם. ואתה אומר, והאבן הזאת אשר שמתי מצבה, שמשמע, שיעקב שם אותה עתה למצבה, ועד עתה לא היתה כתקונה. שכתוב ויקח את האבן אשר שם מראשותיו. והרי אבן שתיה מתוקנת עוד מקודם שנברא העולם, ועוד הרי יעקב בבית אל היה, ואבן ההיא שתיה היתה בירושלם. כי היא עומדת במקום המקדש, שהוא בירושלם."],[2,"ר' יהודא לא אסחר וכו':","ר\"י לא החזיר ראשו אליו. פתח ר\"י ואמר הכון לקראת אלקיך ישראל. וכתוב הסכת ושמע ישראל. כי דברי תורה צריכים כוונה, וצריכים להתתקן בגוף וברצון כאחד. קם אותו היהודי ונתלבש, וישב אצל ר\"י, ואמר, אשריכם צדיקים שאתם עוסקים בתורה יום ולילה."],[3,"א\"ל רבי יהודה וכו':","אמר לו ר\"י, עתה שכוונת עצמך, אמור דבריך, ונתחבר יחד, כי דברי תורה צריכים תקון הגוף, ותקון הלב, ואם לא זה, הייתי שוכב, במטתי והרהרתי הדברים בלבי. אלא הרי למדנו, שאפילו אחד היושב ועוסק בתורה, השכינה מתחברת עמו. ואם השכינה כאן, ואני אהיה שוכב במטתי. ולא עוד. אלא שדברי תורה צריכים צחות, והשוכב במטתו אין דעתו צחה."],[4,"ותו דכל ב\"נ וכו':","ועוד, שכל איש הקם לעסוק בתורה מחצות לילה ואילך, כאשר נתעורר רוח הצפוני, הקב\"ה נכנס אז להשתעשע עם הצדיקים בגן עדן, והוא עם כל הצדיקים שבגן, כולם מקשיבים לאלו הדברים היוצאים מפיו. ואם הקב\"ה וכל הצדיקים מתעדנים לשמוע דברי תורה בשעה זו, ואני אהיה שוכב במטתי. אמר לו ר\"י להיהודי עתה אמור דבריך."],[5,"א\"ל שאילנא וכו':","אמר לו שאלתי על מה שאמרת בפסוק הזה, והאבן הזאת וגו', שהוא אבן שתיה, איך אפשר זה, הרי אבן שתיה מקודם שנברא העולם היה, וממנה נשתל העולם, ואתה אומר \u0003אשר שמתי,\u0004 שמשמע שיעקב שם אותה עתה. וכן כתוב, ויקח האבן אשר שם מראשותיו."],[6,"ותו דיעקב וכו':","ועוד, יעקב היה בבית אל, ואבן זו היתה בירושלם. אמר לו, שקפל תחתיו כל ארץ ישראל, ואותו האבן תחתיו היה, אע\"פ שהיה בבית אל. אמר לו, \u0003אשר שם\u0004 כתוב. וכתיב והאבן הזאת אשר שמתי מצבה, שמשמע שתקן אותה עתה, ואיך היא אבן שתיה המתוקנה מקודם העולם. אמר לו, אם אתה יודע דבר מה, אמור."],[7,"פתח ואמר וכו':","פתח ואמר אני בצדק אחזה פניך וגו'. דוד המלך, החביבות והדבקות שלו באותו אבן היתה, דהיינו מלכות, הנקראת אבן שתיה, ונקראת צדק. ועליה אמר, אבן מאסו הבונים היתה לראש פנה. וכשרצה להסתכל במראה כבוד רבוני, לקח תחילה אותו האבן בידיו, ואח\"כ נכנס."],[8,"בגין דכל וכו':","משום שכל מי שרוצה להראות לפני רבונו, אינו נכנס אלא באותו אבן, שכתוב בזאת, שהיא מלכות הנקראת זאת, יבא אהרן אל הקודש. ודוד משבח עצמו ואומר, אני בצדק, שהיא מלכות, אחזה פניך. וכל עסקו של דוד היה להראות באותו אבן כראוי כלפי מעלה. פירוש. המוחין דחכמה מכונים עינים וכן ראיה. ואלו המוחין אינם מאירים בשום מדרגה, אחר חכמה דא\"א שנסתמה, אלא בהמלכות, שהיא נוקבא דז\"א, בלבדה. (כנ\"ל בראשית ב' דף ט\"ז ד\"ה אמר) והיא נקראת אבן שתיה, וז\"ש חביבותא ודבקותא דיליה בהאי אבן הוה וכו'. וכן אני בצדק אחזה פניך וגו'. כי המוחין דראיה אינם אלא בה."],[9,"ת\"ח אברהם וכו':","בוא וראה אברהם תקן תפלת שחרית שהוא כנגד חסד דז\"א והודיע מהותו של רבונו בעולם, ותיקן אותו הזמן בתיקוניו כראוי. דהיינו שתקן מדת החסד השולט בבוקר. יצחק תקן תפלת המנחה, שהוא כנגד הגבורה דז\"א, והודיע בעולם שיש דין ויש דיין, שיכול להציל העולם, ולדון העולם. דהיינו שתקן מדת הגבורה."],[10,"יעקב אתקין וכו':","יעקב תקן תפלת ערבית, שהיא כנגד המלכות, שהיא נוקבא דז\"א, ובשביל תפלה זו שתקן מה שלא תקן אדם מקודם לכן כראוי, משום זה, הוא שבח את עצמו ואמר, והאבן הזאת, שהיא מלכות, אשר שמתי מצבה. דהיינו שתקן אותה, שעד אותה שעה לא שם אותה אחר כמוהו."]],[[0,"","רַבִּי יְהוּדָה קָם לַיְלָה אֶחָד לַעֲסֹק בַּתּוֹרָה בַּחֲצוֹת הַלַּיְלָה בְּאַכְסַנְיָה בְּעִיר מַחְסֵיָא, וְהָיָה שָׁם בַּבַּיִת יְהוּדִי אֶחָד שֶׁבָּא בִּשְׁתֵּי אַמְתָּחוֹת שֶׁל מַלְבּוּשִׁים. פָּתַח רַבִּי יְהוּדָה וְאָמַר, (בראשית כח) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים - זוֹהִי אֶבֶן הַשְּׁתִיָּה שֶׁמִּשָּׁם נִשְׁתַּל הָעוֹלָם וְעָלֶיהָ נִבְנָה בֵּית הַמִּקְדָּשׁ."],[1,"","הֵרִים רֹאשׁוֹ אוֹתוֹ יְהוּדִי וְאָמַר לוֹ, דָּבָר זֶה אֵיךְ אֶפְשָׁר? וַהֲרֵי אֶבֶן הַשְּׁתִיָּה טֶרֶם שֶׁנִּבְרָא הָעוֹלָם הָיְתָה, וּמִמֶּנָּה נִשְׁתַּל הָעוֹלָם, וְאַתָּה אָמַרְתָּ וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה, שֶׁמַּשְׁמָע שֶׁיַּעֲקֹב שָׂם אוֹתָהּ עַכְשָׁו, שֶׁכָּתוּב (שם) וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשּתָיו? וְעוֹד, שֶׁיַּעֲקֹב בְּבֵית אֵל הָיָה, וְהָאֶבֶן הַ את הָיְתָה בִּירוּשָׁלַיִם."],[2,"","רַבִּי יְהוּדָה לֹא סוֹבֵב רֹאשׁוֹ אֵלָיו, פָּתַח וְאָמַר, (עמוס ד) הִכּוֹן לִקְרַאת אֱלֹהֶיךְ יִשְׂרָאֵל, וְכָתוּב (דברים כז) הַסְכֵּת וּשְׁמַע יִשְׂרָאֵל. דִּבְרֵי תוֹרָה צְרִיכִים כַּוָּנָה, וְדִבְרֵי תוֹרָה צְרִיכִים לְהִתְתַּקֵּן בְּגוּף וְרָצוֹן כְּאֶחָד. קָם אוֹתוֹ יְהוּדִי וְהִתְלַבֵּשׁ, וְיָשַׁב אֵצֶל רַבִּי יְהוּדָה וְאָמַר, אַשְׁרֵיכֶם הַצַּדִּיקִים שֶׁעוֹסְקִים בַּתּוֹרָה יוֹמָם וָלַיְלָה."],[3,"","אָמַר לוֹ רַבִּי יְהוּדָה, עַכְשָׁו שֶׁכִּוַּנְתָּ עַצְמְךְ, אֱמֹר דְּבָרְךְ שֶׁנִּתְחַבֵּר כְּאֶחָד, שֶׁהֲרֵי דִּבְרֵי תוֹרָה צְרִיכִים תִּקּוּן הַגּוּף וְתִקּוּן הַלֵּב, וְאִם לֹא - בְּמִטָּתִי הָיִיתִי שׁוֹכֵב, וּבְלִבִּי הָיִיתִי אוֹמֵר דְּבָרִים. אֶלָּא הֲרֵי שָׁנִינוּ, שֶׁאֲפִלּוּ אֶחָד שֶׁיּוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, הַשְּׁכִינָה מִתְחַבֶּרֶת עִמּוֹ, וּמַה שְּׁכִינָה כָּאן וַאֲנִי שׁוֹכֵב בְּמִטָּתִי!? וְלֹא עוֹד, אֶלָּא שֶׁצְּרִיכִים צַחוּת."],[4,"","וְעוֹד, שֶׁכָּל בֶּן אָדָם שֶׁקָּם לַעֲסֹק בַּתּוֹרָה מֵחֲצוֹת הַלַּיְלָה, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן (בחצות הלילה), הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן. וְהוּא וְכָל הַצַּדִּיקִים שֶׁבַּגַּן, כֻּלָּם מַקְשִׁיבִים (לו, ומקשיבים) לְאוֹתָם דְּבָרִים שֶׁיּוֹצְאִים מִפִּיו. וּמָה הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁמִּתְעַדְּנִים לִשְׁמֹעַ דִּבְרֵי תוֹרָה בַּשָּׁעָה הַזּוֹ, וַאֲנִי אֶהְיֶה שׁוֹכֵב בְּמִטָּתִי!? אָמַר לוֹ, כָּעֵת אֱמֹר דְּבָרְךְ."],[5,"","אָמַר לוֹ, שָׁאַלְתִּי עַל מַה שֶּׁאָמַרְתָּ בַּפָּסוּק הַזֶּה (סוד של אבן השתיה שאמרת), וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים, שֶׁזּוֹ אֶבֶן הַשְּׁתִיָּה, (עכשו שמקשיב לדברי) אֵיךְ אֶפְשָׁר? שֶׁהֲרֵי אֶבֶן הַשְּׁתִיָּה טֶרֶם שֶׁנִּבְרָא הָעוֹלָם הָיְתָה, וּמִמֶּנָּה נִשְׁתַּל הָעוֹלָם, וְאַתָּה אָמַרְתָּ אֲשֶׁר שַׂמְתִּי, שֶׁמַּשְׁמָע שֶׁיַּעֲקֹב שָׂם אוֹתָהּ כָּעֵת, וְכָתוּב וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשּתָיו?"],[6,"","וְעוֹד, שֶׁיַּעֲקֹב בְּבֵית אֵל הָיָה, וְהָאֶבֶן הַזּוֹ הָיְתָה בִּירוּשָׁלַיִם. אָמַר לוֹ, כָּל אֶרֶץ יִשְׂרָאֵל הִתְקַפְּלָה תַּחְתָּיו, וְאוֹתָהּ אֶבֶן תַּחְתָּיו הָיְתָה. אָמַר לוֹ, אֲשֶׁר שָׂם כָּתוּב, וְכָתוּב וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה. אָמַר לוֹ, אִם יָדַעְתָּ הַדָּבָר - אֱמֹר אוֹתוֹ."],[7,"","פָּתַח וְאָמַר, (תהלים יז) אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךְ אֶשְׂבְּעָה בְהָקִיץ תְּמוּנָתֶךְ. דָּוִד הַמֶּלֶךְ, הַחֲבִיבוּת וְהַדְּבֵקוּת שֶׁלּוֹ הָיְתָה בָּאֶבֶן הַזֹּאת, וְעָלֶיהָ אָמַר (שם קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וּכְשֶׁרָצָה לְהִסְתַּכֵּל בְּמַרְאֵה כְּבוֹד רִבּוֹנוֹ, נָטַל אֶבֶן זוֹ בְּיָדוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ נִכְנַס."],[8,"","מִשּׁוּם שֶׁכָּל מִי שֶׁרוֹצֶה לְהֵרָאוֹת לִפְנֵי רִבּוֹנוֹ, לֹא נִכְנָס אֶלָּא עִם אֶבֶן זאת, שֶׁכָּתוּב (ויקרא יג) בְּזאת יָבא אַהֲרֹן אֶל הַקֹּדֶשׁ. וְדָוִד מְשַׁבֵּחַ עַצְמוֹ וְאוֹמֵר, אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךְ. וְכָל הִשְׁתַּדְּלוּתוֹ שֶׁל דָּוִד לְהֵרָאוֹת בְּאֶבֶן זֹאת כָּרָאוּי כְּלַפֵּי מַעְלָה."],[9,"","בֹּא וְתִרְאֶה, אַבְרָהָם תִּקֵּן תְּפִלַּת הַבֹּקֶר וְהוֹדִיעַ טוּב רִבּוֹנוֹ בָּעוֹלָם, וְתִקֵּן אוֹתָהּ הַשָּׁעָה בְּתִקּוּנֶיהָ כָּרָאוּי, שֶׁכָּתוּב (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. יִצְחָק תִּקֵּן תְּפִלַּת מִנְחָה, וְהוֹדִיעַ בָּעוֹלָם שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן שֶׁיָּכוֹל לְהַצִּיל וְלָדוּן אֶת הָעוֹלָם."],[10,"","יַעָקֹב תִּקֵּן תְּפִלַּת עַרְבִית, וּבִשְׁבִיל הַתְּפִלָּה הַזּוֹ שֶׁתִּקֵּן מַה שֶּׁלֹּא תִקֵּן בֶּן אָדָם מִקֹּדֶם לָזֶה כָּרָאוּי, לָכֵן שִׁבַּח אֶת עַצְמוֹ וְאָמַר וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה. שֶׁעַד אוֹתָהּ שָׁעָה לֹא תִקֵּן אוֹתָהּ אַחֵר כְּמוֹתוֹ."]]],[["וּבְגִין כָּךְ וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשׁוֹתָיו וַיָּשֶׂם אוֹתָהּ מַצֵּבָה. מַאי מַצֵּבָה דְּהֲוָה נְפִילָה וְאוֹקִים לָהּ. וַיִּצּוֹק שֶׁמֶן עַל רֹאשָׁהּ. דְּהָא בְּיַעֲקֹב תַּלְיָא מִילְתָא לְמֶעְבַּד יַתִּיר מִכָּל בְּנֵי עָלְמָא.","אֲתָא רַבִּי יְהוּדָה וּנְשָׁקֵיהּ, אָמַר לֵיהּ וְכָל הַאי יְדַעְתְּ (והיך) וְאַתְּ מִשְׁתַּדֵּל בִּסְחוֹרָתָא וּמַנַּח חַיֵּי עָלְמָא. אָמַר לֵיהּ דְּהֲוָה דְחִיקָא לִי שַׁעֲתָא, וְאִית לִי תְּרֵין בְּנִין וְקָיְימִין כָּל יוֹמָא בְּבֵי רַב וְאֲנָא אִשְׁתַּדַּלְנָא עַל מְזוֹנַיְיהוּ וּלְמֵיהַב לוֹן אֲגַר לְמוֹרַיְיהוּ בְּגִין דְּיִשְׁתַּדְּלוּן בְּאוֹרַיְיתָא.","פָּתַח וְאָמַר, (מלכים א ב׳:י״ב) וּשְׁלֹמֹה יָשַׁב עַל כִּסֵּא דָּוִד אָבִיו וַתִּכּוֹן מַלְכוּתוֹ מְאֹד. מַאי שְׁבָחָא דָא. אֶלָּא דְּאַתְקִין אֶבֶן שְׁתִיָּה וְשַׁוֵּי עֲלָהּ קֹדֶשׁ הַקֳּדָשִׁים וּכְדֵין וַתִּכּוֹן מַלְכוּתוֹ מְאֹד.","וּכְתִיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא תִּיאוּבְתָּא דִילֵיהּ בָּהּ תָּדִיר, וּמַאן דְּלָא אִתְחֲזֵי בָּהּ לָא אָעִיל קַמֵּי מָארֵיהּ. וְעַל דָּא כְּתִיב וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם.","וּרְאִיתִיהָ. מַאי וּרְאִיתִיהָ, רָזָא הוּא כְּמָא דְאַתְּ אָמֵר (יחזקאל ט׳:ד׳) וְהִתְוֵיתָ תָּיו עַל מִצְחוֹת וְגו'. לְאִתְחַזָּאָה עֲלַיְיהוּ. וְאִיכָּא דְאָמְרֵי דָּא רְשִׁימוּ דְּאָת קַדִּישָׁא דִּי בְּבִשְׂרָא.","אָמַר רַבִּי יְהוּדָה וַדַּאי כֹּלָּא הוּא. (ד\"א הכי) אֲבָל הַאי קֶשֶׁת דְּאִתְחֲזֵי בְּעָלְמָא בְּרָזָא עִלָאָה קָיְימָא. וְכַד יִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא זְמִינָא הַאי קֶשֶׁת לְאִתְקַשְׁטָא בְּגַוְונוֹי כְּכַלָּה דָא דְּמִתְקַשְּׁטָא לְבַעֲלָהּ.","אָמַר לֵיהּ הַהוּא יוּדָאי כָּךְ אָמַר לִי אַבָּא כַּד הֲוָה מִסְתַּלַּק מֵעָלְמָא (אמר לי) לָא תְצַפֵּי לְרַגְלֵי דִמְשִׁיחָא עַד דְּיִתְחֲזֵי הַאי קֶשֶׁת בְּעָלְמָא (ד\"א ל\"ג בעננא) מִתְקַשְׁטָא בְּגַוְונִי נְהִירִין וְיִתְנְהִיר לְעָלְמָא. וּכְדֵין צְפֵי לֵיהּ לְמָשִׁיחַ.","מְנָלָן, דִּכְתִיב וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְהַשְׁתָּא דְּאִתְחַזְּיָא בִּגְוָונִין חֲשׁוֹכִין מִתְחַזְּיָא לְדוּכְרָנָא (והיא לזכור) דְּלָא יִיִתֵי מַבּוּל. אֲבָל בְּהַהִיא זִמְנָא אִתְחַזְּיָיא בִּגְוָונִין נְהִירִין וּמִתְקַשְּׁטָא בְּתִקּוּנָא כְּכַלָּה דְּמִתְקַשְּׁטָא לְבַעֲלָהּ וּכְדֵין לִזְכֹּר בְּרִית עוֹלָם וְיִדְכַּר קוּדְשָׁא בְּרִיךְ הוּא לְהַאי בְּרִית דְּאִיהוּ בְּגָלוּתָא וְיָקִים לָהּ מֵעַפְרָא הֲדָא הוּא דִכְתִיב, (הושע ג׳:ה׳) וּבִקְּשׁוּ אֶת יְיָ אֱלהֵיהֶם וְאֶת דָּוִד מַלְכָּם. וּכְתִיב, (ירמיהו ל׳:ט׳) וְעָבְדוּ אֶת יְיָ אֱלֹהֵיהֶם וְאֶת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם, אֲשֶׁר אָקִים מֵעָפָר כְּמָא דְאַתְּ אָמֵר, (עמוס ט׳:י״א) אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפָלֶת. וְעַל דָּא וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם וּלְאַקְמָא לָהּ מֵעַפְרָא.","וְאָמַר הָכִי אַבָּא דִּבְגִין כָּךְ אִדְכַּר בְּאוֹרַיְיתָא פּוּרְקָנָא דְיִשְׂרָאֵל וּדְכוּרָנָא דִּילָהּ. וְדָא הוּא דִכְתִיב, (ישעיהו נ״ד:ט׳) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבוֹר מֵי נֹחַ עוֹד עַל הָאָרֶץ כֵּן נִשְׁבַּעְתִּי מִקְצוֹף עָלַיִךְ וּמִגְּעָר בָּךְ:","וַיִּהְיוּ בְּנִי נֹחַ הַיּוֹצְאִים מִן הַתֵּבָה. רַבִּי אֶלְעָזָר אָמַר כֵּיוָן דִּכְתִיב וַיִּהְיוּ בְּנֵי נֹחַ. אַמַּאי אָמַר הַיּוֹצְאִים מִן הַתֵּבָה. וְכִי בְּנִין אָחֳרָנִין הֲווּ לֵיהּ דְּלָא נָפְקֵי מִן תֵּיבוּתָא.","אָמַר לֵיהּ רַבִּי אַבָּא אִין. דְּהָא לְבָתַר אוֹלִידוּ בְּנוֹי בְּנִין. דִּכְתִיב וְאֵלֶּה תּוֹלְדוֹת שֵׁם וְגו'. וְאִנוּן לָא נָפְקֵי מִגּוֹ תֵּיבוּתָא. וּבְגִין כָּךְ כְּתִיב הַיּוֹצְאִים מִן הַתֵּיבָה שֵׁם חָם וָיָפֶת.","רַבִּי שִׁמְעוֹן אָמַר אִילּוּ הֲוֵינָא שְׁכִיחַ בְּעָלְמָא כַּד יָהִיב קוּדְשָׁא בְּרִיךְ הוּא סִפְרָא דְחֲנוֹךְ בְּעָלְמָא וְסִפְרָא דְאָדָם, אַתְקִיפְנָא דְּלָא יִשְׁתַּכְּחוּן בֵּינֵי אֱנָשָׁא, בְּגִין דְּלָא חַיְישׁוּ כָּל חֲכָמָאן לְאִסְתַּכְּלָא בְּהוּ וְטָעָן בְּמִלִּין אָחֳרָנִין לְאֲפָקָא מֵרְשׁוּ עִלָּאָה לִרְשׁוּ אָחֳרָא. וְהַשְׁתָּא הָא חַכִּימֵי עָלְמָא יָדְעִין מִלִּין וְסָתְמִין לוֹן וּמִתְתַּקְפֵי בְּפוּלְחָנָא דְּמָארֵיהוֹן.","וְהַאי קְרָא אַשְׁכַּחְנָא בְּרָזָא דְרָזִין. (תוספתא) דְּכַד אִתְעַר חֶדְוָה דְּכָל חֶדְוָון טְמִירָא סְתִימָא סַבְתָּא דְסַבְתִּין אַנְהִיר מִנֵּיהּ נְהִירוּ דַּקִּיק. חֶדְוָה דְּכָל חֶדְוָון נָהִיר לְיָמִינָא בִּמְשַׁח רְבוּת עִלָּאָה. וְנָהִיר לִשְׂמָאלָא בְּחֶדְוָוה דְּחַמְרָא טַב, נָהִיר לְאֶמְצָעִיתָא בְּחֶדְוָוה (ד\"א דארגוונא) דִּתְרֵין סִטְרִין. רוּחַ אִתְעַר וְרוּחַ סָלְקָא וְאִתְיְיהִיב בְּרוּחָא.","דָּבְקָן דָּא בְּדָא. תְּלַת עָאלִין בִּתְלַת. מִגּוֹ תְּלַת נָפְקָא חַד בְּרִית דְדָבְקָא בִּבְרִית. אִתְעֲבָרַת רוּחַ דְּסָלְקָא, מִתְעֲבָרַת מִנֵּיהּ. כַּד אִתְיְיהִיבַת בִּתְרֵין סִטְרִין אִתְדַּבְּקוּ רוּחָא בְּרוּחָא וּמִתְעַבְּרָן מִתְּלַת בְּנִין. וְנֹחַ וְתֵיבָה נָפְקוּ מִנַּיְיהוּ תְּלָתָא, כְּגַוְונָא דִּתְלָתָא (דלתתא) עִלָּאִין, וְאִלֵּין אִנוּן דְּנָפְקוּ מִגּוֹ תֵּיבוּתָא שֵׁם וְחָם וְיָפֶת. שֵׁם דְּבִסְטַר יָמִינָא, חָם דְּבִסְטַר שְׂמָאלָא. יֶפֶת אַרְגְּוָונָא דְּכָלִיל לוֹן."],[[0,"ובגין כך וכו':","ומשום זה, ויקח את האבן אשר שם מראשותיו וישם אותה מצבה. מהו מצבה. מצבה פירושו. שהיתה נפילה בהמלכות, והקים אותה. ויצוק שמן על ראשה, כי ביעקב תלוי הדבר לתקנה, יותר מבכל בני העולם. כי יעקב הוא מרכבה לת\"ת. שהוא בעלה, שבו תלוים תקוני המלכות שהיא נוקביה."],[1,"אתא ר' יהודה וכו':","בא ר\"י ונשקו, לאותו יהודי, אמר לו, וכל זה אתה יודע, ואתה עוסק בסחורה ומניח חיי עולם. אמר לו, השעה היתה דחוקה לי, ויש לי שני בנים הנמצאים כל היום בבית המדרש. ואני משתדל על מזונותיהם, ולתת שכר לימוד למוריהם, כדי שיעסקו בתורה."],[2,"פתח ואמר וכו':","ושלמה ישב על כסא דוד אביו ותכון מלכותו מאד. ושואל מהו שבח הזה של שלמה. ואומר. אלא שתקן האבן שתיה. ושם עליה קדש הקדשים. דהיינו שתקן המלכות, והמשיך לה מוחין דג\"ר, שהם בחינת קדש הקדשים. ואז ותכון \u0003מלכותו\u0004 מאד."],[3,"וכתיב וראיתיה לזכור ברית עולם:","כי הקב\"ה, תשוקתו היא בה, בהמלכות, תמיד, ומי שאינו מתראה בה, כלומר שאינו מקבל ממנה מוחין דראיה. שהם חכמה, אינו נכנס לפני רבונו, כי מוחין אלו אינם נמשכים רק ממנה בלבד כנ\"ל בסמוך. וע\"כ כתוב וראיתיה לזכור ברית עולם. כי הראיה רק בה היא."],[4,"וראיתיה וכו':","שואל \u0003מהו וראיתיה,\u0004 לאיזה בחינה שבה, מתכוונת הראיה. אם לבחינת הדין שבה, שהוא הגורם לכל המוחין בסוד המסך דחירק (כנ\"ל דף צ\"ג ד\"ה ביאור) או בבחינת המפתחא שבה, שבו מקובל עצם המוחין, (כנ\"ל דף צ\"ה ד\"ה מאי ע\"ש) ומשיב \u0003רזא הוא, כד\"א והתוית תיו על מצחות וגו' לאתחזאה עלייהו,\u0004 סוד הוא, כש\"א, והתוית תיו, וגו', שהת' יתראה עליהם. כלומר, שהראיה סובב על בחינת ה \u0003ת'\u0004 שבהמלכות שה\"ס בחינת הדין שבה, כמו ש \u0003ת'\u0004 זו הצילה האנשים דהיינו אותם שה \u0003ת'\u0004 היתה נראה במצחם. והוא מטעם שהוא הגורם להתגלות המוחין כנ\"ל. \u0003ואיכא דאמרי, דא רשימו דאת קדישא די בבשרא,\u0004 ויש אומרים שהראיה סובב על הרשימו דאות הקדוש אשר בבשר. דהיינו בהתכללותה בעטרת יסוד, שה\"ס המפתחא, שהמוחין בעצם מקובלים בה, להיותו ממשיך לה הכלים דאמא והמוחין דאמא כנ\"ל בראשית א' דף י' ד\"ה אי ע\"ש."],[5,"אמר ר' יהודה וכו':","אר\"י ודאי הכל הוא בהמלה וראיתיה, הן בחינת ה \u0003ת'\u0004 שבה והן בחינת העטרה, אבל קשת זה הנראה בעולם, בסוד העליון, דהיינו בינה, הוא עומד, דהיינו רק בבחינת העטרה שבה, המשוה אותה לבינה, ומקבלת המוחין והכלים ממנה. וכאשר יצאו ישראל מן הגלות, עתידה קשת הזו להתקשט בצבעיה ככלה זו המתקשטת לבעלה. כלומר שג' הצבעים לבן אדום ירוק, שהם המוחין שבה, יהיו מאירים מאוד, כמ\"ש לפנינו."],[6,"א\"ל ההוא יודאי וכו':","א\"ל אותו היהודי, כך אמר לי אבי, בשעה שהיה מסתלק מהעולם, לא תצפה לעקבות המשיח, עד שתהיה נראה קשת הזו בהעולם, מתקשטת בצבעים מאירים ותאיר להעולם. ואז תצפה למשיח."],[7,"מנלן דכתיב וכו':","מאין לנו זה, כי כתוב וראיתיה לזכור ברית עולם. ועתה, בזמן הגלות, שהקשת נראה בצבעים חשוכים, הוא נראה רק לזכרון, שלא יבא מבול לעולם. אבל בעת ההיא, כשיבוא המשיח, היא תהיה נראה בצבעים מאירים ומתקשטת בתיקוניה. כמו, כלה המתקשטת לבעלה, ואז יקוים \u0003לזכור ברית עולם,\u0004 ויזכור הקב\"ה לברית הזה שהוא בגלות, ויקים אותה מעפר. וז\"ש ובקשו את ה' אלקיהם ואת דוד מלכם, דוד מלכם, רומז על המלכות שה\"ס הקשת. וכתוב ועבדו את ה' אלקיהם ואת דוד מלכם אשר אקים להם. דהיינו אשר אקים מעפר, כמו שאתה אומר, אקים את סוכת דוד הנופלת. וע\"כ נאמר אז, וראיתיה לזכור ברית עולם. ולהקים אותה מעפר."],[8,"ואמר הכי אבא וכו':","וכך אמר אבי. שמשום זה נזכר בהתורה גאולת ישראל, וזכרון שלה, של המלכות, כי לזכור ברית עולם. יורה על גאולת ישראל ותקון המלכות כנ\"ל. וזהו שכתוב, בעת הגאולה, אשר נשבעתי מעבור מי נח עוד על הארץ, כן נשבעתי מקצוף עליך ומגער בך. פירוש. כמו שנשבע בראית הקשת שלא יביא מבול לעולם, שזה הוא גם בזמן הגלות, (כנ\"ל בדבור הסמוך) כן בעת הגאולה, כשתאיר הקשת בגוונין נהירין, יאמר ה', נשבעתי מקצוף עליך ומגער בך. כנ\"ל כי אז יקום סוכת דוד הנופלת לעד ולנצח. ויקוים הכתוב, לזכור ברית עולם."],[9,"ויהיו בני נח וגו':","רבי אלעזר אמר כיון שכתוב ויהיו בני נח, למה אמר הכתוב היוצאים מן התיבה. וכי היו לו בנים אחרים שלא יצאו מן התבה."],[10,"אמר ליה ר' אבא וכו':","א\"ל רבי אבא, כן, שהרי אח\"כ, בניו הולידו בנים, שכתוב ואלה תולדות שם וגו', והם לא יצאו מן התבה, ומשום זה כתוב היוצאים מן התבה, שם חם ויפת."],[11,"רבי שמעון אמר וכו':","רש\"א, אלו הייתי נמצא בעולם, כאשר נתן הקב\"ה ספרו של חנוך בעולם, וספרו של אדם, הייתי מתאמץ שלא יהיו נמצאים בין אנשים. משום שכל החכמים לא חששו אז להסתכל בהם, וטעו, להוציא הדברים מפשוטם, בדברים אחרים להוציאם מרשות העליון דקדושה, לרשות אחר, שאינו קדוש. אבל עתה, הרי חכמי עולם יודעים דברים וסותמים אותם שאינם מגלים הסודות, ומתגברים בעבודת רבונם. וע\"כ עתה מותר לעסוק בסודות."],[12,"והאי קרא אשכחנא וכו':","ומקרא הזה מבני נח שיצאו מהתבה, מצאתי בסוד הסודות. כאשר נתעוררה החדוה שעל כל החדוות הנסתרה הסתומה. שהיא בינה בעת שעלתה לראש א\"א, ונתהפכה שם לחכמה, ואז סבת הסבות, שהוא א\"א, האיר מתוכו אור דק, כלומר, שהבינה לא יכלה לקבל מא\"א רק אור דק, שהוא מטעם חסרון חסדים (כנ\"ל דף מ\"ו ד\"ה פירוש). וע\"כ נסתרה ונסתמה הבינה. וע\"כ נתעוררה הבינה וקבלה בתוכה הארת ג' הקוין, דהיינו, חדוה שעל כל החדוות האירה לקו ימין בשמן המשחה העליון, דהיינו הארת החסדים, שה\"ס חולם. והאירה לקו שמאל בחדות יין הטוב, דהיינו הארת החכמה, שה\"ס שורק. והאירה לקו האמצעי בחדות ב' הקוין דימין ושמאל, שה\"ס חירק. כי רוח, שהוא ז\"א, נתעורר ובא בקו האמצעי דבינה, שממנו נקודת החירק, וקו האמצעי. ורוח דקו שמאל עלה, וניתן ברוח דקו ימין. ואז נכללו ג' הקוין דבינה זה בזה."],[13,"דבקן דא בדא וכו':","מתדבקים זה בזה, ז\"א מתדבק בהבינה, ואז שלשה נכנסים בשלשה. שלשה קוי הבינה נכנסים ונעשים שלשה קוין בז\"א. מתוך השלשה קוין שבז\"א יוצא אחד, הוא ברית, דהיינו יסוד, והנוקבא דבוקה בברית. ואח\"כ נעבר ממנו רוח העולה, שהיא רוח דקו שמאל, והנוקבא מתעברה הימנו, כלומר. שקו שמאל נעבר מז\"א וניתן להנוקבא. (כנ\"ל ב\"א נ\"ב אות ל\"ט) ואח\"כ כאשר ניתבה הנוקבא בב' קוין דז\"א, דהיינו שמקבלת גם חסדים מימין, נתדבקו רוח ברוח, דהיינו ז\"א עם הנוקבא, ומתעברת הנוקבא, משלשה בנים, ואז ונח ותיבה יוצאים מהם שלשה בנים. כעין שלשה קוין העליונים, ואלו הם שיצאו מתוך התבה, שם חם ויפת. שם, שבצד ימין. חם שבצד שמאל. יפת הוא ארגמן, היינו קו אמצעי, הכולל אותם."],[13,"","פירוש. ר\"ש מבאר כאן, סוד שם חם ויפת שהכתוב מדייק בהם לומר היוצאים מן התבה, להורות שהם עצם ג' הקוין שבבינה שנשתלשלו לז\"א ומז\"א להנוקבא שה\"ס התבה, שהם שם חם ויפת שנולדו ויצאו מהתבה. ומביא תחילה איך הבינה היתה בהארת הקו שמאל שקבלה רק נהירו דקיק מא\"א. ואח\"כ מביא שע\"י רוח שהוא קו אמצעי שעלה להבינה, האירה הבינה בג' קוין. שז\"ס מה שאומר לעיל (בראשית א' דף רפ\"ז אות שסג) \u0003תלת נפקי מחד.\u0004 שג' קוי הבינה יוצאים מאחד שהוא ז\"א. ולפיכך \u0003חד\u0004 שהוא ז\"א \u0003בתלת קיימי,\u0004 וכן אומר כאן \u0003תלת עאלין בתלת,\u0004 כי מתוך שז\"א גרם הארת ג' הקוין בבינה, ע\"כ זכה גם הוא בהם. ואח\"כ, \u0003מגו תלת נפקי חד, ברית,\u0004 שמתוך ג' קוין של ז\"א יצא אחד, שהוא ברית. והיינו על דרך שביאר בזהר הנ\"ל, \u0003עאל בין תרין, תרין ינקין לחד,\u0004 ע\"ש בהסולם. ובהברית שהוא יסוד דבוקה ג\"כ הנוקבא, כנודע. וז\"ש \u0003דבקא בברית,\u0004 שהנוקבא דבוקה בהברית, בסוד נקודה תחת היסוד, ואח\"כ נבנית הנוקבא, תחלה מקו שמאל דז\"א, ואח\"כ מכל ג' הקוין, ומזדווגת עמו בסוד \u0003נח ותבה,\u0004 ע\"ד שנתבאר לעיל. ואז קבלה טפת הזווג הכלולה מג' קוין דז\"א, (כנ\"ל דף כ\"ב אות ס\"א ע\"ש בהסולם): ואלו ג' קוין הם שם חם ויפת. הרי שאלו ג' קוין שיצאו בבינה הם שנשתלשו ובאו לז\"א, ומז\"א באו להנוקבא, שה\"ס התיבה, ומהתיבה יצאו ונולדו ובאו לעולם. וע\"כ מדייק הכתוב בהם לומר, ויהיו בני נח היוצאים מהתבה."]],[[0,"","וְלָכֵן וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשּתָיו וַיָּשֶׂם אֹתָהּ מַצֵּבָה. מַה זֶּה מַצֵּבָה? שֶׁהָיְתָה נְפוּלָה, וְהֵקִים אוֹתָהּ. וַיִּצֹק שֶׁמֶן עַל רֹאשָׁהּ. שֶׁהֲרֵי בְּיַעֲקֹב תָּלוּי הַדָּבָר לַעֲשׂוֹת יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם."],[1,"","בָּא רַבִּי יְהוּדָה וּנְשָׁקוֹ. אָמַר לוֹ, וְכָל זֶה יָדַעְתָּ, וְאֵיךְ אַתָּה עוֹסֵק בִּסְחוֹרָה וּמַנִּיחַ חַיֵּי עוֹלָם!? אָמַר לוֹ, שֶׁדְּחוּקָה הָיְתָה לִי הַשָּׁעָה, וְיֵשׁ לִי שְׁנֵי בָנִים, וְעוֹמְדִים כָּל הַיּוֹם בְּבֵית הָרַב, וַאֲנִי מִשְׁתַּדֵּל בִּמְזוֹנָם וְלָתֵת לָהֶם שָׂכָר לְמוֹרָם כְּדֵי שֶׁיַּעַסְקוּ בַתּוֹרָה."],[2,"","פָּתַח וְאָמַר, (מלכים א ב) וּשְׁלֹמֹה יָשַׁב עַל כִּסֵּא דָּוִד אָבִיו וַתִּכֹּן מַלְכֻתוֹ מְאֹד. מַה הוּא הַשֶּׁבַח הַזֶּה? אֶלָּא שֶׁהִתְקִין אֶבֶן שְׁתִיָּה וְשָׂם עָלֶיהָ קֹדֶשׁ הַקְּדָשִׁים, וְאָז וַתִּכֹּן מַלְכֻתוֹ מְאֹד."],[3,"","וְכָתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא חִשְׁקוֹ בָהּ תָּמִיד, וּמִי שֶׁלֹּא נִרְאֶה עִמָּהּ, לֹא נִכְנָס לִפְנֵי רִבּוֹנוֹ. וְעַל זֶה כָּתוּב וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם."],[4,"","וּרְאִיתִיהָ, מַה זֶּה וּרְאִיתִיהָ? סוֹד הוּא, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל ט) וְהִתְוִיתָ תָּו עַל מִצְחוֹת וְגוֹ', לְהֵרָאוֹת עֲלֵיהֶם. וְיֵשׁ אוֹמְרִים, זֶה רֹשֶׁם הָאוֹת הַקָּדוֹשׁ שֶׁבַּבָּשָׂר."],[5,"","אָמַר רַבִּי יְהוּדָה, וַדַּאי הַכֹּל הוּא. (כך) אֲבָל קֶשֶׁת זוֹ שֶׁנִּרְאֵית בָּעוֹלָם עוֹמֶדֶת בְּסוֹד עֶלְיוֹן, וּכְשֶׁיֵּצְאוּ יִשְׂרָאֵל מֵהַגָּלוּת, עֲתִידָה קֶשֶׁת זוֹ לְהִתְקַשֵּׁט בִּגְוָנִים כַּכַּלָּה הַזּוֹ שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ."],[6,"","אָמַר לוֹ אוֹתוֹ יְהוּדִי, כָּךְ אָמַר לִי אַבָּא, כְּשֶׁהָיָה מִסְתַּלֵּק מֵהָעוֹלָם, (אמר לי) אַל תְּצַפֶּה לְרַגְלֵי מָשִׁיחַ עַד שֶׁתֵּרָאֶה קֶשֶׁת זוֹ בָּעוֹלָם (בענן) מְקֻשֶּׁטֶת בִּגְוָנִים מְאִירִים וְיוֹאַר לָעוֹלָם, וְאָז צַפֵּה לַמָּשִׁיחַ."],[7,"","מִנַּיִן לָנוּ? שֶׁכָּתוּב וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְכָעֵת שֶׁנִּרְאֵית בִּגְוָנִים חֲשׁוּכִים, נִרְאֵית לְזִכָּרוֹן (והיא לזכר) שֶׁלֹּא יָבֹא מַבּוּל. אֲבָל בְּאוֹתוֹ זְמַן נִרְאֵית בִּגְוָנִים מְאִירִים וּמְקֻשֶּׁטֶת בְּתִקּוּן כְּמוֹ כַּלָּה שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ, וְאָז לִזְכֹּר בְּרִית עוֹלָם, וְיִזְכֹּר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַבְּרִית הַזּוֹ שֶׁהִיא בַּגָּלוּת וִיקִימָהּ מֵהֶעָפָר. זֶהוּ שֶׁכָּתוּב (הושע ג) וּבִקְשׁוּ אֶת ה' אֱלֹהֵיהֶם וְאֵת דָּוִיד מַלְכָּם. וְכָתוּב (ירמיה ל) וְעָבְדוּ אֵת ה' אֱלֹהֵיהֶם וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם. אֲשֶׁר אָקִים מֵעָפָר. כְּמוֹ שֶׁנֶּאֱמַר (עמוס ט) אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. וְעַל זֶה וּרְאִיתִיהָ לִזְכֹר בְּרִית עוֹלָם וְלַהֲקִימָהּ מֵהֶעָפָר."],[8,"","וְאָמַר כָּךְ אַבָּא, שֶׁמִּשּׁוּם כָּךְ נִזְכְּרָה בַּתּוֹרָה גְּאֻלַּת יִשְׂרָאֵל וְזִכְרוֹנָהּ. וְזֶהוּ שֶׁכָּתוּב (ישעיה נד) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ עוֹד עַל הָאָרֶץ כֵּן נִשְׁבַּעְתִּי מִקְּצֹף עָלַיִךְ וּמִגְּעָר בָּךְ."],[9,"","וַיִּהְיוּ בְנֵי נֹחַ הַיּצְאִים מִן הַתֵּבָה. רַבִּי אֶלְעָזָר אָמַר, כֵּיוָן שֶׁכָּתוּב וַיִּהְיוּ בְנֵי נֹחַ, לָמָּה אָמַר הַיֹּצְאִים מִן הַתֵּבָה? וְכִי בָנִים אֲחֵרִים הָיוּ לוֹ שֶׁלֹּא יָצְאוּ מֵהַתֵּבָה?"],[10,"","אָמַר לוֹ רַבִּי אַבָּא, כֵּן, שֶׁהֲרֵי אַחַר כָּךְ הוֹלִידוּ בָנָיו בָּנִים, שֶׁכָּתוּב אֵלֶּה תּוֹלְדת שֵׁם וְגוֹ', וְהֵם לֹא יָצְאוּ מֵהַתֵּבָה. וְלָכֵן כָּתוּב הַיֹּצְאִים מִן הַתֵּבָה שֵׁם וְחָם וָיָפֶת."],[11,"","רַבִּי שִׁמְעוֹן אָמַר, אִלּוּ הָיִיתִי מָצוּי בָּעוֹלָם כְּשֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא סִפְרוֹ שֶׁל חֲנוֹךְ בָּעוֹלָם וְסִפְרוֹ שֶׁל אָדָם, הָיִיתִי מִתְחַזֵּק שֶׁלֹּא יִמָּצְאוּ בֵּין הָאֲנָשִׁים, כִּי לֹא חָשְׁשׁוּ כָּל הַחֲכָמִים לְהִסְתַּכֵּל בָּהֶם וְטָעוּ בִּדְבָרִים אֲחֵרִים לְהוֹצִיא מֵרָשׁוּת עֶלְיוֹנָה לְרָשׁוּת אַחֶרֶת, וְכָעֵת הִנֵּה חַכְמֵי הָעוֹלָם יוֹדְעִים דְּבָרִים וּמַסְתִּירִים אוֹתָם וּמִתְחַזְּקִים בַּעֲבוֹדַת רִבּוֹנָם."],[12,"","וּפָסוּק זֶה מָצָאתִי בְּסוֹד הַסּוֹדוֹת (תוספתא), שֶׁכְּשֶׁמְּעוֹרֵר חֶדְוַת כָּל הַחֶדְווֹת הַטָּמִיר הַנִּסְתָּר, זְקַן הַזְּקֵנִים מֵאִיר מִמֶּנּוּ אוֹר דַּקִּיק. חֶדְוַת כָּל הַחֶדְווֹת מֵאִיר לְיָמִין בְּשֶׁמֶן מִשְׁחָה עֶלְיוֹן, וּמֵאִיר לַשְּׂמֹאל בְּחֶדְוַת הַיַּיִן הַטּוֹב, מֵאִיר לָאֶמְצַע בְּחֶדְוָה (של הארגמן) שֶׁל שְׁנֵי צְדָדִים. רוּחַ מִתְעוֹרֶרֶת וְרוּחַ עוֹלָה וְנִתָּן בָּרוּחַ."],[13,"","דְּבֵקִים זֶה בָּזֶה. שָׁלֹשׁ נִכְנָסִים לְשָׁלֹשׁ. מִתּוֹךְ שָׁלֹשׁ יוֹצֵאת בְּרִית אַחַת שֶׁדָּבְקָה בַּבְּרִית. עוֹבֶרֶת הָרוּחַ הָעוֹלָה וּמִתְעַבֶּרֶת מִמֶּנּוּ. כְּשֶׁנִּתֶּנֶת בִּשְׁנֵי צְדָדִים, נִדְבָּקִים רוּחַ בְּרוּחַ, וּמִתְעַבְּרוֹת מִשְּׁלֹשָׁה בָנִים. וְנֹחַ וְתֵבָה יָצְאוּ מֵהֶם שְׁלֹשָׁה, כְּמוֹ שְׁלֹשֶׁת הָעֶלְיוֹנִים, וְאֵלֶּה הֵם שֶׁיָּצְאוּ מִתּוֹךְ הַתֵּבָה - שֵׁם וְחָם וָיָפֶת. שֵׁם שֶׁבְּצַד יָמִין, חָם שֶׁבְּצַד שְׂמֹאל, יֶפֶת אַרְגָּמָן שֶׁכּוֹלֵל אוֹתָם."]]],[["וְחָם הוּא אֲבִי כְנָעַן. זוּהֲמָא דְדַהֲבָא תְּחוֹת קַסְטִיפִין. אִתְעֲרוּתָא דְּרוּחָא מְסָאֲבָא דְּנָחָשׁ קַדְמָאָה. וּבְגִין כָּךְ רְשִׁים וְאָמַר, וְחָם הוּא אֲבִי כְנָעַן. דְּאַיְיתֵי לְוָוטִין עַל עָלְמָא. הַהוּא כְנָעַן דְּאִתְלַטְּיָא. הַהוּא כְנָעַן דְּאַחְשִׁיךְ אַנְפֵּי בְּרִיָּין.","וּבְגִין כָּךְ (כלהו) לָא נָפִיק מִגּוֹ כְּלָלָא דְּכֻלְהוּ אֶלָּא דָא דִּכְתִיב וְחָם הוּא אֲבִי כְנָעַן. הַהוּא דְּאַחְשִׁיךְ עָלְמָא, וְלָא כְּתִיב בִּכְלָלָא דָא וְשֵׁם הוּא אֲבִי כָךְ אוֹ יֶפֶת הוּא אֲבִי כָךְ, אֶלָּא מִיָּד קָפַץ וְאָמַר וְחָם הוּא אֲבִי כְנָעַן. וַדַּאי.","וְעַל דָּא כַּד אֲתָא אַבְרָהָם מַה כְּתִיב (בראשית י״ב:ו׳) וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. דְּעַד לָא הֲוָה קִיּוּמָא דְּאֲבָהָן וְלָא אָתוּ זַרְעָא דְיִשְׂרָאֵל בְּעָלְמָא, דְּיִפּוּק שְׁמָא דָא וְיֵיעוּל שְׁמָא עִלָּאָה קַדִּישָׁא. כַּד הֲווּ זַכָּאִין יִשְׂרָאֵל אִקְרֵי אַרְעָא עַל שְׁמָא דָא אֶרֶץ יִשְׂרָאֵל. כַּד לָא זָכוּ אִקְרֵי אַרְעָא עַל שְׁמָא אָחֳרָא, אֶרֶץ כְּנָעַן.","וְעַל דָּא כְּתִיב, (בראשית ט׳:כ״ה) וַיֹּאמֶר אָרוּר כְּנַעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. דְּאִיהוּ אַיְיתֵי לְוָוטִין עַל עָלְמָא. וּבְנָחָשׁ מַה כְּתִיב, (בראשית ג׳:י״ד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה. הַיְינוּ דִכְתִיב עֶבֶד עֲבָדִים. וְעַל דָּא כְּתִיב שֵׁם חָם וְיָפֶת. תְּלַת אִלֵין בְּנֵי נֹחַ הַיּוֹצְאִים מִן הַתֵּיבָה כִּדְקָאַמְרִינָן:","שְׁלשָׁה אֵלֶּה בְּנִי נֹחַ. קִיּוּמָא דְּכָל עָלְמָא, קִיּוּמָא דְרָזָא עִלָּאָה. וּמֵאֵלֶּה נָפְצָה כָל הָאָרֶץ. הַיְינוּ רָזָא (דא) דִּתְלַת גְּוָונִין עִלָּאִין. דְּכַד הַהוּא נָהָר דְּנָגִיד וְנָפִיק אַשְׁקֵי לְגִנְתָא בְּחֵילָא דִתְלַת אִלֵּין עִלָּאִין. וּמִתַּמָּן אִתְפָּרְשָׁן גְּוָונִין דִּלְתַתָּא כָּל חַד וְחַד כָּלִיל בְּחַבְרֵיהּ, לְאַחֲזָאָה דִּיקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְפַּשַּׁט לְעֵילָא וְתַתָּא, וְאִיהוּ חַד בְּעִלָּאֵי וְתַתָּאֵי.","אָמַר רַבִּי אֶלְעָזָר תְּלַת גְּוָונִין אִלֵּין בְּכָל אִנוּן דְּאַתְיָין מִסְּטַר דִּקְדוּשָׁה, וּמֵחֵיזוּ דִּתְלַת גְּוָונִין אִלֵּין מִתְפָּרְשָׁאן לְכָל אִנוּן דְּאַתְיָין מִסִּטְרָא דְרוּחָא אָחֳרָא. וְכַד תִּסְתַּכֵּל בְּרָזָא דְדַרְגִּין תִּשְׁכַּח הֵיךְ מִתְפָּרְשָׁן גְּוָונִין לְכָל אִנוּן סִטְרִין עַד דְּעָיְילִין לְתַתָּא בְּרָזָא דְּאִנוּן שִׁבְעָה וְעֶשְׂרִין צִנּוֹרִין (סטרי) דְּדַשֵּׁי דְּחָפְיָין לִתְהוֹמֵי.","וְכֹלָּא יְדִיעָא לַחֲכִימִין עֶלְיוֹנִין. זַכָּאָה חוּלַקְהוֹן דְּצַדִּיקַיָיא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בִּיקְרֵיהוֹן וְגָלֵי לוֹן סִתְרִין עִלָּאִין דְּחָכְמְתָא, עֲלַיְיהוּ כְּתִיב, (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר (ישעיהו כ״ה:א׳) יְיָ אֱלהַי אַתָּה אֲרוֹמִמְךָ אוֹדֶה שִׁמְךָ כִּי עָשִׂיתָ פֶּלֶא עֵצוֹת מֵרָחוֹק אֱמוּנָה אֹמֶן. כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּכָּלָא בִּיקְרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּלְשַׁבְּחָא לִיקָרֵיהּ. בְּגִין דְּכָל מַאן דְּיָדַע לְשַׁבְּחָא לְמָארֵיהּ כְּדְקָא יָאוֹת, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ רְעוּתֵיהּ. וְלָא עוֹד אֶלָּא דְאַסְגֵּי בִּרְכָאן לְעֵילָא וְתַתָּא.","וְעַל דָּא מַאן דְּיָדַע לְשַׁבְּחָא לֵיהּ לְמָארֵיהּ וּלְיַחֲדָא שְׁמֵיהּ, חָבִיב הוּא לְעֵילָא וְחָמִיד לְתַתָּא וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּבֵּחַ בֵּיהּ (נ\"א ביקריה), וְעֲלֵיהּ כְּתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר:","וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כֶּרֶם. רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי. חַד אָמַר מִגַּן עֵדֶן (אתרכבת) אִתְתַּרְכַת וּנְצִיב לָהּ הָכָא. וְחַד אָמַר בְּאַרְעָא הֲוַת וְעָקַר לָהּ וְשָׁתַל לָהּ, וּבְהַהוּא יוֹמָא עַבְדַת אִיבִּין וְנִיצַת לַבְלְבִין וְעֲנָבִים וְהֲוָה סָחִיט לָהּ וְשָׁתֵי מִן חַמְרָא וְרָוֵי.","רַבִּי שִׁמְעוֹן אָמַר רָזָא דְּחָכְמְתָא אִיהוּ הָכָא בְּהַאי קְרָא. כַּד בָּעָא נֹחַ לְמִבְדַּק בְּהַהוּא חוֹבָא דְּבָדַק אָדָם הָרִאשׁוֹן. לָאו לְאִתְדַּבְּקָא בֵּיהּ, אֶלָּא לְמִנְדַע וּלְאַתְקָנָא עָלְמָא וְלָא יָכִיל. סָחַט עֲנָבִים לְמִבְדַּק בְּהַהוּא כֶּרֶם. כֵּיוָן דְּמָטָא לְהַאי, (ד\"א כדין) וַיִּשְׁכָּר וַיִּתְגָּל. וְלָא הֲוָה לֵיהּ חֵילָא לְמֵיקַם. וּבְגִין כָּךְ וַיִּתְגָּל גַּלֵּי פִּרְצָה דְעָלְמָא דְּהֲוָה סָתִים. בְּתוֹךְ אָהֳלֹה כְּתִיב בְּה\"א. וְעַל דָּא כְּתִיב וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ. בְּתוֹךְ אָהֳלָהּ דְּהַהוּא כָּרֶם."],[[0,"וחם הוא אבי כנען וכו':","כנען הוא זוהם הזהב שמתחת הפסולת, היינו הנשקע בתוך כור הזהב בעת ההתוך, הוא התעוררות רוח הטומאה של נחש הקדמוני, כי חם הוא קו שמאל שה\"ס זהב, וכנען הוא הפסולת שלו, והוא בחינת נחש הקדמוני, ומשום זה מדייק הכתוב ואומר \u0003וחם הוא אבי כנען,\u0004 אותו כנען שהביא קללות על העולם, אותו כנען שנתקלל, אותו כנען שהחשיך פני הבריות. דהיינו הנחש, שפיתה את חוה והביא קללות על העולם והוא נתקלל, והחשיך פני הבריות, שהביא מיתה על הבריות."],[1,"ובג\"כ לא נפיק וכו':","ומשום זה לא יצא מן כלל כולם, אלא חם, שכתוב בו וחם הוא אבי כנען. להורות על אותו שהחשיך העולם, דהיינו כח הנחש ולא כתוב בכלל זה, ושם הוא אבי כך, או יפת הוא אבי כך, אלא מיד קפץ ואמר, וחם הוא אבי כנען, ודאי הוא כמו שאמרנו שמשמיענו שהקו שמאל שהוא חם, הוא אביו של נחש הקדמוני, הנק' כנען."],[2,"וע\"ד כד אתא אברהם וכו':","וע\"כ כאשר בא אברהם מה כתוב, ויעבור אברם בארץ וגו' והכנעני אז בארץ, כי עוד לא היה הקיום של האבות, דהיינו המוחין שהמשיכו להנוקבא, הנקראת ארץ, ועוד לא באו זרע ישראל לעולם, שיצא שם זה של כנען מהארץ, ויכנוס בה שם העליון הקדוש, שהוא ישראל, פירוש. ארץ, ה\"ס הנוקבא דז\"א. וכל עוד שלא תקנו אותה האבות בסוד ג' קוין, היתה רק בבחינת קו שמאל בלבד שה\"ס זהב שנמשך ממנו פסולת הזהב, שהוא בחינת נחש הקדמוני הנקרא כנען, (כנ\"ל בדיבור הסמוך) וז\"ש הכתוב, והכנעני אז בארץ. וז\"ש, \u0003כד הוו זכאין ישראל, אקרי ארעא על שמא דא ארץ ישראל,\u0004 כאשר היו ישראל צדיקים והמשיכו ג' הקוין להנוקבא, ונזדווגה עם ז\"א הנקרא ישראל, נקראת אז הארץ על שם הזה ארץ ישראל, דהיינו על שם ישראל התחתונים שתקנוה, וע\"ש ז\"א בעלה. \u0003כד לא זכו אקרי ארעא על שמא אחרא. ארץ כנען.\u0004 כשלא זכו ישראל, והשאירו הנוקבא בקו שמאל שיש בו פסולת הנקרא כנען, נקראת אז הארץ בשם אחר. דהיינו ארץ כנען."],[3,"ועל דא כתיב וכו':","וע\"כ כתוב, ויאמר ארור כנען עבד עבדים יהיה לאחיו. שהוא להיותו בחינת נחש הקדמוני, שהביא קללות על העולם, ובנחש מה כתוב, ארור אתה מכל הבהמה, וע\"כ קללו גם עתה ארור כנען, והיינו עבד עבדים יהיה לאחיו. כי הבהמות המה עבדים לאדם, ולהיותו עוד גרוע ומקולל יותר מכל בהמה, הריהו עבד עבדים. ועל כן כתוב, בשם חם ויפת, שלשה אלה בני נח היוצאים מן התיבה, כמו שאמרנו, שה\"ס ג' הקוין, שהנוקבא הנקראת תיבה, קבלה אותם מז\"א, ונתעברה מהם והוציאה אותם להעולם. כנ\"ל באות רצ\"ז."],[4,"שלשה אלה בני נח וכו':","הם הקיום של כל העולם. קיום פירושו מוחין והיינו המוחין של הנוקבא, הנקראת עולם. הם הקיום של סוד העליון, היינו המוחין שבבינה. \u0003ומאלה נפצה כל הארץ,\u0004 היינו שכל הנשמות של בני אדם באים מהם. כי הם הסוד של ג' צבעים העליונים שבבינה, שהם ג' קוין. פירוש. כי ג' קוין הללו נתקנו מתחילה בבינה העליונה, ואח\"כ קבלם ז\"א והשפיע אותם לנוקבא. כנ\"ל באות רצ\"ז והנוקבא הולידה אותם, שהם שם חם ויפת, שמהם נתפשטו כל באי העולם. כלומר, שכל המוחין שבעולם מהם באים."],[4,"דכד ההוא נהר וכו':","כי כאשר הנהר הנמשך ויוצא מעדן, שהוא ז\"א (כנ\"ל בראשית א' דף רי\"א אות רמ\"ז), השקה את הגן, שהיא הנוקבא, השקה אותה בכח שלשה קוין, הללו העליונים, מהבינה העליונה, ומשם נתפשטו הגוונין, לבן אדום ושחור, שה\"ס ג' הקוין, שלמטה, של הנוקבא, כל אחד ואחד כלול בחבירו, להראות, כי כבודו של הקב\"ה מתפשט למעלה בבינה ולמטה במלכות, והוא אחד בעליונים ובתחתונים."],[5,"אמר רבי אלעזר וכו':","אר\"א ג' גוונין הללו הם בכל אלו המוחין הבאים מצד הקדושה. ומהמראה שלהם, דהיינו המלכות, שהוא חיזו הנכללתת מג' הגוונין, (כנ\"ל אות רס\"ו) מתפשטים לכל אלו הבאים מצד רוח האחר פירוש. כי הוקשה לו, כיון ששם חם ויפת ה\"ס ג' הקוין של המוחין דקדושה, איך נתפשטו מהם כל באי עולם, דהיינו אפילו הרשעים. וע\"ז אומר, שהם נתפשטו מהחיזו דג' קוין, שה\"ס המלכות. והיינו סו\"ה, ומלכותו בכל משלה. כי אפילו הס\"א מתקיימת על ידיה. אבל בג' קוין עצמם, אין יניקה רק לצד הקדושה."],[5,"וכד תסתכל ברזא וכו':","וכאשר תסתכל בסוד המדרגות, תמצא, איך הגוונין מתפשטים. לכל אלו הצדדים, דהיינו ימין שמאל אמצע, עד שנכנסים למטה, להמלכות, בסוד שהם כ\"ז צנורות של הדלתות המכסים את התהום."],[5,"","פירוש. האותיות נמשכות מבינה ובאים לז\"א ומשתלמים בהנוקבא, וכשהם נמשכות מהבינה לז\"א הם במספר כ\"ב אותיות הנאצלים בסוד ג' הקוין, ז' אותיות בקו ימין, ז' אותיות בקו שמאל, ושמונה אותיות בקו אמצעי שהם כ\"ב אותיות, וכבר נתבאר ענין זה היטב בהזהר (לעיל בראשית א' דף מ\"ו אות ל\"ד ע\"ש בהסולם) ונמצא שמעצם ג' הקוין נמשכים רק כ\"ב אותיות, אלא כשהם נמשכים להמלכות, שה\"ס ה' גבורות, יצאו מהן, אותיות מנצפך, הבאות בסיום המלה, ונעשה מספרם כ\"ז אותיות. וז\"ש, \u0003וכד תסתכל ברזא דדרגין,\u0004 כשתסתכל בג' הקוין כשנמשכים דרך המדרגות, מבינה עד מלכות, \u0003תשכח היך מתפרשן גוונין לכל אינון סטרין,\u0004 דהיינו שהגוונין מתפרשין לעצם ג' הסטרין, ונעשו כ\"ב אותיות. \u0003עד דעיילין לתתא,\u0004 עד שנכנסים למטה, להמלכות, שהוא חיזו דתלת גוונין. \u0003ברזא דאינון שבעה ועשרין צנורין דדשי דחפיין לתהומי\u0004 שהם נעשים שם בסוד כ\"ז אותיות דהיינו עם ה' האותיות \u0003מנצפ\"ך\u0004 של המלכות, שה\"ס כ\"ז צנורות מביאי השפע אליה, שנעשו מהם דלתות לכסות על הדינים שבהמלכות הנקראים תהומות."],[6,"וכלא ידיעא וכו':","וכל זה ידוע להחכמים העליונים. אשרי חלקם של הצדיקים, שהקב\"ה רצה בכבודם, וגילה להם נסתרות העליונות של החכמה, עליהם כתוב, סוד ה' ליראיו ובריתו להודיעם."],[7,"פתח רבי אלעזר וכו':","פתח ר\"א ואמר ה' אלקי אתה וגו'. כמה יש להם לבני אדם להסתכל בכבודו של הקב\"ה, ולשבח לכבודו, משום, שכל מי שיודע לשבח לרבונו כראוי, הקב\"ה עושה לו רצונו. ולא עוד, אלא שמרבה ברכות למעלה ולמטה."],[8,"וע\"ד מאן וכו':","ועל כן, מי שיודע לשבח לרבונו, וליחד את שמו, חביב הוא למעלה, ונחמד למטה, והקב\"ה משתבח בו, ועליו כתוב, ויאמר לי עבדי אתה ישראל אשר בך אתפאר."],[9,"ויחל נח איש האדמה ויטע כרם:","חולקים בזה ר' יהודה ור' יוסי אחד אמר, שהגפן מגן עדן נגרשה ונטע אותה כאן באדמה, ואחד אמר, שהגפן בארץ היה, ועקר אותה ממקומה, ושתלה במקום אחר, וע\"כ כתוב ויטע, ובאותו יום עשתה פירות, והניצה ציץ וענבים, והיה סחט אותה, ושתה מהיין ונשכר, פירוש. אחד אומר, שה\"ס עץ הדעת שחטא בו אדה\"ר. וסבר שעצה\"ד גפן היתה, וכשחטא בה אדה\"ר, נגרשה עמו יחד מג\"ע. ונח תקן את הגפן הגרושה הזו, וחזר ונטעה מחוץ לג\"ע, ושתה מיינה ונשכר. ודומה חטאו לחטא אדה\"ר. ואחד אומר, שגפן זו לא היתה בג\"ע, אלא מחוץ לג\"ע מצא אותה. ומ\"ש ויטע, הוא מפני שעקרה ממקומה ושתלה במקום אחר. ולדבריו אינו דומה חטאו של נח לחטאו של אדה\"ר."],[10,"ר' שמעון אמר וכו':","רש\"א, סוד החכמה יש כאן במקרא הזה. כי כאשר בא נח לבדוק באותו החטא, דעצה\"ד, שבדק אדם הראשון, ולא להתדבק בו, אלא לדעת ולתקן העולם. ולא יכול לתקנו, סחט ענבים כדי לבדוק בכרם ההוא. וכיון שהגיע לזה, אז, וישכר ויתגל, ולא היה לו כח לקום ומשום זה, אומר הכתוב \u0003ויתגל\u0004 שגילה הפרצה של העולם שהיתה סתומה. \u0003בתוך אהלה\u0004 כתוב ב \u0003ה'\u0004 ולא אהלו ב \u0003ו',\u0004 וע\"כ כתוב, ולא תקרב אל פתח ביתה, כי המשמעות היא \u0003בתוך אהלה\u0004 של כרם ההוא ולא בתוך אהלה של עצמו, וע\"כ כתוב ב \u0003ה'\u0004 ולא ב \u0003ו'.\u0004"],[10,"","פירוש. ב' נקודות הם בבנין הנוקבא, האחת, היא ממותקת בבינה, ומבחינתה נעשית ראויה לקבל המוחין כמו הכלים דבינה. והשניה, היא בחינתה עצמה, מדת הדין, שאינה נמתקת במדת הרחמים. ומבחינה זו אינה יכולה לקבל שום מוחין עליונים, כי עליה היה צמצום א' שלא לקבל לתוכה כלום מבחינת אור ישר. וזה מבואר בהקדמת הזהר דף קכ\"ג אות קכ\"ב ע\"ש. ולפיכך אומר שם, \u0003חד גניזא וטמירא\u0004 דהיינו הנקודה דמדת הדין. \u0003וחד קיימא באתגליא\u0004 דהיינו הנקודה הממותקת בהבינה, במדת הרחמים. וכיון שנקודה דמה\"ד גניזא וטמירא, ע\"כ ראויה לקבל כל המוחין העליונים. ע\"י הנקודה דמדת הרחמים הגלויה בה. ובזה תבין ענין איסור אכילת עץ הדעת שאמר לו הקב\"ה ביום אכלך ממנו מות תמות. כי הזהר אומר שם (באות קכ\"ג) שמטעם ב' נקודות הללו, נקראת הנוקבא עץ הדעת טוב ורע, \u0003זכי בר נש הא טוב,\u0004 דהיינו שנזהר שלא להמשיך הארת השמאל שבהנוקבא ממעלה למטה, היא עצה\"ד טוב, ומקבל ממנה כל המוחין שבה, \u0003ואם לא זכי הא רע,\u0004 דהיינו שממשיך הארת השמאל שבה, ממעלה למטה, שזה נבחן לאכילת עצה\"ד, אז \u0003הא רע,\u0004 כי נקודה דמדת הדין שהיתה גניזא וטמירא היא מתגלית, ואז מסתלקים כל המוחין מהנוקבא, כי מבחינה זו אינה ראויה לקבל מוחין כנ\"ל, וזהו המיתה לבאי עולם, כי המוחין שלה הם החיים של כל באי העולם, וז\"ס ביום אכלך ממנו מות תמות, כי תתגלה נקודה דמה\"ד, ויסתלקו ממנה המוחין, שהם החיים של האדם שהוא מקבל ממנה, וע\"כ ימות."],[10,"","והנה ר' יהודה ורבי יוסי חולקים לעיל, אם חטאו של נח דומה לעצה\"ד או לא. ור\"ש מכריע ביניהם, ואומר שהחטא עצמו הוא כעצה\"ד, אבל לא נתכוין לחטוא כמוהו, אלא רצה להמשיך הארת השמאל פעם אחת למטה כדי לתקן אותו, ואח\"כ יפרוש הימנו."],[10,"","וז\"ש \u0003כד בעא נח למבדק בההוא חובא דבדק אדה\"ר\u0004 כשרצה נח לבדוק באותו החטא שבדק אדה\"ר, דהיינו שבדק לראות אם ימות על ידו, כי הנחש שיקר בשמא דקב\"ה ואמר לא מות תמותון וגו', \u0003לאו לאתדבקא ביה אלא למנדע ולאתקנא עלמא, ולא יכיל,\u0004 ולא רצה להתדבק בו כאדה\"ר שאמר אכלתי ואוכל עוד (בראשית רבה פי\"ט י\"ב) אלא לדעת ולתקן העולם ואח\"כ יפרוש ממנו, אבל לא יכול לתקן אותו. ומפרש, \u0003סחט ענבים למבדק בההוא כרם,\u0004 סחט ענבים, פירושו, המשכת הארת השמאל, כי הארת השמאל מכונה יין (כנ\"ל דף פ\"ד ד\"ה פירוש) \u0003לבדוק באותו הכרם,\u0004 פירושו. שהמשיכה ממעלה למטה כדי לבדוק אם יתגלה מדת הדין בהכרם, ואז יתקן אותו כנ\"ל, \u0003כיון דמטא להאי,\u0004 דהיינו להמשיך הארת השמאל ממעלה למטה. \u0003כדין וישכר ויתגל,\u0004 אז נשתכר ונתגלה הנקודה דמדת הדין, ותכף נסתלקו ממנו המוחין \u0003ולא הוה ליה חילא למיקם\u0004 ולא היה לו עוד כח לקום. \u0003ובג\"כ ויתגל, גלה פרצה דעלמא דהוה סתים,\u0004 וע\"כ אומר ויתגל, כי גילה פרצת העולם, שהיא הנקודה דמדת הדין, שעד כאן היתה גניזא וטמירא כנ\"ל ועתה נתגלתה. \u0003בתוך אהלה כתיב בה',\u0004 הרומז על אהל הנוקבא דקליפה, הנקראת אשה זרה, \u0003וע\"ד כתיב ואל תקרב אל פתח ביתה,\u0004 של אותה אשה זרה, \u0003בתוך אהלה דההוא כרם,\u0004 והוא בתוך האהל של אותו הכרם. כלומר. אהל פירושו הארה, מלשון בהלו נרו וגו'. (איוב כ\"ט) והכתוב אומר שהנקודה דמה\"ד נתגלה, בתוך הארת הכרם שהמשיך ממעלה למטה."]],[[0,"","וְחָם הוּא אֲבִי כְנָעַן, זֻהֲמַת הַזָּהָב תַּחַת סִיגִים. הִתְעוֹרְרוּת רוּחַ הַטֻּמְאָה שֶׁל נָחָשׁ הַקַּדְמוֹנִי. וְלָכֵן רָשַׁם וְאָמַר, וְחָם הוּא אֲבִי כְנָעַן. שֶׁהֵבִיא קְלָלוֹת עַל הָעוֹלָם. אוֹתוֹ כְּנַעַן שֶׁהִתְקַלֵּל, אוֹתוֹ כְנַעַן שֶׁהֶחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת."],[1,"","וְלָכֵן (כלם) לֹא יָצָא מִכְּלַל כֻּלָּם, אֶלָּא זֶה שֶׁכָּתוּב וְחָם הוּא אֲבִי כְנָעַן, אוֹתוֹ שֶׁהֶחְשִׁיךְ אֶת הָעוֹלָם, וְלֹא כָתוּב בִּכְלַל זֶה וְשֵׁם הוּא אֲבִי כָּךְ אוֹ יֶפֶת הוּא אֲבִי כָּךְ, אֶלָּא מִיָּד קָפַץ וְאָמַר וְחָם הוּא אֲבִי כְנָעַן. וַדַּאי."],[2,"","וְעַל זֶה, כְּשֶׁבָּא אַבְרָהָם, מַה כָּתוּב? (בראשית יב) וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. שֶׁעֲדַיִן לֹא הָיָה קִיּוּם שֶׁל הָאָבוֹת וְלֹא בָאוּ זֶרַע שֶׁל יִשְׂרָאֵל לָעוֹלָם שֶׁיֵּצֵא הַשֵּׁם הַזֶּה וְיִכָּנֵס שֵׁם עֶלְיוֹן קָדוֹשׁ. כְּשֶׁהָיוּ יִשְׂרָאֵל צַדִּיקִים, נִקְרְאָה הָאָרֶץ עַל הַשֵּׁם הַזֶּה - אֶרֶץ יִשְׂרָאֵל. כְּשֶׁלֹּא זָכוּ, נִקְרְאָה הָאָרֶץ עַל שֵׁם אַחֵר - אֶרֶץ כְּנַעַן."],[3,"","וְעַל זֶה כָּתוּב (שם ט) וַיֹּאמֶר אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. שֶׁהוּא הֵבִיא קְלָלוֹת עַל הָעוֹלָם. וּבַנָּחָשׁ מַה כָּתוּב? (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה, הַיְנוּ מַה שֶּׁכָּתוּב עֶבֶד עֲבָדִים. וְעַל זֶה כָּתוּב שֵׁם וְחָם וָיָפֶת. שְׁלֹשֶׁת אֵלֶּה בְּנֵי נֹחַ הַיּוֹצְאִים מִן הַתֵּבָה, כְּמוֹ שֶׁאָמַרְנוּ."],[4,"","שְׁלשָה אֵלֶּה בְּנֵי נֹחַ, הַקִּיּוּם שֶׁל כָּל הָעוֹלָם, הַקִּיּוּם שֶׁל סוֹד עֶלְיוֹן. וּמֵאֵלֶּה נָפְצָה כָל הָאָרֶץ, הַיְנוּ סוֹד (זה) שֶׁל שְׁלֹשֶׁת הַגְּוָנִים הָעֶלְיוֹנִים. שֶׁכְּשֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מַשְׁקֶה אֶת הַגָּן בַּכֹּחַ שֶׁל שְׁלֹשֶׁת הָעֶלְיוֹנִים הַלָּלוּ. וּמִשָּׁם נִפְרָדִים הַגְּוָנִים שֶׁלְּמַטָּה כָּל אֶחָד וְאֶחָד כָּלוּל בַּחֲבֵרוֹ, לְהַרְאוֹת שֶׁכְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְפַּשֵּׁט לְמַעְלָה וּלְמַטָּה, וְהוּא אֶחָד בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים."],[5,"","אָמַר רַבִּי אֶלְעָזָר, שְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ בְּכָל אוֹתָם שֶׁבָּאִים מִצַּד הַקְּדֻשָּׁה, וּמִמַּרְאֶה שֶׁל שְׁלֹשֶׁת גְּוָנִים אֵלּוּ נִפְרָדִים לְכָל אוֹתָם שֶׁבָּאִים מִצַּד הָרוּחַ הָאַחֶרֶת, וּכְשֶׁתִּסְתַּכֵּל בְּסוֹד הַדְּרָגוֹת תִּמְצָא אֵיךְ נִפְרָדִים הַגְּוָנִים לְכָל אוֹתָם הַצְּדָדִים, עַד שֶׁנִּכְנָסִים לְמַטָּה בַּסּוֹד שֶׁל אוֹתָם עֶשְׂרִים וְשִׁבְעָה הַצִּנּוֹרוֹת, (הצדדים) שֶׁל הַדְּלָתוֹת שֵׁמְּכַסִּים אֶת הַתְּהוֹמוֹת."],[6,"","וְהַסֹלֹ יָדוּעַ לַחֲכָמִים עֶלְיוֹנִים. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם וְגִלָּה לָהֶם סִתְרֵי חָכְמָה עֶלְיוֹנִים, עֲלֵיהֶם כָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם."],[7,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיה כה) ה' אֱלֹהַי אַתָּה אֲרוֹמִמְךְ אוֹדֶה שִׁמְךְ כִּי עָשִׂיתָ פֶּלֶא עֵצוֹת מֵרָחֹק אֱמוּנָה אֹמֶן. כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִסְתַּכֵּל בִּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְשַׁבֵּחַ לִכְבוֹדוֹ, מִשּׁוּם שֶׁכָּל מִי שֶׁיּוֹדֵעַ לְשַׁבֵּחַ אֶת רִבּוֹנוֹ כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אֶת רְצוֹנוֹ, וְלֹא עוֹד - אֶלָּא שֶׁמַּרְבֶּה בְרָכוֹת לְמַעְלָה וּלְמַטָּה."],[8,"","וְעַל כֵּן, מִי שֶׁיּוֹדֵעַ לְשַׁבֵּחַ אֶת רִבּוֹנוֹ וּלְיַחֵד אֶת שְׁמוֹ, חָבִיב הוּא לְמַעְלָה וְנֶחְמָד לְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ (בכבודו), וְעָלָיו כָּתוּב (שם מט) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[9,"","וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כֶּרֶם. רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי. אֶחָד אָמַר מִגַּן עֵדֶן (נתרכבה) גֹּרְשָׁה וְנָטַע אוֹתָהּ כָּאן. וְאֶחָד אָמַר בָּאָרֶץ הָיְתָה, וְעָקַר אוֹתָהּ וְשָׁתַל אוֹתָהּ, וּבְאוֹתוֹ יוֹם עָשְׂתָה פֵרוֹת וְנִצְנְצוּ לִבְלוּבִים וַעֲנָבִים, וְהָיָה סוֹחֵט אוֹתָהּ וְשׁוֹתֶה מֵהַיַּיִן וּמִשְׁתַּכֵּר."],[10,"","רַבִּי שִׁמְעוֹן אָמַר, סוֹד הַחָכְמָה הוּא כָּאן בַּפָּסוּק הַזֶּה. כְּשֶׁרָצָה נֹחַ לִבְדֹּק בְּאוֹתוֹ חֵטְא שֶׁבָּדַק אָדָם הָרִאשׁוֹן - לֹא כְּדֵי לְהִתְדַּבֵּק בּוֹ, אֶלָּא לָדַעַת וּלְתַקֵּן הָעוֹלָם, וְלֹא יָכֹל. סָחַט עֲנָבִים לִבְדֹּק בְּאוֹתוֹ כֶּרֶם. כֵּיוָן שֶׁהִגִּיעַ לָזֶה, (אז) וַיִּשְׁכָּר וַיִּתְגַּל, וְלֹא הָיָה לוֹ כֹּחַ לַעֲמֹד. וְלָכֵן וַיִּתְגַּל, גִּלָּה פִּרְצָה שֶׁל הָעוֹלָם שֶׁהָיְתָה נִסְתֶּרֶת. בְּתוֹךְ אָהֳלֹה, כָּתוּב בְּהֵ\"א. וְעַל זֶה כָּתוּב וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ. בְּתוֹךְ אָהֳלָהּ שֶׁל אוֹתָהּ כֶּרֶם."]]],[["כְּגַוְונָא דָא בְּנֵי אַהֲרֹן דְּתָנִינָן שְׁתוּיֵי יַיִן הֲווּ. וְכִי מַאן יָהִיב לוֹן חַמְרָא בְּהַהוּא אֲתַר לְמִשְׁתֵּי. אִי סַלְקָא דַעְתָּךְ דְּאִנוּן חֲצִיפִין הֲווּ דְּרָווֹ חַמְרָא. לָאו הָכִי, אֶלָּא וַדַּאי מֵהַהוּא חַמְרָא רָווֹ דִּכְתִיב, (ויקרא י׳:א׳) וַיַּקְרִיבוּ לִפְנֵי יְיָ אֵשׁ זָרָה. כְּתִיב הָכָא אֵשׁ זָרָה וּכְתִיב הָתָם (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָּׁה זָרָה וְכֹלָּא חַד מִלָּה.","וְכֵן כְּגַוְונָא דָא וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל. וְעַל דָּא אִתְעַר חָם אֲבִי כְנָעַן כְּמָה דְּאִתְּמָר וְאִתְיְהִיב אֲתַר לִכְנַעַן לְשַׁלְטָאָה, וּמַאי דְּהֲוָה הָדֵין צַדִּיק בְּרָזָא דִּבְרִית סֵרְסוֹ. וְתַנְיָא דְּאַעֲבַר מִינֵיהּ הַהוּא קִיּוּמָא.","וּבְגִין כָּךְ אָמַר אָרוּר דְּהָא לְוָוטִין אִתְעָרוּ בְּקַדְמִיתָא עַל יְדֵיהּ בְּעָלְמָא. (ועל דא ויאמר ארור כנען דהא לווטין ייתון על עלמא כקדמיתא). עֶבֶד עֲבָדִים יִהְיֶה כְּמָא דְאַתְּ אָמֵר אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגו'. כֹּלָּא יִתְתַּקַּן לְזִמְנָא דְּאָתֵי וְהוּא לָא יִתְתַּקַּן. וְכֹלָּא יִפְקוּן לְחֵירוּ וְהוּא לָא יִפּוּק. וְרָזָא אִיהוּ לְאִנוּן דְּיָדְעֵי אָרְחוֹי וּשְׁבִילֵי דְאוֹרַיְיתָא.","פָּתַח וְאָמַר (תהילים נ״א:ה׳) כִּי פְשָׁעַי אֲנִי אֵדָע וְחַטָּאתִי נֶגְדִּי תָמִיד. כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּמְּרָא מֵחוֹבַיְיהוּ מִקַּמֵי קוּדְשָׁא בְּרִיךְ הוּא. דְּהָא לְבָתַר דְּחָטָא בַּר נָשׁ רָשִׁים הוּא חוֹבֵיהּ לְעֵילָא וְלָא אִתְמְחַק בַּר בְּתוּקְפָא דִּתְיוּבְתָּא סַגְיָא. כְּמָא דְאַתְּ אָמֵר, (ירמיהו ב׳:כ״ב) כִּי אִם תְּכַבְּסִי בַּנֶּתֶר וְתַרְבִּי לָךְ בּוֹרִית נִכְתַּם עֲוֹנֵךְ לְפָנָי.","תָּא חֲזֵי, כֵּיוָן דְּחָב בַר נָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא זִמְנָא חָדָא עָבִיד רְשִׁימוּ. וְכַד חָב בֵּיהּ זִמְנָא תִּנְיָינָא אִתְתַּקַּף הַהוּא רְשִׁימוּ יַתִּיר. חָב בֵּיהּ זִמְנָא תְּלִיתָאָה אִתְפַּשַּׁט הַהוּא כִּתְמָא מִסִּטְרָא דָא לְסִטְרָא דָא, כְּדֵין כְּתִיב נִכְתַּם עֲוֹנֵךְ לְפָנָי.","תָּא חֲזֵי, דָּוִד מַלְכָּא כֵּיוָן דְּחָב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל עִסְקָא דְּבַת שֶׁבַע, חָשִׁיב דְּהַהוּא חוֹבָא אִתְרְשִׁים עֲלֵיהּ לְעָלְמִין. מַה כְּתִיב, (שמואל ב י״ב:י״ג) גַּם יְיָ הֶעֱבִיר חַטָּאתְךָ לא תָמוּת. (קודשא בריך הוא) אַעֲבַר הַהוּא רְשִׁימוּ מִקַּמֵּיהּ.","אָמַר לֵיהּ רַבִּי אַבָּא וְהָא תָּנִינָן דְּבַת שֶׁבַע דִּילֵיהּ דְּדָוִד מַלְכָּא הֲוַת מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, אַמַּאי יָהֲבָהּ קוּדְשָׁא בְּרִיךְ הוּא לְאוּרִיָה הַחִתִּי מִן קַדְמַת דְּנָא.","אָמַר לֵיהּ הָכִי אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא אַף עַל גַּב דְּאִתְּתָא אַזְמִינָא לֵיהּ לְבַר נָשׁ לְמֶהֱוֵי דִילֵיהּ, אַקְדִים אַחֲרָא וּנְסִיב לָהּ עַד דְּמָטָא זִמְנֵיהּ דְּהַאי. כֵּיוָן דְּמָטָא זִמְנֵיהּ, אִתְדַּחְיָיא הַאי דְּנָסִיב לָהּ מִקַּמֵּי הַאי אָחֳרָא דְּאָתֵי לְבָתַר וְאִסְתַּלַּק מֵעָלְמָא. וְקָשֵׁי קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לֵיהּ מֵעָלְמָא עַד לָא מָטֵי זִמְנֵיהּ מִקַּמֵּי הַאי אָחֳרָא.","וְרָזָא דְּבַת שֶׁבַע דְּאִתְיְיהִיבַת לְאוּרִיָה הַחִתִּי (כדאמרן) בְּקַדְמִיתָא, פּוּק וְדוּק וְתִשְׁכַּח. אַמַּאי אִתְיְהִיבַת אַרְעָא קַדִּישָׁא לִכְנַעַן עַד לָא יֵיתוּן יִשְׂרָאֵל. וְתִשְׁכַּח מִלָּה דָא. וְכֹלָּא רָזָא חָדָא אִיהוּ וּמִלָּה חָדָא.","תָּא חֲזֵי, דָּוִד אַף עַל גַּב דְּאוֹדֵי עַל חוֹבֵיהּ וְתָב בִּתְיוּבְתָּא, לָא אַעֲדֵי לִבֵּיהּ וּרְעוּתֵיהּ מֵאִנוּן חוֹבִין דְּחָב, וּמֵהַהוּא חוֹבָא דְּבַת שֶׁבַע, בְּגִין דְּדָחִיל עֲלַיְיהוּ תָּדִיר דִּילְמָא גָּרִים חַד מִנַּיְיהוּ וִיקַטְרֵג עֲלֵיהּ בְּשַׁעֲתָא דְסַכָּנָה. וּבְגִין כָּךְ לָא אַנְשֵׁי לוֹן מִינֵיהּ וּמֵרְעוּתֵיהּ.","דָבָר אֲחַר כִּי פְשָׁעַי אֲנִי אֵדָע כֻּלְהוּ דַּרְגִּין דְּתַלְיָין בְּהוּ חוֹבֵי בְּנֵי נָשָׁא אֲנִי אֵדָע. וְחַטָּאתִי נֶגְדִּי תָמִיד דָּא פְּגִימוּ דְסִיהֲרָא דְּלָא נָפְקָא מִסְאוּבְתָּא עַד דְּאָתָא שְׁלֹמֹה וְאִתְנְהִירַת בְּאַשְׁלָמוּתָא. וּכְדֵין אִתְבַּסָּם עָלְמָא וִיתִיבוּ יִשְׂרָאֵל לְרָחֲצָן דִּכְתִיב, (מלכים א ה׳:ה׳) וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַח אִישׁ תַּחַת גַּפְנוֹ וְתַחַת תְאֵנָתוֹ. וְעִם כָּל דָּא וְחַטָּאתִי נֶגְדִּי תָמִיד. וְלָא אִתְפְּסָק מֵעָלְמָא. עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא לְזִמְנָא דְּאָתֵי כְּמָה דְּאִתְּמָר (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר מִן הָאָרֶץ:","הוּא הָיָה גִּבּוֹר צַיִּד לִפְנִי יְיָ עַל כֵּן יֵאָמַר כְּנִמְרוֹד גִּבּוֹר צַיִד לִפְנֵי יְיָ. תָּא חֲזֵי, הוּא הֲוָה גְּבַר תַּקִּיף. לְבוּשׁוֹי דְּאָדָם הָרִאשׁוֹן הֲוָה לָבִישׁ וְהֲוָה יָדַע לְמֵיצַד צֵידָה דִּבְרִיָּיתָא בְּהוּ.","אָמַר רַבִּי אֶלְעָזָר נִמְרוֹד הֲוָה מְפַתֵּי לִבְרִיָּיתָא לְמֵיהַךְ בָּתַר פּוּלְחַן דְּעַבוֹדָה זָרָה וְהֲוָה שַׁלִּיט בְּאִנוּן לְבוּשִׁין וְנָצַח בְּנֵי עָלְמָא וְהֲוָה אָמַר דְּאִיהוּ שַׁלִּיטָא בְּעָלְמָא וּפָלְחִין לֵיהּ בְּנִי נָשָׁא. וְאַמַּאי אִקְרֵי שְׁמֵיהּ נִמְרוֹד דְּמָרַד בְּמַלְכָּא עִלָּאָה דִּלְעֵילָא דְּמָרַד בְּעִלָּאֵי וּמָרַד בְּתַתָּאֵי."],[[0,"כגוונא דא בני אהרן:","כעין זה בבני אהרן, שלמדנו שהיו שתויי יין. ושואל, וכי מי נתן להם יין, במקום הזה, לשתות. הכי יעלה על דעתך שהיו עזי פנים כל כך שנשתכרו ביין, אינו כן. אלא ודאי מאותו היין נשתכרו, שכתוב ויקריבו לפני ה' אש זרה, ושם כתוב לשמרך מאשה זרה. והכל הוא דבר אחד. פירוש. כי ענין השכרות מיין נתבאר לעיל בדיבור הסמוך, שה\"ס המשכת הארת השמאל ממעלה למטה, שאז נגלה הנקודה דמדת הדין, ומתעוררת הקליפה דאשה זרה, והמוחין מסתלקין מהנוקבא, והחוטא מת. ע\"ש. וז\"ש ודאי מאותו היין נשתכרו, שכתוב ויקריבו אש זרה, שעם השכרות הם מקריבים הקליפה לינק מהקדושה והמוחין מסתלקים. וז\"ש \u0003כתיב ויקריבו לפני ה' אש זרה, וכתיב התם לשמרך מאשה זרה וכלא חד מלה,\u0004 כי הבחינת דכר נק' אש זרה ובחינת הנוקבא נקראת אשה זרה."],[1,"וכן כגוונא דא וכו':","וכן כעין זה, וישת מן היין וישכר \u0003ויתגל,\u0004 ועל זה נתעורר חם אבי כנען, שבסבתו נתגלה הנקודה דמדת הדין שה\"ס ערות אביו. וכמו שלמדנו שניתן מקום לכנען שישלוט, ומה שהיה צדיק הזה, נח, בסוד הברית, עקרו שעשאו סריס, ולמדנו שהעביר ממנו הברית, כלומר שנסתלקו ממנו מוחין דהולדה המתוקנים רק בתקון ברית קדש, ונבחן זה כמו שסרסו. פירוש. כי הוקשה לו הרי חם חטא בראיתו, ולא כנען, ולמה נתקלל כנען ולא חם. וז\"ש וכן כגוונא דא וכו' \u0003ויתגל.\u0004 שפירושו שנתגלה הנקודה דמדת הדין, שה\"ס ערות אביו, \u0003ועל דא אתער הם אבי כנען,\u0004 ועל התגלות הנקודה התעורר חם אבי כנען ע\"י ראיתו, להיותו קו השמאל, שנח משך הארתו ממעלה למטה, שבסבה זו נתגלה המדת הדין כנ\"ל, אבל כיון שנח לא התכוון לחטוא לא היו מסתלקים המוחין משום גילוי הנקודה, אלא \u0003ואתיהיב אתר לכנען לשלטאה,\u0004 שניתן, ע\"י הגילוי דנקודה של מדה\"ד, כח לכנען שיתקרב לינק מן הנוקבא, שקליפת כנען ה\"ס הנחש הקדמוני וה\"ס אש זרה המתקרבת בסבת הנקודה דמדה\"ד כנ\"ל בדיבור הסמוך. והוא \u0003סרסו,\u0004 שבסבת כנען נסתלקו ממנו המוחין דהולדה שה\"ס המוחין דחיה שהיה לו. הרי שחם לא עשה לו כלום אלא כנען בנו, וע\"כ קלל את כנען. אלא שהמקרא מכסה על זה משום כבוד אלקים הסתר דבר."],[2,"ובג\"כ אמר ארור וגו':","ומשום זה אמר נח \u0003ארור\u0004, כי הקללות נתעוררו תחילה בעולם על ידו. כי ה\"ס הנחש כנ\"ל, \u0003עבד עבדים יהיה וגו',\u0004 הכל יתוקן לעתיד לבא, וכנען לא יתוקן, וכל העבדים יצאו לחירות, וכנען לא יצא לחירות לעולם. וסוד הוא לאלו היודעים אורחותיה ושביליה של התורה."],[3,"פתח ואמר, כי פשעי אני אדע וגו'","כמה יש להם לבני אדם להשמר מפני הקב\"ה מעונותיהם. כי לאחר שחטא האדם נרשם עונו למעלה, ואינו נמחק, רק בתוקפה של תשובה גדולה. כמו שאתה אומר, כי אם תכבסי בנתר וגו'."],[4,"ת\"ח כיון","וכו': בוא וראה, כיון שחטא האדם לפני הקב\"ה, פעם אחת עושה רושם, וכשחטא בו בפעם השניה מתחזק הרושם יותר, חטא בו פעם שלישית, מתפשט אותו כתם מעבר אל עבר, אז כתוב נכתם עונך לפני."],[5,"ת\"ח דוד מלכא","וכו': בוא וראה, דוד המלך, כיון שחטא לפני הקב\"ה בענין בת שבע, חשב, שחטא זה נרשם עליו לעולם. מה כתוב, גם ה' העביר חטאתך לא תמות, להורות שהעביר אותו הרושם מפניו."],[6,"א\"ל רבי אבא","וכו': אמר לו ר\"א, והרי למדנו, שבת שבע, של דוד המלך היתה, מיום שנברא העולם, אם כן, למה נתנה הקב\"ה לאוריה החתי מקודם לכן."],[7,"א\"ל הכי","וכו': אמר לו, כך דרכיו של הקב\"ה, אע\"פ שהאשה מזומנת להאדם להיות שלו, מקדימו אחר ונושא אותה מקודם שהגיע זמנו של זה. כיון שהגיע זמנו, נדחה זה שנשא אותה, מפני זה השני שבא אחר כך, ומסתלק מהעולם. וקשה הדבר לפני הקב\"ה להעבירו מהעולם, מפני השני, לפני זמנו."],[8,"ורזא דבת שבע","וכו': והסוד שבת שבע ניתנה מקודם לאוריה החתי, צא ודוק, ותמצא למה ניתנה ארץ הקדש לכנען מקודם שבאו ישראל, ואז תמצא גם דבר הזה, שבת שבע ניתנה מקודם לאוריה, והכל הוא סוד אחד ודבר אחד."],[8,"","והסוד הוא. כי בת שבע וכן ארץ ישראל ה\"ס הנוקבא. ונודע שתחילת בנין הנוקבא הוא במוחין דהארת השמאל, ואח\"כ נבנית במוחין דפנים מכל ג' הקוין (כנ\"ל ב\"ב דף קל\"ה ד\"ה ביאור) ובחינת אוריה ה\"ס המוחין דחכמה בלי חסדים שה\"ס הארת השמאל. ובחינת דוד המלך ה\"ס המוחין דפנים מג' הקוין, ולפיכך אע\"פ שבת שבע בת זוגו של דוד היתה, אמנם כדי שתוכל לקבל המוחין דפנים מדוד היתה מוכרחת להנשא מקודם לאוריה כדי לקבל ממנו המוחין דאחורים מהארת השמאל. כי אי אפשר לה לקבל מוחין דפנים מטרם שקבלה המוחין דאחורים, שהם המוחין דהארת השמאל. ומאותו הטעם שלט ג\"כ כנען בארץ ישראל מטרם שניתנה לישראל כי בעת שהנוקבא מקבלת ממוחין דקו שמאל, שולט בה אז קליפת כנען, שהוא סיגי הזהב (כנ\"ל באות רצ\"ח) אבל אי אפשר לה לקבל מוחין דפנים שה\"ס ישראל, מטרם שקבלה המוחין דקו שמאל, כנ\"ל, וע\"כ בהכרח ששלט בה כנען מקודם שבאו ישראל, הרי שנתינת בת שבע לאוריה מקודם שניתנה לדוד, וכן שליטת כנען בארץ הקדש מטרם שניתנה לישראל הוא ענין אחד וסוד אחד, דהיינו מטעם שהארת קו שמאל מוכרח להנוקבא מטרם שמקבלת מג' הקוין"],[9,"ת\"ח, דוד אע\"ג וכו':","בוא וראה, דוד, אע\"פ שהתודה על חטאתו וחזר בתשובה, לא סר לבו ורצונו מאלו החטאים שחטא, ומאותו החטא דבת שבע, מפני שירא בשבילם תמיד, אולי יגרום אחד מהם ויבא לקטרג עליו בשעת הסכנה. ומשום זה לא הסיח אותם ממנו ומרצונו. וע\"כ אמר, כי פשעי אני אדע וחטאתי נגדי תמיד."],[10,"ד\"א כי פשעי אני אדע וגו':","שאמר, כל המדרגות שבהם תלוים עונות בני אדם אני אדע, כלומר שכבר תקן אותם. וחטאתי נגדי תמיד. זו מיעוט הירח, שלא תקן. כי לא יצאה מפגמה עד שבא שלמה, ואז האירה בשלמות במילואה בלי פגם. ואז נתבשם העולם וישבו ישראל לבטח. שכתוב, וישב יהודה וישראל וגו' ועם כל זה וחטאתי נגדי תמיד, כלומר שגם בימי שלמה לא נתקן מיעוט הירח בשלמות, כי בהמ\"ק חזר ונחרב. והלבנה שהיא הנוקבא חזרה למיעוטה. \u0003ולא אתפסק מעלמא וכו'\u0004 ולא יפסוק הפגם מהעולם עד שיבא מלך המשיח, לעתיד לבא כמ\"ש ואת רוח הטומאה אעביר מן הארץ."],[11,"הוא היה גבור ציד וגו':","בוא וראה, הוא היה איש גבור, ולבושים של אדם הראשון היה לובש, והיה יודע לצוד בהם ציד של הבריות. כי כל הבריות נכנעו אליו בסבת הלבושים הללו, והיינו הלבושים דכתנות עור, שהכ' אומר ויעש ה' אלקים לאדם ולאשתו כתנות עור וילבישם. וה\"ס מוחין עליונים, ונמרוד היה לו בחינת חיצוניות של אלו הלבושים דאדה\"ר. ובכחם כבש והכניע את כל העולם תחתיו. כמ\"ש להלן."],[12,"אמר רבי אלעזר וכו':","אר\"א נמרוד היה מפתה את הבריות ללכת אחר עבדות של עבודה זרה. והיה שולט בכח אלו הלבושים ונצח את בני העולם. והיה אומר על עצמו שהוא המושל בהעולם דהיינו שעשה עצמו אלהים, ובני אדם היו עובדים אליו. ולמה נקרא שמו נמרוד, משום שמרד במלך העליון של מעלה, שמרד בעליונים, דהיינו בקדושה העליונה ומרד בתחתונים. דהיינו בבני עולם הזה."]],[[0,"","כְּמוֹ זֶה בְּנֵי אַהֲרֹן שֶׁשָּׁנִינוּ שֶׁהָיוּ שְׁתוּיֵי יַיִן, וְכִי מִי נָתַן לָהֶם יַיִן בְּאוֹתוֹ מָקוֹם לִשְׁתּוֹת? אִם תַּעֲלֶה בְדַעְתְּךְ שֶׁהָיוּ חֲצוּפִים שֶׁשָּׁתוּ יַיִן - לֹא כָּךְ! אֶלָּא וַדַּאי מֵאוֹתוֹ יַיִן שָׁתוּ, שֶׁכָּתוּב (ויקרא י) וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה. כָּתוּב כָּאן אֵשׁ זָרָה, וְכָתוּב שָׁם (משלי ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה. וְהַכֹּל דָּבָר אֶחָד."],[1,"","וְכָךָ כְּמוֹ זֶה וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל. וְעַל זֶה הִתְעוֹרֵר חָם אֲבִי כְנַעַן, כְּמוֹ שֶׁנִּתְבָּאֵר, וְנִתַּן מָקוֹם לִכְנַעַן לִשְׁלֹט. וּמַה שֶּׁהָיָה זֶה צַדִּיק בְּסוֹד הַבְּרִית, סֵרַס אוֹתוֹ. וְשָׁנִינוּ, שֶׁהֶעֱבִיר מִמֶּנּוּ אוֹתוֹ קִיּוּם."],[2,"","וְלָכֵן אָמַר אָרוּר, שֶׁהֲרֵי הַקְּלָלוֹת הִתְעוֹרְרוּ בַּתְּחִלָּה עַל יָדוֹ בָּעוֹלָם. (ועל זה ויאמר ארור כנען, שהרי קללות יבאו על העולם כבתחלה). עֶבֶד עֲבָדִים יִהְיֶה, כְּמוֹ שֶׁנֶּאֱמַר אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹ'. הַכֹּל יְתֻקַּן לֶעָתִיד לָבֹא, וְהוּא לֹא יְתֻקַּן. וְכֻלָּם יֵצְאוּ לְחֵרוּת, וְהוּא לֹא יֵצֵא. וְסוֹד הוּא לְאוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי וּשְׁבִילֵי הַתּוֹרָה."],[3,"","פָּתַח וְאָמַר, (תהלים נא) כִּי פְשָׁעַי אֲנִי אֵדָע וְחַטָּאתִי נֶגְדִּי תָמִיד. כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִשָּׁמֵר מֵחֲטָאֵיהֶם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אַחַר שֶׁחָטָא אָדָם, רָשׁוּם חֶטְאוֹ לְמַעְלָה וְלֹא נִמְחָק, רַק בְּכֹחַ שֶׁל תְּשׁוּבָה רַבָּה, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה ב) כִּי אִם תְּכַבְּסִי בַּנֶּתֶר וְתַרְבִּי לָךְ בֹּרִית נִכְתָּם עֲונֵךְ לְפָנַי."],[4,"","בֹּא רְאֵה, כֵּיוָן שֶׁחָטָא אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא פַּעַם אַחַת - עוֹשֶׂה רֹשֶׁם. וּכְשֶׁחָטָא בּוֹ פַּעַם שְׁנִיָּה - מִתְחַזֵּק יוֹתֵר אוֹתוֹ הָרֹשֶׁם. חָטָא בּוֹ פַּעַם שְׁלִישִׁית - מִתְפַּשֵּׁט אוֹתוֹ הַכֶּתֶם מִצַּד זֶה לְצַד זֶה, וְאָז כָּתוּב נִכְתָּם עֲוֹנֵךְ לְפָנַי."],[5,"","בֹּא רְאֵה, כֵּיוָן שֶׁחָטָא דָוִד הַמֶּלֶךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעֵסֶק שֶׁל בַּת שֶׁבַע, חָשַׁב שֶׁאוֹתוֹ חֵטְא נִרְשָׁם עָלָיו לְעוֹלָמִים. מַה כָּתוּב? (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. הָעֳבַר אוֹתוֹ הָרֹשֶׁם מִלְּפָנָיו."],[6,"","אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי שָׁנִינוּ שֶׁבַּת שֶׁבַע הָיְתָה שֶׁל דָּוִד הַמֶּלֶךְ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, לָמָּה נָתַן אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוּרִיָּה הַחִתִּי מִקֹּדֶם לָזֶה?"],[7,"","אָמַר לוֹ, כָּךְ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - אַף עַל גַּב שֶׁמְּזֻמֶּנֶת לְבֶן אָדָם לִהְיוֹת שֶׁלּוֹ, מַקְדִּים אַחֵר וְנוֹשֵׂא אוֹתָהּ עַד שֶׁמַּגִּיעַ זְמַנּוֹ שֶׁל זֶה. כֵּיוָן שֶׁהִגִּיעַ זְמַנּוֹ, נִדְחֶה זֶה שֶׁנָּשָׂא אוֹתָהּ מִלִּפְנֵי הָאַחֵר הַזֶּה שֶׁבָּא אַחַר כָּךְ וּמִסְתַּלֵּק מֵהָעוֹלָם, וְקָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מֵהָעוֹלָם כְּשֶׁעֲדַיִן לֹא הִגִּיעַ זְמַנּוֹ מִלִּפְנֵי הָאַחֵר הַזֶּה."],[8,"","וְסוֹד שֶׁבַּת שֶׁבַע שֶׁנִּתְּנָה לְאוּרִיָּה הַחִתִּי (כפי שאמרנו) בַּתְּחִלָּה, צֵא וְדַיֵּק וְתִמְצָא לָמָּה נִתְּנָה הָאָרֶץ הַקְּדוֹשָׁה לִכְנַעַן בְּטֶרֶם שֶׁבָּאוּ יִשְׂרָאֵל, וְתִמְצָא דָבָר זֶה. וְהַכֹּל סוֹד אֶחָד הוּא וְדָבָר אֶחָד."],[9,"","בֹּא רְאֵה, דָּוִד, אַף עַל גַּב שֶׁהוֹדָה עַל חֶטְאוֹ וְשָׁב בִּתְשׁוּבָה, לֹא הֵסִיר מִלִּבּוֹ וּרְצוֹנוֹ מֵאוֹתָם חֲטָאִים שֶׁחָטָא וּמֵאוֹתוֹ חֵטְא שֶׁל בַּת שֶׁבַע, כִּי פָחַד עֲלֵיהֶם תָּמִיד שֶׁמָּא יִגְרֹם אֶחָד מֵהֶם וִיקַטְרֵג עָלָיו בִּשְׁעַת הַסַּכָּנָה, וְלָכֵן לֹא שָׁכַח אוֹתָם מִמֶּנּוּ וּמֵרְצוֹנוֹ."],[10,"","דָּבָר אַחֵר, כִּי פְשָׁעַי אֲנִי אֵדָע - כָּל הַדְּרָגוֹת שֶׁתְּלוּיוֹת בָּהֶם חֲטָאֵי בְּנֵי אָדָם אֲנִי אֵדַע. וְחַטָּאתִי נֶגְדִּי תָמִיד - זוֹ פְגִימַת הַלְּבָנָה שֶׁלֹּא יָצְאָה מִטֻּמְאָתָהּ עַד שֶׁבָּא שְׁלֹמֹה וְהֵאִירָה בִשְׁלֵמוּת, וְאָז הִתְבַּסֵּם הָעוֹלָם וְיָשְׁבוּ יִשְׂרָאֵל לָבֶטַח, שֶׁכָּתוּב (מלכים א ה) וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַח אִישׁ תַּחַת גַּפְנוֹ וְתַחַת תְּאֵנָתוֹ. וְעִם כָּל זֶה - וְחַטָּאתִי נֶגְדִּי תָמִיד, וְלֹא נִפְסָק מֵהָעוֹלָם עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ לֶעָתִיד לָבא, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ."],[11,"","הוּא הָיָה גִבֹּר צַיִד לִפְנֵי ה' עַל כֵּן יֵאָמַר כְּנִמְרֹד גִּבּוֹר צַיִד לִפְנֵי ה'. בֹּא רְאֵה, הוּא הָיָה אִישׁ חָזָק. לְבוּשֵׁי אָדָם הָרִאשׁוֹן הָיָה לוֹבֵשׁ, וְיָדַע לָצוּד צִידָה שֶׁל הַבְּרִיּוֹת בָּהֶם."],[12,"","אָמַר רַבִּי אֶלְעָזָר, נִמְרוֹד הָיָה מְפַתֶּה אֶת הַבְּרִיּוֹת לָלֶכֶת אַחַר עֲבוֹדַת הָעֲבוֹדָה זָרָה, וְהָיָה שׁוֹלֵט בְּאוֹתָם לְבוּשִׁים וּמְנַצֵּחַ אֶת בְּנֵי הָעוֹלָם, וְהָיָה אוֹמֵר שֶׁהוּא שַׁלִּיט שֶׁל הָעוֹלָם, וְעוֹבְדִים אוֹתוֹ בְּנֵי אָדָם. וְלָמָּה נִקְרָא שְׁמוֹ נִמְרוֹד? שֶׁמָּרַד בַּמֶּלֶךְ הָעֶלְיוֹן שֶׁלְּמַעְלָה, שֶׁמָּרַד בָּעֶלְיוֹנִים וּמָרַד בַּתַּחְתּוֹנִים."]]],[["בְּאִנוּן לְבוּשִׁין שַׁלִּיט עַל כָּל (ד\"א שאר) בְּנִי עָלְמָא וּמָלַךְ בְּהוּ וּמָרַד בְּמָארֵיהּ וְאָמַר דְּאִיהוּ שַׁלִּיטָא דְעָלְמָא וְהֲוָה מְפַתֵּי לִבְרִיָּיתָא אֲבַתְרֵיהּ עַד דְּמָשַׁךְ בְּנֵי נָשָׁא לְמֵיפַק מִבָּתַר פּוּלְחָנָא דְּמָארֵי עָלְמָא. אָמַר רַבִּי שִׁמְעוֹן בְּאִילֵין לְבוּשִׁין יָדְעֵי בְּהוּ חַבְרַיָיא רָזָא עִלָּאָה:","מַתְנִיתִין. וַיְהִי כָל הָאָרֶץ שָׂפָה אַחַת וּדְבָרִים אֲחָדִים. רַבִּי שִׁמְעוֹן פָּתַח (מלכים א ו׳:ז׳) וְהַבַּיִת בְּהִבָּנוֹתוֹ אֶבֶן שְׁלֵמָה מַסַּע נִבְנָה וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלֵי בַּרְזֶל לא נִשְׁמַע בַּבַּיִת בְּהִבָּנוֹתוֹ. (האי קרא אית לאסתכלא ביה), וְהַבַּיִת בְּהִבָּנוֹתוֹ. וְכִי לָא הֲוָה בָּנִי לֵיהּ שְׁלמֹה וְכֻלְהוּ אוּמָנִין דְּהֲווּ תַּמָּן, מַהוּ בְּהִבָּנוֹתוֹ.","אֶלָּא כָּךְ הוּא כְּמָה דִכְתִיב, (שמות כ״ה:ל״א) מִקְשָׁה תֵּיעָשֶׂה הַמְנוֹרָה. אִם הִיא מִקְשָׁה מַהוּ תֵּיעָשֶׂה. אֶלָּא וַדַּאי כֹּלָּא בְּאָת וְנִיסָּא אִתְעֲבִיד אִיהוּ מִגַּרְמֵיהּ. כֵּיוָן דְּשָׁרָאן לְמֶעְבַּד עֲבִידְתָּא אוֹלִיף לְאוּמָנִין לְמֶעְבַּד בָּהּ מַה דְּלֹא הֲווּ יָדְעִין מִקַּדְמַת דְּנָא.","מַאי טַעְמָא בְּגִין דְּבִרְכְתָא דְּקוּדְשָׁא בְּרִיךְ הוּא שְׁרָא עַל יְדַיְיהוּ, וְעַל דָּא כְּתִיב בְּהִבָּנוֹתוֹ אִיהוּ אִתְבְּנִי מִגַּרְמֵיהּ, דְּהוּא אוּלְפָא אוּלְפַן לְאוּמָנִין הֵיאךְ שָׁרָאן לְמֶעְבַּד, וְלָא אִסְתַּלַּק מֵעֵינַיְיהוּ רְשִׁימוּ דְּהַהוּא עֲבִידְתָּא מַמָּשׁ וּמִסְתַּכְּלָאן בֵּיהּ וְעָבְדֵי עַד דְּאִתְבְּנֵי כָּל בֵּיתָא.","אֶבֶן שְׁלֵמָה מַסַּע נִבְנֶה. שְׁלֵמָה כְּתִיב חָסֵר יו\"ד אֶבֶן שְׁלֵמָה וַדַּאי. מַסַּע דְּאִתְנְטִיל וְאַתְיָיא וְשָׁרְיָיא עֲלַיְיהוּ וְאִתְעֲבִיד עֲבִידְתָּא (מסע דאתנטיל ועביד עבידתא), מַסַּע דְּאַנְטִיל יָדָן לְמֶעְבַּד דְּלָא מִדַּעְתַּיְיהוּ. כְּתִיב הָכָא מַסַּע וּכְתִיב הָתָם (במדבר י׳:ב׳) וּלְמַסַּע אֶת הַמַּחֲנוֹת.","וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלֵי בַּרְזֶל לֹא נִשְׁמַע. בְּגִין דְּשָׁמִיר בָּזַע כֹּלָּא וְלָא אִשְׁתְּמַע מִלָּה, דְּלָא אִצְטְרִיכוּ לִשְׁאָר מָאנִין לְמֶעְבַּד. וְכֹלָּא בְּאָת וְנִיסָּא הֲוָה.","אָמַר רַבִּי שִׁמְעוֹן כַּמָּה חֲבִיבִין אִנוּן מִלֵּי דְאוֹרַיְיתָא. זַכָּאָה חוּלָקֵיהּ מַאן דְּאִתְעַסַּק בְּהוּ וְיָדַע לְמֵיהַךְ (ביה) בְּאֹרַח קְשׁוֹט. וְהַבַּיִת בְּהִבָּנוֹתוֹ. כַּד סָלְקָא בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד יְקָרָא לִיקָרֵיהּ, סָלְקָא מִגּוֹ מַחֲשָׁבָה רְעוּתָא לְאִתְפַּשְׁטָא, וְאִתְפַּשְׁטַת מֵאֲתַר דְּאִיהִי מַחֲשָׁבָה סְתִימָא דְּלָא אִתְיְידַע.","עַד דְּאִתְפַּשְׁטַת וְשַׁרְיָיא לְבֵי גָרוֹן אֲתַר דְּאִיהוּ נְבִיעַ תָּדִיר בְּרָזָא דְּאִיהוּ רוּחַ חַיִּים. וּכְדֵין כַּד אִתְפַּשְׁטַת הַהִיא מַחֲשָׁבָה וְשָׁרְיָא בְּאֲתַר דָּא, אִקְרֵי הַהִיא מַחֲשָׁבָה אֱלֹהִים חַיִּים. דִּכְתִיב, (ירמיהו י׳:י׳) הוּא אֱלהִים חַיִּים.","עוֹד בָּעָא לְאִתְפַּשְׁטָא וּלְאִתְגַּלְּיָא מִתַּמָּן נָפְקוּ אֶשָׁ\"א וְרוּחָ\"א וּמַיָ\"א כְּלִילָן כְּחֲדָא, וְנָפַק יַעֲקֹב גְּבַר שְׁלִים וְאִיהוּ קוֹל חַד דְּנָפִיק וְאִשְׁתְּמַע. מֵהָכָא מַחֲשָׁבָה דְּהֲוָה סְתִימָא בַּחֲשַׁאי אִשְׁתְּמַע לְאִתְגַּלְיָא.","עוֹד אִתְפַּשְׁטַת הַאי מַחֲשָׁבָה לְאִתְגַּלְיָא. וּבָטַשׁ הַאי קוֹל וְאַקִּישׁ בְּשִׂפְוָון, וּכְדֵין נַפְקָא דִּבּוּר, דְּאַשְׁלִים כֹּלָּא, וְגָלֵי כֹּלָּא. אִשְׁתְּמַע דְּכֹלָּא אִיהוּ הַהִיא מַחֲשָׁבָה סְתִימָא דְּהֲוַת לְגוֹ וְכֹלָּא חַד.","כֵּיוָן דְּמָטָא אִתְפַּשְׁטוּתָא דָא וְאִתְעֲבִיד דִּבּוּר בִּתְקִיפָא דְּהַהוּא קָלָא, כְּדֵין וְהַבַּיִת בְּהִבָּנוֹתוֹ. כַּאֲשֶׁר נִבְנָה לא כְּתִיב אֶלָּא בְּהִבָּנוֹתוֹ בְּכָל זִמְנָא וְזִמְנָא. אֶבֶן שְׁלֵמָה כְּמָה דְּאִתְּמָר. וּכְתִיב, (שיר השירים ג׳:י״א) בָּעֲטָרָה שֶׁעִטְרָה לוֹ אִמּוֹ.","מַסַּע דְּנַפְקָא מִלְּגוֹ וְשַׁרְיָא וְנָטִיל לְבַר, נַפְקָא מִלְּעֵילָא וְשַׁרְיָא וְנָטִיל לְתַתָּא. וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלֵי בַּרְזֶל. אִלֵּין שְׁאָר דַּרְגִּין תַּתָּאִין דְּכֻלְהוּ תַּלְיָין בֵּיהּ וְלָא אִשְׁתְּמָעוּ וְלָא אִתְקַבְּלָן לְגוֹ כַּד אִיהִי סַלְקָא לְאִתְאַחֲדָא לְעֵילָא וּלְיָנְקָא מִתַּמָּן. וְדָא הוּא בְּהִבָּנוֹתוֹ.","וּכְדֵין כַּד אִיהִי יָנְקָא, כֻּלְהוּ קָיְימֵי בְּחֶדְוָותָא וְיָנְקִין וְאִתְמַלְיָין בִּרְכָאן. וּכְדֵין קָיְימִין עָלְמִין כֻּלְהוּ בְּרָזָא חָדָא בְּיִחוּדָא חַד, וְלָא הֲוֵי בְּהוּ בְּכֻלְהוּ עָלְמִין פִּירוּדָא. לְבָתַר דְּנָטְלֵי חוּלַקְהוֹן כָּל חַד וְחַד כֻּלְהוּ מִתְפַּשְׁטָן וּמִתְפָּרְשָׁן לְסִטְרַיְיהוּ לְמָה דְאִתְמַנָּן."],[[0,"באינון לבושין וכו':","בכח אלו הלבושים היה שולט על כל בני העולם, ומלך עליהם, ומרד בהם ומרד ברבונו, ואמר שהוא השליט של העולם, דהיינו אלהים, והיה מפתה את הבריות אחריו עד שמשך את בני האדם לצאת מן העבדות של רבון העולם. אמר רבי שמעון, באלו הלבושים ידעו החברים בהם סוד עליון."],[1,"ויהי כל הארץ שפה אחת ודברים אחדים:","רבי שמעון פתח. והבית בהבנותו אבן שלמה מסע וגו'. ומקשה, והבית בהבנותו, שמשמע שנבנה מאליו, וכי שלמה וכל האומנים שהיו שם לא בנו אותו, מהו בהבנותו."],[2,"אלא כך וכו':","אלא כך הוא כמ\"ש מקשה תעשה המנורה. אם הוא מקשה, שפירושו שהאומנים היו מכים על העשת בקורנס, א\"כ מהו תעשה, שמשמע שהיה נעשה מאליו. אלא ודאי הכל נעשה בבית המקדש מאליו, באות ונס. כיון שהאומנים התחילו לעשות, המלאכה למדה את האומנים לעשותה, מה שלא היו יודעים לעשות מקודם שהתחילו אותה."],[3,"מ\"ט בגין וכו':","מהו הטעם. משום שברכת הקב\"ה היתה שורה על ידיהם. ועל כן כתוב \u0003בהבנותו,\u0004 שהוא נבנה מאליו, כי הוא למד את האומנים הלמוד, איך מתחילים לעשותו, והרשימה של אותה המלאכה לא היתה מסתלקת מעיניהם ממש, והיו מסתכלים בהרשימה ועושים, עד שנבנה כל הבית."],[4,"אבן שלמה מסע נבנה:","שלמה כתוב חסר יוד, אבן שלמה ודאי. כלומר, כיון שכתוב, חסר יוד, אפשר לקראו שלמה ולא שלימה. דהיינו הנוקבא הנקראת, אבן של המלך שהשלום שלו. (כמ\"ש לעיל בראשית א' דף ק\"פ ד\"ה פתח ע\"ש)."],[4,"מסע, דאתנטיל ואתיא וכו':","מסע, פירושו שאבן שלמה שהיא הנוקבא, נסעה מלמעלה ובאה ושרתה עליהם, והמלאכה נעשית. פירוש אחר, \u0003מסע,\u0004 שהסיעה את הידים לעשות שלא מדעתן. כתוב כאן מסע, ושם כתוב ולמסע את המחנות, מה שם פירושו פועל יוצא אף כאן פירושו פועל יוצא."],[5,"ומקבות והגרזן וגו' לא נשמע:","משום שתולעת הנקרא שמיר בקע הכל, ולא נשמע דבר כי לא נצרכו לעבוד בכלים אחרים. והכל באות ונס היה. פירוש. שלא היו צריכים למקבות וגרזן לבקוע האבנים, כי היה להם תולעת הנקרא \u0003שמיר,\u0004 ונתנו אותה על האבנים והיו מתבקעות תחתיו. (כמ\"ש במס' סוטה דף מח:) כותב עליהם בדיו, ומראה להן \u0003שמיר\u0004 מבחוץ, והן נבקעות מאליהן."],[5,"","פנימיות הדברים. המדרגות נק' אבנים, והדינים הבוקעים את המדרגות באמצען, לכו\"ח ולבינה ותו\"מ, נקראים בשם \u0003שמיר.\u0004 ונקרא כן, מטעם היותו \u0003שמור\u0004 מפני אחיזת החיצונים כי ה\"ס מלכות הממותקת לגמרי בהבינה, ונעשית כמו הבינה, ואין אחיזה להם בהבינה. וסוד כלי ברזל ה\"ס הדינים של עצמות המלכות המצומצמת שהיא סוד נקודה דמדת הדין, ואם קולה נשמע תכף מסתלקים המוחין מהנוקבא. (כנ\"ל דף צ\"ג ד\"ה ביאור). ולפי שבקיעת האבנים שה\"ס יציאת הקטנות של המדרגות שלה, נעשה על ידי השמיר, שה\"ס קטנות דבינה, נעשה הבנין שלהן, שה\"ס המשכת המוחין דגדלות, ג\"כ מהבינה. ואז יכולה הנוקבא לעלות ולהלביש את בינה עלאה, ואז נקראת הנוקבא \u0003בית המקדש,\u0004 כי קבלה מוחין מאו\"א הנקראים קדש. אבל אם לא היה להם סוד ה \u0003שמיר\u0004 והיה נשמע קול כלי ברזל, שה\"ס הנקודה דמדת הדין, לא היתה מקבלת הנוקבא מוחין דקדש לעולם, ובית המקדש לא היה יכול להבנות."],[6,"אמר רבי שמעון וכו':","כמה חביבים הם דברי התורה. אשרי חלקו מי שעוסק בהם, ויודע ללכת בדרך אמת, \u0003והבית בהבנותו,\u0004 פירושו, כי כשעלה ברצונו של הקב\"ה לעשות יקר ליקרו, עלה רצון מתוך המחשבה להתפשט, דהיינו שהבינה המכונה רצון, יצאה מהראש דא\"א הנקרא מחשבה, ונתפשטה הבינה. מהמקום שהוא מחשבה סתומה. דהיינו ממקום חכמה סתימאה דא\"א, שהיא בלתי נודעה, כי חכמה דא\"א נסתמה, ואינה נודעת במדרגות האצילות עד גמר התקון. ובינה זו שיצאה מראש א\"א משמשת להשפיע חכמה במקום חכמה סתימאה דא\"א."],[7,"עד דאתפשטת וכו':","עד שנתפשטה הבינה ושרתה בתוך הגרון דא\"א, מקום שהוא נובע תמיד, בסוד שהוא רוח חיים. רוח פירושו קומת ו\"ק, ומתוך שהבינה יצאה מראש דא\"א, לגרון, היא נעשתה לו\"ק חסר ג\"ר, וע\"כ אומר, שהוא רוח חיים."],[7,"וכדין, כד אתפשטת וכו':","ואחר כך, כאשר נתפשטה מחשבה ההיא, חכמה דא\"א, ושרתה במקום זה, בהבינה, דהיינו שהבינה חזרה וקבלה ג\"ר מהחכמה דא\"א, ונעשית הבינה שוב לבחינת מחשבה, נקרא אז מחשבה הזו בשם אלקים חיים. שכתוב, הוא אלקים חיים. פירוש. כי מטרם שהבינה השיגה ג\"ר היתה רק באותיות מ\"י של אלקים, כי אותיות אל\"ה נפלו ממנה לזו\"ן, וכשחזרה לראש א\"א עם אתוון אל\"ה, נעשה בה שוב השם אלקים, אלא שהיה עוד סתום ואינו מאיר מטעם חוסר חסדים. וכשקנתה ג' הקוין, נעשה בה השם, \u0003אלקים חיים,\u0004 כנ\"ל בהקדמת הזהר דף ל' אות כ' ע\"ש."],[8,"עוד בעא לאתפשטא וכו':","המאציל רצה עוד להתפשט ולהתגלות משם, מהבינה, יצאו מהבינה אש רוח ומים כלולים יחד, שה\"ס ג' קוין, ויצא יעקב איש תם. שהוא ז\"א, והוא קול אחד שיצא ונשמע. מכאן נשמע, שהמחשבה שהיתה סתומה בחשאי, דהיינו הבינה, נשמעת להתגלות על ידי יעקב שהוא ז\"א. פירוש. כי אומר לעיל, (בראשית ב' דף ק\"מ אות ר\"מ) \u0003תרין אינון דאשתמעו\u0004 וכו' \u0003קול דיעקב ודבור דאתאחיד בהדיה,\u0004 וזהו שאומר כאן, \u0003ואיהו קול חד דנפק ואשתמע,\u0004 דהיינו קול אחד \u0003מתרין דאשתמעו\u0004 הנ\"ל. והבינה נקראת \u0003קול גדול דהוא דק ונפיק בחשאי\u0004 כמ\"ש שם בזהר אות רל\"ט. וע\"ש בהסולם, ואין להכפיל דברים."],[9,"עוד אתפשטת וכו':","עוד נתפשטה מחשבה הזו להתגלות, ודפק קול הזה והכה בשפתים, ואז יצא הדבור שהשלים הכל וגילה הכל. נשמע מכאן, שהכל הוא אותה מחשבה סתומה, שהיתה בפנימיות, והכל אחד."],[9,"","ביאור הדברים. נודע שה' מיני קומות יש, שהן נקראות נרנח\"י, היוצאות על ידי זווג דהכאה בה' בחינות שבמסך, שהם שורש וד' בחינות חו\"ב תו\"מ, אשר על בחינת השורש יוצאת קומת נפש. ועל בחי\"א יוצאת קומת רוח. ועל בחי\"ב נשמה. ועל בחי\"ג חיה. ועל בחי\"ד יחידה. (כמ\"ש בפתיחה לחכמת הקבלה דף ז' אות כ\"ז וכ\"ח עש\"ה) וכל פרצופי אצילות מקבלים, מפה דא\"א, כל אחד שיעור קומה השייך לו, והוא מודד להם על פי ה' בחינות מסך, המכונות ה' מוצאות הפה חיך גרון לשון שינים ושפתים, ולפיכך בעת שהבינה יצאה מראש דא\"א, שנתמעטה ואינה יכולה לקבל רק נפש רוח, שהם ו\"ק בלי ראש, הרי אז משפיע לה א\"א מבחינת זווג דהכאה על המסכים \u0003דחיך וגרון,\u0004 ומודד לה משם קומת רוח, הנק' רוח חיים."],[9,"","וז\"ש \u0003דאתפשטת ושריא לבי גרון וכו' ברזא דרוח חיים.\u0004 שהיא בחינת הקטנות דבינה. ומקומת רוח ואילך הם מוחין דגדלות הנקראים ג\"ר. וע\"כ יש ג' בחינות ג\"ר: נשמה, חיה, יחידה. המכונים \u0003מחשבה, קול, דיבור.\u0004 היוצאות על המסכים: דבחי\"ב ובחי\"ג, ובחי\"ד. אשר קומת בינה, הנקראת \u0003מחשבה\u0004 יוצאת על מסך דבחי\"ב שבפה, המכונה \u0003לשון.\u0004"],[9,"","וז\"ש \u0003כד אתפשטת ההיא מחשבה וכו' אקרי ההיא מחשבה אלקים חיים.\u0004 כי אחר שהשיגה מפה דא\"א קומת נשמה הנקרא מחשבה. נקראת הבינה בשם \u0003אלקים חיים.\u0004 ונבחנת קומה זו שהיא \u0003לא אשתמע,\u0004 אלא שהיא \u0003בחשאי,\u0004 וקולה לא ישמע. והוא מטעם כי הארת החכמה אינה מתגלה בקומה הזו, וע\"כ אע\"פ שמספקת להיות ג\"ר ובחינת ראש להבינה עצמה, כי אינה צריכה להארת חכמה. עכ\"ז אין הזו\"ן יכולים לקבל ממנה יותר מבחינת ו\"ק בלי ראש, משום שז\"א צריך להארת חכמה ביחוד. (כנ\"ל דף פ\"ב ד\"ה פירוש) וז\"ס \u0003וקולה\u0004 שהוא ז\"א הנק' קול, \u0003לא ישמע,\u0004 אינו נגלה לחוץ, כי \u0003הקול\u0004 נשאר בו\"ק בלי ראש. וע\"כ נבחנת הארת ג\"ר זו, שהיא בחשאי."],[9,"","וקומת חיה, המכונה \u0003קול\u0004 יוצאת על מסך דבהי\"ג שבפה, המכונה \u0003שינים.\u0004 וז\"ש \u0003עוד בעא לאתפשטא ולאתגליא\u0004 וכו' \u0003ואיהו קול חד דנפיק ואשתמע,\u0004 כי עתה בקומה זו יש הארת החכמה, וע\"כ מקבל ממנה גם ז\"א הנק' קול ונעשה לו לבחי' ג\"ר, והוא נשמע לחוץ, כלומר שמוליד נשמות לתחתונים."],[9,"","וז\"ש \u0003מחשבה דהוה סתימא בחשאי\u0004 דהיינו קומת נשמה, שלא האירה בחי' ג\"ר לז\"א, בסו\"ה וקולה לא ישמע, עתה \u0003אשתמע לאתגליא,\u0004 כי עתה, קולה ישמע."],[9,"","וקומת יחידה המכונה \u0003דיבור,\u0004 יוצאת על מסך דבחי\"ד שבפה, הנקרא \u0003שפתים.\u0004 וז\"ש \u0003עוד אתפשטת האי מחשבה לאתגליא, וכו' ואקיש בשפוון, וכדין נפקא דיבור דאשלים כלא,\u0004 כי אחר שנעשה זווג דהכאה בשפתים, \u0003ואקיש בשפוון,\u0004 אז יצאה קומת יחידה הנקרא דיבור, המשלים הכל, ומגלה הכל. דהיינו שבה נשלמים כל ה' אורות נרנח\"י, ובה שלימות הגילוי של הארת החכמה כנודע."],[9,"","וז\"ש \u0003אשתמע דכלא איהו ההיא מחשבה סתימא דהות לגו,\u0004 נשמע מכאן, שכל נרנח\"י הללו, הם של המחשבה סתימא, שהיא קומת הבינה, שהיתה בפנימיות, ולא יכלה להאיר לתחתונים, שהם זו\"ן, ועתה נתפשטה אותה הבינה משם ומאירה לזו\"ן. ב' הקומות חיה יחידה, והם נעשו על ידה עתה \u0003לקול ודיבור.\u0004 כי אין זו\"ן יכולים לקבל מפה דא\"א. אלא הבינה מקבלת הקומות מא\"א ומשפעת אותם לזו\"ן ונעשו לקול ודבור. באופן, שהם התפשטות המחשבה בלבד."],[10,"כיון דמטא אתפשטותא וכו':","כיון שהגיע התפשטות הזו מהבינה, ונעשה \u0003דבור\u0004 דהיינו שנמשך להנוקבא, בתקפו של \u0003קול\u0004 ההוא, שהוא ז\"א המקבל מבינה ומשפיע להנוקבא. אז כתוב והבית בהבנותו, דהיינו שנבנה מאליו ע\"י אות ונס, כי המוחין שנשלמו בבינה נשפעו אל \u0003הבית\u0004 ע\"י ז\"א, בלי שום תשומת יד מהתחתונים הצריכים בהכרח לכלי ברזל, שה\"ס הנקודה דמדה\"ד. כנ\"ל. \u0003כאשר נבנה לא כתיב, אלא בהבנותו,\u0004 מקשה, אם כונת הכתוב להורות שנבנה מאליו, היה מספיק לומר והבית כאשר נבנה, ולמה לו לומר בהבנותו. ומשיב, כי זה מלמדינו שהוא כן \u0003בכל זמנא וזמנא.\u0004 כלומר, שהמוחין הללו היו מאירים אז בכל זמן וזמן, דהיינו בזווג דלא פסיק. והוא מטעם שזו\"ן כשיש להם מוחין הללו הנקראים \u0003קול ודבור,\u0004 אז הם עולים ומלבישים לאו\"א עלאין, שהם בזווג דלא פסיק לעלמין, כנודע, וע\"כ נעשו גם הזו\"ן כמוהם. כי התחתון העולה לעליון נעשה כמוהו. \u0003אבן שלמה כמה דאתמר\u0004 וכו': אבן שלמה פירושו. כמו שאמרנו לעיל, (באות שכ\"ו) אבן של שלמה, וכתוב בעטרה שעטרה לו אמו, דהיינו בינה הנקראת אמא. וכאשר הנוקבא מקבלת ג\"כ עטרות הללו נקראת אבן של שלמה."],[11,"מסע, דנפקא מלגו","וכו': מסע, פירושו שהארת המוחין יצאה מפנימיות, מהבינה, כלומר שנגמרה שם כל המלאכה עד סופה, ונסעה משם ושרתה בחוץ, בז\"א. באופן שיצאה מלמעלה מבינה, ונסעה ושרתה למטה, בהנוקבא. ומקבות והגרזן כל כלי ברזל, הם שאר מדרגות התחתונות שכולן תלוים בה. בהנוקבא, ועם כל זה, לא נשמעו ולא נתקבלו בפנימית בעת שהנוקבא עלתה להתאחד למעלה. להלביש לאו\"א, ולינק משם. פירוש. המקבות וכל כלי ברזל הם נמשכים מנקודה דמדת הדין מצמצום א' (כנ\"ל דף קי\"ד ד\"ה פנימיות) וכל המוחין שהנוקבא משגת הוא מטעם הגניזו דנקודה דמדה\"ד הזו, ורק נקודה דמדת הרחמים גלויה בה, וע\"כ יכלה לעלות לפנימיות דהיינו לאו\"א. ואם היו נשמעים אלו המדרגות דמדה\"ד הנמשכים ממנה הנק' כלי ברזל, תכף היתה אובדת המוחין כמ\"ש שם. אמנם שמשו בשמיר, ולא נצטרכו לעורר כלים ההם, וע\"כ לא נשמע מציאותם, כנ\"ל. \u0003ודא הוא בהבנותו\u0004 וזהו שהכתוב אומר בהבנותו. דהיינו שנבנה מאליו בלי תשומת יד מהתחתונים. כנ\"ל."],[12,"וכדין כד איהי ינקא וכו':","ואז כאשר הנוקבא יונקת מאו\"א, נמצאים כל העולמות בשמחה, ויונקים מהנוקבא, ומתמלאים עם ברכות. ואז נמצאים העולמות כולם בסוד אחד, ביחוד אחד. ואין בהם בכל העולמות שום פירוד. פירוש, כיון שכלי ברזל לא נשמע, שה\"ס נקודה דמדה\"ד, ע\"כ נמצאים כל העולמות בסוד אחד, דהיינו בסוד הבינה שה\"ס הנקודה דמדת הרחמים, ואז אין בחי' \u0003פירוד\u0004 בכל העולמות, מפני שכל \u0003פירוד\u0004 היא רק מהנקודה דמדה\"ד. ולאחר שכל העולמות לקחו כל אחד ואחד חלקם מהנוקבא, כולם מתפשטים וחוזרים לבחינתם למה שנתמנו."]],[[0,"","בְּאוֹתָם לְבוּשִׁים הוּא שָׁלַט עַל כָּל (שאר) בְּנֵי הָעוֹלָם וּמָלַךְ בָּהֶם, וּמָרַד בְּרִבּוֹנוֹ וְאָמַר שֶׁהוּא הַשַּׁלִּיט שֶׁל הָעוֹלָם, וְהָיָה מְפַתֶּה אֶת הַבְּרִיּוֹת אַחֲרָיו, עַד שֶׁמָּשַׁךְ בְּנֵי אָדָם לָצֵאת מֵאַחַר עֲבוֹדַת רִבּוֹן הָעוֹלָם. אָמַר רַבִּי שִׁמְעוֹן, בַּלְּבוּשִׁים הַלָּלוּ יוֹדְעִים בָּהֶם הַחֲבֵרִים סוֹד עֶלְיוֹן."],[1,"","מִשְׁנָה, וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים. רַבִּי שִׁמְעוֹן פָּתַח, (מלכים א ו) וְהַבַּיִת בְּהִבָּנֹתוֹ אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל לֹא נִשְׁמַע בַּבַּיִת בְּהִבָּנֹתוֹ. וְהַבַּיִת בְּהִבָּנֹתוֹ - וְכִי לֹא הָיָה בּוֹנֶה אוֹתוֹ שְׁלֹמֹה וְכָל הָאָמָּנִים שֶׁהָיוּ שָׁם? מַה זֶּה בְּהִבָּנֹתוֹ?"],[2,"","אֶלָּא כָּךְ הוּא, כְּמוֹ שֶׁכָּתוּב (שמות כה) מִקְשָׁה תֵּיעָשֶׂה הַמְּנוֹרָה. אִם הִיא מִקְשָׁה, מַהוּ תֵּיעָשֶׂה? אֶלָּא וַדַּאי הַכֹּל בְּאוֹת וְנֵס נַעֲשָׂה הוּא מֵעַצְמוֹ. כֵּיוָן שֶׁהִתְחִילוּ לַעֲשׂוֹת הַמַּעֲשֶׂה, לִמֵּד אֶת הָאָמָּנִים לַעֲשׂוֹת אוֹתָהּ מַה שֶּׁלֹּא הָיוּ יוֹדְעִים מִקֹּדֶם לָכֵן."],[3,"","מָה הַטַּעַם? מִשּׁוּם שֶׁבִּרְכַּת הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁרְתָה עַל יָדָם, וְעַל כֵּן כָּתוּב בְּהִבָּנֹתוֹ, הוּא נִבְנָה מֵעַצְמוֹ, שֶׁהוּא לִמֵּד אֶת הַלִּמּוּד לָאָמָּנִים אֵיךְ לְהַתְחִיל לַעֲשׂוֹת, וְלֹא הִסְתַּלֵּק מֵעֵינֵיהֶם הָרֹשֶׁם שֶׁל אוֹתוֹ הַמַּעֲשֶׂה מַמָּשׁ, וּמִסְתַּכְּלִים בּוֹ וְעוֹשִׂים, עַד שֶׁנִּבְנָה כָּל הַבַּיִת."],[4,"","אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה, שְׁלֵמָה כָּתוּב חָסֵד יוֹ\"ד, אֶבֶן שְׁלֵמָה וַדַּאי. מַסָּע, שֶׁנָּסְעָה וּבָאָה וְשָׁרְתָה עֲלֵיהֶם וְנֶעֶשְׂתָה הָעֲבוֹדָה (מסע, שנסעה ידם ונעשתה העבודה). מַסָּע, שֶׁהִסִּיעַ יָדָם לַעֲשׂוֹת שֶׁלֹּא מִדַּעְתָּם. כָּתוּב כָּאן מַסָּע, וְכָתוּב שָׁם (במדבר י) וּלְמַסַּע אֶת הַמַּחֲנוֹת."],[5,"","וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל לֹא נִשְׁמַע, מִשּׁוּם שֶׁהַשָּׁמִיר בָּקַע הַכֹּל וְלֹא נִשְׁמַע דָּבָר, שֶׁלֹּא הִצְטָרְכוּ לִשְׁאָר הַכֵּלִים לַעֲשׂוֹת, וְהַכֹּל הָיָה עִם אוֹת וְנֵס."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה חֲבִיבִים הֵם דִּבְרֵי הַתּוֹרָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְעַסֵּק בָּהֶם וְיוֹדֵעַ לָלֶכֶת (בו) בְּדֶרֶךְ אֱמֶת. וְהַבַּיִת בְּהִבָּנֹתוֹ. כַּאֲשֶׁר עָלָה בִּרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת כָּבוֹד לִכְבוֹדוֹ, עָלָה מִתּוֹךְ הַמַּחֲשָׁבָה רָצוֹן לְהִתְפַּשֵּׁט, וְהִתְפַּשֵּׁט מֵהַמָּקוֹם שֶׁל אוֹתָהּ הַמַּחֲשָׁבָה הַנִּסְתֶּרֶת שֶׁאֵינָהּ יְדוּעָה."],[7,"","עֵד שֶׁמִּתְפַּשֶּׁטֶת וְשׁוֹרָה בְּבֵית הַגָּרוֹן, הַמָּקוֹם שֶׁתָּמִיד נוֹבֵעַ בְּסוֹד שֶׁהוּא רוּחַ חַיִּים. וְאָז, כְּשֶׁמִּתְפַּשֶּׁטֶת הַמַּחֲשָׁבָה הַהִיא וְשׁוֹרָה בַּמָּקוֹם הַזֶּה, נִקְרֵאת הַמַּחֲשָׁבָה הַהִיא אֱלֹהִים חַיִּים, שֶׁכָּתוּב (ירמיה י) הוּא אֱלֹהִים חַיִּים."],[8,"","עוֹד רָצָה לְהִתְפַּשֵּׁט וּלְהִתְגַּלּוֹת, מִשָּׁם יָצְאוּ אֵשׁ רוּחַ וּמַיִם כְּלוּלִים יַחַד, וְיוֹצֵא יַעֲקֹב אִישׁ שָׁלֵם, וְהוּא קוֹל אֶחָד שֶׁיּוֹצֵא וְנִשְׁמָע. מִכָּאן הַמַּחֲשָׁבָה שֶׁהָיְתָה נִסְתֶּרֶת בַּחֲשַׁאי נִשְׁמַעַת בְּגִלּוּי."],[9,"","עוֹד מִתְפַּשֶּׁטֶת הַמַּחֲשָׁבָה הַזּוֹ לְהִתְגַּלּוֹת, וּמַכֶּה הַקּוֹל הַזֶּה וּמַקִּישׁ בַּשְּׂפָתַיִם, וְאָז יוֹצֵא הַדִּבּוּר שֶׁמַּשְׁלִים הַכֹּל וּמְגַלֶּה הַכֹּל. נִשְׁמָע שֶׁהַכֹּל הוּא אוֹתָהּ מַחֲשָׁבָה נִסְתֶּרֶת שֶׁהָיְתָה בִּפְנִים, וְהַכֹּל אֶחָד."],[10,"","כֵּיוָן שֶׁמַּגִּיעָה הִתְפַּשְּׁטוּת זוֹ וְנַעֲשֶׂה דִבּוּר בְּכֹחַ אוֹתוֹ הַקּוֹל, אָז - וְהַבַּיִת בְּהִבָּנֹתוֹ. לֹא כָּתוּב כַּאֲשֶׁר נִבְנָה, אֶלָּא בְּהִבָּנֹתוֹ, בְּכָל פַּעַם וּפַעַם. אֶבֶן שְׁלֵמָה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְכָתוּב (שיר ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ."],[11,"","מַסָּע, שֶׁיּוֹצֵא מִבִּפְנִים וְשׁוֹרֶה וְנוֹסֵעַ הַחוּצָה. יוֹצֵא מִלְמַעְלָה וְשׁוֹרֶה וְנוֹסֵעַ לְמַטָּה. וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל - אֵלּוּ שְׁאָר הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁכֻּלָּם תְּלוּיִים בּוֹ, וְלֹא נִשְׁמְעוּ וְלֹא הִתְקַבְּלוּ פְּנִימָה כְּשֶׁהִיא עוֹלָה לְהֵאָחֵז לְמַעְלָה וְלִינוֹק מִשָּׁם, וְזֶהוּ בְּהִבָּנֹתוֹ."],[12,"","וְאָז, כְּשֶׁהִיא יוֹנֶקֶת, כֻּלָּם עוֹמְדִים בְּחֶדְוָה וְיוֹנְקִים וּמִתְמַלְּאִים בִּבְרָכוֹת, וְאָז כָּל הָעוֹלָמוֹת עוֹמְדִים בְּסוֹד אֶחָד, בְּיִחוּד אֶחָד, וְאֵין בָּהֶם בְּכָל הָעוֹלָמוֹת פֵּרוּד. אַחַר שֶׁכָּל אֶחָד וְאֶחָד נוֹטְלִים חֶלְקָם, כֻּלָּם מִתְפַּשְּׁטִים וְנִפְרָדִים לְצִדֵּיהֶם לְמַה שֶּׁהִתְמַנּוּ."]]],[["תָּא חֲזֵי, וַיְהִי כָל הָאָרֶץ שָׂפָה אַחַת וְגו' לְבָתַר מַה כְּתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם. מֵהַהוּא קַדְמָאָה דְעָלְמָא. וַיִּמְצְאוּ בִּקְעָה בְּאֶרֶץ שִׁנְעָר. דְּהָא מִתַּמָּן מִתְפָּרְשָׁן לְכָל אִנוּן סִטְרִין, וְאִיהוּ רִישׁ מַלְכוּ לְאִתְבְּדָרָא.","וְאִי תֵימָא הָא כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד. וַדַּאי הָכִי הוּא דְּכֵיוָן דְּנָטְלֵי מִתַּמָּן הֲוֵי פִּירוּדָא, וְכַד אִנוּן כְּנִישִׁין תַּמָּן לְיַנְקָאָה לָא הֲוִי פִּירוּדָא. וְכַד נָטְלִין הֲוֵי פִּירוּדָא, דִּכְתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם וַיִּמְצְאוּ בִּקְעָה כְּמָה דְּאִתְּמָר.","וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים דְּהָא כְּדֵין עָלְמָא בִּיסוֹדָא וְעִקָּרָא וְשָׁרְשָׁא חָדָא וּמְהֵימְנוּתָא חָדָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם מִקַּדְמָאָה עִקָּרָא דְּעָלְמָא מְהֵימְנוּתָא דְּכֹלָּא. וַיִּמְצְאוּ בִּקְעָה. מְצִיאָה אַשְׁכָּחוּ וְנָפְקוּ בָּהּ מִתְּחוֹת מְהֵימְנוּתָא עִלָּאָה (וימצאו).","תָּא חֲזֵי, נִמְרוֹד מַה כְּתִיב בֵּיהּ וַתְּהִי רֵאשִׁית מַמְלַכְתּוֹ בָּבֶל. דְּהָא מִתַּמָּן נְטַל לְאִתְאַחֲדָא בִּרְשׁוּ אָחֳרָא. וְהָכָא וַיִּמְצְאוּ בִּקְעָה בְּאֶרֶץ שִׁנְעָר מִתַּמָּן נְטָלוּ בְּלִבַּיְיהוּ לְאֲפָקָא מֵרְשׁוּתָא עִלָּאָה לִרְשׁוּ אָחֳרָא:","וַיֹּאמְרוּ הָבָה נִבְנָה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם וְנַעֲשֶׂה לָנוּ שֵׁם. רַבִּי חִיָּיא פָּתַח (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגו'. וְכִי אִית יָם נִגְרָשׁ. אִין, דְּכַד יַמָּא נַפְקָא מִתִּקּוּנֵיהּ וְאָזִיל (בלא הבלא) בְּלָא חַבָּלָא, כְּדֵין נִגְרַשׁ וְאִתְתְּרַךְ מֵאַתְרֵיהּ, כְּמַאן דְּרָוֵי חַמְרָא וְלָא יָתִיב עַל בּוּרְיֵיהּ וְסָלְקָא וְנָחֲתָא. מַאי טַעְמָא בְּגִין כִּי הַשְׁקֵט לא יוּכַל, וְיִגְרְשׁוּ מֵימָיו רֶפֶשׁ וְטִיט. דְּמַפְקוּ מֵימוֹי כָּל הַהוּא טִינָא דְיַמָּא וְכָל טִנּוּפָא לְשִׂפְוָותֵיהּ.","כְּגַוְונָא דָא אִנוּן רְשָׁעִים דְּנַפְקָא מֵאָרְחָא דְּתָקְנָא וְאָזְלֵי כְּרָוִי חַמְרָא בְּלָא תִּקּוּנָא, דְּנָפְקֵי מֵאוֹרַח מֵישָׁר לְאוֹרַח עָקִים. מַאי טַעְמָא, בְּגִין כִּי הַשְׁקֵט לא יוּכָל. דְּהָא עֲקִימוּ דְּאָרְחַיְיהוּ גָּרִים לוֹן לְמֵהַךְ בְּלָא תִקּוּנָא וּבְלָא שְׁכִיכוּ.","וְלָא עוֹד אֶלָּא דְּכָל רוּגְזָא דִידְהוּ בְּשַׁעֲתָא דְּאָמְרִי מִלָּה מִפּוּמַיְיהוּ הַהוּא מִלָּה רֶפֶשׁ וְטִיט כֻּלְהוּ מַפְקֵי טִנּוּפָא וְגִיעוּלָא מִפּוּמַיְיהוּ לְבַר עַד דְּמִסְתָּאֲבֵי וּמְסָאֲבֵי לוֹן."],[[0,"ת\"ח ויהי כל הארץ וגו':","בוא וראה מה שכתוב ויהי כל הארץ שפה אחת ודברים אחדים. פירוש. עם כל המתבאר במאמר הנ\"ל מובן מה שכתוב ויהי כל הארץ שפה אחת וגו'. כי כל האברים הכפולים כמו עינים אזנים שפתים, הם מכח התכללות ב' הנקודות בינה ומלכות זה בזה. וע\"כ יש ב' אברים אחת מבינה ואחת ממלכות. ונתבאר בסו\"ה והבית בהבנותו, שלא היה שום גילוי כאן לנקודה דמדה\"ד. שה\"ס כלי ברזל. אלא הכל נעשה בסוד נקודה דמדה\"ר לבדה. נמצא שסוד זווג דהכאה הנעשה בשפתים בסוד הדיבור, דהיינו \u0003ואקיש בשפוון,\u0004 לא נעשה בבחינת ב' השפתים אלא בבחינת \u0003שפה אחת,\u0004 דהיינו שפה עלאה שה\"ס מנקודה דמדת הרחמים בלבד. וז\"ש כאן הכתוב, \u0003ויהי כל הארץ שפה אחת,\u0004 דהיינו הזווג דהכאה שנעשה בסוד \u0003הדיבור,\u0004 עוד לא כלל ב' השפות שה\"ס ב' הנקודות. אלא שזווג דהכאה היתה בבחינת \u0003שפה אחת\u0004 בלבד. וע\"כ \u0003ודברים אחדים,\u0004 שעוד לא היה פירוד בהעולמות והיה הכל בסוד היחוד והאחדות."],[0,"לבתר מה כתיב וכו':","ואח\"כ מה כתוב ויהי בהנסעם מקדם, שנסעו מקדמונו של עולם, כלומר שהמשיכו הארת קו השמאל ממעלה למטה, אשר קדמונו של עולם אסר להם את זה. וע\"כ \u0003וימצאו בקעה בארץ שנער,\u0004 שמשם מתפשטים הדינין לכל הצדדים, והוא הראש וההתחלה של המלכות להפרד מהקדושה, כי עליה נאמר אנת הוא רישא די דהבא. כי זה לעומת זה עשה אלקים, ויש בהקליפות ג\"כ ד' בחינות חו\"ב תו\"מ, וקליפת בבל, היא בחינת חכמה דקליפה, והיא ראש לכל הקליפות."],[1,"ואי תימא הא וכו':","ואם תאמר, הרי כתוב, ונהר יוצא מעדן להשקות את הגן ומשם יפרד. ואיך תאמר שהבקעה בארץ שנער היא ההתחלה של הפירוד. ומשיב \u0003ודאי כן הוא,\u0004 שהפירוד מתחיל אחר המלכות דאצילות שה\"ס הגן. כי \u0003כיון שנסעו משם\u0004 מהגן, ע\"כ מצאו בקעה בארץ שנער ונעשה פירוד, אבל \u0003וכד אינון כנישין תמן לינקאה לא הוי פירודא,\u0004 וכשמכונסים שם בהגן לינוק, ואינם ממשיכים הארת השמאל משם ולמטה, אז אין שם פירוד. וע\"כ אומה\"כ על הגן ומשם יפרד, אבל דוקא \u0003וכד נטלין הוי פרודא,\u0004 אם נוסעים מהגן נעשה פירוד, שכתוב \u0003ויהי בנסעם מקדם,\u0004 דהיינו מהגן, וימצאו בקעה. כמו שנתבאר, ואם לא היו נוסעים משם לא היו מוצאים בקעה בארץ שנער, ולא היו מתפרדים מהקדושה, וע\"כ נחשב הבקעה בארץ שנער להתחלה של הפירוד."],[2,"ויהי כל הארץ שפה אחת","וכו': כי אז היה העולם ביסוד ועיקר ושורש אחד, דהיינו בבחינת הנקודה דמדת הרחמים, והיו באמונה אחת בהקב\"ה. שלא לחטא לפניו. מה כתוב, \u0003ויהי בנסעם מקדם,\u0004 שנסעו מקדמונו ועקרו של העולם, אמונת הכל. \u0003וימצאו בקעה,\u0004 מציאה מצאו, ויצאו מחמתה מתחת האמונה העליונה כמ\"ש להלן."],[3,"ת\"ח נמרוד וכו':","בוא וראה, נמרוד מה כתוב בו, ותהי ראשית ממלכתו בבל, כי משם לקח כח להאחז ברשות הסטרא אחרא, וכן כאן כתוב וימצאו בקעה בארץ שנער, שמשם לקחו הרצון בלבותיהם לצאת מרשות העליון לרשות האחר. הרי שארץ שנער, שהוא בבל, הוא הראש והשורש להפרד מהקב\"ה."],[3,"","ביאור הדברים. כי בנין הקליפות התחיל עם החטא דעצה\"ד, והגם שמציאותם היתה גם מקודם החטא דעצה\"ד, כי ענין הקליפות הן שיעורי גילוי חסרונות שבקדושה, וע\"כ עוד מעת צמצום א', שנגלה חסרון קבלה בהמלכות, ונמנעה מלקבל לתוכה אור ישר, יצאה לעומתה בחינת מלכות דקליפות, וכן בשיעור שמלכות דקדושה הזאת נכללה בז\"א, יצאה ג\"כ בחינת ז\"א דקליפה. אמנם זו\"ן אלו דקליפות אין להם שום כח דפרודא ממש, והם רק מציאות בלי שום כח. וזהו מטעם כי אותו המיעוט שבמלכות דקדושה, שמשם יצאו, לא היה מיעוט כלל, אלא להיפך, שע\"י מיעוט הזה נתקנה המלכות בסוד זווג דהכאה והאצילה כל העולמות, והוא כל הדרה ותפארתה. ולפיכך אע\"פ שנעשה מחמת צמצום א' מציאות של זו\"ן דקליפות. היה זה בלי שום כח של היזק ופירוד כלל. ותחלת כח הפירוד נתגלה בהם עם החטא של עץ הדעת, שאחר שנבנתה המלכות עם הכלים דבינה, וקיבלה אור ישר בהם, ועל ידי החטא דעצה\"ד חזר ונגלה מדת הדין שבה, שאינה ראויה לקבל, וכל האורות פרחו ממנה, הרי נגלה פגם ממש בהמלכות, ומתוך שבינה היתה נכללת ממנה. הגיע פגם ההיא גם בבינה, ובשיעור שבינה זו חזרה לחכמה, כדי להשפיע חכמה אל זו\"ן, הרי הגיע פגם משהו גם לחכמה, ומה גם כי עיקר החטא דעצה\"ד, היה המשכת הארת החכמה מלמעלה למטה כנודע. וע\"כ נגלה כאן ד' חסרונות בקדושה כנגד חו\"ב וזו\"ן, ונבנו מן פגמים הללו ד' בחינות חו\"ב תו\"מ דקליפות."],[3,"","אמנם עם העונש של המבול ועם יציאת נח ובניו מן התבה והקרבת הקרבן, נתתקן הרבה החטא דעצה\"ד, וכמעט שנתבטלה זוהמת הנחש כמו במתן תורה, כנ\"ל בזהר (דף ל\"ב אות פ\"ח) וע\"כ חזרו ונתבטלו בניני הקליפות לשעתם, ולא נשאר להם שורש ומציאות בחכמה ובינה, אלא רק בזו\"ן בלבד, כמו שהיו לפני החטא של עצה\"ד כנ\"ל. וזסו\"ה ויהי הארץ שפה אחת ודברים אחדים, שלא היה שום כח פירוד בהעולמות כנ\"ל בזהר."],[3,"","וזה אמרו, \u0003ויהי בנסעם מקדם, מקדמאה עקרא דעלמא,\u0004 דהיינו, שהסכימו בדעתם לחטא בהמשכת החכמה ממעלה למטה כעצת הנחש, \u0003וימצאו בקעה, מציאה אשכחו, ונפקו בה מתחות מהימנותא עלאה,\u0004 דהיינו שמצאו את בינה דקליפה, אשר מטרם זה כבר נתבטלה מהעולמות ואיננה, ועתה חזרה להגלות ומצאו אותה, והוא מכח שנסעו מקדמונו של עולם ונתגלה בהם זוהמא דחויא, ע\"כ חזרה ונבנה להם תכף הבינה דקליפה, דהיינו רק מן בחינת הקטנות שבה, הנקראת \u0003בקעה,\u0004 ששם הזה יורה על עת בקיעת המדרגה שנעשה בהבינה מכח התכללותה של המלכות בתוכה, כנ\"ל, שפגם של המלכות מתערב בהבינה, ומפגם זה נבנתה הבינה דקליפה, שחטאו ויצאו בה מתחת האמונה העליונה, דהיינו בינה. כי המלכות נקראת \u0003מהמנותא,\u0004 והבינה נקראת \u0003מהמנותא עלאה.\u0004 ושיעור הכתוב הוא, \u0003וימצאו בקעה\u0004 היינו קטנות ופגם. \u0003בארץ שנער,\u0004 היא הבינה דקליפה, \u0003וישבו שם,\u0004 היינו שתקנו אותה לבחינת ישוב, שהמשיכו אליה בחזרה שלימת הכלים, באופן שתהא ראויה למוחין דחכמה, כי הקטנות נבחנת כמו מדבר, שאינו ראוי לישוב בני אדם. והגדלות נבחנת לישוב, ותכף ומיד אמרו, \u0003הבה נבנה לנו עיר ומגדל\u0004 וגו', דהיינו להמשיך הג\"ר דחו\"ב אל הבינה דקליפה הזאת. הנקראים עיר ומגדל. באופן שיאירו ממעלה למטה עד לעוה\"ז. שעם זה בנו את החכמה דקליפה ונמצא עתה שארץ שנער נבנתה בכחם להיות חכמה דקליפה. וחזר בנין ד' בחינות חו\"ב תו\"מ להקליפות כמו שהיו בשעת החטא דעצה\"ד. ובדברים הללו תבין את ההמשך של המאמר."],[4,"ויאטרו הבה נבנה וגו':","רבי חייא פתח והרשעים כים נגרש וגו' ומקשה, וכי יש ים נגרש. ואומר, הן, כי כשהים יוצא ממקום תקונו, והולך לבלי גבול, כלומר, שרוצה לעבור את החול, שהוא גבולו, ולהשתפך על היבשה. אז הוא נגרש ויוצא ממקומו. כמו השכור מיין, ואינו יושב על היכנו אלא עולה ויורד, מהו הטעם, משום, כי השקט לא יוכל ויגרשו מימיו רפש וטיט. שמימיו מוציאים כל טיט הים וכל טנופת. מקרקע הים אל שפתו."],[5,"כגוונא דא וכו':","כעין זה הם הרשעים דהיינו דור הפלגה, שיצאו מדרך המתוקן, מקדמונו של עולם והלכו בלי תקון, כשכורי יין שנתדבקו בבינה דקליפה כנ\"ל ויצאו מדרך הישר לדרך מעוות. דהיינו להבקעה בארץ שנער, שהיא הפגם שמצאו שם כנ\"ל. מהו הטעם, משום, כי השקט לא יוכל, כי העקמימות שבדרכם שהיא הפגם שמצאו בה גרמה להם ללכת בלי תקון ובלי השקט. עד שאמרו, הבה נבנה לנו עיר ומגדל וגו', דהיינו שבנו את חו\"ב של הקליפות כנ\"ל."],[6,"ולא עוד וכו':","עוד אלא שנתמלאו בכעס, בשעה שאמרו הדבר בפיהם. דהיינו בשעה שאמרו הבה נבנה לנו וגו' כי נתכוונו בזה למלאות תאותם (בלהלן באות שמ\"ד) וכל גרגרן כועס. דבר ההוא שאמרו. הוא רפש וטיט, שהכתוב אומר עליהם ויגרשו מימיו רפש וטיט. דהיינו בחינות הקליפות הנקראות רפש וטיט. כולם הוציאו טנוף וגיעול מפיהם לחוץ. דהיינו הזוהמא דחויא שהמשיכו באמירתם הבה נבנה וגו', עד שנטמאו בטומאת הנחש, והנחש טימא אותם."]],[[0,"","בֹּא רְאֵה, וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וְגוֹ'. מַה כָּתוּב אַחַר כָּךְ? וַיְהִי בְּנָסְעָם מִקֶּדֶם - מֵאוֹתוֹ קַדְמוֹנוֹ שֶׁל הָעוֹלָם - וַיִּמְצְאוּ בִקְעָה בְּאֶרֶץ שִׁנְעָר. שֶׁהֲרֵי מִשָּׁם נִפְרָדִים לְכָל אוֹתָם הַצְּדָדִים, וְהוּא רֹאשׁ הַמַּלְכוּת לְהִתְפַּזֵּר."],[1,"","וְאִם תֹּאמַר, הִנֵּה כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד? וַדַּאי שֶׁכָּכָה זֶה. שֶׁכֵּיוָן שֶׁנּוֹסְעִים מִשָּׁם יֵשׁ פֵּרוּד, וְכַאֲשֶׁר הֵם מְכֻנָּסִים שָׁם לִינוֹק אֵין פֵּרוּד. וּכְשֶׁנּוֹסְעִים יֵשׁ פֵּרוּד, שֶׁכָּתוּב וַיְהִי בְּנָסְעָם מִקֶּדֶם וַיִּמְצְאוּ בִקְעָה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[2,"","וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים, שֶׁאָז הֲרֵי הָעוֹלָם בִּיסוֹד וְעִקָּר וְשֹׁרֶשׁ אֶחָד וֶאֱמוּנָה אַחַת בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. מַה כָּתוּב? וַיְהִי בְּנָסְעָם מִקֶּדֶם, מֵהָרִאשׁוֹן עִקַּר הָעוֹלָם אֱמוּנַת הַכֹּל. וַיִּמְצְאוּ בִקְעָה, מְצִיאָה מָצְאוּ וְיָצְאוּ בָהּ מִתַּחַת הָאֱמוּנָה הָעֶלְיוֹנָה (וימצאו)."],[3,"","בֹּא רְאֵה מַה כָּתוּב בְּנִמְרוֹד, וַתְּהִי רֵאשִׁית מַמְלַכְתּוֹ בָּבֶל. שֶׁהֲרֵי מִשָּׁם נָסַע לְהֵאָחֵז בְּרָשׁוּת אַחֶרֶת. וְכָאן, וַיִּמְצְאוּ בִקְעָה בְּאֶרֶץ שִׁנְעָר. מִשָּׁם נָסְעוּ בְּלִבָּם לָצֵאת מֵרָשׁוּת הָעֶלְיוֹנָה לְרָשׁוּת אַחֶרֶת."],[4,"","וַיֹּאמְרוּ הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם וְנַעֲשֶׂה לָּנוּ שֵׁם. רַבִּי חִיָּיא פָּתַח, (ישעיה נז) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגוֹ'. וְכִי יֵשׁ יָם נִגְרָשׁ? כֵּן. שֶׁכַּאֲשֶׁר הַיָּם יוֹצֵא מִתִּקּוּנוֹ וְהוֹלֵךְ (בלי הבל) בְּלִי רַב חוֹבֵל, אָז נִגְרָשׁ וּמִתְגָּרֵשׁ מִמְּקוֹמוֹ, כְּמִי שֶׁשּׁוֹתֶה יַיִן וְלֹא יוֹשֵׁב עַל בֻּרְיוֹ וְעוֹלֶה וְיוֹרֵד. מָה הַטַּעַם? מִשּׁוּם כִּי הַשְׁקֵט לֹא יוּכָל וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט. שֶׁמּוֹצִיאִים מֵימָיו כָּל אוֹתוֹ הַטִּיט שֶׁל הַיָּם וְכָל הַטִּנֹּפֶת לִשְׂפָתוֹ."],[5,"","כְּמוֹ זֶה אוֹתָם הָרְשָׁעִים שֶׁיּוֹצְאִים מִדֶּרֶךְ תְּקִינָה וְהוֹלְכִים כִּשְׁתוּיֵי יַיִן בְּלִי תִקּוּן, שֶׁיּוֹצְאִים מִדֶּרֶךְ יְשָׁרָה לְדֶרֶךְ עֲקֻמָּה. מָה הַטַּעַם? מִשּׁוּם כִּי הַשְׁקֵט לֹא יוּכָל, שֶׁהֲרֵי עִקּוּם דַּרְכֵיהֶם גָּרַם לָהֶם לָלֶכֶת בְּלִי תִקּוּן וּבְלִי שֶׁקֶט."],[6,"","וְלֹא עוֹד, אֶלָּא שֶׁכָּל רֻגְזָם בְּשָׁעָה שֶׁאוֹמְרִים דִּבּוּר מִפִּיהֶם, אוֹתוֹ הַדִּבּוּר רֶפֶשׁ וָטִיט, כֻּלָּם מוֹצִיאִים טִנֹּפֶת וְגֹעַל מִפִּיהֶם הַחוּצָה עַד שֶׁנִּטְמָאִים וּמְטַמְּאִים אוֹתָם."]]],[["תָּא חֲזֵי, וַיֹּאמְרוּ הָבָה נִבְנָה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם. לֵית הָבָה אֶלָּא הַזְמָנָה בְּעָלְמָא. נִבְנֶה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם. כֻּלְהוּ בְּעֵיטָא בִּישָׁא אָתוּ לְסַרְבָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. בִּשְׁטוּתָא אָתוּ (איהו) בְּטִפְּשׁוּ דְּלִבָּא.","אָמַר רַבִּי אַבָּא שְׁטוּתָא נְסִיבוּ בְּלִבַּיְיהוּ. אֲבָל בְּחָכְמָה דִּרְשִׁיעוּ אָתוּ בְּגִין לְנָפְקָא מֵרְשׁוּ עִלָּאָה לִרְשׁוּ אָחֳרָא וּלְאַחְלָפָא יְקָרֵיהּ לִיקָרָא נוּכְרָאָה. וּבְכֹלָּא אִית רָזָא דְּחָכְמְתָא עִלָּאָה.","הָבָה נִבְנָה לָנוּ עִיר וּמִגְדָּל. תָּא חֲזֵי, כַּד מָטוּ לְהַאי בִּקְעָה דְּאִיהוּ רְשׁוּ נוּכְרָאָה וְאִתְגְּלִי לְהוּ אֲתַר דְּשָׁלְטְנוּתָא דָּא תְּקִיעַ בְּגוֹ נוּנֵי יַמָּא. אָמְרוּ הָא אֲתַר לְמֵיתַב וּלְאִתְתַּקְפָא לִבָּא לְאִתְהַנָּאָה בֵּיהּ תַּתָּאֵי. מִיָּד הָבָה נִבְנָה לָנוּ עִיר. נַתְקִין בְּאֲתַר דָּא עִיר וּמִגְדָּל.","וְנַעֲשֶׂה לָנוּ שֵׁם. אֲתַר דָּא (יהיב לון) יְהֵא לָן לְדַחֲלָא וְלָא אָחֳרָא, וְנִבְנֶה לְאֲתַר דָּא עִיר וּמִגְדָּל. לָמָּה לָן לְסָלְקָא לְעֵילָא דְּלָא נֵיכוֹל לְאִתְהַנָּאָה מִנָּהּ. הָא הָכָא אֲתַר מְתַקְנָא. וְנַעֲשֶׂה לָנוּ שֵׁם דַּחֲלָא לְמִפְלַח תַּמָּן. פֶּן נָפוּץ לְדַרְגִּין אָחֳרָנִין וְנִתְבַּדַּר לְסִטְרֵי עָלְמָא:","\u0003סִתְרֵי תּוֹרָה\u0004 קוּמְטוּרָא דְּהֻרְמָנָא מְמַלְּלָן בְּלָשׁוֹן הַקֹּדֶשׁ דְּמַלְאֲכֵי הַשָׁרֵתּ אִשְׁתְּמוֹדְעָן בֵּיהּ וְלָא הֲווּ מְמַלְלִין בְּלִישָׁן אָחֳרָא. בְּגִין כָּךָ כְּתִּיב וְעַתָּה לֹא יִבָּצֵּר מֵהֶם וְגו'. דְּאִלְמָלֵי מִשְׁתָּעָאן בְּלִישָׁן אָחֳרָא דְּמַלְאֲכֵי עִלָּאֵי לָא הֲווּ אִשְׁתְּמוֹדְעָן בֵּיהּ, גָּרַע חֲשִׁיבוּ דְּאִנוּן חָשְׁבִין לְמֶעְבַּד. בְּגִין דְּעוֹבָדָא דְּשֵׁדִין לָאו אִיהוּ אֶלָּא בְּרִגְעָא חָדָא לְחֵזוּ בְּנֵי אֱנָשָׁא ולא יַתִּיר.","וּדְבָרִים אֲחָדִים. דְּהֲווּ יָדְעִין דַּרְגִּין עִלָּאִין כָּל חַד וְחַד על בּוּרְיֵיהּ ולא אִתְּחְלַף לְהוּ דַּרְגָּא וּבְגִין כָּךָ כְּתִּיב וּדְבָרִים אֲחָדִים. וּבְגִין כָּךָ אִתְּיָעֲטוּ בְּעִיטָא בִּישָׁא עִיטָא דְּחָכְמְתָּא דִּכְתִּיב הָבָה נִבְנֶה לָנוּ עִיר וּמִגְדָּל.","כּלָּא בְּרָזָא דְּחָכְמְתָּא הוּא, וּבָעוּ לְאִתַּקְפָּא בְּאַרְעָא סִטְרָא אָחֳרָא וּלְמִפְּלַח פּוּלְחָנָא דִּילֵיהּ. בְּגִין דְּהֲווּ יָדְעִין דְּהָא כָּל דִּינִין בִּישִׁין מִתַּמָּן נַחֲתִּין לְעָלְמִין. וּבָעְיָין לִדְחוּיֵי דַּרְגָּא דְּקֻדְּשָׁא.","עִי\"ר וּמִגְדָּ\"ל, דָּא חָכְמְתָּא עִלָּאָה. (ד\"א דהא) הֲווּ יָדְעֵי דּשמָא קַדִּישָׁא לָא אִתְּתַּקַּף בְּאַרְעָא, אֶלָּא בְּעִיר וּמִגְדָּל. עִי\"ר דִּכְתִּיב, (שמואל ב ה׳:ז׳) (מ\"א ח) עִיר דָּוד הִיא צִּיּוֹן וְגו'. מִגְדָּ\"ל דִּכְתִּיב (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַּוָּארֵךָ. וּבְחָכְמְתָּא עֲבָדוּ לְמֶהֱוֵי שָׁלְטָנָא דְּסִטְרָא אָחֳרָא בִּאַרְעָא דְּדַחְיָיא (ד\"א לדחייא) ֹ אֲדוֹן כָּל הָאָרֶץ מֵאַתְּרֵיהּ. וּלְמֶהֱוִי דִיוּרָא לְסִטְרָא אָחֳרָא בְּאַרְעָא.","וְנַעֲשֶׂה לָנוּ שֵׁם. כְּמָה דַּאֲחִידָא (ד\"א דאחרא) אִיהוּ שֵׁם לְעֵילָא, נַתְּקִיף לָהּ בֵּיננא לְמֶהֱוֵי שֵׁם בְּאַרְעָא. פֶּן נָפּוֹץ. יְדִיעָה הֲווּ יָדְעִין דְּיִתְּבַּדְּרוּן מֵעַל אַפֵּי אַרְעָא. וּבְגִין כָּךָ הֲווּ מִתְּיַחֲדִין לְמֶעְבַּד עֲבִידְתָּא דָא בְּחָכְמָה.","סִטְרָא אָחֳרָא אִיהוּ דְּכַר וְנוּקְבָא תּוּקְפָּא דְזוּהֲמָא דְדִינָא קַשְׁיָא. וּכְמָה דְאָדָם חָב (ביה) בְּהוּ וְאִתְּקָפּוּ בְּגִינֵיהּ על עָלְמָא. אוּף הָכִי אִנּוּן עָבְדִין דְּאִתְּתַּקַּף יַתִּיר. דִּכְתִּיב אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. בְּנוֹי דְּאָדָם קַדְמָאָה דְּאַיְיתֵּי וְאַשְׁלִיט סִטְרָא אָחֳרָא עַל עָלְמָא סִטְרָא בִישָׁא. כְּמָה דְסִטְרָא דִקְדוּשָׁה לָאו שָׁלְטָנֵיהּ בְּהַאי עָלְמָא אֶלָּא בְּעִיר וּמִגְדָּל. אוּף הָכִי חֲשִׁיבֵי אִנּוּן לְמִבְנֵי עִיר וּמִגְדָּל לְמִשְׁלַט הַאי סְטַר בִּישָׁא בְּעָלְמָא:","וִיִּרֶד יְיָ לִרְאוֹתּ. נָחַתּ הַאי שְׁמָא דְּקַדִּישָׁא לְמֶחֱזִי (על) עוֹבָדֵיהוֹן דְּבִנְיָינא דְּבָנוּ. וְאִנּוּן הֲווּ מְמַלְּלָן בִּלְשׁוֹן קֹדֶשׁ לְגַבֵּי כָּל אִנּוּן דַּרְגִּין קַדִּישִׁין וְהֲווּ מַצְּלִיחִין. כֵּיוָן דְּנַחֲתַּתּ קְדֻשָׁה אִתְּבַּלְבְּלוּ כָּל אִנּוּן דַּרְגִּין. עִלָּאִין נָחֲתּוּ וְתַּתָּאִין סְלִיקוּ. וְלָא הֲווּ קָיְימִין בְּאֹרַח מֵישָׁר כְּמָה דְּהֲווּ. וּלְבָתַּר בִּלְבֵּל לִישַׁנְהוֹן בְּע' לִישָׁן וְאִתְּבַּדָּרוּ לְכָל סִטְרֵי עָלְמָא.","חַד מְמַנָּא הוּא בִּרְקִיעָא וּבֵיהּ קָיְימִין כָּל (ד\"א ל\"ג אנון) מַפְּתְּחָן דְּעוֹבָדֵי עָלְמָא. ואִיהוּ קָיְימָא זַמִּין בְּשַׁעֲתֵּי וְרִגְעֵי דְיוֹמָא. וְאִנּוּן הֲווּ יָדְעִין בְּרָזָא דְחָכְמְתָּא גִּנְזָא דְּהַאי מְמַנָּא. וְהֲווּ פָּתְּחֵי וְסָגְרֵי וּמַצְּלְחֵי בְּעוֹבָדֵיהוֹן בְּמֵימְרָא דְפּוּמְהוֹן. כֵּיוָן (דאסתכלא) דְּאִתְּבַּלְבָּל מֵימְרָא דִלְהוֹן, כֹּלָּא אִתְּמְנָע מִנַּיְיהוּ.","וַאֲתַּר מְתֻּקָּן אַשְׁכָּחוּ בְּהַהוּא בִּקְעָה. סִטְרָא דְּסִטְרִין: וַיִּמְצְּאוּ בִּקְעָה. אֲתַּר מְתֻּקָּן לְהַאי (ד\"א ל\"ג ההוא) סִטְרָא בִּישָׁא דְּבָעוּ אִנּוּן לְאַתְּקָפָּא וְאִתְּמְנָעוּ. תּוּקְפָּא (דיליה) דְּהַהוּא סִטְרָא הֲוָה תַּלְיָא לְאִתְּפְּרָעָא בְּהַהִיא בִּקְעָה עַד דְּנָטְלָא תַּמָּן חֵילִין וּמַשִׁירְיָין כְּגַוְונָא דְּאִנּוּן דְּבָנוּ קַרְתָּא וּמִגְדְּלָא וְאִתְּיְהִיבוּ (כלא) כֻּלְהוּ בִּידָהָא. וְאִתְּקַטָלוּ תַּמָּן","אִנּוּן דּלא בָּעוּ לְמֵיפַּק בְּקֵ\"ץ הַיָּמִי\"ן. אִתְּבְּהִילוּ וְנָפְּלוּ בְּקֵץ הַיָּמִי\"ם. בְּהַהוּא אֲתַּר דְּאִתְּחַלַּשׁ תֻּקְפָּא בְּקַדְמִיתָּא בְּהַאי בִּקְעָה. ועל דָּא כְּתִּיב, (יחזקאל לו) וְהִיא מְלֵאָה עֲצָּמוֹתּ.","וְאִתְּתַּקְפַּתּ בְּהַהוּא צּוּלְמָא דְאָקִים נְבוּכַדְנֶצַּר. וְאִתְּבַּר תּוּקְפָּא לְבָתַּר בְּאִנּוּן גַּרְמִין וּבְהַהוּא צּוּלְמָא. דְּאִנּוּן קַדְמָאֵי קָיְימוּ וקָמוּ עַל רַגְלֵיהוֹן. וְהַהוּא צּוּלְמָא אִתְּבָּר.","וּכְדֵין יָדְעוּ כָּל עַמִּין דְּעָלְמָא דְּלֵיתּ אֱלוֹהַּ בַּר קוּדְשָׁא בְּרִיךָ הוּא בִּלְחוֹדוֹי. ותּוּ דְּאִתְּקַדַּשׁ שְׁמֵיהּ עַל יְדָא דְּחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה וְכלָּא בְּחַד יוֹמָא. וְעַל דָּא כְּתִּיב, (ישעיהו כ״ט:כ״ג) וְהִקְדִּישׁוּ אֶתּ קְדוֹשׁ יַעֲקֹב וגו', (עד כאן סתרי תורה)","וַיֵּרֶד יְיָ לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל דָּא הוּא חַד מֵאִנּוּן עֶשֶׂר זִמְנִין דְּנָחֲתָא שְׁכִינְתָּא לְאַרְעָא. וְכִי מַה הוּא לִרְאוֹת וְלָא הֲוָה יָדַע מִקַּדְמַת דְּנָא. אֶלָּא לִרְאוֹת לְאַשְׁגָּחָא בְּדִינָא כְּמָא דְאַתְּ אָמֵר, (שמות ה׳:כ״א) יֵרֶא יְיָ עֲלֵיכֶם וְיִשְׁפֹּט.","אֶת הָעִיר וְאֶת הַמִּגְדָּל. הָכָא אִית לְאִסְתַּכָּלָא. דְּהָא לָא כְּתִיב לִרְאוֹת אֶת בְּנֵי הָאָדָם. אֶלָּא לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל. אַמַּאי. אֶלָּא בְּשַׁעֲתָא דְּאַשְׁגַּח קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא, בְּקַדְמִיתָא יַשְׁגַּח בְּדַרְגָּא דִלְעֵילָא, וּלְבָתַר בְּדַרְגָּא דִלְתַתָּא. בְּקַדְמִיתָא בְּעִלָּאֵי וּלְבָתַר בְּתַתָּאֵי. וּבְגִין דְּהַאי מִלָּה מָטָא לְעֵילָא, אַשְׁגָּחוּתָא דִלְעֵילָא הֲוָה בֵּיהּ בְּקַדְמִיתָא דִּכְתִיב לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל.","אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. מַאי בְּנֵי הָאָדָם בְּנוֹי דְאָדָם קַדְמָאָה דְּמָרַד בְּמָרֵיהּ וְגָרַם מוֹתָא לְעָלְמָא. אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם בִּנְיָינָא וַדַּאי אָמְרוּ (גרמו) וּבָעוּ לְמִבְנִי לְעֵילָא."],[[0,"ת\"ח ויאמרו וכו':","בוא וראה, ויאמרו הבה נבנה לנו עיר ומגדל וראשו בשמים, אין \u0003הבה\u0004 אלא הזמנה בלבד. דהיינו רק דיבור בלי מעשה, אלא שהדיבור שאמרו, גרם בנין עיר ומגדל למעלה, כמ\"ש להלן (באות שנ\"ג כולם באו בעצה הרעה למאן בהקב\"ה, ובאו בשטות בטפשות הלב."],[1,"אמר ר' אבא וכו':","אמר רבי אבא, שטות לקח לבם, אבל באו בחכמה דקליפה, כדי לצאת מרשות העליון הקדוש לרשות אחר, להקליפות, ולהחליף כבודו ית' בכבוד אל זר. ובכל הענין יש סוד חכמה העליונה."],[2,"הבה נבנה לנו וגו':","בוא וראה, כאשר באו לבקעה הזו, שהיא רשות נכרי, דהיינו בפגם הבינה דקליפה וישבו שם שפירושו, שנגלה להם שמקום זה תקועה בתוך דגי הים, כלומר שנגלה להם שלימות הכלים של בינה זו, שראויה לישוב בני אדם. דהיינו לקבל חכמה. (כנ\"ל דף קי\"ט ד\"ה וזה עש\"ה) \u0003ים,\u0004 פירושו חכמה. \u0003דגי הים,\u0004 פירושו מדרגות החכמה. אמרו הנה המקום, לשבת ולחזק הלב, ושיהנו בו, התחתונים. כלומר להמשיך ממעלה למטה, שזהו מקום הקליפות. מיד אמרו, הבה נבנה לנו עיר, נתקן במקום הזה עיר ומגדל."],[3,"ונעשה לנו שם:","מקום הזה יהיה לנו לאלהים, דהיינו מקום הקליפות, ולא מקום אחר, ונבנה למקום הזה עיר ומגדל, דהיינו להמשיך חו\"ב דקליפות הנק' עיר ומגדל כנ\"ל. למה לנו לעלות למעלה, דהיינו להמשיך ממטה למעלה, שאין אנו יכולים להנות משם, הנה כאן מקום מתוקן, להמשיך ממעלה למטה. ונעשה לנו שם, פירושו, אלהים לעבוד שם. \u0003פן נפוץ,\u0004 למדרגות אחרות ונתפזר לארבע רוחות העולם."],[4,"קומטורא דהרמנא וכו':","מקימי העיר והמגדל, היו מדברים בלשון הקדש, שמלאכי השרת מכירים אותו. ולא היו מדברים בלשון אחר. משום זה כתוב, ועתה לא יבצר מהם וגו'. ואם היו מדברים בלשון אחר, שמלאכים העליונים אינם מכירים אותו, היתה נמנעה מחשבתם שחשבו לעשות, משום שמעשה שדים אינו אלא לרגע אחד, רק למראה בני אדם ולא יותר, \u0003קומטורא דהרמנא,\u0004 לפי הענין, פירושו, מקימי העיר והמגדל, ויכול להיות שצריך לומר קמטרא והרמנא. או קומי טירא והרמנא. טירא פירושו העיר. והרמנא הוא כמו ארמנא, שפירושו הארמון, המגדל."],[4,"","ביאור הדברים. כי הזהר מבאר מה משמיענו במה שכתוב, ויהי כל הארץ שפה אחת, ואומר ששפה אחת, פירושו לשון הקדש. ומשמיענו שבשביל שדברו בלשון הקדש היו משביעים המלאכים העליונים שיסייעו אותם בבנינם. ולפיכך אומר הכתוב, לא יבצר מהם אשר יזמו לעשות. אבל אם לא היו מדברים בלשון הקדש, לא היה להם עזרת המלאכים, והיו מעשיהם כמעשה שדים, שאין לו תקומה אלא רגע, ותכף מתבטל מעצמו."],[5,"ודברים אחדים וכו':","שהיו יודעים מדרגות העליונות כל אחת ואחת על היכנה. ולא היתה נחלפת להם מדרגה, ומשום זה כתוב ודברים אחדים. כלומר שהמדרגות היו ברורות להם כמו דברים אחדים, שאין בהם טורח להכירם. ומשום זה נועצו בעצה רעה, עצה של החכמה, שכתוב, הבה נבנה לנו עיר ומגדל. שהוא בחינת חכמה דקליפות כנ\"ל."],[6,"כלא ברזא דחכמתא וכו':","הכל הוא בסוד החכמה, שרצו להגביר את הסטרא אחרא בהארץ. ולעבוד העבודה של הס\"א, משום שידעו כי כל דינים הרעים יורדים משם להעולמות, ורצו בזה לדחות מדרגת הקדושה."],[7,"עיר ומגדל דא חכמתא וכו':","עיר ומגדל זהו חכמה העליונה. כי היו יודעים שהשם הקדוש, שהוא מלכות, לא נתחזק בהארץ אלא בעיר ומגדל. \u0003עיר,\u0004 שכתוב, עיר דוד היא ציון וגו' \u0003מגדל,\u0004 שכתוב, כמגדל דוד צוארך. הרי שהשם הקדוש, שהיא מלכותא דדוד, נקראת ג\"כ בשמות הללו, עיר ומגדל, והיינו בעת שהמלכות ממשכת חכמה. ועשו גם הם בחכמה דס\"א לקיים ממשלת הסטרא אחרא בארץ, שהוא הלעומת של המלכות, ולדחות המלכות הנקראת אדון כל הארץ, ממקומה. ושתהיה ישיבה ומגורים להסטרא אחרא בהארץ."],[8,"ונעשה לנו שם וכו':","כמו שהאחר, דהיינו הקדושה, הוא שם למעלה, נחזק, אותה בינינו שתהיה שם בהארץ. כלומר, כמו שהקדושה מאירה ממטה למעלה, כן נמשיך ממעלה למטה להארץ. \u0003פן נפוץ.\u0004 ידיעה היו יודעים, שיתפזרו על פני הארץ, ועל כן היו מתיחדים לעשות עבודה הזאת, דעיר ומגדל, בחכמה."],[9,"סטרא אחרא איהו וכו':","ס\"א הוא זכר ונקבה. הם תוקף הזוהמא של דין הקשה. וכמו שאדם חטא בו, בעצה\"ד, ונתחזקו הדו\"נ דס\"א על ידו בהעולם, כן עשו אף הם שיתחזק הס\"א יותר, שכתוב, אשר בנו בני האדם, דהיינו בניו של אדם הראשון, שהביא והמשיל הסטרא אחרא על העולם, הוא הצד הרע. כמו שצר הקדושה אין לה ממשלה בעולם הזה, אלא בעיר ומגדל, כן חשבו אף הם לבנות עיר ומגדל, להשליט את צד הרע הזה בהעולם."],[10,"וירד ה' לראות וכו':","ירד שם הקדוש הזה, להסתכל במעשיהם בהבנין שבנו, והם היו מדברים בלשון הקודש אל כל מדרגות הקדושות, שעשו השבעות כנ\"ל. והיו מצליחים, כיון שירדה הקדושה, נתבלבלו כל אלו מדרגות, העליונות ירדו, והתחתונות עלו, ולא היו עומדים בדרך הישר כמו שהיו, וע\"כ לא יכלו עוד לעשות השבעות, כי השמות נחלפו להם. ואח\"כ בלבל לשונם בע' לשון, ונתפזרו לכל רוחות העולם."],[11,"חד ממנא הוא וכו':","ממונה אחד, הוא ברקיע, ועמו נמצאים כל המפתחות למעשי העולם, והוא עומד מוכן לדורשיו, רק בשעות ורגעים ידועים של היום והם היו יודעים בסוד החכמה את הנסתרות של ממונה הזה, והיו פותחים וסוגרים במאמר פיהם את השערים של כל הנסתרות, ומצליחים, דהיינו ע\"י השבעות שעשו בפיהם לאותו הממונה, הצליחו בבנין העיר והמגדל, להיותו השר של העולם ומנהיגו. כיון שנתבלבל מאמר פיהם, הכל נמנע מהם. כי לא ידעו עוד לעשות השבעות לאותו הממונה."],[12,"ואתר מתקן אשכחו וכו':","ומקום מוכן ומוכשר מצאו באותה בקעה, והוא סתר שבסתרים. \u0003וימצאו בקעה,\u0004 פירושו, מקום מוכשר לצד הרע הזה, שרצו להגבירו ונמנע מהם. תוקפו של אותו הצד נשאר תלוי, באותה הבקעה, להפרע, עד שנסעו ובאו שם צבאות ומחנות כעין אלו שבנו העיר והמגדל, דהיינו בני אפרים, כמו שמסיים, וניתנו כולם בידי אותו הצד, ונהרגו שם."],[13,"אנון דלא וכו':","ואלו שלא רצו לצאת בקץ הימין, שהם בני אפרים, שיצאו ממצרים קודם הזמן, (כמ\"ש בסנהדרין צב: ע\"ש). נבהלו ונפלו לקץ הימים, במקום ההוא שכבר נחלש תוקפו בבקעה זו. דהיינו בזמן דור הפלגה. ועתה בעונם חזר ונתגבר והרגם, ועל זה כתוב והיא מלאה עצמות."],[14,"ואתתקפת בההוא וכו':","ונתגברה הס\"א באותו הצלם שהקים נבוכדנצר, ואח\"כ נשבר תוקפה באלו העצמות של בני אפרים שיחזקאל החיה אותם, ובאותו הצלם דקדושה של אלו הראשונים שחזרו לתחיה וקמו על רגליהם, נשבר צלם ההוא שעשה נבוכדנצר."],[15,"וכדין ידעו וכו':","ואז ידעו כל עמי העולם שאין אלוה זולת הקב\"ה בלבדו. ועוד שנתקדש השם על ידי חנניה מישאל ועזריה, שגם זה גרם שנשבר תוקפה דס\"א. וכל אלו, היו ביום אחד, וע\"כ כתוב והקדישו וכו' כי ג' אלו דהיינו תחית המתים דיחזקאל, וקידוש השם של חנניה מישאל ועזריה, ושבירת הצלם דנבוכדנצר, הכל היה ביום אחד, (כמ\"ש בסנהדרין צב:) ששה נסים נעשו באותו היום ע\"ש."],[16,"וירד ה' לראות וגו':","זה הוא אחת מאלו עשר פעמים שירדה השכינה לארץ. (כמ\"ש באבות דרבי נתן פל\"ד ע\"ש) ושואל, וכי מה היה לו \u0003לראות,\u0004 שלא היה יודע מקודם לכן. ומשיב, אלא \u0003לראות\u0004 פירושו, להשגיח במדת הדין. כמ\"ש ירא אלקים וישפוט."],[17,"את העיר ואת המגדל וכו':","יש כאן להסתכל כי לא כתוב, לראות את בני האדם, אלא, לראות את העיר ואת המגדל. למה. אלא בשעה שהקב\"ה משגיח לפעול בדין. בתחילה הוא משגיח בהמדרגה של מעלה, שהיא השורש, ואח\"כ בהמדרגה של מטה, דהיינו בהענף. בתחילה בהעליונים ואח\"כ בהתחתונים. ומשום שדבר זה, דעיר ומגדל, מגיע עד למעלה. דהיינו בעולמות העליונים, ההשגחה של מעלה היה בו בתחילה, שכתוב לראות את העיר ואת המגדל. דהיינו עיר ומגדל שבעולמות העליונים."],[18,"אשר בנו בני האדם.","שואל מהו שאומר בני האדם. ומשיב, שהכתוב מרמז שהם בניו של אדם הראשון שמרד ברבונו וגרם המות להעולם. כלומר, שנמשכו אחרי מעשיו. אשר בנו בני האדם ודאי הוא שבנו בנין. אע\"פ שאמרו הבה נבנה, שהוא רק הזמנה. כי אמרו וגרמו להבנות למעלה. כלומר שאמרו השבעות בפיהם (כנ\"ל באות שנ\"ב) ועל ידיהם נבנו העיר והמגדל."]],[[0,"","בֹּא רְאֵה, וַיֹּאמְרוּ הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם. אֵין הָבָה אֶלָּא לְשׁוֹן הַזְמָנָה בְּעָלְמָא. נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם, כֻּלָּם בָּאוּ בְּעֵצָה רָעָה לְסָרֵב לַקָּדוֹשׁ-בָּרוּךְ-הוּא. בִּשְׁטוּת בָּאוּ, הוּא בְּטִפְּשׁוּת הַלֵּב."],[1,"","אָמַר רַבִּי אַבָּא, שְׁטוּת לָקְחוּ בְּלִבָּם, אֲבָל בְּחָכְמָה שֶׁל רִשְׁעוּת בָּאוּ כְּדֵי לָצֵאת מֵרָשׁוּת עֶלְיוֹנָה לְרָשׁוּת אַחֶרֶת, וּלְהַחֲלִיף כְּבוֹדוֹ לְכָבוֹד זָר. וּבַכֹּל יֵשׁ סוֹד שֶׁל חָכְמָה עֶלְיוֹנָה."],[2,"","הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל. בֹּא רְאֵה, כְּשֶׁהִגִּיעוּ לַבִּקְעָה הַ את שֶׁהִיא רָשׁוּת זָרָה, וְהִתְגַּלָּה לָהֶם מָקוֹם שֶׁשִּׁלְטוֹן זֶה תָּקוּעַ בְּתוֹךְ דְּגֵי הַיָּם, אָמְרוּ, הִנֵּה מָקוֹם לָשֶׁבֶת וּלְחַזֵּק אֶת הַלֵּב לֵהָנוֹת בּוֹ הַתַּחְתּוֹנִים. מִיָּד הָבָה נִבְנֶה לָּנוּ עִיר, נַתְקִין בַּמָּקוֹם הַזֶּה עִיר וּמִגְדָּל."],[3,"","וְנַעָשֶׂה לָּנוּ שֵׁם. מָקוֹם זֶה (נתן להם) יִהְיֶה לָנוּ לְיִרְאָה, וְלֹא אַחֵר, וְנִבְנֶה לְמָקוֹם זֶה עִיר וּמִגְדָּל. לָמָּה לָנוּ לַעֲלוֹת לְמַעְלָה שֶׁלֹּא נוּכַל לֵהָנוֹת מִמֶּנּוּ? הֲרֵי כָּאן מָקוֹם מְתֻקָּן. וְנַעֲשֶׂה לָּנוּ שֵׁם, יִרְאָה לַעֲבֹד שָׁם. פֶּן נָפוּץ לִדְרָגוֹת אֲחֵרוֹת וְנִתְפַּזֵּר לִצִדְדֵי הָעוֹלָם."],[4,"","מְקִימֵי הָעִיר וְהַמִּגְדָּל מְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ שֶׁמַּלְאֲכֵי הַשָּׁרֵת מַכִּירִים אוֹתָהּ, וְלֹא הָיוּ מְדַבְּרִים בְּלָשׁוֹן אַחֶרֶת, מִשּׁוּם כָּךְ כָּתוּב וְעַתָּה לֹא יִבָּצֵר מֵהֶם וְגוֹ'. שֶׁאִלְמָלֵא מְדַבְּרִים בְּלָשׁוֹן אַחֶרֶת שֶׁמַּלְאָכִים עֶלְיוֹנִים לֹא הָיוּ מַכִּירִים אוֹתָהּ, נֶחְסְרָה הַחֲשִׁיבוּת שֶׁהֵם חָשְׁבוּ לַעֲשׂוֹת, כֵּיוָן שֶׁמַּעֲשֵׂה הַשֵּׁדִים אֵינוֹ אֶלָּא בְּרֶגַע אֶחָד לְמַרְאֵה בְּנֵי אָדָם וְלֹא יוֹתֵר."],[5,"","וּדְבָרִים אֲחָדִים, שֶׁהָיוּ יוֹדְעִים דְּרָגוֹת עֶלְיוֹנוֹת כָּל אַחַת וְאַחַת עַל בֻּרְיָהּ, וְלֹא הִתְחַלְּפָה לָהֶם דַּרְגָּה, וְלָכֵן כָּתוּב וּדְבָרִים אֲחָדִים. וּמִשּׁוּם כָּךְ הִתְיָעֲצוּ בְּעֵצָה רָעָה, עֵצָה שֶׁל חָכְמָה, שֶׁכָּתוּב הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל."],[6,"","הַכֹּל הוּא בְּסוֹד הַחָכְמָה. וְרָצוּ לְחַזֵּק בָּאָרֶץ אֶת הַצַּד הָאַחֵר וְלַעֲבֹד אֶת עֲבוֹדָתוֹ, מִשּׁוּם שֶׁהָיוּ יוֹדְעִים שֶׁכָּל הַדִּינִים הָרָעִים מִשָּׁם יוֹרְדִים לָעוֹלָמוֹת, וְרָצוּ לִדְחוֹת אֶת דַּרְגַּת הַקֹּדֶשׁ."],[7,"","עִי\"ר וּמִגְדָּ\"ל - זוֹ הַחָכְמָה הָעֶלְיוֹנָה, (שהרי) הָיוּ יוֹדְעִים שֶׁשֵּׁם הַקָּדוֹשׁ לֹא מִתְחַזֵּק בָּאָרֶץ אֶלָּא בְּעִיר וּמִגְדָּל. עִי\"ר - שֶׁכָּתוּב (שמואל ב ה) עִיר דָּוִד הִיא צִיּוֹן וְגוֹ'. מִגְדָּ\"ל - שֶׁכָּתוּב (שיר ד) כְּמִגְדַּל דָּוִיד צַוָּארֵךְ. וּבְחָכְמָה עָשׂוּ לִהְיוֹת שִׁלְטוֹן הַצַד הָאַחֵר בָּאָרֶץ שֶׁדּוֹחֶה (לדחות) אֶת אֲדוֹן כָּל הָאָרֶץ מִמְּקוֹמוֹ, וְלִהְיוֹת דִּיּוּר לַסִּטְרָא אַחֲרָא בָּאָרֶץ."],[8,"","וְנַעָשֶׂה לָּנוּ שֵׁם - כְּמוֹ שֶׁאָחוּז (שאחר) הוּא הַשֵּׁם לְמַעְלָה, נְחַזֵּק אוֹתָהּ בֵּינֵינוּ שֶׁיִּהְיֶה שֵׁם בָּאָרֶץ. פֶּן נָפוּץ - יְדִיעָה הָיוּ יוֹדְעִים שֶׁיִּתְפַּזְּרוּ מֵעַל פְּנֵי הָאָרֶץ, וְלָכֵן הָיוּ מִתְיַחֲדִים לַעֲשׂוֹת מַעֲשֶׂה זֶה בְּחָכְמָה."],[9,"","הַצַד הָאַחֵר הוּא זָכָר וּנְקֵבָה, תֹּקֶף זֻהֲמַת הַדִּין הַקָּשֶׁה. וּכְמוֹ שֶׁאָדָם חָטָא (בו) בָהֶם וְהִתְחַזְּקוּ בִּגְלָלוֹ עַל הָעוֹלָם, גַּם כָּאן הֵם עָשׂוּ שֶׁיִּתְחַזֵּק יוֹתֵר, שֶׁכָּתוּב אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. בְּנֵי אָדָם הָרִאשׁוֹן שֶׁהֵבִיא וְהִשְׁלִיט צַד הָאַחֵר עַל הָעוֹלָם, הַצַּד הָרָע. כְּמוֹ שֶׁצַּד הַקְּדֻשָּׁה אֵין שִׁלְטוֹנוֹ בָּעוֹלָם הַזֶּה אֶלָּא בְּעִיר וּמִגְדָּל, גַּם כָּאן חָשְׁבוּ הֵם לִבְנוֹת עִיר וּמִגְדָּל לְהַשְׁלִיט אֶת הַצַּד הָרָע הַזֶּה בָּעוֹלָם."],[10,"","וַיֵּרֶד ה' לִרְאוֹת. נָחַת הַשֵּׁם הַקָּדוֹשׁ הַזֶּה לִרְאוֹת (על) אֶת מַעֲשֵׂיהֶם שֶׁל הַבִּנְיָן שֶׁבָּנוּ, וְהֵם הָיוּ מְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ לְכָל אוֹתָם דְּרָגוֹת קְדוֹשׁוֹת וְהָיוּ מַצְלִיחִים. כֵּיוָן שֶׁיָּרְדָה הַקְּדֻשָּׁה, הִתְבַּלְבְּלוּ כָּל הַדְּרָגוֹת הַלָּלוּ. עֶלְיוֹנִים יָרְדוּ וְתַחְתּוֹנִים עָלוּ, וְלֹא הָיוּ עוֹמְדִים בְּדֶרֶךְ יָשָׁר כְּמוֹ שֶׁהָיוּ. וְאַחַר כָּךְ בִּלְבֵּל לְשׁוֹנָם בְּשִׁבְעִים לָשׁוֹן וְהִתְפַּזְּרוּ לְכָל צִדְדֵי הָעוֹלָם."],[11,"","מְמֻנֶּה אֶחָד יֵשׁ בָּרָקִיעַ, וּבוֹ קַיָּמִים כָּל (ד\"א אותם) מַפְתְּחוֹת שֶׁל מַעֲשֵׂי הָעוֹלָם, וְהוּא קַיָּם וְזָמִין בְּכָל הַשָּׁעוֹת וְרִגְעֵי הַיּוֹם. וְהֵם הָיוּ יוֹדְעִים בְּסוֹד הַחָכְמָה, הַגְּנוּזָה שֶׁל הַמְמֻנֶּה הַזֶּה, וְהָיוּ פוֹתְחִים וְסוֹגְרִים וּמַצְלִיחִים בְּמַעֲשֵׂיהֶם בְּמַאֲמַר פִּיהֶם. כֵּיוָן (שהסתכלו) שֶׁהִתְבַּלְבֵּל הַמַּאֲמָר שֶׁלָּהֶם, הַכֹּל נִמְנַע מֵהֶם,"],[12,"","וּמָקוֹם מְתֻקָּן מָצְאוּ בְּאוֹתָהּ בִּקְעָה. צַד הַצְּדָדִים. וַיִּמְצְאוּ בִקְעָה, מָקוֹם מְתֻקָּן לְזֶה (אותו) הַצַּד הָרָע, שֶׁרָצוּ הֵם לְחַזֵּק וְנִמְנְעוּ. תֹּקֶף (שלו) שֶׁל אוֹתוֹ הַצַּד הָיָה תָלוּי לְהִפָּרַע בְּאוֹתָהּ בִּקְעָה, עַד שֶׁנָּטְלָה מִשָּׁם צְבָאוֹת וּמַחֲנוֹת, כְּמוֹ שֶׁהֵם בָּנוּ עִיר וּמִגְדָּל וְנִתְּנוּ (הכל) כֻלָּם בְּיָדֶיהָ. וְנֶהֶרְגוּ שָׁם"],[13,"","אוֹתָם שֶׁלֹּא רָצוּ לָצֵאת בְּקֵ\"ץ הַיָּמִי\"ן. נִבְהֲלוּ וְנָפְלוּ בְּקֵ\"ץ הַיָּמִי\"ם, בְּאוֹתוֹ מָקוֹם שֶׁנֶּחֱלַשׁ הַכֹּחַ בַּתְּחִלָּה בַּבִּקְעָה הַזּוֹ. וְעַל זֶה כָּתוּב (יחזקאל לו) וְהִיא מְלֵאָה עֲצָמוֹת. וְהִתְחַזְּקָה בְּאוֹתוֹ הַצֶּלֶם שֶׁהֵקִים נְבוּכַדְנֶצַּר."],[14,"","וְנִשְׁבַּר הַתֹּקֶף אַחַר כָּךְ בְּאוֹתָם עֲצָמוֹת וּבְאוֹתוֹ צֶלֶם. שֶׁאוֹתָם רִאשׁוֹנִים הִתְקַיְּמוּ וְקָמוּ עַל רַגְלֵיהֶם, וְאוֹתוֹ צֶלֶם נִשְׁבַּר,"],[15,"","וְאָז יָדְעוּ כָּל עַמֵּי הָעוֹלָם שֶׁאֵין אֱלוֹהַּ מִבַּלְעֲדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ. וְעוֹד, שֶׁהִתְקַדֵּשׁ שְׁמוֹ עַל יְדֵי חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, וְהַכֹּל בְּיוֹם אֶחָד. וְעַל זֶה כָּתוּב (ישעיה כט) וְהִקְדִּישׁוּ אֶת קְדוֹשׁ יַעֲקֹב וְגוֹ'. ע\"כ סתרי תורה."],[16,"","וַיֵּרֶד ה' לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל. זוֹ אַחַת מֵעֶשֶׂר פְּעָמִים שֶׁיָּרְדָה הַשְּׁכִינָה לָאָרֶץ. וְכִי מַה הוּא לִרְאוֹת, וְלֹא הָיָה יוֹדֵעַ מִקֹּדֶם לָזֶה? אֶלָּא לִרְאוֹת לְהַשְׁגִּיחַ בַּדִּין, כְּמוֹ שֶׁנֶּאֱמַר (שמות ה) יֵרֶא ה' עֲלֵיכֶם וְיִשְׁפֹּט."],[17,"","אֶת הָעִיר וְאֶת הַמִּגְדָּל - כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי לֹא כָתוּב לִרְאוֹת אֶת בְּנֵי הָאָדָם, אֶלָּא לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל. לָמָּה? אֶלָּא בְּשָׁעָה שֶׁמַּשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין, בַּהַתְחָלָה מַשְׁגִּיחַ בַּדַּרְגָּה שֶׁלְּמַעְלָה, וְאַחַר כָּךְ בַּדַּרְגָּה שֶׁלְּמַטָּה. בַּהַתְחָלָה בָּעֶלְיוֹנִים, וְאַחַר כָּךְ בַּתַּחְתּוֹנִים. וּמִשּׁוּם שֶׁדָּבָר זֶה מַגִּיעַ לְמַעְלָה, הַהַשְׁגָּחָה שֶׁל מַעְלָה הָיְתָה בּוֹ בַּהַתְחָלָה, שֶׁכָּתוּב לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל."],[18,"","אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. מַה זֶּה בְּנֵי הָאָדָם? בְּנֵי אָדָם הָרִאשׁוֹן שֶׁמָּרַד בְּרִבּוֹנוֹ וְגָרַם מָוֶת לָעוֹלָם. אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם - בִּנְיָן וַדַּאי אָמְרוּ (גרמו) וְרָצוּ לִבְנוֹת לְמַעְלָה."]]],[["רַבִּי שִׁמְעוֹן פָּתַח (ואמר) (יחזקאל מ״ו:א׳) כֹּה אָמַר יְיָ אֱלֹהִים שַׁעַר הֶחָצֵר הַפְּנִימִית הַפּוֹנֶה קָדִים יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. וְאִיהוּ רָזָא כְּמָה דְאִתְּמָר. יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה. אַמַּאי (וביום השבת יפתח וביום החדש יפתח וגו'. אמאי יהיה סגור כל אנון יומין דששת ימי המעשה).","אֶלָּא אִלֵין יְמֵי חוֹל. דְּתַרְעָא דָא יִהְיֶה סָגוּר דְּלָא לְאִשְׁתַּמָּשָׁא חוֹל בְּקוּדְשָׁא. וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ. דְּהָא כְּדֵין שִׁמּוּשָׁא (דקודשא בריך הוא) דְּקוּדְשָׁא בְּקוּדְשָׁא. וּכְדֵין אִתְנְהִיר סִיהֲרָא לְאִתְחַבְּרָא בְּשִׁמְשָׁא.","תָּא חֲזֵי, תַּרְעָא דָא לָא אִתְפַּתַּח בְּאִנּוּן שִׁתָּא יוֹמֵי דְּחוֹל. בְּגִין דְּהָא בְּאִנּוּן יוֹמֵי דְּחוֹל עָלְמָא תַּתָּאָה אִתְּזָן וְשָׁלְטִין כָּל אִנּוּן שִׁית יוֹמִין דְּחוֹל עַל עָלְמָא בַּר בְּאַרְעָא דְיִשְׂרָאֵל.","וְאִנּוּן דְּשָׁלְטֵי לָא שָׁלְטֵי בְּאַרְעָא קַדִּישָׁא בְּגִין דְּהַשַּׁעַר הַזֶּה אִיהוּ סָגוּר. אֲבָל בְּיוֹם הַשַּׁבָּת וּבְיוֹם הַחֹדֶשׁ כֻּלְהוּ מִתְעַבְּרָן וְלָא שָׁלְטִין בְּגִין דְּהַשַּׁעַר הַזֶּה אִיהוּ פָּתוּחַ וְעָלְמָא אִיהוּ בְּחֶדְוָה וְאִתְּזָן מִתַּמָּן וְלָא אִתְיְיהִיב עָלְמָא לִרְשׁוּ אָחֳרָא.","וְאִי תֵימָא דְּכָל אִנּוּן שִׁית יוֹמִין אִנּוּן שָׁלְטִין בִּלְחוֹדַיְיהוּ. תָּא חֲזֵי, הַפּוֹנֶה קָדִים. עַד לָא יְקוּמוּן לְשַׁלְטָאָה אִיהוּ אִסְתַּכַּל תָּדִיר בְּעָלְמָא. אֲבָל לָא אִתְפַּתַּח לְאִתְזְנָא עָלְמָא מִקּוּדְשָׁא בַּר בְּיוֹמָא דְשַׁבַּתָּא וּבְיוֹמָא דְחָדְשָׁא. וְכֻלְהוּ יוֹמִין כֻּלְהוּ אִתְדַּבְּקָן בְּיוֹמָא דְשַׁבַּתָּא וְאִתְזְנוּ מִתַּמָּן. דְּהָא (ד\"א ל\"ג כדין) בְּיוֹמָא דְּשַׁבַּתָּא כֻּלְהוּ תַּרְעִין פְּתִיחָן וְנַיְיחָא אִשְׁתְּכַח לְכֹלָּא לְעִלָּאֵי וְתַתָּאֵי. תָּא חֲזֵי, וַיֵּרֶד יְיָ לִרְאוֹת. נָחַת מִקּוּדְשָׁא לְחוֹל (ורדיד פרישא) לְאַשְׁגָּחָא בַּמֶּה דְּבָּנוּ וְקָיְימוּ קִיּוּמָא לְאַתְעָרָא עַל עָלְמָא לְדָחֲלָא לוֹן.","רַבִּי יִצְחָק הֲוָה יָתִיב קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. אָמַר לֵיהּ מָה חָמוּ אִלֵּין דְּעֲבָדוּ שְׁטוּתָא דָא לְמָרְדָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וְכֻלְהוּ בְּעֵיטָא חָדָא אִתְקָיְימוּ בְּדָא. אָמַר לֵיהּ הָא אִתְּמָר דִּכְתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם אִתְנְטִילוּ מֵעֵילָא לְתַתָּא. אִתְנְטִילוּ מֵאַרְעָא דְיִשְׂרָאֵל וְנָחֲתוּ לְבָבָל. אָמְרוּ הָא הָכָא אֲתַר לְמִדְבַּק.","וְנַעֲשֶׂה לָנוּ שֵׁם וְגו' וְיִתְדַּבַּק סִיּוּעָא דִלְתַתָּא בְּאֲתַר דָּא. בְּגִין דְּכַד דִּינָא אָתֵי לְאַשְׁרָאָה בְּעָלְמָא, הָא אֲתַר דָּא לְקֳבְלֵיהּ. וּמֵהָכָא אִתְהַנֵּי עָלְמָא וְיִתְּזָן. דְּהָא לְעֵילָא דְּחִיקוּ אִיהוּ לְאִתְזְנָא עָלְמָא מִנֵּיהּ. וְלָא עוֹד אֶלָּא אֲנַן נִסַּק לִרְקִיעָא וְנַגַּח בֵּיהּ קְרָבָא דְּלָא יֵחוֹת (ביה) טוֹפָנָא בְּעָלְמָא כְּדִבְקַדְמִיתָא:","וַיֹּאמֶר יְיָ הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. בְּגִין דְּכֻלְהוּ כְּחֲדָא, בְּיִיחוּדָא דְּכֻלְהוֹן יַעַבְדוּן וְיִצְלְחוּן בְּעוֹבָדַיְיהוּ. יִתְבַּדְּרוּן דַּרְגִּין כָּל חַד לְסִטְרֵיהּ. וּבְגִין כָּךְ יִתְבַּדְּרוּן כָּל הַנֵּי דִלְתַתָּא. מַה כְּתִיב וַיָּפֶץ יְיָ אוֹתָם מִשָּׁם.","וְאִי תֵימָא לִישַׁנְהוֹן אַמַּאי אִתְבַּלְבֵּל (אתבדר ובלבל לון קודשא בריך הוא). אֶלָּא בְּגִין דְּכֻלְהוֹן מְמַלְּלִין בִּלְשׁוֹן הַקֹּדֶשׁ. הַהוּא לִישְׁנָא קָא עָבִיד לוֹן סִיּוּעָא. בְּגִין דִּבְעוֹבָדָא וּבְמִלּוּלָא דְפוּמָא תַּלְיָין מִלִּין אִלֵּין לְאַדְבְּקָא כַּוָּנָה דְלִבָּא. וּבְדָא עָבְדֵי סִיּוּעָא לְהַהוּא אֲתַר דְּבָעֵי לְאַקָמָא.","וְעַל דָּא אִתְבַּלְבָּל לִישַׁנְהוֹן דְּלָא יָכִילוּ לְאִתְתַּקָּפָא רְעוּתְהוֹן בִּלְשׁוֹן הַקֹּדֶשׁ. כֵּיוָן דְּאִתְחַלַּף לִישַׁנְהוֹן לָא אַצְלָחוּ בְּעוֹבָדָא (כט א בס\"ת) בְּגִין דְּחֵילָא דִּלְעֵילָא לָא יָדְעֵי וְלָא אִשְׁתְּמוֹדְעֵי בַּר בִּלְשׁוֹן הַקֹּדֶשׁ. וְכַד אִתְבַּלְבָּל לִישְׁנָא דִלְהוֹן אִתְחַלַּשׁ חֵילֵיהוֹן וְאִתְבַּר תּוּקְפָא דִלְהוֹן.","תָּא חֲזֵי, דְּהָא מִלָּה (דא) דְּאָמְרֵי תַּתָּאֵי בִּלְשׁוֹן הַקֹּדֶשׁ, כֻּלְהוּ חֵילֵי שְׁמַיָא יָדְעֵי בֵּיהּ וְאִתְתַּקְפֵי בֵּיהּ. וְלִישַׁן אָחֳרָא לָא יָדְעִין וְלָא אִשְׁתְּמוֹדְעֵי בֵּיהּ. וְעַל דָּא אִלֵּין כֵּיוָן דְּאִתְבַּלְבָּל לִישָׁנָא דִלְהוֹן, מִיָּד וַיַּחְדְּלוּ לִבְנוֹת הָעִיר. דְּהָא אִתְבַּר חֵילַיְיהוּ וְלָא יָכִילוּ לְמֶעְבַּד מִדֵּי בִּרְעוּתָא דִלְהוֹן.","(דניאל ב׳:כ׳) לֶהֱוֵי שְׁמֵיהּ (די אלהא) (דקודשא בריך הוא) מְבָרַךְ מִן עָלְמָא וְעַד עָלְמָא, דִי חָכְמְתָא וּגְבוּרָתָא דִי לֵהּהִיא. דְּהָא בְּגִין (דא) דְּאַנְחִית קוּדְשָׁא בְּרִיךְ הוּא רָזֵי דְּחָכְמְתָא לְעָלְמָא, אִתְקַּלְקָלוּ בֵּיהּ בְּנֵי נָשָׁא וּבָעוּ לְאִתְגָּרָא בֵּיהּ."],[[0,"רבי שמען פתח וכו':","ר\"ש פתח, כה אמר ה' אלקים שער החצר הפנימית וגו', בכתוב הזה יש להסתכל בו, והוא סוד. כמו שאמרו, יהיה סגור ששת ימי המעשה, למה יהיה סגור."],[1,"אלא אלין ימי חול וכו':","אלא אלו הם ימי חול, שהשער הזה יהיה סגור כדי שלא להשתמש חול בקדש. וביום השבת יפתח וביום החדש יפתח, כי אז הוא השמוש של קדש בקדש, ואז מאירה הלבנה, שהיא הנוקבא להתחבר בהשמש. שהוא ז\"א."],[1,"","פירוש. מקום ההשפעה לתחתונים, מכונה \u0003שער.\u0004 ושער חצר הפנימית, הוא מקום השפעת אור החכמה לתחתונים. ומ\"ש הפונה קדים יתבאר להלן באות שס\"ה. \u0003פתוח\u0004 פירושו שמשפיע לתחתונים. \u0003סגור,\u0004 פירושו שהוא שמור ממגע החצונים. \u0003חול\u0004 פירושו שיש בו יכולת היניקה להקליפות, ואינו שמור מהן, \u0003קדש\u0004 פירושו שלגמרי אין שם יניקה כל שהיא לקליפות. והכתוב אומר ששער החצר הפנימית יהיה סגור ששת ימי המעשה וביום השבת יפתח. ושואל, למה יהיה סגור בששת ימי המעשה. ומשיב, משום שלא להשתמש חול בקודש. שלא יתערב הס\"א בהקדושה. כי כל עוד שיש יניקה לקליפות, אין שפע קדש מתגלה. ורק בשבת וחדש יפתח. שאז יש זווג זו\"נ בסוד קדש בקדש, דהיינו שזו\"ן עולים לאו\"א שהם קדש בקדש, אין משם שום יניקה לחצונים וקליפות. וז\"ש וכדין אתנהיר סיהרא לאתחברא בשמשא. שהם זו\"ן."],[2,"תא חזי תרעא וכו':","בוא וראה, שער הזה אינו נפתח בששת ימות החול, משום, כי בימות החול ניזון עולם התחתון, ששם נמצאים החיצונים והקליפות, ושולטים כל אלו ימות החול, שהם הס\"א על העולם, חוץ מבא\"י."],[3,"ואינון דשלטי וכו':","ואלו, ימות החול, השולטים בחוץ לארץ, אינם שולטים בארץ הקודש, משום ששער הזה הוא סגור. אבל ביום השבת וביום החדש, כולם, כל הקליפות, נעברים מהעולם, ואינם שולטים, משום ששער הזה הוא פתוח, והעולם הוא בשמחה והוא ניזון משם. ולא ניתן העולם לרשות אחר."],[3,"","פירוש. השם ארץ ישראל הוא בעיקר בעת שזו\"ן עולים ומלבישים לאו\"א, שאז נק' ז\"א ישראל, והנוקבא, ארץ ישראל או ארץ הקודש. כי המוחין דאו\"א נקראים קודש, ולא פחות מהם כנודע. ואז אפילו בששת ימי המעשה. הנמשכים מז\"א המלביש לאבא. שה\"ס מוחין דחסדים מכוסים מחכמה, אין שם יכולת יניקה לימות החול, שה\"ס כחות הס\"א, מפני ששער הזה של חצר הפנימית המאיר בהארת החכמה, הוא סגור שם בעזקא דכיא מג\"ר דבינה דא\"א, ואינו מאיר אלא בחסדים מכוסים מחכמה. \u0003עזקא\u0004 פירושו, טבעת המקיפו סביב סביב, שלא תכנוס בתוכו הארת החכמה. \u0003דכיא,\u0004 פירושו טהור, דהיינו שאין שם משהו חסרון, כי להיותו נמשך מג\"ר דבינה דא\"א, ע\"כ אע\"פ שהוא חסדים, נבחן לבחינת ג\"ר כמו אור החכמה. ולפיכך, עזקא זו מבריחה הס\"א וכחותיה, כי הס\"א בורחת מפני השלימות ואין לה יכולת להתקרב רק במקום חסרון. וז\"ש \u0003לא שלטי בארעא קדישא בגין דהשער הזה איהו סגור,\u0004 בששת ימי המעשה. דהיינו \u0003שסגור בעזקא דכיא\u0004 המבריח את ימות החול שה\"ס כחות הס\"א."],[3,"","ויום השבת ויום החודש, הנמשכים מהנוקבא המלבשת לאמא, שה\"ס ישסו\"ת. שהם המוחין דהארת החכמה, שז\"ס וביום השבת יפתח וביום החדש יפתח, הרי מוחין האלו מעבירים לגמרי את הס\"א וימות החול ממקום הקדושה. וז\"ש, \u0003אבל ביום השבת וביום החדש כולם מתעברים ולא שולטים בגין דשער הזה פתוח,\u0004 כי שער הזה הפתוח בהארת החכמה, מעביר לגמרי את החצונים ממקום הקדושה. וע\"כ אין שליטה לימות החול שהם כחות הס\"א, בארץ ישראל, לא בששת ימי המעשה הנמשכים מז\"א שבמקום אבא, ולא ביום השבת וחדש הנמשכים מהנוקבא שבמקום אמא: לא בששת ימי המעשה, מפני ששער הזה סגור בעזקא דכיא מג\"ר דבינה דא\"א, המבריח החצונים אע\"פ שהוא סגור מחכמה. ולא ביום השבת, מפני ששער הזה פתוח אז בהארת חכמה, וא\"כ נעלמים לגמרי כחות הס\"א וימות החול. באופן שבארץ ישראל אין שליטה לימות החול לא בשבת ולא בחול."],[4,"ואי תימא וכו':","ואם תאמר. שכל אלו ששה הימים שולטים בפני עצמם, פירוש. כי ערך קבלת ז\"א כלפי קבלת הנוקבא, הוא כערך ג\"ר כלפי ו\"ק. ולפיכך, כיון שהמוחין נמשכים רק בשבת וחדש, שה\"ס הנוק' נמשכין רק ו\"ק דחכמה, אבל אם גם ז\"א, שה\"ס ששת הימים, היה מקבל המוחין, היו נמשכים ג\"ר דחכמה. גם נודע שששת הימים מקבלים מיום השבת, וכיון שכן, יש לומר שהם מקבלים הארת החכמה מיום השבת, באופן שיוכלו לשלוט בה מבחינתם עצמם, בלי התכללות בהנוקבא, דהיינו שיאירו בבחינת דכר, שה\"ס ג\"ר דחכמה. ולזה אומר, \u0003תא חזי הפונה קדים\u0004 וכו': פירושו הפונה למקודם, למטרם שעמדו הקליפות לשלוט, שהוא היה אז מסתכל תמיד בהעולם, ואפילו בששת הימים. אבל לא נפתח שיהיה העולם ניזון מקדש, רק ביום השבת וביום החדש. לכן גם עתה, אי אפשר, שששת ימי המעשה יאירו בהארת חכמה בבחינתם עצמם, כי אז לא יהיה להם מזונות מקודש כמקודם לכן, אלא שכל הימים כולם. דהיינו ששת ימי המעשה כולם, מתדבקים ביום השבת וניזונים משם. כי ביום השבת כל השערים פתוחים ונמצא נחת לכל, לעליונים ותחתונים. אבל ששת הימים לא יוכלו להאיר, אם אינם מתדבקים ביום השבת, מטעם חוסר שפע המזונות כמבואר. \u0003תא חזי וירד ה' לראות\u0004 וכו': ירד מקדש לחול להסתכל במה שבנו והעמידו לקיום, דהיינו העיר והמגדל שהעמידו, שהם חו\"ב דקליפה, לעורר העולם לעבוד אותם."],[5,"ר' יצחק הוה יתיב וכו':","ר\"י היה יושב לפני רבי שמעון, אמר לו, מה ראו הללו, שעשו שטות זה למרוד בהקב\"ה, וכולם עמדו בזה בעצה אחת. א\"ל, הרי למדנו, שכתוב, ויהי בנסעם מקדם, נסעו מלמעלה למטה, דהיינו שנסעו מארץ ישראל וירדו לבבל. אמרו הנה כאן המקום להדבק. פירוש, שמקודם לכן היו בארץ ישראל, ששם ה\"ס שפה אחת ודברים אחדים שאין שם שום מקום מגע לחצונים, כי בששת ימי המעשה השער סגור ומבריח החצונים וביום השבת המוחין דחכמה מעבירים החצונים מהעולם, וע\"כ לא יכלו בני הפלגה לעשות שם כלום, כי לא היה להם מקום להדבק. אלא \u0003בהנסעם מקדם,\u0004 שנסעו מארץ ישראל לבבל לחוץ לארץ, ששם שולטים ימות החול, אמרו כאן המקום להדבק ולהמשיך החכמה ממעלה למטה כדי שיאירו גם בששת ימי המעשה. כי אין כאן התיקון שיהיה שער הפנימי סגור בששת ימי המעשה כמו בארץ ישראל."],[6,"ונעשה לנו שם וכו':","והעזרה מלמטה יתחבר במקום הזה, בחוץ לארץ. פירוש. כי בא\"י אין הארת החכמה רק ביום השבת, שאסור בו שום עזרה מלתתא, שה\"ס איסור עשית מלאכה, כי אין המוחין נמשכים אלא בבחינת הנוקבא, שאין בה מעשה כלל. אבל אנו \u0003נעשה לנו שם,\u0004 ונמשיך המוחין בבחינת דכר, שיתכן בו אתערותא דלתתא. וז\"ש יתדבק סיועא דלתתא באתר דא."],[6,"בגין דכד דינא:","משום, כי כשיבא דין לשרות בהעולם, יהיה מקום זה כנגדו. כלומר, שע\"י המשכתם האורות למקום זה, דהיינו ממעלה למטה, יבטלו כל הדינים מהעולם. ומכאן העולם נהנה וניזון כי למעלה, דהיינו מההארות שממטה למעלה, בדוחק העולם ניזון ממנו. ולא עוד אלא שאנו נעלה לרקיע, ונעשה עמו מלחמה. שאל יוריד מבול בעולם כבתחילה. פירוש. כי הפרסא שנתקנה מתחת האצילות, הוא תקון מיוחד שלא להמשיך הארת החכמה ממעלה למטה. וע\"כ אמרו נעלה לרקיע ונעשה עמו מלחמה כדי לבטל את הגבול הזה ולהמשיך האורות ממעלה למטה."],[7,"ויאמר ה' הן עם אחד וגו':","משום שהם כולם כאחד ביחוד, יעשו ויצליחו במעשיהם. לפיכך, יפוצו המדרגות כל אחת לעברה. ומשום זה יפוצו גם כל אלו העמים של מטה, שהם ענפים של אותן המדרגות. מה כתוב, ויפץ ה' אותם משם. כלומר שהקב\"ה עשה הדין בשרשיהם העליונים, שהענפים נגררים אחריהם, (כנ\"ל באות שנ\"ט)."],[8,"ואי תימא לישנהון וכו':","ואם תאמר לשונם למה נתבלבל. אלא, בעת שכולם היו מדברים בלשון הקודש, היה לשון ההוא עושה להם עזרה, דהיינו ע\"י ההשבעות שעשו למדרגות העליונות, כנ\"ל. מפני שבמעשה ודבור פה תלוים דברים הללו, כדי להשיג כוונת הלב, ובזה בכח הכוונה, עשו עזר וחזוק למקום ההוא שרצו להקים. פירוש. ע\"י ההשבעות שעשו הם הוסיפו כח להמלאכים שהשביעו, אותו השיעור שהוסיפו למלאכים העליונים זכו בו גם המשביעים, מפני שהם היו הגורמים. אבל כל זה הוא רק אם עושים ההשבעות בלשון הקודש, שאז מתחזק כונת הלב, והמלאכים נזקקים לו כמ\"ש להלן."],[9,"ועל דא אתבלבל וכו':","ועל כן, נתבלבל הלשון שלהם, ולא יכלו עוד לחזק את כוונתם בלשון הקודש. וכן כיון שנחלף לשונם, לא הצליחו במעשיהם, משום שהכחות העליונים, אינם יודעים ואינם מכירים חוץ מלשון הקודש. לכן. כאשר נתבלבל הלשון שלהם נחלש כחם ונשבר העצמה שלהם. כלומר, שבלבול הלשון, \u0003החליש כחם\u0004 למטה, שלא יכלו לכוון לבם, וכן \u0003שבר עצמתם\u0004 למעלה."],[10,"ת\"ח דהא מלה וכו':","בוא וראה כי הדבר, דהיינו ההשבעה שאומרים התחתונים בלשון הקודש, כל צבאות השמים יודעים בו, ומתחזקים בו, דהיינו שמקבלים תוספת כח ולשון אחר אינם יודעים ואינם מכירים בו, ועל כן, הללו, כיון שנתבלבל הלשון שלהם, מיד, ויחדלו לבנות העיר, כי נשבר כחם, ולא יכלו עוד לעשות משהו בהכוונה שלהם."],[11,"להוי שמיה וכו':","יהא שמו של הקב\"ה מבורך מן העולם ועד העולם. אשר החכמה והגבורה שלו הוא. כי משום שהוריד הקב\"ה סודות החכמה להעולם נתקלקלו בו בני אדם. ורצו להתגרות בו."]],[[0,"","רַבִּי שִׁמְעוֹן פָּתַח (ואמר), (יחזקאל מו) כֹּה אָמַר ה' אֱלֹהִים שַׁעַר הֶחָצֵר הַפְּנִימִית הַפֹּנֶה קָדִים יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל בּוֹ, וְהוּא סוֹד כְּמוֹ שֶׁנֶּאֱמַר. יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, לָמָּה? (וביום השבת יפתח וביום החדש יפתח וגו', למה יהיה סגור כל אותם ימים של ששת ימי המעשה?)"],[1,"","אֶלָּא אֵלּוּ יְמֵי הַחֹל שֶׁשַּׁעַר זֶה יִהְיֶה סָגוּר שֶׁלֹּא לְהִשְׁתַּמֵּשׁ הַחֹל עִם הַקֹּדֶשׁ. וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ, שֶׁהֲרֵי אָז שִׁמּוּשׁ (של הקדוש ברוך הוא) שֶׁל קֹדֶשׁ בְּקֹדֶשׁ, וְאָז מְאִירָה הַלְּבָנָה לְהִתְחַבֵּר עִם הַשֶּׁמֶשׁ."],[2,"","בֹּא רְאֵה, שַׁעַר זֶה לֹא נִפְתָּח בְּאוֹתָם שֵׁשֶׁת יְמֵי הַחֹל, מִשּׁוּם שֶׁהֲרֵי בְּאוֹתָם יְמֵי הַחֹל הָעוֹלָם הַתַּחְתּוֹן נִזּוֹן, וְשׁוֹלְטִים כָּל אוֹתָם שֵׁשֶׁת יְמֵי הַחֹל עַל הָעוֹלָם חוּץ מֵאֲשֶׁר בְּאֶרֶץ יִשְׂרָאֵל."],[3,"","וְאוֹתָם שֶׁשּׁוֹלְטִים, לֹא שׁוֹלְטִים בָּאָרֶץ הַקְּדוֹשָׁה, מִשּׁוּם שֶׁהַשַּׁעַר הַזֶּה סָגוּר. אֲבָל בְּיוֹם הַשַּׁבָּת וּבְיוֹם הַחֹדֶשׁ, כֻּלָּם עוֹבְרִים וְלֹא שׁוֹלְטִים, מִשּׁוּם שֶׁהַשַּׁעַר הַזֶּה הוּא פָתוּחַ, וְהָעוֹלָם הוּא בְּחֶדְוָה וְנִזּוֹן מִשָּׁם, וְלֹא נִתָּן הָעוֹלָם לְרָשׁוּת אַחֶרֶת."],[4,"","וְאִם תֹּאמַר שֶׁכָּל אוֹתָם שִׁשָּׁה יָמִים הֵם שׁוֹלְטִים לְבַדָּם - בֹּא תִרְאֶה, הַפּוֹנֶה קָדִים, עַד שֶׁלֹּא יָקוּמוּ לִשְׁלֹט, הוּא מִסְתַּכֵּל תָּמִיד בָּעוֹלָם. אֲבָל לֹא נִפְתָּח לָזוּן הָעוֹלָם מִן הַקֹּדֶשׁ פְּרָט לְיוֹם הַשַּׁבָּת וְיוֹם הַחֹדֶשׁ. וְכָל הַיָּמִים כֻּלָּם נִדְבָּקִים בְּיוֹם הַשַּׁבָּת וְנִזּוֹנִים מִשָּׁם. שֶׁהֲרֵי (אז) בְּיוֹם הַשַּׁבָּת כָּל הַשְּׁעָרִים פְּתוּחִים, וּמְנוּחָה נִמְצֵאת לַכֹּל - לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. בּא רְאֵה, וַיֵּרֶד ה' לִרְאוֹת, יָרַד מִקֹּדֶשׁ לְחֹל (וצעיף פרוש) לְהַשְׁגִּיחַ בְּמַה שֶּׁבָּנוּ וְקִיְּמוּ קִיּוּם לְעוֹרֵר עַל הָעוֹלָם לְיִרְאָה אוֹתָם."],[5,"","רַבִּי יִצְחָק הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, מָה רָאוּ אֵלֶּה שֶׁעָשׂוּ שְׁטוּת זוֹ לִמְרֹד בַּקָּדוֹשׁ- בָּרוּךְ-הוּא וְכֻלָּם בְּעֵצָה אַחַת הִתְקַיְּמוּ בָזֶה? אָמַר לוֹ, הֲרֵי נִתְבָּאֵר, שֶׁכָּתוּב וַיְהִי בְּנָסְעָם מִקֶּדֶם. הֻסְּעוּ מִלְמַעְלָה לְמַטָּה. נָסְעוּ מֵאֶרֶץ יִשְׂרָאֵל וְיָרְדוּ לְבָּבֶל. אָמִרוּ, הֲרֵי כָּאן מָקוֹם לְהִדָּבֵק."],[6,"","וְנַעָֹשֶׂה לָּנוּ שֵׁם וְגוֹ', וְיִתְדַּבֵּק הַסִּיּוּעַ שֶׁלְּמַטָּה בַּמָּקוֹם הַזֶּה. מִשּׁוּם שֶׁכְּשֶׁהַדִּין בָּא לִשְׁרוֹת בָּעוֹלָם, הֲרֵי מָקוֹם זֶה כְּנֶגְדּוֹ, וּמִכָּאן יֵהָנֶה הָעוֹלָם וְיִזּוֹן. שֶׁהֲרֵי לְמַעְלָה יֵשׁ דּחַק לְהָזִין אֶת הָעוֹלָם מִמֶּנּוּ. וְלֹא עוֹד, אֶלָּא אָנוּ נַעֲלֶה לָרָקִיעַ וְנַעֲרֹךְ בּוֹ קְרָב שֶׁלֹּא יֵרֵד (בו) מַבּוּל בָּעוֹלָם כְּמִקֹּדֶם."],[7,"","וַיֹּאמֶר ה' הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. מִשּׁוּם שֶׁכֻּלָּם כְּאֶחָד, בְּיִחוּד, שֶׁכֻּלָּם יַעֲשׂוּ וְיַצְלִיחוּ בְּמַעֲשֵׂיהֶם, יִתְפַּזְּרוּ הַדְּרָגוֹת כָּל אֶחָד לַצַּד שֶׁלּוֹ, וּבִגְלַל זֶה יִתְפַּזְּרוּ כָּל אֵלֶּה שֶׁלְּמַטָּה. מַה כָּתוּב? וַיָּפֶץ ה' אֹתָם מִשָּׁם."],[8,"","וְאִם תֹּאמַר, לָמָּה הִתְבַּלְבְּלָה לְשׁוֹנָם (פזר ובלבל אותם הקדוש ברוך הוא)? אֶלָּא מִשּׁוּם שֶׁכֻּלָּם מְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ, אוֹתָהּ לָשׁוֹן עָשְׂתָה לָהֶם סִיּוּעַ. מִשּׁוּם שֶׁבְּמַעֲשֶׂה וּבְדִבּוּר הַפֶּה דְּבָרִים הַלָּלוּ תְּלוּיִים לְהַשִּׂיג כַּוָּנַת הַלֵּב, וּבָזֶה עוֹשִׂים סִיּוּעַ לְאוֹתוֹ מָקוֹם שֶׁרָצוּ לְהָקִים."],[9,"","וְעַל זֶה הִתְבַּלְבְּלָה לְשׁוֹנָם שֶׁלֹּא יָכְלוּ לְחַזֵּק רְצוֹנָם בִּלְשׁוֹן הַקֹּדֶשׁ. כֵּיוָן שֶׁהִתְחַלְּפָה לְשׁוֹנָם, לֹא הִצְלִיחוּ בַּמַּעֲשֶׂה, מִשּׁוּם שֶׁהַצָּבָא שֶׁל מַעְלָה לֹא יוֹדְעִים וְלֹא מַכִּירִים - רַק אֶת לְשׁוֹן הַקֹּדֶשׁ. וּכְשֶׁהִתְבַּלְבְּלָה לְשׁוֹנָם, נֶחֱלַשׁ כֹּחָם וְנִשְׁבַּר תָּקְפָּם."],[10,"","בֹּא רְאֵה, שֶׁהֲרֵי דִּבּוּר (זה) שֶׁאוֹמְרִים הַתַּחְתּוֹנִים בִּלְשׁוֹן הַקֹּדֶשׁ, כָּל צִבְאוֹת הַשָּׁמַיִם יוֹדְעִים בּוֹ וּמַחֲזִיקִים בּוֹ, וְלָשׁוֹן אַחֶרֶת אֵינָם יוֹדְעִים וְלֹא מַכִּירִים בָּהּ. וְעַל זֶה, כֵּיוָן שֶׁהִתְבַּלְבְּלָה לְשׁוֹנָם שֶׁל אֵלֶּה, מִיָּד - וַיַּחְדְּלוּ לִבְנֹת הָעִיר, שֶׁהֲרֵי נִשְׁבַּר כֹּחָם וְלֹא יָכְלוּ לַעֲשׂוֹת דָּבָר בָּרָצוֹן שֶׁלָּהֶם."],[11,"","(דניאל ב) שֶׁיִּהְיֶה שְׁמוֹ (שם האלוה) (של הקב\"ה) מְבֹרָךְ מֵהָעוֹלָם וְעַד הָעוֹלָם, שֶׁהַחָכְמָה וְהַגְּבוּרָה שֶׁלּוֹ הִיא. שֶׁהֲרֵי מִשּׁוּם (זה) שֶׁהוֹרִיד הַקָּדוֹשׁ בָּרוּךְ הוּא סוֹדוֹת הַחָכְמָה לָעוֹלָם, הִתְקַלְקְלוּ בָהּ בְּנֵי אָדָם וְרָצוּ לְהִתְגָּרוֹת בּוֹ."]]],[["יָהַב חָכְמְתָא עִלָּאָה לְאָדָם הָרִאשׁוֹן, וּבְהַהִיא חָכְמָה דְּאִתְגְּלֵי לֵיהּ יָדַע דַּרְגִּין, וְאִתְדְּבַק בְּיֵצֶר הָרָע, עַד דְּאִסְתַּלְּקוּ מִנֵּיהּ מַבּוּעֵי דְחָכְמְתָא. וּלְבָתַר תָּב קַמֵּי מָארֵיהּ, וְאִתְגַּלְּיָין לֵיהּ מִנַּיְיהוּ וְלָא כְּקַדְמִיתָא. לְבָתַר בְּהַהוּא סִפְרָא דִילֵיהּ יָדַע חָכְמָאן. וּלְבָתַר אָתוּ בְּנֵי נָשָׁא וְאַרְגִּיזוּ קַמֵּיהּ.","יָהַב חָכְמְתָא לְנֹחַ וּפְלַח בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לְבָתַר מַה כְּתִיב וַיֵּשְׁתְּ מִן הַיַּיִּן וַיִּשְׁכָּר וַיִּתְגַּל כְּמָה דְּאִתְּמָר. יָהַב חָכְמְתָא לְאַבְרָהָם וּפְלַח בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא. לְבָתַר נָפַק מִנֵּיהּ יִשְׁמָעֵאל דְּאַרְגִּיז קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְכֵן יִצְחָק נָפַק מִנֵּיהּ עֵשָׂו. יַעֲקֹב נְסַב תְּרֵין אֲחָתָן.","יָהַב חָכְמְתָא לְמשֶׁה מַה כְּתִיב בֵּיהּ (במדבר י״ב:ז׳) בְּכָל בֵּיתִי נְאֱמָן הוּא. וְלָא הֲוָה כְּמשֶׁה שַׁמָּשׁ מְהֵימָן בְּכֻלְהוּ דַּרְגִּין וְלָא סָטָא לִבֵּיהּ בְּתִיאוּבְתָּא דְּחַד מִנַּיְיהוּ. אֶלָּא קָאִים בִּמְהֵימְנוּתָא עִלָּאָה כְּדְקָא יְאוּת.","יָהַב חָכְמְתָא עִלָּאָה לִשְׁלֹמֹה מַלְכָּא. לְבָתַר מַה כְּתִיב בֵּיהּ (משלי א׳:א׳) מִשְׁלֵי שְׁלֹמֹה (משלי ל׳:א׳) הַמַּשָּׂא נְאֻם הַגֶּבֶר לְאִיתִיאֵל לְאִיתִיאֵל וְאֻכָל. אָמַר שְׁלֹמֹה אִתִּי אֵל וְחָכְמְתָא דִילֵיהּ הוּא. וְאוּכָל וְאֵיכוּל לְמֶעְבַּד רְעוּתִי. לְבָתַר (מלכים א יח) וַיָּקֶם יְיָ שָׂטָן לִשְׁלֹמֹה וְגו'.","תָּא חֲזֵי, בְּגִין זְעִירוּ דְּחָכְמְתָא דְּאַשְׁכָּחוּ אִלֵּין מֵהַהוּא חָכְמָה דְּקַדְמָאֵי, אִתְגָּרוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבָנוּ מִגְדָּל וְעֲבָדוּ כָּל מַה דְּעֲבָדוּ. עַד דְּאִתְבַּדָּרוּ מֵאַנְפֵּי אַרְעָא וְלָא אִשְׁתָּאַר בְּהוּ חָכְמָה לְמֶעְבַּד מִידֵּי.","אֲבָל לְזִמְנָא דְּאָתֵי קוּדְשָׁא בְּרִיךְ הוּא יִתְעַר חָכְמְתָא בְּעָלְמָא וְיִפְלְחוּן לֵיהּ בָּהּ הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ו:כ״ז) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי. לָאו כְּקַדְמָאֵי דְּחֲבִילוּ בֵּיהּ עָלְמָא. אֶלָּא וְעָשִׂיתִי אֶת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וְאֶת מִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם.","רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר לֵיהּ רַבִּי יוֹסֵי לְרַבִּי חִיָּיא נִפְתַּח בְּאוֹרַיְיתָא וְנֵימָא מִלָּה. פָּתַח רַבִּי יוֹסֵי וְאָמַר (דברים כ״ג:ט״ו) כִּי יְיָ אֱלֹהֶיךָ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנְךָ לְהַצִּילְךָ וְלָתֵת אֹיְבֶיךָ לְפָנֶיךָ וְהָיָה מַחְנְיךָ קָדוֹשׁ וְלֹא יִרְאֶה בְךָ עֶרְוַת דָּבָר וְשָׁב מֵאַחֲרֶיךָ. כִּי יְיָ אֱלֹהֶיךָ מִתְהַלֵּךְ, מְהַלֵּךְ מִבָּעֵי לֵיהּ. אֶלָּא כְּמָא דְאַתְּ אָמֵר (בראשית ג׳:ח׳) מִתְהַלֵּךְ בַּגָּן לְרוּחַ הַיּוֹם. וְדָא הוּא אִילָנָא דְּאָכַל מִנֵּיהּ אָדָם הָרִאשׁוֹן. מִתְהַלֵּךְ נוּקְבָא מְהַלֵּךְ דְּכַר.","וְדָא הוּא דְּאָזִיל קַמַּיְיהוּ דְיִשְׂרָאֵל כַּד הֲווּ אָזְלֵי בְּמַדְבְּרָא דִּכְתִיב (שמות י״ג:כ״א) וַיְיָ הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגו'. הוּא דְּאָזִיל קַמֵּיהּ דְבַּר נָשׁ כַּד אָזִיל בְּאָרְחָא. דִּכְתִיב, (תהילים פ״ה:י״ד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. וְדָא הוּא דְּאָזִיל קַמֵּיהּ דְּבַּר נָשׁ בְּשַׁעֲתָא דְּאִיהוּ זָכֵי. וְלָמָּה. לְהַצִּילְךָ וְלָתֵת אוֹיְבֶיךָ לְפָנֶיךָ. לְאִשְׁתְּזָבָא בַּר נָשׁ בְּאָרְחָא וְלָא יִשְׁלוֹט בֵּיהּ אָחֳרָא.","וּבְגִין כָּךְ לִבָּעֵי לֵיהּ לְבַּר נָשׁ לְאִסְתַּמְּרָא מֵחוֹבוֹי וּלְדַכָּאָה לְגַרְמֵיהּ. מַאי דַּכְיוּ דָּא. דִּכְתִיב, (דברים כ״ג:ט״ו) וְהָיָה מַחֲנֶיךָ קָדוֹשׁ. מַאי קָדוֹשׁ, קְדוֹשִׁים מִבָּעֵי לֵיהּ. אֶלָּא מַחֲנֶיךָ קָדוֹשׁ אִלֵּין שַׁיְיפֵי גוּפָא דְּגוּפָא אִתְחַבַּר וְאִתְתַּקַּן בְּהוּ. וּבְגִין כָּךְ וְהָיָה מַחֲנְיךָ קָדוֹשׁ. וְלא יִרְאֶה בְךָ עֶרְוַת דָּבָר.","מַאי עֶרְוַת דָּבָר. דָּא מִלְּתָא (ערייתא) דְעֶרְיָין. דְּדָא הוּא מִלָּה דְּקוּדְשָׁא בְּרִיךְ הוּא מָאִיס בָּהּ יַתִּיר מִכֹּלָּא. כֵּיוָן דְּאָמַר וְלא יִרְאֶה בְךָ עֶרְוַת, אַמַּאי דָּבָר. אֶלָּא הַנִּי חַיָּיבֵי עָלְמָא דְּגָעֲלֵי וּמְסָאֲבֵי גַרְמַיְיהוּ בְּמִלָּה דִּלְהוֹן דְּנָפְקֵי מִפּוּמַיְיהוּ וְהָא אִיהוּ עֶרְוַת דָּבָר.","וְכָל כָּךְ לָמָּה. בְּגִין דְּאִיהוּ אָזִיל קַמָּךְ. וְאִי אַתְּ עָבִיד כְּדֵין, מִיָּד וְשָׁב מֵאַחֲרֶיךָ, דְּלָא יֵזִיל בַּהֲדָךְ וְיֵיתוּב מֵאַחֲרֶיךָ. וְאֲנַן הָא אַזְלִינָן קַמֵּיהּ בְּאָרְחָא נִתְעַסֵּק בְּמִלֵּי דְאוֹרַיְיתָא. דְּהָא אוֹרַיְיתָא אִתְעַטְּרָא עַל רֵישֵׁיהּ דְּבַר נָשׁ וּשְׁכִינְתָּא לָא אַעֲדִיאַת מִינֵּיהּ.","פָּתַח רַבִּי חִיָּיא וְאָמַר וַיֹּאמֶר ה' הֶן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם וְגו' תָּא חֲזֵי, מַה כְּתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם. מַאי מִקֶּדֶם. מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. וַיִּמְצְאוּ. וַיִּרְאוּ מִבָּעֵי לֵיהּ מַאי וַיִּמְצְאוּ. אֶלָּא מְצִיאָה אַשְׁכָּחוּ תַּמָּן מֵרָזֵי דְחָכְמְתָא מִקַּדְמָאֵי דְּאִתְנְעַר תַּמָּן מִן בְּנֵי טוֹפָנָא, וּבָהּ אִשְׁתַּדְלוּ לְמֶעְבַּד בְּהַהִיא עֲבִידְתָּא דְּעֲבָדוּ לְסַרְבָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְהֲווּ אָמְרֵי בְּפוּמָא וְעַבְדֵי עֲבִידְתָּא."],[[0,"יהב חכמתא עלאה וכו':","נתן חכמה העליונה לאדם הראשון, ועל ידי חכמה ההיא שנתגלה אליו, ידע את המדרגות. והוא נתדבק ביצר הרע עד שנסתלקו ממנו מעינות החכמה, ואחר כך שב אל רבונו, וחזרו ונתגלו לו מקצת מדרגות, מהם, ולא כבתחילה ואח\"כ בספר ההיא שלו, שנתן לו רזיאל המלאך ידע חכמות, ולאחר מכאן באו בני אדם וחטאו ע\"י אלו החכמות, לפני הקב\"ה."],[1,"יהב חכמתא לנח וכו':","נתן חכמה לנח ועבד עמה להקב\"ה, ואח\"כ מה כתוב, וישת מן היין וישכר ויתגל, כמו שנתבאר. נתן חכמה לאברהם, ועבד עמה להקב\"ה, ואחר כך יצא ממנו ישמעאל שהכעיס לפני הקב\"ה. וכן יצחק יצא ממנו עשו. יעקב, נשא שתי אחיות."],[2,"יהב חכמתא למשה וכו':","נתן חכמה למשה, מה כתוב בו, בכל ביתי נאמן הוא. ולא היה כמשה איש נאמן בכל המדרגות, ולא נטה לבו מחמת תאוה לאחת מהן, אלא עמד באמונה העליונה כראוי."],[3,"יהב חכמתא עלאה לשלמה וכו':","נתן חכמה העליונה לשלמה המלך, לאחר מכאן מה כתוב בו במשלי שלמה, (סימן ל') המשא נאם הגבר לאיתיאל, לאיתיאל ואוכל. אמר שלמה אתי אל והחכמה שלו הוא. ואוכל, ואוכל לעשות רצוני, ולא אכשל. כלומר, אע\"פ שכתוב בתורה, ולא ירבה לו נשים ולא יסור לבבו, אני ארבה ולא יסור לבי, כי אתי אל, ונתן לי החכמה שלו. ואחר כך כתוב, \u0003ויקם ה' שטן לשלמה וגו',\u0004 כי לעת זקנתו נשיו הטו את לבבו,העניש אותו כמ\"ש ויקם וגו'."],[4,"ת\"ח בגין זעירו וכו':","בוא וראה בשביל משהו חכמה, שמצאו דור הפלגה מחכמת הראשונים, התגרו בהקב\"ה, ובנו מגדל, ועשו כל מה שעשו, עד שנפוצו מעל פני הארץ, ולא נשאר בהם עוד חכמה לעשות משהו."],[5,"אבל לזמנא דאתי וכו':","אבל לעתיד לבא. הקב\"ה יעיר חכמה בעולם, ויעבדו אותו בה. וז\"ש ואת רוחי אתן בקרבכם \u0003ועשיתי.\u0004 לא כראשונים שהשחיתו עמה העולם, אלא ועשיתי, את אשר בחוקי תלכו ואת משפטי תשמרו ועשיתם."],[6,"רבי יוסי וכו':","ר\"י ורבי חייא היו הולכים בדרך. א\"ל ר\"י לר\"ח, נפתח בדברי תורה ונאמר דבר. פתח ר\"י ואמר. כי ה' אלקיך מתהלך וגו', ושואל, כי ה' אלקיך מתהלך, הלא מהלך צריך לומר. ומשיב, אלא כמו שאתה אומר, מתהלך בגן לרוח היום. וזה נאמר על האילן, שאכל ממנו אדם הראשון, דהיינו הנוקבא שה\"ס עץ הדעת, כן, מתהלך שבכאן נאמר על הנוקבא. כי מתהלך יורה על נוקבא. מהלך, על דכר."],[7,"ודא הוא דאזיל וכו':","והוא דהיינו הנוקבא שהלך לפני בני ישראל כשהיו הולכים במדבר, שכתוב, וה' הולך לפניהם יומם וגו'. וה' יורה על הוא ובית דינו, (כנ\"ל דף מ' אות קי\"ב) ובית דינו היינו הנוקבא. וכן ההולך לפני האדם, כשהולך בדרך. שכתוב צדק לפניו יהלך וגו', וצדק הוא הנוקבא. וכן הוא ההולך לפני האדם בשעה שזוכה. ולמה הוא הולך, היינו כמו שכתוב, להצילך ולתת אויבך לפניך, דהיינו להציל את האדם בדרך, ולא ישלוט בו סטרא אחרא."],[8,"ובג\"כ לבעי ליה וכו'.","ומשום זה צריך האדם להשמר מחטאיו, ולטהר את עצמו. ושואל. מהו טהרה. ומשיב, זהו שכתוב, והיה מחניך קדוש. מהו קדוש, קדושים צריך לומר. דהיינו לשון רבים. אלא מחניך קדוש, הם אברי הגוף, אשר הגוף מתחבר ומתתקן מהם. ועל כך, אומר עליו, והיה מחניך קדוש ולא יראה בך ערות דבר."],[9,"מאי ערות וכו':","ושואל מהו ערות דבר. ואומר, הוא דבר עריות, שזה הוא דבר, שהקב\"ה מואס בו יותר מהכל. ושואל כיון שהכתוב אומר, ולא יראה בך ערות, למה לו לומר דבר. ומשיב, אלא אלו הם רשעי עולם המגעלים ומטמאים עצמם בהדבר שהם מוציאים מפיהם, דהיינו ניבול פה, וזה הוא שאומר ערות דבר. ובזה ביאר לנו הזהר מהו טהרה ששואל לעיל (באות שפ\"א) דהיינו שישמור עצמו מדברי עריות, וישמור פיו מלהוציא דבר מגונה."],[10,"וכל כך למה וכו':","ושואל, ולמה מקפיד התורה כל כך, ומשיב, משום שהוא דהיינו השכינה, הולך לפניך, ואם אתה עושה כזאת מיד ושב מאחריך, כי לא ילך עמך, וישוב מאחריך. ומסיים רבי יוסי, ואנו, הננו הולכים לפניו לפני השכינה, בדרך, נעסוק בדברי תורה, כי התורה מתעטרת על ראשו של אדם, העוסק בה והשכינה אינה מסתלקת ממנו."],[11,"פתח ר' חייא וכו':","פתח ר\"ח ואמר ויאמר ה' הן עם אחד ושפה אחת לכולם. בוא וראה מה כתוב. \u0003ויהי בנסעם מקדם,\u0004 מהו \u0003מקדם.\u0004 ואומר שפירושו, מקדמונו של עולם, ושואל \u0003וימצאו.\u0004 היה לו לומר ויראו בקעה, מהו וימצאו. ומשיב אלא שמצאו מציאה מסורות החכמה של הראשונים, דהיינו דור המבול, שהתנערו שם (שע\"כ נקרא המקום ההוא שנער.) ובחכמה זו שמצאו, השתדלו לעשות העבודה שעשו, כדי למרות בהקב\"ה. והיו אומרים בפיהם השבעות לשרים העליונים. ועשו את העבודה, דהיינו בנין העיר והמגדל."]],[[0,"","נָתַן חָכְמָה עֶלְיוֹנָה לְאָדָם הָרִאשׁוֹן. וּבְאוֹתָהּ חָכְמָה שֶׁהִתְגַּלְּתָה לוֹ, יָדַע דְּרָגוֹת וְנִדְבַּק בַּיֵּצֶר הָרָע, עַד שֶׁהִסְתַּלְּקוּ מִמֶּנּוּ מַעְיְנוֹת הַחָכְמָה, וְאַחַר כָּךְ שָׁב לִפְנֵי רִבּוֹנוֹ וְהִתְגַּלּוּ לוֹ מֵהֶם, וְלֹא כְּמוֹ מִקֹּדֶם. אַחַר כָּךְ בְּאוֹתוֹ הַסֵּפֶר שֶׁלּוֹ יָדַע חָכְמוֹת. אַחַר כָּךְ בָּאוּ בְּנֵי אָדָם וְהִרְגִּיזוּ לְפָנָיו."],[1,"","נָתַן חָכְמָה לְנֹחַ וְעָבַד בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַחַר כָּךְ מַה כָּתוּב? וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל, כְּמוֹ שֶׁנִּתְבָּאֵר. נָתַן חָכְמָה לְאַבְרָהָם וְעָבַד בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אַחַר כָּךְ יָצָא מִמֶּנּוּ יִשְׁמָעֵאל שֶׁהִרְגִּיז לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכֵן יִצְחָק יָצָא מִמֶּנּוּ עֵשָׂו. יַעֲקֹב לָקַח שְׁתֵּי אֲחָיוֹת."],[2,"","נָתַן חָכְמָה לְמֹשֶׁה, מַה כָּתוּב בּוֹ? (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא. וְלֹא הָיָה כְּמֹשֶׁה שַׁמָּשׁ נֶאֱמָן בְּכָל הַדְּרָגוֹת, וְלֹא סָטָה לִבּוֹ בִּתְשׁוּקַת אֶחָד מֵהֶם, אֶלָּא עָמַד בֶּאֱמוּנָה עֶלְיוֹנָה כָּרָאוּי."],[3,"","נָתַן חָכְמָה עֶלְיוֹנָה לִשְׁלֹמֹה הַמֶּלֶךְ, אַחַר כָּךְ מַה כָּתוּב בּוֹ? (משלי א) מִשְׁלֵי שְׁלֹמֹה, (שם ל) הַמַּשָּׂא נְאֻם הַגֶּבֶר לְאִיתִיאֵל לְאִיתִיאֵל וְאֻכָל. אָמַר שְׁלֹמֹה, אִתִּי אֵל, וְהַחָכְמָה שֶׁלּוֹ הִיא. וְאֻכָל - וַאֲנִי יָכוֹל לַעֲשׂוֹת רְצוֹנִי. אַחַר כָּךְ (מלכים א יח) וַיָּקֶם ה' שָׂטָן לִשְׁלֹמֹה וְגוֹ'."],[4,"","בֹּא רְאֵה, מִשּׁוּם קְצָת חָכְמָה שֶׁמָּצְאוּ אֵלֶּה מֵאוֹתָהּ חָכְמַת הָרִאשׁוֹנִים, הִתְגָּרוּ בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וּבָנוּ מִגְדָּל וְעָשׂוּ כָּל מַה שֶּׁעָשׂוּ, עַד שֶׁהִתְפַּזְּרוּ מֵעַל פְּנֵי הָאָרֶץ, וְלֹא נִשְׁאֲרָה בָהֶם חָכְמָה לַעֲשׂוֹת דָּבָר."],[5,"","אֲבָל לֶעָתִיד לָבא הַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר חָכְמָה בָּעוֹלָם וְיַעַבְדוּ אוֹתוֹ בָּהּ. זֶהוּ שֶׁכָּתוּב (יחזקאל לו) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי. לֹא כָּרִאשׁוֹנִים שֶׁהִשְׁחִיתוּ בָהּ אֶת הָעוֹלָם, אֶלָּא - וְעָשִׂיתִי אֵת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וּמִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם."],[6,"","רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר לוֹ רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, נִפְתַּח בַּתּוֹרָה וְנֹאמַר דָּבָר. פָּתַח רַבִּי יוֹסֵי וְאָמַר, (דברים כג) כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ לְהַצִּילְךְ וְלָתֵת אֹיְבֶיךְ לְפָנֶיךְ וְהָיָה מַחֲנֶיךְ קָדוֹשׁ וְלֹא יִרְאֶה בְךְ עֶרְוַת דָּבָר וְשָׁב מֵאַחֲרֶיךְ. כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ? מְהַלֵּךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (בראשית ג) מִתְהַלֵּךְ בַּגָּן לְרוּחַ הַיּוֹם. וְזֶהוּ אִילָן שֶׁאָכַל מִמֶּנּוּ אָדָם הָרִאשׁוֹן. מִתְהַלֵּךְ - נְקֵבָה. מְהַלֵּךְ - זָכָר."],[7,"","וְזְהִוּ שֶׁהָלַךְ לִפְנֵי יִשְׂרָאֵל כְּשֶׁהָיוּ הוֹלְכִים בַּמִּדְבָּר, שֶׁכָּתוּב (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגוֹ'. וְהוּא שֶׁהוֹלֵךְ לִפְנֵי הָאָדָם כְּשֶׁהוֹלֵךְ בַּדֶּרֶךְ, שֶׁכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. וְזֶהוּ שֶׁהוֹלֵךְ לִפְנֵי הָאָדָם בְּשָׁעָה שֶׁהוּא זוֹכֶה. וְלָמָּה? לְהַצִּילְךְ וְלָתֵת אֹיְבֶיךְ לְפָנֶיךְ, לְהַצִּיל אָדָם בַּדֶּרֶךְ וְלֹא יִשְׁלֹט בּוֹ אַחֵר."],[8,"","וְלָכֵן צָרִיךְ אָדָם לְהִשָּׁמֵר מֵחֲטָאָיו וּלְטַהֵר אֶת עַצְמוֹ. מַה טָּהֳרָה זוֹ? שֶׁכָּתוּב (דברים כג) וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. מַה זֶּה קָדוֹשׁ? קְדוֹשִׁים הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא מַחֲנֶיךְ קָדוֹשׁ - אֵלּוּ אֵיבְרֵי הַגּוּף שֶׁהַגּוּף מִתְחַבֵּר וְנִתְקָן בָּהֶם. וְלָכֵן וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. וְלֹא יִרְאֶה בְךְ עֶרְוַת דָּבָר."],[9,"","מַה זֶּה עֶרְוַת דָּבָר? זֶה דְּבַר (ערוה) עֲרָיוֹת, שֶׁזֶּה הוּא דָבָר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בּוֹ יוֹתֵר מֵהַכֹּל. כֵּיוָן שֶׁאָמַר וְלֹא יִרְאֶה בְךְ עֶרְוַת, לָמָּה דָּבָר? אֶלָּא רִשְׁעֵי הָעוֹלָם הַלָּלוּ שֶׁגּוֹעֲלִים וּמְטַמְּאִים אֶת עַצְמָם בְּדִבּוּרָם שֶׁיּוֹצֵא מִפִּיהֶם, וְזֶהוּ עֶרְוַת דָּבָר."],[10,"","וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁהוּא הוֹלֵךְ לְפָנֶיךְ. וְאִם אַתָּה עוֹשֶׂה כָּךְ, מִיָּד - וְשָׁב מֵאַחֲרֶיךְ. שֶׁלֹּא יֵלֵךְ עִמְּךְ וְיָשׁוּב מֵאַחֲרֶיךְ. וְאָנוּ הֲרֵינוּ הוֹלְכִים לְפָנָיו בַּדֶּרֶךְ, נִתְעַסֵּק בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי הַתּוֹרָה מִתְעַטֶּרֶת עַל רֹאשׁוֹ שֶׁל אָדָם וְהַשְּׁכִינָה לֹא זָזָה מִמֶּנּוּ."],[11,"","פָּתַח רַבִּי חִיָּיא וְאָמַר, וַיֹּאמֶר ה' הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם וְגוֹ' בֹּא רְאֵה מַה כָּתוּב, וַיְהִי בְּנָסְעָם מִקֶּדֶם. מַה זֶּה מִקֶּדֶם? מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. וַיִּמְצְאוּ? וַיִּרְאוּ צָרִיךְ הָיָה לִהְיוֹת! מַה זֶּה וַיִּמְצְאוּ? אֶלָּא מְצִיאָה מָצְאוּ שָׁם מִסּוֹדֵי הַחָכְמָה מֵהַקַּדְמוֹנִים שֶׁהִתְנַעֲרָה שָׁם מִבְּנֵי הַמַּבּוּל, וּבָהּ הִתְעַסְּקוּ לַעֲשׂוֹת בְּאוֹתוֹ מַעֲשֶׂה שֶׁעָשׂוּ לְסָרֵב לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהָיוּ אוֹמְרִים בַּפֶּה וְעוֹשִׂים מַעֲשֶׂה."]]],[["חָמֵי מַה כְּתִיב הֶן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. בְּגִין דְּאִנּוּן בְּלִבָּא חַד וּרְעוּתָא חַד וּמְמַלְּלֵי בִּלְשׁוֹן הַקֹּדֶשׁ. וְעַתָּה לא יִבָּצֵר מֵהֶם כָּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת. וְלֵית מַאן דְּיִמְנַע עוֹבָדָא דִלְהוֹן. אֲבָל מַאי אַעֲבִיד, אֲבַלְבֵּל לוֹן דַּרְגִּין דִלְעֵילָא, וְלִישַׁן דִּלְהוֹן לְתַתָּא. וּכְדֵין אִתְמְנַע עוֹבָדָא דִלְהוֹן.","וּמַה בְּגִין דְּהֲווּ בִּרְעוּתָא וְלִבָּא חַד וּמְמַלְּלֵי בִּלְשׁוֹן הַקֹּדֶשׁ כְּתִיב לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, וְדִינָא דִלְעֵילָא לָא יָכִיל לְשַׁלְטָאָה בְּהוּ. אֲנַן אוֹ חַבְרַיָיא דְּמִתְעַסְּקִין בְּאוֹרַיְיתָא, וְאֲנַן בְּלִבָּא חַד וּרְעוּתָא חַד, עַל אַחַת כַּמָּה וְכַמָּה.","אָמַר רַבִּי יוֹסֵי מִכָּאן לְאִנּוּן מָארֵי דְמַחְלוֹקֶת לֵית לוֹן קִיּוּמָא. דְּהָא כָּל זִמְנָא (דאלין) דִּבְנֵי עָלְמָא אִלֵּין עִם אִלֵּין בִּרְעוּתָא חָדָא וְלִבָּא חָד, אַף עַל גַּב דְּמָרְדֵּי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, לָא שָׁלְטָא בְּהוּ דִינָא דִּלְעֵילָא. כֵּיוָן דְּאִתְפַּלְּגוּ מִיָּד וַיָּפֶץ יְיָ אוֹתָם מִשָּׁם וְגו'.","אָמַר רַבִּי חִיָּיא אִשְׁתְּמַע דְּכֹלָּא בְּמִלָּה דְפוּמָא תַּלְיָיא. דְּהָא כֵּיוָן דְּאִתְבַּלְבֵּל מִיָּד וַיָּפֶץ יְיָ אֹתָם מִשָּׁם. אֲבָל בְּזִמְנָא דְאָתֵי מַה כְּתִיב, (צפניה ג׳:ט׳) כִּי אָז אֶהֱפֹךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻּלָּם בְּשֵׁם יְיָ וּלְעָבְדוֹ שְׁכֶם אֶחָד וּכְתִיב, (זכריה י״ד:ט׳) וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן:"],[[0,"חמי מה כתיב וכו':","ראה מה שכתוב הן עם אחד ושפה אחת לכולם, ומשום שהם בלב אחד ורצון אחד, ומדברים בלשון הקדש, ע\"כ ועתה לא יבצר מהם כל אשר יזמו לעשות. ואין מי שיוכל למנוע את מעשיהם. אבל אמר הקב\"ה, מה אעשה, אני אבלבל את המדרגות של מעלה ואת הלשון שלהם למטה ואז תמנע העבודה שלהם."],[1,"ומה בגין דהוו וכו':","ומה, משום שהיו ברצון ולב אחד, ודברו בלשון הקודש כתוב, לא יבצר מהם אשר יזמו לעשות, ודין העליון לא יכול לשלוט עליהם, אנו או החברים שעוסקים בתורה, ואנו בלב אחד ורצון אחד על אחת כמה וכמה שלא יבצר ממנו, מה שנרצה לעשות."],[2,"א\"ר יוסי וכו':","אר\"י מכאן נשמע, שכל אלו בעלי המחלוקת אין להם קיום. שהרי כל זמן שבני העולם הם אלו עם אלו ברצון אחד ולב אחד אע\"פ שמורדים בהקב\"ה, לא שלט בהם דין העליון, כמו שאירע בדור הפלגה וכיון שנחלקו, מיד כתוב עליהם ויפץ ה' אותם משם וגו'. הרי שלבעלי מחלוקת אין להם קיום."],[3,"א\"ר חייא וכו':","אר\"ח, משמע שהכל תלוי בדברי הפה, כי כיון שנתבלבל שפתם, מיד ויפץ ה' אותם משם וכו'. אבל לעתיד לבא, מה כתוב, כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד. וכתוב והיה ה' למלך על כל הארץ וגו'."]],[[0,"","רְאֵה מַה כָּתוּב, הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. מִשּׁוּם שֶׁהֵם בְּלֵב אֶחָד וּבְרָצוֹן אֶחָד וּמְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ. וְעַתָּה לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, וְאֵין מִי שֶׁיִּמְנַע מַעֲשֵׂיהֶם. אֲבָל מָה אֶעֱשֶׂה? אֲבַלְבֵּל לָהֶם הַדְּרָגוֹת שֶׁל מַעְלָה וּלְשׁוֹנָם שֶׁלְּמַטָּה, וְאָז נִמְנַע מַעֲשֶׂה שֶׁלָּהֶם."],[1,"","וּמַה מִשּׁוּם שֶׁהָיוּ בְּרָצוֹן וְלֵב אֶחָד וּמְדַבְּרִים בִּלְשׁוֹן הַקֹּדֶשׁ כָּתוּב לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, וְדִין שֶׁלְּמַעְלָה לֹא יָכֹל לִשְׁלֹט בָּהֶם - אָנוּ אוֹ הַחֲבֵרִים שֶׁמִּתְעַסְּקִים בַּתּוֹרָה, וְאָנוּ בְּלֵב אֶחָד וְרָצוֹן אֶחָד, עַל אַחַת כַּמָּה וְכַמָּה."],[2,"","אָמַר רַבִּי יוֹסֵי, מִכָּאן שֶׁלְּאוֹתָם בַּעֲלֵי הַמַּחֲלֹקֶת אֵין לָהֶם קִיּוּם. שֶׁהֲרֵי בְּכָל פַּעַם שֶׁהַלָּלוּ בְּנֵי הָעוֹלָם אֵלֶּה עִם אֵלֶּה בְּרָצוֹן אֶחָד וְלֵב אֶחָד - אַף עַל גַּב שֶׁמּוֹרְדִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, לֹא שׁוֹלֵט בָּהֶם הַדִּין שֶׁלְּמַעְלָה. כֵּיוָן שֶׁנֶּחְלְקוּ, מִיָּד - וַיָּפֶץ אֹתָם ה' מִשָּׁם וְגוֹ'."],[3,"","אָמַר רַבִּי חִיָּיא, נִשְׁמָע שֶׁהַכֹּל בְּדִבּוּר הַפֶּה תָּלוּי, שֶׁהֲרֵי כֵּיוָן שֶׁהִתְבַּלְבְּלוּ, מִיָּד וַיָּפֶץ ה' אֹתָם מִשָּׁם. אֲבָל לֶעָתִיד לָבֹא מַה כָּתוּב? (צפניה ג) כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם ה' לְעָבְדוֹ שְׁכֶם אֶחָד, וְכָתוּב (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן:"]]]]};
